  void _persistScannerHistory(
    String mode,
    Map<String, String> data,
    NazaScannerResult result,
  ) {
    if (!widget.initializeServices) return;
    unawaited(
      NazaVault.instance
          .appendScannerResult(
            mode: mode,
            input: Map<String, String>.from(data),
            result: result,
          )
          .catchError((Object _) {}),
    );
  }

  Future<NazaScannerResult> _submitScannerPrompt({
    required String title,
    required String kind,
    required String visibleSummary,
    required String riskPrompt,
    required String safetyPrompt,
    required NazaScannerTrace trace,
    required String riskStatus,
    required String safetyStatus,
    required String scannerModel,
    required Map<String, String> scannerData,
  }) async {
    if (_sending) {
      return NazaScannerResult.failed(
        title: title,
        kind: kind,
        visibleSummary: visibleSummary,
        error: 'Another local generation is already running.',
        trace: trace,
      );
    }

    setState(() {
      _sending = true;
      _stopping = false;
      _status = '$riskStatus + score';
    });

    await WidgetsBinding.instance.endOfFrame;

    try {
      final useLlama = scannerModel == 'llama3-small';
      NazaScannerSentinelDecision? sentinel;
      if (useLlama) {
        if (mounted) {
          setState(() => _status = 'Llama 3 Small scanner classification');
        }
        sentinel = await NazaSentinelGuard.instance.classifyScanner(
          domain: kind.toLowerCase().contains('road')
              ? 'road-scanner'
              : 'food-water-scanner',
          // Keep the small 2,048-token GGUF classifier aligned with the
          // reference implementation: send the compact public observation
          // summary, not the full explanatory Gemma prompt.
          evidence: kind.toLowerCase().contains('road')
              ? NazaScannerPrompts.buildReferenceRoadLlama(scannerData, trace)
              : NazaScannerPrompts.buildReferenceFoodLlama(scannerData, trace),
          lState: <String>[
            trace.chromaticRibbon,
            trace.rgbTiming,
            trace.nonlocalRibbon,
            trace.entropy,
            trace.integrity,
            trace.multiNode,
            trace.defenseCapsule,
            trace.colorwheel,
            'checksum=${trace.checksum}',
          ].join('\n'),
          defensePasses: trace.defensePasses.clamp(1, 5),
        );
      } else if (scannerModel != 'gemma4-e2b-litert') {
        throw const FormatException('Unsupported scanner model selection.');
      }
      final scannerPrompt = NazaScannerPrompts.buildSinglePassScanner(
        kind: kind,
        visibleSummary: visibleSummary,
        primaryPrompt: riskPrompt,
        safetyPrompt: safetyPrompt,
      );
      final scannerResponse = sentinel != null
          ? _localLlamaScannerResponse(
              decision: sentinel,
              kind: kind,
              visibleSummary: visibleSummary,
            )
          : await NazaLocalGemma.instance.send(
              scannerPrompt,
              historyUserText: visibleSummary,
              useMemory: false,
              persistTurn: false,
              maxContinuationsOverride: 0,
              origin: NazaGenerationOrigin.scanner,
              scannerMode: true,
              routeOverride:
                  'scanner-${kind.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '-')}',
            );
      final calibratedResponse = sentinel == null
          ? NazaResponse(
              text: scannerResponse.text,
              score: scannerResponse.score,
              route: '${scannerResponse.route}+gemma4-scanner',
              cancelled: scannerResponse.cancelled,
              createdAt: scannerResponse.createdAt,
            )
          : sentinel.valid
          ? _applyScannerSentinel(scannerResponse, sentinel)
          : NazaResponse(
              text:
                  '''Classifier output was not a valid Low, Medium, or High label.
Raw CHUNKD output is shown below.''',
              score: 0,
              route: 'local-llama3-small-invalid-output',
              cancelled: false,
              createdAt: DateTime.now(),
            );

      if (mounted) {
        setState(() => _status = safetyStatus);
      }

      await WidgetsBinding.instance.endOfFrame;

      return NazaScannerResult.fromResponses(
        title: title,
        kind: kind,
        visibleSummary: visibleSummary,
        riskResponse: calibratedResponse,
        safetyResponse: calibratedResponse,
        trace: trace,
        rawModelOutput: sentinel?.rawOutput ?? scannerResponse.text,
      );
    } catch (error) {
      return NazaScannerResult.failed(
        title: title,
        kind: kind,
        visibleSummary: visibleSummary,
        error: error,
        trace: trace,
      );
    } finally {
      if (mounted) {
        setState(() {
          _sending = false;
          _stopping = false;
          _status = _labelForPanel(_panel);
        });
      }
    }
  }

  NazaResponse _applyScannerSentinel(
    NazaResponse response,
    NazaScannerSentinelDecision sentinel,
  ) {
    return NazaResponse(
      text: NazaScannerSentinelPolicy.calibrateStructuredText(
        response.text,
        sentinel,
      ),
      score: response.score,
      route: '${response.route}+sentinel-${sentinel.risk.name}',
      cancelled: response.cancelled,
      createdAt: response.createdAt,
    );
  }

  NazaResponse _localLlamaScannerResponse({
    required NazaScannerSentinelDecision decision,
    required String kind,
    required String visibleSummary,
  }) {
    final risk = decision.risk;
    final matchingVotes = decision.votes.where((vote) => vote == risk).length;
    final agreement = decision.votes.isEmpty
        ? 0.0
        : matchingVotes / decision.votes.length;
    final confidence = agreement >= 0.999
        ? 'High'
        : agreement >= 0.60
        ? 'Medium'
        : 'Low';
    final score = switch (risk) {
      NazaHarmRisk.low => 85,
      NazaHarmRisk.medium => 60,
      NazaHarmRisk.high => 30,
      NazaHarmRisk.indeterminate => 50,
    };
    final safetyBand = switch (risk) {
      NazaHarmRisk.low => 'High',
      NazaHarmRisk.medium => 'Medium',
      NazaHarmRisk.high => 'Low',
      NazaHarmRisk.indeterminate => 'Medium',
    };
    final domain = kind.toLowerCase().contains('road')
        ? 'road conditions'
        : 'food or water conditions';
    final summary = NazaPromptData.inline(visibleSummary, maxChars: 220);
    final text =
        '''Risk: ${risk.label}
Confidence: $confidence
Primary cues:
- Local Llama Small classification of the supplied $domain.
- Supplied observation summary: $summary
Recommended action:
- Verify the relevant conditions directly on-site.
- Use the conservative ${risk.label.toLowerCase()}-risk precautions until verified.
Safety Score: $score
Safety Band: $safetyBand
Score drivers:
- Result from one bounded local CHUNKD session; voting is disabled.
- Score is the fixed conservative midpoint for the selected risk band.
Immediate verification:
- Confirm current observable conditions before acting.
- Re-run after adding specific visibility, surface, storage, or hazard details.''';
    return NazaResponse(
      text: text,
      score: agreement,
      route: 'local-llama3-small-${risk.name}',
      cancelled: false,
      createdAt: DateTime.now(),
    );
  }

  void _stopActiveGeneration() {
    if (!_sending || _stopping) return;
    final accepted =
        widget.chatPromptCanceller?.call() ??
        NazaLocalGemma.instance.cancelActiveGeneration(
          reason: 'user pressed Stop',
        );
    if (!accepted) return;
    setState(() {
      _stopping = true;
      _status = 'stopping • keeping generated text';
    });
  }

  Future<void> _continueWhereLeftOff() async {
    final original = _continuationOriginalPrompt?.trim() ?? '';
    final turnId = _continuationTurnId;
    final assistantId = _continuationAssistantMessageId;
    final prefix = _continuationText.trimRight();
    if (_sending ||
        original.isEmpty ||
        turnId == null ||
        assistantId == null ||
        prefix.isEmpty) {
      return;
    }

    final continuingMessage = NazaUiMessage.assistant(
      prefix,
      id: assistantId,
      route: 'manual-continuation',
      score: 1,
      isWorking: true,
    );
    _activeStreamingMessage.value = continuingMessage;
    setState(() {
      _sending = true;
      _stopping = false;
      _status = 'continuing from saved seam';
      final index = _messages.indexWhere((item) => item.id == assistantId);
      if (index >= 0) {
        _messages[index] = continuingMessage;
      }
    });
    _scrollToBottom(force: true);
    await WidgetsBinding.instance.endOfFrame;
    if (!mounted) return;

    var lastPartialText = '';
    void paint(String partial) {
      if (!mounted) return;
      final cleaned = partial.trim();
      if (cleaned.isEmpty || cleaned == lastPartialText) return;
      lastPartialText = cleaned;
      _activeStreamingMessage.value = NazaUiMessage.assistant(
        cleaned,
        id: assistantId,
        route: 'manual-continuation',
        score: 1,
        isWorking: true,
      );
      _scrollToBottom();
    }

    final response = await NazaLocalGemma.instance.continueOnce(
      originalUserText: original,
      accumulatedReply: prefix,
      historyThreadId: _activeThreadId,
      historyTurnId: turnId,
      onPartial: paint,
    );
    if (!mounted) return;

    final finalText = response.text.trim().isEmpty ? prefix : response.text;
    final finalMessage = NazaUiMessage.assistant(
      finalText,
      id: assistantId,
      route: response.route,
      score: response.score,
    );
    _activeStreamingMessage.value = finalMessage;
    setState(() {
      _sending = false;
      _stopping = false;
      _status = response.cancelled
          ? 'continuation stopped'
          : response.route == 'manual-continuation-restart-required'
          ? 'continuation needs an app restart'
          : response.route == 'manual-continuation-busy'
          ? 'another local response is still active'
          : 'ready';
      final index = _messages.indexWhere((item) => item.id == assistantId);
      if (index >= 0) {
        _messages[index] = finalMessage;
      }
      final rowIndex = _threadRows.indexWhere((item) => item.id == turnId);
      if (rowIndex >= 0) {
        final prior = _threadRows[rowIndex];
        _threadRows[rowIndex] = NazaHistoryRow(
          id: prior.id,
          threadId: prior.threadId,
          timestamp: prior.timestamp,
          user: prior.user,
          assistant: finalText,
          route: response.route,
          score: response.score,
        );
      }
      _continuationText = finalText;
    });
    _scrollToBottom();
  }

  void _newThread() {
    if (_sending) return;
    _activeStreamingMessage.value = null;
    setState(() {
      _activeThreadId = NazaHistoryRow._id();
      _threadRows.clear();
      _continuationOriginalPrompt = null;
      _continuationTurnId = null;
      _continuationAssistantMessageId = null;
      _continuationText = '';
      _messages.clear();
      _panel = NazaPanel.chat;
      _status = 'ready';
    });
    _scrollToBottom(force: true);
    _inputFocus.requestFocus();
  }

  void _openThread(NazaConversationThread thread) {
    if (_sending) return;
    _activeStreamingMessage.value = null;
    if (_panel == NazaPanel.history) {
      _panelCache.remove(NazaPanel.history);
    }
    final turns = thread.turns.toList(growable: false);
    setState(() {
      _activeThreadId = thread.id;
      _threadRows
        ..clear()
        ..addAll(turns);
      _messages.clear();
      for (final row in turns) {
        _messages
          ..add(NazaUiMessage.user(row.user, id: 'user-${row.id}'))
          ..add(
            NazaUiMessage.assistant(
              row.assistant,
              id: 'assistant-${row.id}',
              route: row.route,
              score: row.score,
            ),
          );
      }
      final last = turns.isEmpty ? null : turns.last;
      _continuationOriginalPrompt = last?.user;
      _continuationTurnId = last?.id;
      _continuationAssistantMessageId = last == null
          ? null
          : 'assistant-${last.id}';
      _continuationText = last?.assistant ?? '';
      _panel = NazaPanel.chat;
      _status = 'thread reopened • ${turns.length} turns';
    });
    _scrollToBottom(force: true);
  }

  void _openScannerHistory(NazaScannerHistoryRow row) {
    if (_sending) return;
    if (_panel == NazaPanel.history) {
      _panelCache.remove(NazaPanel.history);
    }
    _panelCache.remove(
      row.mode == 'road' ? NazaPanel.roadScanner : NazaPanel.foodWater,
    );
    setState(() {
      switch (row.mode) {
        case 'food':
          _foodDraft = Map<String, String>.from(row.input);
          _foodResult = row.result;
          _panel = NazaPanel.foodWater;
          _status = 'reopened food / water scan';
          break;
        case 'foodPlanner':
          _foodPlannerDraft = {
            'max_targets': '6',
            ...Map<String, String>.from(row.input),
          };
          _foodPlannerResult = row.result;
          _panel = NazaPanel.foodWater;
          _status = 'reopened multi-scan plan';
          break;
        default:
          _roadDraft = Map<String, String>.from(row.input);
          _roadResult = row.result;
          _panel = NazaPanel.roadScanner;
          _status = 'reopened road scan';
      }
    });
    _scheduleScannerDraftSave();
  }

  Future<void> _resetChat() async {
    if (_sending) return;
    setState(() => _status = 'resetting chat context');
    try {
      await NazaLocalGemma.instance.resetChat();
    } catch (error) {
      if (!mounted) return;
      setState(() => _status = 'reset failed: $error');
      return;
    }
    if (!mounted) return;
    setState(() {
      _status = 'chat context reset';
      _messages
        ..clear()
        ..add(
          NazaUiMessage.assistant(
            'Local chat context reset.',
            route: 'settings',
            score: 1,
          ),
        );
    });
    _scrollToBottom(force: true);
  }

  Future<void> _clearHistory() async {
    if (_sending) return;
    setState(() => _status = 'clearing history');
    try {
      await NazaVault.instance.clearHistory();
      await NazaVectorMemory.instance.clear();
      await NazaHistoryMetadataRepository().clear();
    } catch (error) {
      if (!mounted) return;
      setState(() => _status = 'clear failed: $error');
      return;
    }
    if (!mounted) return;
    _panelCache.remove(NazaPanel.history);
    setState(() {
      _status = 'history cleared';
    });
  }

  void _setPanel(NazaPanel panel) {
    if (_panel == NazaPanel.history && panel != NazaPanel.history) {
      // History owns vault listeners and performs encrypted reads. Dispose it
      // when hidden so every generated turn does not rebuild an offstage list.
      _panelCache.remove(NazaPanel.history);
    }
    setState(() {
      _panel = panel;
      _status = _labelForPanel(panel);
    });
  }

  void _openHealthPage(NazaHealthPage page) {
    setState(() {
      _healthPage = page;
      _panel = NazaPanel.health;
      _status = _labelForPanel(NazaPanel.health);
    });
  }

  void _openExplorationSection(NazaExplorationSection section) {
    setState(() {
      _exploreSection = section;
      _panel = NazaPanel.labs;
      _status = section.label;
    });
  }

  void _openFoodWorkspace(String workspace) {
    setState(() {
      _foodWorkspace = workspace;
      _panel = NazaPanel.foodWater;
      _status = 'food $workspace';
      _panelCache.remove(NazaPanel.foodWater);
    });
  }

  void _openBookWorkspace(int workspace) {
    setState(() {
      _bookWorkspace = workspace.clamp(0, 2);
      _panel = NazaPanel.book;
      _status = 'bookforge';
      _panelCache.remove(NazaPanel.book);
    });
  }

  void _openGames([String? game]) {
    setState(() {
      _gameWorkspace = game;
      _panel = NazaPanel.games;
      _status = game ?? 'games';
      _panelCache.remove(NazaPanel.games);
    });
