  Future<String> _runHealthVision({
    required Uint8List imageBytes,
    required String systemInstruction,
    required String prompt,
  }) async {
    final response = await NazaLocalGemma.instance.send(
      prompt,
      historyUserText: 'Private personal health vision workflow',
      visionImage: NazaVisionImage(
        bytes: imageBytes,
        name: 'personal-health-image.jpg',
        width: 1,
        height: 1,
      ),
      useMemory: false,
      persistTurn: false,
      maxContinuationsOverride: 0,
      routeOverride: 'health-agent-vision',
      systemInstructionOverride: systemInstruction,
    );
    return response.text;
  }

  void _openHealthChatWithPrompt(String prompt) {
    _setPanel(NazaPanel.chat);
    _inputController
      ..text = prompt
      ..selection = TextSelection.collapsed(offset: prompt.length);
    _inputFocus.requestFocus();
  }

  void _scrollToBottom({bool force = false}) {
    if (!force && !_followOutput) return;
    if (force) _followOutput = true;
    final now = DateTime.now();
    if (!force &&
        now.difference(_lastScrollRequestAt) <
            const Duration(milliseconds: 240)) {
      return;
    }
    _lastScrollRequestAt = now;

    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_scrollController.hasClients) return;
      if (!force && !_followOutput) return;
      _scrollController.jumpTo(_scrollController.position.maxScrollExtent);
    });
  }

  @override
  Widget build(BuildContext context) {
    final wide = MediaQuery.sizeOf(context).width >= 760;

    return _NazaThemeSurface(
      child: Scaffold(
        resizeToAvoidBottomInset: true,
        backgroundColor: NazaPalette.inkDeep,
        body: Stack(
          children: [
            const _NazaStaticBackdrop(),
            SafeArea(
              child: Row(
                children: [
                  if (wide) _buildDesktopFeatureRail(),
                  Expanded(
                    child: Column(
                      children: [
                        _TopBar(
                          panel: _panel,
                          status: _status,
                          wide: wide,
                          sending: _sending,
                          stopping: _stopping,
                          onStop: _stopActiveGeneration,
                          onNewThread: _newThread,
                          onPanel: _setPanel,
                        ),
                        Expanded(
                          child: Row(
                            children: [Expanded(child: _buildPanelStack())],
                          ),
                        ),
                        if (_panel == NazaPanel.chat)
                          _ComposerBar(
                            controller: _inputController,
                            focusNode: _inputFocus,
                            sending: _sending,
                            pickingImage: _pickingImage,
                            selectedImage: _pendingVisionImage,
                            canContinue:
                                _continuationText.trim().isNotEmpty &&
                                _continuationTurnId != null,
                            onPickImage: _pickVisionImage,
                            onRemoveImage: _removeVisionImage,
                            onSend: _send,
                            onStop: _stopActiveGeneration,
                            onContinue: _continueWhereLeftOff,
                          ),
                        if (!wide) _buildFeatureDrawer(),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildFeatureDrawer() {
    final destinations = _destinations;
    return NazaUnifiedFeatureDrawer(
      destinations: destinations,
      selectedId: _selectedFeatureId,
      surface: NazaPalette.shell,
      panel: NazaPalette.panel,
      border: NazaPalette.border,
      text: NazaPalette.text,
      subtext: NazaPalette.subtext,
    );
  }

  Widget _buildDesktopFeatureRail() => NazaUnifiedFeatureRail(
    destinations: _destinations,
    selectedId: _selectedFeatureId,
    surface: NazaPalette.shell,
    panel: NazaPalette.panel,
    border: NazaPalette.border,
    text: NazaPalette.text,
    subtext: NazaPalette.subtext,
  );

