            },
            icon: spec.$6,
            accent: accent,
            onOpen: () => _openHealthPage(spec.$7),
          ),
        )
        .toList(growable: false);
  }

  String get _selectedFeatureId {
    if (_panel == NazaPanel.health) {
      return switch (_healthPage) {
        NazaHealthPage.today => 'health',
        NazaHealthPage.walking => 'walking',
        NazaHealthPage.schedule => 'health-schedule',
        NazaHealthPage.medications => 'health-medications',
        NazaHealthPage.dental => 'health-dental',
        NazaHealthPage.exercise => 'health-exercise',
        NazaHealthPage.recovery => 'health-recovery',
        NazaHealthPage.meals => 'health-meals',
        NazaHealthPage.mealPlan => 'health-meal-plan',
        NazaHealthPage.weight => 'health-weight',
        NazaHealthPage.groceries => 'health-groceries',
        NazaHealthPage.intelligence => 'health-intelligence',
        NazaHealthPage.workflow => 'health-workflow',
        NazaHealthPage.command => 'health-command',
        NazaHealthPage.foodShare => 'health-food-share',
      };
    }
    if (_panel == NazaPanel.labs) {
      return switch (_exploreSection) {
        NazaExplorationSection.findIt => 'findit',
        NazaExplorationSection.garden => 'garden',
        NazaExplorationSection.drive => 'drive',
        NazaExplorationSection.predict => 'predict',
        NazaExplorationSection.heartFlow => 'heart-flow',
      };
    }
    return switch (_panel) {
      NazaPanel.chat => 'chat',
      NazaPanel.games =>
        _gameWorkspace == 'revrecall' ? 'memory-game' : 'games',
      NazaPanel.chess => 'chess',
      NazaPanel.roadScanner => 'road-scanner',
      NazaPanel.foodWater => switch (_foodWorkspace) {
        'recipes' => 'food-recipes',
        'shelf' => 'food-shelf',
        'bake' => 'food-bake',
        'safety' => 'food-safety',
        _ => 'food-scanner',
      },
      NazaPanel.book => switch (_bookWorkspace) {
        1 => 'bookforge-generate',
        2 => 'bookforge-repository',
        _ => 'bookforge',
      },
      NazaPanel.labs => 'findit',
      NazaPanel.history => 'history',
      NazaPanel.settings => 'settings',
      NazaPanel.health => 'health',
      NazaPanel.intelligence => switch (_intelligenceWorkspace) {
        NazaIntelligenceWorkspace.knowledge => 'knowledge-vault',
        NazaIntelligenceWorkspace.observatory => 'memory-observatory',
        NazaIntelligenceWorkspace.projects => 'projects',
        NazaIntelligenceWorkspace.workflows => 'workflow-builder',
      },
      NazaPanel.agenticCoding => 'agentic-coding',
      NazaPanel.dataPipes => 'data-pipes',
    };
  }

  Widget _buildMainPanel([NazaPanel? panelOverride]) {
    final panel = panelOverride ?? _panel;
    switch (panel) {
      case NazaPanel.chat:
        return ListView.builder(
          key: const ValueKey<String>('chat-message-list'),
          controller: _scrollController,
          keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
          padding: const EdgeInsets.fromLTRB(16, 12, 16, 12),
          addRepaintBoundaries: true,
          itemCount: _messages.length + 1,
          itemBuilder: (context, index) {
            if (index == 0) {
              return ValueListenableBuilder<NazaModelStoreStatus>(
                valueListenable: NazaSecureModelStore.status,
                builder: (context, modelStatus, _) {
                  final showModelCard =
                      !modelStatus.installed ||
                      modelStatus.busy ||
                      modelStatus.error != null;
                  return showModelCard
                      ? const _ModelFirstBootCard()
                      : const SizedBox.shrink();
                },
              );
            }
            final message = _messages[index - 1];
            if (!message.isWorking) {
              return _StableMessageBubble(
                key: ValueKey<String>(message.id),
                message: message,
              );
            }
            return ValueListenableBuilder<NazaUiMessage?>(
              key: ValueKey<String>('stream-${message.id}'),
              valueListenable: _activeStreamingMessage,
              builder: (context, activeMessage, _) {
                final visibleMessage = activeMessage?.id == message.id
                    ? activeMessage!
                    : message;
                return _StableMessageBubble(
                  key: ValueKey<String>(visibleMessage.id),
                  message: visibleMessage,
                );
              },
            );
          },
        );
      case NazaPanel.chess:
        return NazaChessTab(runAgent: _runChessAgent);
      case NazaPanel.games:
        return NazaGamesTab(initialGame: _gameWorkspace);
      case NazaPanel.roadScanner:
        return _RoadScannerPanel(
          actionsEnabled: !_sending,
          initialData: _roadDraft,
          initialResult: _roadResult,
          onDraftChanged: _updateRoadDraft,
          onResultChanged: (result) => _roadResult = result,
          onScan: _runRoadScan,
        );
      case NazaPanel.foodWater:
        return FoodVisionHub(
          key: ValueKey<String>('food-workspace-$_foodWorkspace'),
          repository: _foodRepository,
          photoPicker: _foodPhotoPicker,
          analyzeFridgeImage: _analyzeFridgeImage,
          analyzeBakeImage: _analyzeBakeImage,
          regenerateRecipes: _regenerateFoodRecipes,
          onCancel: _stopActiveGeneration,
          draftController: _foodVisionDraft,
          initialWorkspace: _foodWorkspace,
          foodSafetyChild: _FoodWaterScannerPanel(
            embedded: true,
            actionsEnabled: !_sending,
            initialScanData: _foodDraft,
            initialPlannerData: _foodPlannerDraft,
            initialSingleResult: _foodResult,
            initialPlannerResult: _foodPlannerResult,
            onScanDraftChanged: _updateFoodDraft,
            onPlannerDraftChanged: _updateFoodPlannerDraft,
            onSingleResultChanged: (result) => _foodResult = result,
            onPlannerResultChanged: (result) => _foodPlannerResult = result,
            onScan: _runFoodWaterScan,
            onPlanner: _runFoodWaterPlanner,
          ),
        );
      case NazaPanel.health:
        return NazaHealthDashMonolith(
          initialPage: _healthPage,
          agent: NazaHealthAgentBridge(
            runText: _runHealthText,
            runVision: _runHealthVision,
            pickImage: _pickHealthImage,
          ),
          existing: NazaExistingSurfaceBridge(
            openChat: () => _setPanel(NazaPanel.chat),
            openChatWithPrompt: _openHealthChatWithPrompt,
            openRoadScanner: () => _setPanel(NazaPanel.roadScanner),
            openFoodVision: () => _setPanel(NazaPanel.foodWater),
            openHistory: () => _setPanel(NazaPanel.history),
            openSettings: () => _setPanel(NazaPanel.settings),
          ),
          vault: NazaHealthVault(database: NazaSecureDatabase.instance),
        );
      case NazaPanel.book:
        return BookForgeApp(
          completion: _runBookText,
          initialPage: _bookWorkspace,
        );
      case NazaPanel.labs:
        return NazaExplorationHub(
          runPrompt: _runExplorePrompt,
          pickGardenImage: _pickGardenImage,
          initialSection: _exploreSection,
        );
      case NazaPanel.settings:
        return _SettingsPanel(
          actionsEnabled: !_sending,
          onResetChat: _resetChat,
          onClearHistory: _clearHistory,
        );
      case NazaPanel.history:
        return _HistoryPanel(
          onOpenThread: _openThread,
          onOpenScanner: _openScannerHistory,
        );
      case NazaPanel.intelligence:
        return NazaIntelligenceHub(
          initialWorkspace: _intelligenceWorkspace,
          inspectMemory: () async {
            final chunks = await NazaVectorMemory.instance.inspectChunks();
            return chunks
                .map(
                  (chunk) => NazaObservedMemory(
                    id: chunk.id,
                    text: chunk.text,
                    role: chunk.role,
                    route: chunk.route,
                    importance: chunk.importance,
                    accessCount: chunk.accessCount,
                    createdAt: chunk.createdAt,
                  ),
                )
                .toList(growable: false);
          },
          forgetMemory: NazaVectorMemory.instance.forgetChunk,
          indexKnowledge:
              ({
                required String projectId,
                required String documentName,
                required String text,
              }) => NazaVectorMemory.instance.rememberMessagePair(
                user:
                    'Imported Knowledge Vault document $documentName in project $projectId.',
                assistant: text.length > 12000
                    ? text.substring(0, 12000)
                    : text,
                route: 'knowledge-vault/$projectId',
                score: 0.86,
                turnId: 'knowledge-$projectId-${documentName.hashCode}',
              ),
        );
      case NazaPanel.agenticCoding:
        return NazaAgenticCodingSurface(
          runTask: _runAgenticTask,
          pickImage: _pickAgenticImage,
        );
      case NazaPanel.dataPipes:
        return const NazaDataPipesSurface();
    }
  }

  Widget _buildPanelStack() {
    final activeIndex = _panelIndex(_panel);
    final children = <Widget>[
      _tickerPanel(NazaPanel.chat, _panelForStack(NazaPanel.chat)),
      _tickerPanel(NazaPanel.games, _panelForStack(NazaPanel.games)),
      _tickerPanel(NazaPanel.chess, _panelForStack(NazaPanel.chess)),
      _tickerPanel(
        NazaPanel.roadScanner,
        _panelForStack(NazaPanel.roadScanner),
      ),
      _tickerPanel(NazaPanel.foodWater, _panelForStack(NazaPanel.foodWater)),
      _tickerPanel(NazaPanel.health, _panelForStack(NazaPanel.health)),
      _tickerPanel(NazaPanel.book, _panelForStack(NazaPanel.book)),
      _tickerPanel(NazaPanel.labs, _panelForStack(NazaPanel.labs)),
      _tickerPanel(NazaPanel.settings, _panelForStack(NazaPanel.settings)),
      _tickerPanel(NazaPanel.history, _panelForStack(NazaPanel.history)),
      _tickerPanel(
        NazaPanel.intelligence,
        _panelForStack(NazaPanel.intelligence),
      ),
      _tickerPanel(
        NazaPanel.agenticCoding,
        _panelForStack(NazaPanel.agenticCoding),
      ),
      _tickerPanel(NazaPanel.dataPipes, _panelForStack(NazaPanel.dataPipes)),
    ];
    return IndexedStack(index: activeIndex, children: children);
  }

  Widget _tickerPanel(NazaPanel panel, Widget child) {
    return TickerMode(enabled: _panel == panel, child: child);
  }

  Widget _panelForStack(NazaPanel panel) {
    if (_panel == panel) {
      final child = _buildMainPanel(panel);
      _panelCache[panel] = child;
      return child;
    }
    return _panelCache[panel] ?? const SizedBox.shrink();
  }

  int _panelIndex(NazaPanel panel) {
    return switch (panel) {
      NazaPanel.chat => 0,
      NazaPanel.games => 1,
      NazaPanel.chess => 2,
      NazaPanel.roadScanner => 3,
      NazaPanel.foodWater => 4,
      NazaPanel.health => 5,
      NazaPanel.book => 6,
      NazaPanel.labs => 7,
      NazaPanel.settings => 8,
      NazaPanel.history => 9,
      NazaPanel.intelligence => 10,
      NazaPanel.agenticCoding => 11,
      NazaPanel.dataPipes => 12,
    };
  }

  String _labelForPanel(NazaPanel panel) {
    switch (panel) {
      case NazaPanel.chat:
        return 'ready';
      case NazaPanel.games:
        return 'games';
      case NazaPanel.chess:
        return 'chess agent';
      case NazaPanel.roadScanner:
        return 'road scanner';
      case NazaPanel.foodWater:
        return 'food / water scanner';
      case NazaPanel.health:
        return 'personal health studio';
      case NazaPanel.book:
        return 'bookforge';
      case NazaPanel.labs:
        return _exploreSection.label;
      case NazaPanel.settings:
        return 'settings';
      case NazaPanel.history:
        return 'history';
      case NazaPanel.intelligence:
        return 'intelligence';
      case NazaPanel.agenticCoding:
        return 'agentic code foundry';
      case NazaPanel.dataPipes:
        return 'secure data pipes';
    }
  }
}

class _NazaStaticBackdrop extends StatelessWidget {
  const _NazaStaticBackdrop();

  @override
  Widget build(BuildContext context) {
    // Keep the decorative canvas available for GPU builds, but use an opaque
    // surface on the software renderer. The large translucent circles, paths,
    // and grid were the dominant source of raster jank behind every panel.
    final background = Stack(
      fit: StackFit.expand,
      children: [
        DecoratedBox(
          decoration: BoxDecoration(
            color: NazaPalette.inkDeep,
            image: DecorationImage(
              image: AssetImage('assets/backgrounds/chat_river_forest.png'),
              fit: BoxFit.cover,
              opacity: 0.16,
              filterQuality: FilterQuality.low,
            ),
          ),
        ),
        ColoredBox(
          color: NazaPalette.inkDeep.withValues(alpha: 0.22),
        ),
        if (!NazaPalette.reduceRasterEffects)
          const Positioned.fill(
            child: CustomPaint(painter: _NazaBackdropPainter()),
          ),
      ],
    );
    return IgnorePointer(child: RepaintBoundary(child: background));
  }
}

class _NazaBackdropPainter extends CustomPainter {
  const _NazaBackdropPainter();

  @override
  void paint(Canvas canvas, Size size) {
    final bg = Paint()..color = const Color(0xB2020806);
    canvas.drawRect(Offset.zero & size, bg);

    final gridPaint = Paint()
      ..color = const Color(0x0C80F6B3)
      ..strokeWidth = 1;
    const grid = 136.0;
    for (var x = grid; x < size.width; x += grid) {
      canvas.drawLine(Offset(x, 0), Offset(x, size.height), gridPaint);
    }
    for (var y = grid; y < size.height; y += grid) {
      canvas.drawLine(Offset(0, y), Offset(size.width, y), gridPaint);
    }

    final nodes = <({double x, double y, Color color, double radius})>[
      (x: 0.12, y: 0.18, color: Color(0x1457EFAE), radius: 104),
      (x: 0.82, y: 0.16, color: Color(0x1070D2FF), radius: 132),
      (x: 0.30, y: 0.82, color: Color(0x1259EFA9), radius: 142),
      (x: 0.87, y: 0.78, color: Color(0x10B6FFDF), radius: 96),
    ];

    for (var i = 0; i < nodes.length; i++) {
      final node = nodes[i];
      final center = Offset(size.width * node.x, size.height * node.y);
      final paint = Paint()..color = node.color;
      canvas.drawCircle(center, node.radius, paint);

      final corePaint = Paint()
        ..color = const Color(0x244CF0AE)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.1;
      canvas.drawCircle(center, node.radius * 0.22, corePaint);
    }

    final ribbonPaint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..strokeWidth = 1.8;

    final ribbons = <({double y, double lift, Color color})>[
      (y: 0.22, lift: 0.08, color: Color(0x1757EFAE)),
      (y: 0.46, lift: -0.06, color: Color(0x1470D2FF)),
      (y: 0.70, lift: 0.05, color: Color(0x1259EFA9)),
    ];
    for (final ribbon in ribbons) {
      final y = size.height * ribbon.y;
      final lift = size.height * ribbon.lift;
      final path = Path()
        ..moveTo(-40, y)
        ..cubicTo(
          size.width * 0.22,
          y - lift,
          size.width * 0.40,
          y + lift,
          size.width * 0.60,
          y,
        )
        ..cubicTo(
          size.width * 0.78,
          y - lift,
          size.width * 0.96,
          y + lift,
          size.width + 40,
          y,
        );
      ribbonPaint.color = ribbon.color;
      canvas.drawPath(path, ribbonPaint);
    }
  }

  @override
  bool shouldRepaint(covariant _NazaBackdropPainter oldDelegate) => false;
}

class _ModelWorkingBeacon extends StatefulWidget {
  const _ModelWorkingBeacon();

  @override
  State<_ModelWorkingBeacon> createState() => _ModelWorkingBeaconState();
}

class _ModelWorkingBeaconState extends State<_ModelWorkingBeacon>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1500),
  )..repeat();

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Tooltip(
      message: 'Local model is working',
      child: RepaintBoundary(
        child: SizedBox(
          width: 38,
          height: 38,
          child: AnimatedBuilder(
            animation: _controller,
            builder: (_, _) => CustomPaint(
              painter: _ModelWorkingBeaconPainter(_controller.value),
            ),
          ),
        ),
      ),
    );
  }
}

class _ModelWorkingBeaconPainter extends CustomPainter {
  final double progress;

  const _ModelWorkingBeaconPainter(this.progress);

  @override
  void paint(Canvas canvas, Size size) {
    final center = size.center(Offset.zero);
    final radius = size.shortestSide * 0.13;
    // Keep the beacon as solid geometry. Blur-backed mask filters compile a
    // new fragment shader on first use and are especially costly on desktop.
    canvas.drawCircle(center, radius, Paint()..color = NazaPalette.mintSoft);
    for (var i = 0; i < 3; i++) {
      final phase = (progress + i / 3) % 1.0;
      final orbitRadius = size.shortestSide * (0.16 + phase * 0.34);
      final angle = phase * math.pi * 2 + i * math.pi * 0.67;
      final point = Offset(
        center.dx + math.cos(angle) * orbitRadius,
        center.dy + math.sin(angle) * orbitRadius,
      );
      final opacity = ((1 - phase) * 0.72 + 0.18).clamp(0.0, 1.0);
      canvas.drawCircle(
        point,
        1.7 + (1 - phase) * 1.2,
        Paint()..color = NazaPalette.mint.withAlpha((opacity * 255).round()),
      );
    }
    canvas.drawCircle(
      center,
      size.shortestSide * 0.42,
      Paint()
        ..color = NazaPalette.mint.withAlpha(80)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1,
    );
  }

  @override
  bool shouldRepaint(covariant _ModelWorkingBeaconPainter oldDelegate) =>
      oldDelegate.progress != progress;
}

class _TopBar extends StatelessWidget {
  final NazaPanel panel;
  final String status;
  final bool wide;
  final bool sending;
  final bool stopping;
  final VoidCallback onStop;
  final VoidCallback onNewThread;
  final ValueChanged<NazaPanel> onPanel;

  const _TopBar({
    required this.panel,
    required this.status,
    required this.wide,
    required this.sending,
    required this.stopping,
    required this.onStop,
    required this.onNewThread,
    required this.onPanel,
  });

  @override
  Widget build(BuildContext context) {
    final title = _title(panel);
    final narrow = MediaQuery.sizeOf(context).width < 380;
    final compactButtonStyle = IconButton.styleFrom(
      minimumSize: const Size(38, 40),
      fixedSize: const Size(38, 40),
      padding: EdgeInsets.zero,
      tapTargetSize: MaterialTapTargetSize.shrinkWrap,
    );
    return Container(
      height: 68,
      padding: EdgeInsets.symmetric(horizontal: narrow ? 8 : 14),
      decoration: BoxDecoration(
        color: NazaPalette.shell,
        border: Border(bottom: BorderSide(color: NazaPalette.border)),
        boxShadow: NazaPalette.reduceRasterEffects
            ? const []
            : [
                BoxShadow(
                  color: NazaPalette.mint.withAlpha(22),
                  blurRadius: 24,
                  offset: const Offset(0, 8),
                ),
              ],
      ),
      child: Row(
        children: [
          _IconPill(
            icon: Icons.spa_rounded,
            selected: true,
            onTap: () => onPanel(NazaPanel.chat),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: AnimatedSwitcher(
              duration: const Duration(milliseconds: 120),
              switchInCurve: Curves.easeOutCubic,
              child: title == null
                  ? const SizedBox.shrink(
                      key: ValueKey<NazaPanel>(NazaPanel.chat),
                    )
                  : Text(
                      title,
                      key: ValueKey<NazaPanel>(panel),
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        color: NazaPalette.text,
                        fontWeight: FontWeight.w900,
                        fontSize: 23,
                        letterSpacing: -0.7,
                        fontFamily: NazaFonts.display,
                      ),
                    ),
            ),
          ),
          if (panel == NazaPanel.chat) ...[
            if (sending && !narrow) const _ModelWorkingBeacon(),
            IconButton(
              onPressed: sending ? null : onNewThread,
              tooltip: 'Start new thread',
              icon: Icon(Icons.add_comment_rounded),
              color: NazaPalette.mintSoft,
              style: narrow ? compactButtonStyle : null,
            ),
          ],
          ConstrainedBox(
            constraints: BoxConstraints(
              maxWidth: wide
                  ? 260
                  : narrow
                  ? 76
                  : 110,
            ),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
              decoration: BoxDecoration(
                color: NazaPalette.shellSoft,
                borderRadius: BorderRadius.circular(18),
                border: Border.all(color: NazaPalette.border),
              ),
              child: sending
                  ? ValueListenableBuilder<NazaRuntimeSnapshot>(
                      valueListenable: NazaLocalGemma.instance.snapshot,
                      builder: (_, snap, _) =>
                          _TopStatusText(snap.busy ? snap.phase : status),
                    )
                  : _TopStatusText(status),
            ),
          ),
          if (sending) ...[
            const SizedBox(width: 8),
            IconButton.filled(
              onPressed: stopping ? null : onStop,
              tooltip: stopping ? 'Stopping generation' : 'Stop generation',
              icon: Icon(
                stopping ? Icons.hourglass_top_rounded : Icons.stop_rounded,
              ),
              color: NazaPalette.text,
              style: IconButton.styleFrom(
                minimumSize: narrow ? const Size(40, 40) : null,
                fixedSize: narrow ? const Size(40, 40) : null,
                padding: narrow ? EdgeInsets.zero : null,
                tapTargetSize: narrow ? MaterialTapTargetSize.shrinkWrap : null,
                backgroundColor: NazaPalette.danger,
                disabledBackgroundColor: NazaPalette.danger.withAlpha(100),
              ),
            ),
          ],
        ],
      ),
    );
  }

  static String? _title(NazaPanel panel) {
    switch (panel) {
      case NazaPanel.chat:
        return null;
      case NazaPanel.games:
        return 'Games';
      case NazaPanel.chess:
        return 'Chess Agent';
      case NazaPanel.roadScanner:
        return 'Road Scanner';
      case NazaPanel.foodWater:
        return 'Food / Water Scanner';
      case NazaPanel.health:
        return 'Personal Health Studio';
      case NazaPanel.book:
        return 'BookForge';
      case NazaPanel.labs:
        return 'Exploration Studio';
      case NazaPanel.settings:
        return 'Settings';
      case NazaPanel.history:
        return 'History';
