final class _ModelAssemblySettingsCard extends StatefulWidget {
  const _ModelAssemblySettingsCard();

  @override
  State<_ModelAssemblySettingsCard> createState() =>
      _ModelAssemblySettingsCardState();
}

final class _ModelAssemblySettingsCardState
    extends State<_ModelAssemblySettingsCard> {
  final _store = NazaModelAssemblyStore();
  final _chunk = TextEditingController(text: '12000');
  final _shards = TextEditingController(text: '3');
  final _threshold = TextEditingController(text: '0.35');
  NazaModelAssemblyConfig _config = const NazaModelAssemblyConfig();
  List<NazaRemoteModelProfile> _profiles = const [];
  Set<String> _selectedProfiles = <String>{};
  bool _loading = true;
  bool _saving = false;
  String? _message;

  @override
  void initState() {
    super.initState();
    unawaited(_load());
  }

  @override
  void dispose() {
    _chunk.dispose();
    _shards.dispose();
    _threshold.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    try {
      final config = await _store.load();
      final profiles = await NazaRemoteModelCatalog().load();
      if (!mounted) return;
      setState(() {
        _config = config;
        _profiles = profiles;
        _selectedProfiles = config.profileIds.toSet();
        _chunk.text = config.chunkCharacters.toString();
        _shards.text = config.maxShards.toString();
        _threshold.text = config.entropyThreshold.toStringAsFixed(2);
        _loading = false;
      });
    } catch (error) {
      if (mounted) {
        setState(() {
          _loading = false;
          _message = 'Unlock the encrypted vault to manage assembly: $error';
        });
      }
    }
  }

  Future<void> _save() async {
    if (_saving) return;
    final config = _config.copyWith(
      profileIds: _selectedProfiles,
      chunkCharacters: int.tryParse(_chunk.text.trim()) ?? 12000,
      maxShards: int.tryParse(_shards.text.trim()) ?? 3,
      entropyThreshold: double.tryParse(_threshold.text.trim()) ?? 0.35,
    );
    setState(() => _saving = true);
    try {
      await _store.save(config);
      if (mounted) {
        setState(() {
          _config = config;
          _message = 'Assembly policy saved in the encrypted vault.';
        });
      }
    } catch (error) {
      if (mounted)
        setState(() => _message = 'Assembly policy was not saved: $error');
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) => _NazaGlassCard(
    padding: const EdgeInsets.all(16),
    radius: 20,
    active: _config.mode == NazaAssemblyMode.shardedAssembly,
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Text(
          'Chunked provider assembly',
          style: TextStyle(fontSize: 18, fontWeight: FontWeight.w900),
        ),
        const SizedBox(height: 4),
        Text(
          'Gemma 4 E2B local is always the default. Assembly is opt-in per feature route and keeps provider keys in the encrypted vault.',
          style: TextStyle(color: NazaPalette.subtext, height: 1.35),
        ),
        const SizedBox(height: 12),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: [
            for (final mode in NazaAssemblyMode.values)
              ChoiceChip(
                label: Text(switch (mode) {
                  NazaAssemblyMode.localOnly => 'Local Gemma only',
                  NazaAssemblyMode.singleRemote => 'One remote profile',
                  NazaAssemblyMode.shardedAssembly => 'Multi-provider shards',
                }),
                selected: _config.mode == mode,
                onSelected: _loading
                    ? null
                    : (_) => setState(
                        () => _config = _config.copyWith(mode: mode),
                      ),
              ),
          ],
        ),
        const SizedBox(height: 12),
        if (_profiles.isEmpty)
          Text(
            'Add at least two saved provider profiles above to enable sharded assembly.',
            style: TextStyle(color: NazaPalette.muted),
          )
        else ...[
          Text(
            'Shard participants',
            style: TextStyle(
              fontWeight: FontWeight.w800,
              color: NazaPalette.text,
            ),
          ),
          const SizedBox(height: 6),
          Wrap(
            spacing: 6,
            runSpacing: 6,
            children: [
              for (final profile in _profiles)
                FilterChip(
                  label: Text(profile.displayName),
                  selected: _selectedProfiles.contains(profile.id),
                  onSelected: (selected) => setState(() {
                    if (selected) {
                      _selectedProfiles.add(profile.id);
                    } else {
                      _selectedProfiles.remove(profile.id);
                    }
                  }),
                ),
            ],
          ),
        ],
        const SizedBox(height: 12),
        Wrap(
          spacing: 10,
          runSpacing: 10,
          children: [
            SizedBox(
              width: 150,
              child: TextField(
                controller: _chunk,
                keyboardType: TextInputType.number,
                decoration: const InputDecoration(
                  labelText: 'Chunk characters',
                  helperText: '2k–40k',
                  border: OutlineInputBorder(),
                ),
              ),
            ),
            SizedBox(
              width: 130,
              child: TextField(
                controller: _shards,
                keyboardType: TextInputType.number,
                decoration: const InputDecoration(
                  labelText: 'Max shards',
                  helperText: '1–8',
                  border: OutlineInputBorder(),
                ),
              ),
            ),
            SizedBox(
              width: 150,
              child: TextField(
                controller: _threshold,
                keyboardType: const TextInputType.numberWithOptions(
                  decimal: true,
                ),
                decoration: const InputDecoration(
                  labelText: 'Entropy threshold',
                  helperText: '0.00–1.00',
                  border: OutlineInputBorder(),
                ),
              ),
            ),
          ],
        ),
        const SizedBox(height: 10),
        Text(
          'Entropy surface measures normalized vocabulary disagreement between shard results. It is a review signal, not a truth score.',
          style: TextStyle(
            color: NazaPalette.subtext,
            fontSize: 12,
            height: 1.35,
          ),
        ),
        const SizedBox(height: 12),
        FilledButton.icon(
          onPressed: _saving ? null : _save,
          icon: const Icon(Icons.hub_rounded),
          label: Text(_saving ? 'Saving…' : 'Save assembly policy'),
        ),
        if (_message != null) ...[
          const SizedBox(height: 8),
          Text(_message!, style: TextStyle(color: NazaPalette.subtext)),
        ],
      ],
    ),
  );
}

final class _RemoteModelSettingsCard extends StatefulWidget {
  const _RemoteModelSettingsCard({required this.feature});

  final NazaModelFeature feature;

  @override
  State<_RemoteModelSettingsCard> createState() =>
      _RemoteModelSettingsCardState();
}

final class _RemoteModelSettingsCardState
    extends State<_RemoteModelSettingsCard> {
  final _catalog = NazaRemoteModelCatalog();
  final _routingStore = NazaModelRoutingStore();
  final _profileIdController = TextEditingController(text: 'provider-openAi-1');
  final _model = TextEditingController(text: 'gpt-6-astra');
  final _endpoint = TextEditingController(
    text: 'https://api.openai.com/v1/chat/completions',
  );
  final _apiKey = TextEditingController();
  NazaRemoteProvider _provider = NazaRemoteProvider.openAi;
  NazaOpenAiReasoningEffort _reasoningEffort = NazaOpenAiReasoningEffort.light;
  List<NazaRemoteModelProfile> _profiles = const [];
  NazaModelRoutingConfig _routing = const NazaModelRoutingConfig();
  bool _loading = true;
  bool _saving = false;
  bool _showKey = false;
  String? _message;

  @override
  void initState() {
    super.initState();
    unawaited(_load());
  }

  @override
  void dispose() {
    _profileIdController.dispose();
    _model.dispose();
    _endpoint.dispose();
    _apiKey.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    try {
      final profiles = await _catalog.load();
      final routing = await _routingStore.load();
      if (!mounted) return;
      final firstOpenAi = profiles.where(
        (profile) => profile.provider == NazaRemoteProvider.openAi,
      );
      setState(() {
        _profiles = profiles;
        _routing = routing;
        if (firstOpenAi.isNotEmpty) {
          final profile = firstOpenAi.first;
          _provider = profile.provider;
          _profileIdController.text = profile.id;
          _model.text = profile.model;
          _reasoningEffort = profile.reasoningEffort;
          _endpoint.text = profile.endpoint;
        }
        _loading = false;
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _loading = false;
        _message = 'Unlock the encrypted vault to manage providers: $error';
      });
    }
  }

  String get _profileId => _profileIdController.text.trim();

  NazaRemoteModelProfile? get _existing {
    for (final profile in _profiles) {
      if (profile.id == _profileId) return profile;
    }
    return null;
  }

  void _selectProvider(NazaRemoteProvider provider) {
    final existing = _profiles.where((item) => item.provider == provider);
    setState(() {
      _provider = provider;
      _apiKey.clear();
      if (existing.isNotEmpty) {
        _profileIdController.text = existing.first.id;
        _model.text = existing.first.model;
        _reasoningEffort = existing.first.reasoningEffort;
        _endpoint.text = existing.first.endpoint;
      } else {
        _profileIdController.text = 'provider-${provider.name}-1';
        _reasoningEffort = NazaOpenAiReasoningEffort.light;
        final defaults = _providerDefaults(provider);
        _model.text = defaults.$1;
        _endpoint.text = defaults.$2;
      }
    });
  }

  void _loadProfile(String id) {
    final profile = _profiles.where((item) => item.id == id);
    if (profile.isEmpty) return;
    final selected = profile.first;
    setState(() {
      _provider = selected.provider;
      _profileIdController.text = selected.id;
      _model.text = selected.model;
      _reasoningEffort = selected.reasoningEffort;
      _endpoint.text = selected.endpoint;
      _apiKey.clear();
      _message =
          'Loaded ${selected.displayName}. Enter a new key only if it changed.';
    });
  }

  void _selectCatalogModel(String model) {
    setState(() {
      _model.text = model;
      if (_provider == NazaRemoteProvider.gemini) {
        _endpoint.text =
            'https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent';
      }
    });
  }

  Future<void> _saveProfile() async {
    if (_saving) return;
    setState(() {
      _saving = true;
      _message = null;
    });
    try {
      final prior = _existing;
      if (_profileId.isEmpty || _profileId.length > 100) {
        throw const FormatException(
          'Enter a short profile name or identifier.',
        );
      }
      final profile = NazaRemoteModelProfile(
        id: _profileId,
        provider: _provider,
        displayName: '${_provider.label} · ${_model.text.trim()}',
        model: _model.text.trim(),
        reasoningEffort: _reasoningEffort,
        endpoint: _endpoint.text.trim(),
        apiKey: _apiKey.text.trim().isEmpty
            ? (prior?.apiKey ?? '')
            : _apiKey.text.trim(),
        allowCustomEndpoint: _provider == NazaRemoteProvider.custom,
      );
      if (profile.apiKey.isEmpty) {
        throw const FormatException('Enter an API key before saving.');
      }
      await _catalog.upsert(profile);
      final profiles = await _catalog.load();
      if (!mounted) return;
      setState(() {
        _profiles = profiles;
        _apiKey.clear();
        _message = 'Saved securely in the encrypted Naza vault.';
      });
    } catch (error) {
      if (mounted) setState(() => _message = 'Provider was not saved: $error');
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  Future<void> _setRoute(String id) async {
    final nextRoutes = Map<NazaModelFeature, String>.from(
      _routing.featureProfiles,
    );
    nextRoutes[widget.feature] = id;
    final next = NazaModelRoutingConfig(
      defaultProfileId: _routing.defaultProfileId,
      featureProfiles: nextRoutes,
    );
    try {
      await _routingStore.save(next);
      if (mounted) {
        setState(() {
          _routing = next;
          _message = '${widget.feature.label} model routing saved.';
        });
      }
    } catch (error) {
      if (mounted) setState(() => _message = 'Routing was not saved: $error');
    }
  }

  Future<void> _setDefaultRoute(String id) async {
    final next = NazaModelRoutingConfig(
      defaultProfileId: id == NazaModelRoutingStore.localProfileId ? null : id,
      featureProfiles: _routing.featureProfiles,
    );
    try {
      await _routingStore.save(next);
      if (mounted) {
        setState(() {
          _routing = next;
          _message = id == NazaModelRoutingStore.localProfileId
              ? 'Local Gemma restored as the global default.'
              : 'Global provider fallback saved for apps without an override.';
        });
      }
    } catch (error) {
      if (mounted)
        setState(() => _message = 'Global route was not saved: $error');
    }
  }

  @override
  Widget build(BuildContext context) {
    // A profile may have been removed from the vault since routing was saved.
    // Always fall back to local Gemma so DropdownButton never receives a value
    // that is missing from its item list.
    final configured = _routing.profileFor(widget.feature);
    final knownProfileIds = <String>{
      NazaModelRoutingStore.localProfileId,
      ..._profiles.map((profile) => profile.id),
    };
    final selected = configured != null && knownProfileIds.contains(configured)
        ? configured
        : NazaModelRoutingStore.localProfileId;
    final globalDefault =
        _routing.defaultProfileId != null &&
            knownProfileIds.contains(_routing.defaultProfileId)
        ? _routing.defaultProfileId!
        : NazaModelRoutingStore.localProfileId;
    return _NazaGlassCard(
      padding: const EdgeInsets.all(16),
      radius: 20,
      active: selected != NazaModelRoutingStore.localProfileId,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            '${widget.feature.editorialTitle} model',
            style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w900),
          ),
          const SizedBox(height: 4),
          Text(
            'Choose Local Gemma or a vault-backed remote provider for this feature group.',
            style: TextStyle(color: NazaPalette.subtext),
          ),
          const SizedBox(height: 12),
          DropdownButtonFormField<String>(
            key: ValueKey('route-${widget.feature.name}-$selected'),
            initialValue: selected,
            decoration: const InputDecoration(
              labelText: 'Active model',
              prefixIcon: Icon(Icons.hub_rounded),
              border: OutlineInputBorder(),
            ),
            items: [
              const DropdownMenuItem(
                value: NazaModelRoutingStore.localProfileId,
                child: Text('Gemma 4 E2B · local and private'),
              ),
              for (final profile in _profiles)
                DropdownMenuItem(
                  value: profile.id,
                  child: Text(profile.displayName),
                ),
            ],
            onChanged: _loading
                ? null
                : (value) {
                    if (value != null) unawaited(_setRoute(value));
                  },
          ),
          const SizedBox(height: 10),
          DropdownButtonFormField<String>(
            key: ValueKey('default-route-$globalDefault'),
            initialValue: globalDefault,
            decoration: const InputDecoration(
              labelText: 'Global default for all apps',
              helperText:
                  'Local Gemma stays selected until you explicitly change this.',
              prefixIcon: Icon(Icons.public_rounded),
              border: OutlineInputBorder(),
            ),
            items: [
              const DropdownMenuItem(
                value: NazaModelRoutingStore.localProfileId,
                child: Text('Gemma 4 E2B · local and private'),
              ),
              for (final profile in _profiles)
                DropdownMenuItem(
                  value: profile.id,
                  child: Text(profile.displayName),
                ),
            ],
            onChanged: _loading
                ? null
                : (value) {
                    if (value != null) unawaited(_setDefaultRoute(value));
                  },
          ),
          const Divider(height: 28),
          const Text(
            'Remote provider vault',
            style: TextStyle(fontWeight: FontWeight.w900),
          ),
          const SizedBox(height: 10),
          DropdownButtonFormField<String>(
            initialValue: _profiles.any((profile) => profile.id == _profileId)
                ? _profileId
                : null,
            decoration: const InputDecoration(
              labelText: 'Saved provider profile',
              helperText:
                  'Create multiple profiles to use multiple keys from one provider.',
              border: OutlineInputBorder(),
            ),
            items: [
              for (final profile in _profiles)
                DropdownMenuItem(
                  value: profile.id,
                  child: Text('${profile.displayName} · ${profile.id}'),
                ),
            ],
            onChanged: _saving
                ? null
                : (value) {
                    if (value != null) _loadProfile(value);
                  },
          ),
          const SizedBox(height: 10),
          TextField(
            controller: _profileIdController,
            decoration: const InputDecoration(
              labelText: 'Profile name / ID',
              helperText: 'Use a distinct ID for every API key or shard.',
              border: OutlineInputBorder(),
            ),
          ),
          const SizedBox(height: 10),
          DropdownButtonFormField<NazaRemoteProvider>(
            initialValue: _provider,
            decoration: const InputDecoration(
              labelText: 'Provider type',
              border: OutlineInputBorder(),
            ),
            items: NazaRemoteProvider.values
                .map(
                  (provider) => DropdownMenuItem(
                    value: provider,
                    child: Text(provider.label),
                  ),
                )
                .toList(),
            onChanged: _saving
                ? null
                : (value) {
                    if (value != null) _selectProvider(value);
                  },
          ),
          const SizedBox(height: 10),
          TextField(
            controller: _model,
            decoration: const InputDecoration(
              labelText: 'Model identifier',
              border: OutlineInputBorder(),
            ),
          ),
          if (NazaProviderModelCatalog.forProvider(_provider).isNotEmpty) ...[
            const SizedBox(height: 8),
            Text(
              'Provider model catalog · tap to use',
              style: TextStyle(fontWeight: FontWeight.w800, fontSize: 12),
            ),
            const SizedBox(height: 6),
            Wrap(
              spacing: 6,
              runSpacing: 6,
              children: [
                for (final model in NazaProviderModelCatalog.forProvider(
                  _provider,
                ))
                  ActionChip(
                    label: Text(model),
                    onPressed: () => _selectCatalogModel(model),
                  ),
              ],
            ),
          ],
          const SizedBox(height: 10),
          if (_provider == NazaRemoteProvider.openAi) ...[
            DropdownButtonFormField<NazaOpenAiReasoningEffort>(
              key: ValueKey('reasoning-$_profileId-${_reasoningEffort.name}'),
              initialValue: _reasoningEffort,
              decoration: const InputDecoration(
                labelText: 'Reasoning effort',
                helperText: 'For GPT-6 Astra. Save the provider to apply changes.',
                border: OutlineInputBorder(),
              ),
              items: [
                for (final effort in NazaOpenAiReasoningEffort.values)
                  DropdownMenuItem(value: effort, child: Text(effort.label)),
              ],
              onChanged: (value) {
                if (value != null) setState(() => _reasoningEffort = value);
              },
            ),
            const SizedBox(height: 10),
          ],
          TextField(
            controller: _endpoint,
            decoration: const InputDecoration(
              labelText: 'HTTPS endpoint',
              border: OutlineInputBorder(),
            ),
          ),
          const SizedBox(height: 10),
          TextField(
            controller: _apiKey,
            obscureText: !_showKey,
            enableSuggestions: false,
            autocorrect: false,
            decoration: InputDecoration(
              labelText: _existing == null
                  ? 'API key'
                  : 'API key · leave blank to keep saved key',
              border: const OutlineInputBorder(),
              suffixIcon: IconButton(
                tooltip: _showKey ? 'Hide API key' : 'Show API key',
                onPressed: () => setState(() => _showKey = !_showKey),
                icon: Icon(_showKey ? Icons.visibility_off : Icons.visibility),
              ),
            ),
          ),
          const SizedBox(height: 10),
          FilledButton.icon(
            onPressed: _saving ? null : _saveProfile,
            icon: const Icon(Icons.lock_rounded),
            label: Text(_saving ? 'Saving…' : 'Save provider securely'),
          ),
          if (_message != null) ...[
            const SizedBox(height: 10),
            Text(_message!, style: TextStyle(color: NazaPalette.subtext)),
          ],
        ],
      ),
    );
  }

  static (String, String) _providerDefaults(
    NazaRemoteProvider provider,
  ) => switch (provider) {
    NazaRemoteProvider.openAi => (
      'gpt-6-astra',
      'https://api.openai.com/v1/chat/completions',
    ),
    NazaRemoteProvider.anthropic => (
      'claude-sonnet-4-0',
      'https://api.anthropic.com/v1/messages',
    ),
    NazaRemoteProvider.gemini => (
      'gemini-2.5-flash',
      'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent',
    ),
    NazaRemoteProvider.digitalOcean => (
      'llama-3.3-70b-instruct',
      'https://inference.do-ai.run/v1/chat/completions',
    ),
    NazaRemoteProvider.meta => (
      'muse-spark-1.2',
      'https://api.meta.ai/v1/chat/completions',
    ),
    NazaRemoteProvider.custom => ('', 'https://'),
  };
}

final class _BookForgeConnectionSettingsCard extends StatefulWidget {
  const _BookForgeConnectionSettingsCard();

  @override
  State<_BookForgeConnectionSettingsCard> createState() =>
      _BookForgeConnectionSettingsCardState();
}

final class _BookForgeConnectionSettingsCardState
    extends State<_BookForgeConnectionSettingsCard> {
  final _token = TextEditingController();
  bool _saving = false;
  bool _show = false;
  String? _message;

  @override
  void dispose() {
    _token.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    if (_token.text.trim().isEmpty) {
      setState(() => _message = 'Enter a fine-grained GitHub token.');
      return;
    }
    setState(() => _saving = true);
    try {
      await NazaSecureDatabase.instance.writeJson(
        'bookforge',
        'github-token',
        _token.text.trim(),
      );
      if (mounted) {
        setState(() {
          _token.clear();
          _message = 'AddBooks token saved in the encrypted vault.';
        });
      }
    } catch (error) {
      if (mounted) setState(() => _message = 'Token was not saved: $error');
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) => _NazaGlassCard(
    padding: const EdgeInsets.all(16),
    radius: 20,
    active: true,
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Text(
          'AddBooks connection',
          style: TextStyle(fontSize: 18, fontWeight: FontWeight.w900),
        ),
        const SizedBox(height: 4),
        Text(
          'Store the fine-grained GitHub token used by AddBooks. Repository contents permission should be limited to the intended book repositories.',
          style: TextStyle(color: NazaPalette.subtext),
        ),
        const SizedBox(height: 10),
        TextField(
          controller: _token,
          obscureText: !_show,
          enableSuggestions: false,
          autocorrect: false,
          decoration: InputDecoration(
            labelText: 'GitHub token · leave empty after saving',
            border: const OutlineInputBorder(),
            suffixIcon: IconButton(
              tooltip: _show ? 'Hide token' : 'Show token',
              onPressed: () => setState(() => _show = !_show),
              icon: Icon(_show ? Icons.visibility_off : Icons.visibility),
            ),
          ),
        ),
        const SizedBox(height: 10),
        FilledButton.icon(
          onPressed: _saving ? null : _save,
          icon: const Icon(Icons.lock_rounded),
          label: Text(_saving ? 'Saving…' : 'Save AddBooks token'),
        ),
        if (_message != null) ...[
          const SizedBox(height: 8),
          Text(_message!, style: TextStyle(color: NazaPalette.subtext)),
        ],
      ],
    ),
  );
}

