// LLM-CONTEXT:BEGIN
// FILE: lib/agentic/agentic_coding_surface.dart
// ROLE: Visual GUI for bounded coding-agent orchestration and evidence review.
// DOMAIN: agentic-coding
// SECURITY-INVARIANT: Model output is a proposal until separately approved;
// credentials never enter prompts, logs, receipts, or public node projections.
// CHANGE-GUARD: Keep local-first defaults, responsive layouts, explicit
// capability approvals, and honest labels for diagnostic entropy surfaces.
// LLM-CONTEXT:END

typedef NazaAgenticTaskRunner =
    Future<NazaAgenticRunResult> Function(NazaAgenticTaskRequest request);
typedef NazaAgenticImagePicker = Future<NazaAgenticAttachment?> Function();

class NazaAgenticCodingSurface extends StatefulWidget {
  const NazaAgenticCodingSurface({
    super.key,
    required this.runTask,
    this.pickImage,
    this.store,
    this.operationsStore,
    this.collaborationStore,
    this.chatRoomStore,
    this.kuboSettingsStore,
    this.harmGate,
    this.collector = const NazaRepositoryContextCollector(),
    this.initialConfig,
    this.persistState = true,
  });

  final NazaAgenticTaskRunner runTask;
  final NazaAgenticImagePicker? pickImage;
  final NazaAgenticWorkspaceStore? store;
  final NazaRemoteOperationsStore? operationsStore;
  final NazaCollaborationQueueStore? collaborationStore;
  final NazaIpfsChatRoomStore? chatRoomStore;
  final NazaKuboSettingsStore? kuboSettingsStore;
  final NazaHarmGate? harmGate;
  final NazaRepositoryContextCollector collector;
  final NazaAgenticWorkspaceConfig? initialConfig;
  final bool persistState;

  @override
  State<NazaAgenticCodingSurface> createState() =>
      _AgenticCodingSurfaceNazaAgenticCodingSurfaceState();
}

class _AgenticCodingSurfaceNazaAgenticCodingSurfaceState
    extends State<NazaAgenticCodingSurface> {
  static const Color _agenticCodingSurfaceViolet = Color(0xFFAA93FF);
  static const Color _agenticCodingSurfaceCyan = Color(0xFF62D9F7);
  static const Color _agenticCodingSurfaceMint = Color(0xFF76E3B4);
  static const Color _agenticCodingSurfaceAmber = Color(0xFFFFC66D);
  static const Color _agenticCodingSurfaceRose = Color(0xFFFF7F9B);
  static const Color _agenticCodingSurfaceInk = Color(0xFF06100F);
  static const Color _agenticCodingSurfacePanel = Color(0xFF0D1B19);
  static const Color _agenticCodingSurfaceBorder = Color(0xFF29433D);
  static const Color _agenticCodingSurfaceText = Color(0xFFF0FFF8);
  static const Color _agenticCodingSurfaceSubtext = Color(0xFFA8BDB5);

  late final NazaAgenticWorkspaceStore _agenticCodingSurfaceStore;
  late final NazaRemoteOperationsStore _agenticCodingSurfaceOperationsStore;
  late final NazaCollaborationQueueStore
  _agenticCodingSurfaceCollaborationStore;
  late final NazaIpfsChatRoomStore _agenticCodingSurfaceChatRoomStore;
  late final NazaKuboSettingsStore _agenticCodingSurfaceKuboSettingsStore;
  late final NazaHarmGate _agenticCodingSurfaceHarmGate;
  late NazaAgenticWorkspaceConfig _agenticCodingSurfaceConfig;
  final TextEditingController
  _agenticCodingSurfaceTaskController = TextEditingController(
    text:
        'Inspect the selected architecture, find the highest-leverage improvement, and propose a reversible patch with focused verification.',
  );
  final FocusNode _agenticCodingSurfaceTaskFocus = FocusNode();
  NazaRepositoryContext? _agenticCodingSurfaceRepository;
  NazaAgenticAttachment? _agenticCodingSurfaceAttachment;
  NazaAgenticRunResult? _agenticCodingSurfaceResult;
  bool _agenticCodingSurfaceLoading = true;
  bool _agenticCodingSurfaceIndexing = false;
  bool _agenticCodingSurfaceRunning = false;
  bool _agenticCodingSurfaceProposePatch = true;
  bool _agenticCodingSurfaceRunChecks = false;
  bool _agenticCodingSurfaceAllowNetwork = false;
  bool _agenticCodingSurfaceMutationApproved = false;
  bool _agenticCodingSurfaceNetworkApproved = false;
  String _agenticCodingSurfaceStatus = 'Initializing the secure workbench';
  String? _agenticCodingSurfaceError;
  NazaAgenticPolicyDecision? _agenticCodingSurfaceLastPolicy;
  final Map<String, String> _agenticCodingSurfaceNodeStates =
      <String, String>{};
  List<NazaRemoteOperationRequest> _agenticCodingSurfaceOperations =
      const <NazaRemoteOperationRequest>[];
  List<NazaCollaborationPool> _agenticCodingSurfaceCollaborationPools =
      const <NazaCollaborationPool>[];
  List<NazaQueuedEdit> _agenticCodingSurfaceQueuedEdits =
      const <NazaQueuedEdit>[];
  List<NazaAgentEnvelope> _agenticCodingSurfaceAgentEnvelopes =
      const <NazaAgentEnvelope>[];
  List<NazaChatRoom> _agenticCodingSurfaceChatRooms = const <NazaChatRoom>[];
  final Map<String, NazaChatRoomMonitorSnapshot>
  _agenticCodingSurfaceChatMonitors = <String, NazaChatRoomMonitorSnapshot>{};
  final Map<String, List<NazaChatMessageEnvelope>>
  _agenticCodingSurfaceChatMessages = <String, List<NazaChatMessageEnvelope>>{};
  NazaKuboNodeSettings _agenticCodingSurfaceKuboSettings =
      NazaKuboNodeSettings.defaults;

  @override
  void initState() {
    super.initState();
    _agenticCodingSurfaceHarmGate =
        widget.harmGate ?? NazaSentinelGuard.instance.gate;
    _agenticCodingSurfaceStore = widget.store ?? NazaAgenticWorkspaceStore();
    _agenticCodingSurfaceOperationsStore =
        widget.operationsStore ??
        NazaRemoteOperationsStore(harmGate: _agenticCodingSurfaceHarmGate);
    _agenticCodingSurfaceCollaborationStore =
        widget.collaborationStore ?? NazaCollaborationQueueStore();
    _agenticCodingSurfaceChatRoomStore =
        widget.chatRoomStore ?? NazaIpfsChatRoomStore();
    _agenticCodingSurfaceKuboSettingsStore =
        widget.kuboSettingsStore ?? NazaKuboSettingsStore();
    _agenticCodingSurfaceConfig =
        widget.initialConfig ?? const NazaAgenticWorkspaceConfig();
    if (widget.persistState) {
      unawaited(_agenticCodingSurfaceLoadConfig());
      unawaited(_agenticCodingSurfaceLoadOperations());
      unawaited(_agenticCodingSurfaceLoadCollaboration());
      unawaited(_agenticCodingSurfaceLoadChatRooms());
      unawaited(_agenticCodingSurfaceLoadKuboSettings());
    } else {
      _agenticCodingSurfaceLoading = false;
      _agenticCodingSurfaceStatus = 'Local planning boundary ready';
    }
  }

  Future<void> _agenticCodingSurfaceLoadOperations() async {
    try {
      final loaded = await _agenticCodingSurfaceOperationsStore.load();
      if (!mounted) return;
      setState(() => _agenticCodingSurfaceOperations = loaded);
    } catch (_) {
      // A locked vault must not prevent the visual workbench from opening.
      // The UI will label new requests as ephemeral if persistence fails.
    }
  }

  Future<void> _agenticCodingSurfaceLoadCollaboration() async {
    try {
      final pools = await _agenticCodingSurfaceCollaborationStore.loadPools();
      final active = pools.where(
        (pool) => pool.state == NazaCollaborationPoolState.active,
      );
      final pool = active.isEmpty ? null : active.first;
      final edits = pool == null
          ? const <NazaQueuedEdit>[]
          : await _agenticCodingSurfaceCollaborationStore.loadEdits(pool.id);
      final envelopes = pool == null
          ? const <NazaAgentEnvelope>[]
          : await _agenticCodingSurfaceCollaborationStore.loadEnvelopes(
              pool.id,
            );
      if (!mounted) return;
      setState(() {
        _agenticCodingSurfaceCollaborationPools = pools;
        _agenticCodingSurfaceQueuedEdits = edits;
        _agenticCodingSurfaceAgentEnvelopes = envelopes;
      });
    } catch (_) {
      // A locked vault does not prevent local planning; the panel reports the
      // persistence boundary when a new queue request is staged.
    }
  }

  Future<void> _agenticCodingSurfaceLoadChatRooms() async {
    try {
      final rooms = await _agenticCodingSurfaceChatRoomStore.loadRooms();
      final monitors = <String, NazaChatRoomMonitorSnapshot>{};
      final messages = <String, List<NazaChatMessageEnvelope>>{};
      for (final room in rooms) {
        final monitor = await _agenticCodingSurfaceChatRoomStore.loadMonitor(
          room.id,
        );
        final roomMessages = await _agenticCodingSurfaceChatRoomStore
            .loadMessages(room.id);
        if (monitor != null) monitors[room.id] = monitor;
        messages[room.id] = roomMessages;
      }
      if (!mounted) return;
      setState(() {
        _agenticCodingSurfaceChatRooms = rooms;
        _agenticCodingSurfaceChatMonitors
          ..clear()
          ..addAll(monitors);
        _agenticCodingSurfaceChatMessages
          ..clear()
          ..addAll(messages);
      });
    } catch (_) {
      // The surface remains usable while the encrypted vault is locked.
    }
  }

  Future<void> _agenticCodingSurfaceLoadKuboSettings() async {
    try {
      final settings = await _agenticCodingSurfaceKuboSettingsStore.load();
      if (!mounted) return;
      setState(() => _agenticCodingSurfaceKuboSettings = settings);
    } catch (_) {
      // Disabled defaults remain safe if the vault is unavailable.
    }
  }

  Future<void> _agenticCodingSurfaceAppendRemoteOperation(
    NazaRemoteOperationRequest request,
  ) async {
    final next = <NazaRemoteOperationRequest>[
      ..._agenticCodingSurfaceOperations,
      request,
    ];
    setState(() {
      _agenticCodingSurfaceOperations =
          next.length <= NazaRemoteOperationsStore.maxRequests
          ? List<NazaRemoteOperationRequest>.unmodifiable(next)
          : List<NazaRemoteOperationRequest>.unmodifiable(
              next.sublist(next.length - NazaRemoteOperationsStore.maxRequests),
            );
      _agenticCodingSurfaceError = null;
      _agenticCodingSurfaceStatus =
          '${request.kind.label} request sealed · awaiting approval';
    });
    if (!widget.persistState) return;
    try {
      await _agenticCodingSurfaceOperationsStore.append(request);
    } catch (_) {
      if (!mounted) return;
      setState(
        () => _agenticCodingSurfaceStatus =
            '${request.kind.label} request staged locally · unlock vault to persist',
      );
    }
  }

  @override
  void dispose() {
    _agenticCodingSurfaceTaskController.dispose();
    _agenticCodingSurfaceTaskFocus.dispose();
    super.dispose();
  }

  Future<void> _agenticCodingSurfaceLoadConfig() async {
    try {
      final loaded = await _agenticCodingSurfaceStore.load();
      if (!mounted) return;
      setState(() {
        _agenticCodingSurfaceConfig = loaded;
        _agenticCodingSurfaceLoading = false;
        _agenticCodingSurfaceStatus = 'Encrypted workspace policy restored';
      });
    } catch (_) {
      if (!mounted) return;
      setState(() {
        _agenticCodingSurfaceLoading = false;
        _agenticCodingSurfaceStatus =
            'Ephemeral local policy · unlock vault to persist';
      });
    }
  }

  Future<void> _agenticCodingSurfacePersistConfig() async {
    if (!widget.persistState) return;
    try {
      await _agenticCodingSurfaceStore.save(_agenticCodingSurfaceConfig);
    } catch (_) {
      if (!mounted) return;
      setState(() {
        _agenticCodingSurfaceStatus =
            'Policy changed locally · encrypted vault unavailable';
      });
    }
  }

  void _agenticCodingSurfaceUpdateConfig(NazaAgenticWorkspaceConfig next) {
    setState(() {
      _agenticCodingSurfaceConfig = next;
      _agenticCodingSurfaceResult = null;
      _agenticCodingSurfaceLastPolicy = null;
      _agenticCodingSurfaceError = null;
    });
    unawaited(_agenticCodingSurfacePersistConfig());
  }

  Future<void> _agenticCodingSurfaceChooseRepository() async {
    if (_agenticCodingSurfaceIndexing || _agenticCodingSurfaceRunning) return;
    final selected = await file_selector.getDirectoryPath(
      confirmButtonText: 'Index workspace',
    );
    if (selected == null || selected.trim().isEmpty || !mounted) return;
    setState(() {
      _agenticCodingSurfaceIndexing = true;
      _agenticCodingSurfaceError = null;
      _agenticCodingSurfaceStatus =
          'Building a bounded, secret-filtered evidence snapshot';
    });
    try {
      final context = await widget.collector.collect(
        selected,
        maxFiles: _agenticCodingSurfaceConfig.maxFiles,
        maxBytes: _agenticCodingSurfaceConfig.maxContextBytes,
      );
      if (!mounted) return;
      setState(() {
        _agenticCodingSurfaceRepository = context;
        _agenticCodingSurfaceIndexing = false;
        _agenticCodingSurfaceStatus =
            '${context.files.length} files · ${_agenticCodingSurfaceFormatBytes(context.bytes)} · evidence ${context.fingerprint.substring(0, 10)}';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _agenticCodingSurfaceIndexing = false;
        _agenticCodingSurfaceError = 'Workspace indexing failed: $error';
        _agenticCodingSurfaceStatus = 'Repository evidence unavailable';
      });
    }
  }

  Future<void> _agenticCodingSurfacePickAttachment() async {
    final picker = widget.pickImage;
    if (picker == null || _agenticCodingSurfaceRunning) return;
    try {
      final attachment = await picker();
      if (!mounted || attachment == null) return;
      setState(() {
        _agenticCodingSurfaceAttachment = attachment;
        _agenticCodingSurfaceError = null;
        _agenticCodingSurfaceStatus =
            '${attachment.name} · ${attachment.dimensions} · local vision';
      });
    } catch (error) {
      if (!mounted) return;
      setState(
        () => _agenticCodingSurfaceError = 'Could not attach image: $error',
      );
    }
  }

  Set<NazaAgenticPermission>
  _agenticCodingSurfacePermissionsForRun() => <NazaAgenticPermission>{
    if (_agenticCodingSurfaceConfig.modality == NazaAgenticModality.repository)
      NazaAgenticPermission.inspectRepository,
    if (_agenticCodingSurfaceProposePatch) NazaAgenticPermission.proposePatch,
    if (_agenticCodingSurfaceRunChecks) NazaAgenticPermission.runChecks,
    if (_agenticCodingSurfaceAllowNetwork) NazaAgenticPermission.networkAccess,
    if (_agenticCodingSurfaceConfig.activeNode.kind ==
        NazaExecutionTargetKind.remoteSsh)
      NazaAgenticPermission.remoteExecution,
  };

  Future<void> _agenticCodingSurfaceRun() async {
    if (_agenticCodingSurfaceRunning) return;
    NazaAgenticTaskRequest request;
    try {
      request = NazaAgenticTaskRequest.validated(
        task: _agenticCodingSurfaceTaskController.text,
        modelMode: _agenticCodingSurfaceConfig.modelMode,
        modality: _agenticCodingSurfaceConfig.modality,
        node: _agenticCodingSurfaceConfig.activeNode,
        permissions: _agenticCodingSurfacePermissionsForRun(),
        mutationApproved: _agenticCodingSurfaceMutationApproved,
        networkApproved: _agenticCodingSurfaceNetworkApproved,
        memoryEnabled: _agenticCodingSurfaceConfig.memoryEnabled,
        repository: _agenticCodingSurfaceRepository,
        attachment: _agenticCodingSurfaceAttachment,
      );
    } catch (error) {
      setState(() => _agenticCodingSurfaceError = error.toString());
      _agenticCodingSurfaceTaskFocus.requestFocus();
      return;
    }
    final policy = const NazaAgenticPolicyEngine().evaluate(request);
    if (!policy.canRun) {
      setState(() {
        _agenticCodingSurfaceLastPolicy = policy;
        _agenticCodingSurfaceError = [
          ...policy.blockers,
          ...policy.approvals,
        ].join(' ');
        _agenticCodingSurfaceStatus = policy.requiresApproval
            ? 'Capability approval required'
            : 'Policy gate blocked this run';
      });
      return;
    }
    setState(() {
      _agenticCodingSurfaceRunning = true;
      _agenticCodingSurfaceResult = null;
      _agenticCodingSurfaceLastPolicy = policy;
      _agenticCodingSurfaceError = null;
      // Approval acknowledgements are single-use even though this release is
      // planning-only. A future execution adapter cannot inherit stale grants.
      _agenticCodingSurfaceMutationApproved = false;
      _agenticCodingSurfaceNetworkApproved = false;
      _agenticCodingSurfaceStatus =
          'Context → divergence → synthesis → verification';
    });
    try {
      final result = await widget.runTask(request);
      try {
        await _agenticCodingSurfaceStore.appendReceipt(
          NazaAgenticRunReceipt.fromRun(request, result),
        );
      } catch (_) {
        // The completed response remains useful if encrypted receipt storage
        // is temporarily unavailable. No plaintext prompt is written here.
      }
      if (!mounted) return;
      setState(() {
        _agenticCodingSurfaceRunning = false;
        _agenticCodingSurfaceResult = result;
        _agenticCodingSurfaceStatus = result.weave.reviewRequired
            ? 'Synthesis complete · human review required'
            : 'Synthesis complete · evidence surface convergent';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _agenticCodingSurfaceRunning = false;
        _agenticCodingSurfaceError = 'Agentic synthesis failed: $error';
        _agenticCodingSurfaceStatus = 'Run failed closed';
      });
    }
  }

  Future<void> _agenticCodingSurfaceAddRemoteNode() async {
    final name = TextEditingController(text: 'Secure build node');
    final host = TextEditingController();
    final port = TextEditingController(text: '22');
    final user = TextEditingController();
    final hostKey = TextEditingController(text: 'SHA256:');
    final root = TextEditingController(text: '/workspace');
    final key = TextEditingController();
    var trust = 0.70;
    final submitted = await showDialog<NazaAgenticNodeProfile>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          backgroundColor: _agenticCodingSurfacePanel,
          surfaceTintColor: Colors.transparent,
          title: const Text(
            'Register encrypted SSH node',
            style: TextStyle(
              color: _agenticCodingSurfaceText,
              fontWeight: FontWeight.w800,
            ),
          ),
          content: SizedBox(
            width: 560,
            child: SingleChildScrollView(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Text(
                    'The profile and key are separate authenticated vault records. No connection is attempted while saving.',
                    style: TextStyle(
                      color: _agenticCodingSurfaceSubtext,
                      height: 1.4,
                    ),
                  ),
                  const SizedBox(height: 16),
                  _agenticCodingSurfaceDialogField(name, 'Node title'),
                  const SizedBox(height: 10),
                  Row(
                    children: [
                      Expanded(
                        child: _agenticCodingSurfaceDialogField(
                          host,
                          'Host or IP',
                        ),
                      ),
                      const SizedBox(width: 10),
                      SizedBox(
                        width: 110,
                        child: _agenticCodingSurfaceDialogField(port, 'Port'),
                      ),
                    ],
                  ),
                  const SizedBox(height: 10),
                  _agenticCodingSurfaceDialogField(user, 'SSH username'),
                  const SizedBox(height: 10),
                  _agenticCodingSurfaceDialogField(
                    hostKey,
                    'Pinned SSH host key (SHA256:…)',
                    monospace: true,
                  ),
                  const SizedBox(height: 10),
                  _agenticCodingSurfaceDialogField(
                    root,
                    'Remote workspace root',
                  ),
                  const SizedBox(height: 10),
                  _agenticCodingSurfaceDialogField(
                    key,
                    'OpenSSH / PKCS#8 private key',
                    maxLines: 6,
                    monospace: true,
                  ),
                  const SizedBox(height: 14),
                  Text(
                    'Initial trust weight · ${(trust * 100).round()}%',
                    style: const TextStyle(
                      color: _agenticCodingSurfaceText,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                  Slider(
                    value: trust,
                    min: 0.2,
                    max: 1,
                    divisions: 8,
                    activeColor: _agenticCodingSurfaceCyan,
                    onChanged: (value) => setDialogState(() => trust = value),
                  ),
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            FilledButton.icon(
              style: FilledButton.styleFrom(
                backgroundColor: _agenticCodingSurfaceViolet,
              ),
              onPressed: () {
                try {
                  final id = 'remote-${DateTime.now().microsecondsSinceEpoch}';
                  final profile = NazaAgenticNodeProfile.createRemote(
                    id: id,
                    name: name.text,
                    host: host.text,
                    port: int.tryParse(port.text) ?? 22,
                    username: user.text,
                    hostKeySha256: hostKey.text,
                    workspaceRoot: root.text,
                    trustWeight: trust,
                    hasCredential: key.text.trim().isNotEmpty,
                  );
                  Navigator.pop(dialogContext, profile);
                } catch (error) {
                  ScaffoldMessenger.of(
                    this.context,
                  ).showSnackBar(SnackBar(content: Text(error.toString())));
                }
              },
              icon: const Icon(Icons.enhanced_encryption_rounded),
              label: const Text('Seal profile'),
            ),
          ],
        ),
      ),
    );
    try {
      if (submitted != null) {
        if (key.text.trim().isNotEmpty) {
          await _agenticCodingSurfaceStore.saveSshPrivateKey(
            nodeId: submitted.id,
            privateKey: key.text,
          );
        }
        if (!mounted) return;
        final next = _agenticCodingSurfaceConfig.copyWith(
          nodes: <NazaAgenticNodeProfile>[
            ..._agenticCodingSurfaceConfig.nodes,
            submitted,
          ],
          activeNodeId: submitted.id,
        );
        _agenticCodingSurfaceUpdateConfig(next);
        setState(
          () => _agenticCodingSurfaceStatus =
              'Remote node sealed in encrypted storage',
        );
      }
    } catch (error) {
      if (mounted) {
        setState(
          () =>
              _agenticCodingSurfaceError = 'Could not seal remote node: $error',
        );
      }
    } finally {
      name.dispose();
      host.dispose();
      port.dispose();
      user.dispose();
      hostKey.dispose();
      root.dispose();
      key.dispose();
    }
  }

