  Future<void> _agenticCodingSurfaceRemoveRemoteNode(
    NazaAgenticNodeProfile node,
  ) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: _agenticCodingSurfacePanel,
        title: const Text(
          'Remove remote node?',
          style: TextStyle(color: _agenticCodingSurfaceText),
        ),
        content: Text(
          'This removes ${node.name} and its encrypted SSH-key record. This cannot be undone.',
          style: const TextStyle(color: _agenticCodingSurfaceSubtext),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Keep node'),
          ),
          FilledButton(
            style: FilledButton.styleFrom(
              backgroundColor: _agenticCodingSurfaceRose,
            ),
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Remove'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    try {
      await _agenticCodingSurfaceRequestNodeAction(node, 'delete');
      if (node.hasCredential)
        await _agenticCodingSurfaceStore.deleteSshPrivateKey(node.id);
      if (!mounted) return;
      _agenticCodingSurfaceUpdateConfig(
        _agenticCodingSurfaceConfig.copyWith(
          nodes: _agenticCodingSurfaceConfig.nodes.where(
            (item) => item.id != node.id,
          ),
          activeNodeId: NazaAgenticNodeProfile.localDefault.id,
        ),
      );
    } catch (error) {
      if (mounted)
        setState(
          () => _agenticCodingSurfaceError = 'Could not remove node: $error',
        );
    }
  }

  Future<void> _agenticCodingSurfaceRequestNodeAction(
    NazaAgenticNodeProfile node,
    String action,
  ) async {
    if (_agenticCodingSurfaceRunning) return;
    final kind = switch (action) {
      'start' => NazaRemoteOperationKind.nodeStart,
      'stop' => NazaRemoteOperationKind.nodeStop,
      'delete' => NazaRemoteOperationKind.nodeDelete,
      _ => null,
    };
    if (kind == null) return;
    final request = NazaRemoteOperationRequest.nodeAction(
      id: 'op-${DateTime.now().microsecondsSinceEpoch}',
      nodeId: node.id,
      kind: kind,
      label: node.name,
    );
    setState(() {
      _agenticCodingSurfaceNodeStates[node.id] =
          '$action requested · approval boundary';
    });
    await _agenticCodingSurfaceAppendRemoteOperation(request);
  }

