  Future<void> _agenticCodingSurfaceCancelRemoteOperation(
    NazaRemoteOperationRequest operation,
  ) async {
    final cancelled = operation.copyWith(
      state: NazaRemoteOperationState.cancelled,
    );
    setState(() {
      _agenticCodingSurfaceOperations =
          List<NazaRemoteOperationRequest>.unmodifiable(
            _agenticCodingSurfaceOperations.map(
              (item) => item.id == operation.id ? cancelled : item,
            ),
          );
      _agenticCodingSurfaceStatus =
          '${operation.kind.label} request cancelled locally';
    });
    if (widget.persistState) {
      try {
        await _agenticCodingSurfaceOperationsStore.update(cancelled);
      } catch (_) {
        if (mounted) {
          setState(
            () => _agenticCodingSurfaceStatus =
                'Cancellation staged locally · vault unavailable',
          );
        }
      }
    }
  }

  Future<void> _agenticCodingSurfaceApproveRemoteOperation(
    NazaRemoteOperationRequest operation,
  ) async {
    final approved = operation.copyWith(
      state: NazaRemoteOperationState.approved,
    );
    try {
      if (widget.persistState) {
        await _agenticCodingSurfaceOperationsStore.update(approved);
      } else {
        await _agenticCodingSurfaceHarmGate.requireAllowed(
          operation.kind.sentinelCommandName,
        );
      }
      if (!mounted) return;
      setState(() {
        _agenticCodingSurfaceOperations =
            List<NazaRemoteOperationRequest>.unmodifiable(
              _agenticCodingSurfaceOperations.map(
                (item) => item.id == operation.id ? approved : item,
              ),
            );
        _agenticCodingSurfaceError = null;
        _agenticCodingSurfaceStatus =
            '${operation.kind.label} passed harm filter · trusted adapter still required';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _agenticCodingSurfaceError = error is NazaHarmDeniedException
            ? '${operation.kind.label} denied by the core safety sentinel (${error.decision.risk.label}).'
            : '${operation.kind.label} approval failed closed: $error';
        _agenticCodingSurfaceStatus =
            'Remote operation remains awaiting approval';
      });
    }
  }

  NazaCollaborationPool? get _agenticCodingSurfaceActiveCollaborationPool {
    for (final pool in _agenticCodingSurfaceCollaborationPools) {
      if (pool.state == NazaCollaborationPoolState.active) return pool;
    }
    return null;
  }

  Future<void> _agenticCodingSurfaceCreateCollaborationPool() async {
    final name = TextEditingController(text: 'MMO coding pool');
    final fingerprint = TextEditingController(
      text: _agenticCodingSurfaceRepository?.fingerprint ?? '',
    );
    final peers = TextEditingController(text: 'local-only');
