    final values = await showDialog<(String, String, String, int)?>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: _agenticCodingSurfacePanel,
        title: const Text(
          'Create cooperative edit pool',
          style: TextStyle(
            color: _agenticCodingSurfaceText,
            fontWeight: FontWeight.w800,
          ),
        ),
        content: SizedBox(
          width: 560,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              _agenticCodingSurfaceDialogField(name, 'Pool name'),
              const SizedBox(height: 10),
              _agenticCodingSurfaceDialogField(
                fingerprint,
                'Workspace base fingerprint (sha256:…)',
                monospace: true,
              ),
              const SizedBox(height: 10),
              _agenticCodingSurfaceDialogField(
                peers,
                'IPFS / node peer group label',
              ),
              const SizedBox(height: 10),
              _agenticCodingSurfaceDialogField(
                concurrency,
                'Max concurrent edit claims',
              ),
              const SizedBox(height: 10),
              const Text(
                'Agents claim relative file sectors against this immutable base. Only encrypted CID references and signed-receipt references move between nodes.',
                style: TextStyle(
                  color: _agenticCodingSurfaceSubtext,
                  height: 1.4,
                ),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, (
              name.text,
              fingerprint.text,
              peers.text,
              int.tryParse(concurrency.text) ?? 0,
            )),
            child: const Text('Seal pool'),
          ),
        ],
      ),
    );
    name.dispose();
    fingerprint.dispose();
    peers.dispose();
    concurrency.dispose();
    if (values == null || !mounted) return;
    try {
      final pool = NazaCollaborationPool(
        id: 'pool-${DateTime.now().microsecondsSinceEpoch}',
        name: values.$1,
        workspaceFingerprint: values.$2,
        peerGroup: values.$3,
        maxConcurrentEdits: values.$4,
        createdAt: DateTime.now().toUtc(),
      );
      final errors = pool.validate();
      if (errors.isNotEmpty) throw FormatException(errors.join(' '));
      if (widget.persistState)
        await _agenticCodingSurfaceCollaborationStore.savePool(pool);
      setState(() {
        _agenticCodingSurfaceCollaborationPools = <NazaCollaborationPool>[
          ..._agenticCodingSurfaceCollaborationPools,
          pool,
        ];
        _agenticCodingSurfaceStatus =
            'Cooperative pool sealed · ${pool.bondSuite}';
      });
    } catch (error) {
      if (mounted)
        setState(
          () => _agenticCodingSurfaceError = 'Could not seal edit pool: $error',
        );
    }
  }

