        dependencies: values.$5
            .split(',')
            .map((value) => value.trim())
            .where((value) => value.isNotEmpty)
            .toList(growable: false),
        createdAt: DateTime.now().toUtc(),
      );
      final errors = edit.validate();
      if (errors.isNotEmpty) throw FormatException(errors.join(' '));
      if (widget.persistState)
        await _agenticCodingSurfaceCollaborationStore.enqueueEdit(edit);
      setState(() {
        _agenticCodingSurfaceQueuedEdits = <NazaQueuedEdit>[
          ..._agenticCodingSurfaceQueuedEdits,
          edit,
        ];
        _agenticCodingSurfaceStatus =
            'Edit queued · waiting for an agent claim';
      });
    } catch (error) {
      if (mounted)
        setState(
          () => _agenticCodingSurfaceError = 'Could not queue edit: $error',
        );
    }
  }

  Future<void> _agenticCodingSurfacePostAgentEnvelope() async {
    final pool = _agenticCodingSurfaceActiveCollaborationPool;
    if (pool == null) {
      setState(
        () => _agenticCodingSurfaceStatus =
            'Create an active cooperative pool first',
      );
      return;
    }
    final cid = TextEditingController();
    final sender = TextEditingController();
    final signature = TextEditingController();
    final recipient = TextEditingController();
    final editId = TextEditingController();
    final values = await showDialog<(String, String, String, String, String)?>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: _agenticCodingSurfacePanel,
        title: const Text(
          'Queue encrypted agent handoff',
          style: TextStyle(
            color: _agenticCodingSurfaceText,
            fontWeight: FontWeight.w800,
          ),
        ),
        content: SizedBox(
          width: 560,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              _agenticCodingSurfaceDialogField(
                cid,
                'Ciphertext CID (message body never stored here)',
              ),
              const SizedBox(height: 10),
              _agenticCodingSurfaceDialogField(
                sender,
                'Sender bond public-key ID',
              ),
              const SizedBox(height: 10),
              _agenticCodingSurfaceDialogField(
                signature,
                'Signature public-key ID',
              ),
              const SizedBox(height: 10),
              _agenticCodingSurfaceDialogField(
                recipient,
                'Recipient bond public-key ID (optional)',
              ),
              const SizedBox(height: 10),
              _agenticCodingSurfaceDialogField(editId, 'Edit ID (optional)'),
              const SizedBox(height: 10),
              const Text(
                'The node adapter must perform ML-KEM/X25519 envelope encryption and ML-DSA receipt verification. This queue only coordinates references.',
                style: TextStyle(
                  color: _agenticCodingSurfaceSubtext,
                  height: 1.4,
                ),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, (
              cid.text,
              sender.text,
              signature.text,
              recipient.text,
              editId.text,
            )),
            child: const Text('Queue handoff'),
          ),
        ],
      ),
    );
    cid.dispose();
    sender.dispose();
    signature.dispose();
    recipient.dispose();
    editId.dispose();
    if (values == null || !mounted) return;
    try {
      final envelope = NazaAgentEnvelope(
        id: 'msg-${DateTime.now().microsecondsSinceEpoch}',
        poolId: pool.id,
        kind: NazaAgentEnvelopeKind.handoff,
        senderBondKeyId: values.$2,
        ciphertextCid: values.$1,
        signatureKeyId: values.$3,
        recipientBondKeyId: values.$4.trim().isEmpty ? null : values.$4,
        editId: values.$5.trim().isEmpty ? null : values.$5,
        sequence: _agenticCodingSurfaceAgentEnvelopes.length,
        createdAt: DateTime.now().toUtc(),
      );
      final errors = envelope.validate();
      if (errors.isNotEmpty) throw FormatException(errors.join(' '));
      if (widget.persistState)
        await _agenticCodingSurfaceCollaborationStore.postEnvelope(envelope);
      setState(() {
        _agenticCodingSurfaceAgentEnvelopes = <NazaAgentEnvelope>[
          ..._agenticCodingSurfaceAgentEnvelopes,
          envelope,
        ];
        _agenticCodingSurfaceStatus =
            'Encrypted handoff reference queued · ${pool.peerGroup}';
      });
    } catch (error) {
      if (mounted)
        setState(
          () => _agenticCodingSurfaceError = 'Could not queue handoff: $error',
        );
    }
  }

  NazaChatRoom? get _agenticCodingSurfaceActiveChatRoom {
    for (final room in _agenticCodingSurfaceChatRooms) {
      if (room.state == NazaChatRoomState.active) return room;
    }
    return null;
  }

  Future<void> _agenticCodingSurfaceCreateChatRoom() async {
    final name = TextEditingController(text: 'Encrypted human room');
    final topic = TextEditingController(text: 'naza-chat/v1/human-room');
    final peers = TextEditingController(text: 'local-only');
    final relay = TextEditingController();
    var kind = NazaChatRoomKind.human;
    var publicDiscovery = false;
    var publicExposureApproved = false;
    final room = await showDialog<NazaChatRoom?>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          backgroundColor: _agenticCodingSurfacePanel,
          title: const Text(
            'Create encrypted IPFS chatroom',
            style: TextStyle(
              color: _agenticCodingSurfaceText,
              fontWeight: FontWeight.w800,
            ),
          ),
          content: SizedBox(
            width: 580,
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  SegmentedButton<NazaChatRoomKind>(
                    segments: const [
                      ButtonSegment(
                        value: NazaChatRoomKind.human,
                        label: Text('Human room'),
                        icon: Icon(Icons.people_alt_rounded),
                      ),
                      ButtonSegment(
                        value: NazaChatRoomKind.agent,
                        label: Text('Agent room'),
                        icon: Icon(Icons.smart_toy_rounded),
                      ),
                    ],
                    selected: <NazaChatRoomKind>{kind},
                    onSelectionChanged: (value) =>
                        setDialogState(() => kind = value.first),
                  ),
                  const SizedBox(height: 12),
                  _agenticCodingSurfaceDialogField(name, 'Room name'),
                  const SizedBox(height: 10),
                  _agenticCodingSurfaceDialogField(
                    topic,
                    'IPFS PubSub topic',
                    monospace: true,
                  ),
                  const SizedBox(height: 10),
                  _agenticCodingSurfaceDialogField(peers, 'Trusted peer group'),
                  const SizedBox(height: 10),
                  _agenticCodingSurfaceDialogField(
                    relay,
                    'DigitalOcean relay node ID (optional)',
                  ),
                  SwitchListTile.adaptive(
                    contentPadding: EdgeInsets.zero,
                    title: const Text(
                      'Publicly discoverable room',
                      style: TextStyle(color: _agenticCodingSurfaceText),
                    ),
                    subtitle: const Text(
                      'Off by default; private rooms still use encrypted IPFS envelopes.',
                      style: TextStyle(
                        color: _agenticCodingSurfaceSubtext,
                        fontSize: 11,
                      ),
                    ),
                    value: publicDiscovery,
                    activeTrackColor: _agenticCodingSurfaceRose,
                    onChanged: (value) => setDialogState(() {
                      publicDiscovery = value;
                      if (!value) publicExposureApproved = false;
                    }),
                  ),
                  if (publicDiscovery)
                    CheckboxListTile(
                      contentPadding: EdgeInsets.zero,
                      title: const Text(
                        'I approve public room discovery',
                        style: TextStyle(
                          color: _agenticCodingSurfaceText,
                          fontSize: 13,
                        ),
                      ),
                      value: publicExposureApproved,
                      activeColor: _agenticCodingSurfaceRose,
                      onChanged: (value) => setDialogState(
                        () => publicExposureApproved = value == true,
                      ),
                    ),
                  const Text(
                    'Kubo PubSub is transport only: messages are encrypted before publishing, and the Kubo RPC port must remain private to the adapter. IPFS PubSub is not treated as durable history; encrypted CIDs provide replayable history.',
                    style: TextStyle(
                      color: _agenticCodingSurfaceSubtext,
                      height: 1.4,
                    ),
                  ),
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () {
                try {
                  final next = NazaChatRoom(
                    id: 'room-${DateTime.now().microsecondsSinceEpoch}',
                    name: name.text,
                    kind: kind,
                    topic: topic.text,
                    peerGroup: peers.text,
                    relayNodeId: relay.text.trim().isEmpty ? null : relay.text,
                    publicDiscovery: publicDiscovery,
                    publicExposureApproved: publicExposureApproved,
                    createdAt: DateTime.now().toUtc(),
                  );
                  final errors = next.validate();
                  if (errors.isNotEmpty)
                    throw FormatException(errors.join(' '));
                  Navigator.pop(dialogContext, next);
                } catch (error) {
                  ScaffoldMessenger.of(
                    context,
                  ).showSnackBar(SnackBar(content: Text(error.toString())));
                }
              },
              child: const Text('Seal chatroom'),
            ),
          ],
        ),
      ),
    );
    name.dispose();
    topic.dispose();
    peers.dispose();
    relay.dispose();
    if (room == null || !mounted) return;
    try {
      final monitor = NazaChatRoomMonitorSnapshot(
        roomId: room.id,
        linkState: NazaIpfsChatLinkState.offline,
        observedAt: DateTime.now().toUtc(),
        lastError: 'No IPFS adapter attached; no network probe performed.',
      );
      if (widget.persistState) {
        await _agenticCodingSurfaceChatRoomStore.saveRoom(room);
        await _agenticCodingSurfaceChatRoomStore.saveMonitor(monitor);
      }
      setState(() {
        _agenticCodingSurfaceChatRooms = <NazaChatRoom>[
          ..._agenticCodingSurfaceChatRooms,
          room,
        ];
        _agenticCodingSurfaceChatMonitors[room.id] = monitor;
        _agenticCodingSurfaceChatMessages[room.id] =
            const <NazaChatMessageEnvelope>[];
        _agenticCodingSurfaceStatus =
            '${room.kind.label} sealed · IPFS adapter pending';
      });
    } catch (error) {
      if (mounted)
        setState(
          () => _agenticCodingSurfaceError = 'Could not save chatroom: $error',
        );
    }
  }

