    cid.dispose();
    sender.dispose();
    aad.dispose();
    signature.dispose();
    replyTo.dispose();
    attachments.dispose();
    if (values == null || !mounted) return;
    try {
      final envelope = NazaChatMessageEnvelope(
        id: 'chat-${DateTime.now().microsecondsSinceEpoch}',
        roomId: room.id,
        senderId: values.$2,
        senderKind: room.kind,
        ciphertextCid: values.$1,
        aadDigest: values.$3,
        signatureKeyId: values.$4,
        sequence: _agenticCodingSurfaceChatMessages[room.id]?.length ?? 0,
        replyTo: values.$5.trim().isEmpty ? null : values.$5,
        attachmentCids: values.$6
            .split(',')
            .map((value) => value.trim())
            .where((value) => value.isNotEmpty)
            .toList(growable: false),
        createdAt: DateTime.now().toUtc(),
      );
      final errors = envelope.validate();
      if (errors.isNotEmpty) throw FormatException(errors.join(' '));
      if (widget.persistState)
        await _agenticCodingSurfaceChatRoomStore.appendMessage(envelope);
      setState(() {
        final current =
            _agenticCodingSurfaceChatMessages[room.id] ??
            const <NazaChatMessageEnvelope>[];
        _agenticCodingSurfaceChatMessages[room.id] = <NazaChatMessageEnvelope>[
          ...current,
          envelope,
        ];
        _agenticCodingSurfaceStatus =
            '${room.kind.label} envelope queued · ciphertext only';
      });
    } catch (error) {
      if (mounted)
        setState(
          () => _agenticCodingSurfaceError =
              'Could not queue chat envelope: $error',
        );
    }
  }

  Future<void> _agenticCodingSurfaceRecordChatMonitorBoundary(
    NazaChatRoom room,
  ) async {
    final monitor = NazaChatRoomMonitorSnapshot(
      roomId: room.id,
      linkState: NazaIpfsChatLinkState.offline,
      connectedPeers: 0,
      subscribed: false,
      backlog: _agenticCodingSurfaceChatMessages[room.id]?.length ?? 0,
      relayNodeId: room.relayNodeId,
      observedAt: DateTime.now().toUtc(),
      lastError: 'Adapter probe not installed; no Kubo RPC call was made.',
    );
    if (widget.persistState) {
      try {
        await _agenticCodingSurfaceChatRoomStore.saveMonitor(monitor);
      } catch (_) {}
    }
    if (!mounted) return;
    setState(() {
      _agenticCodingSurfaceChatMonitors[room.id] = monitor;
      _agenticCodingSurfaceStatus = '${room.name}: monitor boundary recorded';
    });
  }

