  Future<void> _agenticCodingSurfaceSetKuboEnabled(bool enabled) async {
    final next = _agenticCodingSurfaceKuboSettings.copyWith(enabled: enabled);
    final errors = next.validate();
    if (errors.isNotEmpty) {
      setState(() => _agenticCodingSurfaceError = errors.join(' '));
      return;
    }
    if (widget.persistState) {
      try {
        await _agenticCodingSurfaceKuboSettingsStore.save(next);
      } catch (error) {
        if (mounted)
          setState(
            () => _agenticCodingSurfaceError =
                'Could not persist Kubo setting: $error',
          );
        return;
      }
    }
    if (!mounted) return;
    setState(() {
      _agenticCodingSurfaceKuboSettings = next;
      _agenticCodingSurfaceStatus = enabled
          ? 'Kubo backend enabled · client starts only on explicit room dispatch'
          : 'Kubo backend disabled · no client or socket loaded';
    });
  }

