    } catch (error) {
      if (mounted)
        setState(
          () => _agenticCodingSurfaceError =
              'Could not save Kubo settings: $error',
        );
    }
  }

  void _agenticCodingSurfaceValidNodeReferenceForDialog(String value) {
    if (!RegExp(r'^[A-Za-z0-9][A-Za-z0-9._-]{1,95}$').hasMatch(value.trim())) {
      throw const FormatException('Enter a valid droplet or node ID.');
    }
  }

  void _agenticCodingSurfaceReplaceNode(
    NazaAgenticNodeProfile replacement, {
    bool select = false,
  }) {
    _agenticCodingSurfaceUpdateConfig(
      _agenticCodingSurfaceConfig.copyWith(
        nodes: <NazaAgenticNodeProfile>[
          for (final node in _agenticCodingSurfaceConfig.nodes)
            if (node.id == replacement.id) replacement else node,
        ],
        activeNodeId: select
            ? replacement.id
            : _agenticCodingSurfaceConfig.activeNodeId,
      ),
    );
  }

  Widget _agenticCodingSurfaceDialogField(
    TextEditingController controller,
    String label, {
    int maxLines = 1,
    bool monospace = false,
  }) {
    return TextField(
      controller: controller,
      maxLines: maxLines,
      autocorrect: false,
      enableSuggestions: false,
      style: TextStyle(
        color: _agenticCodingSurfaceText,
        fontFamily: monospace ? 'JetBrainsMono' : null,
        fontSize: monospace ? 12 : null,
      ),
      decoration: InputDecoration(
        labelText: label,
        labelStyle: const TextStyle(color: _agenticCodingSurfaceSubtext),
        filled: true,
        fillColor: _agenticCodingSurfaceInk,
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(12),
          borderSide: const BorderSide(color: _agenticCodingSurfaceBorder),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(12),
          borderSide: const BorderSide(color: _agenticCodingSurfaceCyan),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return ColoredBox(
      color: _agenticCodingSurfaceInk,
      child: Stack(
        children: [
          const Positioned.fill(child: _AgenticCodingSurfaceFoundryBackdrop()),
          SafeArea(
            top: false,
            child: ListView(
              key: const ValueKey<String>('agentic-code-foundry'),
              padding: const EdgeInsets.fromLTRB(18, 18, 18, 56),
              children: [
                _agenticCodingSurfaceBuildHero(),
                const SizedBox(height: 16),
                _agenticCodingSurfaceBuildPipeline(),
                const SizedBox(height: 16),
                LayoutBuilder(
                  builder: (context, constraints) {
                    final wide = constraints.maxWidth >= 980;
                    final controls = Column(
                      children: [
                        _agenticCodingSurfaceBuildModelFabric(),
                        const SizedBox(height: 14),
                        _agenticCodingSurfaceBuildTargetFabric(),
                        const SizedBox(height: 14),
                        _agenticCodingSurfaceBuildContextFabric(),
                      ],
                    );
                    final composer = Column(
                      children: [
                        _agenticCodingSurfaceBuildComposer(),
                        const SizedBox(height: 14),
                        _agenticCodingSurfaceBuildCapabilityGate(),
                      ],
                    );
                    if (!wide) {
                      return Column(
                        children: [
                          controls,
                          const SizedBox(height: 14),
                          composer,
                        ],
                      );
                    }
                    return Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Expanded(flex: 10, child: controls),
                        const SizedBox(width: 14),
                        Expanded(flex: 11, child: composer),
                      ],
                    );
                  },
                ),
                if (_agenticCodingSurfaceError != null) ...[
                  const SizedBox(height: 14),
                  _AgenticCodingSurfaceNoticeCard(
                    icon: Icons.gpp_bad_rounded,
                    color: _agenticCodingSurfaceRose,
                    title: 'Policy / runtime notice',
                    message: _agenticCodingSurfaceError!,
                    onDismiss: () =>
                        setState(() => _agenticCodingSurfaceError = null),
                  ),
                ],
                if (_agenticCodingSurfaceLastPolicy?.warnings.isNotEmpty ==
                    true) ...[
                  const SizedBox(height: 14),
                  _AgenticCodingSurfaceNoticeCard(
                    icon: Icons.science_outlined,
                    color: _agenticCodingSurfaceAmber,
                    title: 'Interpretation boundary',
                    message: _agenticCodingSurfaceLastPolicy!.warnings.join(
                      ' ',
                    ),
                  ),
                ],
                if (_agenticCodingSurfaceResult != null) ...[
                  const SizedBox(height: 18),
                  _agenticCodingSurfaceBuildResult(
                    _agenticCodingSurfaceResult!,
                  ),
                  const SizedBox(height: 18),
                  const NazaCodeWorkbench(),
                ],
                const SizedBox(height: 18),
                _agenticCodingSurfaceBuildRemoteOperations(),
                const SizedBox(height: 18),
                _agenticCodingSurfaceBuildCollaborationQueues(),
                const SizedBox(height: 18),
                _agenticCodingSurfaceBuildIpfsChatrooms(),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _agenticCodingSurfaceBuildHero() {
    return Container(
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: _agenticCodingSurfacePanel.withValues(alpha: 0.94),
        borderRadius: BorderRadius.circular(24),
        border: Border.all(
          color: _agenticCodingSurfaceViolet.withValues(alpha: 0.48),
        ),
      ),
      child: LayoutBuilder(
        builder: (context, constraints) {
          final compact = constraints.maxWidth < 700;
          final title = Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const _AgenticCodingSurfaceMicroLabel(
                'EXECUTION INTELLIGENCE / CODE FOUNDRY',
              ),
              const SizedBox(height: 8),
              Text(
                'Agentic Code Foundry',
                style: TextStyle(
                  color: _agenticCodingSurfaceText,
                  fontSize: compact ? 29 : 38,
                  height: 1,
                  letterSpacing: -1.2,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 10),
              const Text(
                'A visual, local-first coding control plane for evidence, model assemblies, encrypted memory, and approval-gated execution targets.',
                style: TextStyle(
                  color: _agenticCodingSurfaceSubtext,
                  height: 1.45,
                  fontSize: 14,
                ),
              ),
            ],
          );
          final badges = Wrap(
            spacing: 8,
            runSpacing: 8,
            alignment: WrapAlignment.end,
            children: const [
              _AgenticCodingSurfaceStatusBadge(
                'LOCAL GEMMA DEFAULT',
                _agenticCodingSurfaceMint,
              ),
              _AgenticCodingSurfaceStatusBadge(
                'AES-GCM VAULT',
                _agenticCodingSurfaceCyan,
              ),
              _AgenticCodingSurfaceStatusBadge(
                'ML-KEM-1024 RECOVERY',
                _agenticCodingSurfaceViolet,
              ),
              _AgenticCodingSurfaceStatusBadge(
                'HUMAN APPROVAL',
                _agenticCodingSurfaceAmber,
              ),
            ],
          );
          if (compact) {
            return Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [title, const SizedBox(height: 16), badges],
            );
          }
          return Row(
            children: [
              Expanded(flex: 3, child: title),
              const SizedBox(width: 20),
              Expanded(flex: 2, child: badges),
            ],
          );
        },
      ),
    );
  }

  Widget _agenticCodingSurfaceBuildPipeline() {
    const stages = <(IconData, String, String, Color)>[
      (Icons.radar_rounded, '01', 'CONTEXT', _agenticCodingSurfaceCyan),
      (Icons.call_split_rounded, '02', 'DIVERGE', _agenticCodingSurfaceViolet),
      (Icons.balance_rounded, '03', 'WEIGH', _agenticCodingSurfaceAmber),
      (Icons.merge_type_rounded, '04', 'SYNTHESIZE', _agenticCodingSurfaceMint),
      (Icons.verified_rounded, '05', 'VERIFY', _agenticCodingSurfaceRose),
    ];
    return _AgenticCodingSurfaceFoundryCard(
      child: LayoutBuilder(
        builder: (context, constraints) => Wrap(
          spacing: 8,
          runSpacing: 8,
          children: stages
              .map(
                (stage) => SizedBox(
                  width: math.max(142, (constraints.maxWidth - 32) / 5),
                  child: _AgenticCodingSurfacePipelineStage(
                    icon: stage.$1,
                    index: stage.$2,
                    label: stage.$3,
                    color: stage.$4,
                    active: _agenticCodingSurfaceRunning || stage.$2 == '01',
                  ),
                ),
              )
              .toList(growable: false),
        ),
      ),
    );
  }

  Widget _agenticCodingSurfaceBuildModelFabric() {
    return _AgenticCodingSurfaceFoundrySection(
      icon: Icons.hub_rounded,
      title: 'Model assembly fabric',
      subtitle: 'Choose one reasoning topology for this coding run.',
      trailing: _agenticCodingSurfaceLoading
          ? const SizedBox.square(
              dimension: 18,
              child: CircularProgressIndicator(
                strokeWidth: 2,
                color: _agenticCodingSurfaceCyan,
              ),
            )
          : null,
      child: Column(
        children: [
          for (final mode in NazaAgenticModelMode.values)
            _AgenticCodingSurfaceSelectionTile(
              title: mode.label,
              subtitle: mode.description,
              selected: _agenticCodingSurfaceConfig.modelMode == mode,
              color: switch (mode) {
                NazaAgenticModelMode.localGemma => _agenticCodingSurfaceMint,
                NazaAgenticModelMode.routedProvider =>
                  _agenticCodingSurfaceCyan,
                NazaAgenticModelMode.shardedFabric =>
                  _agenticCodingSurfaceViolet,
              },
              onTap: _agenticCodingSurfaceRunning
                  ? null
                  : () => _agenticCodingSurfaceUpdateConfig(
                      _agenticCodingSurfaceConfig.copyWith(modelMode: mode),
                    ),
            ),
        ],
      ),
    );
  }

  Widget _agenticCodingSurfaceBuildTargetFabric() {
    return _AgenticCodingSurfaceFoundrySection(
      icon: Icons.dns_rounded,
      title: 'Execution envelope lattice',
      subtitle:
          'Profiles describe boundaries. No shell, Docker, or SSH action runs implicitly.',
      trailing: IconButton.filledTonal(
        key: const ValueKey<String>('add-remote-node'),
        tooltip: 'Add encrypted SSH node',
        onPressed: _agenticCodingSurfaceRunning
            ? null
            : _agenticCodingSurfaceAddRemoteNode,
        icon: const Icon(Icons.add_link_rounded),
      ),
      child: Column(
        children: [
          Align(
            alignment: Alignment.centerRight,
            child: OutlinedButton.icon(
              onPressed: _agenticCodingSurfaceRunning
                  ? null
                  : _agenticCodingSurfaceRequestEnvironment,
              icon: const Icon(Icons.rocket_launch_rounded, size: 17),
              label: const Text('Request environment'),
            ),
          ),
          for (final node in _agenticCodingSurfaceConfig.nodes)
            _AgenticCodingSurfaceNodeTile(
              node: node,
              selected: _agenticCodingSurfaceConfig.activeNodeId == node.id,
              onSelect: node.enabled && !_agenticCodingSurfaceRunning
                  ? () => _agenticCodingSurfaceUpdateConfig(
                      _agenticCodingSurfaceConfig.copyWith(
                        activeNodeId: node.id,
                      ),
                    )
                  : null,
              onConfigure: node.kind == NazaExecutionTargetKind.ociContainer
                  ? () => _agenticCodingSurfaceConfigureContainer(node)
                  : null,
              onRemove: node.kind == NazaExecutionTargetKind.remoteSsh
                  ? () => _agenticCodingSurfaceRemoveRemoteNode(node)
                  : null,
              state: _agenticCodingSurfaceNodeStates[node.id],
              onStart: () =>
                  _agenticCodingSurfaceRequestNodeAction(node, 'start'),
              onStop: () =>
                  _agenticCodingSurfaceRequestNodeAction(node, 'stop'),
            ),
        ],
      ),
    );
  }

  Widget _agenticCodingSurfaceBuildContextFabric() {
    return _AgenticCodingSurfaceFoundrySection(
      icon: Icons.layers_rounded,
      title: 'Multimodal context fabric',
      subtitle: 'Only explicitly attached evidence crosses into the model run.',
      child: Column(
        children: [
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              for (final modality in NazaAgenticModality.values)
                ChoiceChip(
                  label: Text(modality.label),
                  selected: _agenticCodingSurfaceConfig.modality == modality,
                  selectedColor: _agenticCodingSurfaceCyan.withValues(
                    alpha: 0.22,
                  ),
                  backgroundColor: _agenticCodingSurfaceInk,
                  side: BorderSide(
                    color: _agenticCodingSurfaceConfig.modality == modality
                        ? _agenticCodingSurfaceCyan
                        : _agenticCodingSurfaceBorder,
                  ),
                  labelStyle: TextStyle(
                    color: _agenticCodingSurfaceConfig.modality == modality
                        ? _agenticCodingSurfaceText
                        : _agenticCodingSurfaceSubtext,
                    fontWeight: FontWeight.w700,
                  ),
                  onSelected: _agenticCodingSurfaceRunning
                      ? null
                      : (_) => _agenticCodingSurfaceUpdateConfig(
                          _agenticCodingSurfaceConfig.copyWith(
                            modality: modality,
                          ),
                        ),
                ),
            ],
          ),
          const SizedBox(height: 12),
          if (_agenticCodingSurfaceConfig.modality ==
              NazaAgenticModality.repository)
            _AgenticCodingSurfaceEvidenceAction(
              icon: Icons.folder_open_rounded,
              color: _agenticCodingSurfaceCyan,
              title: _agenticCodingSurfaceRepository == null
                  ? 'Select a repository'
                  : _agenticCodingSurfaceBasename(
                      _agenticCodingSurfaceRepository!.root,
                    ),
              subtitle: _agenticCodingSurfaceRepository == null
                  ? 'Read-only · no symlinks · key/database filters · bounded bytes'
                  : '${_agenticCodingSurfaceRepository!.files.length} files · ${_agenticCodingSurfaceFormatBytes(_agenticCodingSurfaceRepository!.bytes)} · ${_agenticCodingSurfaceRepository!.excludedEntries} excluded${_agenticCodingSurfaceRepository!.truncated ? ' · bounded' : ''}',
              actionLabel: _agenticCodingSurfaceIndexing ? 'INDEXING' : 'INDEX',
              busy: _agenticCodingSurfaceIndexing,
              onTap:
                  _agenticCodingSurfaceIndexing || _agenticCodingSurfaceRunning
                  ? null
                  : _agenticCodingSurfaceChooseRepository,
            )
          else if (_agenticCodingSurfaceConfig.modality ==
              NazaAgenticModality.vision)
            _AgenticCodingSurfaceEvidenceAction(
              icon: Icons.image_search_rounded,
              color: _agenticCodingSurfaceViolet,
              title:
                  _agenticCodingSurfaceAttachment?.name ??
                  'Attach one coding image',
              subtitle: _agenticCodingSurfaceAttachment == null
                  ? 'Diagram, screenshot, UI state, or error surface · local vision only'
                  : '${_agenticCodingSurfaceAttachment!.dimensions} · ${_agenticCodingSurfaceFormatBytes(_agenticCodingSurfaceAttachment!.bytes.length)}',
              actionLabel: 'ATTACH',
              onTap: _agenticCodingSurfaceRunning
                  ? null
                  : _agenticCodingSurfacePickAttachment,
            )
          else
            const _AgenticCodingSurfaceEvidenceAction(
              icon: Icons.short_text_rounded,
              color: _agenticCodingSurfaceMint,
              title: 'Intent-only context',
              subtitle:
                  'No filesystem or image evidence will be attached to this run.',
              actionLabel: 'PRIVATE',
            ),
          const SizedBox(height: 10),
          SwitchListTile.adaptive(
            contentPadding: EdgeInsets.zero,
            title: const Text(
              'Encrypted embedding memory',
              style: TextStyle(
                color: _agenticCodingSurfaceText,
                fontWeight: FontWeight.w700,
              ),
            ),
            subtitle: const Text(
              'Retrieve and index through the in-house encrypted vector memory.',
              style: TextStyle(
                color: _agenticCodingSurfaceSubtext,
                fontSize: 12,
              ),
            ),
            value: _agenticCodingSurfaceConfig.memoryEnabled,
            activeTrackColor: _agenticCodingSurfaceMint,
            onChanged: _agenticCodingSurfaceRunning
                ? null
                : (value) => _agenticCodingSurfaceUpdateConfig(
                    _agenticCodingSurfaceConfig.copyWith(memoryEnabled: value),
                  ),
          ),
        ],
      ),
    );
  }

  Widget _agenticCodingSurfaceBuildRemoteOperations() {
    final recent = _agenticCodingSurfaceOperations.reversed
        .take(6)
        .toList(growable: false);
    final awaiting = _agenticCodingSurfaceOperations
        .where(
          (operation) =>
              operation.state == NazaRemoteOperationState.awaitingApproval,
        )
        .length;
    final approved = _agenticCodingSurfaceOperations
        .where(
          (operation) => operation.state == NazaRemoteOperationState.approved,
        )
        .length;
    final failed = _agenticCodingSurfaceOperations
        .where(
          (operation) => operation.state == NazaRemoteOperationState.failed,
        )
        .length;
    return _AgenticCodingSurfaceFoundrySection(
      icon: Icons.public_rounded,
      title: 'Remote operations control plane',
      subtitle:
          'Compose bounded DigitalOcean, Chromium, and IPFS intents. Every network or mutation action stays queued until a trusted adapter and fresh approval exist.',
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Wrap(
            spacing: 7,
            runSpacing: 7,
            children: [
              _AgenticCodingSurfaceStatusBadge(
                'AWAITING $awaiting',
                _agenticCodingSurfaceAmber,
              ),
              _AgenticCodingSurfaceStatusBadge(
                'APPROVED $approved',
                _agenticCodingSurfaceMint,
              ),
              _AgenticCodingSurfaceStatusBadge(
                'FAILED $failed',
                failed == 0
                    ? _agenticCodingSurfaceSubtext
                    : _agenticCodingSurfaceRose,
              ),
            ],
          ),
          const SizedBox(height: 11),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              OutlinedButton.icon(
                key: const ValueKey<String>('request-digitalocean-environment'),
                onPressed: _agenticCodingSurfaceRunning
                    ? null
                    : _agenticCodingSurfaceRequestEnvironment,
                icon: const Icon(Icons.cloud_queue_rounded, size: 17),
                label: const Text('DigitalOcean droplet'),
              ),
              OutlinedButton.icon(
                key: const ValueKey<String>('request-chromium-scrape'),
                onPressed: _agenticCodingSurfaceRunning
                    ? null
                    : _agenticCodingSurfaceRequestChromiumScrape,
                icon: const Icon(Icons.travel_explore_rounded, size: 17),
                label: const Text('Chromium scrape'),
              ),
              OutlinedButton.icon(
                key: const ValueKey<String>('request-ipfs-publish'),
                onPressed: _agenticCodingSurfaceRunning
                    ? null
                    : _agenticCodingSurfaceRequestIpfsPublish,
                icon: const Icon(Icons.hub_outlined, size: 17),
                label: const Text('IPFS publish'),
              ),
              OutlinedButton.icon(
                key: const ValueKey<String>('request-scrape-ipfs-export'),
                onPressed: _agenticCodingSurfaceRunning
                    ? null
                    : _agenticCodingSurfaceRequestScrapeExport,
                icon: const Icon(Icons.output_rounded, size: 17),
                label: const Text('Scrape → IPFS'),
              ),
              OutlinedButton.icon(
                key: const ValueKey<String>('manage-digitalocean-droplet'),
                onPressed: _agenticCodingSurfaceRunning
                    ? null
                    : _agenticCodingSurfaceRequestDigitalOceanAction,
                icon: const Icon(Icons.settings_ethernet_rounded, size: 17),
                label: const Text('Manage DO droplet'),
              ),
            ],
          ),
          const SizedBox(height: 12),
          if (recent.isEmpty)
            const _AgenticCodingSurfaceEvidenceAction(
              icon: Icons.lock_clock_rounded,
              color: _agenticCodingSurfaceCyan,
              title: 'No remote requests sealed',
              subtitle:
                  'The queue is empty. Operation history stores plans and references only—not tokens, keys, cookies, commands, or scraped content.',
              actionLabel: 'SEALED',
            )
          else ...[
            const _AgenticCodingSurfaceMicroLabel('RECENT REQUEST QUEUE'),
            const SizedBox(height: 8),
            for (final operation in recent)
              _AgenticCodingSurfaceRemoteOperationTile(
                operation: operation,
                onApprove:
                    operation.state == NazaRemoteOperationState.awaitingApproval
                    ? () =>
                          _agenticCodingSurfaceApproveRemoteOperation(operation)
                    : null,
                onCancel:
                    operation.state ==
                            NazaRemoteOperationState.awaitingApproval ||
                        operation.state == NazaRemoteOperationState.approved
                    ? () =>
                          _agenticCodingSurfaceCancelRemoteOperation(operation)
                    : null,
              ),
          ],
        ],
      ),
    );
  }

  Widget _agenticCodingSurfaceBuildCollaborationQueues() {
    final pool = _agenticCodingSurfaceActiveCollaborationPool;
    final edits = _agenticCodingSurfaceQueuedEdits.reversed
        .take(5)
        .toList(growable: false);
    return _AgenticCodingSurfaceFoundrySection(
      icon: Icons.groups_2_rounded,
      title: 'MMO coding collaboration queues',
      subtitle:
          'Turn a large goal into non-overlapping file-sector claims. Agents exchange encrypted handoff references through the selected node/IPFS peer group and return signed receipts for review.',
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              OutlinedButton.icon(
                key: const ValueKey<String>('create-collaboration-pool'),
                onPressed: _agenticCodingSurfaceRunning
                    ? null
                    : _agenticCodingSurfaceCreateCollaborationPool,
                icon: const Icon(Icons.add_chart_rounded, size: 17),
                label: const Text('Create pool'),
              ),
              OutlinedButton.icon(
                key: const ValueKey<String>('queue-collaborative-edit'),
                onPressed: _agenticCodingSurfaceRunning
                    ? null
                    : _agenticCodingSurfaceEnqueueCollaborativeEdit,
                icon: const Icon(Icons.playlist_add_rounded, size: 17),
                label: const Text('Queue edit'),
              ),
              OutlinedButton.icon(
                key: const ValueKey<String>('queue-agent-handoff'),
                onPressed: _agenticCodingSurfaceRunning
                    ? null
                    : _agenticCodingSurfacePostAgentEnvelope,
                icon: const Icon(Icons.swap_horiz_rounded, size: 17),
                label: const Text('Agent handoff'),
              ),
            ],
          ),
          const SizedBox(height: 12),
          if (pool == null)
            const _AgenticCodingSurfaceEvidenceAction(
              icon: Icons.account_tree_outlined,
              color: _agenticCodingSurfaceViolet,
              title: 'No active collaboration pool',
              subtitle:
                  'Create a pool with a workspace fingerprint before agents can claim edits or exchange envelopes.',
              actionLabel: 'WAITING',
            )
          else ...[
            Container(
              padding: const EdgeInsets.all(11),
              decoration: BoxDecoration(
                color: _agenticCodingSurfaceInk.withValues(alpha: 0.72),
                borderRadius: BorderRadius.circular(13),
                border: Border.all(
                  color: _agenticCodingSurfaceViolet.withValues(alpha: 0.42),
                ),
              ),
              child: Row(
                children: [
                  const Icon(
                    Icons.hub_rounded,
                    color: _agenticCodingSurfaceViolet,
                    size: 20,
                  ),
                  const SizedBox(width: 9),
                  Expanded(
                    child: Text(
                      '${pool.name} · ${pool.peerGroup} · max ${pool.maxConcurrentEdits} claims · ${pool.bondSuite}',
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: _agenticCodingSurfaceSubtext,
                        fontSize: 11,
                      ),
                    ),
                  ),
                  _AgenticCodingSurfaceTinyState(
                    pool.state.label,
                    _agenticCodingSurfaceMint,
                  ),
                ],
              ),
            ),
            const SizedBox(height: 9),
            if (edits.isEmpty)
              const Text(
                'No edit claims yet. Queue the first bounded file-sector task.',
                style: TextStyle(
                  color: _agenticCodingSurfaceSubtext,
                  fontSize: 11,
                ),
              )
            else
              for (final edit in edits)
                Padding(
                  padding: const EdgeInsets.only(bottom: 6),
                  child: Material(
                    color: Colors.transparent,
                    child: ListTile(
                      dense: true,
                      contentPadding: const EdgeInsets.symmetric(horizontal: 9),
                      tileColor: _agenticCodingSurfaceInk.withValues(
                        alpha: 0.68,
                      ),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(11),
                        side: const BorderSide(
                          color: _agenticCodingSurfaceBorder,
                        ),
                      ),
                      leading: const Icon(
                        Icons.code_rounded,
                        color: _agenticCodingSurfaceCyan,
                        size: 19,
                      ),
                      title: Text(
                        '${edit.relativePath} · ${edit.sector}',
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: _agenticCodingSurfaceText,
                          fontSize: 12,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                      subtitle: Text(
                        edit.goal,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: _agenticCodingSurfaceSubtext,
                          fontSize: 10,
                        ),
                      ),
                      trailing: _AgenticCodingSurfaceTinyState(
                        edit.state.label,
                        _agenticCodingSurfaceCyan,
                      ),
                    ),
                  ),
                ),
            Text(
              '${_agenticCodingSurfaceAgentEnvelopes.length} encrypted handoff reference${_agenticCodingSurfaceAgentEnvelopes.length == 1 ? '' : 's'} queued · source payloads remain outside the queue',
              style: const TextStyle(
                color: _agenticCodingSurfaceSubtext,
                fontSize: 10.5,
              ),
            ),
          ],
        ],
      ),
    );
  }

  Widget _agenticCodingSurfaceBuildIpfsChatrooms() {
    final activeRoom = _agenticCodingSurfaceActiveChatRoom;
    return _AgenticCodingSurfaceFoundrySection(
      icon: Icons.forum_rounded,
      title: 'Encrypted IPFS chatroom monitor',
      subtitle:
          'Human and agent rooms use separate room identities, encrypted CID envelopes, PQ bond references, and observational peer health.',
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
