  Widget _agenticCodingSurfaceBuildCapabilityGate() {
    final remote =
        _agenticCodingSurfaceConfig.activeNode.kind ==
        NazaExecutionTargetKind.remoteSsh;
    return _AgenticCodingSurfaceFoundrySection(
      icon: Icons.policy_rounded,
      title: 'Capability gate',
      subtitle:
          'Model reasoning and host capabilities are separate. Elevated surfaces require a per-run acknowledgement.',
      child: Column(
        children: [
          _AgenticCodingSurfaceCapabilityToggle(
            title: 'Generate a reviewable patch proposal',
            subtitle: 'Produces text/diff only; never writes files.',
            value: _agenticCodingSurfaceProposePatch,
            color: _agenticCodingSurfaceMint,
            onChanged: _agenticCodingSurfaceRunning
                ? null
                : (value) =>
                      setState(() => _agenticCodingSurfaceProposePatch = value),
          ),
          _AgenticCodingSurfaceCapabilityToggle(
            title: 'Request check execution capability',
            subtitle:
                'Reserved for a future verified adapter; requires mutation approval.',
            value: _agenticCodingSurfaceRunChecks,
            color: _agenticCodingSurfaceAmber,
            onChanged: _agenticCodingSurfaceRunning
                ? null
                : (value) => setState(() {
                    _agenticCodingSurfaceRunChecks = value;
                    if (!value) _agenticCodingSurfaceMutationApproved = false;
                  }),
          ),
          _AgenticCodingSurfaceCapabilityToggle(
            title: 'Request network capability',
            subtitle: remote
                ? 'Required by the selected SSH node; no connection is automatic.'
                : 'Disabled by default for local and container planning.',
            value: _agenticCodingSurfaceAllowNetwork || remote,
            color: _agenticCodingSurfaceRose,
            onChanged: _agenticCodingSurfaceRunning || remote
                ? null
                : (value) => setState(() {
                    _agenticCodingSurfaceAllowNetwork = value;
                    if (!value) _agenticCodingSurfaceNetworkApproved = false;
                  }),
          ),
          if (_agenticCodingSurfaceRunChecks)
            CheckboxListTile(
              contentPadding: EdgeInsets.zero,
              value: _agenticCodingSurfaceMutationApproved,
              activeColor: _agenticCodingSurfaceAmber,
              title: const Text(
                'I approve the check capability for this run',
                style: TextStyle(
                  color: _agenticCodingSurfaceText,
                  fontSize: 13,
                ),
              ),
              onChanged: _agenticCodingSurfaceRunning
                  ? null
                  : (value) => setState(
                      () =>
                          _agenticCodingSurfaceMutationApproved = value == true,
                    ),
            ),
          if (_agenticCodingSurfaceAllowNetwork || remote)
            CheckboxListTile(
              contentPadding: EdgeInsets.zero,
              value: _agenticCodingSurfaceNetworkApproved,
              activeColor: _agenticCodingSurfaceRose,
              title: const Text(
                'I approve network / remote capability for this run',
                style: TextStyle(
                  color: _agenticCodingSurfaceText,
                  fontSize: 13,
                ),
              ),
              onChanged: _agenticCodingSurfaceRunning
                  ? null
                  : (value) => setState(
                      () =>
                          _agenticCodingSurfaceNetworkApproved = value == true,
                    ),
            ),
          const Divider(color: _agenticCodingSurfaceBorder, height: 22),
          const Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Icon(
                Icons.lock_clock_rounded,
                color: _agenticCodingSurfaceCyan,
                size: 18,
              ),
              SizedBox(width: 9),
              Expanded(
                child: Text(
                  'Strict boundary: this release invokes model synthesis only. Native command/container/SSH adapters must independently attest their sandbox before execution can be enabled.',
                  style: TextStyle(
                    color: _agenticCodingSurfaceSubtext,
                    fontSize: 12,
                    height: 1.4,
                  ),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _agenticCodingSurfaceBuildResult(NazaAgenticRunResult result) {
    return _AgenticCodingSurfaceFoundrySection(
      icon: Icons.account_tree_rounded,
      title: 'Assembly result & evidence telemetry',
      subtitle:
          result.fallbackReason ??
          '${result.contributions.length} contribution${result.contributions.length == 1 ? '' : 's'} · ${result.memoryIndexed ? 'encrypted memory indexed' : 'memory not indexed'}',
      trailing: IconButton(
        tooltip: 'Copy synthesis',
        onPressed: () async {
          await Clipboard.setData(ClipboardData(text: result.text));
          if (mounted) {
            ScaffoldMessenger.of(
              context,
            ).showSnackBar(const SnackBar(content: Text('Synthesis copied')));
          }
        },
        icon: const Icon(
          Icons.copy_all_rounded,
          color: _agenticCodingSurfaceSubtext,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          LayoutBuilder(
            builder: (context, constraints) {
              final telemetry = _AgenticCodingSurfaceTelemetryGrid(
                snapshot: result.weave,
              );
              final radar = SizedBox(
                height: 220,
                child: _AgenticCodingSurfaceEntropyRadar(
                  snapshot: result.weave,
                ),
              );
              if (constraints.maxWidth < 700) {
                return Column(
                  children: [telemetry, const SizedBox(height: 10), radar],
                );
              }
              return Row(
                crossAxisAlignment: CrossAxisAlignment.center,
                children: [
                  Expanded(flex: 3, child: telemetry),
                  const SizedBox(width: 12),
                  Expanded(flex: 2, child: radar),
                ],
              );
            },
          ),
          const SizedBox(height: 16),
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(16),
            decoration: BoxDecoration(
              color: _agenticCodingSurfaceInk.withValues(alpha: 0.88),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: _agenticCodingSurfaceBorder),
            ),
            child: MarkdownBody(
              data: result.text,
              selectable: true,
              styleSheet: MarkdownStyleSheet(
                p: const TextStyle(
                  color: _agenticCodingSurfaceText,
                  height: 1.5,
                  fontSize: 13.5,
                ),
                h1: const TextStyle(
                  color: _agenticCodingSurfaceText,
                  fontWeight: FontWeight.w900,
                  fontSize: 24,
                ),
                h2: const TextStyle(
                  color: _agenticCodingSurfaceMint,
                  fontWeight: FontWeight.w800,
                  fontSize: 19,
                ),
                h3: const TextStyle(
                  color: _agenticCodingSurfaceCyan,
                  fontWeight: FontWeight.w800,
                  fontSize: 16,
                ),
                code: const TextStyle(
                  color: Color(0xFFD8FFF0),
                  backgroundColor: Color(0xFF142722),
                  fontFamily: 'JetBrainsMono',
                  fontSize: 12,
                ),
                codeblockDecoration: BoxDecoration(
                  color: const Color(0xFF081310),
                  borderRadius: BorderRadius.circular(10),
                  border: Border.all(color: _agenticCodingSurfaceBorder),
                ),
                listBullet: const TextStyle(color: _agenticCodingSurfaceViolet),
                blockquote: const TextStyle(
                  color: _agenticCodingSurfaceSubtext,
                  height: 1.45,
                ),
                blockquoteDecoration: const BoxDecoration(
                  border: Border(
                    left: BorderSide(
                      color: _agenticCodingSurfaceViolet,
                      width: 3,
                    ),
                  ),
                ),
              ),
            ),
          ),
          const SizedBox(height: 16),
          const _AgenticCodingSurfaceMicroLabel('PROVENANCE LATTICE'),
          const SizedBox(height: 9),
          for (final entry in result.provenance)
            _AgenticCodingSurfaceProvenanceTile(entry: entry),
          const SizedBox(height: 10),
          const Text(
            'Entropy weave values are normalized lexical/disagreement diagnostics. They are not cryptographic entropy, model confidence, correctness, or quantum advantage.',
            style: TextStyle(
              color: _agenticCodingSurfaceSubtext,
              fontSize: 11,
              height: 1.4,
            ),
          ),
        ],
      ),
    );
  }

  static String _agenticCodingSurfaceBasename(String path) =>
      path.split(RegExp(r'[/\\]')).where((part) => part.isNotEmpty).last;

  static String _agenticCodingSurfaceFormatBytes(int bytes) {
    if (bytes >= 1024 * 1024) {
      return '${(bytes / (1024 * 1024)).toStringAsFixed(1)} MiB';
    }
    if (bytes >= 1024) return '${(bytes / 1024).toStringAsFixed(1)} KiB';
    return '$bytes B';
  }
}

class _AgenticCodingSurfaceFoundryBackdrop extends StatelessWidget {
  const _AgenticCodingSurfaceFoundryBackdrop();

  @override
  Widget build(BuildContext context) {
    return IgnorePointer(
      child: CustomPaint(
        painter: _AgenticCodingSurfaceFoundryBackdropPainter(),
      ),
    );
  }
}

class _AgenticCodingSurfaceFoundryBackdropPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final grid = Paint()
      ..color = const Color(0x0D62D9F7)
      ..strokeWidth = 1;
    const step = 72.0;
    for (var x = 0.0; x <= size.width; x += step) {
      canvas.drawLine(Offset(x, 0), Offset(x, size.height), grid);
    }
    for (var y = 0.0; y <= size.height; y += step) {
      canvas.drawLine(Offset(0, y), Offset(size.width, y), grid);
    }
    final glow = Paint()
      ..shader =
          const RadialGradient(
            colors: [Color(0x2AAA93FF), Color(0x006210A0)],
          ).createShader(
            Rect.fromCircle(
              center: Offset(size.width * 0.84, 80),
              radius: math.min(420, size.width * 0.42),
            ),
          );
    canvas.drawCircle(
      Offset(size.width * 0.84, 80),
      math.min(420, size.width * 0.42),
      glow,
    );
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

