class _AgenticCodingSurfaceTelemetryGrid extends StatelessWidget {
  const _AgenticCodingSurfaceTelemetryGrid({required this.snapshot});

  final NazaEntropyWeaveSnapshot snapshot;

  @override
  Widget build(BuildContext context) {
    final metrics = <(String, double, Color, String)>[
      (
        'SHARD DISAGREEMENT',
        snapshot.disagreement,
        _AgenticCodingSurfaceNazaAgenticCodingSurfaceState
            ._agenticCodingSurfaceRose,
        'pairwise evidence distance',
      ),
      (
        'TRUST CONSENSUS',
        snapshot.trustConsensus,
        _AgenticCodingSurfaceNazaAgenticCodingSurfaceState
            ._agenticCodingSurfaceMint,
        'trust-weighted similarity',
      ),
      (
        'PROVENANCE',
        snapshot.provenanceCoverage,
        _AgenticCodingSurfaceNazaAgenticCodingSurfaceState
            ._agenticCodingSurfaceCyan,
        'labeled contribution coverage',
      ),
      (
        'LEXICAL ENTROPY',
        snapshot.lexicalEntropy,
        _AgenticCodingSurfaceNazaAgenticCodingSurfaceState
            ._agenticCodingSurfaceViolet,
        'normalized vocabulary spread',
      ),
      (
        'ANOMALY SURFACE',
        snapshot.anomalySurface,
        _AgenticCodingSurfaceNazaAgenticCodingSurfaceState
            ._agenticCodingSurfaceAmber,
        'review pressure composite',
      ),
      (
        'CIRCUIT SWEEP',
        snapshot.circuitMean,
        _AgenticCodingSurfaceNazaAgenticCodingSurfaceState
            ._agenticCodingSurfaceViolet,
        '${snapshot.circuitMin.toStringAsFixed(2)}–${snapshot.circuitMax.toStringAsFixed(2)} classical range',
      ),
    ];
    return LayoutBuilder(
      builder: (context, constraints) {
        final width = math.max(150.0, (constraints.maxWidth - 10) / 2);
        return Wrap(
          spacing: 10,
          runSpacing: 10,
          children: metrics
              .map(
                (metric) => SizedBox(
                  width: width,
                  child: _AgenticCodingSurfaceMetricTile(
                    label: metric.$1,
                    value: metric.$2,
                    color: metric.$3,
                    detail: metric.$4,
                  ),
                ),
              )
              .toList(growable: false),
        );
      },
    );
  }
}

