class _AgenticCodingSurfaceEntropyRadarPainter extends CustomPainter {
  _AgenticCodingSurfaceEntropyRadarPainter(this.snapshot);

  final NazaEntropyWeaveSnapshot snapshot;

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2);
    final radius = math.min(size.width, size.height) * 0.37;
    const axes = 5;
    final gridPaint = Paint()
      ..color = _AgenticCodingSurfaceNazaAgenticCodingSurfaceState
          ._agenticCodingSurfaceBorder
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1;
    for (var ring = 1; ring <= 4; ring++) {
      canvas.drawPath(
        _agenticCodingSurfacePolygon(center, radius * ring / 4, axes),
        gridPaint,
      );
    }
    for (var index = 0; index < axes; index++) {
      final point = _agenticCodingSurfacePoint(center, radius, index, axes);
      canvas.drawLine(center, point, gridPaint);
    }
    final values = <double>[
      snapshot.trustConsensus,
      snapshot.provenanceCoverage,
      1 - snapshot.anomalySurface,
      snapshot.circuitMean,
      1 - snapshot.disagreement,
    ];
    final path = Path();
    for (var index = 0; index < axes; index++) {
      final point = _agenticCodingSurfacePoint(
        center,
        radius * values[index].clamp(0.0, 1.0),
        index,
        axes,
      );
      if (index == 0) {
        path.moveTo(point.dx, point.dy);
      } else {
        path.lineTo(point.dx, point.dy);
      }
    }
    path.close();
    canvas.drawPath(
      path,
      Paint()
        ..color = _AgenticCodingSurfaceNazaAgenticCodingSurfaceState
            ._agenticCodingSurfaceViolet
            .withValues(alpha: 0.20)
        ..style = PaintingStyle.fill,
    );
    canvas.drawPath(
      path,
      Paint()
        ..color = _AgenticCodingSurfaceNazaAgenticCodingSurfaceState
            ._agenticCodingSurfaceCyan
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2,
    );
    const labels = <String>['TRUST', 'SOURCE', 'STABLE', 'SWEEP', 'AGREE'];
    final textPainter = TextPainter(textDirection: TextDirection.ltr);
    for (var index = 0; index < axes; index++) {
      final point = _agenticCodingSurfacePoint(
        center,
        radius + 17,
        index,
        axes,
      );
      textPainter.text = TextSpan(
        text: labels[index],
        style: const TextStyle(
          color: _AgenticCodingSurfaceNazaAgenticCodingSurfaceState
              ._agenticCodingSurfaceSubtext,
          fontFamily: 'JetBrainsMono',
          fontSize: 7.5,
          fontWeight: FontWeight.w800,
        ),
      );
      textPainter.layout();
      textPainter.paint(
        canvas,
        point - Offset(textPainter.width / 2, textPainter.height / 2),
      );
    }
  }

  static Path _agenticCodingSurfacePolygon(
    Offset center,
    double radius,
    int count,
  ) {
    final path = Path();
    for (var index = 0; index < count; index++) {
      final point = _agenticCodingSurfacePoint(center, radius, index, count);
      if (index == 0) {
        path.moveTo(point.dx, point.dy);
      } else {
        path.lineTo(point.dx, point.dy);
      }
    }
    return path..close();
  }

  static Offset _agenticCodingSurfacePoint(
    Offset center,
    double radius,
    int index,
    int count,
  ) {
    final angle = -math.pi / 2 + index * math.pi * 2 / count;
    return center + Offset(math.cos(angle) * radius, math.sin(angle) * radius);
  }

  @override
  bool shouldRepaint(
    covariant _AgenticCodingSurfaceEntropyRadarPainter oldDelegate,
  ) => oldDelegate.snapshot != snapshot;
}

