/// Human-facing code viewer/editor for the Code Foundry.
///
/// Loading is bounded and saving is an explicit local mutation. Remote node
/// execution is deliberately not hidden behind this editor; a future
/// transport must supply its own approval and host-key policy boundary.
final class NazaCodeWorkbench extends StatefulWidget {
  const NazaCodeWorkbench({super.key});

  @override
  State<NazaCodeWorkbench> createState() =>
      _CodeWorkbenchNazaCodeWorkbenchState();
}

final class _CodeWorkbenchNazaCodeWorkbenchState
    extends State<NazaCodeWorkbench> {
  static const _codeWorkbenchViolet = Color(0xFFAA93FF);
  static const _codeWorkbenchCyan = Color(0xFF62D9F7);
  static const _codeWorkbenchMint = Color(0xFF76E3B4);
  static const _codeWorkbenchInk = Color(0xFF06100F);
  static const _codeWorkbenchPanel = Color(0xFF0D1B19);
  static const _codeWorkbenchBorder = Color(0xFF29433D);
  static const _codeWorkbenchText = Color(0xFFF0FFF8);
  static const _codeWorkbenchSubtext = Color(0xFFA8BDB5);
  static const _codeWorkbenchMaxBytes = 320000;

  final _codeWorkbenchEditor = TextEditingController();
  String _codeWorkbenchOriginal = '';
  String _codeWorkbenchPath = '';
  String _codeWorkbenchStatus =
      'Select a source file to open the human code surface.';
  bool _codeWorkbenchDiff = false;
  bool _codeWorkbenchSaving = false;

  @override
  void dispose() {
    _codeWorkbenchEditor.dispose();
    super.dispose();
  }

  Future<void> _codeWorkbenchOpen() async {
    final selected = await file_selector.openFile(
      acceptedTypeGroups: [
        file_selector.XTypeGroup(
          label: 'Source',
          extensions: const [
            'dart',
            'py',
            'js',
            'ts',
            'tsx',
            'jsx',
            'rs',
            'go',
            'java',
            'kt',
            'swift',
            'c',
            'cpp',
            'h',
            'hpp',
            'json',
            'yaml',
            'yml',
            'md',
            'txt',
            'sql',
            'html',
            'css',
            'scss',
          ],
        ),
      ],
    );
    if (selected == null || selected.path.trim().isEmpty) return;
    final selectedPath = selected.path;
    final file = File(selectedPath);
    final stat = await file.stat();
    if (stat.size > _codeWorkbenchMaxBytes) {
      if (mounted)
        setState(
          () => _codeWorkbenchStatus =
              'File exceeds the 320 KiB viewer boundary.',
        );
      return;
    }
    final text = await file.readAsString();
    if (!mounted) return;
    setState(() {
      _codeWorkbenchPath = selectedPath;
      _codeWorkbenchOriginal = text;
      _codeWorkbenchEditor.text = text;
      _codeWorkbenchStatus =
          'Opened ${_codeWorkbenchBasename(selectedPath)} · ${text.length} characters';
      _codeWorkbenchDiff = false;
    });
  }

  Future<void> _codeWorkbenchSave() async {
    if (_codeWorkbenchPath.isEmpty ||
        _codeWorkbenchSaving ||
        _codeWorkbenchEditor.text == _codeWorkbenchOriginal)
      return;
    final approved = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('Write local file?'),
        content: Text(
          'This will replace the contents of ${_codeWorkbenchBasename(_codeWorkbenchPath)}. The Code Foundry will not write remote nodes from this editor.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Save local file'),
          ),
        ],
      ),
    );
    if (approved != true) return;
    setState(() {
      _codeWorkbenchSaving = true;
      _codeWorkbenchStatus = 'Writing approved local edit';
    });
    try {
      await File(
        _codeWorkbenchPath,
      ).writeAsString(_codeWorkbenchEditor.text, flush: true);
      if (mounted)
        setState(() {
          _codeWorkbenchOriginal = _codeWorkbenchEditor.text;
          _codeWorkbenchSaving = false;
          _codeWorkbenchStatus =
              'Saved ${_codeWorkbenchBasename(_codeWorkbenchPath)}';
        });
    } catch (error) {
      if (mounted)
        setState(() {
          _codeWorkbenchSaving = false;
          _codeWorkbenchStatus = 'Save failed: $error';
        });
    }
  }

  String _codeWorkbenchDiffText() {
    final before = _codeWorkbenchOriginal.split('\n');
    final after = _codeWorkbenchEditor.text.split('\n');
    final lines = <String>[
      '--- a/${_codeWorkbenchBasename(_codeWorkbenchPath)}',
      '+++ b/${_codeWorkbenchBasename(_codeWorkbenchPath)}',
    ];
    final count = before.length > after.length ? before.length : after.length;
    for (var i = 0; i < count; i++) {
      final left = i < before.length ? before[i] : null;
      final right = i < after.length ? after[i] : null;
      if (left == right && left != null) {
        lines.add(' $left');
      } else {
        if (left != null) lines.add('-$left');
        if (right != null) lines.add('+$right');
      }
    }
    return lines.join('\n');
  }

  @override
  Widget build(BuildContext context) {
    final changed = _codeWorkbenchEditor.text != _codeWorkbenchOriginal;
    return Card(
      color: _codeWorkbenchPanel.withValues(alpha: 0.96),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(20),
        side: const BorderSide(color: _codeWorkbenchBorder),
      ),
      child: Padding(
        padding: const EdgeInsets.all(14),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                const Icon(Icons.code_rounded, color: _codeWorkbenchCyan),
                const SizedBox(width: 9),
                const Expanded(
                  child: Text(
                    'Human code studio',
                    style: TextStyle(
                      color: _codeWorkbenchText,
                      fontSize: 17,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
                IconButton(
                  tooltip: 'Open source file',
                  onPressed: _codeWorkbenchOpen,
                  icon: const Icon(
                    Icons.folder_open_rounded,
                    color: _codeWorkbenchSubtext,
                  ),
                ),
                IconButton(
                  tooltip: 'Toggle diff',
                  onPressed: _codeWorkbenchPath.isEmpty
                      ? null
                      : () => setState(
                          () => _codeWorkbenchDiff = !_codeWorkbenchDiff,
                        ),
                  icon: Icon(
                    Icons.compare_arrows_rounded,
                    color: _codeWorkbenchDiff
                        ? _codeWorkbenchMint
                        : _codeWorkbenchSubtext,
                  ),
                ),
                IconButton(
                  tooltip: 'Save approved local edit',
                  onPressed: changed ? _codeWorkbenchSave : null,
                  icon: Icon(
                    _codeWorkbenchSaving
                        ? Icons.hourglass_top_rounded
                        : Icons.save_rounded,
                    color: changed
                        ? _codeWorkbenchViolet
                        : _codeWorkbenchSubtext,
                  ),
                ),
              ],
            ),
            Text(
              _codeWorkbenchPath.isEmpty
                  ? _codeWorkbenchStatus
                  : '${_codeWorkbenchBasename(_codeWorkbenchPath)} · ${changed ? 'unsaved changes' : 'clean'}',
              style: const TextStyle(
                color: _codeWorkbenchSubtext,
                fontSize: 11,
              ),
            ),
            const SizedBox(height: 10),
            SizedBox(
              height: 380,
              child: _codeWorkbenchDiff
                  ? SingleChildScrollView(
                      child: SelectableText(
                        _codeWorkbenchDiffText(),
                        style: const TextStyle(
                          color: _codeWorkbenchText,
                          fontFamily: 'JetBrainsMono',
                          fontSize: 12,
                          height: 1.45,
                        ),
                      ),
                    )
                  : TextField(
                      controller: _codeWorkbenchEditor,
                      expands: true,
                      maxLines: null,
                      minLines: null,
                      autocorrect: false,
                      enableSuggestions: false,
                      style: const TextStyle(
                        color: _codeWorkbenchText,
                        fontFamily: 'JetBrainsMono',
                        fontSize: 12,
                        height: 1.45,
                      ),
                      decoration: const InputDecoration(
                        filled: true,
                        fillColor: _codeWorkbenchInk,
                        border: OutlineInputBorder(
                          borderSide: BorderSide(color: _codeWorkbenchBorder),
                        ),
                      ),
                    ),
            ),
          ],
        ),
      ),
    );
  }

  static String _codeWorkbenchBasename(String path) =>
      path.split(RegExp(r'[/\\]')).where((part) => part.isNotEmpty).last;
}

