  final String bondSuite;
  final DateTime createdAt;

  List<String> validate() {
    final errors = <String>[];
    if (!_collaborationQueueValidId(id))
      errors.add('Invalid collaboration pool ID.');
    if (!_collaborationQueueValidLabel(name, 100))
      errors.add('Pool name is invalid.');
    if (!_collaborationQueueFingerprint(workspaceFingerprint)) {
      errors.add('Workspace fingerprint must be an immutable digest.');
