  final String sector;
  final String goal;
  final String baseFingerprint;
  final List<String> dependencies;
  final int priority;
  final NazaQueuedEditState state;
  final String? claimedByAgent;
  final String? executionNodeId;
  final String? encryptedContextCid;
  final String? receiptCid;
  final DateTime createdAt;

  List<String> validate() {
    final errors = <String>[];
    if (!_collaborationQueueValidId(id) || !_collaborationQueueValidId(poolId))
      errors.add('Invalid edit identity.');
    if (!_collaborationQueueRelativePath(relativePath)) {
      errors.add('Edit path must be relative and traversal-safe.');
    }
    if (!_collaborationQueueValidLabel(sector, 80))
      errors.add('Edit sector is invalid.');
    if (!_collaborationQueueValidLabel(goal, 500))
      errors.add('Edit goal is invalid.');
    if (!_collaborationQueueFingerprint(baseFingerprint))
      errors.add('Base fingerprint is invalid.');
    if (dependencies.length > 32 ||
        dependencies.any((id) => !_collaborationQueueValidId(id))) {
      errors.add('Edit dependencies are invalid or too numerous.');
