    if (priority < 0 || priority > 100)
      errors.add('Edit priority must be 0–100.');
    if (encryptedContextCid != null &&
        !_collaborationQueueValidCid(encryptedContextCid!)) {
      errors.add('Encrypted context CID is invalid.');
    }
    if (receiptCid != null && !_collaborationQueueValidCid(receiptCid!)) {
      errors.add('Receipt CID is invalid.');
