class NazaDataPipesSurface extends StatefulWidget {
  const NazaDataPipesSurface({super.key, this.store});
  final NazaDataPipeStore? store;
  @override
  State<NazaDataPipesSurface> createState() =>
      _DataPipesSurfaceNazaDataPipesSurfaceState();
}

class _DataPipesSurfaceNazaDataPipesSurfaceState
    extends State<NazaDataPipesSurface> {
  late final NazaDataPipeStore _dataPipesSurfaceStore =
      widget.store ?? NazaDataPipeStore();
  final _dataPipesSurfaceName = TextEditingController(
    text: 'Secure research pipe',
  );
  final _dataPipesSurfaceUrl = TextEditingController();
  final _dataPipesSurfaceDomains = TextEditingController();
  final _dataPipesSurfaceImage = TextEditingController();
  int _dataPipesSurfaceMaxPages = 10;
  bool _dataPipesSurfaceSaving = false;
  String _dataPipesSurfaceStatus =
      'No remote operation runs without explicit approval.';

  @override
  void dispose() {
    _dataPipesSurfaceName.dispose();
    _dataPipesSurfaceUrl.dispose();
    _dataPipesSurfaceDomains.dispose();
    _dataPipesSurfaceImage.dispose();
    super.dispose();
  }

  Future<void> _dataPipesSurfaceQueue() async {
    setState(() => _dataPipesSurfaceSaving = true);
    try {
      final now = DateTime.now().toUtc();
      final plan = NazaDataPipePlan(
        id: 'pipe-${now.microsecondsSinceEpoch}',
        name: NazaBoundarySanitizer.databaseText(
          _dataPipesSurfaceName.text,
          maxCharacters: 100,
        ),
        targetUrl: NazaBoundarySanitizer.remoteText(
          _dataPipesSurfaceUrl.text,
          maxCharacters: 2048,
          redactSecrets: true,
        ),
        allowedDomains: _dataPipesSurfaceDomains.text
            .split(',')
            .map((v) => v.trim().toLowerCase())
            .where((v) => v.isNotEmpty)
            .take(32)
            .toList(),
        image: _dataPipesSurfaceImage.text.trim(),
        maxPages: _dataPipesSurfaceMaxPages,
        createdAt: now,
      );
      await _dataPipesSurfaceStore.savePlan(plan);
      if (mounted)
        setState(
          () => _dataPipesSurfaceStatus =
              'Pipeline queued for human approval. No droplet was created.',
        );
    } catch (error) {
      if (mounted)
        setState(
          () => _dataPipesSurfaceStatus =
              'Rejected: ${NazaBoundarySanitizer.databaseText(error.toString(), maxCharacters: 300)}',
        );
    } finally {
      if (mounted) setState(() => _dataPipesSurfaceSaving = false);
    }
  }

  @override
  Widget build(BuildContext context) => ColoredBox(
    color: const Color(0xFF06100F),
    child: ListView(
      padding: const EdgeInsets.all(20),
      children: [
        const Text(
          'Data Pipes / Scraping',
          style: TextStyle(
            color: Color(0xFFF0FFF8),
            fontSize: 28,
            fontWeight: FontWeight.w700,
          ),
        ),
        const SizedBox(height: 8),
        const Text(
          'Plan an ephemeral DigitalOcean worker, pinned hardened Chromium container, proxy-only allowlisted crawl, verified result transfer, encrypted local SQLite import, and automatic teardown.',
          style: TextStyle(color: Color(0xFFA8BDB5), height: 1.4),
        ),
        const SizedBox(height: 18),
        _dataPipesSurfaceField(_dataPipesSurfaceName, 'Pipeline name'),
        _dataPipesSurfaceField(_dataPipesSurfaceUrl, 'HTTPS target URL'),
        _dataPipesSurfaceField(
          _dataPipesSurfaceDomains,
          'Allowed domains (comma separated)',
        ),
        _dataPipesSurfaceField(
          _dataPipesSurfaceImage,
          'Pinned OCI image@sha256:<digest>',
        ),
        Row(
          children: [
            const Text(
              'Maximum pages',
              style: TextStyle(color: Color(0xFFA8BDB5)),
            ),
            Expanded(
              child: Slider(
                value: _dataPipesSurfaceMaxPages.toDouble(),
                min: 1,
                max: 100,
                divisions: 99,
                label: '$_dataPipesSurfaceMaxPages',
                onChanged: (v) =>
                    setState(() => _dataPipesSurfaceMaxPages = v.round()),
              ),
            ),
            Text(
              '$_dataPipesSurfaceMaxPages',
              style: const TextStyle(color: Color(0xFFF0FFF8)),
            ),
          ],
        ),
        const SizedBox(height: 8),
        FilledButton.icon(
          onPressed: _dataPipesSurfaceSaving ? null : _dataPipesSurfaceQueue,
          icon: const Icon(Icons.add_task_rounded),
          label: Text(
            _dataPipesSurfaceSaving ? 'Validating…' : 'Queue for approval',
          ),
        ),
        const SizedBox(height: 14),
        Text(
          _dataPipesSurfaceStatus,
          style: const TextStyle(color: Color(0xFF76E3B4)),
        ),
        const SizedBox(height: 20),
        const Text(
          'Enforced boundary',
          style: TextStyle(
            color: Color(0xFFF0FFF8),
            fontWeight: FontWeight.w700,
          ),
        ),
        const Text(
          '• robots.txt required • no cookies • immutable image digest • non-root/read-only/no-new-privileges • capabilities dropped • proxy-only egress • 64 MiB/10,000-row import bounds • sentinel checks at provision, deploy, scrape, and teardown • secrets never enter model prompts',
          style: TextStyle(color: Color(0xFFA8BDB5), height: 1.5),
        ),
      ],
    ),
  );

  Widget _dataPipesSurfaceField(
    TextEditingController controller,
    String label,
  ) => Padding(
    padding: const EdgeInsets.only(bottom: 12),
    child: TextField(
      controller: controller,
      style: const TextStyle(color: Color(0xFFF0FFF8)),
      decoration: InputDecoration(
        labelText: label,
        filled: true,
        fillColor: const Color(0xFF0D1B19),
        border: const OutlineInputBorder(),
      ),
    ),
  );
}

