  final NazaChatRoomKind kind;
  final String topic;
  final String peerGroup;
  final NazaChatRoomState state;
  final String? relayNodeId;
  final String? ipnsName;
  final bool publicDiscovery;
  final bool publicExposureApproved;
  final int maxMessageBytes;
  final bool requiresSignedReceipts;
  final String bondSuite;
  final DateTime createdAt;

  List<String> validate() {
    final errors = <String>[];
    if (!_ipfsChatroomsValidId(id)) errors.add('Invalid chatroom identity.');
    if (!_ipfsChatroomsValidLabel(name, 120))
      errors.add('Chatroom name is invalid.');
    if (!_ipfsChatroomsValidTopic(topic))
      errors.add('Chatroom topic is invalid.');
    if (!_ipfsChatroomsValidLabel(peerGroup, 120))
      errors.add('Peer group is invalid.');
    if (relayNodeId != null && !_ipfsChatroomsValidId(relayNodeId!)) {
      errors.add('Relay node reference is invalid.');
    }
    if (ipnsName != null && !_ipfsChatroomsValidIpnsName(ipnsName!)) {
      errors.add('IPNS name is invalid.');
    }
    if (publicDiscovery && !publicExposureApproved) {
      errors.add(
        'Public chatroom discovery requires explicit exposure approval.',
      );
    }
    if (maxMessageBytes < 1024 || maxMessageBytes > 4 * 1024 * 1024) {
      errors.add('Maximum message size must be 1 KiB–4 MiB.');
    }
    if (bondSuite != nazaChatHybridSuite) {
      errors.add('Unsupported chatroom bond suite.');
    }
    return List<String>.unmodifiable(errors);
  }

  Map<String, Object?> toJson() => <String, Object?>{
    'id': id,
    'name': name,
    'kind': kind.name,
    'topic': topic,
    'peerGroup': peerGroup,
    'state': state.name,
    if (relayNodeId != null) 'relayNodeId': relayNodeId,
    if (ipnsName != null) 'ipnsName': ipnsName,
    'publicDiscovery': publicDiscovery,
    'publicExposureApproved': publicExposureApproved,
    'maxMessageBytes': maxMessageBytes,
    'requiresSignedReceipts': requiresSignedReceipts,
    'bondSuite': bondSuite,
    'createdAt': createdAt.toUtc().toIso8601String(),
  };

  static NazaChatRoom? fromJson(Object? value) {
    if (value is! Map) return null;
    final createdAt = DateTime.tryParse(value['createdAt']?.toString() ?? '');
    final kind = _ipfsChatroomsEnumByName<NazaChatRoomKind>(
      value['kind']?.toString(),
      NazaChatRoomKind.values,
    );
    final state = _ipfsChatroomsEnumByName<NazaChatRoomState>(
      value['state']?.toString(),
      NazaChatRoomState.values,
    );
    if (createdAt == null || kind == null || state == null) return null;
    final room = NazaChatRoom(
      id: value['id']?.toString() ?? '',
      name: value['name']?.toString() ?? '',
      kind: kind,
      topic: value['topic']?.toString() ?? '',
      peerGroup: value['peerGroup']?.toString() ?? '',
      state: state,
      relayNodeId: _ipfsChatroomsNullable(value['relayNodeId']?.toString()),
      ipnsName: _ipfsChatroomsNullable(value['ipnsName']?.toString()),
      publicDiscovery: value['publicDiscovery'] == true,
      publicExposureApproved: value['publicExposureApproved'] == true,
      maxMessageBytes: value['maxMessageBytes'] is num
          ? (value['maxMessageBytes'] as num).round()
          : 1024 * 1024,
      requiresSignedReceipts: value['requiresSignedReceipts'] != false,
      bondSuite: value['bondSuite']?.toString() ?? '',
      createdAt: createdAt.toUtc(),
    );
    return room.validate().isEmpty ? room : null;
  }
}

/// A transport-neutral message envelope. `ciphertextCid` points to encrypted
/// bytes pinned by an adapter; no chat text is ever accepted by this model.
@immutable
final class NazaChatMessageEnvelope {
  const NazaChatMessageEnvelope({
    required this.id,
    required this.roomId,
    required this.senderId,
    required this.senderKind,
    required this.ciphertextCid,
    required this.aadDigest,
    required this.signatureKeyId,
    required this.sequence,
    required this.createdAt,
    this.replyTo,
    this.attachmentCids = const <String>[],
    this.mlDsa87PublicKey,
    this.mlDsa87Signature,
    this.passkeyCredentialId,
    this.passkeyAssertionDigest,
  });

  final String id;
  final String roomId;
  final String senderId;
  final NazaChatRoomKind senderKind;
  final String ciphertextCid;
  final String aadDigest;
  final String signatureKeyId;
  final int sequence;
  final String? replyTo;
  final List<String> attachmentCids;
  final DateTime createdAt;
  final String? mlDsa87PublicKey;
  final String? mlDsa87Signature;
  final String? passkeyCredentialId;
  final String? passkeyAssertionDigest;

  bool get hasAdvancedSignature =>
      mlDsa87PublicKey != null && mlDsa87Signature != null;

  List<String> validate() {
    final errors = <String>[];
    if (!_ipfsChatroomsValidId(id) ||
        !_ipfsChatroomsValidId(roomId) ||
        !_ipfsChatroomsValidId(senderId)) {
      errors.add('Message identity is invalid.');
    }
    if (!_ipfsChatroomsValidCid(ciphertextCid))
      errors.add('Ciphertext CID is invalid.');
    if (!_ipfsChatroomsValidDigest(aadDigest))
      errors.add('AAD digest is invalid.');
    if (!_ipfsChatroomsValidKeyReference(signatureKeyId)) {
      errors.add('Signature key reference is invalid.');
    }
    if (sequence < 0 || sequence > 1000000000) {
      errors.add('Message sequence is invalid.');
    }
    if (replyTo != null && !_ipfsChatroomsValidId(replyTo!)) {
      errors.add('Reply reference is invalid.');
    }
    if (attachmentCids.length > 16 ||
        attachmentCids.any((cid) => !_ipfsChatroomsValidCid(cid))) {
      errors.add('Attachment CID list is invalid.');
    }
    if ((mlDsa87PublicKey == null) != (mlDsa87Signature == null)) {
      errors.add('Post-quantum signature material is incomplete.');
    }
    if (hasAdvancedSignature &&
        (!_ipfsChatroomsValidBase64Length(
              mlDsa87PublicKey!,
              DilithiumParams.mlDsa87.publicKeyBytes,
            ) ||
            !_ipfsChatroomsValidBase64Length(
              mlDsa87Signature!,
              DilithiumParams.mlDsa87.signatureBytes,
            ))) {
      errors.add('ML-DSA-87 signature material is invalid.');
    }
    if ((passkeyCredentialId == null) != (passkeyAssertionDigest == null) ||
        (passkeyCredentialId != null &&
            !_ipfsChatroomsValidPasskeyCredential(passkeyCredentialId!)) ||
        (passkeyAssertionDigest != null &&
            !RegExp(r'^[a-fA-F0-9]{64}$').hasMatch(passkeyAssertionDigest!))) {
      errors.add('Passkey proof binding is invalid.');
    }
    return List<String>.unmodifiable(errors);
  }

  Map<String, Object?> toJson() => <String, Object?>{
    'id': id,
    'roomId': roomId,
    'senderId': senderId,
    'senderKind': senderKind.name,
    'ciphertextCid': ciphertextCid,
    'aadDigest': aadDigest,
    'signatureKeyId': signatureKeyId,
    'sequence': sequence,
    if (replyTo != null) 'replyTo': replyTo,
    'attachmentCids': attachmentCids,
    'createdAt': createdAt.toUtc().toIso8601String(),
    if (mlDsa87PublicKey != null) 'mlDsa87PublicKey': mlDsa87PublicKey,
    if (mlDsa87Signature != null) 'mlDsa87Signature': mlDsa87Signature,
    if (passkeyCredentialId != null) 'passkeyCredentialId': passkeyCredentialId,
    if (passkeyAssertionDigest != null)
      'passkeyAssertionDigest': passkeyAssertionDigest,
  };

  static NazaChatMessageEnvelope? fromJson(Object? value) {
    if (value is! Map) return null;
    final createdAt = DateTime.tryParse(value['createdAt']?.toString() ?? '');
    final senderKind = _ipfsChatroomsEnumByName<NazaChatRoomKind>(
      value['senderKind']?.toString(),
      NazaChatRoomKind.values,
    );
    if (createdAt == null || senderKind == null) return null;
    final envelope = NazaChatMessageEnvelope(
      id: value['id']?.toString() ?? '',
      roomId: value['roomId']?.toString() ?? '',
      senderId: value['senderId']?.toString() ?? '',
      senderKind: senderKind,
      ciphertextCid: value['ciphertextCid']?.toString() ?? '',
      aadDigest: value['aadDigest']?.toString() ?? '',
      signatureKeyId: value['signatureKeyId']?.toString() ?? '',
      sequence: value['sequence'] is num
          ? (value['sequence'] as num).round()
          : -1,
      replyTo: _ipfsChatroomsNullable(value['replyTo']?.toString()),
      attachmentCids: _ipfsChatroomsStrings(value['attachmentCids'], 16),
      createdAt: createdAt.toUtc(),
      mlDsa87PublicKey: _ipfsChatroomsNullable(
        value['mlDsa87PublicKey']?.toString(),
      ),
      mlDsa87Signature: _ipfsChatroomsNullable(
        value['mlDsa87Signature']?.toString(),
      ),
      passkeyCredentialId: _ipfsChatroomsNullable(
        value['passkeyCredentialId']?.toString(),
      ),
      passkeyAssertionDigest: _ipfsChatroomsNullable(
        value['passkeyAssertionDigest']?.toString(),
      ),
    );
    return envelope.validate().isEmpty ? envelope : null;
  }

  Uint8List signatureTranscript() => Uint8List.fromList(
    utf8.encode(
      jsonEncode(<String, Object?>{
        'context': _ipfsChatroomsNazaIpfsSignatureContext,
        'id': id,
        'roomId': roomId,
        'senderId': senderId,
        'senderKind': senderKind.name,
        'ciphertextCid': ciphertextCid,
        'aadDigest': aadDigest,
        'signatureKeyId': signatureKeyId,
        'sequence': sequence,
        'replyTo': replyTo,
        'attachmentCids': attachmentCids,
        'createdAt': createdAt.toUtc().toIso8601String(),
        'passkeyCredentialId': passkeyCredentialId,
        'passkeyAssertionDigest': passkeyAssertionDigest,
      }),
    ),
  );

  Future<bool> verifyAdvancedSignature() async {
    if (!hasAdvancedSignature || validate().isNotEmpty) return false;
    final publicKey = base64Decode(mlDsa87PublicKey!);
    final signature = base64Decode(mlDsa87Signature!);
    final transcript = signatureTranscript();
    try {
      return await Isolate.run(
        () => MlDsa.verify(
          Uint8List.fromList(publicKey),
          transcript,
          Uint8List.fromList(signature),
          DilithiumParams.mlDsa87,
          ctx: Uint8List.fromList(
            utf8.encode(_ipfsChatroomsNazaIpfsSignatureContext),
          ),
        ),
      );
    } finally {
      publicKey.fillRange(0, publicKey.length, 0);
      signature.fillRange(0, signature.length, 0);
      transcript.fillRange(0, transcript.length, 0);
    }
  }
}

final class NazaIpfsMlDsa87Signer {
  NazaIpfsMlDsa87Signer._(
    this._ipfsChatroomsPublicKey,
    this._ipfsChatroomsPrivateKey,
  );
  final Uint8List _ipfsChatroomsPublicKey;
  final Uint8List _ipfsChatroomsPrivateKey;
  bool _ipfsChatroomsDestroyed = false;

  static Future<NazaIpfsMlDsa87Signer> generate() async {
    final pair = await Isolate.run(
      () => MlDsa.generateKeyPair(DilithiumParams.mlDsa87),
    );
    return NazaIpfsMlDsa87Signer._(pair.$1, pair.$2);
  }

  String get publicKeyBase64 {
    if (_ipfsChatroomsDestroyed)
      throw StateError('Signing key has been destroyed.');
    return base64Encode(_ipfsChatroomsPublicKey);
  }

  Future<NazaChatMessageEnvelope> sign(NazaChatMessageEnvelope envelope) async {
    if (_ipfsChatroomsDestroyed)
      throw StateError('Signing key has been destroyed.');
    if (envelope.validate().isNotEmpty || envelope.hasAdvancedSignature) {
      throw const FormatException(
        'Only a valid unsigned IPFS envelope can be signed.',
      );
    }
    final transcript = envelope.signatureTranscript();
    final privateCopy = Uint8List.fromList(_ipfsChatroomsPrivateKey);
    try {
      final signature = await Isolate.run(() {
        try {
          return MlDsa.sign(
            privateCopy,
            transcript,
            DilithiumParams.mlDsa87,
            ctx: Uint8List.fromList(
              utf8.encode(_ipfsChatroomsNazaIpfsSignatureContext),
            ),
          );
        } finally {
          privateCopy.fillRange(0, privateCopy.length, 0);
        }
      });
      return NazaChatMessageEnvelope(
        id: envelope.id,
        roomId: envelope.roomId,
        senderId: envelope.senderId,
        senderKind: envelope.senderKind,
        ciphertextCid: envelope.ciphertextCid,
        aadDigest: envelope.aadDigest,
        signatureKeyId: envelope.signatureKeyId,
        sequence: envelope.sequence,
        createdAt: envelope.createdAt,
        replyTo: envelope.replyTo,
        attachmentCids: envelope.attachmentCids,
        passkeyCredentialId: envelope.passkeyCredentialId,
        passkeyAssertionDigest: envelope.passkeyAssertionDigest,
        mlDsa87PublicKey: base64Encode(_ipfsChatroomsPublicKey),
        mlDsa87Signature: base64Encode(signature),
      );
    } finally {
      transcript.fillRange(0, transcript.length, 0);
    }
  }

  void destroy() {
    _ipfsChatroomsPrivateKey.fillRange(0, _ipfsChatroomsPrivateKey.length, 0);
    _ipfsChatroomsDestroyed = true;
  }
}

@immutable
final class NazaChatRoomMonitorSnapshot {
  const NazaChatRoomMonitorSnapshot({
    required this.roomId,
    required this.linkState,
    required this.observedAt,
    this.connectedPeers = 0,
    this.subscribed = false,
    this.backlog = 0,
    this.droppedMessages = 0,
    this.relayNodeId,
    this.lastSeen,
    this.lastError,
    this.transportVersion = 'ipfs-pubsub-v1',
  });

  final String roomId;
  final NazaIpfsChatLinkState linkState;
  final int connectedPeers;
  final bool subscribed;
  final int backlog;
  final int droppedMessages;
  final String? relayNodeId;
  final DateTime? lastSeen;
  final String? lastError;
  final String transportVersion;
  final DateTime observedAt;

  List<String> validate() {
    final errors = <String>[];
    if (!_ipfsChatroomsValidId(roomId))
      errors.add('Invalid monitor room reference.');
    if (connectedPeers < 0 || connectedPeers > 100000) {
      errors.add('Peer count is invalid.');
    }
    if (backlog < 0 || backlog > 1000000) errors.add('Backlog is invalid.');
    if (droppedMessages < 0 || droppedMessages > 1000000) {
      errors.add('Dropped-message count is invalid.');
    }
    if (relayNodeId != null && !_ipfsChatroomsValidId(relayNodeId!)) {
      errors.add('Monitor relay reference is invalid.');
    }
    if (lastError != null && lastError!.length > 300) {
      errors.add('Monitor error is too long.');
    }
    return List<String>.unmodifiable(errors);
  }

  Map<String, Object?> toJson() => <String, Object?>{
    'roomId': roomId,
    'linkState': linkState.name,
    'connectedPeers': connectedPeers,
    'subscribed': subscribed,
    'backlog': backlog,
    'droppedMessages': droppedMessages,
    if (relayNodeId != null) 'relayNodeId': relayNodeId,
    if (lastSeen != null) 'lastSeen': lastSeen!.toUtc().toIso8601String(),
    if (lastError != null) 'lastError': lastError,
    'transportVersion': transportVersion,
    'observedAt': observedAt.toUtc().toIso8601String(),
  };

  static NazaChatRoomMonitorSnapshot? fromJson(Object? value) {
    if (value is! Map) return null;
    final observedAt = DateTime.tryParse(value['observedAt']?.toString() ?? '');
    final linkState = _ipfsChatroomsEnumByName<NazaIpfsChatLinkState>(
      value['linkState']?.toString(),
      NazaIpfsChatLinkState.values,
    );
    if (observedAt == null || linkState == null) return null;
    final monitor = NazaChatRoomMonitorSnapshot(
      roomId: value['roomId']?.toString() ?? '',
      linkState: linkState,
      connectedPeers: value['connectedPeers'] is num
          ? (value['connectedPeers'] as num).round()
          : 0,
      subscribed: value['subscribed'] == true,
      backlog: value['backlog'] is num ? (value['backlog'] as num).round() : 0,
      droppedMessages: value['droppedMessages'] is num
          ? (value['droppedMessages'] as num).round()
          : 0,
      relayNodeId: _ipfsChatroomsNullable(value['relayNodeId']?.toString()),
      lastSeen: DateTime.tryParse(value['lastSeen']?.toString() ?? '')?.toUtc(),
      lastError: _ipfsChatroomsNullable(value['lastError']?.toString()),
      transportVersion: _ipfsChatroomsBounded(
        value['transportVersion']?.toString() ?? 'ipfs-pubsub-v1',
        80,
      ),
      observedAt: observedAt.toUtc(),
    );
    return monitor.validate().isEmpty ? monitor : null;
  }
}

