/// Kubo is intentionally opt-in. The default settings do not construct a
/// client, start a process, or open a socket. The RPC endpoint is restricted
/// to a loopback address because Kubo RPC is an admin surface, not a public
/// chat endpoint.
@immutable
final class NazaKuboNodeSettings {
  const NazaKuboNodeSettings({
    this.enabled = false,
    this.apiBaseUrl = 'http://127.0.0.1:5001',
    this.gatewayBaseUrl = 'http://127.0.0.1:8080',
    this.binaryPath = 'ipfs',
    this.remoteNodeId,
    // Every IPFS capability is opt-in.  Kubo itself is already disabled by
    // default; keep its server profile and PubSub transport disabled too.
    this.serverProfile = false,
    this.pubSubEnabled = false,
    this.healthCheckSeconds = 30,
  });

  final bool enabled;
  final String apiBaseUrl;
  final String gatewayBaseUrl;
  final String binaryPath;
  final String? remoteNodeId;
  final bool serverProfile;
  final bool pubSubEnabled;
  final int healthCheckSeconds;

  static const NazaKuboNodeSettings defaults = NazaKuboNodeSettings();

  NazaKuboNodeSettings copyWith({
    bool? enabled,
    String? apiBaseUrl,
    String? gatewayBaseUrl,
    String? binaryPath,
    String? remoteNodeId,
    bool clearRemoteNodeId = false,
    bool? serverProfile,
    bool? pubSubEnabled,
    int? healthCheckSeconds,
  }) {
    return NazaKuboNodeSettings(
      enabled: enabled ?? this.enabled,
      apiBaseUrl: apiBaseUrl ?? this.apiBaseUrl,
      gatewayBaseUrl: gatewayBaseUrl ?? this.gatewayBaseUrl,
      binaryPath: binaryPath ?? this.binaryPath,
      remoteNodeId: clearRemoteNodeId
          ? null
          : remoteNodeId ?? this.remoteNodeId,
      serverProfile: serverProfile ?? this.serverProfile,
      pubSubEnabled: pubSubEnabled ?? this.pubSubEnabled,
      healthCheckSeconds: healthCheckSeconds ?? this.healthCheckSeconds,
    );
  }

  List<String> validate() {
    final errors = <String>[];
    if (!_ipfsChatroomsLoopbackEndpoint(apiBaseUrl)) {
      errors.add('Kubo RPC must use a loopback endpoint or an adapter tunnel.');
    }
    if (!_ipfsChatroomsLoopbackEndpoint(gatewayBaseUrl)) {
      errors.add(
        'Kubo gateway must use a loopback endpoint or an adapter tunnel.',
      );
    }
    if (binaryPath.trim().isEmpty || binaryPath.length > 512) {
      errors.add('Kubo binary path is invalid.');
    }
    if (remoteNodeId != null && !_ipfsChatroomsValidId(remoteNodeId!)) {
      errors.add('Kubo remote node reference is invalid.');
    }
    if (healthCheckSeconds < 5 || healthCheckSeconds > 3600) {
      errors.add('Kubo health interval must be 5–3600 seconds.');
    }
    return List<String>.unmodifiable(errors);
  }

  Map<String, Object?> toJson() => <String, Object?>{
    'format': 'naza-kubo-settings-v1',
    'enabled': enabled,
    'apiBaseUrl': apiBaseUrl,
    'gatewayBaseUrl': gatewayBaseUrl,
    'binaryPath': binaryPath,
    if (remoteNodeId != null) 'remoteNodeId': remoteNodeId,
    'serverProfile': serverProfile,
    'pubSubEnabled': pubSubEnabled,
    'healthCheckSeconds': healthCheckSeconds,
  };

  static NazaKuboNodeSettings fromJson(Object? value) {
    if (value is! Map || value['format'] != 'naza-kubo-settings-v1') {
      return defaults;
    }
    final settings = NazaKuboNodeSettings(
      enabled: value['enabled'] == true,
      apiBaseUrl: value['apiBaseUrl']?.toString() ?? defaults.apiBaseUrl,
      gatewayBaseUrl:
          value['gatewayBaseUrl']?.toString() ?? defaults.gatewayBaseUrl,
      binaryPath: value['binaryPath']?.toString() ?? defaults.binaryPath,
      remoteNodeId: _ipfsChatroomsNullable(value['remoteNodeId']?.toString()),
      // Missing flags must remain disabled.  This prevents an older or
      // hand-written settings blob from enabling an IPFS capability merely
      // by omitting the new field.
      serverProfile: value['serverProfile'] == true,
      pubSubEnabled: value['pubSubEnabled'] == true,
      healthCheckSeconds: value['healthCheckSeconds'] is num
          ? (value['healthCheckSeconds'] as num).round()
          : defaults.healthCheckSeconds,
    );
    return settings.validate().isEmpty ? settings : defaults;
  }
}

final class NazaKuboSettingsStore {
  NazaKuboSettingsStore({NazaSecureDatabase? database})
    : _ipfsChatroomsDatabase = database ?? NazaSecureDatabase.instance;

  static const String _ipfsChatroomsNamespace = 'agentic-ipfs-runtime';
  static const String _ipfsChatroomsKey = 'kubo-settings-v1';

  final NazaSecureDatabase _ipfsChatroomsDatabase;

  Future<NazaKuboNodeSettings> load() async {
    return NazaKuboNodeSettings.fromJson(
      await _ipfsChatroomsDatabase.readJson(
        _ipfsChatroomsNamespace,
        _ipfsChatroomsKey,
      ),
    );
  }

  Future<void> save(NazaKuboNodeSettings settings) async {
    final errors = settings.validate();
    if (errors.isNotEmpty) throw FormatException(errors.join(' '));
    await _ipfsChatroomsDatabase.writeJson(
      _ipfsChatroomsNamespace,
      _ipfsChatroomsKey,
      settings.toJson(),
    );
  }
}

/// Minimal Dart RPC client for an already-running Kubo daemon. It is never
/// created by default and accepts no non-loopback endpoint. Provisioning or
/// starting Kubo remains the responsibility of the local/remote adapter.
final class NazaKuboRpcClient {
  NazaKuboRpcClient({
    required NazaKuboNodeSettings settings,
    NazaHarmGate? harmGate,
  }) : _ipfsChatroomsSettings = settings,
       _ipfsChatroomsHarmGate = harmGate ?? NazaSentinelGuard.instance.gate,
       _ipfsChatroomsHttp = HttpClient() {
    if (!settings.enabled) {
      throw StateError('Kubo backend is disabled in settings.');
    }
    final errors = settings.validate();
    if (errors.isNotEmpty) throw FormatException(errors.join(' '));
    _ipfsChatroomsHttp.connectionTimeout = const Duration(seconds: 8);
    _ipfsChatroomsHttp.idleTimeout = const Duration(seconds: 15);
    _ipfsChatroomsHttp.autoUncompress = false;
  }

  final NazaKuboNodeSettings _ipfsChatroomsSettings;
  final NazaHarmGate _ipfsChatroomsHarmGate;
  final HttpClient _ipfsChatroomsHttp;

  Future<Map<String, Object?>> nodeIdentity() =>
      _ipfsChatroomsPostJson('/api/v0/id');

  void requirePubSubEnabled() => _ipfsChatroomsRequirePubSub();

  Future<List<String>> pubsubPeers(String topic) async {
    _ipfsChatroomsRequirePubSub();
    _ipfsChatroomsRequireTopic(topic);
    final result = await _ipfsChatroomsPostJson(
      '/api/v0/pubsub/peers',
      <String, String>{'arg': topic},
    );
    final values = result['Strings'];
    if (values is! List) return const <String>[];
    return values
        .map((value) => value.toString().trim())
        .where(_ipfsChatroomsValidPeerId)
        .take(1000)
        .toList(growable: false);
  }

  Future<void> publishEnvelope(
    String topic,
    NazaChatMessageEnvelope envelope,
  ) async {
    _ipfsChatroomsRequirePubSub();
    _ipfsChatroomsRequireTopic(topic);
    final errors = envelope.validate();
    if (errors.isNotEmpty) throw FormatException(errors.join(' '));
    final base = Uri.parse(_ipfsChatroomsSettings.apiBaseUrl);
    final uri = _ipfsChatroomsRpcUri(
      base,
      '/api/v0/pubsub/pub',
      <String, String>{'arg': topic},
    );
    await _ipfsChatroomsHarmGate.requireAllowed('ipfs.data.publish');
    final boundary = 'naza${DateTime.now().microsecondsSinceEpoch}';
    final body = utf8.encode(jsonEncode(envelope.toJson()));
    final request = await _ipfsChatroomsHttp.postUrl(uri);
    request.headers.set(HttpHeaders.acceptEncodingHeader, 'identity');
    request.headers.set(
      HttpHeaders.contentTypeHeader,
      'multipart/form-data; boundary=$boundary',
    );
    request.add(utf8.encode('--$boundary\r\n'));
    request.add(
      utf8.encode(
        'Content-Disposition: form-data; name="file"; filename="envelope.json"\r\n',
      ),
    );
    request.add(utf8.encode('Content-Type: application/json\r\n\r\n'));
    request.add(body);
    request.add(utf8.encode('\r\n--$boundary--\r\n'));
    final response = await request.close().timeout(const Duration(seconds: 12));
    final text = await _ipfsChatroomsBoundedResponse(
      response,
    ).timeout(const Duration(seconds: 15));
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw HttpException(
        'Kubo publish failed (${response.statusCode}): ${_ipfsChatroomsSafeDaemonText(text)}',
      );
    }
  }

  Stream<NazaChatMessageEnvelope> subscribe(String topic) async* {
    _ipfsChatroomsRequirePubSub();
    _ipfsChatroomsRequireTopic(topic);
    final base = Uri.parse(_ipfsChatroomsSettings.apiBaseUrl);
    final uri = _ipfsChatroomsRpcUri(
      base,
      '/api/v0/pubsub/sub',
      <String, String>{'arg': topic},
    );
    await _ipfsChatroomsHarmGate.requireAllowed('ipfs.data.pull');
    final request = await _ipfsChatroomsHttp.postUrl(uri);
    request.headers.set(HttpHeaders.acceptEncodingHeader, 'identity');
    final response = await request.close().timeout(const Duration(seconds: 12));
    if (response.statusCode < 200 || response.statusCode >= 300) {
      final text = await _ipfsChatroomsBoundedResponse(response);
      throw HttpException(
        'Kubo subscribe failed (${response.statusCode}): ${_ipfsChatroomsSafeDaemonText(text)}',
      );
    }
    await for (final line in _ipfsChatroomsBoundedUtf8Lines(
      response,
      512 * 1024,
    )) {
      if (line.trim().isEmpty) continue;
      try {
        final decoded = jsonDecode(line);
        final rawData = decoded is Map ? decoded['data'] : decoded;
        final messageData = rawData is String
            ? jsonDecode(utf8.decode(base64.decode(rawData)))
            : rawData;
        final envelope = NazaChatMessageEnvelope.fromJson(messageData);
        if (envelope != null) yield envelope;
      } on FormatException {
        // Ignore malformed transport frames; the monitor/adapter records the
        // failure separately instead of allowing untrusted data to crash UI.
      } on JsonUnsupportedObjectError {
        // Same fail-closed behavior for malformed frames.
      }
    }
  }

  Future<Map<String, Object?>> _ipfsChatroomsPostJson(
    String path, [
    Map<String, String> query = const <String, String>{},
  ]) async {
    final uri = _ipfsChatroomsRpcUri(
      Uri.parse(_ipfsChatroomsSettings.apiBaseUrl),
      path,
      query,
    );
    await _ipfsChatroomsHarmGate.requireAllowed(
      _ipfsChatroomsSentinelCommandForPath(path),
    );
    final request = await _ipfsChatroomsHttp.postUrl(uri);
    request.headers.set(HttpHeaders.acceptEncodingHeader, 'identity');
    request.headers.contentType = ContentType.json;
    final response = await request.close().timeout(const Duration(seconds: 12));
    final text = await _ipfsChatroomsBoundedResponse(
      response,
    ).timeout(const Duration(seconds: 15));
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw HttpException(
        'Kubo RPC failed (${response.statusCode}): ${_ipfsChatroomsSafeDaemonText(text)}',
      );
    }
    final decoded = jsonDecode(text);
    if (decoded is! Map)
      throw const FormatException('Kubo response was not an object.');
    return <String, Object?>{
      for (final entry in decoded.entries) entry.key.toString(): entry.value,
    };
  }

  Future<String> _ipfsChatroomsBoundedResponse(
    HttpClientResponse response,
  ) async {
    final declared = response.contentLength;
    if (declared > 1024 * 1024) {
      throw const FormatException('Kubo response exceeded the bounded limit.');
    }
    final bytes = <int>[];
    await for (final chunk in response) {
      if (bytes.length + chunk.length > 1024 * 1024) {
        throw const FormatException(
          'Kubo response exceeded the bounded limit.',
        );
      }
      bytes.addAll(chunk);
    }
    return utf8.decode(bytes, allowMalformed: false);
  }

  void _ipfsChatroomsRequirePubSub() {
    if (!_ipfsChatroomsSettings.pubSubEnabled) {
      throw StateError('Kubo PubSub transport is disabled in settings.');
    }
  }

  void _ipfsChatroomsRequireTopic(String topic) {
    if (!_ipfsChatroomsValidTopic(topic))
      throw const FormatException('Invalid chat topic.');
  }

  void close() => _ipfsChatroomsHttp.close(force: true);

  static String _ipfsChatroomsSentinelCommandForPath(String path) =>
      switch (path) {
        '/api/v0/id' => 'ipfs.node.identity',
        '/api/v0/pubsub/peers' => 'ipfs.pubsub.peers',
        _ => 'ipfs.rpc.request',
      };

  static String _ipfsChatroomsSafeDaemonText(String value) =>
      NazaBoundarySanitizer.remoteText(value, maxCharacters: 600);

  static Stream<String> _ipfsChatroomsBoundedUtf8Lines(
    Stream<List<int>> source,
    int maximumLineBytes,
  ) async* {
    var bytes = <int>[];
    var discarding = false;
    await for (final chunk in source) {
      for (final byte in chunk) {
        if (byte == 0x0A) {
          if (!discarding && bytes.isNotEmpty) {
            yield utf8.decode(bytes, allowMalformed: false);
          }
          bytes = <int>[];
          discarding = false;
          continue;
        }
        if (discarding) continue;
        if (bytes.length >= maximumLineBytes) {
          bytes = <int>[];
          discarding = true;
          continue;
        }
        bytes.add(byte);
      }
    }
    if (!discarding && bytes.isNotEmpty) {
      yield utf8.decode(bytes, allowMalformed: false);
    }
  }
}

/// Adapter implementation using the Kubo RPC client. Construction is opt-in;
/// no chatroom calls happen until `connect` is invoked with a fresh approval.
final class NazaKuboChatTransport implements NazaIpfsChatTransport {
  NazaKuboChatTransport({
    required NazaKuboNodeSettings settings,
    NazaHarmGate? harmGate,
  }) : _ipfsChatroomsClient = NazaKuboRpcClient(
         settings: settings,
         harmGate: harmGate,
       );

  final NazaKuboRpcClient _ipfsChatroomsClient;
  final Map<String, NazaChatRoom> _ipfsChatroomsRooms =
      <String, NazaChatRoom>{};

  @override
  Future<void> connect(
    NazaChatRoom room, {
    required NazaChatDispatchApproval approval,
  }) async {
    _ipfsChatroomsRequireApproval(room, approval);
    _ipfsChatroomsClient.requirePubSubEnabled();
    if (room.state != NazaChatRoomState.active) {
      throw StateError('Only active chatrooms can connect.');
    }
    await _ipfsChatroomsClient.nodeIdentity();
    _ipfsChatroomsRooms[room.id] = room;
  }

  @override
  Future<void> publish(
    NazaChatMessageEnvelope envelope, {
    required NazaChatDispatchApproval approval,
  }) async {
    final room = _ipfsChatroomsRooms[envelope.roomId];
    if (room == null) throw StateError('Chatroom is not connected.');
    _ipfsChatroomsRequireApproval(room, approval);
    if (envelope.senderKind != room.kind) {
      throw StateError('Envelope sender kind does not match the room.');
    }
    if (room.requiresSignedReceipts &&
        !await envelope.verifyAdvancedSignature()) {
      throw StateError(
        'This room requires a valid ML-DSA-87 envelope signature.',
      );
    }
    await _ipfsChatroomsClient.publishEnvelope(room.topic, envelope);
  }

  @override
  Stream<NazaChatMessageEnvelope> subscribe(
    String roomId, {
    required NazaChatDispatchApproval approval,
  }) async* {
    final room = _ipfsChatroomsRooms[roomId];
    if (room == null) throw StateError('Chatroom is not connected.');
    _ipfsChatroomsRequireApproval(room, approval);
    await for (final envelope in _ipfsChatroomsClient.subscribe(room.topic)) {
      _ipfsChatroomsRequireApproval(room, approval);
      if (envelope.roomId != room.id || envelope.senderKind != room.kind) {
        continue;
      }
      if (room.requiresSignedReceipts &&
          !await envelope.verifyAdvancedSignature()) {
        continue;
      }
      yield envelope;
    }
  }

  @override
  Future<NazaChatRoomMonitorSnapshot> probe(
    NazaChatRoom room, {
    required NazaChatDispatchApproval approval,
  }) async {
    _ipfsChatroomsRequireApproval(room, approval);
    final identity = await _ipfsChatroomsClient.nodeIdentity();
    final peers = await _ipfsChatroomsClient.pubsubPeers(room.topic);
    return NazaChatRoomMonitorSnapshot(
      roomId: room.id,
      linkState: NazaIpfsChatLinkState.online,
      connectedPeers: peers.length,
      subscribed: _ipfsChatroomsRooms.containsKey(room.id),
      relayNodeId: room.relayNodeId,
      lastSeen: DateTime.now().toUtc(),
      observedAt: DateTime.now().toUtc(),
      transportVersion: 'kubo-rpc-${identity['AgentVersion'] ?? 'unknown'}',
    );
  }

  @override
  Future<void> disconnect(String roomId) async {
    _ipfsChatroomsRooms.remove(roomId);
  }

  void close() => _ipfsChatroomsClient.close();

  static void _ipfsChatroomsRequireApproval(
    NazaChatRoom room,
    NazaChatDispatchApproval approval,
  ) {
    final now = DateTime.now().toUtc();
    final lifetime = approval.expiresAt.difference(approval.approvedAt);
    if (!_ipfsChatroomsValidId(approval.approvalId) ||
        approval.approvedAt.isAfter(now) ||
        now.difference(approval.approvedAt) > const Duration(minutes: 5) ||
        !approval.expiresAt.isAfter(approval.approvedAt) ||
        lifetime > const Duration(minutes: 10) ||
        !approval.isActive) {
      throw StateError('Chat dispatch approval is invalid or expired.');
    }
    if (room.state != NazaChatRoomState.active) {
      throw StateError('Only active chatrooms can dispatch.');
    }
    if (room.publicDiscovery && !approval.publicExposureApproved) {
      throw StateError('Public chatroom exposure was not approved.');
    }
  }
}

/// Implemented by a separately attested node adapter. The default Flutter
/// surface deliberately has no HTTP client for Kubo RPC and no ability to
/// publish messages or expose admin ports.
abstract interface class NazaIpfsChatTransport {
  Future<void> connect(
    NazaChatRoom room, {
    required NazaChatDispatchApproval approval,
  });

  Future<void> publish(
    NazaChatMessageEnvelope envelope, {
    required NazaChatDispatchApproval approval,
  });

  Stream<NazaChatMessageEnvelope> subscribe(
    String roomId, {
    required NazaChatDispatchApproval approval,
  });

  Future<NazaChatRoomMonitorSnapshot> probe(
    NazaChatRoom room, {
    required NazaChatDispatchApproval approval,
  });

  Future<void> disconnect(String roomId);
}

final class NazaIpfsChatRoomStore {
  NazaIpfsChatRoomStore({NazaSecureDatabase? database})
    : _ipfsChatroomsDatabase = database ?? NazaSecureDatabase.instance;

  static const String _ipfsChatroomsNamespace = 'agentic-ipfs-chatrooms';
  static const String _ipfsChatroomsRoomsKey = 'rooms-v1';
  static const String _ipfsChatroomsMessagesKey = 'messages-v1';
  static const String _ipfsChatroomsMonitorsKey = 'monitors-v1';
  static const int maxRooms = 64;
  static const int maxMessages = 2000;
  static const int maxMonitors = 64;

  final NazaSecureDatabase _ipfsChatroomsDatabase;
  Future<void> _ipfsChatroomsMessageMutationTail = Future<void>.value();

  Future<List<NazaChatRoom>> loadRooms() async {
    final raw = await _ipfsChatroomsDatabase.readJson(
      _ipfsChatroomsNamespace,
      _ipfsChatroomsRoomsKey,
    );
    if (raw is! List) return const <NazaChatRoom>[];
    return List<NazaChatRoom>.unmodifiable(
      raw.map(NazaChatRoom.fromJson).whereType<NazaChatRoom>().take(maxRooms),
    );
  }

  Future<List<NazaChatMessageEnvelope>> loadMessages(String roomId) async {
    final raw = await _ipfsChatroomsDatabase.readJson(
      _ipfsChatroomsNamespace,
      _ipfsChatroomsMessagesKey,
    );
    if (raw is! List) return const <NazaChatMessageEnvelope>[];
    return List<NazaChatMessageEnvelope>.unmodifiable(
      raw
          .map(NazaChatMessageEnvelope.fromJson)
          .whereType<NazaChatMessageEnvelope>()
          .where((message) => message.roomId == roomId)
          .take(maxMessages),
    );
  }

  Future<NazaChatRoomMonitorSnapshot?> loadMonitor(String roomId) async {
    final raw = await _ipfsChatroomsDatabase.readJson(
      _ipfsChatroomsNamespace,
      _ipfsChatroomsMonitorsKey,
    );
    if (raw is! List) return null;
    final matches = raw
        .map(NazaChatRoomMonitorSnapshot.fromJson)
        .whereType<NazaChatRoomMonitorSnapshot>()
        .where((monitor) => monitor.roomId == roomId);
    return matches.isEmpty ? null : matches.first;
  }

  Future<void> saveRoom(NazaChatRoom room) async {
    _ipfsChatroomsThrowIfInvalid(room.validate());
    final current = await loadRooms();
    final next = <NazaChatRoom>[
      ...current.where((item) => item.id != room.id),
      room,
    ];
    final bounded = next.length <= maxRooms
        ? next
        : next.sublist(next.length - maxRooms);
    await _ipfsChatroomsDatabase.writeJson(
      _ipfsChatroomsNamespace,
      _ipfsChatroomsRoomsKey,
      bounded.map((item) => item.toJson()).toList(growable: false),
    );
  }

  Future<void> appendMessage(NazaChatMessageEnvelope message) {
    final completer = Completer<void>();
    _ipfsChatroomsMessageMutationTail = _ipfsChatroomsMessageMutationTail.then((
      _,
    ) async {
      try {
        await _ipfsChatroomsAppendMessageNow(message);
        completer.complete();
      } catch (error, stackTrace) {
        completer.completeError(error, stackTrace);
      }
    });
    return completer.future;
  }

  Future<void> _ipfsChatroomsAppendMessageNow(
    NazaChatMessageEnvelope message,
  ) async {
    _ipfsChatroomsThrowIfInvalid(message.validate());
    final rooms = await loadRooms();
    final roomMatches = rooms.where((room) => room.id == message.roomId);
    if (roomMatches.isEmpty ||
        roomMatches.first.state != NazaChatRoomState.active) {
      throw const FormatException('Chatroom is not active.');
    }
    if (roomMatches.first.kind != message.senderKind) {
      throw const FormatException('Message sender kind does not match room.');
    }
    final raw = await _ipfsChatroomsDatabase.readJson(
      _ipfsChatroomsNamespace,
      _ipfsChatroomsMessagesKey,
    );
    final current = raw is List
        ? raw
              .map(NazaChatMessageEnvelope.fromJson)
              .whereType<NazaChatMessageEnvelope>()
              .toList()
        : <NazaChatMessageEnvelope>[];
    final sameId = current.where((item) => item.id == message.id);
    if (sameId.isNotEmpty) {
      if (jsonEncode(sameId.first.toJson()) != jsonEncode(message.toJson())) {
        throw const FormatException(
          'A message identity cannot be rebound to different ciphertext.',
        );
      }
      return;
    }
    if (current.any(
      (item) =>
          item.roomId == message.roomId &&
          item.senderId == message.senderId &&
          item.sequence == message.sequence,
    )) {
      throw const FormatException(
        'A sender sequence cannot identify multiple messages.',
      );
    }
    final next = <NazaChatMessageEnvelope>[...current, message];
    final bounded = next.length <= maxMessages
        ? next
        : next.sublist(next.length - maxMessages);
    await _ipfsChatroomsDatabase.writeJson(
      _ipfsChatroomsNamespace,
      _ipfsChatroomsMessagesKey,
      bounded.map((item) => item.toJson()).toList(growable: false),
    );
  }

  Future<void> saveMonitor(NazaChatRoomMonitorSnapshot monitor) async {
    _ipfsChatroomsThrowIfInvalid(monitor.validate());
    final raw = await _ipfsChatroomsDatabase.readJson(
      _ipfsChatroomsNamespace,
      _ipfsChatroomsMonitorsKey,
    );
    final current = raw is List
        ? raw
              .map(NazaChatRoomMonitorSnapshot.fromJson)
              .whereType<NazaChatRoomMonitorSnapshot>()
              .toList()
        : <NazaChatRoomMonitorSnapshot>[];
    final next = <NazaChatRoomMonitorSnapshot>[
      ...current.where((item) => item.roomId != monitor.roomId),
      monitor,
    ];
    final bounded = next.length <= maxMonitors
        ? next
        : next.sublist(next.length - maxMonitors);
    await _ipfsChatroomsDatabase.writeJson(
      _ipfsChatroomsNamespace,
      _ipfsChatroomsMonitorsKey,
      bounded.map((item) => item.toJson()).toList(growable: false),
    );
  }

  static void _ipfsChatroomsThrowIfInvalid(List<String> errors) {
    if (errors.isNotEmpty) throw FormatException(errors.join(' '));
  }
}

String _ipfsChatroomsBounded(String value, int max) {
  return NazaBoundarySanitizer.databaseText(value, maxCharacters: max);
}

String? _ipfsChatroomsNullable(String? value) {
  final clean = value?.trim() ?? '';
  return clean.isEmpty ? null : _ipfsChatroomsBounded(clean, 300);
}

bool _ipfsChatroomsValidId(String value) =>
    RegExp(r'^[A-Za-z0-9][A-Za-z0-9._-]{1,95}$').hasMatch(value.trim());

bool _ipfsChatroomsValidLabel(String value, int max) {
  final raw = value.trim();
  final clean = NazaBoundarySanitizer.databaseText(value, maxCharacters: max);
  return clean.isNotEmpty && raw.length <= max && clean == raw;
}

bool _ipfsChatroomsValidTopic(String value) {
  final clean = value.trim();
  return clean.length >= 10 &&
      clean.length <= 200 &&
      clean.startsWith('naza-chat/v1/') &&
      !clean.contains(' ');
}

bool _ipfsChatroomsValidIpnsName(String value) {
  final clean = value.trim();
  return clean.length >= 10 &&
      clean.length <= 128 &&
      RegExp(r'^[A-Za-z0-9._-]+$').hasMatch(clean);
}

bool _ipfsChatroomsValidCid(String value) {
  final clean = value.trim();
  return clean.length >= 10 &&
      clean.length <= 128 &&
      RegExp(r'^[A-Za-z0-9]+$').hasMatch(clean);
}

bool _ipfsChatroomsValidDigest(String value) {
  return RegExp(r'^(?:sha256:)?[a-fA-F0-9]{32,128}$').hasMatch(value.trim());
}

bool _ipfsChatroomsValidBase64Length(String value, int expectedLength) {
  if (value.length > ((expectedLength + 2) ~/ 3) * 4 + 4) return false;
  try {
    return base64Decode(value).length == expectedLength;
  } on FormatException {
    return false;
  }
}

bool _ipfsChatroomsValidKeyReference(String value) {
  final clean = value.trim();
  return clean.length >= 8 &&
      clean.length <= 160 &&
      RegExp(r'^[A-Za-z0-9._:+/-]+$').hasMatch(clean);
}

bool _ipfsChatroomsValidPasskeyCredential(String value) {
  final clean = value.trim();
  return clean.length >= 8 &&
      clean.length <= 512 &&
      RegExp(r'^[A-Za-z0-9_-]+$').hasMatch(clean);
}

bool _ipfsChatroomsValidPeerId(String value) {
  final clean = value.trim();
  return clean.length >= 10 &&
      clean.length <= 128 &&
      RegExp(r'^[A-Za-z0-9]+$').hasMatch(clean);
}

List<String> _ipfsChatroomsStrings(Object? value, int max) {
  if (value is! List) return const <String>[];
  return List<String>.unmodifiable(
    value
        .map((entry) => entry.toString().trim())
        .where((entry) => entry.isNotEmpty)
        .take(max),
  );
}

T? _ipfsChatroomsEnumByName<T extends Enum>(String? value, List<T> values) {
  if (value == null) return null;
  for (final candidate in values) {
    if (candidate.name == value) return candidate;
  }
  return null;
}

bool _ipfsChatroomsLoopbackEndpoint(String value) {
  final uri = Uri.tryParse(value.trim());
  if (uri == null || (uri.scheme != 'http' && uri.scheme != 'https')) {
    return false;
  }
  if (uri.userInfo.isNotEmpty ||
      uri.query.isNotEmpty ||
      uri.fragment.isNotEmpty) {
    return false;
  }
  final host = uri.host.toLowerCase();
  return host == '127.0.0.1' || host == '::1';
}

Uri _ipfsChatroomsRpcUri(Uri base, String path, Map<String, String> query) {
  final basePath = base.path.endsWith('/')
      ? base.path.substring(0, base.path.length - 1)
      : base.path;
  return base.replace(
    path: '$basePath$path',
    queryParameters: query.isEmpty ? null : query,
  );
}

