// SOURCE SECTION: lib/audio/encrypted_voice_cache.dart
// ============================================================================

// LLM-CONTEXT:BEGIN
// FILE: lib/audio/encrypted_voice_cache.dart
// ROLE: Owns authenticated encrypted persistence and recall for generated speech audio.
// DOMAIN: audio
// SECURITY-INVARIANT: Never persist voice bytes outside the unlocked AES-GCM vault; verify request and audio hashes before recall.
// CHANGE-GUARD: Preserve bounded retention, authenticated identity checks, strict WAV validation, and fail-closed parsing.
// DOCS: See /SECURITY.md and /lib/security/secure_database.dart.
// LLM-CONTEXT:END

/// An authenticated voice artifact recalled from the encrypted vault.
final class NazaCachedVoice {
  const NazaCachedVoice({
    required this.requestHash,
    required this.messageHash,
    required this.audioSha256,
    required this.voice,
    required this.model,
    required this.speed,
    required this.createdAt,
    required this.lastPlayedAt,
    required this.playCount,
    required this.wav,
  });

  final String requestHash;
  final String messageHash;
  final String audioSha256;
  final String voice;
  final String model;
  final double speed;
  final DateTime createdAt;
  final DateTime? lastPlayedAt;
  final int playCount;
  final Uint8List wav;
}

/// Bounded encrypted cache for OpenAI speech responses.
///
/// The cache stores no plaintext message text. A SHA-256 request identity
/// covers the normalized message, instructions, model, voice, speed and output
/// format. Voice bytes are independently SHA-256 checked after the vault's
/// AES-256-GCM authentication succeeds.
final class NazaEncryptedVoiceCache {
  NazaEncryptedVoiceCache({
    NazaSecureDatabase? database,
    this.maximumEntries = 64,
    this.maximumTotalAudioBytes = 32 * 1024 * 1024,
    this.maximumEntryBytes = 16 * 1024 * 1024,
    DateTime Function()? clock,
  }) : _encryptedVoiceCacheDatabase = database ?? NazaSecureDatabase.instance,
       _encryptedVoiceCacheClock = clock ?? DateTime.now {
    if (maximumEntries < 1 || maximumEntries > 512) {
      throw ArgumentError.value(
        maximumEntries,
        'maximumEntries',
        'Use a voice-cache limit from 1 to 512.',
      );
    }
    if (maximumEntryBytes < 44 || maximumEntryBytes > 64 * 1024 * 1024) {
      throw ArgumentError.value(
        maximumEntryBytes,
        'maximumEntryBytes',
        'Use a per-entry limit from 44 bytes to 64 MiB.',
      );
    }
    if (maximumTotalAudioBytes < maximumEntryBytes ||
        maximumTotalAudioBytes > 256 * 1024 * 1024) {
      throw ArgumentError.value(
        maximumTotalAudioBytes,
        'maximumTotalAudioBytes',
        'The total cache budget must cover one entry and not exceed 256 MiB.',
      );
    }
  }

  static final NazaEncryptedVoiceCache instance = NazaEncryptedVoiceCache();

  static const String namespace = 'naza-encrypted-voice-cache-v1';
  static const String indexKey = 'index';
  static const String recordFormat = 'naza-encrypted-voice-record-v1';
  static const String indexFormat = 'naza-encrypted-voice-index-v1';
  static const String _encryptedVoiceCacheEntryPrefix = 'entry:';
  static const int _encryptedVoiceCacheMaximumMessageCharacters = 200000;
  static const int _encryptedVoiceCacheMaximumInstructionsCharacters = 8000;

  final NazaSecureDatabase _encryptedVoiceCacheDatabase;
  final int maximumEntries;
  final int maximumTotalAudioBytes;
  final int maximumEntryBytes;
  final DateTime Function() _encryptedVoiceCacheClock;
  Future<void> _encryptedVoiceCacheTail = Future<void>.value();

  bool get isUnlocked => _encryptedVoiceCacheDatabase.isUnlocked;

  /// Normalizes text exactly as the speech request chunker does.
  static String normalizeText(String value) {
    final normalized = value.replaceAll(RegExp(r'\s+'), ' ').trim();
    if (normalized.isEmpty ||
        normalized.runes.length >
            _encryptedVoiceCacheMaximumMessageCharacters) {
      throw ArgumentError.value(
        value.length,
        'text',
        'Speech text must contain 1-$_encryptedVoiceCacheMaximumMessageCharacters characters.',
      );
    }
    return normalized;
  }

  static String requestHash({
    required String text,
    required String voice,
    required String model,
    required String instructions,
    required double speed,
  }) {
    return _encryptedVoiceCacheIdentity(
      text: text,
      voice: voice,
      model: model,
      instructions: instructions,
      speed: speed,
    ).requestHash;
  }

  Future<NazaCachedVoice?> recall({
    required String text,
    required String voice,
    required String model,
    required String instructions,
    required double speed,
  }) {
    final identity = _encryptedVoiceCacheIdentity(
      text: text,
      voice: voice,
      model: model,
      instructions: instructions,
      speed: speed,
    );
    return _encryptedVoiceCacheEnqueue(
      () => _encryptedVoiceCacheRecallNow(identity),
    );
  }

  Future<NazaCachedVoice> store({
    required String text,
    required String voice,
    required String model,
    required String instructions,
    required double speed,
    required Uint8List wav,
  }) {
    final identity = _encryptedVoiceCacheIdentity(
      text: text,
      voice: voice,
      model: model,
      instructions: instructions,
      speed: speed,
    );
    final copy = Uint8List.fromList(wav);
    _encryptedVoiceCacheValidateWav(copy, maximumBytes: maximumEntryBytes);
    return _encryptedVoiceCacheEnqueue(
      () => _encryptedVoiceCacheStoreNow(identity, copy),
    );
  }

  Future<void> recordPlayback(String requestHash) {
    _encryptedVoiceCacheValidateHash(requestHash, 'requestHash');
    return _encryptedVoiceCacheEnqueue(() async {
      _encryptedVoiceCacheRequireUnlocked();
      final index = await _encryptedVoiceCacheReadIndex();
      final mutation = index.withPlayback(
        requestHash,
        _encryptedVoiceCacheClock().toUtc(),
      );
      if (mutation == null) {
        throw const NazaVaultException(
          'voice_cache_incomplete',
          'The encrypted voice record is missing from its authenticated index.',
        );
      }
      await _encryptedVoiceCacheDatabase.writeJson(
        namespace,
        indexKey,
        mutation.toJson(),
      );
    });
  }

  Future<void> clear() {
    return _encryptedVoiceCacheEnqueue(() async {
      _encryptedVoiceCacheRequireUnlocked();
      final index = await _encryptedVoiceCacheReadIndex();
      for (final entry in index.entries) {
        await _encryptedVoiceCacheDatabase.delete(
          namespace,
          _encryptedVoiceCacheEntryKey(entry.requestHash),
        );
      }
      await _encryptedVoiceCacheDatabase.delete(namespace, indexKey);
    });
  }

  Future<NazaCachedVoice?> _encryptedVoiceCacheRecallNow(
    _EncryptedVoiceCacheVoiceRequestIdentity identity,
  ) async {
    _encryptedVoiceCacheRequireUnlocked();
    final index = await _encryptedVoiceCacheReadIndex();
    final indexEntry = index.byRequestHash(identity.requestHash);
    if (indexEntry == null) return null;

    final raw = await _encryptedVoiceCacheDatabase.readJson(
      namespace,
      _encryptedVoiceCacheEntryKey(identity.requestHash),
    );
    if (raw == null) {
      throw const NazaVaultException(
        'voice_cache_incomplete',
        'The authenticated voice index references a missing encrypted record.',
      );
    }
    return _encryptedVoiceCacheDecodeRecord(raw, identity, indexEntry);
  }

  Future<NazaCachedVoice> _encryptedVoiceCacheStoreNow(
    _EncryptedVoiceCacheVoiceRequestIdentity identity,
    Uint8List wav,
  ) async {
    _encryptedVoiceCacheRequireUnlocked();
    final now = _encryptedVoiceCacheClock().toUtc();
    final audioHash = _encryptedVoiceCacheSha256(wav);
    final index = await _encryptedVoiceCacheReadIndex();
    final entry = _EncryptedVoiceCacheVoiceIndexEntry(
      requestHash: identity.requestHash,
      audioSha256: audioHash,
      voice: identity.voice,
      model: identity.model,
      bytes: wav.length,
      createdAt: now,
      lastPlayedAt: null,
      playCount: 0,
    );
    final mutation = index.withStored(
      entry,
      maximumEntries: maximumEntries,
      maximumTotalBytes: maximumTotalAudioBytes,
    );
    final record = <String, Object?>{
      'format': recordFormat,
      'requestHash': identity.requestHash,
      'messageHash': identity.messageHash,
      'instructionsHash': identity.instructionsHash,
      'audioSha256': audioHash,
      'voice': identity.voice,
      'model': identity.model,
      'speed': identity.speed,
      'bytes': wav.length,
      'createdAt': now.toIso8601String(),
      'wavBase64': base64Encode(wav),
    };
    await _encryptedVoiceCacheDatabase.importRecords(
      <NazaVaultRecordKey, Object?>{
        NazaVaultRecordKey(
          namespace,
          _encryptedVoiceCacheEntryKey(identity.requestHash),
        ): record,
        const NazaVaultRecordKey(namespace, indexKey): mutation.index.toJson(),
      },
    );
    for (final hash in mutation.prunedRequestHashes) {
      await _encryptedVoiceCacheDatabase.delete(
        namespace,
        _encryptedVoiceCacheEntryKey(hash),
      );
    }
    return NazaCachedVoice(
      requestHash: identity.requestHash,
      messageHash: identity.messageHash,
      audioSha256: audioHash,
      voice: identity.voice,
      model: identity.model,
      speed: identity.speed,
      createdAt: now,
      lastPlayedAt: null,
      playCount: 0,
      wav: Uint8List.fromList(wav),
    );
  }

  NazaCachedVoice _encryptedVoiceCacheDecodeRecord(
    Object raw,
    _EncryptedVoiceCacheVoiceRequestIdentity identity,
    _EncryptedVoiceCacheVoiceIndexEntry indexEntry,
  ) {
    if (raw is! Map || raw['format'] != recordFormat) {
      throw const NazaVaultException(
        'invalid_voice_cache',
        'An encrypted voice record has an unsupported format.',
      );
    }
    final requestHash = raw['requestHash']?.toString() ?? '';
    final messageHash = raw['messageHash']?.toString() ?? '';
    final instructionsHash = raw['instructionsHash']?.toString() ?? '';
    final audioHash = raw['audioSha256']?.toString() ?? '';
    final voice = raw['voice']?.toString() ?? '';
    final model = raw['model']?.toString() ?? '';
    final speed = (raw['speed'] as num?)?.toDouble();
    final byteLength = (raw['bytes'] as num?)?.toInt() ?? -1;
    final encoded = raw['wavBase64'];
    final createdAt = DateTime.tryParse(raw['createdAt']?.toString() ?? '');
    if (!_encryptedVoiceCacheConstantTimeEquals(
          requestHash,
          identity.requestHash,
        ) ||
        !_encryptedVoiceCacheConstantTimeEquals(
          messageHash,
          identity.messageHash,
        ) ||
        !_encryptedVoiceCacheConstantTimeEquals(
          instructionsHash,
          identity.instructionsHash,
        ) ||
        !_encryptedVoiceCacheConstantTimeEquals(
          audioHash,
          indexEntry.audioSha256,
        ) ||
        voice != identity.voice ||
        indexEntry.voice != identity.voice ||
        model != identity.model ||
        indexEntry.model != identity.model ||
        speed != identity.speed ||
        byteLength != indexEntry.bytes ||
        createdAt == null ||
        createdAt.toUtc() != indexEntry.createdAt ||
        encoded is! String ||
        encoded.length >
            _encryptedVoiceCacheMaximumBase64Characters(maximumEntryBytes)) {
      throw const NazaVaultException(
        'invalid_voice_cache',
        'An encrypted voice record failed identity or bounds validation.',
      );
    }

    Uint8List wav;
    try {
      wav = Uint8List.fromList(base64Decode(encoded));
    } on FormatException catch (error) {
      throw NazaVaultException(
        'invalid_voice_cache',
        'An encrypted voice record contains malformed audio encoding.',
        error,
      );
    }
    _encryptedVoiceCacheValidateWav(wav, maximumBytes: maximumEntryBytes);
    if (wav.length != byteLength ||
        !_encryptedVoiceCacheConstantTimeEquals(
          _encryptedVoiceCacheSha256(wav),
          audioHash,
        )) {
      throw const NazaVaultException(
        'voice_hash_mismatch',
        'The recalled voice failed its SHA-256 integrity check.',
      );
    }
    return NazaCachedVoice(
      requestHash: requestHash,
      messageHash: messageHash,
      audioSha256: audioHash,
      voice: voice,
      model: model,
      speed: speed!,
      createdAt: createdAt.toUtc(),
      lastPlayedAt: indexEntry.lastPlayedAt,
      playCount: indexEntry.playCount,
      wav: wav,
    );
  }

  Future<_EncryptedVoiceCacheVoiceCacheIndex>
  _encryptedVoiceCacheReadIndex() async {
    final raw = await _encryptedVoiceCacheDatabase.readJson(
      namespace,
      indexKey,
    );
    if (raw == null)
      return const _EncryptedVoiceCacheVoiceCacheIndex(
        <_EncryptedVoiceCacheVoiceIndexEntry>[],
      );
    return _EncryptedVoiceCacheVoiceCacheIndex.fromJson(raw);
  }

  void _encryptedVoiceCacheRequireUnlocked() {
    if (!_encryptedVoiceCacheDatabase.isUnlocked) {
      throw const NazaVaultException(
        'voice_cache_locked',
        'Unlock the encrypted vault before using Read Aloud.',
      );
    }
  }

  Future<T> _encryptedVoiceCacheEnqueue<T>(Future<T> Function() operation) {
    final queued = _encryptedVoiceCacheTail.then((_) => operation());
    _encryptedVoiceCacheTail = queued.then<void>(
      (_) {},
      onError: (Object _, StackTrace _) {},
    );
    return queued;
  }

  static _EncryptedVoiceCacheVoiceRequestIdentity _encryptedVoiceCacheIdentity({
    required String text,
    required String voice,
    required String model,
    required String instructions,
    required double speed,
  }) {
    final normalized = normalizeText(text);
    final cleanVoice = _encryptedVoiceCacheValidateParameter(
      voice,
      'voice',
      maximum: 80,
    );
    final cleanModel = _encryptedVoiceCacheValidateParameter(
      model,
      'model',
      maximum: 160,
    );
    if (instructions.isEmpty ||
        instructions.runes.length >
            _encryptedVoiceCacheMaximumInstructionsCharacters ||
        instructions.contains('\u0000')) {
      throw ArgumentError.value(
        instructions.length,
        'instructions',
        'Speech instructions must contain 1-$_encryptedVoiceCacheMaximumInstructionsCharacters characters.',
      );
    }
    if (!speed.isFinite || speed < 0.25 || speed > 4) {
      throw ArgumentError.value(
        speed,
        'speed',
        'Speech speed must be finite and between 0.25 and 4.',
      );
    }
    final messageHash = _encryptedVoiceCacheSha256(utf8.encode(normalized));
    final instructionsHash = _encryptedVoiceCacheSha256(
      utf8.encode(instructions),
    );
    final requestHash = _encryptedVoiceCacheSha256(
      utf8.encode(
        jsonEncode(<Object?>[
          'naza-reading-request-v1',
          messageHash,
          instructionsHash,
          cleanVoice,
          cleanModel,
          speed,
          'wav',
        ]),
      ),
    );
    return _EncryptedVoiceCacheVoiceRequestIdentity(
      requestHash: requestHash,
      messageHash: messageHash,
      instructionsHash: instructionsHash,
      voice: cleanVoice,
      model: cleanModel,
      speed: speed,
    );
  }

  static String _encryptedVoiceCacheValidateParameter(
    String value,
    String name, {
    required int maximum,
  }) {
    if (value.isEmpty ||
        value != value.trim() ||
        value.length > maximum ||
        value.contains('\u0000')) {
      throw ArgumentError.value(value, name, 'Invalid speech $name.');
    }
    return value;
  }

  static String _encryptedVoiceCacheEntryKey(String requestHash) {
    _encryptedVoiceCacheValidateHash(requestHash, 'requestHash');
    return '$_encryptedVoiceCacheEntryPrefix$requestHash';
  }
}

final class _EncryptedVoiceCacheVoiceRequestIdentity {
  const _EncryptedVoiceCacheVoiceRequestIdentity({
    required this.requestHash,
    required this.messageHash,
    required this.instructionsHash,
    required this.voice,
    required this.model,
    required this.speed,
  });

  final String requestHash;
  final String messageHash;
  final String instructionsHash;
  final String voice;
  final String model;
  final double speed;
}

final class _EncryptedVoiceCacheVoiceCacheIndex {
  const _EncryptedVoiceCacheVoiceCacheIndex(this.entries);

  factory _EncryptedVoiceCacheVoiceCacheIndex.fromJson(Object raw) {
    if (raw is! Map || raw['format'] != NazaEncryptedVoiceCache.indexFormat) {
      throw const NazaVaultException(
        'invalid_voice_cache_index',
        'The encrypted voice index has an unsupported format.',
      );
    }
    final rawEntries = raw['entries'];
    if (rawEntries is! List || rawEntries.length > 512) {
      throw const NazaVaultException(
        'invalid_voice_cache_index',
        'The encrypted voice index exceeds its safe entry budget.',
      );
    }
    final entries = <_EncryptedVoiceCacheVoiceIndexEntry>[];
    final hashes = <String>{};
    for (final rawEntry in rawEntries) {
      final entry = _EncryptedVoiceCacheVoiceIndexEntry.fromJson(rawEntry);
      if (!hashes.add(entry.requestHash)) {
        throw const NazaVaultException(
          'invalid_voice_cache_index',
          'The encrypted voice index contains a duplicate identity.',
        );
      }
      entries.add(entry);
    }
    return _EncryptedVoiceCacheVoiceCacheIndex(
      List<_EncryptedVoiceCacheVoiceIndexEntry>.unmodifiable(entries),
    );
  }

  final List<_EncryptedVoiceCacheVoiceIndexEntry> entries;

  _EncryptedVoiceCacheVoiceIndexEntry? byRequestHash(String requestHash) {
    for (final entry in entries) {
      if (_encryptedVoiceCacheConstantTimeEquals(
        entry.requestHash,
        requestHash,
      ))
        return entry;
    }
    return null;
  }

  _EncryptedVoiceCacheVoiceCacheMutation withStored(
    _EncryptedVoiceCacheVoiceIndexEntry stored, {
    required int maximumEntries,
    required int maximumTotalBytes,
  }) {
    final candidates = <_EncryptedVoiceCacheVoiceIndexEntry>[
      stored,
      ...entries.where(
        (entry) => !_encryptedVoiceCacheConstantTimeEquals(
          entry.requestHash,
          stored.requestHash,
        ),
      ),
    ];
    final retained = <_EncryptedVoiceCacheVoiceIndexEntry>[];
    final pruned = <String>[];
    var totalBytes = 0;
    for (final entry in candidates) {
      if (retained.length < maximumEntries &&
          totalBytes + entry.bytes <= maximumTotalBytes) {
        retained.add(entry);
        totalBytes += entry.bytes;
      } else {
        pruned.add(entry.requestHash);
      }
    }
    return _EncryptedVoiceCacheVoiceCacheMutation(
      index: _EncryptedVoiceCacheVoiceCacheIndex(
        List<_EncryptedVoiceCacheVoiceIndexEntry>.unmodifiable(retained),
      ),
      prunedRequestHashes: List<String>.unmodifiable(pruned),
    );
  }

  _EncryptedVoiceCacheVoiceCacheIndex? withPlayback(
    String requestHash,
    DateTime playedAt,
  ) {
    final existing = byRequestHash(requestHash);
    if (existing == null) return null;
    final updated = existing.copyWithPlayback(playedAt);
    return _EncryptedVoiceCacheVoiceCacheIndex(
      <_EncryptedVoiceCacheVoiceIndexEntry>[
        updated,
        ...entries.where(
          (entry) => !_encryptedVoiceCacheConstantTimeEquals(
            entry.requestHash,
            requestHash,
          ),
        ),
      ],
    );
  }

  Map<String, Object?> toJson() => <String, Object?>{
    'format': NazaEncryptedVoiceCache.indexFormat,
    'updatedAt': DateTime.now().toUtc().toIso8601String(),
    'entries': entries.map((entry) => entry.toJson()).toList(growable: false),
  };
}

final class _EncryptedVoiceCacheVoiceIndexEntry {
  const _EncryptedVoiceCacheVoiceIndexEntry({
    required this.requestHash,
    required this.audioSha256,
    required this.voice,
    required this.model,
    required this.bytes,
    required this.createdAt,
    required this.lastPlayedAt,
    required this.playCount,
  });

  factory _EncryptedVoiceCacheVoiceIndexEntry.fromJson(Object? raw) {
    if (raw is! Map) {
      throw const NazaVaultException(
        'invalid_voice_cache_index',
        'The encrypted voice index contains a malformed entry.',
      );
    }
    final requestHash = raw['requestHash']?.toString() ?? '';
    final audioHash = raw['audioSha256']?.toString() ?? '';
    final voice = raw['voice']?.toString() ?? '';
    final model = raw['model']?.toString() ?? '';
    final bytes = (raw['bytes'] as num?)?.toInt() ?? -1;
    final createdAt = DateTime.tryParse(raw['createdAt']?.toString() ?? '');
    final rawLastPlayedAt = raw['lastPlayedAt'];
    final lastPlayedAt = rawLastPlayedAt == null
        ? null
        : DateTime.tryParse(rawLastPlayedAt.toString());
    final playCount = (raw['playCount'] as num?)?.toInt() ?? -1;
    _encryptedVoiceCacheValidateHash(requestHash, 'requestHash');
    _encryptedVoiceCacheValidateHash(audioHash, 'audioSha256');
    if (voice.isEmpty ||
        voice.length > 80 ||
        model.isEmpty ||
        model.length > 160 ||
        bytes < 44 ||
        bytes > 64 * 1024 * 1024 ||
        createdAt == null ||
        (rawLastPlayedAt != null && lastPlayedAt == null) ||
        playCount < 0 ||
        playCount > 1000000000) {
      throw const NazaVaultException(
        'invalid_voice_cache_index',
        'The encrypted voice index entry failed bounds validation.',
      );
    }
    return _EncryptedVoiceCacheVoiceIndexEntry(
      requestHash: requestHash,
      audioSha256: audioHash,
      voice: voice,
      model: model,
      bytes: bytes,
      createdAt: createdAt.toUtc(),
      lastPlayedAt: lastPlayedAt?.toUtc(),
      playCount: playCount,
    );
  }

  final String requestHash;
  final String audioSha256;
  final String voice;
  final String model;
  final int bytes;
  final DateTime createdAt;
  final DateTime? lastPlayedAt;
  final int playCount;

  _EncryptedVoiceCacheVoiceIndexEntry copyWithPlayback(DateTime playedAt) =>
      _EncryptedVoiceCacheVoiceIndexEntry(
        requestHash: requestHash,
        audioSha256: audioSha256,
        voice: voice,
        model: model,
        bytes: bytes,
        createdAt: createdAt,
        lastPlayedAt: playedAt.toUtc(),
        playCount: playCount + 1,
      );

  Map<String, Object?> toJson() => <String, Object?>{
    'requestHash': requestHash,
    'audioSha256': audioSha256,
    'voice': voice,
    'model': model,
    'bytes': bytes,
    'createdAt': createdAt.toUtc().toIso8601String(),
    'lastPlayedAt': lastPlayedAt?.toUtc().toIso8601String(),
    'playCount': playCount,
  };
}

final class _EncryptedVoiceCacheVoiceCacheMutation {
  const _EncryptedVoiceCacheVoiceCacheMutation({
    required this.index,
    required this.prunedRequestHashes,
  });

  final _EncryptedVoiceCacheVoiceCacheIndex index;
  final List<String> prunedRequestHashes;
}

String _encryptedVoiceCacheSha256(List<int> bytes) =>
    crypto.sha256.convert(bytes).toString();

void _encryptedVoiceCacheValidateHash(String value, String name) {
  if (!RegExp(r'^[0-9a-f]{64}$').hasMatch(value)) {
    throw NazaVaultException(
      'invalid_voice_cache',
      'The encrypted voice $name is malformed.',
    );
  }
}

void _encryptedVoiceCacheValidateWav(
  Uint8List wav, {
  required int maximumBytes,
}) {
  if (wav.length < 44 || wav.length > maximumBytes) {
    throw const NazaVaultException(
      'invalid_voice_audio',
      'Voice audio is outside the encrypted cache size budget.',
    );
  }
  final view = ByteData.sublistView(wav);
  final channels = view.getUint16(22, Endian.little);
  final sampleRate = view.getUint32(24, Endian.little);
  final byteRate = view.getUint32(28, Endian.little);
  final blockAlign = view.getUint16(32, Endian.little);
  final bitsPerSample = view.getUint16(34, Endian.little);
  final expectedBlockAlign = channels * (bitsPerSample ~/ 8);
  if (!_encryptedVoiceCacheAsciiEquals(wav, 0, 'RIFF') ||
      !_encryptedVoiceCacheAsciiEquals(wav, 8, 'WAVE') ||
      !_encryptedVoiceCacheAsciiEquals(wav, 12, 'fmt ') ||
      !_encryptedVoiceCacheAsciiEquals(wav, 36, 'data') ||
      view.getUint32(4, Endian.little) != wav.length - 8 ||
      view.getUint32(16, Endian.little) != 16 ||
      view.getUint16(20, Endian.little) != 1 ||
      (channels != 1 && channels != 2) ||
      sampleRate < 8000 ||
      sampleRate > 96000 ||
      bitsPerSample != 16 ||
      blockAlign != expectedBlockAlign ||
      byteRate != sampleRate * expectedBlockAlign ||
      view.getUint32(40, Endian.little) != wav.length - 44) {
    throw const NazaVaultException(
      'invalid_voice_audio',
      'Voice audio is not a canonical bounded PCM WAV.',
    );
  }
}

bool _encryptedVoiceCacheAsciiEquals(
  Uint8List bytes,
  int offset,
  String expected,
) {
  for (var i = 0; i < expected.length; i++) {
    if (bytes[offset + i] != expected.codeUnitAt(i)) return false;
  }
  return true;
}

int _encryptedVoiceCacheMaximumBase64Characters(int bytes) =>
    ((bytes + 2) ~/ 3) * 4;

bool _encryptedVoiceCacheConstantTimeEquals(String left, String right) {
  var diff = left.length ^ right.length;
  final length = left.length > right.length ? left.length : right.length;
  for (var i = 0; i < length; i++) {
    final leftCode = i < left.length ? left.codeUnitAt(i) : 0;
    final rightCode = i < right.length ? right.codeUnitAt(i) : 0;
    diff |= leftCode ^ rightCode;
  }
  return diff == 0;
}

