// ============================================================================

final class OpenAiLiveTranscribeInput {
  OpenAiLiveTranscribeInput({AudioRecorder? recorder})
    : _openaiLiveTranscribeInputRecorder = recorder ?? AudioRecorder();

  final AudioRecorder _openaiLiveTranscribeInputRecorder;
  WebSocket? _openaiLiveTranscribeInputSocket;
  StreamSubscription<Uint8List>? _openaiLiveTranscribeInputAudioSubscription;
  StreamSubscription<dynamic>? _openaiLiveTranscribeInputSocketSubscription;
  final StringBuffer _openaiLiveTranscribeInputTranscript = StringBuffer();
  static const int _openaiLiveTranscribeInputMaxEventCharacters = 256 * 1024;
  static const int _openaiLiveTranscribeInputMaxTranscriptCharacters = 100000;

  static Future<bool> isConfigured() async {
    try {
      final profiles = await NazaRemoteModelCatalog().load();
      return profiles.any(
        (profile) =>
            profile.provider == NazaRemoteProvider.openAi &&
            profile.enabled &&
            profile.apiKey.trim().isNotEmpty,
      );
    } catch (_) {
      // Locked vault, first boot, or unavailable settings means the control
      // must remain hidden rather than surfacing an error from every field.
      return false;
    }
  }

  Future<void> start({required ValueChanged<String> onText}) async {
    await stop();
    if (!await _openaiLiveTranscribeInputRecorder.hasPermission()) {
      throw StateError('Microphone permission was not granted.');
    }
    final profiles = await NazaRemoteModelCatalog().load();
    final profile = profiles.where(
      (candidate) =>
          candidate.provider == NazaRemoteProvider.openAi &&
          candidate.enabled &&
          candidate.apiKey.trim().isNotEmpty,
    );
    if (profile.isEmpty)
      throw StateError('Configure OpenAI transcription in Settings first.');
    final socket = await WebSocket.connect(
      'wss://api.openai.com/v1/realtime?model=gpt-live-transcribe',
      headers: {'Authorization': 'Bearer ${profile.first.apiKey}'},
    );
    _openaiLiveTranscribeInputSocket = socket;
    _openaiLiveTranscribeInputSocketSubscription = socket.listen((data) {
      if (data is! String ||
          data.length > _openaiLiveTranscribeInputMaxEventCharacters)
        return;
      try {
        final event = jsonDecode(data);
        if (event is! Map) return;
        final type = event['type']?.toString() ?? '';
        final delta = event['delta']?.toString() ?? '';
        if ((type.contains('transcription') || type.contains('text')) &&
            delta.isNotEmpty &&
            _openaiLiveTranscribeInputTranscript.length + delta.length <=
                _openaiLiveTranscribeInputMaxTranscriptCharacters) {
          _openaiLiveTranscribeInputTranscript.write(delta);
          onText(_openaiLiveTranscribeInputTranscript.toString());
        }
      } on FormatException {
        // Ignore malformed remote events without terminating microphone cleanup.
      }
    });
    socket.add(
      jsonEncode({
        'type': 'session.update',
        'session': {
          'type': 'realtime',
          'audio': {
            'input': {
              'format': {'type': 'audio/pcm', 'rate': 24000},
              'transcription': {'model': 'gpt-live-transcribe'},
            },
          },
        },
      }),
    );
    final stream = await _openaiLiveTranscribeInputRecorder.startStream(
      const RecordConfig(
        encoder: AudioEncoder.pcm16bits,
        sampleRate: 24000,
        numChannels: 1,
      ),
    );
    _openaiLiveTranscribeInputAudioSubscription = stream.listen((bytes) {
      if (_openaiLiveTranscribeInputSocket != null && bytes.isNotEmpty) {
        _openaiLiveTranscribeInputSocket!.add(
          jsonEncode({
            'type': 'input_audio_buffer.append',
            'audio': base64Encode(bytes),
          }),
        );
      }
    });
  }

  Future<void> stop() async {
    await _openaiLiveTranscribeInputAudioSubscription?.cancel();
    _openaiLiveTranscribeInputAudioSubscription = null;
    await _openaiLiveTranscribeInputRecorder.stop();
    _openaiLiveTranscribeInputSocket?.add(
      jsonEncode({'type': 'input_audio_buffer.commit'}),
    );
    await _openaiLiveTranscribeInputSocketSubscription?.cancel();
    _openaiLiveTranscribeInputSocketSubscription = null;
    await _openaiLiveTranscribeInputSocket?.close(
      WebSocketStatus.normalClosure,
      'input stopped',
    );
    _openaiLiveTranscribeInputSocket = null;
    _openaiLiveTranscribeInputTranscript.clear();
  }

  Future<void> dispose() async {
    await stop();
    await _openaiLiveTranscribeInputRecorder.dispose();
  }
}

final class NazaVoiceInputButton extends StatefulWidget {
  const NazaVoiceInputButton({super.key, required this.controller});
  final TextEditingController controller;

  @override
  State<NazaVoiceInputButton> createState() =>
      _OpenaiLiveTranscribeInputNazaVoiceInputButtonState();
}

final class _OpenaiLiveTranscribeInputNazaVoiceInputButtonState
    extends State<NazaVoiceInputButton> {
  late final OpenAiLiveTranscribeInput _openaiLiveTranscribeInputInput;
  bool _openaiLiveTranscribeInputConfigured = false;
  bool _openaiLiveTranscribeInputRecording = false;

  @override
  void initState() {
    super.initState();
    _openaiLiveTranscribeInputInput = OpenAiLiveTranscribeInput();
    unawaited(_openaiLiveTranscribeInputLoadAvailability());
  }

  Future<void> _openaiLiveTranscribeInputLoadAvailability() async {
    final configured = await OpenAiLiveTranscribeInput.isConfigured();
    if (mounted)
      setState(() => _openaiLiveTranscribeInputConfigured = configured);
  }

  @override
  void dispose() {
    unawaited(_openaiLiveTranscribeInputInput.dispose());
    super.dispose();
  }

  Future<void> _openaiLiveTranscribeInputToggle() async {
    if (!_openaiLiveTranscribeInputConfigured) return;
    if (_openaiLiveTranscribeInputRecording) {
      await _openaiLiveTranscribeInputInput.stop();
      if (mounted) setState(() => _openaiLiveTranscribeInputRecording = false);
      return;
    }
    try {
      setState(() => _openaiLiveTranscribeInputRecording = true);
      await _openaiLiveTranscribeInputInput.start(
        onText: (text) {
          final existing = widget.controller.text.trimRight();
          widget.controller.text = existing.isEmpty ? text : '$existing $text';
          widget.controller.selection = TextSelection.collapsed(
            offset: widget.controller.text.length,
          );
        },
      );
    } catch (_) {
      if (mounted) setState(() => _openaiLiveTranscribeInputRecording = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (!_openaiLiveTranscribeInputConfigured) return const SizedBox.shrink();
    return IconButton(
      tooltip: _openaiLiveTranscribeInputRecording
          ? 'Stop live transcription'
          : 'Dictate with OpenAI',
      onPressed: _openaiLiveTranscribeInputToggle,
      color: _openaiLiveTranscribeInputRecording ? Colors.redAccent : null,
      icon: Icon(
        _openaiLiveTranscribeInputRecording
            ? Icons.stop_circle_rounded
            : Icons.mic_none_rounded,
      ),
    );
  }
}

// ============================================================================
// SOURCE SECTION: lib/audio/openai_reading_service.dart
// ============================================================================

/// Cancellable multi-backend reading surface for books and chat.
///
/// OpenAI remains the fast default. Suno Bark on Replicate is an opt-in
/// alternative. Both share a cheap local performance planner, a bounded
/// request queue, encrypted recall, and the same WAV finishing stage.
final class OpenAiReadingService {
  OpenAiReadingService({
    AudioPlayer? player,
    http.Client? client,
    NazaEncryptedVoiceCache? voiceCache,
    NazaVoiceSettingsStore? settingsStore,
    HumanizedSpeechPlanner? planner,
    NazaWavComposer? composer,
  }) : _openaiReadingServicePlayer = player ?? AudioPlayer(),
       _openaiReadingServiceClient = client ?? http.Client(),
       _openaiReadingServiceOwnsClient = client == null,
       _openaiReadingServiceVoiceCache =
           voiceCache ?? NazaEncryptedVoiceCache.instance,
       _openaiReadingServiceSettingsStore =
           settingsStore ?? NazaVoiceSettingsStore(),
       _openaiReadingServicePlanner = planner ?? const HumanizedSpeechPlanner(),
       _openaiReadingServiceComposer = composer ?? const NazaWavComposer() {
    _openaiReadingServiceBark = ReplicateBarkClient(
      client: _openaiReadingServiceClient,
    );
    _openaiReadingServicePlayerCompletion = _openaiReadingServicePlayer
        .onPlayerComplete
        .listen(
          (_) => unawaited(_openaiReadingServiceHandlePlayerComplete()),
          onError: (Object error, StackTrace stackTrace) => unawaited(
            _openaiReadingServiceHandlePlayerError(error, stackTrace),
          ),
        );
  }

  final AudioPlayer _openaiReadingServicePlayer;
  final http.Client _openaiReadingServiceClient;
  final bool _openaiReadingServiceOwnsClient;
  final NazaEncryptedVoiceCache _openaiReadingServiceVoiceCache;
  final NazaVoiceSettingsStore _openaiReadingServiceSettingsStore;
  final HumanizedSpeechPlanner _openaiReadingServicePlanner;
  final NazaWavComposer _openaiReadingServiceComposer;
  late final ReplicateBarkClient _openaiReadingServiceBark;
  final StreamController<void> _openaiReadingServiceCompletionController =
      StreamController<void>.broadcast();
  late final StreamSubscription<void> _openaiReadingServicePlayerCompletion;
  bool _openaiReadingServiceCancelled = false;
  Uint8List? _openaiReadingServiceLastWav;
  String? _openaiReadingServiceLastPath;
  String? _openaiReadingServiceLastAudioSha256;
  String? _openaiReadingServiceLastRequestHash;
  bool _openaiReadingServiceLastReadWasCached = false;
  Directory? _openaiReadingServicePlaybackDirectory;
  File? _openaiReadingServicePlaybackFile;

  static const int _openaiReadingServiceMaxResponseBytes = 16 * 1024 * 1024;
  static const int _openaiReadingServiceMaxCombinedResponseBytes =
      NazaWavComposer.maxCombinedBytes;
  static const Duration _openaiReadingServiceRequestTimeout = Duration(
    seconds: 45,
  );
  static const String _openaiReadingServicePlaybackDirectoryPrefix =
      'naza-one-reading-';
  static const String _openaiReadingServicePlaybackFileName = 'reading.wav';
  static Future<void>? _openaiReadingServiceStalePlaybackCleanup;

  Future<Uint8List> read({
    required String text,
    String? voice,
    String model = 'gpt-4o-mini-tts',
    String instructions =
        'Read naturally and warmly, as if speaking to one person nearby. '
        'Use expressive but restrained emphasis and comfortable phrasing.',
    void Function(int total)? onPlanned,
    void Function(int completed, int total)? onProgress,
    int? performanceSeed,
  }) async {
    if (model != 'gpt-4o-mini-tts') {
      throw ArgumentError.value(model, 'model', 'Unsupported speech model.');
    }
    _openaiReadingServiceCancelled = false;
    _openaiReadingServiceLastReadWasCached = false;
    _openaiReadingServiceLastAudioSha256 = null;
    _openaiReadingServiceLastRequestHash = null;
    await _openaiReadingServiceStopPlayerAndCleanup();
    if (!_openaiReadingServiceVoiceCache.isUnlocked) {
      throw const NazaVaultException(
        'voice_cache_locked',
        'Unlock the encrypted vault before using Read Aloud.',
      );
    }

    final savedSettings = await _openaiReadingServiceSettingsStore.load();
    final settings = voice == null
        ? savedSettings
        : savedSettings.copyWith(openAiVoice: voice);
    settings.validate();
    if (!NazaVoiceSettings.openAiVoices.contains(settings.openAiVoice)) {
      throw ArgumentError.value(
        settings.openAiVoice,
        'voice',
        'Unsupported voice.',
      );
    }
    if (settings.backend == NazaSpeechBackend.replicateBark &&
        settings.replicateApiToken.isEmpty) {
      throw StateError(
        'Add a Replicate API token in Settings → Voice & read aloud.',
      );
    }

    final seed =
        performanceSeed ??
        _openaiReadingServiceStablePerformanceSeed(text, settings);
    final plan = _openaiReadingServicePlanner.plan(
      text: text,
      settings: settings,
      seed: seed,
    );
    onPlanned?.call(plan.segmentCount);
    final cacheVoice = settings.backend == NazaSpeechBackend.openAi
        ? 'openai:${settings.openAiVoice}'
        : 'replicate-bark:${settings.barkVoice}';
    final cacheModel = settings.backend == NazaSpeechBackend.openAi
        ? model
        : ReplicateBarkClient.modelVersion;
    final cacheInstructions = _openaiReadingServiceCachePerformanceIdentity(
      text: text,
      baseInstructions: instructions,
      settings: settings,
      seed: seed,
    );
    final cached = await _openaiReadingServiceVoiceCache.recall(
      text: text,
      voice: cacheVoice,
      model: cacheModel,
      instructions: cacheInstructions,
      speed: settings.baseSpeed,
    );
    if (cached != null) {
      if (_openaiReadingServiceCancelled)
        throw const CancelledReadingException();
      _openaiReadingServiceLastWav = Uint8List.fromList(cached.wav);
      _openaiReadingServiceLastAudioSha256 = cached.audioSha256;
      _openaiReadingServiceLastRequestHash = cached.requestHash;
      _openaiReadingServiceLastReadWasCached = true;
      await _openaiReadingServicePlayAndRecord(cached);
      return Uint8List.fromList(cached.wav);
    }

    final profile = settings.backend == NazaSpeechBackend.openAi
        ? await _openaiReadingServiceOpenAiProfile()
        : null;
    if (settings.backend == NazaSpeechBackend.openAi && profile == null) {
      throw StateError(
        'Add an enabled OpenAI profile with an API key in Settings.',
      );
    }
    final wavs = await _openaiReadingServiceRenderPlan(
      plan: plan,
      settings: settings,
      profile: profile,
      model: model,
      baseInstructions: instructions,
      onProgress: onProgress,
    );
    if (_openaiReadingServiceCancelled) throw const CancelledReadingException();
    final combined = _openaiReadingServiceComposer.compose(
      wavs: wavs,
      segments: plan.segments,
    );
    _openaiReadingServiceLastWav = combined;
    _openaiReadingServiceLastPath = null;
    if (_openaiReadingServiceCancelled) throw const CancelledReadingException();
    if (combined.length <= _openaiReadingServiceVoiceCache.maximumEntryBytes) {
      final stored = await _openaiReadingServiceVoiceCache.store(
        text: text,
        voice: cacheVoice,
        model: cacheModel,
        instructions: cacheInstructions,
        speed: settings.baseSpeed,
        wav: combined,
      );
      _openaiReadingServiceLastAudioSha256 = stored.audioSha256;
      _openaiReadingServiceLastRequestHash = stored.requestHash;
      await _openaiReadingServicePlayAndRecord(stored);
    } else {
      _openaiReadingServiceLastAudioSha256 = crypto.sha256
          .convert(combined)
          .toString();
      await _openaiReadingServicePlayWav(combined);
    }
    return combined;
  }

  Future<void> pause() => _openaiReadingServicePlayer.pause();
  Future<void> resume() => _openaiReadingServicePlayer.resume();
  Stream<void> get onComplete =>
      _openaiReadingServiceCompletionController.stream;

  Future<void> stop() async {
    _openaiReadingServiceCancelled = true;
    await Future.wait<void>(<Future<void>>[
      _openaiReadingServiceStopPlayerAndCleanup(),
      _openaiReadingServiceBark.cancelActive(),
    ]);
  }

  Future<String> saveLastWav({String fileName = 'naza-reading.wav'}) async {
    final wav = _openaiReadingServiceLastWav;
    if (wav == null || wav.isEmpty)
      throw StateError('No completed reading is available.');
    final directory = await getApplicationDocumentsDirectory();
    final safeName = fileName.replaceAll(RegExp(r'[^a-zA-Z0-9._-]'), '_');
    final file = File('${directory.path}/$safeName');
    await file.writeAsBytes(wav, flush: true);
    _openaiReadingServiceLastPath = file.path;
    return file.path;
  }

  String? get lastSavedPath => _openaiReadingServiceLastPath;
  String? get lastAudioSha256 => _openaiReadingServiceLastAudioSha256;
  String? get lastRequestHash => _openaiReadingServiceLastRequestHash;
  bool get lastReadWasCached => _openaiReadingServiceLastReadWasCached;

  Future<NazaRemoteModelProfile?> _openaiReadingServiceOpenAiProfile() async {
    final profiles = await NazaRemoteModelCatalog().load();
    for (final profile in profiles) {
      if (profile.provider == NazaRemoteProvider.openAi &&
          profile.enabled &&
          profile.apiKey.trim().isNotEmpty)
        return profile;
    }
    return null;
  }

  Future<List<Uint8List>> _openaiReadingServiceRenderPlan({
    required NazaSpeechPlan plan,
    required NazaVoiceSettings settings,
    required NazaRemoteModelProfile? profile,
    required String model,
    required String baseInstructions,
    required void Function(int completed, int total)? onProgress,
  }) async {
    final output = List<Uint8List?>.filled(plan.segmentCount, null);
    Object? firstError;
    StackTrace? firstStack;
    var cursor = 0;
    var completed = 0;
    var combinedBytes = 0;
    var abortWorkers = false;

    Future<void> worker() async {
      while (!_openaiReadingServiceCancelled && !abortWorkers) {
        if (cursor >= plan.segmentCount) return;
        final index = cursor++;
        final segment = plan.segments[index];
        try {
          final wav = settings.backend == NazaSpeechBackend.replicateBark
              ? await _openaiReadingServiceBark.generate(
                  prompt: segment.barkPrompt,
                  historyPrompt: settings.barkVoice,
                  textTemperature: segment.barkTextTemperature,
                  waveformTemperature: segment.barkWaveformTemperature,
                  apiToken: settings.replicateApiToken,
                  isCancelled: () =>
                      _openaiReadingServiceCancelled || abortWorkers,
                )
              : await _openaiReadingServiceRenderOpenAiSegment(
                  segment: segment,
                  profile: profile!,
                  model: model,
                  voice: settings.openAiVoice,
                  baseInstructions: baseInstructions,
                );
          if (_openaiReadingServiceCancelled || abortWorkers) return;
          combinedBytes += wav.length;
          if (combinedBytes > _openaiReadingServiceMaxCombinedResponseBytes) {
            throw const FormatException('Combined speech audio is too large.');
          }
          output[index] = wav;
          completed++;
          onProgress?.call(completed, plan.segmentCount);
        } on Object catch (error, stack) {
          firstError ??= error;
          firstStack ??= stack;
          abortWorkers = true;
          return;
        }
      }
    }

    final workerCount = settings.parallelRequests
        .clamp(1, plan.segmentCount)
        .toInt();
    await Future.wait<void>(<Future<void>>[
      for (var i = 0; i < workerCount; i++) worker(),
    ]);
    if (firstError != null) {
      await _openaiReadingServiceBark.cancelActive();
      if (firstError is ReplicateBarkCancelledException &&
          _openaiReadingServiceCancelled) {
        throw const CancelledReadingException();
      }
      Error.throwWithStackTrace(firstError!, firstStack!);
    }
    if (_openaiReadingServiceCancelled) throw const CancelledReadingException();
    if (output.any((item) => item == null)) {
      throw StateError('Speech generation ended before every segment.');
    }
    return output.cast<Uint8List>();
  }

  Future<Uint8List> _openaiReadingServiceRenderOpenAiSegment({
    required NazaSpeechSegment segment,
    required NazaRemoteModelProfile profile,
    required String model,
    required String voice,
    required String baseInstructions,
  }) async {
    final request =
        http.Request('POST', Uri.https('api.openai.com', '/v1/audio/speech'))
          ..followRedirects = false
          ..headers.addAll(<String, String>{
            'authorization': 'Bearer ${profile.apiKey}',
            'content-type': 'application/json',
            'accept': 'audio/wav',
          })
          ..body = jsonEncode(<String, Object?>{
            'model': model,
            'voice': voice,
            'input': segment.spokenText,
            'instructions': segment.openAiInstructions(baseInstructions),
            'response_format': 'wav',
            'speed': segment.speed,
          });
    final response = await _openaiReadingServiceClient
        .send(request)
        .timeout(_openaiReadingServiceRequestTimeout);
    if (response.statusCode >= 300 && response.statusCode < 400) {
      throw StateError('OpenAI speech redirects are not allowed.');
    }
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw StateError('OpenAI reading failed (${response.statusCode}).');
    }
    if (response.contentLength != null &&
        response.contentLength! > _openaiReadingServiceMaxResponseBytes) {
      throw const FormatException('OpenAI WAV response is too large.');
    }
    final bytes = BytesBuilder(copy: false);
    var length = 0;
    await for (final chunk in response.stream.timeout(
      _openaiReadingServiceRequestTimeout,
    )) {
      if (chunk.length > _openaiReadingServiceMaxResponseBytes - length) {
        throw const FormatException('OpenAI WAV response is too large.');
      }
      length += chunk.length;
      bytes.add(chunk);
    }
    return bytes.takeBytes();
  }

  static int _openaiReadingServiceStablePerformanceSeed(
    String text,
    NazaVoiceSettings settings,
  ) {
    final publicSettings = Map<String, Object?>.from(settings.toJson())
      ..remove('replicateApiToken');
    final digest = crypto.sha256
        .convert(utf8.encode(jsonEncode(<Object?>[text, publicSettings])))
        .bytes;
    return ByteData.sublistView(
          Uint8List.fromList(digest),
        ).getUint32(0, Endian.little) &
        0x7fffffff;
  }

  static String _openaiReadingServiceCachePerformanceIdentity({
    required String text,
    required String baseInstructions,
    required NazaVoiceSettings settings,
    required int seed,
  }) {
    final publicSettings = Map<String, Object?>.from(settings.toJson())
      ..remove('replicateApiToken');
    return jsonEncode(<String, Object?>{
      'format': 'naza-human-voice-performance-v2',
      'rawTextSha256': crypto.sha256.convert(utf8.encode(text)).toString(),
      'baseInstructions': baseInstructions,
      'settings': publicSettings,
      'seed': seed,
    });
  }

  Future<void> _openaiReadingServicePlayAndRecord(NazaCachedVoice voice) async {
    await _openaiReadingServicePlayWav(voice.wav);
    try {
      await _openaiReadingServiceVoiceCache.recordPlayback(voice.requestHash);
    } catch (_) {
      await _openaiReadingServiceStopPlayerAndCleanup();
      rethrow;
    }
  }

  Future<void> _openaiReadingServicePlayWav(Uint8List wav) async {
    await (_openaiReadingServiceStalePlaybackCleanup ??=
        _openaiReadingServiceRemoveStalePlaybackArtifacts());
    await _openaiReadingServiceDeletePlaybackArtifact();
    final temporaryRoot = await getTemporaryDirectory();
    final directory = await NazaPrivateAudioPlaybackDirectory.create(
      temporaryRoot,
      prefix: _openaiReadingServicePlaybackDirectoryPrefix,
    );
    try {
      if (!Platform.isWindows) {
        final stat = await directory.stat();
        if ((stat.mode & 0x3f) != 0) {
          throw const FileSystemException(
            'Private audio playback directory has unsafe permissions.',
          );
        }
      }
      final file = File(
        '${directory.path}${Platform.pathSeparator}$_openaiReadingServicePlaybackFileName',
      );
      await file.writeAsBytes(wav, flush: true);
      _openaiReadingServicePlaybackDirectory = directory;
      _openaiReadingServicePlaybackFile = file;
      await _openaiReadingServicePlayer.play(
        DeviceFileSource(file.path, mimeType: 'audio/wav'),
      );
    } catch (_) {
      _openaiReadingServicePlaybackDirectory = directory;
      await _openaiReadingServiceDeletePlaybackArtifact();
      rethrow;
    }
  }

  Future<void> _openaiReadingServiceHandlePlayerComplete() async {
    try {
      await _openaiReadingServiceDeletePlaybackArtifact();
      if (!_openaiReadingServiceCompletionController.isClosed)
        _openaiReadingServiceCompletionController.add(null);
    } catch (error, stackTrace) {
      if (!_openaiReadingServiceCompletionController.isClosed) {
        _openaiReadingServiceCompletionController.addError(error, stackTrace);
      }
    }
  }

  Future<void> _openaiReadingServiceHandlePlayerError(
    Object error,
    StackTrace stackTrace,
  ) async {
    try {
      await _openaiReadingServiceDeletePlaybackArtifact();
    } catch (cleanupError, cleanupStackTrace) {
      if (!_openaiReadingServiceCompletionController.isClosed) {
        _openaiReadingServiceCompletionController.addError(
          cleanupError,
          cleanupStackTrace,
        );
      }
      return;
    }
    if (!_openaiReadingServiceCompletionController.isClosed) {
      _openaiReadingServiceCompletionController.addError(error, stackTrace);
    }
  }

  Future<void> _openaiReadingServiceStopPlayerAndCleanup() async {
    try {
      await _openaiReadingServicePlayer.stop();
    } finally {
      await _openaiReadingServiceDeletePlaybackArtifact();
    }
  }

  Future<void> _openaiReadingServiceDeletePlaybackArtifact() async {
    final file = _openaiReadingServicePlaybackFile;
    final directory = _openaiReadingServicePlaybackDirectory;
    _openaiReadingServicePlaybackFile = null;
    _openaiReadingServicePlaybackDirectory = null;
    if (file != null &&
        await FileSystemEntity.type(file.path, followLinks: false) ==
            FileSystemEntityType.file) {
      await file.delete();
    }
    if (directory != null &&
        await FileSystemEntity.type(directory.path, followLinks: false) ==
            FileSystemEntityType.directory) {
      await directory.delete();
    }
  }

  static Future<void>
  _openaiReadingServiceRemoveStalePlaybackArtifacts() async {
    final temporaryRoot = await getTemporaryDirectory();
    await for (final entity in temporaryRoot.list(followLinks: false)) {
      final name = entity.path.split(Platform.pathSeparator).last;
      if (!name.startsWith(_openaiReadingServicePlaybackDirectoryPrefix) ||
          await FileSystemEntity.type(entity.path, followLinks: false) !=
              FileSystemEntityType.directory) {
        continue;
      }
      final file = File(
        '${entity.path}${Platform.pathSeparator}$_openaiReadingServicePlaybackFileName',
      );
      if (await FileSystemEntity.type(file.path, followLinks: false) ==
          FileSystemEntityType.file) {
        await file.delete();
      }
      try {
        await Directory(entity.path).delete();
      } on FileSystemException {
        // Never recursively delete an unexpected directory. A non-empty
        // artifact is left untouched instead of following attacker-controlled
        // contents or links.
      }
    }
  }

  Future<void> dispose() async {
    _openaiReadingServiceCancelled = true;
    await _openaiReadingServicePlayerCompletion.cancel();
    try {
      await _openaiReadingServiceBark.cancelActive();
      await _openaiReadingServicePlayer.dispose();
    } finally {
      await _openaiReadingServiceDeletePlaybackArtifact();
      if (_openaiReadingServiceOwnsClient) _openaiReadingServiceClient.close();
      await _openaiReadingServiceCompletionController.close();
    }
  }
}

/// Creates the playback container privately before any plaintext WAV is written.
/// POSIX mkdtemp atomically creates a unique directory with mode 0700; unlike
/// creating then chmod-ing it, there is no interval with broader permissions.
final class NazaPrivateAudioPlaybackDirectory {
  const NazaPrivateAudioPlaybackDirectory._();

  static Future<Directory> create(
    Directory root, {
    required String prefix,
  }) async {
    if (!RegExp(r'^[A-Za-z0-9_-]{1,80}$').hasMatch(prefix) ||
        root.path.contains('\u0000')) {
      throw const FileSystemException('Invalid private audio directory path.');
    }
    // Windows uses the application cache directory's inherited user ACL.
    if (Platform.isWindows) return root.createTemp(prefix);
    final template =
        '${root.absolute.path}${Platform.pathSeparator}${prefix}XXXXXX'
            .toNativeUtf8(allocator: calloc);
    try {
      final mkdtemp = ffi.DynamicLibrary.process().lookupFunction<
          ffi.Pointer<Utf8> Function(ffi.Pointer<Utf8>),
          ffi.Pointer<Utf8> Function(ffi.Pointer<Utf8>)>('mkdtemp');
      final result = mkdtemp(template);
      if (result == ffi.nullptr) {
        throw const FileSystemException(
          'Unable to create a private audio playback directory.',
        );
      }
      final directory = Directory(template.toDartString());
      try {
        final type = await FileSystemEntity.type(directory.path, followLinks: false);
        final stat = await directory.stat();
        if (type != FileSystemEntityType.directory ||
            (stat.mode & 0x1ff) != 0x1c0) {
          throw const FileSystemException(
            'Private audio playback directory has unsafe permissions.',
          );
        }
        return directory;
      } catch (_) {
        // Delete only the empty directory created by this call; never recurse.
        if (await FileSystemEntity.type(directory.path, followLinks: false) ==
            FileSystemEntityType.directory) {
          await directory.delete();
        }
        rethrow;
      }
    } finally {
      calloc.free(template);
    }
  }
}

final class CancelledReadingException implements Exception {
  const CancelledReadingException();
}

final class NazaReadAloudButton extends StatefulWidget {
  const NazaReadAloudButton({super.key, required this.text});

  final String text;

  @override
  State<NazaReadAloudButton> createState() =>
      _OpenaiReadingServiceNazaReadAloudButtonState();
}

final class _OpenaiReadingServiceNazaReadAloudButtonState
    extends State<NazaReadAloudButton> {
  late final OpenAiReadingService _openaiReadingServiceReader;
  StreamSubscription<void>? _openaiReadingServiceCompletion;
  bool _openaiReadingServiceBusy = false;
  bool _openaiReadingServicePlaying = false;
  bool _openaiReadingServicePaused = false;
  String? _openaiReadingServiceStatus;

  @override
  void initState() {
    super.initState();
    _openaiReadingServiceReader = OpenAiReadingService();
    _openaiReadingServiceCompletion = _openaiReadingServiceReader.onComplete
        .listen(
          (_) {
            if (!mounted) return;
            setState(() {
              _openaiReadingServicePlaying = false;
              _openaiReadingServicePaused = false;
              _openaiReadingServiceStatus =
                  _openaiReadingServiceEncryptedVoiceStatus(
                    _openaiReadingServiceReader,
                    prefix: 'Reading complete',
                  );
            });
          },
          // Platform playback errors are also delivered through this stream.
          // Handling them here prevents a failed Linux GStreamer pipeline from
          // escaping as an unhandled asynchronous exception.
          onError: (Object error, StackTrace stackTrace) {
            if (!mounted) return;
            setState(() {
              _openaiReadingServicePlaying = false;
              _openaiReadingServicePaused = false;
              _openaiReadingServiceStatus =
                  _openaiReadingServiceReadingFailureMessage(error);
            });
          },
        );
  }

  @override
  void didUpdateWidget(covariant NazaReadAloudButton oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.text != widget.text) {
      unawaited(_openaiReadingServiceReader.stop());
      _openaiReadingServiceBusy = false;
      _openaiReadingServicePlaying = false;
      _openaiReadingServicePaused = false;
      _openaiReadingServiceStatus = null;
    }
  }

  @override
  void dispose() {
    unawaited(_openaiReadingServiceCompletion?.cancel());
    unawaited(_openaiReadingServiceReader.dispose());
    super.dispose();
  }

  Future<void> _openaiReadingServiceStart() async {
    setState(() {
      _openaiReadingServiceBusy = true;
      _openaiReadingServicePlaying = false;
      _openaiReadingServicePaused = false;
      _openaiReadingServiceStatus = 'preparing voice';
    });
    try {
      await _openaiReadingServiceReader.read(
        text: widget.text,
        onPlanned: (total) {
          if (mounted) {
            setState(
              () => _openaiReadingServiceStatus = total == 1
                  ? 'Preparing one natural voice moment…'
                  : 'Preparing $total natural voice moments…',
            );
          }
        },
        onProgress: (done, total) {
          if (mounted)
            setState(() => _openaiReadingServiceStatus = 'Voice $done/$total');
        },
      );
      if (mounted) {
        setState(() {
          _openaiReadingServicePlaying = true;
          _openaiReadingServiceStatus =
              _openaiReadingServiceEncryptedVoiceStatus(
                _openaiReadingServiceReader,
                prefix: 'Playing',
              );
        });
      }
    } catch (error) {
      if (mounted) {
        setState(() {
          _openaiReadingServicePlaying = false;
          _openaiReadingServiceStatus = error is CancelledReadingException
              ? 'Reading stopped'
              : _openaiReadingServiceReadingFailureMessage(error);
        });
      }
    } finally {
      if (mounted) setState(() => _openaiReadingServiceBusy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final active = _openaiReadingServicePlaying || _openaiReadingServicePaused;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.end,
      children: [
        Wrap(
          spacing: 4,
          crossAxisAlignment: WrapCrossAlignment.center,
          children: [
            if (!active)
              FilledButton.tonalIcon(
                onPressed: _openaiReadingServiceBusy
                    ? null
                    : _openaiReadingServiceStart,
                icon: _openaiReadingServiceBusy
                    ? const SizedBox.square(
                        dimension: 16,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : const Icon(Icons.record_voice_over_rounded, size: 18),
                label: Text(
                  _openaiReadingServiceBusy ? 'Preparing audio…' : 'Read aloud',
                ),
              ),
            if (active)
              FilledButton.tonalIcon(
                onPressed: () async {
                  if (_openaiReadingServicePaused) {
                    await _openaiReadingServiceReader.resume();
                  } else {
                    await _openaiReadingServiceReader.pause();
                  }
                  if (mounted)
                    setState(
                      () => _openaiReadingServicePaused =
                          !_openaiReadingServicePaused,
                    );
                },
                icon: Icon(
                  _openaiReadingServicePaused
                      ? Icons.play_arrow_rounded
                      : Icons.pause_rounded,
                  size: 18,
                ),
                label: Text(_openaiReadingServicePaused ? 'Play' : 'Pause'),
              ),
            if (_openaiReadingServiceBusy || active)
              IconButton(
                tooltip: 'Stop reading',
                onPressed: () async {
                  await _openaiReadingServiceReader.stop();
                  if (mounted) {
                    setState(() {
                      _openaiReadingServiceBusy = false;
                      _openaiReadingServicePlaying = false;
                      _openaiReadingServicePaused = false;
                      _openaiReadingServiceStatus = 'Reading stopped';
                    });
                  }
                },
                icon: const Icon(Icons.stop_rounded, size: 18),
              ),
            if (_openaiReadingServiceReader.lastSavedPath != null ||
                (_openaiReadingServiceStatus?.startsWith('Reading complete') ??
                    false))
              IconButton(
                tooltip: 'Export decrypted WAV file',
                onPressed: () async {
                  final path = await _openaiReadingServiceReader.saveLastWav();
                  if (mounted) {
                    setState(
                      () => _openaiReadingServiceStatus =
                          'Exported plaintext WAV: $path',
                    );
                  }
                },
                icon: const Icon(Icons.download_rounded, size: 18),
              ),
          ],
        ),
        if (_openaiReadingServiceStatus != null) ...[
          const SizedBox(height: 4),
          ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 520),
            child: Text(
              _openaiReadingServiceStatus!,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              textAlign: TextAlign.right,
              style: Theme.of(context).textTheme.bodySmall,
            ),
          ),
        ],
      ],
    );
  }
}

String _openaiReadingServiceReadingFailureMessage(Object error) {
  if (error is NazaVaultException) return error.message;
  final message = error.toString().replaceFirst('Bad state: ', '');
  if (Platform.isLinux && message.contains('LinuxAudioError')) {
    return 'Linux audio playback needs the GStreamer good plug-ins. '
        'Install gstreamer1.0-plugins-good, then restart Naza One.';
  }
  return message;
}

String _openaiReadingServiceEncryptedVoiceStatus(
  OpenAiReadingService reader, {
  required String prefix,
}) {
  final digest = reader.lastAudioSha256;
  final shortDigest = digest == null || digest.length < 12
      ? 'hash unavailable'
      : 'SHA-256 ${digest.substring(0, 12)}…';
  final source = reader.lastReadWasCached
      ? 'recalled from encrypted vault'
      : 'saved to encrypted vault';
  return '$prefix • $source • $shortDigest';
}

