/// GA Realtime voice session boundary.
///
/// This is intentionally separate from request-based WAV generation: Realtime
/// is a live session for low-latency text/audio interaction, while the WAV
/// reader remains the durable export path. Audio deltas are retained so a
/// completed session can be exported by a platform audio sink later.
final class OpenAiRealtimeVoiceSession {
  WebSocket? _openaiRealtimeVoiceSessionSocket;
  final StreamController<Map<String, dynamic>>
  _openaiRealtimeVoiceSessionEvents =
      StreamController<Map<String, dynamic>>.broadcast();
  final BytesBuilder _openaiRealtimeVoiceSessionPcm = BytesBuilder(copy: false);
  bool _openaiRealtimeVoiceSessionPaused = false;
  int _openaiRealtimeVoiceSessionPcmBytes = 0;

  static const int _openaiRealtimeVoiceSessionMaxTextCharacters = 50000;
  static const int _openaiRealtimeVoiceSessionMaxEventCharacters = 512 * 1024;
  static const int _openaiRealtimeVoiceSessionMaxPcmBytes = 48 * 1024 * 1024;
  static const Set<String> _openaiRealtimeVoiceSessionAllowedVoices = {
    'alloy',
    'ash',
    'ballad',
    'coral',
    'echo',
    'marin',
    'sage',
    'shimmer',
    'verse',
  };

  Stream<Map<String, dynamic>> get events =>
      _openaiRealtimeVoiceSessionEvents.stream;
  bool get connected => _openaiRealtimeVoiceSessionSocket != null;
  bool get paused => _openaiRealtimeVoiceSessionPaused;

  Future<void> connect({
    String model = 'gpt-realtime-2.1',
    String voice = 'marin',
    String instructions =
        'Read naturally, warmly, and clearly. Preserve the supplied text exactly; do not summarize.',
  }) async {
    if (model != 'gpt-realtime-2.1') {
      throw ArgumentError.value(model, 'model', 'Unsupported realtime model.');
    }
    if (!_openaiRealtimeVoiceSessionAllowedVoices.contains(voice)) {
      throw ArgumentError.value(voice, 'voice', 'Unsupported voice.');
    }
    await close();
    final profile = await _openaiRealtimeVoiceSessionOpenAiProfile();
    if (profile == null) {
      throw StateError(
        'Add an enabled OpenAI profile with an API key in Settings.',
      );
    }
    final uri = Uri.parse(
      'wss://api.openai.com/v1/realtime?model=${Uri.encodeQueryComponent(model)}',
    );
    final socket = await WebSocket.connect(
      uri.toString(),
      headers: {'Authorization': 'Bearer ${profile.apiKey}'},
    );
    _openaiRealtimeVoiceSessionSocket = socket;
    socket.listen(
      (data) => _openaiRealtimeVoiceSessionHandle(data),
      onError: (Object error, StackTrace stack) {
        if (!_openaiRealtimeVoiceSessionEvents.isClosed)
          _openaiRealtimeVoiceSessionEvents.addError(error, stack);
      },
      onDone: () => _openaiRealtimeVoiceSessionSocket = null,
      cancelOnError: false,
    );
    _openaiRealtimeVoiceSessionSend({
      'type': 'session.update',
      'session': {
        'type': 'realtime',
        'instructions': instructions,
        'audio': {
          'output': {
            'format': {'type': 'audio/pcm', 'rate': 24000},
            'voice': voice,
          },
        },
      },
    });
    _openaiRealtimeVoiceSessionEvents.add({
      'type': 'session.connected',
      'model': model,
    });
  }

  void speak(String text) {
    final value = text.trim();
    if (value.isEmpty || !connected) return;
    if (value.length > _openaiRealtimeVoiceSessionMaxTextCharacters) {
      throw StateError(
        'Realtime speech text exceeds the 50,000 character limit.',
      );
    }
    _openaiRealtimeVoiceSessionPaused = false;
    _openaiRealtimeVoiceSessionSend({
      'type': 'conversation.item.create',
      'item': {
        'type': 'message',
        'role': 'user',
        'content': [
          {'type': 'input_text', 'text': value},
        ],
      },
    });
    _openaiRealtimeVoiceSessionSend({
      'type': 'response.create',
      'response': {
        'output_modalities': ['audio'],
        'audio': {
          'output': {
            'format': {'type': 'audio/pcm', 'rate': 24000},
          },
        },
      },
    });
  }

  void pause() {
    if (!connected) return;
    _openaiRealtimeVoiceSessionPaused = true;
    _openaiRealtimeVoiceSessionSend({'type': 'response.cancel'});
    _openaiRealtimeVoiceSessionEvents.add({'type': 'session.paused'});
  }

  void stop() {
    if (!connected) return;
    _openaiRealtimeVoiceSessionSend({'type': 'response.cancel'});
    _openaiRealtimeVoiceSessionPcm.clear();
    _openaiRealtimeVoiceSessionPcmBytes = 0;
    _openaiRealtimeVoiceSessionEvents.add({'type': 'session.stopped'});
  }

  Uint8List get pcm16 {
    final bytes = _openaiRealtimeVoiceSessionPcm.takeBytes();
    _openaiRealtimeVoiceSessionPcmBytes = 0;
    return bytes;
  }

  Future<void> close() async {
    final socket = _openaiRealtimeVoiceSessionSocket;
    _openaiRealtimeVoiceSessionSocket = null;
    await socket?.close(WebSocketStatus.normalClosure, 'client closed');
  }

  Future<void> dispose() async {
    await close();
    await _openaiRealtimeVoiceSessionEvents.close();
  }

  void _openaiRealtimeVoiceSessionSend(Map<String, dynamic> event) =>
      _openaiRealtimeVoiceSessionSocket?.add(jsonEncode(event));

  void _openaiRealtimeVoiceSessionHandle(Object? data) {
    if (data is! String ||
        data.length > _openaiRealtimeVoiceSessionMaxEventCharacters)
      return;
    try {
      final decoded = jsonDecode(data);
      if (decoded is! Map) return;
      final event = Map<String, dynamic>.from(decoded);
      final type = event['type']?.toString() ?? '';
      final delta = event['delta']?.toString();
      if (type == 'response.output_audio.delta' && delta != null) {
        final bytes = base64Decode(delta);
        if (_openaiRealtimeVoiceSessionPcmBytes + bytes.length >
            _openaiRealtimeVoiceSessionMaxPcmBytes) {
          pause();
          if (!_openaiRealtimeVoiceSessionEvents.isClosed) {
            _openaiRealtimeVoiceSessionEvents.addError(
              StateError('Realtime audio exceeded its memory limit.'),
            );
          }
          return;
        }
        _openaiRealtimeVoiceSessionPcm.add(bytes);
        _openaiRealtimeVoiceSessionPcmBytes += bytes.length;
      }
      if (!_openaiRealtimeVoiceSessionEvents.isClosed)
        _openaiRealtimeVoiceSessionEvents.add(event);
    } on FormatException {
      // Ignore malformed remote events while preserving session cleanup.
    }
  }

  Future<NazaRemoteModelProfile?>
  _openaiRealtimeVoiceSessionOpenAiProfile() async {
    final profiles = await NazaRemoteModelCatalog().load();
    for (final profile in profiles) {
      if (profile.provider == NazaRemoteProvider.openAi &&
          profile.enabled &&
          profile.apiKey.trim().isNotEmpty)
        return profile;
    }
    return null;
  }
}

