final class NazaVoiceSettingsCard extends StatefulWidget {
  const NazaVoiceSettingsCard({super.key, required this.advanced});

  final bool advanced;

  @override
  State<NazaVoiceSettingsCard> createState() =>
      _VoiceSettingsCardNazaVoiceSettingsCardState();
}

final class _VoiceSettingsCardNazaVoiceSettingsCardState
    extends State<NazaVoiceSettingsCard> {
  final NazaVoiceSettingsStore _voiceSettingsCardStore =
      NazaVoiceSettingsStore();
  final TextEditingController _voiceSettingsCardReplicateToken =
      TextEditingController();
  NazaVoiceSettings _voiceSettingsCardSettings = const NazaVoiceSettings();
  bool _voiceSettingsCardLoading = true;
  bool _voiceSettingsCardSaving = false;
  bool _voiceSettingsCardShowToken = false;
  String? _voiceSettingsCardStatus;

  @override
  void initState() {
    super.initState();
    unawaited(_voiceSettingsCardLoad());
  }

  @override
  void dispose() {
    _voiceSettingsCardReplicateToken.dispose();
    super.dispose();
  }

  Future<void> _voiceSettingsCardLoad() async {
    try {
      final settings = await _voiceSettingsCardStore.load();
      if (!mounted) return;
      setState(() {
        _voiceSettingsCardSettings = settings;
        _voiceSettingsCardLoading = false;
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _voiceSettingsCardLoading = false;
        _voiceSettingsCardStatus = _voiceSettingsCardMessage(error);
      });
    }
  }

  Future<void> _voiceSettingsCardSave() async {
    final enteredToken = _voiceSettingsCardReplicateToken.text.trim();
    final next = enteredToken.isEmpty
        ? _voiceSettingsCardSettings
        : _voiceSettingsCardSettings.copyWith(replicateApiToken: enteredToken);
    if (next.backend == NazaSpeechBackend.replicateBark &&
        next.replicateApiToken.isEmpty) {
      setState(
        () =>
            _voiceSettingsCardStatus = 'Enter a Replicate API token for Bark.',
      );
      return;
    }
    setState(() {
      _voiceSettingsCardSaving = true;
      _voiceSettingsCardStatus = null;
    });
    try {
      await _voiceSettingsCardStore.save(next);
      if (!mounted) return;
      setState(() {
        _voiceSettingsCardSettings = next;
        _voiceSettingsCardReplicateToken.clear();
        _voiceSettingsCardStatus =
            next.backend == NazaSpeechBackend.replicateBark
            ? 'Bark voice and human cadence saved in the encrypted vault.'
            : 'OpenAI voice and human cadence saved.';
      });
    } catch (error) {
      if (mounted)
        setState(
          () => _voiceSettingsCardStatus = _voiceSettingsCardMessage(error),
        );
    } finally {
      if (mounted) setState(() => _voiceSettingsCardSaving = false);
    }
  }

  Future<void> _voiceSettingsCardRemoveReplicateToken() async {
    setState(() {
      _voiceSettingsCardSaving = true;
      _voiceSettingsCardStatus = null;
    });
    try {
      final next = _voiceSettingsCardSettings.copyWith(
        backend: NazaSpeechBackend.openAi,
        clearReplicateApiToken: true,
      );
      await _voiceSettingsCardStore.save(next);
      if (!mounted) return;
      setState(() {
        _voiceSettingsCardSettings = next;
        _voiceSettingsCardReplicateToken.clear();
        _voiceSettingsCardStatus =
            'Replicate token removed; OpenAI voice restored.';
      });
    } catch (error) {
      if (mounted)
        setState(
          () => _voiceSettingsCardStatus = _voiceSettingsCardMessage(error),
        );
    } finally {
      if (mounted) setState(() => _voiceSettingsCardSaving = false);
    }
  }

  void _voiceSettingsCardUpdate(NazaVoiceSettings next) => setState(() {
    _voiceSettingsCardSettings = next;
    _voiceSettingsCardStatus = null;
  });

