  );
}

final class NazaConversationTitlePolicy {
  const NazaConversationTitlePolicy._();

  static String fallback(String text) {
    final cleaned = text
        .replaceAll(RegExp(r'https?://\S+'), ' ')
        .replaceAll(RegExp(r'[`*_#>\[\]{}()]'), ' ')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
    if (cleaned.isEmpty) return 'New conversation';

    final words = cleaned
        .split(' ')
        .where((word) => word.length > 1)
        .where((word) => !_historyDrawerStop.contains(word.toLowerCase()))
        .take(6)
        .toList(growable: false);
    if (words.isEmpty) return 'New conversation';
    final title = words.join(' ');
    return '${title[0].toUpperCase()}${title.substring(1)}';
  }

  static String sanitizeModelTitle(String generated, String fallbackText) {
    var title = generated
        .replaceAll(RegExp(r'''^[\s"'`#*-]+|[\s"'`#*.-]+$'''), '')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
    final words = title.split(' ').where((word) => word.isNotEmpty).toList();
    if (title.isEmpty || words.length > 8 || title.length > 72) {
      return fallback(fallbackText);
    }
    if (words.length > 6) title = words.take(6).join(' ');
    return title;
  }

  static const Set<String> _historyDrawerStop = <String>{
    'a',
    'an',
    'the',
    'please',
    'can',
    'could',
    'would',
    'you',
    'me',
    'my',
    'i',
    'we',
    'our',
    'this',
    'that',
    'with',
    'for',
    'to',
    'of',
    'in',
    'on',
  };
}

typedef NazaGenerateConversationTitle =
    Future<String> Function({
      required String userText,
      required String assistantText,
    });

final class NazaConversationTitleCoordinator {
  NazaConversationTitleCoordinator({required this.generateTitle});

  final NazaGenerateConversationTitle generateTitle;
  final Set<String> _historyDrawerAttempted = <String>{};
  final Map<String, Future<String>> _historyDrawerInFlight =
      <String, Future<String>>{};
  final Map<String, String> _historyDrawerCompleted = <String, String>{};

  Future<String> titleFor({
    required String threadId,
    required String userText,
    required String assistantText,
    bool force = false,
  }) {
    final fallback = NazaConversationTitlePolicy.fallback(userText);
    final completed = _historyDrawerCompleted[threadId];
    if (!force && completed != null) return Future.value(completed);
    if (!force && _historyDrawerAttempted.contains(threadId))
      return Future.value(fallback);
    final active = _historyDrawerInFlight[threadId];
    if (active != null) return active;

    _historyDrawerAttempted.add(threadId);
    final future = () async {
      try {
        final generated = await generateTitle(
          userText: userText,
          assistantText: assistantText,
        );
        final title = NazaConversationTitlePolicy.sanitizeModelTitle(
          generated,
          userText,
        );
        _historyDrawerCompleted[threadId] = title;
        return title;
      } catch (_) {
        _historyDrawerAttempted.remove(threadId);
        return fallback;
      } finally {
        _historyDrawerInFlight.remove(threadId);
      }
    }();
    _historyDrawerInFlight[threadId] = future;
    return future;
  }

  void allowRegeneration(String threadId) =>
      _historyDrawerAttempted.remove(threadId);
}

