// LLM-CONTEXT:BEGIN
// FILE: lib/chat/scroll_follow_controller.dart
// ROLE: Owns scroll follow controller behavior within the conversation subsystem.
// DOMAIN: conversation
// SECURITY-INVARIANT: Preserve turn identity, cancellation semantics, and encrypted-history ownership across async work.
// CHANGE-GUARD: Preserve public contracts, bounded inputs, lifecycle cleanup, and fail-closed behavior; run analysis and relevant tests after edits.
// DOCS: See /docs/llm-context-schema.md and the nearest mermaid.md architecture map.
// LLM-CONTEXT:END

/// Controls chat auto-follow without fighting the reader.
///
/// Streaming output follows the tail only while the user is already near it.
/// A deliberate upward scroll detaches auto-follow immediately; returning to
/// the bottom re-arms it. Programmatic scrolls are tracked separately so they
/// cannot be mistaken for user intent.
final class NazaChatScrollFollowController extends ChangeNotifier {
  NazaChatScrollFollowController({
    ScrollController? scrollController,
    this.tailThreshold = 92,
  }) : controller = scrollController ?? ScrollController(),
       _scrollFollowControllerOwnsController = scrollController == null {
    controller.addListener(_scrollFollowControllerOnPositionChanged);
  }

  final ScrollController controller;
  final bool _scrollFollowControllerOwnsController;
  final double tailThreshold;

  bool _scrollFollowControllerFollowTail = true;
  bool _scrollFollowControllerProgrammaticMove = false;
  bool _scrollFollowControllerDisposed = false;
  bool _scrollFollowControllerStreaming = false;
  bool _scrollFollowControllerScrollQueued = false;
  double _scrollFollowControllerLastPixels = 0;

  bool get followTail => _scrollFollowControllerFollowTail;
  bool get streaming => _scrollFollowControllerStreaming;
  bool get showJumpToLatest =>
      !_scrollFollowControllerFollowTail && controller.hasClients;

  void setStreaming(bool value) {
    if (_scrollFollowControllerStreaming == value) return;
    _scrollFollowControllerStreaming = value;
    notifyListeners();
  }

  bool handleNotification(ScrollNotification notification) {
    if (_scrollFollowControllerDisposed ||
        _scrollFollowControllerProgrammaticMove ||
        !controller.hasClients)
      return false;

    if (notification is UserScrollNotification) {
      if (notification.direction == ScrollDirection.forward &&
          _scrollFollowControllerFollowTail) {
        _scrollFollowControllerSetFollow(false);
      } else if (notification.direction == ScrollDirection.idle &&
          _scrollFollowControllerIsNearTail()) {
        _scrollFollowControllerSetFollow(true);
      }
    } else if (notification is ScrollEndNotification &&
        _scrollFollowControllerIsNearTail()) {
      _scrollFollowControllerSetFollow(true);
    }
    return false;
  }

  void onStreamPaint() {
    if (!_scrollFollowControllerFollowTail ||
        _scrollFollowControllerDisposed ||
        _scrollFollowControllerScrollQueued)
      return;

    // Coalesce all stream updates for the current frame into one tail move.
    // Using a post-frame callback avoids fighting layout while the latest text
    // chunk is still changing the scroll extent, which otherwise shows up as
    // small repeated viewport snaps during generation.
    _scrollFollowControllerScrollQueued = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _scrollFollowControllerScrollQueued = false;
      if (_scrollFollowControllerDisposed ||
          !_scrollFollowControllerFollowTail ||
          !controller.hasClients)
        return;
      unawaited(scrollToLatest(animated: false));
    });
  }

  Future<void> jumpToLatest() async {
    _scrollFollowControllerSetFollow(true);
    await scrollToLatest(animated: true);
  }

  Future<void> scrollToLatest({bool animated = false}) async {
    if (_scrollFollowControllerDisposed || !controller.hasClients) return;
    final position = controller.position;
    final target = position.maxScrollExtent;
    if ((target - position.pixels).abs() < 0.5) return;

    _scrollFollowControllerProgrammaticMove = true;
    try {
      if (animated) {
        await controller.animateTo(
          target,
          duration: const Duration(milliseconds: 180),
          curve: Curves.easeOutCubic,
        );
      } else {
        controller.jumpTo(target);
      }
    } finally {
      _scrollFollowControllerProgrammaticMove = false;
      if (_scrollFollowControllerIsNearTail())
        _scrollFollowControllerSetFollow(true);
    }
  }

  void armForConversationTail() {
    _scrollFollowControllerSetFollow(true);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!_scrollFollowControllerDisposed)
        unawaited(scrollToLatest(animated: false));
    });
  }

  void _scrollFollowControllerOnPositionChanged() {
    if (_scrollFollowControllerDisposed || !controller.hasClients) return;
    final pixels = controller.position.pixels;
    final delta = pixels - _scrollFollowControllerLastPixels;
    _scrollFollowControllerLastPixels = pixels;

    if (!_scrollFollowControllerProgrammaticMove) {
      if (delta < -1.5 && _scrollFollowControllerFollowTail) {
        _scrollFollowControllerSetFollow(false);
      } else if (_scrollFollowControllerIsNearTail() &&
          !_scrollFollowControllerFollowTail) {
        _scrollFollowControllerSetFollow(true);
      }
    }
  }

  bool _scrollFollowControllerIsNearTail() {
    if (!controller.hasClients) return true;
    final position = controller.position;
    return position.maxScrollExtent - position.pixels <= tailThreshold;
  }

  void _scrollFollowControllerSetFollow(bool value) {
    if (_scrollFollowControllerFollowTail == value ||
        _scrollFollowControllerDisposed)
      return;
    _scrollFollowControllerFollowTail = value;
    notifyListeners();
  }

  @override
  void dispose() {
    _scrollFollowControllerDisposed = true;
    controller.removeListener(_scrollFollowControllerOnPositionChanged);
    // The controller is injectable so a parent can coordinate scrolling with
    // another viewport. Only dispose controllers created by this object;
    // disposing an injected controller can invalidate an unrelated widget on
    // the next frame and is a particularly difficult lifecycle bug to trace.
    if (_scrollFollowControllerOwnsController) controller.dispose();
    super.dispose();
  }
}

