  late List<String> _chessTabBoard;
  String _chessTabTurn = 'w';
  int? _chessTabSelected;
  int? _chessTabEnPassantTarget;
  String _chessTabStatus = 'White to move';
  final List<String> _chessTabMoves = <String>[];
  final List<_ChessTabChessSnapshot> _chessTabUndoStack =
      <_ChessTabChessSnapshot>[];
  final List<_ChessTabChessSnapshot> _chessTabRedoStack =
      <_ChessTabChessSnapshot>[];
  final TextEditingController _chessTabPrompt = TextEditingController(
    text: _chessTabPromptPresets.first,
  );
  String _chessTabSelectedPreset = _chessTabPromptPresets.first;
  String _chessTabAgentPrompt = _chessTabPromptPresets.first;
  String _chessTabAgentBrief = '';
