/// Cleaner public food-scanner workspace.
///
/// Mature recipe/bake/safety surfaces are preserved in [legacy.FoodVisionHub]
/// under More while Fridge and Shelf get dedicated responsive scanner flows.
class FoodVisionHub extends StatefulWidget {
  final FoodRepository repository;
  final FoodPhotoPicker photoPicker;
  final FridgeImageAnalyzer analyzeFridgeImage;
  final BakeImageAnalyzer analyzeBakeImage;
  final FoodRecipeRegenerator regenerateRecipes;
  final VoidCallback onCancel;
  final Widget? foodSafetyChild;
  final FoodVisionDraftController? draftController;
  final String initialWorkspace;

  const FoodVisionHub({
    super.key,
    required this.repository,
    required this.photoPicker,
    required this.analyzeFridgeImage,
    required this.analyzeBakeImage,
    required this.regenerateRecipes,
    required this.onCancel,
    this.foodSafetyChild,
    this.draftController,
    this.initialWorkspace = 'fridge',
  });

  @override
  State<FoodVisionHub> createState() => _FoodHubFoodVisionHubState();
}

enum _FoodHubWorkspaceTab { fridge, shelf, recipes, bake, safety, more }

enum _FoodHubPhotoChoice { camera, gallery, files }

class _FoodHubFoodVisionHubState extends State<FoodVisionHub> {
  final ShelfRepository _foodHubShelfRepository = EncryptedShelfRepository();
  final Map<_FoodHubWorkspaceTab, Widget> _foodHubTabCache =
      <_FoodHubWorkspaceTab, Widget>{};
  late _FoodHubWorkspaceTab _foodHubTab;

  @override
  void initState() {
    super.initState();
    _foodHubTab = switch (widget.initialWorkspace) {
      'recipes' => _FoodHubWorkspaceTab.recipes,
      'shelf' => _FoodHubWorkspaceTab.shelf,
      'bake' => _FoodHubWorkspaceTab.bake,
      'safety' => _FoodHubWorkspaceTab.safety,
      'more' => _FoodHubWorkspaceTab.more,
      _ => _FoodHubWorkspaceTab.fridge,
    };
  }

  @override
  void didUpdateWidget(covariant FoodVisionHub oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.initialWorkspace == widget.initialWorkspace) return;
    final nextTab = switch (widget.initialWorkspace) {
      'recipes' => _FoodHubWorkspaceTab.recipes,
      'shelf' => _FoodHubWorkspaceTab.shelf,
      'bake' => _FoodHubWorkspaceTab.bake,
      'safety' => _FoodHubWorkspaceTab.safety,
      'more' => _FoodHubWorkspaceTab.more,
      _ => _FoodHubWorkspaceTab.fridge,
    };
    if (mounted) setState(() => _foodHubTab = nextTab);
  }

  Widget _foodHubTabFor(_FoodHubWorkspaceTab tab) {
    return _foodHubTabCache.putIfAbsent(tab, () {
      return switch (tab) {
        _FoodHubWorkspaceTab.fridge => _FoodHubCleanFridgePane(
          repository: widget.repository,
          photoPicker: widget.photoPicker,
          analyzer: widget.analyzeFridgeImage,
          onCancel: widget.onCancel,
        ),
        _FoodHubWorkspaceTab.shelf => ShelfScannerPane(
          repository: _foodHubShelfRepository,
          photoPicker: widget.photoPicker,
          analyzeVision: widget.analyzeFridgeImage,
          onCancel: widget.onCancel,
        ),
        _FoodHubWorkspaceTab.recipes => NazaLegacyFoodVisionHub(
          repository: widget.repository,
          photoPicker: widget.photoPicker,
          analyzeFridgeImage: widget.analyzeFridgeImage,
          analyzeBakeImage: widget.analyzeBakeImage,
          regenerateRecipes: widget.regenerateRecipes,
          onCancel: widget.onCancel,
          foodSafetyChild: widget.foodSafetyChild,
          draftController: widget.draftController,
          openRecipes: true,
        ),
        _FoodHubWorkspaceTab.bake => NazaLegacyFoodVisionHub(
          repository: widget.repository,
          photoPicker: widget.photoPicker,
          analyzeFridgeImage: widget.analyzeFridgeImage,
          analyzeBakeImage: widget.analyzeBakeImage,
          regenerateRecipes: widget.regenerateRecipes,
          onCancel: widget.onCancel,
          foodSafetyChild: widget.foodSafetyChild,
          draftController: widget.draftController,
          initialTab: 'bake',
        ),
        _FoodHubWorkspaceTab.safety => NazaLegacyFoodVisionHub(
          repository: widget.repository,
          photoPicker: widget.photoPicker,
          analyzeFridgeImage: widget.analyzeFridgeImage,
          analyzeBakeImage: widget.analyzeBakeImage,
          regenerateRecipes: widget.regenerateRecipes,
          onCancel: widget.onCancel,
          foodSafetyChild: widget.foodSafetyChild,
          draftController: widget.draftController,
          initialTab: 'safety',
        ),
        _FoodHubWorkspaceTab.more => NazaLegacyFoodVisionHub(
          repository: widget.repository,
          photoPicker: widget.photoPicker,
          analyzeFridgeImage: widget.analyzeFridgeImage,
          analyzeBakeImage: widget.analyzeBakeImage,
          regenerateRecipes: widget.regenerateRecipes,
          onCancel: widget.onCancel,
          foodSafetyChild: widget.foodSafetyChild,
          draftController: widget.draftController,
          initialTab: widget.initialWorkspace,
        ),
      };
    });
  }

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, _) {
        // Keep already visited tabs alive, but do not build hidden workspaces
        // on the first frame. The legacy More workspace is intentionally
        // large and used to cause a visible build hitch on Fridge startup.
        final body = IndexedStack(
          index: _foodHubTab.index,
          children: [
            for (final tab in _FoodHubWorkspaceTab.values)
              tab == _foodHubTab
                  ? _foodHubTabFor(tab)
                  : (_foodHubTabCache[tab] ?? const SizedBox()),
          ],
        );

        // App-level navigation is owned by NazaUnifiedFeatureDrawer/Rail.
        // Food workspaces remain content modes and are opened from the global
        // wheel (Recipes, Fridge, Shelf, Bake Lab, and FoodQualityScanner), preventing a second
        // competing rail or bottom navigation bar from consuming the shell.
        return Scaffold(
          body: Column(
            children: [
              Expanded(child: body),
              _FoodHubFoodAnalyticsStrip(repository: widget.repository),
            ],
          ),
        );
      },
    );
  }
}

final class _FoodHubFoodAnalyticsStrip extends StatefulWidget {
  final FoodRepository repository;
  const _FoodHubFoodAnalyticsStrip({required this.repository});
  @override
  State<_FoodHubFoodAnalyticsStrip> createState() =>
      _FoodHubFoodAnalyticsStripState();
}

class _FoodHubFoodAnalyticsStripState
    extends State<_FoodHubFoodAnalyticsStrip> {
  late Future<({List<FridgeLog> fridge, List<BakeLog> bake})> _foodHubFuture;
  @override
  void initState() {
    super.initState();
    _foodHubFuture = _foodHubLoad();
    widget.repository.revision.addListener(_foodHubRefresh);
  }

  @override
  void didUpdateWidget(covariant _FoodHubFoodAnalyticsStrip oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.repository != widget.repository) {
      oldWidget.repository.revision.removeListener(_foodHubRefresh);
      widget.repository.revision.addListener(_foodHubRefresh);
      _foodHubRefresh();
    }
  }

  @override
  void dispose() {
    widget.repository.revision.removeListener(_foodHubRefresh);
    super.dispose();
  }

  void _foodHubRefresh() {
    if (mounted) setState(() => _foodHubFuture = _foodHubLoad());
  }

  Future<({List<FridgeLog> fridge, List<BakeLog> bake})> _foodHubLoad() async =>
      (
        fridge: await widget.repository.listFridgeLogs(limit: 30),
        bake: await widget.repository.listBakeLogs(limit: 30),
      );
  @override
  Widget build(
    BuildContext context,
  ) => FutureBuilder<({List<FridgeLog> fridge, List<BakeLog> bake})>(
    future: _foodHubFuture,
    builder: (context, snapshot) {
      final data = snapshot.data;
      if (data == null) return const SizedBox(height: 4);
      final fridge = data.fridge.reversed.toList(growable: false);
      final bake = data.bake.reversed.toList(growable: false);
      return Padding(
        padding: const EdgeInsets.fromLTRB(12, 4, 12, 8),
        child: Card(
          clipBehavior: Clip.antiAlias,
          child: ExpansionTile(
            initiallyExpanded: false,
            leading: const Icon(Icons.auto_graph_rounded),
            title: const Text(
              'Kitchen trends',
              style: TextStyle(fontWeight: FontWeight.w900),
            ),
            subtitle: Text(
              '${data.fridge.length} fridge captures · ${data.bake.length} bake observations',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
            childrenPadding: const EdgeInsets.fromLTRB(10, 0, 10, 12),
            children: [
              NazaAnalyticsCard(
                title: 'Kitchen trends',
                subtitle: 'Descriptive trends, not safety guarantees',
                series: [
                  NazaTrendSeries(
                    name: 'Visible food items',
                    color: Colors.orangeAccent,
                    points: fridge.map(
                      (log) => NazaTrendPoint(
                        time: log.capturedAt,
                        value: log.analysis.items.length.toDouble(),
                      ),
                    ),
                  ),
                  NazaTrendSeries(
                    name: 'Bake estimate %',
                    color: Colors.lightBlueAccent,
                    points: bake.map(
                      (log) => NazaTrendPoint(
                        time: log.capturedAt,
                        value: log.simulation.estimatedPercent,
                      ),
                    ),
                  ),
                ],
              ),
            ],
          ),
        ),
      );
    },
  );
}

class _FoodHubCleanFridgePane extends StatefulWidget {
  final FoodRepository repository;
  final FoodPhotoPicker photoPicker;
  final FridgeImageAnalyzer analyzer;
  final VoidCallback onCancel;

  const _FoodHubCleanFridgePane({
    required this.repository,
    required this.photoPicker,
    required this.analyzer,
    required this.onCancel,
  });

  @override
  State<_FoodHubCleanFridgePane> createState() =>
      _FoodHubCleanFridgePaneState();
}

class _FoodHubCleanFridgePaneState extends State<_FoodHubCleanFridgePane> {
  final TextEditingController _foodHubNote = TextEditingController();
  FoodVisionImage? _foodHubImage;
  FridgeLog? _foodHubLatest;
  bool _foodHubStarted = false;
  bool _foodHubBusy = false;
  String _foodHubStatus = 'Ready for a private fridge scan';

  @override
  void initState() {
    super.initState();
    unawaited(_foodHubLoadLatest());
  }

  @override
  void dispose() {
    _foodHubNote.dispose();
    super.dispose();
  }

  Future<void> _foodHubLoadLatest() async {
    try {
      final logs = await widget.repository.listFridgeLogs(limit: 1);
      if (!mounted || logs.isEmpty) return;
      setState(() => _foodHubLatest = logs.first);
    } catch (_) {
      // A locked/unavailable vault is surfaced when an explicit action runs.
    }
  }

  Future<void> _foodHubPickPhoto() async {
    if (_foodHubBusy || !_foodHubStarted) return;
    final choice = await _foodHubChoosePhotoSource(context);
    if (choice == null || !mounted) return;
    setState(() {
      _foodHubBusy = true;
      _foodHubStatus = 'Preparing photo securely';
    });
    final result = switch (choice) {
      _FoodHubPhotoChoice.camera => await widget.photoPicker.captureCamera(),
      _FoodHubPhotoChoice.gallery => await widget.photoPicker.pickGallery(),
      _FoodHubPhotoChoice.files => await widget.photoPicker.pickFiles(),
    };
    if (!mounted) return;
    setState(() {
      _foodHubBusy = false;
      if (result.selected) {
        _foodHubImage = result.image;
        _foodHubStatus = 'Picture ready • source metadata discarded';
      } else {
        _foodHubStatus = result.message ?? 'Picture selection cancelled';
      }
    });
  }

  Future<void> _foodHubAnalyze() async {
    final image = _foodHubImage;
    if (_foodHubBusy || !_foodHubStarted || image == null) return;
    setState(() {
      _foodHubBusy = true;
      _foodHubStatus = 'Analyzing visible fridge inventory locally';
    });
    try {
      final analysis = await widget.analyzer(image, _foodHubNote.text.trim());
      final log = FridgeLog(
        id: newFoodId('fridge'),
        capturedAt: DateTime.now().toUtc(),
        image: image,
        note: _foodHubNote.text.trim(),
        analysis: analysis,
      );
      await widget.repository.saveFridgeLog(log);
      if (!mounted) return;
      setState(() {
        _foodHubLatest = log;
        _foodHubBusy = false;
        _foodHubStatus = analysis.status == FoodAnalysisStatus.complete
            ? 'Encrypted fridge scan saved'
            : 'Encrypted scan saved • review uncertainty';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _foodHubBusy = false;
        _foodHubStatus = 'Fridge scan failed: $error';
      });
    }
  }

  void _foodHubStop() {
    try {
      widget.onCancel();
    } catch (_) {}
    if (!mounted) return;
    setState(() {
      _foodHubBusy = false;
      _foodHubStatus = 'Scan stopped';
    });
  }

  @override
  Widget build(BuildContext context) {
    final width = MediaQuery.sizeOf(context).width;
    final wide = width >= 900;
    final controls = _FoodHubFridgeControls(
      image: _foodHubImage,
      note: _foodHubNote,
      busy: _foodHubBusy,
      started: _foodHubStarted,
      onPicture: _foodHubPickPhoto,
      onClear: _foodHubBusy
          ? null
          : () => setState(() {
              _foodHubImage = null;
              _foodHubStatus = 'Picture cleared';
            }),
      onAnalyze: _foodHubBusy || !_foodHubStarted || _foodHubImage == null
          ? null
          : _foodHubAnalyze,
    );
    final results = _FoodHubFridgeResults(log: _foodHubLatest);

    return SafeArea(
      child: Padding(
        padding: EdgeInsets.all(wide ? 20 : 12),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: <Widget>[
            _FoodHubScannerHeader(
              title: 'Fridge Scanner',
              subtitle: _foodHubStatus,
              started: _foodHubStarted,
              busy: _foodHubBusy,
              onStart: () => setState(() {
                _foodHubStarted = true;
                _foodHubStatus = 'Scanner started • choose a picture';
              }),
              onStop: _foodHubStop,
              onPicture: _foodHubStarted && !_foodHubBusy
                  ? _foodHubPickPhoto
                  : null,
            ),
            const SizedBox(height: 12),
            Expanded(
              child: wide
                  ? Row(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: <Widget>[
                        Expanded(child: controls),
                        const SizedBox(width: 12),
                        Expanded(child: results),
                      ],
                    )
                  : ListView(
                      keyboardDismissBehavior:
                          ScrollViewKeyboardDismissBehavior.onDrag,
                      children: <Widget>[
                        controls,
                        const SizedBox(height: 12),
                        results,
                      ],
                    ),
            ),
          ],
        ),
      ),
    );
  }
}

