// LLM-CONTEXT:BEGIN
// FILE: lib/food/food_hub_legacy.dart
// ROLE: Owns food hub legacy behavior within the food-vision subsystem.
// DOMAIN: food-vision
// SECURITY-INVARIANT: Bound image/data inputs and distinguish visible evidence from model inference.
// CHANGE-GUARD: Preserve public contracts, bounded inputs, lifecycle cleanup, and fail-closed behavior; run analysis and relevant tests after edits.
// DOCS: See /docs/llm-context-schema.md and the nearest mermaid.md architecture map.
// LLM-CONTEXT:END

typedef FridgeImageAnalyzer =
    Future<FridgeAnalysis> Function(FoodVisionImage image, String note);
typedef BakeImageAnalyzer =
    Future<BakeVisualAssessment> Function(
      FoodVisionImage image,
      BakeInput input,
    );
typedef FoodRecipeRegenerator =
    Future<List<RecipeSuggestion>> Function(FridgeAnalysis analysis);

/// Owns unfinished food-form text independently from the selected app panel.
///
/// The top-level app can retain one of these while [FoodVisionHub] is offstage
/// or rebuilt, so a navigation tap never discards a fridge note or bake setup.
class FoodVisionDraftController {
  final TextEditingController fridgeNote = TextEditingController();
  final TextEditingController bakeName = TextEditingController(text: 'Pizza');
  final TextEditingController elapsedMinutes = TextEditingController();
  final TextEditingController plannedMinutes = TextEditingController();
  final TextEditingController ovenTemperature = TextEditingController();
  final TextEditingController probeTemperature = TextEditingController();
  final TextEditingController targetTemperature = TextEditingController();
  final TextEditingController bakeNotes = TextEditingController();

  void dispose() {
    fridgeNote.dispose();
    bakeName.dispose();
    elapsedMinutes.dispose();
    plannedMinutes.dispose();
    ovenTemperature.dispose();
    probeTemperature.dispose();
    targetTemperature.dispose();
    bakeNotes.dispose();
  }
}

/// A self-contained food-vision workspace with no chat or continuation state.
///
/// Vision and recipe generation are injected so the UI stays independent from
/// any particular local-model runtime. Completed analyses are persisted through
/// [repository] as authenticated food records.
class NazaLegacyFoodVisionHub extends StatefulWidget {
  final FoodRepository repository;
  final FoodPhotoPicker photoPicker;
  final FridgeImageAnalyzer analyzeFridgeImage;
  final BakeImageAnalyzer analyzeBakeImage;
  final FoodRecipeRegenerator regenerateRecipes;
  final VoidCallback onCancel;
  final Widget? foodSafetyChild;
  final FoodVisionDraftController? draftController;
  final bool openRecipes;
  final String initialTab;

  const NazaLegacyFoodVisionHub({
    super.key,
    required this.repository,
    required this.photoPicker,
    required this.analyzeFridgeImage,
    required this.analyzeBakeImage,
    required this.regenerateRecipes,
    required this.onCancel,
    this.foodSafetyChild,
    this.draftController,
    this.openRecipes = false,
    this.initialTab = 'fridge',
  });

  @override
  State<NazaLegacyFoodVisionHub> createState() =>
      _FoodHubLegacyFoodVisionHubState();
}

enum _FoodHubLegacyFoodHubTab { fridge, recipes, bake, safety }

enum _FoodHubLegacyHubTask {
  loadingHistory,
  fridgePhoto,
  fridgeAnalysis,
  recipeGeneration,
  bakePhoto,
  bakeAnalysis,
}

extension on _FoodHubLegacyHubTask {
  bool get canCancel => switch (this) {
    _FoodHubLegacyHubTask.fridgeAnalysis ||
    _FoodHubLegacyHubTask.recipeGeneration ||
    _FoodHubLegacyHubTask.bakeAnalysis => true,
    _ => false,
  };
}

class _FoodHubLegacyFoodVisionHubState extends State<NazaLegacyFoodVisionHub> {
  late final FoodVisionDraftController _foodHubLegacyDraft;
  late final bool _foodHubLegacyOwnsDraft;

  TextEditingController get _foodHubLegacyFridgeNote =>
      _foodHubLegacyDraft.fridgeNote;
  TextEditingController get _foodHubLegacyBakeName =>
      _foodHubLegacyDraft.bakeName;
  TextEditingController get _foodHubLegacyElapsedMinutes =>
      _foodHubLegacyDraft.elapsedMinutes;
  TextEditingController get _foodHubLegacyPlannedMinutes =>
      _foodHubLegacyDraft.plannedMinutes;
  TextEditingController get _foodHubLegacyOvenTemperature =>
      _foodHubLegacyDraft.ovenTemperature;
  TextEditingController get _foodHubLegacyProbeTemperature =>
      _foodHubLegacyDraft.probeTemperature;
  TextEditingController get _foodHubLegacyTargetTemperature =>
      _foodHubLegacyDraft.targetTemperature;
  TextEditingController get _foodHubLegacyBakeNotes =>
      _foodHubLegacyDraft.bakeNotes;

  late _FoodHubLegacyFoodHubTab _foodHubLegacyTab;

  _FoodHubLegacyHubTask? _foodHubLegacyTask;
  FoodVisionImage? _foodHubLegacyFridgeImage;
  FoodVisionImage? _foodHubLegacyBakeImage;
  BakeItemKind _foodHubLegacyBakeKind = BakeItemKind.pizza;
  List<FridgeLog> _foodHubLegacyFridgeLogs = const [];
  List<BakeLog> _foodHubLegacyBakeLogs = const [];
  String _foodHubLegacyStatus = 'Private kitchen ready';
  String? _foodHubLegacyNotice;
  bool _foodHubLegacyNoticeIsError = false;
  int _foodHubLegacyOperationSerial = 0;

  @override
  void initState() {
    super.initState();
    _foodHubLegacyTab = widget.openRecipes
        ? _FoodHubLegacyFoodHubTab.recipes
        : switch (widget.initialTab) {
            'bake' => _FoodHubLegacyFoodHubTab.bake,
            'safety' => _FoodHubLegacyFoodHubTab.safety,
            _ => _FoodHubLegacyFoodHubTab.fridge,
          };
    _foodHubLegacyOwnsDraft = widget.draftController == null;
    _foodHubLegacyDraft = widget.draftController ?? FoodVisionDraftController();
    widget.repository.revision.addListener(
      _foodHubLegacyHandleRepositoryRevision,
    );
    unawaited(_foodHubLegacyLoadLogs());
  }

  @override
  void didUpdateWidget(covariant NazaLegacyFoodVisionHub oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!identical(oldWidget.repository, widget.repository)) {
      oldWidget.repository.revision.removeListener(
        _foodHubLegacyHandleRepositoryRevision,
      );
      widget.repository.revision.addListener(
        _foodHubLegacyHandleRepositoryRevision,
      );
      unawaited(_foodHubLegacyLoadLogs());
    }
  }

  @override
  void dispose() {
    _foodHubLegacyOperationSerial++;
    widget.repository.revision.removeListener(
      _foodHubLegacyHandleRepositoryRevision,
    );
    if (_foodHubLegacyOwnsDraft) _foodHubLegacyDraft.dispose();
    super.dispose();
  }

  bool get _foodHubLegacyBusy => _foodHubLegacyTask != null;

  FridgeLog? get _foodHubLegacyLatestFridgeLog =>
      _foodHubLegacyFridgeLogs.isEmpty ? null : _foodHubLegacyFridgeLogs.first;

  BakeLog? get _foodHubLegacyLatestBakeLog =>
      _foodHubLegacyBakeLogs.isEmpty ? null : _foodHubLegacyBakeLogs.first;

  void _foodHubLegacyHandleRepositoryRevision() {
    if (_foodHubLegacyBusy) return;
    unawaited(_foodHubLegacyLoadLogs());
  }

  Future<void> _foodHubLegacyLoadLogs() async {
    final token = _foodHubLegacyBeginTask(
      _FoodHubLegacyHubTask.loadingHistory,
      'Opening encrypted food journal',
      clearNotice: false,
    );
    try {
      final results = await Future.wait<Object>([
        widget.repository.listFridgeLogs(),
        widget.repository.listBakeLogs(),
      ]);
      if (!_foodHubLegacyIsCurrent(token)) return;
      final fridge = List<FridgeLog>.from(results[0] as List<FridgeLog>)
        ..sort((a, b) => b.capturedAt.compareTo(a.capturedAt));
      final bake = List<BakeLog>.from(results[1] as List<BakeLog>)
        ..sort((a, b) => b.capturedAt.compareTo(a.capturedAt));
      setState(() {
        _foodHubLegacyFridgeLogs = List<FridgeLog>.unmodifiable(fridge);
        _foodHubLegacyBakeLogs = List<BakeLog>.unmodifiable(bake);
        _foodHubLegacyTask = null;
        _foodHubLegacyStatus = 'Private kitchen ready';
      });
    } catch (error) {
      _foodHubLegacyFinishWithError(
        token,
        'Encrypted food history could not be opened: $error',
      );
    }
  }

  int _foodHubLegacyBeginTask(
    _FoodHubLegacyHubTask task,
    String status, {
    bool clearNotice = true,
  }) {
    final token = ++_foodHubLegacyOperationSerial;
    if (mounted) {
      setState(() {
        _foodHubLegacyTask = task;
        _foodHubLegacyStatus = status;
        if (clearNotice) _foodHubLegacyNotice = null;
      });
    }
    return token;
  }

  bool _foodHubLegacyIsCurrent(int token) =>
      mounted && token == _foodHubLegacyOperationSerial;

  void _foodHubLegacyFinishTask(int token, String status, {String? notice}) {
    if (!_foodHubLegacyIsCurrent(token)) return;
    setState(() {
      _foodHubLegacyTask = null;
      _foodHubLegacyStatus = status;
      _foodHubLegacyNotice = notice;
      _foodHubLegacyNoticeIsError = false;
    });
  }

  void _foodHubLegacyFinishWithError(int token, Object error) {
    if (!_foodHubLegacyIsCurrent(token)) return;
    setState(() {
      _foodHubLegacyTask = null;
      _foodHubLegacyStatus = 'Needs attention';
      _foodHubLegacyNotice = error.toString();
      _foodHubLegacyNoticeIsError = true;
    });
  }

  void _foodHubLegacyCancelActiveTask() {
    final task = _foodHubLegacyTask;
    if (task == null || !task.canCancel) return;
    _foodHubLegacyOperationSerial++;
    try {
      widget.onCancel();
    } catch (_) {
      // Cancellation remains best-effort; stale operation results are ignored.
    }
    setState(() {
      _foodHubLegacyTask = null;
      _foodHubLegacyStatus = 'Analysis stopped';
      _foodHubLegacyNotice =
          'The active local-model task was stopped. Your selected photo and form values were kept.';
      _foodHubLegacyNoticeIsError = false;
    });
  }

  Future<void> _foodHubLegacyPickFridgePhoto(FoodPhotoSource source) async {
    if (_foodHubLegacyBusy) return;
    final token = _foodHubLegacyBeginTask(
      _FoodHubLegacyHubTask.fridgePhoto,
      'Opening ${_foodHubLegacySourceLabel(source)}',
    );
    try {
      final result = await widget.photoPicker.pick(source);
      if (!_foodHubLegacyIsCurrent(token)) return;
      switch (result.outcome) {
        case FoodPhotoPickOutcome.selected:
          final image = result.image;
          if (image == null) {
            _foodHubLegacyFinishWithError(
              token,
              'The photo picker returned no image.',
            );
            return;
          }
          setState(() {
            _foodHubLegacyFridgeImage = image;
            _foodHubLegacyTask = null;
            _foodHubLegacyStatus = 'Fridge photo ready';
            _foodHubLegacyNotice =
                'Review the photo, add an optional note, then analyze and save it to the encrypted journal.';
            _foodHubLegacyNoticeIsError = false;
          });
          break;
        case FoodPhotoPickOutcome.cancelled:
          _foodHubLegacyFinishTask(token, 'Photo selection cancelled');
          break;
        case FoodPhotoPickOutcome.unavailable:
        case FoodPhotoPickOutcome.failed:
          _foodHubLegacyFinishWithError(
            token,
            result.message ?? 'The selected photo could not be prepared.',
          );
          break;
      }
    } catch (error) {
      _foodHubLegacyFinishWithError(token, 'Photo selection failed: $error');
    }
  }

  Future<void> _foodHubLegacyPickBakePhoto(FoodPhotoSource source) async {
    if (_foodHubLegacyBusy) return;
    final token = _foodHubLegacyBeginTask(
      _FoodHubLegacyHubTask.bakePhoto,
      'Opening ${_foodHubLegacySourceLabel(source)}',
    );
    try {
      final result = await widget.photoPicker.pick(source);
      if (!_foodHubLegacyIsCurrent(token)) return;
      switch (result.outcome) {
        case FoodPhotoPickOutcome.selected:
          final image = result.image;
          if (image == null) {
            _foodHubLegacyFinishWithError(
              token,
              'The photo picker returned no image.',
            );
            return;
          }
          setState(() {
            _foodHubLegacyBakeImage = image;
            _foodHubLegacyTask = null;
            _foodHubLegacyStatus = 'Bake photo ready';
            _foodHubLegacyNotice =
                'Add timing and temperature evidence before running the completion simulation.';
            _foodHubLegacyNoticeIsError = false;
          });
          break;
        case FoodPhotoPickOutcome.cancelled:
          _foodHubLegacyFinishTask(token, 'Photo selection cancelled');
          break;
        case FoodPhotoPickOutcome.unavailable:
        case FoodPhotoPickOutcome.failed:
          _foodHubLegacyFinishWithError(
            token,
            result.message ?? 'The selected photo could not be prepared.',
          );
          break;
      }
    } catch (error) {
      _foodHubLegacyFinishWithError(token, 'Photo selection failed: $error');
    }
  }

  Future<void> _foodHubLegacyAnalyzeFridge() async {
    final image = _foodHubLegacyFridgeImage;
    if (_foodHubLegacyBusy || image == null) {
      _foodHubLegacyShowError('Take or choose a fridge photo first.');
      return;
    }
    final note = _foodHubLegacyFridgeNote.text.trim();
    final token = _foodHubLegacyBeginTask(
      _FoodHubLegacyHubTask.fridgeAnalysis,
      'Analyzing fridge locally',
    );
    try {
      final analysis = await widget.analyzeFridgeImage(image, note);
      if (!_foodHubLegacyIsCurrent(token)) return;
      final log = FridgeLog(
        id: newFoodId('fridge'),
        capturedAt: DateTime.now().toUtc(),
        image: image,
        note: note,
        analysis: analysis,
      );
      await widget.repository.saveFridgeLog(log);
      if (!_foodHubLegacyIsCurrent(token)) return;
      setState(() {
        _foodHubLegacyFridgeLogs = List<FridgeLog>.unmodifiable(<FridgeLog>[
          log,
          ..._foodHubLegacyFridgeLogs.where((entry) => entry.id != log.id),
        ]);
        _foodHubLegacyTask = null;
        _foodHubLegacyStatus = 'Fridge log saved';
        _foodHubLegacyNotice = analysis.status == FoodAnalysisStatus.complete
            ? 'The photo and structured inventory were saved in the encrypted SQLite journal.'
            : 'The photo was saved. Review the uncertainty notes before relying on the partial analysis.';
        _foodHubLegacyNoticeIsError =
            analysis.status == FoodAnalysisStatus.failed;
      });
    } catch (error) {
      _foodHubLegacyFinishWithError(
        token,
        'Fridge analysis or encrypted save did not complete: $error',
      );
    }
  }

  Future<void> _foodHubLegacyRegenerateRecipes() async {
    final sourceLog = _foodHubLegacyLatestFridgeLog;
    if (_foodHubLegacyBusy || sourceLog == null) {
      _foodHubLegacyShowError(
        'Save a fridge analysis before generating recipes.',
      );
      return;
    }
    final token = _foodHubLegacyBeginTask(
      _FoodHubLegacyHubTask.recipeGeneration,
      'Building recipes from the latest log',
    );
    try {
      final recipes = await widget.regenerateRecipes(sourceLog.analysis);
      if (!_foodHubLegacyIsCurrent(token)) return;
      final updatedAnalysis = _foodHubLegacyAnalysisWithRecipes(
        sourceLog.analysis,
        recipes,
      );
      final updatedLog = sourceLog.copyWith(analysis: updatedAnalysis);
      await widget.repository.saveFridgeLog(updatedLog);
      if (!_foodHubLegacyIsCurrent(token)) return;
      setState(() {
        _foodHubLegacyFridgeLogs = List<FridgeLog>.unmodifiable(
          _foodHubLegacyFridgeLogs
              .map((entry) => entry.id == updatedLog.id ? updatedLog : entry)
              .toList(growable: false),
        );
        _foodHubLegacyTask = null;
        _foodHubLegacyStatus = 'Recipe ideas refreshed';
        _foodHubLegacyNotice = recipes.isEmpty
            ? 'No recipe passed structured validation. Confirm the visible inventory and try again.'
            : '${recipes.length} recipe ${recipes.length == 1 ? 'idea was' : 'ideas were'} saved with the latest fridge log.';
        _foodHubLegacyNoticeIsError = false;
      });
    } catch (error) {
      _foodHubLegacyFinishWithError(
        token,
        'Recipe generation did not complete: $error',
      );
    }
  }

  Future<void> _foodHubLegacyAnalyzeBake() async {
    final image = _foodHubLegacyBakeImage;
    if (_foodHubLegacyBusy || image == null) {
      _foodHubLegacyShowError('Take or choose a bake photo first.');
      return;
    }
    final input = _foodHubLegacyBuildBakeInput();
    if (input == null) return;

    final token = _foodHubLegacyBeginTask(
      _FoodHubLegacyHubTask.bakeAnalysis,
      'Inspecting visible bake cues',
    );
    try {
      final visual = await widget.analyzeBakeImage(image, input);
      if (!_foodHubLegacyIsCurrent(token)) return;
      final simulation = BakeSimulationEngine.estimate(
        input: input,
        visual: visual,
      );
      final log = BakeLog(
        id: newFoodId('bake'),
        capturedAt: DateTime.now().toUtc(),
        image: image,
        input: input,
        visual: visual,
        simulation: simulation,
      );
      await widget.repository.saveBakeLog(log);
      if (!_foodHubLegacyIsCurrent(token)) return;
      setState(() {
        _foodHubLegacyBakeLogs = List<BakeLog>.unmodifiable(<BakeLog>[
          log,
          ..._foodHubLegacyBakeLogs.where((entry) => entry.id != log.id),
        ]);
        _foodHubLegacyTask = null;
        _foodHubLegacyStatus = 'Bake estimate saved';
        _foodHubLegacyNotice =
            'The visual assessment and deterministic simulation were saved. Completion percentage is not a food-safety verdict.';
        _foodHubLegacyNoticeIsError = false;
      });
    } catch (error) {
      _foodHubLegacyFinishWithError(
        token,
        'Bake analysis or encrypted save failed: $error',
      );
    }
  }

  BakeInput? _foodHubLegacyBuildBakeInput() {
    final elapsed = _foodHubLegacyRequiredNumber(
      _foodHubLegacyElapsedMinutes,
      'Elapsed minutes',
    );
    final planned = _foodHubLegacyRequiredNumber(
      _foodHubLegacyPlannedMinutes,
      'Planned minutes',
    );
    if (elapsed == null || planned == null) return null;
    if (planned <= 0) {
      _foodHubLegacyShowError('Planned minutes must be greater than zero.');
      return null;
    }

    final oven = _foodHubLegacyOptionalNumber(
      _foodHubLegacyOvenTemperature,
      'Oven temperature',
    );
    final probe = _foodHubLegacyOptionalNumber(
      _foodHubLegacyProbeTemperature,
      'Probe temperature',
    );
    final target = _foodHubLegacyOptionalNumber(
      _foodHubLegacyTargetTemperature,
      'Target temperature',
    );
    if (_foodHubLegacyHasInvalidOptionalNumber) {
      _foodHubLegacyHasInvalidOptionalNumber = false;
      return null;
    }
    if ((probe == null) != (target == null)) {
      _foodHubLegacyShowError(
        'Enter both probe and target temperatures, or leave both blank.',
      );
      return null;
    }

    return BakeInput(
      kind: _foodHubLegacyBakeKind,
      itemName: _foodHubLegacyBakeName.text.trim().isEmpty
          ? _foodHubLegacyKindLabel(_foodHubLegacyBakeKind)
          : _foodHubLegacyBakeName.text.trim(),
      elapsedMinutes: elapsed,
      plannedMinutes: planned,
      ovenTemperatureF: oven,
      startingTemperatureF: null,
      probeTemperatureF: probe,
      targetTemperatureF: target,
      notes: _foodHubLegacyBakeNotes.text.trim(),
    );
  }

  bool _foodHubLegacyHasInvalidOptionalNumber = false;

  double? _foodHubLegacyRequiredNumber(
    TextEditingController controller,
    String label,
  ) {
    final value = double.tryParse(controller.text.trim());
    if (value == null || !value.isFinite || value < 0) {
      _foodHubLegacyShowError('$label must be a non-negative number.');
      return null;
    }
    return value;
  }

  double? _foodHubLegacyOptionalNumber(
    TextEditingController controller,
    String label,
  ) {
    final text = controller.text.trim();
    if (text.isEmpty) return null;
    final value = double.tryParse(text);
    if (value == null || !value.isFinite || value < 0) {
      _foodHubLegacyHasInvalidOptionalNumber = true;
      _foodHubLegacyShowError(
        '$label must be a non-negative number or left blank.',
      );
      return null;
    }
    return value;
  }

  void _foodHubLegacyShowError(String message) {
    if (!mounted) return;
    setState(() {
      _foodHubLegacyNotice = message;
      _foodHubLegacyNoticeIsError = true;
      _foodHubLegacyStatus = 'Needs attention';
    });
  }

  FridgeAnalysis _foodHubLegacyAnalysisWithRecipes(
    FridgeAnalysis source,
    List<RecipeSuggestion> recipes,
  ) {
    return FridgeAnalysis(
      status: source.status,
      summary: source.summary,
      items: source.items,
      useSoon: source.useSoon,
      ingredientSuggestions: source.ingredientSuggestions,
      recipes: List<RecipeSuggestion>.unmodifiable(recipes),
      uncertainties: source.uncertainties,
      rawModelText: source.rawModelText,
    );
  }

  @override
  Widget build(BuildContext context) {
    final inherited = Theme.of(context);
    // This workspace is mounted under the app's Food > More tab. Keep its
    // compact kitchen layout, but inherit the selected app color scheme rather
    // than installing a second, permanently green theme over the subtree.
    final scheme = inherited.colorScheme;
    final theme = inherited.copyWith(
      colorScheme: scheme,
      scaffoldBackgroundColor: inherited.scaffoldBackgroundColor,
      cardColor: scheme.surfaceContainer,
      dividerColor: scheme.outlineVariant,
      inputDecorationTheme: InputDecorationTheme(
        filled: true,
        fillColor: scheme.surfaceContainerHighest,
        labelStyle: TextStyle(color: scheme.onSurfaceVariant),
        hintStyle: TextStyle(
          color: scheme.onSurfaceVariant.withValues(alpha: 0.72),
        ),
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(18),
          borderSide: BorderSide(color: scheme.outlineVariant),
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(18),
          borderSide: BorderSide(color: scheme.outlineVariant),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(18),
          borderSide: BorderSide(color: scheme.secondary, width: 1.6),
        ),
      ),
    );

    return Theme(
      data: theme,
      child: LayoutBuilder(
        builder: (context, constraints) {
          final wide = constraints.maxWidth >= 900;
          return Scaffold(
            appBar: AppBar(
              backgroundColor: scheme.surface,
              surfaceTintColor: Colors.transparent,
              elevation: 0,
              titleSpacing: wide ? 24 : 16,
              title: Row(
                children: [
                  const _FoodHubLegacyHubMark(),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text(
                          'Naza Kitchen',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(fontWeight: FontWeight.w900),
                        ),
                        Text(
                          _foodHubLegacyStatus,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                            color: scheme.onSurfaceVariant,
                            fontSize: 11,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
              actions: [
                if (_foodHubLegacyTask?.canCancel == true)
                  Padding(
                    padding: const EdgeInsets.only(right: 10),
                    child: FilledButton.tonalIcon(
                      onPressed: _foodHubLegacyCancelActiveTask,
                      icon: const Icon(Icons.stop_circle_outlined),
                      label: const Text('Stop'),
                      style: FilledButton.styleFrom(
                        foregroundColor: _FoodHubLegacyFoodColors.warning,
                      ),
                    ),
                  ),
              ],
            ),
            body: DecoratedBox(
              decoration: BoxDecoration(
                color: inherited.scaffoldBackgroundColor,
              ),
              child: wide
                  ? Row(
                      children: [
                        _FoodHubLegacyHubRail(
                          tab: _foodHubLegacyTab,
                          onSelected: _foodHubLegacySelectTab,
                        ),
                        const VerticalDivider(width: 1),
                        Expanded(child: _foodHubLegacyBuildTabBody()),
                      ],
                    )
                  : _foodHubLegacyBuildTabBody(),
            ),
            bottomNavigationBar: wide
                ? null
                : NavigationBar(
                    selectedIndex: _foodHubLegacyTab.index,
                    onDestinationSelected: (index) => _foodHubLegacySelectTab(
                      _FoodHubLegacyFoodHubTab.values[index],
                    ),
                    backgroundColor: scheme.surface,
                    indicatorColor: scheme.secondary.withValues(alpha: 0.22),
                    destinations: const [
                      NavigationDestination(
                        icon: Icon(Icons.kitchen_outlined),
                        selectedIcon: Icon(Icons.kitchen_rounded),
                        label: 'Fridge',
                      ),
                      NavigationDestination(
                        icon: Icon(Icons.menu_book_outlined),
                        selectedIcon: Icon(Icons.menu_book_rounded),
                        label: 'Recipes',
                      ),
                      NavigationDestination(
                        icon: Icon(Icons.bakery_dining_outlined),
                        selectedIcon: Icon(Icons.bakery_dining_rounded),
                        label: 'Bake Lab',
                      ),
                      NavigationDestination(
                        icon: Icon(Icons.health_and_safety_outlined),
                        selectedIcon: Icon(Icons.health_and_safety_rounded),
                        label: 'Safety',
                      ),
                    ],
                  ),
          );
        },
      ),
    );
  }

  void _foodHubLegacySelectTab(_FoodHubLegacyFoodHubTab tab) {
    if (_foodHubLegacyTab == tab) return;
    setState(() => _foodHubLegacyTab = tab);
  }

  Widget _foodHubLegacyBuildTabBody() {
    return Column(
      children: [
        if (_foodHubLegacyNotice != null)
          _FoodHubLegacyHubNotice(
            message: _foodHubLegacyNotice!,
            error: _foodHubLegacyNoticeIsError,
            onDismiss: () => setState(() => _foodHubLegacyNotice = null),
          ),
        if (_foodHubLegacyBusy) const LinearProgressIndicator(minHeight: 2),
        Expanded(
          child: IndexedStack(
            index: _foodHubLegacyTab.index,
            children: [
              _FoodHubLegacyFridgeLogTab(
                image: _foodHubLegacyFridgeImage,
                noteController: _foodHubLegacyFridgeNote,
                latestLog: _foodHubLegacyLatestFridgeLog,
                recentLogs: _foodHubLegacyFridgeLogs,
                busy: _foodHubLegacyBusy,
                onCamera: () => unawaited(
                  _foodHubLegacyPickFridgePhoto(FoodPhotoSource.camera),
                ),
                onGallery: () => unawaited(
                  _foodHubLegacyPickFridgePhoto(FoodPhotoSource.gallery),
                ),
                onRemovePhoto: _foodHubLegacyBusy
                    ? null
                    : () => setState(() => _foodHubLegacyFridgeImage = null),
                onAnalyze:
                    _foodHubLegacyBusy || _foodHubLegacyFridgeImage == null
                    ? null
                    : () => unawaited(_foodHubLegacyAnalyzeFridge()),
                onOpenRecipes: () =>
                    _foodHubLegacySelectTab(_FoodHubLegacyFoodHubTab.recipes),
              ),
              _FoodHubLegacyRecipesTab(
                sourceLog: _foodHubLegacyLatestFridgeLog,
                busy: _foodHubLegacyBusy,
                onRegenerate:
                    _foodHubLegacyBusy || _foodHubLegacyLatestFridgeLog == null
                    ? null
                    : () => unawaited(_foodHubLegacyRegenerateRecipes()),
                onOpenFridge: () =>
                    _foodHubLegacySelectTab(_FoodHubLegacyFoodHubTab.fridge),
              ),
              _FoodHubLegacyBakeLabTab(
                image: _foodHubLegacyBakeImage,
                latestLog: _foodHubLegacyLatestBakeLog,
                recentLogs: _foodHubLegacyBakeLogs,
                busy: _foodHubLegacyBusy,
                kind: _foodHubLegacyBakeKind,
                onKindChanged: _foodHubLegacyBusy
                    ? null
                    : (kind) {
                        if (kind == null) return;
                        setState(() {
                          _foodHubLegacyBakeKind = kind;
                          if (_foodHubLegacyBakeName.text.trim().isEmpty) {
                            _foodHubLegacyBakeName.text =
                                _foodHubLegacyKindLabel(kind);
                          }
                        });
                      },
                nameController: _foodHubLegacyBakeName,
                elapsedController: _foodHubLegacyElapsedMinutes,
                plannedController: _foodHubLegacyPlannedMinutes,
                ovenController: _foodHubLegacyOvenTemperature,
                probeController: _foodHubLegacyProbeTemperature,
                targetController: _foodHubLegacyTargetTemperature,
                notesController: _foodHubLegacyBakeNotes,
                onCamera: () => unawaited(
                  _foodHubLegacyPickBakePhoto(FoodPhotoSource.camera),
                ),
                onGallery: () => unawaited(
                  _foodHubLegacyPickBakePhoto(FoodPhotoSource.gallery),
                ),
                onRemovePhoto: _foodHubLegacyBusy
                    ? null
                    : () => setState(() => _foodHubLegacyBakeImage = null),
                onAnalyze: _foodHubLegacyBusy || _foodHubLegacyBakeImage == null
                    ? null
                    : () => unawaited(_foodHubLegacyAnalyzeBake()),
              ),
              _FoodHubLegacySafetyTab(child: widget.foodSafetyChild),
            ],
          ),
        ),
      ],
    );
  }

  static String _foodHubLegacySourceLabel(FoodPhotoSource source) =>
      switch (source) {
        FoodPhotoSource.camera => 'camera',
        FoodPhotoSource.gallery => 'photo library',
      };
}

