class _FoodHubLegacyPhotoSurface extends StatelessWidget {
  final FoodVisionImage? image;
  final bool enabled;
  final VoidCallback onCamera;
  final VoidCallback onGallery;
  final VoidCallback? onRemove;
  final String emptyTitle;
  final String emptyBody;

  const _FoodHubLegacyPhotoSurface({
    required this.image,
    required this.enabled,
    required this.onCamera,
    required this.onGallery,
    required this.onRemove,
    required this.emptyTitle,
    required this.emptyBody,
  });

  @override
  Widget build(BuildContext context) {
    final current = image;
    final scheme = Theme.of(context).colorScheme;
    return Container(
      width: double.infinity,
      decoration: BoxDecoration(
        color: scheme.surfaceContainerHighest,
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: scheme.outlineVariant),
      ),
      clipBehavior: Clip.antiAlias,
      child: Column(
        children: [
          if (current == null)
            Padding(
              padding: const EdgeInsets.fromLTRB(22, 26, 22, 18),
              child: Column(
                children: [
                  Icon(
                    Icons.add_a_photo_outlined,
                    color: scheme.secondary,
                    size: 42,
                  ),
                  const SizedBox(height: 10),
                  Text(
                    emptyTitle,
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      color: scheme.onSurface,
                      fontSize: 17,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  const SizedBox(height: 5),
                  Text(
                    emptyBody,
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      color: scheme.onSurfaceVariant,
                      height: 1.35,
                    ),
                  ),
                ],
              ),
            )
          else
            Stack(
              children: [
                AspectRatio(
                  aspectRatio: 16 / 9,
                  child: Image.memory(
                    current.bytes,
                    cacheWidth: 1200,
                    fit: BoxFit.cover,
                    errorBuilder: (_, _, _) => const Center(
                      child: Icon(
                        Icons.broken_image_outlined,
                        color: _FoodHubLegacyFoodColors.danger,
                        size: 42,
                      ),
                    ),
                  ),
                ),
                Positioned(
                  top: 8,
                  right: 8,
                  child: Material(
                    color: scheme.surface.withValues(alpha: 0.88),
                    shape: const CircleBorder(),
                    child: IconButton(
                      onPressed: onRemove,
                      tooltip: 'Remove photo',
                      icon: const Icon(Icons.close_rounded),
                    ),
                  ),
                ),
                Positioned(
                  left: 10,
                  bottom: 10,
                  child: Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 10,
                      vertical: 6,
                    ),
                    decoration: BoxDecoration(
                      color: scheme.surface.withValues(alpha: 0.88),
                      borderRadius: BorderRadius.circular(99),
                    ),
                    child: Text(
                      '${current.name} • ${current.dimensions}',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        color: scheme.onSurface,
                        fontSize: 11,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                  ),
                ),
              ],
            ),
          Padding(
            padding: const EdgeInsets.all(12),
            child: Wrap(
              alignment: WrapAlignment.center,
              spacing: 10,
              runSpacing: 8,
              children: [
                FilledButton.icon(
                  onPressed: enabled ? onCamera : null,
                  icon: const Icon(Icons.photo_camera_rounded),
                  label: Text(current == null ? 'Take photo' : 'Retake'),
                ),
                OutlinedButton.icon(
                  onPressed: enabled ? onGallery : null,
                  icon: const Icon(Icons.photo_library_outlined),
                  label: const Text('Choose from gallery'),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _FoodHubLegacyFridgeLogTab extends StatelessWidget {
  final FoodVisionImage? image;
  final TextEditingController noteController;
  final FridgeLog? latestLog;
  final List<FridgeLog> recentLogs;
  final bool busy;
  final VoidCallback onCamera;
  final VoidCallback onGallery;
  final VoidCallback? onRemovePhoto;
  final VoidCallback? onAnalyze;
  final VoidCallback onOpenRecipes;

  const _FoodHubLegacyFridgeLogTab({
    required this.image,
    required this.noteController,
    required this.latestLog,
    required this.recentLogs,
    required this.busy,
    required this.onCamera,
    required this.onGallery,
    required this.onRemovePhoto,
    required this.onAnalyze,
    required this.onOpenRecipes,
  });

  @override
  Widget build(BuildContext context) {
    final analysis = latestLog?.analysis;
    return _FoodHubLegacyPageScroll(
      children: [
        const _FoodHubLegacyPageHeading(
          icon: Icons.kitchen_rounded,
          eyebrow: 'Daily food journal',
          title: 'Fridge Log',
          body:
              'Capture what is visible, review uncertainty, and save a private inventory snapshot in the encrypted vault.',
        ),
        _FoodHubLegacySurface(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              const _FoodHubLegacySectionHeading(
                icon: Icons.camera_alt_outlined,
                title: 'Today’s fridge photo',
                subtitle:
                    'Use a bright, steady image. Labels and hidden items may remain unknown.',
              ),
              _FoodHubLegacyPhotoSurface(
                image: image,
                enabled: !busy,
                onCamera: onCamera,
                onGallery: onGallery,
                onRemove: onRemovePhoto,
                emptyTitle: 'Photograph the open fridge',
                emptyBody:
                    'Keep the full shelves in frame. The model processes one normalized image locally.',
              ),
              const SizedBox(height: 12),
              TextField(
                controller: noteController,
                enabled: !busy,
                maxLength: 1200,
                maxLines: 3,
                decoration: const InputDecoration(
                  labelText: 'Optional note',
                  hintText:
                      'Grocery day, freezer not pictured, leftovers from Monday…',
                  prefixIcon: Icon(Icons.edit_note_rounded),
                ),
              ),
              const SizedBox(height: 4),
              FilledButton.icon(
                onPressed: onAnalyze,
                icon: Icon(
                  busy
                      ? Icons.hourglass_top_rounded
                      : Icons.auto_awesome_rounded,
                ),
                label: Text(
                  busy
                      ? 'Local analysis in progress…'
                      : 'Analyze & save encrypted log',
                ),
                style: FilledButton.styleFrom(
                  minimumSize: const Size.fromHeight(52),
                ),
              ),
            ],
          ),
        ),
        if (analysis == null)
          const _FoodHubLegacyEmptyAnalysisCard(
            icon: Icons.inventory_2_outlined,
            title: 'No structured fridge log yet',
            body:
                'Your most recent confirmed analysis will appear here with visible items, use-soon cues, ingredient ideas, and recipe starters.',
          )
        else ...[
          _FoodHubLegacyFridgeSummaryCard(log: latestLog!),
          _FoodHubLegacyInventoryItemsCard(items: analysis.items),
          _FoodHubLegacyUseSoonCard(items: analysis.useSoon),
          _FoodHubLegacyIngredientIdeasCard(
            items: analysis.ingredientSuggestions,
          ),
          _FoodHubLegacyRecipePreviewCard(
            recipes: analysis.recipes,
            onOpenRecipes: onOpenRecipes,
          ),
        ],
        if (recentLogs.isNotEmpty)
          _FoodHubLegacyRecentFridgeLogs(logs: recentLogs),
      ],
    );
  }
}

class _FoodHubLegacyFridgeSummaryCard extends StatelessWidget {
  final FridgeLog log;

  const _FoodHubLegacyFridgeSummaryCard({required this.log});

  @override
  Widget build(BuildContext context) {
    final analysis = log.analysis;
    final complete = analysis.status == FoodAnalysisStatus.complete;
    return _FoodHubLegacySurface(
      accent: complete
          ? _FoodHubLegacyFoodColors.mint
          : _FoodHubLegacyFoodColors.warning,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _FoodHubLegacySectionHeading(
            icon: complete
                ? Icons.check_circle_outline_rounded
                : Icons.rule_rounded,
            title: complete ? 'Latest structured inventory' : 'Review required',
            subtitle: _foodHubLegacyFormatDateTime(log.capturedAt),
            trailing: _FoodHubLegacyStatusChip(
              label: analysis.status.name,
              color: complete
                  ? _FoodHubLegacyFoodColors.mint
                  : _FoodHubLegacyFoodColors.warning,
            ),
          ),
          Text(
            analysis.summary,
            style: const TextStyle(
              color: _FoodHubLegacyFoodColors.text,
              height: 1.45,
              fontWeight: FontWeight.w600,
            ),
          ),
          if (analysis.uncertainties.isNotEmpty) ...[
            const SizedBox(height: 12),
            _FoodHubLegacyWarningBox(
              icon: Icons.visibility_off_outlined,
              title: 'Uncertainty to verify',
              lines: analysis.uncertainties,
            ),
          ],
          const SizedBox(height: 10),
          const Text(
            'A photo cannot prove freshness, expiration, allergen safety, or the condition of hidden food. Verify packaging, smell, temperature, and labels yourself.',
            style: TextStyle(
              color: _FoodHubLegacyFoodColors.subtext,
              fontSize: 12,
              height: 1.35,
            ),
          ),
        ],
      ),
    );
  }
}

class _FoodHubLegacyInventoryItemsCard extends StatelessWidget {
  final List<FridgeItemObservation> items;

  const _FoodHubLegacyInventoryItemsCard({required this.items});

  @override
  Widget build(BuildContext context) {
    return _FoodHubLegacySurface(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          _FoodHubLegacySectionHeading(
            icon: Icons.inventory_2_outlined,
            title: 'Visible items',
            subtitle:
                '${items.length} structured observation${items.length == 1 ? '' : 's'}',
          ),
          if (items.isEmpty)
            const _FoodHubLegacyInlineEmpty(
              'No item passed structured parsing.',
            )
          else
            LayoutBuilder(
              builder: (context, constraints) {
                final columns = constraints.maxWidth >= 820
                    ? 3
                    : constraints.maxWidth >= 540
                    ? 2
                    : 1;
                final width =
                    (constraints.maxWidth - (columns - 1) * 10) / columns;
                return Wrap(
                  spacing: 10,
                  runSpacing: 10,
                  children: [
                    for (final item in items)
                      SizedBox(
                        width: width,
                        child: _FoodHubLegacyInventoryItemTile(item: item),
                      ),
                  ],
                );
              },
            ),
        ],
      ),
    );
  }
}

class _FoodHubLegacyInventoryItemTile extends StatelessWidget {
  final FridgeItemObservation item;

  const _FoodHubLegacyInventoryItemTile({required this.item});

  @override
  Widget build(BuildContext context) {
    final confidenceColor = switch (item.confidence) {
      FoodConfidence.high => _FoodHubLegacyFoodColors.mint,
      FoodConfidence.medium => _FoodHubLegacyFoodColors.warning,
      FoodConfidence.low => _FoodHubLegacyFoodColors.danger,
    };
    return Container(
      padding: const EdgeInsets.all(13),
      decoration: BoxDecoration(
        color: _FoodHubLegacyFoodColors.field,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: confidenceColor.withAlpha(75)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                child: Text(
                  item.name,
                  style: const TextStyle(
                    color: _FoodHubLegacyFoodColors.text,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              _FoodHubLegacyStatusChip(
                label: '${item.confidence.label} confidence',
                color: confidenceColor,
                compact: true,
              ),
            ],
          ),
          const SizedBox(height: 8),
          _FoodHubLegacyMiniFact(
            icon: Icons.numbers_rounded,
            text: item.approximateQuantity,
          ),
          _FoodHubLegacyMiniFact(
            icon: Icons.place_outlined,
            text: item.location,
          ),
          _FoodHubLegacyMiniFact(
            icon: Icons.schedule_rounded,
            text: item.useWindow,
          ),
          if (item.visibleCues.isNotEmpty) ...[
            const SizedBox(height: 6),
            Text(
              item.visibleCues.join(' • '),
              style: const TextStyle(
                color: _FoodHubLegacyFoodColors.subtext,
                fontSize: 11,
                height: 1.35,
              ),
            ),
          ],
        ],
      ),
    );
  }
}

