class _FoodHubLegacyBakeLabTab extends StatelessWidget {
  final FoodVisionImage? image;
  final BakeLog? latestLog;
  final List<BakeLog> recentLogs;
  final bool busy;
  final BakeItemKind kind;
  final ValueChanged<BakeItemKind?>? onKindChanged;
  final TextEditingController nameController;
  final TextEditingController elapsedController;
  final TextEditingController plannedController;
  final TextEditingController ovenController;
  final TextEditingController probeController;
  final TextEditingController targetController;
  final TextEditingController notesController;
  final VoidCallback onCamera;
  final VoidCallback onGallery;
  final VoidCallback? onRemovePhoto;
  final VoidCallback? onAnalyze;

  const _FoodHubLegacyBakeLabTab({
    required this.image,
    required this.latestLog,
    required this.recentLogs,
    required this.busy,
    required this.kind,
    required this.onKindChanged,
    required this.nameController,
    required this.elapsedController,
    required this.plannedController,
    required this.ovenController,
    required this.probeController,
    required this.targetController,
    required this.notesController,
    required this.onCamera,
    required this.onGallery,
    required this.onRemovePhoto,
    required this.onAnalyze,
  });

  @override
  Widget build(BuildContext context) {
    return _FoodHubLegacyPageScroll(
      children: [
        const _FoodHubLegacyPageHeading(
          icon: Icons.bakery_dining_rounded,
          eyebrow: 'Vision + deterministic simulation',
          title: 'Bake Lab',
          body:
              'Estimate a process-completion interval from visible cues, elapsed time, and optional probe evidence. Never treat it as proof of food safety.',
        ),
        _FoodHubLegacySurface(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              const _FoodHubLegacySectionHeading(
                icon: Icons.tune_rounded,
                title: 'Bake evidence',
                subtitle:
                    'More measured evidence narrows the estimate. Temperatures use °F.',
              ),
              LayoutBuilder(
                builder: (context, constraints) {
                  final wide = constraints.maxWidth >= 680;
                  final fieldWidth = wide
                      ? (constraints.maxWidth - 12) / 2
                      : constraints.maxWidth;
                  return Wrap(
                    spacing: 12,
                    runSpacing: 12,
                    children: [
                      SizedBox(
                        width: fieldWidth,
                        child: DropdownButtonFormField<BakeItemKind>(
                          initialValue: kind,
                          onChanged: onKindChanged,
                          decoration: const InputDecoration(
                            labelText: 'Bake profile',
                            prefixIcon: Icon(Icons.category_outlined),
                          ),
                          items: [
                            for (final value in BakeItemKind.values)
                              DropdownMenuItem(
                                value: value,
                                child: Text(_foodHubLegacyKindLabel(value)),
                              ),
                          ],
                        ),
                      ),
                      SizedBox(
                        width: fieldWidth,
                        child: TextField(
                          controller: nameController,
                          enabled: !busy,
                          decoration: const InputDecoration(
                            labelText: 'Item name',
                            prefixIcon: Icon(Icons.label_outline_rounded),
                          ),
                        ),
                      ),
                      SizedBox(
                        width: fieldWidth,
                        child: _FoodHubLegacyNumberField(
                          controller: elapsedController,
                          enabled: !busy,
                          label: 'Elapsed minutes',
                          icon: Icons.timer_outlined,
                          required: true,
                        ),
                      ),
                      SizedBox(
                        width: fieldWidth,
                        child: _FoodHubLegacyNumberField(
                          controller: plannedController,
                          enabled: !busy,
                          label: 'Planned minutes',
                          icon: Icons.schedule_rounded,
                          required: true,
                        ),
                      ),
                      SizedBox(
                        width: fieldWidth,
                        child: _FoodHubLegacyNumberField(
                          controller: ovenController,
                          enabled: !busy,
                          label: 'Oven setting °F',
                          icon: Icons.local_fire_department_outlined,
                        ),
                      ),
                      SizedBox(
                        width: fieldWidth,
                        child: _FoodHubLegacyNumberField(
                          controller: probeController,
                          enabled: !busy,
                          label: 'Measured probe °F',
                          icon: Icons.thermostat_rounded,
                        ),
                      ),
                      SizedBox(
                        width: fieldWidth,
                        child: _FoodHubLegacyNumberField(
                          controller: targetController,
                          enabled: !busy,
                          label: 'Recipe target °F',
                          icon: Icons.flag_outlined,
                        ),
                      ),
                    ],
                  );
                },
              ),
              const SizedBox(height: 12),
              TextField(
                controller: notesController,
                enabled: !busy,
                maxLines: 3,
                maxLength: 1200,
                decoration: const InputDecoration(
                  labelText: 'Optional context',
                  hintText: 'Frozen pizza, dark pan, convection, top rack…',
                  prefixIcon: Icon(Icons.notes_rounded),
                ),
              ),
              const SizedBox(height: 6),
              _FoodHubLegacyPhotoSurface(
                image: image,
                enabled: !busy,
                onCamera: onCamera,
                onGallery: onGallery,
                onRemove: onRemovePhoto,
                emptyTitle: 'Photograph the baked item',
                emptyBody:
                    'Use neutral lighting and keep the visible surface and edges in frame. Avoid touching a hot oven or pan.',
              ),
              const SizedBox(height: 12),
              FilledButton.icon(
                onPressed: onAnalyze,
                icon: Icon(
                  busy ? Icons.hourglass_top_rounded : Icons.science_outlined,
                ),
                label: Text(
                  busy
                      ? 'Simulation in progress…'
                      : 'Analyze & simulate completion',
                ),
                style: FilledButton.styleFrom(
                  minimumSize: const Size.fromHeight(52),
                ),
              ),
            ],
          ),
        ),
        if (latestLog == null)
          const _FoodHubLegacyEmptyAnalysisCard(
            icon: Icons.query_stats_outlined,
            title: 'No bake simulation yet',
            body:
                'A completion interval and its independent timing, visual, and probe signals will appear here.',
          )
        else
          _FoodHubLegacyBakeResultCard(log: latestLog!),
        if (recentLogs.isNotEmpty)
          _FoodHubLegacyRecentBakeLogs(logs: recentLogs),
      ],
    );
  }
}

class _FoodHubLegacyNumberField extends StatelessWidget {
  final TextEditingController controller;
  final bool enabled;
  final String label;
  final IconData icon;
  final bool required;

  const _FoodHubLegacyNumberField({
    required this.controller,
    required this.enabled,
    required this.label,
    required this.icon,
    this.required = false,
  });

  @override
  Widget build(BuildContext context) {
    return TextField(
      controller: controller,
      enabled: enabled,
      keyboardType: const TextInputType.numberWithOptions(decimal: true),
      decoration: InputDecoration(
        labelText: required ? '$label *' : label,
        prefixIcon: Icon(icon),
      ),
    );
  }
}

class _FoodHubLegacyBakeResultCard extends StatelessWidget {
  final BakeLog log;

  const _FoodHubLegacyBakeResultCard({required this.log});

  @override
  Widget build(BuildContext context) {
    final result = log.simulation;
    final visual = log.visual;
    return _FoodHubLegacySurface(
      accent: _FoodHubLegacyFoodColors.warning,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          _FoodHubLegacySectionHeading(
            icon: Icons.query_stats_rounded,
            title: '${log.input.itemName} completion estimate',
            subtitle:
                '${_foodHubLegacyFormatDateTime(log.capturedAt)} • ${_foodHubLegacyPhaseLabel(result.phase)}',
            trailing: _FoodHubLegacyStatusChip(
              label: visual.confidence.label,
              color: switch (visual.confidence) {
                FoodConfidence.high => _FoodHubLegacyFoodColors.mint,
                FoodConfidence.medium => _FoodHubLegacyFoodColors.warning,
                FoodConfidence.low => _FoodHubLegacyFoodColors.danger,
              },
            ),
          ),
          _FoodHubLegacyCompletionBand(result: result),
          const SizedBox(height: 14),
          LayoutBuilder(
            builder: (context, constraints) {
              final width = constraints.maxWidth >= 680
                  ? (constraints.maxWidth - 20) / 3
                  : constraints.maxWidth;
              return Wrap(
                spacing: 10,
                runSpacing: 10,
                children: [
                  SizedBox(
                    width: width,
                    child: _FoodHubLegacySignalMetric(
                      label: 'Timing model',
                      value: result.timeSignal,
                      icon: Icons.timer_outlined,
                    ),
                  ),
                  SizedBox(
                    width: width,
                    child: _FoodHubLegacySignalMetric(
                      label: 'Visible surface',
                      value: result.visualSignal,
                      icon: Icons.visibility_outlined,
                    ),
                  ),
                  SizedBox(
                    width: width,
                    child: _FoodHubLegacySignalMetric(
                      label: 'Probe model',
                      value: result.thermalSignal,
                      icon: Icons.thermostat_rounded,
                    ),
                  ),
                ],
              );
            },
          ),
          const SizedBox(height: 14),
          _FoodHubLegacyWarningBox(
            icon: Icons.health_and_safety_outlined,
            title: 'Not a food-safety verdict',
            lines: [result.safetyMessage],
            danger: true,
          ),
          if (visual.observations.isNotEmpty) ...[
            const SizedBox(height: 14),
            _FoodHubLegacyBulletSection(
              icon: Icons.visibility_outlined,
              title: 'Visible observations',
              values: visual.observations,
              color: _FoodHubLegacyFoodColors.sky,
            ),
          ],
          if (visual.limitations.isNotEmpty) ...[
            const SizedBox(height: 12),
            _FoodHubLegacyBulletSection(
              icon: Icons.help_outline_rounded,
              title: 'Limitations',
              values: visual.limitations,
              color: _FoodHubLegacyFoodColors.warning,
            ),
          ],
          const SizedBox(height: 12),
          _FoodHubLegacyBulletSection(
            icon: Icons.functions_rounded,
            title: 'Simulation signals',
            values: result.signals,
            color: _FoodHubLegacyFoodColors.mint,
          ),
        ],
      ),
    );
  }
}

class _FoodHubLegacyCompletionBand extends StatelessWidget {
  final BakeSimulationResult result;

  const _FoodHubLegacyCompletionBand({required this.result});

  @override
  Widget build(BuildContext context) {
    return Semantics(
      label:
          'Estimated completion ${result.estimatedPercent.toStringAsFixed(0)} percent, interval ${result.lowerBound.toStringAsFixed(0)} to ${result.upperBound.toStringAsFixed(0)} percent',
      child: Container(
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: _FoodHubLegacyFoodColors.field,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
            color: _FoodHubLegacyFoodColors.warning.withAlpha(80),
          ),
        ),
        child: Column(
          children: [
            Row(
              crossAxisAlignment: CrossAxisAlignment.end,
              children: [
                Text(
                  '${result.estimatedPercent.toStringAsFixed(0)}%',
                  style: const TextStyle(
                    color: _FoodHubLegacyFoodColors.text,
                    fontSize: 36,
                    fontWeight: FontWeight.w900,
                    height: 1,
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Padding(
                    padding: const EdgeInsets.only(bottom: 3),
                    child: Text(
                      'estimated process completion\n${result.lowerBound.toStringAsFixed(0)}–${result.upperBound.toStringAsFixed(0)}% uncertainty band',
                      style: const TextStyle(
                        color: _FoodHubLegacyFoodColors.subtext,
                        height: 1.25,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 14),
            LayoutBuilder(
              builder: (context, constraints) {
                final width = constraints.maxWidth;
                final lower = width * result.lowerBound / 100;
                final upper = width * result.upperBound / 100;
                final estimate = width * result.estimatedPercent / 100;
                return SizedBox(
                  height: 22,
                  child: Stack(
                    clipBehavior: Clip.none,
                    children: [
                      Positioned.fill(
                        top: 7,
                        bottom: 7,
                        child: DecoratedBox(
                          decoration: BoxDecoration(
                            color: _FoodHubLegacyFoodColors.muted.withAlpha(35),
                            borderRadius: BorderRadius.circular(99),
                          ),
                        ),
                      ),
                      Positioned(
                        left: lower,
                        top: 5,
                        width: (upper - lower).clamp(3, width),
                        height: 12,
                        child: DecoratedBox(
                          decoration: BoxDecoration(
                            color: _FoodHubLegacyFoodColors.warning.withAlpha(
                              130,
                            ),
                            borderRadius: BorderRadius.circular(99),
                          ),
                        ),
                      ),
                      Positioned(
                        left: (estimate - 2).clamp(0, width - 4),
                        top: 1,
                        width: 4,
                        height: 20,
                        child: DecoratedBox(
                          decoration: BoxDecoration(
                            color: _FoodHubLegacyFoodColors.text,
                            borderRadius: BorderRadius.circular(99),
                          ),
                        ),
                      ),
                    ],
                  ),
                );
              },
            ),
            const Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(
                  '0%',
                  style: TextStyle(color: _FoodHubLegacyFoodColors.muted),
                ),
                Text(
                  '100%',
                  style: TextStyle(color: _FoodHubLegacyFoodColors.muted),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

