class _FoodHubLegacyWarningBox extends StatelessWidget {
  final IconData icon;
  final String title;
  final List<String> lines;
  final bool danger;

  const _FoodHubLegacyWarningBox({
    required this.icon,
    required this.title,
    required this.lines,
    this.danger = false,
  });

  @override
  Widget build(BuildContext context) {
    final color = danger
        ? _FoodHubLegacyFoodColors.danger
        : _FoodHubLegacyFoodColors.warning;
    return Container(
      padding: const EdgeInsets.all(13),
      decoration: BoxDecoration(
        color: color.withAlpha(17),
        borderRadius: BorderRadius.circular(17),
        border: Border.all(color: color.withAlpha(85)),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
