enum FoodConfidence {
  low,
  medium,
  high;

  String get label => switch (this) {
    FoodConfidence.low => 'Low',
    FoodConfidence.medium => 'Medium',
    FoodConfidence.high => 'High',
  };

  static FoodConfidence parse(Object? value) {
    return switch (value?.toString().trim().toLowerCase()) {
      'high' => FoodConfidence.high,
      'medium' => FoodConfidence.medium,
      _ => FoodConfidence.low,
    };
  }
}

enum FoodAnalysisStatus { complete, partial, failed, cancelled }

final class FoodVisionImage {
  final Uint8List bytes;
  final String name;
  final int width;
  final int height;

  const FoodVisionImage({
    required this.bytes,
    required this.name,
    required this.width,
    required this.height,
  });

  String get dimensions => '$width × $height';

  Map<String, Object?> toJson() => <String, Object?>{
    'bytes': base64Encode(bytes),
    'name': name,
    'width': width,
    'height': height,
  };

  factory FoodVisionImage.fromJson(Map<String, Object?> json) {
    final encoded = json['bytes']?.toString() ?? '';
    // Reject before base64Decode allocates the decoded buffer. Base64 expands
    // data by roughly 4/3, so this bound also prevents oversized persisted
    // records from becoming a transient memory-allocation primitive.
    final maxEncoded = ((8 * 1024 * 1024 + 2) ~/ 3) * 4 + 4;
    if (encoded.isEmpty || encoded.length > maxEncoded) {
      throw const FormatException(
        'Food image encoding exceeds the safe limit.',
      );
    }
    final bytes = base64Decode(encoded);
    if (bytes.isEmpty || bytes.length > 8 * 1024 * 1024) {
      throw const FormatException('Food image exceeds the safe limit.');
    }
    return FoodVisionImage(
      bytes: bytes,
      name: _modelsBounded(json['name'], 180, fallback: 'food-image.png'),
      width: _modelsInt(json['width']).clamp(1, 10000),
      height: _modelsInt(json['height']).clamp(1, 10000),
    );
  }
}

