    'id': id,
    'captured_at': capturedAt.toUtc().toIso8601String(),
    'image': image.toJson(),
    'input': input.toJson(),
    'visual': visual.toJson(),
    'simulation': simulation.toJson(),
  };

  factory BakeLog.fromJson(Map<String, Object?> json) => BakeLog(
    id: _modelsBounded(json['id'], 100, fallback: newFoodId('bake')),
    capturedAt:
        DateTime.tryParse(json['captured_at']?.toString() ?? '') ??
        DateTime.now().toUtc(),
    image: FoodVisionImage.fromJson(_modelsMap(json['image'])),
    input: BakeInput.fromJson(_modelsMap(json['input'])),
    visual: BakeVisualAssessment.fromJson(_modelsMap(json['visual'])),
    simulation: BakeSimulationResult.fromJson(_modelsMap(json['simulation'])),
  );
}

String newFoodId(String prefix) {
  final random = math.Random.secure();
  final bytes = List<int>.generate(12, (_) => random.nextInt(256));
  return '$prefix-${base64UrlEncode(bytes).replaceAll('=', '')}';
}

Map<String, Object?> decodeModelJson(String raw) {
  var clean = raw.trim();
  clean = clean.replaceFirst(
    RegExp(r'^```(?:json)?\s*', caseSensitive: false),
    '',
  );
  clean = clean.replaceFirst(RegExp(r'\s*```$'), '');
  final start = clean.indexOf('{');
  final end = clean.lastIndexOf('}');
  if (start < 0 || end <= start) {
    throw const FormatException('No JSON object was returned.');
  }
  final decoded = jsonDecode(clean.substring(start, end + 1));
  if (decoded is! Map) {
    throw const FormatException('The response is not an object.');
  }
  return <String, Object?>{
    for (final entry in decoded.entries) entry.key.toString(): entry.value,
  };
}

Map<String, Object?> _modelsMap(Object? value) {
  if (value is! Map) return <String, Object?>{};
  return <String, Object?>{
    for (final entry in value.entries) entry.key.toString(): entry.value,
  };
}

List<Map<String, Object?>> _modelsMapList(Object? value) {
  if (value is! List) return const [];
  return value.whereType<Map>().map(_modelsMap).toList(growable: false);
}

List<String> _modelsStringList(
  Object? value, {
  required int maxItems,
  required int maxChars,
}) {
  if (value is! List) return const [];
  return value
      .map((item) => _modelsBounded(item, maxChars))
      .where((item) => item.isNotEmpty)
      .take(maxItems)
      .toList(growable: false);
}

String _modelsBounded(Object? value, int maxChars, {String fallback = ''}) {
  final clean = value?.toString().replaceAll(RegExp(r'\s+'), ' ').trim() ?? '';
  if (clean.isEmpty) return fallback;
  final runes = clean.runes.toList(growable: false);
  if (runes.length <= maxChars) return clean;
  return '${String.fromCharCodes(runes.take(maxChars)).trimRight()}…';
}

int _modelsInt(Object? value) => int.tryParse(value?.toString() ?? '') ?? 0;

double _modelsDouble(Object? value) =>
    double.tryParse(value?.toString() ?? '') ?? 0;

double? _modelsNullableDouble(Object? value) {
  if (value == null || value.toString().trim().isEmpty) return null;
  return double.tryParse(value.toString());
}

double _modelsPercent(Object? value) =>
    _modelsDouble(value).clamp(0, 100).toDouble();

T? _modelsEnumByName<T extends Enum>(Iterable<T> values, Object? value) {
  final name = value?.toString().trim();
  for (final candidate in values) {
    if (candidate.name == name) return candidate;
  }
  return null;
}

