const String _repositoryFoodEntryKeyPrefix = 'entry:';

/// Durable storage boundary for the food surfaces.
///
/// Implementations keep newest captures first and apply [limit] after
/// [offset]. A null limit returns every retained entry after the offset.
abstract interface class FoodRepository {
  ValueNotifier<int> get revision;

  Future<void> saveFridgeLog(FridgeLog log);

  Future<List<FridgeLog>> listFridgeLogs({int? limit, int offset = 0});

  Future<FridgeLog?> getFridgeLog(String id);

  Future<void> deleteFridgeLog(String id);

  Future<void> clearFridgeLogs();

  Future<void> saveBakeLog(BakeLog log);

  Future<List<BakeLog>> listBakeLogs({int? limit, int offset = 0});

  Future<BakeLog?> getBakeLog(String id);

  Future<void> deleteBakeLog(String id);

  Future<void> clearBakeLogs();

  Future<void> clearAll();
}

/// Stores food captures as independently authenticated records in the
/// encrypted SQLite vault. The encrypted index contains only bounded IDs and
/// capture times, allowing history pages to load without decrypting every
/// retained image first.
final class EncryptedFoodRepository implements FoodRepository {
  EncryptedFoodRepository({
    NazaSecureDatabase? database,
    this.fridgeLimit = FoodVisionConfig.fridgeLogLimit,
    this.bakeLimit = FoodVisionConfig.bakeLogLimit,
  }) : _repositoryDatabase = database ?? NazaSecureDatabase.instance {
    _repositoryValidateRetentionLimit(fridgeLimit, 'fridgeLimit');
    _repositoryValidateRetentionLimit(bakeLimit, 'bakeLimit');
  }

  static const String _repositoryFridgeKind = 'fridge';
  static const String _repositoryBakeKind = 'bake';

  final NazaSecureDatabase _repositoryDatabase;
  final int fridgeLimit;
  final int bakeLimit;
  Future<void> _repositoryTail = Future<void>.value();

  @override
  final ValueNotifier<int> revision = ValueNotifier<int>(0);

  @override
  Future<void> saveFridgeLog(FridgeLog log) {
    _repositoryValidateFridgeLog(log);
    return _repositoryEnqueue(() async {
      final index = await _repositoryReadIndex(
        namespace: FoodVisionConfig.fridgeNamespace,
        indexKey: FoodVisionConfig.fridgeIndexKey,
        kind: _repositoryFridgeKind,
      );
      final mutation = index.withEntry(
        id: log.id,
        capturedAt: log.capturedAt,
        maximumEntries: fridgeLimit,
      );
      await _repositoryDatabase.importRecords(<NazaVaultRecordKey, Object?>{
        NazaVaultRecordKey(
          FoodVisionConfig.fridgeNamespace,
          _repositoryEntryKey(log.id),
        ): log
            .toJson(),
        const NazaVaultRecordKey(
          FoodVisionConfig.fridgeNamespace,
          FoodVisionConfig.fridgeIndexKey,
        ): mutation.index
            .toJson(),
      });
      revision.value++;
      await _repositoryDeletePruned(
        namespace: FoodVisionConfig.fridgeNamespace,
        ids: mutation.prunedIds,
      );
    });
  }

  @override
  Future<List<FridgeLog>> listFridgeLogs({int? limit, int offset = 0}) {
    _repositoryValidatePage(limit: limit, offset: offset);
    return _repositoryEnqueue(() async {
      final index = await _repositoryReadIndex(
        namespace: FoodVisionConfig.fridgeNamespace,
        indexKey: FoodVisionConfig.fridgeIndexKey,
        kind: _repositoryFridgeKind,
      );
      final result = <FridgeLog>[];
      for (final entry in index.entries.skip(offset)) {
        if (limit != null && result.length >= limit) break;
        final log = await _repositoryReadFridgeLog(entry.id);
        if (log != null) result.add(log);
      }
      return List<FridgeLog>.unmodifiable(result);
    });
  }

  @override
  Future<FridgeLog?> getFridgeLog(String id) {
    final validId = _repositoryValidateId(id);
    return _repositoryEnqueue(() => _repositoryReadFridgeLog(validId));
  }

  @override
  Future<void> deleteFridgeLog(String id) {
    final validId = _repositoryValidateId(id);
    return _repositoryEnqueue(() async {
      await _repositoryDatabase.delete(
        FoodVisionConfig.fridgeNamespace,
        _repositoryEntryKey(validId),
      );
      final index = await _repositoryReadIndex(
        namespace: FoodVisionConfig.fridgeNamespace,
        indexKey: FoodVisionConfig.fridgeIndexKey,
        kind: _repositoryFridgeKind,
      );
      await _repositoryWriteIndex(
        namespace: FoodVisionConfig.fridgeNamespace,
        indexKey: FoodVisionConfig.fridgeIndexKey,
        index: index.without(validId),
      );
      revision.value++;
    });
  }

  @override
  Future<void> clearFridgeLogs() {
    return _repositoryEnqueue(() async {
      await _repositoryClearNamespace(
        namespace: FoodVisionConfig.fridgeNamespace,
        indexKey: FoodVisionConfig.fridgeIndexKey,
        kind: _repositoryFridgeKind,
      );
      revision.value++;
    });
  }

  @override
  Future<void> saveBakeLog(BakeLog log) {
    _repositoryValidateBakeLog(log);
    return _repositoryEnqueue(() async {
      final index = await _repositoryReadIndex(
        namespace: FoodVisionConfig.bakeNamespace,
        indexKey: FoodVisionConfig.bakeIndexKey,
        kind: _repositoryBakeKind,
      );
      final mutation = index.withEntry(
        id: log.id,
        capturedAt: log.capturedAt,
        maximumEntries: bakeLimit,
      );
      await _repositoryDatabase.importRecords(<NazaVaultRecordKey, Object?>{
        NazaVaultRecordKey(
          FoodVisionConfig.bakeNamespace,
          _repositoryEntryKey(log.id),
        ): log
            .toJson(),
        const NazaVaultRecordKey(
          FoodVisionConfig.bakeNamespace,
          FoodVisionConfig.bakeIndexKey,
        ): mutation.index
            .toJson(),
      });
      revision.value++;
      await _repositoryDeletePruned(
        namespace: FoodVisionConfig.bakeNamespace,
        ids: mutation.prunedIds,
      );
    });
  }

  @override
  Future<List<BakeLog>> listBakeLogs({int? limit, int offset = 0}) {
    _repositoryValidatePage(limit: limit, offset: offset);
    return _repositoryEnqueue(() async {
      final index = await _repositoryReadIndex(
        namespace: FoodVisionConfig.bakeNamespace,
        indexKey: FoodVisionConfig.bakeIndexKey,
        kind: _repositoryBakeKind,
      );
      final result = <BakeLog>[];
      for (final entry in index.entries.skip(offset)) {
        if (limit != null && result.length >= limit) break;
        final log = await _repositoryReadBakeLog(entry.id);
        if (log != null) result.add(log);
      }
      return List<BakeLog>.unmodifiable(result);
    });
  }

  @override
  Future<BakeLog?> getBakeLog(String id) {
    final validId = _repositoryValidateId(id);
    return _repositoryEnqueue(() => _repositoryReadBakeLog(validId));
  }

  @override
  Future<void> deleteBakeLog(String id) {
    final validId = _repositoryValidateId(id);
    return _repositoryEnqueue(() async {
      await _repositoryDatabase.delete(
        FoodVisionConfig.bakeNamespace,
        _repositoryEntryKey(validId),
      );
      final index = await _repositoryReadIndex(
        namespace: FoodVisionConfig.bakeNamespace,
        indexKey: FoodVisionConfig.bakeIndexKey,
        kind: _repositoryBakeKind,
      );
      await _repositoryWriteIndex(
        namespace: FoodVisionConfig.bakeNamespace,
        indexKey: FoodVisionConfig.bakeIndexKey,
        index: index.without(validId),
      );
      revision.value++;
    });
  }

  @override
  Future<void> clearBakeLogs() {
    return _repositoryEnqueue(() async {
      await _repositoryClearNamespace(
        namespace: FoodVisionConfig.bakeNamespace,
        indexKey: FoodVisionConfig.bakeIndexKey,
        kind: _repositoryBakeKind,
      );
      revision.value++;
    });
  }

  @override
  Future<void> clearAll() {
    return _repositoryEnqueue(() async {
      await _repositoryClearNamespace(
        namespace: FoodVisionConfig.fridgeNamespace,
        indexKey: FoodVisionConfig.fridgeIndexKey,
        kind: _repositoryFridgeKind,
      );
      await _repositoryClearNamespace(
        namespace: FoodVisionConfig.bakeNamespace,
        indexKey: FoodVisionConfig.bakeIndexKey,
        kind: _repositoryBakeKind,
      );
      revision.value++;
    });
  }

  Future<FridgeLog?> _repositoryReadFridgeLog(String id) async {
    final raw = await _repositoryDatabase.readJson(
      FoodVisionConfig.fridgeNamespace,
      _repositoryEntryKey(id),
    );
    if (raw == null) return null;
    final json = _repositoryRecordMap(
      raw,
      expectedFormat: 'naza-fridge-log-v1',
      expectedId: id,
      label: 'fridge log',
    );
    try {
      return FridgeLog.fromJson(json);
    } catch (error) {
      throw NazaVaultException(
        'invalid_food_fridge_log',
        'An encrypted fridge log is malformed.',
        error,
      );
    }
  }

  Future<BakeLog?> _repositoryReadBakeLog(String id) async {
    final raw = await _repositoryDatabase.readJson(
      FoodVisionConfig.bakeNamespace,
      _repositoryEntryKey(id),
    );
    if (raw == null) return null;
    final json = _repositoryRecordMap(
      raw,
      expectedFormat: 'naza-bake-log-v1',
      expectedId: id,
      label: 'bake log',
    );
    try {
      return BakeLog.fromJson(json);
    } catch (error) {
      throw NazaVaultException(
        'invalid_food_bake_log',
        'An encrypted bake log is malformed.',
        error,
      );
    }
  }

  Future<_RepositoryFoodIndex> _repositoryReadIndex({
    required String namespace,
    required String indexKey,
    required String kind,
  }) async {
    final raw = await _repositoryDatabase.readJson(namespace, indexKey);
    if (raw == null) return _RepositoryFoodIndex.empty(kind);
    try {
      return _RepositoryFoodIndex.fromJson(raw, expectedKind: kind);
    } catch (error) {
      throw NazaVaultException(
        'invalid_food_index',
        'The encrypted $kind history index is malformed.',
        error,
      );
    }
  }

  Future<void> _repositoryWriteIndex({
    required String namespace,
    required String indexKey,
    required _RepositoryFoodIndex index,
  }) {
    return _repositoryDatabase.writeJson(namespace, indexKey, index.toJson());
  }

  Future<void> _repositoryClearNamespace({
    required String namespace,
    required String indexKey,
    required String kind,
  }) async {
    final index = await _repositoryReadIndex(
      namespace: namespace,
      indexKey: indexKey,
      kind: kind,
    );
    for (final entry in index.entries) {
      await _repositoryDatabase.delete(
        namespace,
        _repositoryEntryKey(entry.id),
      );
    }
    await _repositoryDatabase.delete(namespace, indexKey);
  }

  Future<void> _repositoryDeletePruned({
    required String namespace,
    required Iterable<String> ids,
  }) async {
    for (final id in ids) {
      await _repositoryDatabase.delete(namespace, _repositoryEntryKey(id));
    }
  }

  Future<T> _repositoryEnqueue<T>(Future<T> Function() operation) {
    final queued = _repositoryTail.then((_) => operation());
    _repositoryTail = queued.then<void>(
      (_) {},
      onError: (Object _, StackTrace _) {},
    );
    return queued;
  }
}

/// Deterministic repository used by widget tests and previews. It mirrors the
/// encrypted implementation's ordering, page semantics, and retention caps.
final class MemoryFoodRepository implements FoodRepository {
  MemoryFoodRepository({
    Iterable<FridgeLog> fridgeLogs = const <FridgeLog>[],
    Iterable<BakeLog> bakeLogs = const <BakeLog>[],
    this.fridgeLimit = FoodVisionConfig.fridgeLogLimit,
    this.bakeLimit = FoodVisionConfig.bakeLogLimit,
  }) {
    _repositoryValidateRetentionLimit(fridgeLimit, 'fridgeLimit');
    _repositoryValidateRetentionLimit(bakeLimit, 'bakeLimit');
    for (final log in fridgeLogs) {
      _repositoryValidateFridgeLog(log);
      _repositoryFridgeLogs[log.id] = log;
    }
    for (final log in bakeLogs) {
      _repositoryValidateBakeLog(log);
      _repositoryBakeLogs[log.id] = log;
    }
    _repositoryPruneFridge();
    _repositoryPruneBake();
  }

  final int fridgeLimit;
  final int bakeLimit;
  final Map<String, FridgeLog> _repositoryFridgeLogs = <String, FridgeLog>{};
  final Map<String, BakeLog> _repositoryBakeLogs = <String, BakeLog>{};
  Future<void> _repositoryTail = Future<void>.value();

  @override
  final ValueNotifier<int> revision = ValueNotifier<int>(0);

  @override
  Future<void> saveFridgeLog(FridgeLog log) {
    _repositoryValidateFridgeLog(log);
    return _repositoryEnqueue(() async {
      _repositoryFridgeLogs[log.id] = log;
      _repositoryPruneFridge();
      revision.value++;
    });
  }

  @override
  Future<List<FridgeLog>> listFridgeLogs({int? limit, int offset = 0}) {
    _repositoryValidatePage(limit: limit, offset: offset);
    return _repositoryEnqueue(() async {
      final ordered = _repositoryOrderedFridge().skip(offset);
      final selected = limit == null ? ordered : ordered.take(limit);
      return List<FridgeLog>.unmodifiable(selected);
    });
  }

  @override
  Future<FridgeLog?> getFridgeLog(String id) {
    final validId = _repositoryValidateId(id);
    return _repositoryEnqueue(() async => _repositoryFridgeLogs[validId]);
  }

  @override
  Future<void> deleteFridgeLog(String id) {
    final validId = _repositoryValidateId(id);
    return _repositoryEnqueue(() async {
      _repositoryFridgeLogs.remove(validId);
      revision.value++;
    });
  }

  @override
  Future<void> clearFridgeLogs() {
    return _repositoryEnqueue(() async {
      _repositoryFridgeLogs.clear();
      revision.value++;
    });
  }

  @override
  Future<void> saveBakeLog(BakeLog log) {
    _repositoryValidateBakeLog(log);
    return _repositoryEnqueue(() async {
      _repositoryBakeLogs[log.id] = log;
      _repositoryPruneBake();
      revision.value++;
    });
  }

  @override
  Future<List<BakeLog>> listBakeLogs({int? limit, int offset = 0}) {
    _repositoryValidatePage(limit: limit, offset: offset);
    return _repositoryEnqueue(() async {
      final ordered = _repositoryOrderedBake().skip(offset);
      final selected = limit == null ? ordered : ordered.take(limit);
      return List<BakeLog>.unmodifiable(selected);
    });
  }

  @override
  Future<BakeLog?> getBakeLog(String id) {
    final validId = _repositoryValidateId(id);
    return _repositoryEnqueue(() async => _repositoryBakeLogs[validId]);
  }

  @override
  Future<void> deleteBakeLog(String id) {
    final validId = _repositoryValidateId(id);
    return _repositoryEnqueue(() async {
      _repositoryBakeLogs.remove(validId);
      revision.value++;
    });
  }

  @override
  Future<void> clearBakeLogs() {
    return _repositoryEnqueue(() async {
      _repositoryBakeLogs.clear();
      revision.value++;
    });
  }

  @override
  Future<void> clearAll() {
    return _repositoryEnqueue(() async {
      _repositoryFridgeLogs.clear();
      _repositoryBakeLogs.clear();
      revision.value++;
    });
  }

  List<FridgeLog> _repositoryOrderedFridge() {
    return _repositoryFridgeLogs.values.toList(growable: false)..sort(
      (a, b) =>
          _repositoryCompareCapture(a.capturedAt, a.id, b.capturedAt, b.id),
    );
  }

  List<BakeLog> _repositoryOrderedBake() {
    return _repositoryBakeLogs.values.toList(growable: false)..sort(
      (a, b) =>
          _repositoryCompareCapture(a.capturedAt, a.id, b.capturedAt, b.id),
    );
  }

  void _repositoryPruneFridge() {
    final ordered = _repositoryOrderedFridge();
    for (final log in ordered.skip(fridgeLimit)) {
      _repositoryFridgeLogs.remove(log.id);
    }
  }

  void _repositoryPruneBake() {
    final ordered = _repositoryOrderedBake();
    for (final log in ordered.skip(bakeLimit)) {
      _repositoryBakeLogs.remove(log.id);
    }
  }

  Future<T> _repositoryEnqueue<T>(Future<T> Function() operation) {
    final queued = _repositoryTail.then((_) => operation());
    _repositoryTail = queued.then<void>(
      (_) {},
      onError: (Object _, StackTrace _) {},
    );
    return queued;
  }
}

final class _RepositoryFoodIndexEntry {
  final String id;
  final DateTime capturedAt;

  const _RepositoryFoodIndexEntry({required this.id, required this.capturedAt});

  Map<String, Object?> toJson() => <String, Object?>{
    'id': id,
    'captured_at': capturedAt.toUtc().toIso8601String(),
  };

  factory _RepositoryFoodIndexEntry.fromJson(Map<Object?, Object?> json) {
    final id = _repositoryValidateId(json['id']?.toString() ?? '');
    final capturedAt = DateTime.tryParse(json['captured_at']?.toString() ?? '');
    if (capturedAt == null) {
      throw const FormatException('A food index timestamp is invalid.');
    }
    return _RepositoryFoodIndexEntry(id: id, capturedAt: capturedAt);
  }
}

final class _RepositoryFoodIndex {
  final String kind;
  final List<_RepositoryFoodIndexEntry> entries;

  const _RepositoryFoodIndex({required this.kind, required this.entries});

  factory _RepositoryFoodIndex.empty(String kind) {
    return _RepositoryFoodIndex(
      kind: kind,
      entries: const <_RepositoryFoodIndexEntry>[],
    );
  }

  factory _RepositoryFoodIndex.fromJson(
    Object? raw, {
    required String expectedKind,
  }) {
    if (raw is! Map) {
      throw const FormatException('A food index must be a JSON object.');
    }
    if (raw['format'] != 'naza-food-log-index-v1' ||
        raw['kind'] != expectedKind ||
        raw['entries'] is! List) {
      throw const FormatException('A food index has an unsupported format.');
    }
    final byId = <String, _RepositoryFoodIndexEntry>{};
    for (final item in raw['entries'] as List) {
      if (item is! Map) {
        throw const FormatException('A food index entry is malformed.');
      }
      final entry = _RepositoryFoodIndexEntry.fromJson(item);
      final existing = byId[entry.id];
      if (existing == null || entry.capturedAt.isAfter(existing.capturedAt)) {
        byId[entry.id] = entry;
      }
    }
    final entries = byId.values.toList(growable: false)
      ..sort(_repositoryCompareEntries);
    return _RepositoryFoodIndex(
      kind: expectedKind,
      entries: List<_RepositoryFoodIndexEntry>.unmodifiable(entries),
    );
  }

  _RepositoryFoodIndexMutation withEntry({
    required String id,
    required DateTime capturedAt,
    required int maximumEntries,
  }) {
    final byId = <String, _RepositoryFoodIndexEntry>{
      for (final entry in entries)
        if (entry.id != id) entry.id: entry,
      id: _RepositoryFoodIndexEntry(id: id, capturedAt: capturedAt),
    };
    final sorted = byId.values.toList(growable: false)
      ..sort(_repositoryCompareEntries);
    final kept = sorted.take(maximumEntries).toList(growable: false);
    final pruned = sorted
        .skip(maximumEntries)
        .map((entry) => entry.id)
        .toList(growable: false);
    return _RepositoryFoodIndexMutation(
      index: _RepositoryFoodIndex(
        kind: kind,
        entries: List<_RepositoryFoodIndexEntry>.unmodifiable(kept),
      ),
      prunedIds: pruned,
    );
  }

  _RepositoryFoodIndex without(String id) {
    return _RepositoryFoodIndex(
      kind: kind,
      entries: List<_RepositoryFoodIndexEntry>.unmodifiable(
        entries.where((entry) => entry.id != id),
      ),
    );
  }

  Map<String, Object?> toJson() => <String, Object?>{
    'format': 'naza-food-log-index-v1',
    'kind': kind,
    'updated_at': DateTime.now().toUtc().toIso8601String(),
    'entries': entries.map((entry) => entry.toJson()).toList(growable: false),
  };
}

final class _RepositoryFoodIndexMutation {
  final _RepositoryFoodIndex index;
  final List<String> prunedIds;

  const _RepositoryFoodIndexMutation({
    required this.index,
    required this.prunedIds,
  });
}

Map<String, Object?> _repositoryRecordMap(
  Object? raw, {
  required String expectedFormat,
  required String expectedId,
  required String label,
}) {
  if (raw is! Map ||
      raw['format'] != expectedFormat ||
      raw['id']?.toString() != expectedId) {
    throw NazaVaultException(
      'invalid_food_record',
      'The encrypted $label has an invalid identity or format.',
    );
  }
  return <String, Object?>{
    for (final entry in raw.entries) entry.key.toString(): entry.value,
  };
}

String _repositoryEntryKey(String id) =>
    '$_repositoryFoodEntryKeyPrefix${_repositoryValidateId(id)}';

String _repositoryValidateId(String id) {
  if (id.isEmpty ||
      id != id.trim() ||
      id.length > 180 ||
      id.contains('\u0000') ||
      id.contains('\u001f')) {
    throw ArgumentError.value(id, 'id', 'Invalid food log ID.');
  }
  return id;
}

void _repositoryValidateRetentionLimit(int value, String name) {
  if (value < 1 || value > 10000) {
    throw ArgumentError.value(value, name, 'Use a limit from 1 to 10000.');
  }
}

void _repositoryValidatePage({required int? limit, required int offset}) {
  if (offset < 0) {
    throw ArgumentError.value(offset, 'offset', 'Offset cannot be negative.');
  }
  if (limit != null && limit < 0) {
    throw ArgumentError.value(limit, 'limit', 'Limit cannot be negative.');
  }
}

void _repositoryValidateImage(FoodVisionImage image) {
  if (image.bytes.isEmpty ||
      image.bytes.length > FoodVisionConfig.visionMaxImageBytes) {
    throw ArgumentError.value(
      image.bytes.length,
      'image.bytes',
      'A normalized food image must contain 1-${FoodVisionConfig.visionMaxImageBytes} bytes.',
    );
  }
  if (image.width < 1 ||
      image.height < 1 ||
      image.width > FoodVisionConfig.visionMaxImageDimension ||
      image.height > FoodVisionConfig.visionMaxImageDimension) {
    throw ArgumentError(
      'A normalized food image must fit within '
      '${FoodVisionConfig.visionMaxImageDimension} × '
      '${FoodVisionConfig.visionMaxImageDimension} pixels.',
    );
  }
}

void _repositoryValidateFridgeLog(FridgeLog log) {
  _repositoryValidateId(log.id);
  _repositoryValidateImage(log.image);
}

void _repositoryValidateBakeLog(BakeLog log) {
  _repositoryValidateId(log.id);
  _repositoryValidateImage(log.image);
}

int _repositoryCompareEntries(
  _RepositoryFoodIndexEntry a,
  _RepositoryFoodIndexEntry b,
) {
  return _repositoryCompareCapture(a.capturedAt, a.id, b.capturedAt, b.id);
}

int _repositoryCompareCapture(
  DateTime aTime,
  String aId,
  DateTime bTime,
  String bId,
) {
  final byTime = bTime.compareTo(aTime);
  return byTime != 0 ? byTime : bId.compareTo(aId);
}

