typedef ShelfVisionAnalyzer =
    Future<FridgeAnalysis> Function(FoodVisionImage image, String note);

enum ShelfRiskLevel {
  low,
  medium,
  high,
  reviewRequired;

  String get label => switch (this) {
    low => 'Low',
    medium => 'Medium',
    high => 'High',
    reviewRequired => 'Review required',
  };

  int get severity => switch (this) {
    low => 0,
    medium => 1,
    high => 2,
    reviewRequired => 3,
  };

  static ShelfRiskLevel parse(Object? value) =>
      switch (value?.toString().trim().toLowerCase()) {
        'low' => low,
        'high' => high,
        'medium' => medium,
        _ => reviewRequired,
      };
}

enum _ShelfScannerShelfPhotoSource { camera, gallery, files }

final class ShelfItem {
  final String id;
  final String name;
  final String approximateQuantity;
  final List<String> visibleCues;
  final FoodConfidence confidence;
  final bool interested;
  final ShelfRiskLevel? risk;
  final String riskReason;
  final List<String> uncertainties;

  const ShelfItem({
    required this.id,
    required this.name,
    required this.approximateQuantity,
    required this.visibleCues,
    required this.confidence,
    this.interested = false,
    this.risk,
    this.riskReason = '',
    this.uncertainties = const <String>[],
  });

  ShelfItem copyWith({
    bool? interested,
    ShelfRiskLevel? risk,
    bool clearRisk = false,
    String? riskReason,
    List<String>? uncertainties,
  }) => ShelfItem(
    id: id,
    name: name,
    approximateQuantity: approximateQuantity,
    visibleCues: visibleCues,
    confidence: confidence,
    interested: interested ?? this.interested,
    risk: clearRisk ? null : (risk ?? this.risk),
    riskReason: riskReason ?? this.riskReason,
    uncertainties: uncertainties ?? this.uncertainties,
  );

  Map<String, Object?> toJson() => <String, Object?>{
    'id': id,
    'name': name,
    'approximate_quantity': approximateQuantity,
    'visible_cues': visibleCues,
    'confidence': confidence.name,
    'interested': interested,
    if (risk != null) 'risk': risk!.name,
    'risk_reason': riskReason,
    'uncertainties': uncertainties,
  };

  factory ShelfItem.fromJson(Map<String, Object?> json) => ShelfItem(
    id: _shelfScannerText(
      json['id'],
      100,
      fallback: _shelfScannerNewId('item'),
    ),
    name: _shelfScannerText(json['name'], 140, fallback: 'Unidentified item'),
    approximateQuantity: _shelfScannerText(
      json['approximate_quantity'],
      100,
      fallback: 'Quantity unclear',
    ),
    visibleCues: _shelfScannerStrings(json['visible_cues'], 8, 220),
    confidence: FoodConfidence.parse(json['confidence']),
    interested: json['interested'] == true,
    risk: json['risk'] == null ? null : ShelfRiskLevel.parse(json['risk']),
    riskReason: _shelfScannerText(json['risk_reason'], 700),
    uncertainties: _shelfScannerStrings(json['uncertainties'], 12, 260),
  );
}

final class ShelfComparison {
  final String id;
  final String leftItemId;
  final String rightItemId;
  final String? recommendedItemId;
  final String summary;
  final DateTime createdAt;

  const ShelfComparison({
    required this.id,
    required this.leftItemId,
    required this.rightItemId,
    required this.recommendedItemId,
    required this.summary,
    required this.createdAt,
  });

  Map<String, Object?> toJson() => <String, Object?>{
    'id': id,
    'left_item_id': leftItemId,
    'right_item_id': rightItemId,
    if (recommendedItemId != null) 'recommended_item_id': recommendedItemId,
    'summary': summary,
    'created_at': createdAt.toUtc().toIso8601String(),
  };

  factory ShelfComparison.fromJson(Map<String, Object?> json) =>
      ShelfComparison(
        id: _shelfScannerText(
          json['id'],
          100,
          fallback: _shelfScannerNewId('compare'),
        ),
        leftItemId: _shelfScannerText(json['left_item_id'], 100),
        rightItemId: _shelfScannerText(json['right_item_id'], 100),
        recommendedItemId: json['recommended_item_id']?.toString(),
        summary: _shelfScannerText(json['summary'], 1200),
        createdAt:
            DateTime.tryParse(json['created_at']?.toString() ?? '') ??
            DateTime.now().toUtc(),
      );
}

final class ShelfScanRecord {
  static const format = 'naza-shelf-scan-v1';

  final String id;
  final DateTime capturedAt;
  final FoodVisionImage image;
  final String note;
  final List<ShelfItem> items;
  final List<ShelfComparison> comparisons;

  const ShelfScanRecord({
    required this.id,
    required this.capturedAt,
    required this.image,
    required this.note,
    required this.items,
    required this.comparisons,
  });

  ShelfScanRecord copyWith({
    List<ShelfItem>? items,
    List<ShelfComparison>? comparisons,
  }) => ShelfScanRecord(
    id: id,
    capturedAt: capturedAt,
    image: image,
    note: note,
    items: items ?? this.items,
    comparisons: comparisons ?? this.comparisons,
  );

  Map<String, Object?> toJson() => <String, Object?>{
    'format': format,
    'id': id,
    'captured_at': capturedAt.toUtc().toIso8601String(),
    'image': image.toJson(),
    'note': note,
    'items': items.map((item) => item.toJson()).toList(growable: false),
    'comparisons': comparisons
        .map((item) => item.toJson())
        .toList(growable: false),
  };

  factory ShelfScanRecord.fromJson(Map<String, Object?> json) {
    if (json['format'] != format) {
      throw const FormatException('Unsupported shelf scan format.');
    }
    final rawItems = json['items'];
    final rawComparisons = json['comparisons'];
    return ShelfScanRecord(
      id: _shelfScannerText(
        json['id'],
        100,
        fallback: _shelfScannerNewId('shelf'),
      ),
      capturedAt:
          DateTime.tryParse(json['captured_at']?.toString() ?? '') ??
          DateTime.now().toUtc(),
      image: FoodVisionImage.fromJson(
        Map<String, Object?>.from(json['image'] as Map? ?? const {}),
      ),
      note: _shelfScannerText(json['note'], 1200),
      items: rawItems is List
          ? rawItems
                .whereType<Map>()
                .take(80)
                .map(
                  (entry) =>
                      ShelfItem.fromJson(Map<String, Object?>.from(entry)),
                )
                .toList(growable: false)
          : const <ShelfItem>[],
      comparisons: rawComparisons is List
          ? rawComparisons
                .whereType<Map>()
                .take(40)
                .map(
                  (entry) => ShelfComparison.fromJson(
                    Map<String, Object?>.from(entry),
                  ),
                )
                .toList(growable: false)
          : const <ShelfComparison>[],
    );
  }
}

abstract interface class ShelfRepository {
  ValueNotifier<int> get revision;
  Future<void> save(ShelfScanRecord record);
  Future<List<ShelfScanRecord>> list({int limit = 20});
  Future<void> clear();
}

final class EncryptedShelfRepository implements ShelfRepository {
  EncryptedShelfRepository({NazaSecureDatabase? database, this.retention = 24})
    : _shelfScannerDatabase = database ?? NazaSecureDatabase.instance {
    if (retention < 1 || retention > 100) {
      throw ArgumentError.value(retention, 'retention');
    }
  }

  static const _shelfScannerNamespace = 'food.shelf.v1';
  static const _shelfScannerIndexKey = 'index';
  static const _shelfScannerEntryPrefix = 'entry:';
  final NazaSecureDatabase _shelfScannerDatabase;
  final int retention;
  Future<void> _shelfScannerTail = Future<void>.value();

  @override
  final ValueNotifier<int> revision = ValueNotifier<int>(0);

  @override
  Future<void> save(ShelfScanRecord record) => _shelfScannerEnqueue(() async {
    final index = await _shelfScannerReadIndex();
    final entries =
        <Map<String, Object?>>[
          <String, Object?>{
            'id': record.id,
            'captured_at': record.capturedAt.toUtc().toIso8601String(),
          },
          ...index.where((entry) => entry['id'] != record.id),
        ]..sort(
          (a, b) => b['captured_at'].toString().compareTo(
            a['captured_at'].toString(),
          ),
        );
    final kept = entries.take(retention).toList(growable: false);
    final keptIds = kept.map((entry) => entry['id'].toString()).toSet();
    final pruned = entries
        .map((entry) => entry['id'].toString())
        .where((id) => !keptIds.contains(id));

    await _shelfScannerDatabase.importRecords(<NazaVaultRecordKey, Object?>{
      NazaVaultRecordKey(
        _shelfScannerNamespace,
        '$_shelfScannerEntryPrefix${record.id}',
      ): record
          .toJson(),
      const NazaVaultRecordKey(_shelfScannerNamespace, _shelfScannerIndexKey):
          <String, Object?>{'format': 'naza-shelf-index-v1', 'entries': kept},
    });
    for (final id in pruned) {
      await _shelfScannerDatabase.delete(
        _shelfScannerNamespace,
        '$_shelfScannerEntryPrefix$id',
      );
    }
    revision.value++;
  });

  @override
  Future<List<ShelfScanRecord>> list({int limit = 20}) {
    if (limit < 1 || limit > 100) throw ArgumentError.value(limit, 'limit');
    return _shelfScannerEnqueue(() async {
      final result = <ShelfScanRecord>[];
      for (final entry in (await _shelfScannerReadIndex()).take(limit)) {
        final id = entry['id']?.toString() ?? '';
        if (id.isEmpty) continue;
        final raw = await _shelfScannerDatabase.readJson(
          _shelfScannerNamespace,
          '$_shelfScannerEntryPrefix$id',
        );
        if (raw is! Map) continue;
        try {
          result.add(ShelfScanRecord.fromJson(Map<String, Object?>.from(raw)));
        } catch (error) {
          throw NazaVaultException(
            'invalid_shelf_scan',
            'An encrypted shelf scan is malformed.',
            error,
          );
        }
      }
      return List<ShelfScanRecord>.unmodifiable(result);
    });
  }

  @override
  Future<void> clear() => _shelfScannerEnqueue(() async {
    for (final entry in await _shelfScannerReadIndex()) {
      final id = entry['id']?.toString() ?? '';
      if (id.isNotEmpty) {
        await _shelfScannerDatabase.delete(
          _shelfScannerNamespace,
          '$_shelfScannerEntryPrefix$id',
        );
      }
    }
    await _shelfScannerDatabase.delete(
      _shelfScannerNamespace,
      _shelfScannerIndexKey,
    );
    revision.value++;
  });

  Future<List<Map<String, Object?>>> _shelfScannerReadIndex() async {
    final raw = await _shelfScannerDatabase.readJson(
      _shelfScannerNamespace,
      _shelfScannerIndexKey,
    );
    if (raw == null) return <Map<String, Object?>>[];
    if (raw is! Map || raw['format'] != 'naza-shelf-index-v1') {
      throw const NazaVaultException(
        'invalid_shelf_index',
        'The encrypted shelf index is malformed.',
      );
    }
    final entries = raw['entries'];
    if (entries is! List) return <Map<String, Object?>>[];
    return entries
        .whereType<Map>()
        .take(100)
        .map((entry) => Map<String, Object?>.from(entry))
        .toList(growable: false);
  }

  Future<T> _shelfScannerEnqueue<T>(Future<T> Function() operation) {
    final queued = _shelfScannerTail.then((_) => operation());
    _shelfScannerTail = queued.then<void>(
      (_) {},
      onError: (Object _, StackTrace _) {},
    );
    return queued;
  }
}

final class MemoryShelfRepository implements ShelfRepository {
  final Map<String, ShelfScanRecord> _shelfScannerRecords =
      <String, ShelfScanRecord>{};

  @override
  final ValueNotifier<int> revision = ValueNotifier<int>(0);

  @override
  Future<void> save(ShelfScanRecord record) async {
    _shelfScannerRecords[record.id] = record;
    revision.value++;
  }

  @override
  Future<List<ShelfScanRecord>> list({int limit = 20}) async {
    final values = _shelfScannerRecords.values.toList(growable: false)
      ..sort((a, b) => b.capturedAt.compareTo(a.capturedAt));
    return List<ShelfScanRecord>.unmodifiable(values.take(limit));
  }

  @override
  Future<void> clear() async {
    _shelfScannerRecords.clear();
    revision.value++;
  }
}

final class ShelfScannerPane extends StatefulWidget {
  final ShelfRepository repository;
  final FoodPhotoPicker photoPicker;
  final ShelfVisionAnalyzer analyzeVision;
  final VoidCallback? onCancel;

  const ShelfScannerPane({
    super.key,
    required this.repository,
    required this.photoPicker,
    required this.analyzeVision,
    this.onCancel,
  });

  @override
  State<ShelfScannerPane> createState() => _ShelfScannerShelfScannerPaneState();
}

class _ShelfScannerShelfScannerPaneState extends State<ShelfScannerPane> {
  final TextEditingController _shelfScannerNote = TextEditingController();
  FoodVisionImage? _shelfScannerImage;
  ShelfScanRecord? _shelfScannerRecord;
  final Set<String> _shelfScannerCompareIds = <String>{};
  bool _shelfScannerBusy = false;
  bool _shelfScannerStarted = false;
  int _shelfScannerAnalysisGeneration = 0;
  String _shelfScannerStatus = 'Ready to scan a grocery shelf';

  @override
  void dispose() {
    _shelfScannerNote.dispose();
    super.dispose();
  }

  void _shelfScannerCancelAnalysis() {
    _shelfScannerAnalysisGeneration++;
    widget.onCancel?.call();
    if (mounted) setState(() => _shelfScannerStatus = 'Analysis cancelled');
  }

  Future<void> _shelfScannerChoosePhoto() async {
    if (_shelfScannerBusy) return;
    final source = await _shelfScannerChooseSource(context);
    if (source == null || !mounted) return;
    setState(() {
      _shelfScannerBusy = true;
      _shelfScannerStatus = 'Preparing photo securely';
    });
    final result = switch (source) {
      _ShelfScannerShelfPhotoSource.camera =>
        await widget.photoPicker.captureCamera(),
      _ShelfScannerShelfPhotoSource.gallery =>
        await widget.photoPicker.pickGallery(),
      _ShelfScannerShelfPhotoSource.files =>
        await widget.photoPicker.pickFiles(),
    };
    if (!mounted) return;
    setState(() {
      _shelfScannerBusy = false;
      if (result.selected) {
        _shelfScannerImage = result.image;
        _shelfScannerRecord = null;
        _shelfScannerCompareIds.clear();
        _shelfScannerStatus =
            'Photo normalized locally; original metadata discarded';
      } else {
        _shelfScannerStatus =
            result.message ??
            (result.outcome == FoodPhotoPickOutcome.cancelled
                ? 'Photo selection cancelled'
                : 'Photo unavailable');
      }
    });
  }

  Future<void> _shelfScannerScanShelf() async {
    final image = _shelfScannerImage;
    if (_shelfScannerBusy || image == null) return;
    setState(() {
      _shelfScannerBusy = true;
      _shelfScannerStatus = 'Finding visible shelf items locally';
    });
    try {
      final note = _shelfScannerNote.text.trim();
      final analysis = await widget.analyzeVision(
        image,
        'GROCERY SHELF INVENTORY MODE. Treat the scene as a retail shelf. '
        'List only products visibly supported by the image. Preserve brand and '
        'product wording only when readable. Do not invent prices, recalls, '
        'expiration dates, ingredients, allergens, pathogens, or hidden '
        'package contents. User note: $note',
      );
      if (!mounted) return;
      final seen = <String, int>{};
      final items = <ShelfItem>[];
      for (final observation in analysis.items.take(60)) {
        final base = _shelfScannerSlug(observation.name);
        final ordinal = (seen[base] ?? 0) + 1;
        seen[base] = ordinal;
        items.add(
          ShelfItem(
            id: '$base-$ordinal',
            name: observation.name,
            approximateQuantity: observation.approximateQuantity,
            visibleCues: observation.visibleCues,
            confidence: observation.confidence,
            uncertainties: analysis.uncertainties,
          ),
        );
      }
      final record = ShelfScanRecord(
        id: _shelfScannerNewId('shelf'),
        capturedAt: DateTime.now().toUtc(),
        image: image,
        note: note,
        items: List<ShelfItem>.unmodifiable(items),
        comparisons: const <ShelfComparison>[],
      );
      await widget.repository.save(record);
      if (!mounted) return;
      setState(() {
        _shelfScannerRecord = record;
        _shelfScannerBusy = false;
        _shelfScannerStatus = items.isEmpty
            ? 'No products were confidently structured from this image'
            : '${items.length} visible product${items.length == 1 ? '' : 's'} saved encrypted';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _shelfScannerBusy = false;
        _shelfScannerStatus = 'Shelf scan failed: $error';
      });
    }
  }

  void _shelfScannerSetInterested(String id, bool value) {
    final record = _shelfScannerRecord;
    if (_shelfScannerBusy || record == null) return;
    final updated = record.copyWith(
      items: List<ShelfItem>.unmodifiable(
        record.items
            .map(
              (item) => item.id == id ? item.copyWith(interested: value) : item,
            )
            .toList(growable: false),
      ),
    );
    setState(() => _shelfScannerRecord = updated);
    unawaited(widget.repository.save(updated));
  }

  Future<void> _shelfScannerRiskSelected() async {
    final record = _shelfScannerRecord;
    if (_shelfScannerBusy || record == null) return;
    final selected = record.items.where((item) => item.interested).toList();
    if (selected.isEmpty) {
      setState(() => _shelfScannerStatus = 'Check at least one item first');
      return;
    }
    setState(() => _shelfScannerBusy = true);
    final generation = ++_shelfScannerAnalysisGeneration;
    var working = record;
    try {
      for (var index = 0; index < selected.length; index++) {
        final target = selected[index];
        if (!mounted) return;
        setState(() {
          _shelfScannerStatus =
              'Reviewing ${index + 1}/${selected.length}: ${target.name}';
        });
        final analysis = await widget.analyzeVision(
          record.image,
          'SHELF ITEM REVIEW MODE. Focus only on the visible product named '
          '"${target.name}". Return only image-supported evidence. Pay attention '
          'to package integrity, visible damage/opening/leak/swelling and '
          'readable storage cues. Do not claim pathogens, recalls, contamination, '
          'expiration, nutrition, ingredients, or allergens unless directly '
          'readable in the supplied image.',
        );
        if (!mounted || generation != _shelfScannerAnalysisGeneration) return;
        final focused = _shelfScannerClosestObservation(
          analysis.items,
          target.name,
        );
        final risk = _shelfScannerDeriveReviewRisk(
          focused ??
              FridgeItemObservation(
                name: target.name,
                approximateQuantity: target.approximateQuantity,
                location: 'Retail shelf',
                visibleCues: target.visibleCues,
                useWindow: 'Verify package and label',
                confidence: target.confidence,
              ),
          analysis,
        );
        working = working.copyWith(
          items: List<ShelfItem>.unmodifiable(
            working.items
                .map(
                  (item) => item.id == target.id
                      ? item.copyWith(
                          risk: risk,
                          riskReason: _shelfScannerRiskReason(risk),
                          uncertainties: analysis.uncertainties,
                        )
                      : item,
                )
                .toList(growable: false),
          ),
        );
        await widget.repository.save(working);
      }
      if (!mounted) return;
      setState(() {
        _shelfScannerRecord = working;
        _shelfScannerBusy = false;
        _shelfScannerStatus = 'Selected-item review complete and encrypted';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _shelfScannerRecord = working;
        _shelfScannerBusy = false;
        _shelfScannerStatus = 'Item review stopped: $error';
      });
    }
  }

  void _shelfScannerToggleCompare(String id, bool selected) {
    if (_shelfScannerBusy) return;
    setState(() {
      if (selected) {
        if (_shelfScannerCompareIds.length < 2) _shelfScannerCompareIds.add(id);
      } else {
        _shelfScannerCompareIds.remove(id);
      }
    });
  }

  Future<void> _shelfScannerCompare() async {
    final record = _shelfScannerRecord;
    if (_shelfScannerBusy ||
        record == null ||
        _shelfScannerCompareIds.length != 2) {
      if (record != null) {
        setState(
          () => _shelfScannerStatus =
              'Choose exactly two similar items to compare',
        );
      }
      return;
    }
    final pair = record.items
        .where((item) => _shelfScannerCompareIds.contains(item.id))
        .toList(growable: false);
    if (pair.length != 2) return;
    setState(() {
      _shelfScannerBusy = true;
      _shelfScannerStatus = 'Running local two-item comparison';
    });
    final generation = ++_shelfScannerAnalysisGeneration;
    try {
      await widget.analyzeVision(
        record.image,
        'SHELF COMPARISON MODE. Compare only "${pair[0].name}" and '
        '"${pair[1].name}" using evidence visibly supported by this shelf '
        'image. Discuss readable packaging/handling cues and uncertainty. Do '
        'not invent price, nutrition, ingredients, recalls, pathogens, '
        'contamination, expiration, or hidden attributes. If the image cannot '
        'support a preference, say so.',
      );
      if (!mounted || generation != _shelfScannerAnalysisGeneration) return;
      final recommendation = _shelfScannerRecommend(pair[0], pair[1]);
      final fallback = _shelfScannerComparisonFallback(
        pair[0],
        pair[1],
        recommendation,
      );
      // The deterministic recommendation is authoritative. Model prose is
      // intentionally not persisted because it can contradict that decision.
      final summary = fallback;
      final comparison = ShelfComparison(
        id: _shelfScannerNewId('compare'),
        leftItemId: pair[0].id,
        rightItemId: pair[1].id,
        recommendedItemId: recommendation?.id,
        summary: summary,
        createdAt: DateTime.now().toUtc(),
      );
      final updated = record.copyWith(
        comparisons: List<ShelfComparison>.unmodifiable(<ShelfComparison>[
          comparison,
          ...record.comparisons,
        ]),
      );
      await widget.repository.save(updated);
      if (!mounted) return;
      setState(() {
        _shelfScannerRecord = updated;
        _shelfScannerBusy = false;
        _shelfScannerStatus = recommendation == null
            ? 'Comparison saved; no evidence-backed winner'
            : 'Comparison saved; ${recommendation.name} suggested';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _shelfScannerBusy = false;
        _shelfScannerStatus = 'Comparison failed: $error';
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final compact = MediaQuery.sizeOf(context).width < 720;
    final record = _shelfScannerRecord;
    return CustomScrollView(
      keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
      slivers: <Widget>[
        SliverPadding(
          padding: EdgeInsets.fromLTRB(
            compact ? 12 : 24,
            16,
            compact ? 12 : 24,
            32,
          ),
          sliver: SliverToBoxAdapter(
            child: Center(
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 1180),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: <Widget>[
                    _ShelfScannerHeader(
                      started: _shelfScannerStarted,
                      busy: _shelfScannerBusy,
                      status: _shelfScannerStatus,
                      onStart: () =>
                          setState(() => _shelfScannerStarted = true),
                      onStop: _shelfScannerBusy
                          ? _shelfScannerCancelAnalysis
                          : null,
                    ),
                    const SizedBox(height: 14),
                    if (!_shelfScannerStarted)
                      _ShelfScannerStartCard(
                        onStart: () =>
                            setState(() => _shelfScannerStarted = true),
                      )
                    else ...<Widget>[
                      _ShelfScannerCaptureCard(
                        image: _shelfScannerImage,
                        busy: _shelfScannerBusy,
                        note: _shelfScannerNote,
                        onPhoto: _shelfScannerChoosePhoto,
                        onClear: _shelfScannerBusy
                            ? null
                            : () => setState(() {
                                _shelfScannerImage = null;
                                _shelfScannerRecord = null;
                                _shelfScannerCompareIds.clear();
                              }),
                        onScan: _shelfScannerImage == null || _shelfScannerBusy
                            ? null
                            : _shelfScannerScanShelf,
                      ),
                      if (record != null) ...<Widget>[
                        const SizedBox(height: 14),
                        _ShelfScannerInterestCard(
                          items: record.items,
                          busy: _shelfScannerBusy,
                          onChanged: _shelfScannerSetInterested,
                          onRiskSelected: _shelfScannerRiskSelected,
                        ),
                        const SizedBox(height: 14),
                        _ShelfScannerCompareCard(
                          record: record,
                          selected: _shelfScannerCompareIds,
                          busy: _shelfScannerBusy,
                          onToggle: _shelfScannerToggleCompare,
                          onCompare: _shelfScannerCompare,
                        ),
                      ],
                    ],
                  ],
                ),
              ),
            ),
          ),
        ),
      ],
    );
  }
}

