final class CsdConfidence {
  const CsdConfidence._({
    required this.visual,
    required this.location,
    required this.temporal,
    required this.entity,
    required this.global,
  });

  factory CsdConfidence({
    required double visual,
    required double location,
    required double temporal,
    required double entity,
    required double global,
  }) => CsdConfidence._(
    visual: _chromaticSpatialModelsUnitDouble(visual, 'visual'),
    location: _chromaticSpatialModelsUnitDouble(location, 'location'),
    temporal: _chromaticSpatialModelsUnitDouble(temporal, 'temporal'),
    entity: _chromaticSpatialModelsUnitDouble(entity, 'entity'),
    global: _chromaticSpatialModelsUnitDouble(global, 'global'),
  );

  final double visual;
  final double location;
  final double temporal;
  final double entity;
  final double global;

  /// Geometric mean: one unsupported evidence channel cannot be hidden by
  /// several high-confidence channels.
  double get aggregate {
    final product = visual * location * temporal * entity * global;
    return product <= 0 ? 0 : math.pow(product, 0.2).toDouble();
  }

  Map<String, Object?> toJson() => <String, Object?>{
    'visual': visual,
    'location': location,
    'temporal': temporal,
    'entity': entity,
    'global': global,
  };

  factory CsdConfidence.fromJson(Map<String, dynamic> json) =>
      _chromaticSpatialModelsDecodeModel(
        'CsdConfidence',
        () => CsdConfidence(
          visual: _chromaticSpatialModelsRequiredDouble(json, 'visual'),
          location: _chromaticSpatialModelsRequiredDouble(json, 'location'),
          temporal: _chromaticSpatialModelsRequiredDouble(json, 'temporal'),
          entity: _chromaticSpatialModelsRequiredDouble(json, 'entity'),
          global: _chromaticSpatialModelsRequiredDouble(json, 'global'),
        ),
      );

  @override
  bool operator ==(Object other) =>
      other is CsdConfidence &&
      visual == other.visual &&
      location == other.location &&
      temporal == other.temporal &&
      entity == other.entity &&
      global == other.global;

  @override
  int get hashCode => Object.hash(visual, location, temporal, entity, global);
}

