/// An immutable, uncertain observation of physical reality.
final class CsdObservation {
  CsdObservation._({
    required this.id,
    required this.kind,
    required this.entities,
    required this.pose,
    required this.region,
    required this.observedAt,
    required this.temporalUncertainty,
    required this.halfLife,
    required this.confidence,
    required this.provenance,
    required List<double> semanticEmbedding,
    required List<double> visualEmbedding,
    required Uint8List perceptualHash,
    required this.metadata,
  }) : _chromaticSpatialModelsSemanticEmbedding = semanticEmbedding,
       _chromaticSpatialModelsVisualEmbedding = visualEmbedding,
       _chromaticSpatialModelsPerceptualHash = perceptualHash;

  factory CsdObservation({
    required String id,
    required CsdObservationKind kind,
    required List<CsdEntityCandidate> entities,
    required CsdPose pose,
    required CsdRegionPath region,
    required DateTime observedAt,
    Duration temporalUncertainty = Duration.zero,
    required Duration halfLife,
    required CsdConfidence confidence,
    required CsdProvenance provenance,
    List<double> semanticEmbedding = const <double>[],
    List<double> visualEmbedding = const <double>[],
    List<int> perceptualHash = const <int>[],
    Map<String, Object?> metadata = const <String, Object?>{},
  }) {
    if (entities.isEmpty ||
        entities.length > CsdModelLimits.maxEntityCandidates) {
      throw RangeError.range(
        entities.length,
        1,
        CsdModelLimits.maxEntityCandidates,
        'entities.length',
      );
    }
    final frozenEntities = List<CsdEntityCandidate>.unmodifiable(entities);
    final entityIds = <String>{};
    var probabilityMass = 0.0;
    for (final entity in frozenEntities) {
      if (!entityIds.add(entity.entityId)) {
        throw ArgumentError.value(
          entity.entityId,
          'entities',
          'Entity candidate IDs must be unique.',
        );
      }
      probabilityMass += entity.probability;
    }
    if (probabilityMass > 1.000000001) {
      throw ArgumentError.value(
        probabilityMass,
        'entities',
        'Entity candidate probability mass must not exceed 1.',
      );
    }
    final utcObservedAt = observedAt.toUtc();
    if (utcObservedAt.year < 1970 || utcObservedAt.year > 9999) {
      throw RangeError.range(utcObservedAt.year, 1970, 9999, 'observedAt.year');
    }
    if (temporalUncertainty.isNegative ||
        temporalUncertainty.inMicroseconds >
            CsdModelLimits.maxTemporalUncertaintyMicroseconds) {
      throw RangeError.range(
        temporalUncertainty.inMicroseconds,
        0,
        CsdModelLimits.maxTemporalUncertaintyMicroseconds,
        'temporalUncertainty.inMicroseconds',
      );
    }
    if (halfLife.inMicroseconds < CsdModelLimits.minHalfLifeMicroseconds ||
        halfLife.inMicroseconds > CsdModelLimits.maxHalfLifeMicroseconds) {
      throw RangeError.range(
        halfLife.inMicroseconds,
        CsdModelLimits.minHalfLifeMicroseconds,
        CsdModelLimits.maxHalfLifeMicroseconds,
        'halfLife.inMicroseconds',
      );
    }
    return CsdObservation._(
      id: _chromaticSpatialModelsBoundedString(
        id,
        'id',
        CsdModelLimits.maxIdCharacters,
      ),
      kind: kind,
      entities: frozenEntities,
      pose: pose,
      region: region,
      observedAt: utcObservedAt,
      temporalUncertainty: temporalUncertainty,
      halfLife: halfLife,
      confidence: confidence,
      provenance: provenance,
      semanticEmbedding: _chromaticSpatialModelsFreezeEmbedding(
        semanticEmbedding,
        'semanticEmbedding',
      ),
      visualEmbedding: _chromaticSpatialModelsFreezeEmbedding(
        visualEmbedding,
        'visualEmbedding',
      ),
      perceptualHash: _chromaticSpatialModelsFreezeBytes(
        perceptualHash,
        'perceptualHash',
        CsdModelLimits.maxPerceptualHashBytes,
      ),
      metadata: _chromaticSpatialModelsFreezeMetadata(metadata),
    );
  }

  static const String format = 'naza-csd-observation-v1';

  final String id;
  final CsdObservationKind kind;
  final List<CsdEntityCandidate> entities;
  final CsdPose pose;
  final CsdRegionPath region;
  final DateTime observedAt;
  final Duration temporalUncertainty;
  final Duration halfLife;
  final CsdConfidence confidence;
  final CsdProvenance provenance;
  final List<double> _chromaticSpatialModelsSemanticEmbedding;
  final List<double> _chromaticSpatialModelsVisualEmbedding;
  final Uint8List _chromaticSpatialModelsPerceptualHash;
  final Map<String, Object?> metadata;

  List<double> get semanticEmbedding =>
      _chromaticSpatialModelsSemanticEmbedding;
  List<double> get visualEmbedding => _chromaticSpatialModelsVisualEmbedding;
  Uint8List get perceptualHash =>
      Uint8List.fromList(_chromaticSpatialModelsPerceptualHash);
  double get entityProbabilityMass =>
      entities.fold<double>(0, (sum, entity) => sum + entity.probability);

  CsdEntityCandidate get mostLikelyEntity {
    var best = entities.first;
    for (final candidate in entities.skip(1)) {
      if (candidate.probability > best.probability ||
          (candidate.probability == best.probability &&
              candidate.entityId.compareTo(best.entityId) < 0)) {
        best = candidate;
      }
    }
    return best;
  }

  double freshnessAt(DateTime time) {
    final ageMicros = math.max(
      0,
      time.toUtc().difference(observedAt).inMicroseconds,
    );
    return math.pow(0.5, ageMicros / halfLife.inMicroseconds).toDouble();
  }

  Map<String, Object?> toJson() => <String, Object?>{
    'format': format,
    'id': id,
    'kind': kind.name,
    'entities': entities
        .map((entity) => entity.toJson())
        .toList(growable: false),
    'pose': pose.toJson(),
    'region': region.toJson(),
    'observedAt': observedAt.toIso8601String(),
    'temporalUncertaintyMicros': temporalUncertainty.inMicroseconds,
    'halfLifeMicros': halfLife.inMicroseconds,
    'confidence': confidence.toJson(),
    'provenance': provenance.toJson(),
    'semanticEmbedding': _chromaticSpatialModelsSemanticEmbedding,
    'visualEmbedding': _chromaticSpatialModelsVisualEmbedding,
    'perceptualHash': _chromaticSpatialModelsBytesToHex(
      _chromaticSpatialModelsPerceptualHash,
    ),
    'metadata': metadata,
  };

  factory CsdObservation.fromJson(Map<String, dynamic> json) =>
      _chromaticSpatialModelsDecodeModel('CsdObservation', () {
        if (json['format'] != format) {
          throw const FormatException('Unsupported CSD observation format.');
        }
        final rawEntities = json['entities'];
        if (rawEntities is! List) {
          throw const FormatException('entities must be a list.');
        }
        if (rawEntities.isEmpty ||
            rawEntities.length > CsdModelLimits.maxEntityCandidates) {
          throw const FormatException('entities has an invalid length.');
        }
        final observedAtValue = json['observedAt'];
        if (observedAtValue is! String) {
          throw const FormatException('observedAt must be an ISO-8601 string.');
        }
        final parsedObservedAt = DateTime.tryParse(observedAtValue);
        if (parsedObservedAt == null || !parsedObservedAt.isUtc) {
          throw const FormatException(
            'observedAt must contain an explicit UTC offset.',
          );
        }
        return CsdObservation(
          id: _chromaticSpatialModelsRequiredString(json, 'id'),
          kind: _chromaticSpatialModelsRequiredEnum(
            json,
            'kind',
            CsdObservationKind.values,
          ),
          entities: rawEntities
              .map((value) {
                if (value is! Map) {
                  throw const FormatException('Invalid entity candidate.');
                }
                if (value.length > 16) {
                  throw const FormatException(
                    'Entity candidate contains excess data.',
                  );
                }
                return CsdEntityCandidate.fromJson(
                  Map<String, dynamic>.from(value),
                );
              })
              .toList(growable: false),
          pose: CsdPose.fromJson(
            _chromaticSpatialModelsRequiredMap(json, 'pose'),
          ),
          region: CsdRegionPath.fromJson(
            _chromaticSpatialModelsRequiredMap(json, 'region'),
          ),
          observedAt: parsedObservedAt.toUtc(),
          temporalUncertainty: Duration(
            microseconds: _chromaticSpatialModelsRequiredInt(
              json,
              'temporalUncertaintyMicros',
            ),
          ),
          halfLife: Duration(
            microseconds: _chromaticSpatialModelsRequiredInt(
              json,
              'halfLifeMicros',
            ),
          ),
          confidence: CsdConfidence.fromJson(
            _chromaticSpatialModelsRequiredMap(json, 'confidence'),
          ),
          provenance: CsdProvenance.fromJson(
            _chromaticSpatialModelsRequiredMap(json, 'provenance'),
          ),
          semanticEmbedding: _chromaticSpatialModelsRequiredDoubleList(
            json,
            'semanticEmbedding',
            maximumLength: CsdModelLimits.maxEmbeddingDimensions,
          ),
          visualEmbedding: _chromaticSpatialModelsRequiredDoubleList(
            json,
            'visualEmbedding',
            maximumLength: CsdModelLimits.maxEmbeddingDimensions,
          ),
          perceptualHash: _chromaticSpatialModelsRequiredHexBytes(
            json,
            'perceptualHash',
            maximumBytes: CsdModelLimits.maxPerceptualHashBytes,
          ),
          metadata: _chromaticSpatialModelsRequiredObjectMap(
            json,
            'metadata',
            maximumEntries: CsdModelLimits.maxMetadataEntries,
          ),
        );
      });

  @override
  bool operator ==(Object other) =>
      other is CsdObservation &&
      id == other.id &&
      kind == other.kind &&
      _chromaticSpatialModelsListEquals(entities, other.entities) &&
      pose == other.pose &&
      region == other.region &&
      observedAt == other.observedAt &&
      temporalUncertainty == other.temporalUncertainty &&
      halfLife == other.halfLife &&
      confidence == other.confidence &&
      provenance == other.provenance &&
      _chromaticSpatialModelsListEquals(
        _chromaticSpatialModelsSemanticEmbedding,
        other._chromaticSpatialModelsSemanticEmbedding,
      ) &&
      _chromaticSpatialModelsListEquals(
        _chromaticSpatialModelsVisualEmbedding,
        other._chromaticSpatialModelsVisualEmbedding,
      ) &&
      _chromaticSpatialModelsListEquals(
        _chromaticSpatialModelsPerceptualHash,
        other._chromaticSpatialModelsPerceptualHash,
      ) &&
      _chromaticSpatialModelsDeepEquals(metadata, other.metadata);

  @override
  int get hashCode => Object.hash(
    id,
    kind,
    Object.hashAll(entities),
    pose,
    region,
    observedAt,
    temporalUncertainty,
    halfLife,
    confidence,
    provenance,
    Object.hashAll(_chromaticSpatialModelsSemanticEmbedding),
    Object.hashAll(_chromaticSpatialModelsVisualEmbedding),
    Object.hashAll(_chromaticSpatialModelsPerceptualHash),
    _chromaticSpatialModelsDeepHash(metadata),
  );
}

/// A compact 96-bit address in perceptual-spatial state.
final class CsdChromaticAddress implements Comparable<CsdChromaticAddress> {
  CsdChromaticAddress._(this._chromaticSpatialModelsBytes);

  factory CsdChromaticAddress(List<int> bytes) {
    return CsdChromaticAddress._(
      _chromaticSpatialModelsFreezeBytes(
        bytes,
        'bytes',
        byteLength,
        exactLength: byteLength,
      ),
    );
  }

  factory CsdChromaticAddress.fromHex(String value) {
    final normalized = value.trim().toLowerCase();
    if (normalized.length != byteLength * 2 ||
        !RegExp(r'^[0-9a-f]+$').hasMatch(normalized)) {
      throw FormatException(
        'A chromatic address must be exactly ${byteLength * 2} hex characters.',
      );
    }
    return CsdChromaticAddress(_chromaticSpatialModelsHexToBytes(normalized));
  }

  static const String format = 'naza-csd-chromatic-address-v1';
  static const int byteLength = 12;

  final Uint8List _chromaticSpatialModelsBytes;

  Uint8List get bytes => Uint8List.fromList(_chromaticSpatialModelsBytes);
  String get hex =>
      _chromaticSpatialModelsBytesToHex(_chromaticSpatialModelsBytes);

  int operator [](CsdChromaticChannel channel) =>
      _chromaticSpatialModelsBytes[channel.index];

  String prefixHex(int byteCount) {
    if (byteCount < 0 || byteCount > byteLength) {
      throw RangeError.range(byteCount, 0, byteLength, 'byteCount');
    }
    return _chromaticSpatialModelsBytesToHex(
      _chromaticSpatialModelsBytes.sublist(0, byteCount),
    );
  }

  /// Weighted normalized Minkowski distance in the range 0...1.
  ///
  /// Hue is circular, so 0 and 255 remain near one another. Missing dimensions
  /// should be suppressed by setting their query group weight to zero.
  double distanceTo(
    CsdChromaticAddress other, {
    required CsdQueryWeights weights,
    double exponent = 2,
  }) {
    exponent = _chromaticSpatialModelsBoundedDouble(exponent, 'exponent', 1, 4);
    final channels = weights.channelWeights;
    var sum = 0.0;
    for (var index = 0; index < byteLength; index++) {
      final rawDifference =
          (_chromaticSpatialModelsBytes[index] -
                  other._chromaticSpatialModelsBytes[index])
              .abs();
      final difference = index == CsdChromaticChannel.visualHue.index
          ? math.min(rawDifference, 256 - rawDifference) / 128.0
          : rawDifference / 255.0;
      sum += channels[index] * math.pow(difference, exponent);
    }
    return math.pow(sum, 1.0 / exponent).toDouble().clamp(0.0, 1.0);
  }

  Map<String, Object?> toJson() => <String, Object?>{
    'format': format,
    'hex': hex,
  };

  factory CsdChromaticAddress.fromJson(Map<String, dynamic> json) {
    if (json['format'] != format) {
      throw const FormatException('Unsupported chromatic address format.');
    }
    return CsdChromaticAddress.fromHex(
      _chromaticSpatialModelsRequiredString(json, 'hex'),
    );
  }

  @override
  int compareTo(CsdChromaticAddress other) {
    for (var index = 0; index < byteLength; index++) {
      final comparison = _chromaticSpatialModelsBytes[index].compareTo(
        other._chromaticSpatialModelsBytes[index],
      );
      if (comparison != 0) return comparison;
    }
    return 0;
  }

  @override
  bool operator ==(Object other) =>
      other is CsdChromaticAddress &&
      _chromaticSpatialModelsListEquals(
        _chromaticSpatialModelsBytes,
        other._chromaticSpatialModelsBytes,
      );

  @override
  int get hashCode => Object.hashAll(_chromaticSpatialModelsBytes);

  @override
  String toString() => hex;
}

/// Contextual group weights expanded deterministically across 12 channels.
final class CsdQueryWeights {
  CsdQueryWeights._({
    required this.spatial,
    required this.visual,
    required this.semantic,
    required this.geometry,
    required this.temporal,
    required this.hierarchy,
  });

  factory CsdQueryWeights({
    double spatial = 0.24,
    double visual = 0.20,
    double semantic = 0.20,
    double geometry = 0.08,
    double temporal = 0.12,
    double hierarchy = 0.16,
  }) {
    final values = <double>[
      _chromaticSpatialModelsNonNegativeFinite(spatial, 'spatial'),
      _chromaticSpatialModelsNonNegativeFinite(visual, 'visual'),
      _chromaticSpatialModelsNonNegativeFinite(semantic, 'semantic'),
      _chromaticSpatialModelsNonNegativeFinite(geometry, 'geometry'),
      _chromaticSpatialModelsNonNegativeFinite(temporal, 'temporal'),
      _chromaticSpatialModelsNonNegativeFinite(hierarchy, 'hierarchy'),
    ];
    final total = values.fold<double>(0, (sum, value) => sum + value);
    if (total <= 1e-15) {
      throw ArgumentError('At least one CSD query weight must be positive.');
    }
    final normalization = (total - 1).abs() <= 1e-12 ? 1.0 : total;
    return CsdQueryWeights._(
      spatial: values[0] / normalization,
      visual: values[1] / normalization,
      semantic: values[2] / normalization,
      geometry: values[3] / normalization,
      temporal: values[4] / normalization,
      hierarchy: values[5] / normalization,
    );
  }

  factory CsdQueryWeights.forProfile(CsdQueryProfile profile) =>
      switch (profile) {
        CsdQueryProfile.balanced => CsdQueryWeights(),
        CsdQueryProfile.navigation => CsdQueryWeights(
          spatial: 0.42,
          visual: 0.06,
          semantic: 0.08,
          geometry: 0.09,
          temporal: 0.12,
          hierarchy: 0.23,
        ),
        CsdQueryProfile.recognition => CsdQueryWeights(
          spatial: 0.08,
          visual: 0.36,
          semantic: 0.30,
          geometry: 0.10,
          temporal: 0.04,
          hierarchy: 0.12,
        ),
        CsdQueryProfile.history => CsdQueryWeights(
          spatial: 0.14,
          visual: 0.08,
          semantic: 0.13,
          geometry: 0.05,
          temporal: 0.45,
          hierarchy: 0.15,
        ),
      };

  static const String format = 'naza-csd-query-weights-v1';

  final double spatial;
  final double visual;
  final double semantic;
  final double geometry;
  final double temporal;
  final double hierarchy;

  List<double> get channelWeights => List<double>.unmodifiable(<double>[
    spatial / 3,
    spatial / 3,
    spatial / 3,
    visual / 2,
    visual / 2,
    semantic / 2,
    semantic / 2,
    geometry,
    temporal,
    hierarchy / 3,
    hierarchy / 3,
    hierarchy / 3,
  ]);

  double weightFor(CsdChromaticChannel channel) =>
      channelWeights[channel.index];

  Map<String, Object?> toJson() => <String, Object?>{
    'format': format,
    'spatial': spatial,
    'visual': visual,
    'semantic': semantic,
    'geometry': geometry,
    'temporal': temporal,
    'hierarchy': hierarchy,
  };

  factory CsdQueryWeights.fromJson(Map<String, dynamic> json) =>
      _chromaticSpatialModelsDecodeModel('CsdQueryWeights', () {
        if (json['format'] != format) {
          throw const FormatException('Unsupported CSD query-weight format.');
        }
        return CsdQueryWeights(
          spatial: _chromaticSpatialModelsRequiredDouble(json, 'spatial'),
          visual: _chromaticSpatialModelsRequiredDouble(json, 'visual'),
          semantic: _chromaticSpatialModelsRequiredDouble(json, 'semantic'),
          geometry: _chromaticSpatialModelsRequiredDouble(json, 'geometry'),
          temporal: _chromaticSpatialModelsRequiredDouble(json, 'temporal'),
          hierarchy: _chromaticSpatialModelsRequiredDouble(json, 'hierarchy'),
        );
      });

  @override
  bool operator ==(Object other) =>
      other is CsdQueryWeights &&
      spatial == other.spatial &&
      visual == other.visual &&
      semantic == other.semantic &&
      geometry == other.geometry &&
      temporal == other.temporal &&
      hierarchy == other.hierarchy;

  @override
  int get hashCode =>
      Object.hash(spatial, visual, semantic, geometry, temporal, hierarchy);
}

double _chromaticSpatialModelsBoundedDouble(
  double value,
  String name,
  double minimum,
  double maximum, {
  bool minOpen = false,
}) {
  if (!value.isFinite ||
      (minOpen ? value <= minimum : value < minimum) ||
      value > maximum) {
    throw RangeError.value(
      value,
      name,
      'Expected a finite value in ${minOpen ? '(' : '['}$minimum, $maximum].',
    );
  }
  return value;
}

double _chromaticSpatialModelsUnitDouble(double value, String name) =>
    _chromaticSpatialModelsBoundedDouble(value, name, 0, 1);

double _chromaticSpatialModelsNonNegativeFinite(double value, String name) {
  if (!value.isFinite || value < 0 || value > 1000000) {
    throw RangeError.range(value, 0, 1000000, name);
  }
  return value;
}

String _chromaticSpatialModelsBoundedString(
  String value,
  String name,
  int maxCharacters,
) {
  final normalized = value.trim();
  if (normalized.isEmpty || normalized.length > maxCharacters) {
    throw RangeError.range(normalized.length, 1, maxCharacters, '$name.length');
  }
  if (RegExp(r'[\u0000-\u001f\u007f]').hasMatch(normalized)) {
    throw ArgumentError.value(
      value,
      name,
      'Control characters are not allowed.',
    );
  }
  return normalized;
}

String? _chromaticSpatialModelsOptionalBoundedString(
  String? value,
  String name,
  int maxCharacters,
) => value == null
    ? null
    : _chromaticSpatialModelsBoundedString(value, name, maxCharacters);

Map<String, String> _chromaticSpatialModelsFreezeStringMap(
  Map<String, String> value,
) {
  if (value.length > CsdModelLimits.maxAttributes) {
    throw RangeError.range(
      value.length,
      0,
      CsdModelLimits.maxAttributes,
      'attributes.length',
    );
  }
  final sorted = SplayTreeMap<String, String>();
  for (final entry in value.entries) {
    final key = _chromaticSpatialModelsBoundedString(
      entry.key,
      'attribute key',
      64,
    );
    final item = _chromaticSpatialModelsBoundedString(
      entry.value,
      'attribute value',
      CsdModelLimits.maxLabelCharacters,
    );
    if (sorted.containsKey(key)) {
      throw ArgumentError.value(
        entry.key,
        'attributes',
        'Attribute keys must remain unique after normalization.',
      );
    }
    sorted[key] = item;
  }
  return Map<String, String>.unmodifiable(sorted);
}

List<double> _chromaticSpatialModelsFreezeEmbedding(
  List<double> value,
  String name,
) {
  if (value.length > CsdModelLimits.maxEmbeddingDimensions) {
    throw RangeError.range(
      value.length,
      0,
      CsdModelLimits.maxEmbeddingDimensions,
      '$name.length',
    );
  }
  final copy = <double>[];
  for (var index = 0; index < value.length; index++) {
    copy.add(
      _chromaticSpatialModelsBoundedDouble(
        value[index],
        '$name[$index]',
        -CsdModelLimits.maxEmbeddingComponentMagnitude,
        CsdModelLimits.maxEmbeddingComponentMagnitude,
      ),
    );
  }
  return List<double>.unmodifiable(copy);
}

Uint8List _chromaticSpatialModelsFreezeBytes(
  List<int> value,
  String name,
  int maximumLength, {
  int? exactLength,
}) {
  if ((exactLength != null && value.length != exactLength) ||
      value.length > maximumLength) {
    throw RangeError.range(
      value.length,
      exactLength ?? 0,
      exactLength ?? maximumLength,
      '$name.length',
    );
  }
  for (var index = 0; index < value.length; index++) {
    final byte = value[index];
    if (byte < 0 || byte > 255) {
      throw RangeError.range(byte, 0, 255, '$name[$index]');
    }
  }
  return Uint8List.fromList(value);
}

Map<String, Object?> _chromaticSpatialModelsFreezeMetadata(
  Map<String, Object?> value,
) {
  if (value.length > CsdModelLimits.maxMetadataEntries) {
    throw RangeError.range(
      value.length,
      0,
      CsdModelLimits.maxMetadataEntries,
      'metadata.length',
    );
  }
  final budget = _ChromaticSpatialModelsJsonBudget();
  return _chromaticSpatialModelsFreezeJsonMap(value, 0, budget);
}

Map<String, Object?> _chromaticSpatialModelsFreezeJsonMap(
  Map<String, Object?> value,
  int depth,
  _ChromaticSpatialModelsJsonBudget budget,
) {
  if (depth > CsdModelLimits.maxMetadataDepth) {
    throw ArgumentError('Metadata nesting is too deep.');
  }
  if (value.length > CsdModelLimits.maxMetadataEntries) {
    throw ArgumentError('A metadata map has too many entries.');
  }
  final sorted = SplayTreeMap<String, Object?>();
  for (final entry in value.entries) {
    budget.consume();
    final key = _chromaticSpatialModelsBoundedString(
      entry.key,
      'metadata key',
      64,
    );
    if (sorted.containsKey(key)) {
      throw ArgumentError.value(
        entry.key,
        'metadata',
        'Metadata keys must remain unique after normalization.',
      );
    }
    sorted[key] = _chromaticSpatialModelsFreezeJsonValue(
      entry.value,
      depth + 1,
      budget,
    );
  }
  return Map<String, Object?>.unmodifiable(sorted);
}

Object? _chromaticSpatialModelsFreezeJsonValue(
  Object? value,
  int depth,
  _ChromaticSpatialModelsJsonBudget budget,
) {
  if (depth > CsdModelLimits.maxMetadataDepth) {
    throw ArgumentError('Metadata nesting is too deep.');
  }
  budget.consume();
  if (value == null || value is bool) return value;
  if (value is String) {
    if (value.length > CsdModelLimits.maxMetadataStringCharacters ||
        RegExp(r'[\u0000-\u0008\u000b\u000c\u000e-\u001f]').hasMatch(value)) {
      throw ArgumentError('Metadata contains an invalid or oversized string.');
    }
    return value;
  }
  if (value is num) {
    final doubleValue = value.toDouble();
    if (!doubleValue.isFinite || doubleValue.abs() > 1000000000000000) {
      throw ArgumentError('Metadata numbers must be finite and bounded.');
    }
    return value;
  }
  if (value is List) {
    if (value.length > CsdModelLimits.maxMetadataListItems) {
      throw ArgumentError('A metadata list has too many items.');
    }
    return List<Object?>.unmodifiable(
      value.map(
        (item) =>
            _chromaticSpatialModelsFreezeJsonValue(item, depth + 1, budget),
      ),
    );
  }
  if (value is Map) {
    final converted = <String, Object?>{};
    for (final entry in value.entries) {
      if (entry.key is! String) {
        throw ArgumentError('Metadata map keys must be strings.');
      }
      converted[entry.key as String] = entry.value;
    }
    return _chromaticSpatialModelsFreezeJsonMap(converted, depth + 1, budget);
  }
  throw ArgumentError.value(
    value.runtimeType,
    'metadata',
    'Only JSON-compatible metadata is supported.',
  );
}

final class _ChromaticSpatialModelsJsonBudget {
  int _chromaticSpatialModelsNodes = 0;

  void consume() {
    _chromaticSpatialModelsNodes++;
    if (_chromaticSpatialModelsNodes > CsdModelLimits.maxMetadataNodes) {
      throw ArgumentError('Metadata has too many nested values.');
    }
  }
}

T _chromaticSpatialModelsDecodeModel<T>(
  String modelName,
  T Function() operation,
) {
  try {
    return operation();
  } on FormatException {
    rethrow;
  } on RangeError catch (error) {
    throw FormatException('Invalid $modelName: ${error.message}');
  } on ArgumentError catch (error) {
    throw FormatException('Invalid $modelName: ${error.message}');
  } on TypeError catch (error) {
    throw FormatException('Invalid $modelName: $error');
  }
}

Map<String, dynamic> _chromaticSpatialModelsRequiredMap(
  Map<String, dynamic> json,
  String key,
) {
  final value = json[key];
  if (value is! Map) throw FormatException('$key must be a map.');
  if (value.length > CsdModelLimits.maxMetadataEntries) {
    throw FormatException('$key contains excess data.');
  }
  return Map<String, dynamic>.from(value);
}

Map<String, Object?> _chromaticSpatialModelsRequiredObjectMap(
  Map<String, dynamic> json,
  String key, {
  required int maximumEntries,
}) {
  final value = json[key];
  if (value is! Map) throw FormatException('$key must be a map.');
  if (value.length > maximumEntries) {
    throw FormatException('$key has too many entries.');
  }
  return Map<String, Object?>.from(value);
}

String _chromaticSpatialModelsRequiredString(
  Map<String, dynamic> json,
  String key,
) {
  final value = json[key];
  if (value is! String) throw FormatException('$key must be a string.');
  return value;
}

String? _chromaticSpatialModelsOptionalString(
  Map<String, dynamic> json,
  String key,
) {
  final value = json[key];
  if (value == null) return null;
  if (value is! String) throw FormatException('$key must be a string.');
  return value;
}

double _chromaticSpatialModelsRequiredDouble(
  Map<String, dynamic> json,
  String key,
) {
  final value = json[key];
  if (value is! num) throw FormatException('$key must be a number.');
  final converted = value.toDouble();
  if (!converted.isFinite) throw FormatException('$key must be finite.');
  return converted;
}

double? _chromaticSpatialModelsOptionalDouble(
  Map<String, dynamic> json,
  String key,
) {
  if (!json.containsKey(key) || json[key] == null) return null;
  return _chromaticSpatialModelsRequiredDouble(json, key);
}

int _chromaticSpatialModelsRequiredInt(Map<String, dynamic> json, String key) {
  final value = json[key];
  if (value is! int) throw FormatException('$key must be an integer.');
  return value;
}

int? _chromaticSpatialModelsOptionalInt(Map<String, dynamic> json, String key) {
  if (!json.containsKey(key) || json[key] == null) return null;
  return _chromaticSpatialModelsRequiredInt(json, key);
}

List<double> _chromaticSpatialModelsRequiredDoubleList(
  Map<String, dynamic> json,
  String key, {
  required int maximumLength,
}) {
  final value = json[key];
  if (value is! List) throw FormatException('$key must be a list.');
  if (value.length > maximumLength) {
    throw FormatException('$key has too many values.');
  }
  return value
      .map((item) {
        if (item is! num || !item.toDouble().isFinite) {
          throw FormatException('$key contains a non-finite number.');
        }
        return item.toDouble();
      })
      .toList(growable: false);
}

Map<String, String> _chromaticSpatialModelsOptionalStringMap(
  Map<String, dynamic> json,
  String key,
) {
  final value = json[key];
  if (value == null) return const <String, String>{};
  if (value is! Map) throw FormatException('$key must be a map.');
  if (value.length > CsdModelLimits.maxAttributes) {
    throw FormatException('$key has too many entries.');
  }
  final result = <String, String>{};
  for (final entry in value.entries) {
    if (entry.key is! String || entry.value is! String) {
      throw FormatException('$key must contain only string keys and values.');
    }
    result[entry.key as String] = entry.value as String;
  }
  return result;
}

T _chromaticSpatialModelsRequiredEnum<T extends Enum>(
  Map<String, dynamic> json,
  String key,
  List<T> values,
) {
  final name = _chromaticSpatialModelsRequiredString(json, key);
  for (final value in values) {
    if (value.name == name) return value;
  }
  throw FormatException('Unsupported $key value: $name.');
}

String _chromaticSpatialModelsBytesToHex(Iterable<int> bytes) =>
    bytes.map((byte) => byte.toRadixString(16).padLeft(2, '0')).join();

List<int> _chromaticSpatialModelsRequiredHexBytes(
  Map<String, dynamic> json,
  String key, {
  required int maximumBytes,
}) {
  final value = _chromaticSpatialModelsRequiredString(json, key);
  if (value.length > maximumBytes * 2) {
    throw FormatException('$key has too many bytes.');
  }
  return _chromaticSpatialModelsHexToBytes(value);
}

List<int> _chromaticSpatialModelsHexToBytes(String value) {
  if (value.length.isOdd || !RegExp(r'^[0-9a-fA-F]*$').hasMatch(value)) {
    throw const FormatException('Invalid hexadecimal byte string.');
  }
  return List<int>.generate(
    value.length ~/ 2,
    (index) => int.parse(value.substring(index * 2, index * 2 + 2), radix: 16),
    growable: false,
  );
}

bool _chromaticSpatialModelsListEquals(
  List<Object?> left,
  List<Object?> right,
) {
  if (identical(left, right)) return true;
  if (left.length != right.length) return false;
  for (var index = 0; index < left.length; index++) {
    if (!_chromaticSpatialModelsDeepEquals(left[index], right[index]))
      return false;
  }
  return true;
}

bool _chromaticSpatialModelsDeepEquals(Object? left, Object? right) {
  if (identical(left, right)) return true;
  if (left is List && right is List) {
    return _chromaticSpatialModelsListEquals(
      left.cast<Object?>(),
      right.cast<Object?>(),
    );
  }
  if (left is Map && right is Map) {
    if (left.length != right.length) return false;
    for (final entry in left.entries) {
      if (!right.containsKey(entry.key) ||
          !_chromaticSpatialModelsDeepEquals(entry.value, right[entry.key])) {
        return false;
      }
    }
    return true;
  }
  return left == right;
}

int _chromaticSpatialModelsDeepHash(Object? value) {
  if (value is List)
    return Object.hashAll(value.map(_chromaticSpatialModelsDeepHash));
  if (value is Map) {
    final entries = value.entries.toList(growable: false)
      ..sort(
        (left, right) => left.key.toString().compareTo(right.key.toString()),
      );
    return Object.hashAll(
      entries.map(
        (entry) => Object.hash(
          _chromaticSpatialModelsDeepHash(entry.key),
          _chromaticSpatialModelsDeepHash(entry.value),
        ),
      ),
    );
  }
  return value.hashCode;
}

