/// A bounded, resumable, multi-provider HTTPS swarm for immutable model files.
///
/// The scheduler can fetch the same logical bytes from several independent
/// planes (the canonical full object, GitHub release parts, and approved runtime
/// mirrors). Chunks arrive out of order, but are committed to the staging file
/// only when the contiguous prefix advances. This provides parallel fetching
/// without holding model chunks in RAM or requiring unsafe random-write reopen
/// semantics.
final class NazaMultiplaneModelDownloader {
  NazaMultiplaneModelDownloader({
    required this.manifest,
    this.chunkBytes = 4 * 1024 * 1024,
    this.minConcurrency = 3,
    this.maxConcurrency = 8,
    this.requestTimeout = const Duration(seconds: 35),
    this.connectionTimeout = const Duration(seconds: 12),
  }) : assert(chunkBytes >= 256 * 1024),
       assert(minConcurrency > 0),
       assert(maxConcurrency >= minConcurrency);

  final NazaModelDistributionManifest manifest;
  final int chunkBytes;
  final int minConcurrency;
  final int maxConcurrency;
  final Duration requestTimeout;
  final Duration connectionTimeout;

  final Map<String, HttpClient> _multiplaneModelDownloaderClients =
      <String, HttpClient>{};
  final Map<String, _MultiplaneModelDownloaderProviderState>
  _multiplaneModelDownloaderProviders =
      <String, _MultiplaneModelDownloaderProviderState>{};
  final Map<String, int> _multiplaneModelDownloaderProviderBytes =
      <String, int>{};
  final Map<int, int> _multiplaneModelDownloaderChunkAttempts = <int, int>{};
  bool _multiplaneModelDownloaderClosed = false;

  Future<NazaDownloadResult> download({
    required File target,
    NazaDownloadProgress? onProgress,
  }) async {
    if (_multiplaneModelDownloaderClosed) {
      throw const NazaModelDistributionException('Downloader is closed.');
    }

    final stopwatch = Stopwatch()..start();
    await target.parent.create(recursive: true);
    final topology = await _multiplaneModelDownloaderProbeTopology(onProgress);
    final layouts = topology.layouts;
    final totalBytes = topology.totalBytes;
    if (totalBytes <= 0 || totalBytes > 8 * 1024 * 1024 * 1024) {
      throw NazaModelDistributionException(
        'Invalid model size reported by providers: $totalBytes bytes.',
      );
    }

    final chunks = _multiplaneModelDownloaderBuildChunks(layouts);
    final partSizes = layouts.map((layout) => layout.length).toList();
    final fingerprint = manifest.fingerprintFor(
      totalBytes: totalBytes,
      partSizes: partSizes,
      chunkBytes: chunkBytes,
    );
    final staging = File('${target.path}.multiplane.part');
    final journal = File('${staging.path}.json');
    final spool = Directory('${staging.path}.chunks');
    final resume = await _multiplaneModelDownloaderPrepareResume(
      staging: staging,
      journal: journal,
      spool: spool,
      fingerprint: fingerprint,
      totalBytes: totalBytes,
      chunks: chunks,
    );

    onProgress?.call(
      NazaDownloadSnapshot(
        stage: NazaDownloadStage.allocating,
        receivedBytes: _multiplaneModelDownloaderPrefixBytes(
          chunks,
          resume.committedPrefixChunks,
        ),
        totalBytes: totalBytes,
        activeTransfers: 0,
        completedChunks:
            resume.committedPrefixChunks + resume.readyChunkIndexes.length,
        totalChunks: chunks.length,
        bytesPerSecond: 0,
        fastestProvider: null,
      ),
    );

    await _multiplaneModelDownloaderDownloadChunks(
      staging: staging,
      journal: journal,
      spool: spool,
      chunks: chunks,
      layouts: layouts,
      fingerprint: fingerprint,
      totalBytes: totalBytes,
      resume: resume,
      onProgress: onProgress,
    );

    onProgress?.call(
      NazaDownloadSnapshot(
        stage: NazaDownloadStage.verifying,
        receivedBytes: totalBytes,
        totalBytes: totalBytes,
        activeTransfers: 0,
        completedChunks: chunks.length,
        totalChunks: chunks.length,
        bytesPerSecond:
            totalBytes / math.max(0.001, stopwatch.elapsedMilliseconds / 1000),
        fastestProvider: _multiplaneModelDownloaderFastestProvider(),
      ),
    );

    final digest = await _multiplaneModelDownloaderSha256File(staging);
    final expected = manifest.expectedSha256.toLowerCase();
    if (digest != expected) {
      await _multiplaneModelDownloaderDiscardResume(staging, journal, spool);
      throw NazaModelDistributionException(
        'Final model SHA-256 mismatch. Expected $expected, got $digest.',
      );
    }

    final backup = File('${target.path}.previous');
    if (await backup.exists()) await backup.delete();
    var movedOld = false;
    try {
      if (await target.exists()) {
        await target.rename(backup.path);
        movedOld = true;
      }
      await staging.rename(target.path);
      if (movedOld && await backup.exists()) await backup.delete();
    } catch (_) {
      if (await staging.exists()) await staging.delete();
      if (movedOld && !await target.exists() && await backup.exists()) {
        await backup.rename(target.path);
      }
      rethrow;
    }
    if (await journal.exists()) await journal.delete();
    if (await spool.exists()) await spool.delete(recursive: true);
    stopwatch.stop();

    onProgress?.call(
      NazaDownloadSnapshot(
        stage: NazaDownloadStage.complete,
        receivedBytes: totalBytes,
        totalBytes: totalBytes,
        activeTransfers: 0,
        completedChunks: chunks.length,
        totalChunks: chunks.length,
        bytesPerSecond:
            totalBytes / math.max(0.001, stopwatch.elapsedMilliseconds / 1000),
        fastestProvider: _multiplaneModelDownloaderFastestProvider(),
      ),
    );

    return NazaDownloadResult(
      file: target,
      sha256: digest,
      totalBytes: totalBytes,
      elapsed: stopwatch.elapsed,
      providerBytes: Map<String, int>.unmodifiable(
        _multiplaneModelDownloaderProviderBytes,
      ),
    );
  }

  Future<({List<_MultiplaneModelDownloaderPartLayout> layouts, int totalBytes})>
  _multiplaneModelDownloaderProbeTopology(
    NazaDownloadProgress? onProgress,
  ) async {
    onProgress?.call(
      const NazaDownloadSnapshot(
        stage: NazaDownloadStage.probing,
        receivedBytes: 0,
        totalBytes: 0,
        activeTransfers: 0,
        completedChunks: 0,
        totalChunks: 0,
        bytesPerSecond: 0,
        fastestProvider: null,
      ),
    );

    for (final source in manifest.fullSources) {
      _multiplaneModelDownloaderProviders.putIfAbsent(
        source.id,
        () => _MultiplaneModelDownloaderProviderState(source),
      );
    }
    for (final part in manifest.parts) {
      for (final source in part.sources) {
        _multiplaneModelDownloaderProviders.putIfAbsent(
          source.id,
          () => _MultiplaneModelDownloaderProviderState(source),
        );
      }
    }

    final partLengths = <int>[];
    for (final part in manifest.parts) {
      int? found;
      final ordered = List<NazaDistributionSource>.from(part.sources)
        ..sort((a, b) => b.trustWeight.compareTo(a.trustWeight));
      for (final source in ordered) {
        try {
          final length = await _multiplaneModelDownloaderProbeLength(
            source.uri,
          );
          if (length > 0) {
            found = length;
            break;
          }
        } catch (_) {
          _multiplaneModelDownloaderProviders[source.id]?.failure();
        }
      }
      if (found == null) {
        throw NazaModelDistributionException(
          'No provider reported a usable size for ${part.name}.',
        );
      }
      partLengths.add(found);
    }

    var offset = 0;
    final layouts = <_MultiplaneModelDownloaderPartLayout>[];
    for (var i = 0; i < partLengths.length; i++) {
      layouts.add(
        _MultiplaneModelDownloaderPartLayout(
          partIndex: i,
          start: offset,
          length: partLengths[i],
        ),
      );
      offset += partLengths[i];
    }

    for (final source in manifest.fullSources) {
      try {
        final full = await _multiplaneModelDownloaderProbeLength(source.uri);
        if (full > 0 && full != offset) {
          throw NazaModelDistributionException(
            'Distribution topology mismatch: parts total $offset bytes but '
            '${source.id} reports $full bytes.',
          );
        }
        break;
      } on NazaModelDistributionException {
        rethrow;
      } catch (_) {
        _multiplaneModelDownloaderProviders[source.id]?.failure();
      }
    }

    return (layouts: layouts, totalBytes: offset);
  }

  Future<int> _multiplaneModelDownloaderProbeLength(Uri uri) async {
    _multiplaneModelDownloaderValidateUri(uri);
    try {
      final response = await _multiplaneModelDownloaderOpenApproved(
        'HEAD',
        uri,
      );
      try {
        if (response.statusCode >= 200 && response.statusCode < 400) {
          if (response.contentLength > 0) return response.contentLength;
          final raw = response.headers.value(HttpHeaders.contentLengthHeader);
          final parsed = int.tryParse(raw ?? '');
          if (parsed != null && parsed > 0) return parsed;
        }
      } finally {
        await response.drain<void>();
      }
    } catch (_) {}

    final response = await _multiplaneModelDownloaderOpenApproved(
      'GET',
      uri,
      configure: (request) {
        request.headers.set(HttpHeaders.rangeHeader, 'bytes=0-0');
        request.headers.set(HttpHeaders.acceptEncodingHeader, 'identity');
      },
    );
    try {
      if (response.statusCode != HttpStatus.partialContent &&
          response.statusCode != HttpStatus.ok) {
        throw HttpException(
          'Probe failed with HTTP ${response.statusCode}.',
          uri: uri,
        );
      }
      final range = response.headers.value(HttpHeaders.contentRangeHeader);
      if (range != null) {
        final match = RegExp(r'/([0-9]+)$').firstMatch(range.trim());
        final parsed = int.tryParse(match?.group(1) ?? '');
        if (parsed != null && parsed > 0) return parsed;
      }
      if (response.statusCode == HttpStatus.ok && response.contentLength > 0) {
        return response.contentLength;
      }
      throw HttpException('Provider did not expose object length.', uri: uri);
    } finally {
      await response.drain<void>();
    }
  }

  List<_MultiplaneModelDownloaderChunk> _multiplaneModelDownloaderBuildChunks(
    List<_MultiplaneModelDownloaderPartLayout> layouts,
  ) {
    final chunks = <_MultiplaneModelDownloaderChunk>[];
    var index = 0;
    for (final layout in layouts) {
      for (
        var partOffset = 0;
        partOffset < layout.length;
        partOffset += chunkBytes
      ) {
        final length = math.min(chunkBytes, layout.length - partOffset);
        chunks.add(
          _MultiplaneModelDownloaderChunk(
            index: index++,
            partIndex: layout.partIndex,
            fileOffset: layout.start + partOffset,
            partOffset: partOffset,
            length: length,
          ),
        );
      }
    }
    return chunks;
  }

  Future<_MultiplaneModelDownloaderResumeState>
  _multiplaneModelDownloaderPrepareResume({
    required File staging,
    required File journal,
    required Directory spool,
    required String fingerprint,
    required int totalBytes,
    required List<_MultiplaneModelDownloaderChunk> chunks,
  }) async {
    await spool.create(recursive: true);
    var committedPrefix = 0;
    var valid = false;

    if (await staging.exists() && await journal.exists()) {
      final decoded = _MultiplaneModelDownloaderResumeJournal.decode(
        await journal.readAsString(),
      );
      if (decoded != null &&
          decoded.fingerprint == fingerprint &&
          decoded.totalBytes == totalBytes &&
          decoded.chunkBytes == chunkBytes &&
          decoded.committedPrefixChunks >= 0 &&
          decoded.committedPrefixChunks <= chunks.length) {
        final expectedLength = _multiplaneModelDownloaderPrefixBytes(
          chunks,
          decoded.committedPrefixChunks,
        );
        final actualLength = await staging.length();
        if (actualLength == expectedLength) {
          committedPrefix = decoded.committedPrefixChunks;
          valid = true;
        }
      }
    }

    if (!valid) {
      await _multiplaneModelDownloaderDiscardResume(staging, journal, spool);
      await staging.create(recursive: true);
      await spool.create(recursive: true);
      committedPrefix = 0;
    }

    final ready = <int>{};
    for (var i = committedPrefix; i < chunks.length; i++) {
      final file = _multiplaneModelDownloaderChunkFile(spool, i);
      if (!await file.exists()) continue;
      if (await file.length() == chunks[i].length) {
        ready.add(i);
      } else {
        await file.delete();
      }
    }

    return _MultiplaneModelDownloaderResumeState(
      committedPrefixChunks: committedPrefix,
      readyChunkIndexes: ready,
    );
  }

  Future<void> _multiplaneModelDownloaderDownloadChunks({
    required File staging,
    required File journal,
    required Directory spool,
    required List<_MultiplaneModelDownloaderChunk> chunks,
    required List<_MultiplaneModelDownloaderPartLayout> layouts,
    required String fingerprint,
    required int totalBytes,
    required _MultiplaneModelDownloaderResumeState resume,
    required NazaDownloadProgress? onProgress,
  }) async {
    var committedPrefix = resume.committedPrefixChunks;
    final ready = Set<int>.from(resume.readyChunkIndexes);
    final pending = Queue<_MultiplaneModelDownloaderChunk>.from(
      chunks.where(
        (chunk) =>
            chunk.index >= committedPrefix && !ready.contains(chunk.index),
      ),
    );
    final active = <int, Future<_MultiplaneModelDownloaderTransferResult>>{};
    var targetConcurrency = math.min(
      maxConcurrency,
      math.max(minConcurrency, 4),
    );
    var networkReceived = _multiplaneModelDownloaderReadyBytes(chunks, ready);
    final started = Stopwatch()..start();
    final sink = staging.openWrite(mode: FileMode.writeOnlyAppend);

    Future<void> persist() async {
      final encoded = jsonEncode(
        _MultiplaneModelDownloaderResumeJournal(
          fingerprint: fingerprint,
          totalBytes: totalBytes,
          chunkBytes: chunkBytes,
          committedPrefixChunks: committedPrefix,
        ).toJson(),
      );
      final temp = File('${journal.path}.tmp');
      await temp.writeAsString(encoded, flush: true);
      await temp.rename(journal.path);
    }

    Future<void> commitContiguous() async {
      var advanced = false;
      while (committedPrefix < chunks.length) {
        final chunk = chunks[committedPrefix];
        final file = _multiplaneModelDownloaderChunkFile(spool, chunk.index);
        if (!ready.contains(chunk.index) || !await file.exists()) break;
        if (await file.length() != chunk.length) {
          ready.remove(chunk.index);
          await file.delete();
          pending.addFirst(chunk);
          break;
        }
        await sink.addStream(file.openRead());
        ready.remove(chunk.index);
        await file.delete();
        committedPrefix++;
        advanced = true;
      }
      if (advanced) {
        await sink.flush();
        await persist();
      }
    }

    int deliveredBytes() =>
        _multiplaneModelDownloaderPrefixBytes(chunks, committedPrefix) +
        _multiplaneModelDownloaderReadyBytes(chunks, ready);

    void publish() {
      onProgress?.call(
        NazaDownloadSnapshot(
          stage: NazaDownloadStage.downloading,
          receivedBytes: deliveredBytes().clamp(0, totalBytes),
          totalBytes: totalBytes,
          activeTransfers: active.length,
          completedChunks: committedPrefix + ready.length,
          totalChunks: chunks.length,
          bytesPerSecond:
              networkReceived /
              math.max(0.001, started.elapsedMilliseconds / 1000),
          fastestProvider: _multiplaneModelDownloaderFastestProvider(),
        ),
      );
    }

    try {
      await commitContiguous();
      while (committedPrefix < chunks.length) {
        while (active.length < targetConcurrency && pending.isNotEmpty) {
          final chunk = pending.removeFirst();
          active[chunk.index] = _multiplaneModelDownloaderDownloadChunkToSpool(
            chunk: chunk,
            layouts: layouts,
            file: _multiplaneModelDownloaderChunkFile(spool, chunk.index),
          );
        }

        if (active.isEmpty) {
          await Future<void>.delayed(const Duration(milliseconds: 120));
          for (var i = committedPrefix; i < chunks.length; i++) {
            if (!ready.contains(i) &&
                !active.containsKey(i) &&
                !pending.any((chunk) => chunk.index == i)) {
              pending.add(chunks[i]);
            }
          }
          continue;
        }

        publish();
        final result = await Future.any(active.values);
        active.remove(result.chunk.index);
        if (result.ok) {
          ready.add(result.chunk.index);
          networkReceived += result.chunk.length;
          _multiplaneModelDownloaderProviderBytes.update(
            result.provider!.source.id,
            (value) => value + result.chunk.length,
            ifAbsent: () => result.chunk.length,
          );
          _multiplaneModelDownloaderChunkAttempts.remove(result.chunk.index);
          await commitContiguous();
          if ((committedPrefix + ready.length) % 16 == 0 &&
              targetConcurrency < maxConcurrency) {
            targetConcurrency++;
          }
        } else {
          final attempts = _multiplaneModelDownloaderChunkAttempts.update(
            result.chunk.index,
            (value) => value + 1,
            ifAbsent: () => 1,
          );
          if (await result.file.exists()) await result.file.delete();
          if (attempts > 3) {
            Error.throwWithStackTrace(
              result.error ??
                  NazaModelDistributionException(
                    'Chunk ${result.chunk.index} exhausted all providers.',
                  ),
              result.stackTrace ?? StackTrace.current,
            );
          }
          pending.addLast(result.chunk);
          targetConcurrency = math.max(minConcurrency, targetConcurrency - 1);
        }
        publish();
      }
      await sink.flush();
      await persist();
    } finally {
      await sink.close();
    }

    final stagingLength = await staging.length();
    if (committedPrefix != chunks.length || stagingLength != totalBytes) {
      throw NazaModelDistributionException(
        'Download assembly incomplete: $committedPrefix/${chunks.length} '
        'chunks, $stagingLength/$totalBytes bytes.',
      );
    }
  }

  Future<_MultiplaneModelDownloaderTransferResult>
  _multiplaneModelDownloaderDownloadChunkToSpool({
    required _MultiplaneModelDownloaderChunk chunk,
    required List<_MultiplaneModelDownloaderPartLayout> layouts,
    required File file,
  }) async {
    try {
      final provider = await _multiplaneModelDownloaderFetchChunk(
        chunk,
        layouts,
        file,
      );
      return _MultiplaneModelDownloaderTransferResult(
        chunk: chunk,
        file: file,
        provider: provider,
      );
    } catch (error, stack) {
      return _MultiplaneModelDownloaderTransferResult(
        chunk: chunk,
        file: file,
        provider: null,
        error: error,
        stackTrace: stack,
      );
    }
  }

  Future<_MultiplaneModelDownloaderProviderState>
  _multiplaneModelDownloaderFetchChunk(
    _MultiplaneModelDownloaderChunk chunk,
    List<_MultiplaneModelDownloaderPartLayout> layouts,
    File output,
  ) async {
    final candidates = <_MultiplaneModelDownloaderProviderState>[];
    for (final source in manifest.fullSources) {
      final state = _multiplaneModelDownloaderProviders[source.id]!;
      if (state.available) candidates.add(state);
    }
    for (final source in manifest.parts[chunk.partIndex].sources) {
      final state = _multiplaneModelDownloaderProviders[source.id]!;
      if (state.available) candidates.add(state);
    }

    if (candidates.isEmpty) {
      final waits = _multiplaneModelDownloaderProviders.values
          .map((state) => state.backoffUntil)
          .whereType<DateTime>()
          .map((time) => time.difference(DateTime.now()))
          .where((duration) => duration > Duration.zero)
          .toList();
      if (waits.isNotEmpty) {
        waits.sort();
        await Future<void>.delayed(
          waits.first > const Duration(seconds: 2)
              ? const Duration(seconds: 2)
              : waits.first,
        );
      }
      return _multiplaneModelDownloaderFetchChunk(chunk, layouts, output);
    }

    candidates.sort((a, b) => b.effectiveScore.compareTo(a.effectiveScore));
    Object? lastError;
    for (final provider in candidates.take(math.min(6, candidates.length))) {
      provider.inFlight++;
      final watch = Stopwatch()..start();
      try {
        final absolute = provider.source.isFullObject;
        final start = absolute ? chunk.fileOffset : chunk.partOffset;
        final end = absolute ? chunk.fileEndInclusive : chunk.partEndInclusive;
        await _multiplaneModelDownloaderRangeGetToFile(
          uri: provider.source.uri,
          start: start,
          end: end,
          output: output,
        );
        watch.stop();
        provider.success(chunk.length, watch.elapsed);
        return provider;
      } catch (error) {
        watch.stop();
        lastError = error;
        provider.failure();
        if (await output.exists()) await output.delete();
      } finally {
        provider.inFlight--;
      }
    }

    throw NazaModelDistributionException(
      'All providers failed for chunk ${chunk.index}: $lastError',
    );
  }

  Future<void> _multiplaneModelDownloaderRangeGetToFile({
    required Uri uri,
    required int start,
    required int end,
    required File output,
  }) async {
    _multiplaneModelDownloaderValidateUri(uri);
    final response = await _multiplaneModelDownloaderOpenApproved(
      'GET',
      uri,
      configure: (request) {
        request.headers.set(HttpHeaders.rangeHeader, 'bytes=$start-$end');
        request.headers.set(HttpHeaders.acceptEncodingHeader, 'identity');
      },
    );
    final expected = end - start + 1;

    if (response.statusCode != HttpStatus.partialContent &&
        !(start == 0 &&
            response.statusCode == HttpStatus.ok &&
            response.contentLength == expected)) {
      await response.drain<void>();
      throw HttpException(
        'Range request failed with HTTP ${response.statusCode}.',
        uri: uri,
      );
    }

    final sink = output.openWrite(mode: FileMode.writeOnly);
    var received = 0;
    try {
      await for (final frame in response.timeout(requestTimeout)) {
        received += frame.length;
        if (received > expected) {
          throw NazaModelDistributionException(
            'Provider exceeded requested range ($received > $expected).',
          );
        }
        sink.add(frame);
      }
      await sink.flush();
    } finally {
      await sink.close();
    }
    if (received != expected || await output.length() != expected) {
      throw NazaModelDistributionException(
        'Provider ended range at $received of $expected bytes.',
      );
    }
  }

  Future<HttpClientResponse> _multiplaneModelDownloaderOpenApproved(
    String method,
    Uri initial, {
    void Function(HttpClientRequest request)? configure,
  }) async {
    var current = initial;
    final visited = <String>{};
    for (var redirects = 0; redirects <= 5; redirects++) {
      _multiplaneModelDownloaderValidateUri(current);
      if (!visited.add(current.toString())) {
        throw NazaModelDistributionException(
          'Model source redirect loop detected at $current.',
        );
      }
      final request = await _multiplaneModelDownloaderClientFor(
        current,
      ).openUrl(method, current).timeout(requestTimeout);
      request.followRedirects = false;
      configure?.call(request);
      final response = await request.close().timeout(requestTimeout);
      if (!response.isRedirect) return response;
      final location = response.headers.value(HttpHeaders.locationHeader);
      await response.drain<void>().timeout(requestTimeout);
      if (redirects == 5 || location == null) {
        throw NazaModelDistributionException(
          'Model source exceeded the approved redirect limit at $current.',
        );
      }
      final parsed = Uri.tryParse(location);
      if (parsed == null) {
        throw NazaModelDistributionException(
          'Model source returned a malformed redirect from $current.',
        );
      }
      current = current.resolveUri(parsed);
    }
    throw const NazaModelDistributionException(
      'Model source redirect validation failed.',
    );
  }

  HttpClient _multiplaneModelDownloaderClientFor(Uri uri) {
    final key = '${uri.scheme}://${uri.host}:${uri.hasPort ? uri.port : 443}';
    return _multiplaneModelDownloaderClients.putIfAbsent(key, () {
      final client = HttpClient()
        ..connectionTimeout = connectionTimeout
        ..idleTimeout = const Duration(seconds: 20)
        ..maxConnectionsPerHost = 3
        ..autoUncompress = false;
      client.userAgent = 'NAZA-One/1 model-distribution-v2';
      return client;
    });
  }

  static void _multiplaneModelDownloaderValidateUri(Uri uri) {
    if (!nazaIsApprovedModelTransportUri(uri)) {
      throw NazaModelDistributionException(
        'Model source is outside the approved HTTPS transport policy: $uri',
      );
    }
  }

  static File _multiplaneModelDownloaderChunkFile(Directory spool, int index) =>
      File('${spool.path}/chunk_${index.toString().padLeft(6, '0')}.bin');

  static int _multiplaneModelDownloaderPrefixBytes(
    List<_MultiplaneModelDownloaderChunk> chunks,
    int prefixChunks,
  ) {
    var total = 0;
    for (var i = 0; i < math.min(prefixChunks, chunks.length); i++) {
      total += chunks[i].length;
    }
    return total;
  }

  static int _multiplaneModelDownloaderReadyBytes(
    List<_MultiplaneModelDownloaderChunk> chunks,
    Set<int> ready,
  ) {
    var total = 0;
    for (final index in ready) {
      if (index >= 0 && index < chunks.length) total += chunks[index].length;
    }
    return total;
  }

  String? _multiplaneModelDownloaderFastestProvider() {
    final states = _multiplaneModelDownloaderProviders.values
        .where((state) => state.ewmaBps > 0)
        .toList(growable: false);
    if (states.isEmpty) return null;
    states.sort((a, b) => b.ewmaBps.compareTo(a.ewmaBps));
    return states.first.source.id;
  }

  static Future<String> _multiplaneModelDownloaderSha256File(File file) async {
    final digest = await crypto.sha256.bind(file.openRead()).first;
    return digest.toString().toLowerCase();
  }

  static Future<void> _multiplaneModelDownloaderDiscardResume(
    File staging,
    File journal,
    Directory spool,
  ) async {
    if (await staging.exists()) await staging.delete();
    if (await journal.exists()) await journal.delete();
    if (await spool.exists()) await spool.delete(recursive: true);
  }

  Future<void> close() async {
    if (_multiplaneModelDownloaderClosed) return;
    _multiplaneModelDownloaderClosed = true;
    for (final client in _multiplaneModelDownloaderClients.values) {
      client.close(force: true);
    }
    _multiplaneModelDownloaderClients.clear();
  }
}

