enum NazaOpenAiReasoningEffort {
  light('low', 'Light'),
  medium('medium', 'Medium'),
  high('high', 'High'),
  extraHigh('xhigh', 'Extra high'),
  maximum('max', 'Maximum');

  const NazaOpenAiReasoningEffort(this.wireName, this.label);
  final String wireName;
  final String label;

  static NazaOpenAiReasoningEffort fromWire(Object? value) =>
      values.firstWhere(
        (effort) => effort.wireName == value,
        orElse: () => light,
      );
}

final class NazaRemoteModelProfile {
  final String id;
  final NazaRemoteProvider provider;
  final String displayName;
  final String model;
  final String endpoint;
  final String apiKey;
  final NazaOpenAiReasoningEffort reasoningEffort;
  final bool enabled;
  final bool allowCustomEndpoint;

  const NazaRemoteModelProfile({
    required this.id,
    required this.provider,
    required this.displayName,
    required this.model,
    required this.endpoint,
    required this.apiKey,
    this.reasoningEffort = NazaOpenAiReasoningEffort.light,
    this.enabled = true,
    this.allowCustomEndpoint = false,
  });

  NazaRemoteModelProfile copyWith({
    String? displayName,
    String? model,
    String? endpoint,
    String? apiKey,
    NazaOpenAiReasoningEffort? reasoningEffort,
    bool? enabled,
    bool? allowCustomEndpoint,
  }) => NazaRemoteModelProfile(
    id: id,
    provider: provider,
    displayName: displayName ?? this.displayName,
    model: model ?? this.model,
    endpoint: endpoint ?? this.endpoint,
    apiKey: apiKey ?? this.apiKey,
    reasoningEffort: reasoningEffort ?? this.reasoningEffort,
    enabled: enabled ?? this.enabled,
    allowCustomEndpoint: allowCustomEndpoint ?? this.allowCustomEndpoint,
  );

  Map<String, Object?> toJson() => <String, Object?>{
    'id': id,
    'provider': provider.wireName,
    'displayName': displayName,
    'model': model,
    'endpoint': endpoint,
    // This object is written only through NazaSecureDatabase.
    'apiKey': apiKey,
    'reasoningEffort': reasoningEffort.wireName,
    'enabled': enabled,
    'allowCustomEndpoint': allowCustomEndpoint,
  };

  static NazaRemoteModelProfile? fromJson(Object? value) {
    if (value is! Map) return null;
    final providerName = value['provider']?.toString();
    final provider = NazaRemoteProvider.values.where(
      (p) => p.name == providerName,
    );
    final id = value['id']?.toString().trim() ?? '';
    final model = value['model']?.toString().trim() ?? '';
    final endpoint = value['endpoint']?.toString().trim() ?? '';
    if (id.isEmpty || model.isEmpty || endpoint.isEmpty || provider.isEmpty)
      return null;
    final profile = NazaRemoteModelProfile(
      id: id,
      provider: provider.first,
      displayName: NazaBoundarySanitizer.databaseText(
        value['displayName']?.toString().trim().isNotEmpty == true
            ? value['displayName'].toString()
            : model,
        maxCharacters: 120,
      ),
      model: model,
      endpoint: endpoint,
      apiKey: value['apiKey']?.toString() ?? '',
      reasoningEffort: NazaOpenAiReasoningEffort.fromWire(value['reasoningEffort']),
      enabled: value['enabled'] != false,
      allowCustomEndpoint: value['allowCustomEndpoint'] == true,
    );
    try {
      NazaRemoteModelCatalog._providerGatewayValidateProfile(profile);
      return profile;
    } on FormatException {
      return null;
    }
  }
}

final class NazaRemoteModelCatalog {
  static const int maxProfiles = 32;
  static const int maxModelIdLength = 160;
  static const String _providerGatewayNamespace = 'remote-model-providers';
  static const String _providerGatewayKey = 'profiles-v1';

  NazaRemoteModelCatalog({NazaSecureDatabase? database})
    : _providerGatewayDatabase = database ?? NazaSecureDatabase.instance;
  final NazaSecureDatabase _providerGatewayDatabase;

  Future<List<NazaRemoteModelProfile>> load() async {
    final raw = await _providerGatewayDatabase.readJson(
      _providerGatewayNamespace,
      _providerGatewayKey,
    );
    if (raw is! List) return <NazaRemoteModelProfile>[];
    return raw
        .map(NazaRemoteModelProfile.fromJson)
        .whereType<NazaRemoteModelProfile>()
        .take(maxProfiles)
        .toList(growable: false);
  }

  Future<void> save(Iterable<NazaRemoteModelProfile> profiles) async {
    final bounded = profiles
        .take(maxProfiles)
        .map((profile) {
          _providerGatewayValidateProfile(profile);
          return profile
              .copyWith(
                displayName: NazaBoundarySanitizer.databaseText(
                  profile.displayName,
                  maxCharacters: 120,
                ),
                model: profile.model.trim(),
                endpoint: profile.endpoint.trim(),
              )
              .toJson();
        })
        .toList(growable: false);
    await _providerGatewayDatabase.writeJson(
      _providerGatewayNamespace,
      _providerGatewayKey,
      bounded,
    );
  }

  Future<void> upsert(NazaRemoteModelProfile profile) async {
    final profiles = await load();
    final next = <NazaRemoteModelProfile>[
      for (final item in profiles)
        if (item.id != profile.id) item,
      profile,
    ];
    await save(next);
  }

  Future<void> remove(String id) async {
    final profiles = await load();
    await save(profiles.where((profile) => profile.id != id));
  }

  static void _providerGatewayValidateProfile(NazaRemoteModelProfile profile) {
    if (!RegExp(
      r'^[A-Za-z0-9][A-Za-z0-9._-]{0,99}$',
    ).hasMatch(profile.id.trim())) {
      throw const FormatException('Invalid remote model profile id.');
    }
    if (profile.model.trim().isEmpty ||
        profile.model.length > maxModelIdLength ||
        !RegExp(
          r'^[A-Za-z0-9][A-Za-z0-9._:/-]{0,159}$',
        ).hasMatch(profile.model.trim())) {
      throw const FormatException('Invalid remote model identifier.');
    }
    if (profile.apiKey.trim().length < 8 ||
        profile.apiKey.length > 4096 ||
        profile.apiKey.contains(RegExp(r'[\u0000-\u001f\u007f]'))) {
      throw const FormatException('Remote model profile has no API key.');
    }
    NazaProviderGateway.validateEndpoint(
      provider: profile.provider,
      endpoint: profile.endpoint,
      allowCustomEndpoint: profile.allowCustomEndpoint,
    );
  }
}

final class NazaRemoteModelResponse {
  final String text;
  final String provider;
  final String model;
  const NazaRemoteModelResponse({
    required this.text,
    required this.provider,
    required this.model,
  });
}

/// One bounded adapter for all supported remote request shapes.
final class NazaProviderGateway {
  NazaProviderGateway({http.Client? client})
    : _providerGatewayClient = client ?? http.Client();
  final http.Client _providerGatewayClient;

  static const int maxPromptCharacters = 120000;
  static const int maxResponseBytes = 8 * 1024 * 1024;

  Future<NazaRemoteModelResponse> send({
    required NazaRemoteModelProfile profile,
    required String prompt,
    String? systemInstruction,
  }) async {
    NazaRemoteModelCatalog._providerGatewayValidateProfile(profile);
    if (prompt.length > maxPromptCharacters) {
      throw const FormatException(
        'Prompt is empty or exceeds the remote limit.',
      );
    }
    final cleanPrompt = NazaBoundarySanitizer.redactExactSecrets(
      NazaBoundarySanitizer.modelInput(
        prompt,
        maxCharacters: maxPromptCharacters,
        redactSecrets: true,
      ),
      <String>[profile.apiKey],
    );
    final cleanSystem = systemInstruction == null
        ? null
        : NazaBoundarySanitizer.redactExactSecrets(
            NazaBoundarySanitizer.modelInput(
              systemInstruction,
              maxCharacters: 24000,
              redactSecrets: true,
            ),
            <String>[profile.apiKey],
          );
    final uri = Uri.parse(profile.endpoint);
    final headers = <String, String>{'content-type': 'application/json'};
    final body = switch (profile.provider) {
      NazaRemoteProvider.anthropic => _providerGatewayAnthropicBody(
        profile,
        cleanPrompt,
        cleanSystem,
      ),
      NazaRemoteProvider.gemini => _providerGatewayGeminiBody(
        profile,
        cleanPrompt,
        cleanSystem,
      ),
      _ => _providerGatewayOpenAiBody(profile, cleanPrompt, cleanSystem),
    };
    if (profile.provider == NazaRemoteProvider.gemini) {
      headers['x-goog-api-key'] = profile.apiKey;
    } else if (profile.provider == NazaRemoteProvider.anthropic) {
      headers['x-api-key'] = profile.apiKey;
      headers['anthropic-version'] = '2023-06-01';
    } else {
      headers['authorization'] = 'Bearer ${profile.apiKey}';
    }
    final encodedBody = jsonEncode(body);
    if (encodedBody.contains(profile.apiKey)) {
      throw const FormatException(
        'A configured credential was detected in the model request body.',
      );
    }
    final request = http.Request('POST', uri)
      ..followRedirects = false
      ..headers.addAll(headers)
      ..body = encodedBody;
    final responseBytes = await _providerGatewaySendBounded(
      request,
    ).timeout(const Duration(seconds: 45));
    final decoded = jsonDecode(
      utf8.decode(responseBytes, allowMalformed: false),
    );
    final text = NazaBoundarySanitizer.redactExactSecrets(
      NazaBoundarySanitizer.remoteText(
        _providerGatewayExtractText(profile.provider, decoded),
        maxCharacters: maxResponseBytes,
      ),
      <String>[profile.apiKey],
    );
    if (text.isEmpty)
      throw const FormatException('Remote provider returned no text.');
    return NazaRemoteModelResponse(
      text: text,
      provider: profile.provider.label,
      model: profile.model,
    );
  }

  static void validateEndpoint({
    required NazaRemoteProvider provider,
    required String endpoint,
    required bool allowCustomEndpoint,
  }) {
    if (allowCustomEndpoint && provider != NazaRemoteProvider.custom) {
      throw const FormatException(
        'Only the Custom provider may use a custom endpoint.',
      );
    }
    final uri = Uri.tryParse(endpoint.trim());
    if (uri == null ||
        uri.scheme != 'https' ||
        uri.host.isEmpty ||
        uri.userInfo.isNotEmpty ||
        uri.fragment.isNotEmpty ||
        uri.hasQuery) {
      throw const FormatException(
        'Remote model endpoints must use HTTPS without credentials or query parameters.',
      );
    }
    final allowed = switch (provider) {
      NazaRemoteProvider.openAi => <String>{'api.openai.com'},
      NazaRemoteProvider.anthropic => <String>{'api.anthropic.com'},
      NazaRemoteProvider.gemini => <String>{
        'generativelanguage.googleapis.com',
      },
      NazaRemoteProvider.digitalOcean => <String>{
        'inference.do-ai.run',
        'api.digitalocean.com',
      },
      NazaRemoteProvider.meta => <String>{'api.meta.ai'},
      NazaRemoteProvider.custom => <String>{},
    };
    if (!allowCustomEndpoint && !allowed.contains(uri.host.toLowerCase())) {
      throw const FormatException(
        'This provider requires its official HTTPS origin.',
      );
    }
    if (!allowCustomEndpoint && uri.hasPort && uri.port != 443) {
      throw const FormatException(
        'Official provider endpoints must use HTTPS port 443.',
      );
    }
  }

  Future<Uint8List> _providerGatewaySendBounded(http.Request request) async {
    final response = await _providerGatewayClient.send(request);
    if (response.statusCode >= 300 && response.statusCode < 400) {
      throw HttpException(
        'Remote provider redirects are not allowed (HTTP ${response.statusCode}).',
      );
    }
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw HttpException(
        'Remote provider returned HTTP ${response.statusCode}.',
      );
    }
    final declaredLength = response.contentLength;
    if (declaredLength != null && declaredLength > maxResponseBytes) {
      throw const FormatException('Remote response exceeds the safety limit.');
    }
    final builder = BytesBuilder(copy: false);
    var total = 0;
    await for (final chunk in response.stream) {
      if (chunk.length > maxResponseBytes - total) {
        throw const FormatException(
          'Remote response exceeds the safety limit.',
        );
      }
      total += chunk.length;
      builder.add(chunk);
    }
    return builder.takeBytes();
  }

  void close() => _providerGatewayClient.close();

  static Map<String, Object?> _providerGatewayOpenAiBody(
    NazaRemoteModelProfile p,
    String prompt,
    String? system,
  ) => <String, Object?>{
    'model': p.model,
    if (p.provider == NazaRemoteProvider.openAi &&
        (p.model == 'gpt-6-astra' || p.model.startsWith('gpt-6-astra-')))
      'reasoning_effort': p.reasoningEffort.wireName,
    'messages': <Object?>[
      if (system?.trim().isNotEmpty == true)
        <String, String>{'role': 'system', 'content': system!.trim()},
      <String, String>{'role': 'user', 'content': prompt},
    ],
  };

  static Map<String, Object?> _providerGatewayAnthropicBody(
    NazaRemoteModelProfile p,
    String prompt,
    String? system,
  ) => <String, Object?>{
    'model': p.model,
    'max_tokens': 4096,
    if (system?.trim().isNotEmpty == true) 'system': system!.trim(),
    'messages': <Object?>[
      <String, String>{'role': 'user', 'content': prompt},
    ],
  };

  static Map<String, Object?> _providerGatewayGeminiBody(
    NazaRemoteModelProfile p,
    String prompt,
    String? system,
  ) => <String, Object?>{
    'contents': <Object?>[
      <String, Object?>{
        'role': 'user',
        'parts': <Object?>[
          <String, String>{'text': '${system ?? ''}\n$prompt'},
        ],
      },
    ],
  };

  static String _providerGatewayExtractText(
    NazaRemoteProvider provider,
    Object? value,
  ) {
    if (value is! Map) return '';
    if (provider == NazaRemoteProvider.anthropic) {
      final content = value['content'];
      if (content is List && content.isNotEmpty && content.first is Map)
        return (content.first as Map)['text']?.toString() ?? '';
    }
    if (provider == NazaRemoteProvider.gemini) {
      final candidates = value['candidates'];
      if (candidates is List && candidates.isNotEmpty) {
        final parts = (candidates.first as Map?)?['content'];
        if (parts is Map && parts['parts'] is List)
          return (parts['parts'] as List)
              .map((part) => (part as Map?)?['text'] ?? '')
              .join();
      }
    }
    final choices = value['choices'];
    if (choices is List && choices.isNotEmpty)
      return ((choices.first as Map?)?['message'] as Map?)?['content']
              ?.toString() ??
          '';
    return '';
  }
}

