// DOMAIN: navigation
// SECURITY-INVARIANT: Resolve navigation only through the closed in-process destination registry; persisted IDs never carry callbacks.
// CHANGE-GUARD: Preserve public contracts, bounded inputs, lifecycle cleanup, and fail-closed behavior; run analysis and relevant tests after edits.
// DOCS: See /docs/llm-context-schema.md and the nearest mermaid.md architecture map.
// LLM-CONTEXT:END

bool _unifiedFeatureDrawerSameDestinationIds(
  List<NazaFeatureDestination> a,
  List<NazaFeatureDestination> b,
) {
  if (a.length != b.length) return false;
  for (var index = 0; index < a.length; index++) {
    if (a[index].id != b[index].id) return false;
  }
  return true;
}

/// A closed, in-process navigation target. Persisted data contains IDs only;
/// callbacks and labels always come from this trusted registry.
final class NazaFeatureDestination {
  final String id;
  final String label;

  /// The editorial title shown in the expanded wheel. Keep [label] short for
  /// compact rails and pinned icons, while [title] gives each app its own
  /// recognizable product identity.
  final String? title;
  final String? subzone;
  final String description;
  final String category;
  final IconData icon;
  final Color accent;
  final VoidCallback onOpen;

  const NazaFeatureDestination({
    required this.id,
    required this.label,
    this.title,
    this.subzone,
    required this.description,
    required this.category,
    required this.icon,
    required this.accent,
    required this.onOpen,
  });

  String get displayTitle => title ?? '$label $category Studio';
  String get displayZone => subzone ?? category;
}

final class NazaFeaturePinPolicy {
  static const String requiredId = 'chat';
  static const int maxPins = 20;
  static const List<String> defaults = <String>[
    requiredId,
    'road-scanner',
    'food-scanner',
    // Keep the BookForge workspaces reachable from the mobile feature strip.
    // These are separate destinations even though they share one workspace.
    'bookforge',
    'bookforge-generate',
    'bookforge-repository',
  ];

  const NazaFeaturePinPolicy._();

  static List<String> sanitize(Iterable<Object?> raw, Set<String> allowed) {
    final clean = <String>[requiredId];
    for (final value in raw) {
      if (value is! String ||
          value == requiredId ||
          !allowed.contains(value) ||
          clean.contains(value)) {
        continue;
      }
      clean.add(value);
      if (clean.length == maxPins) break;
    }
    return clean;
  }

  static List<String> initial(Set<String> allowed) =>
      sanitize(defaults, allowed);
}

final class NazaFeaturePinStore {
  static const _unifiedFeatureDrawerKey = 'naza.navigation.feature_pins.v1';

  const NazaFeaturePinStore();

  Future<List<String>> load(Set<String> allowed) async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getStringList(_unifiedFeatureDrawerKey);
      return raw == null
          ? NazaFeaturePinPolicy.initial(allowed)
          : NazaFeaturePinPolicy.sanitize(raw, allowed);
    } catch (_) {
      return NazaFeaturePinPolicy.initial(allowed);
    }
  }

  Future<bool> save(Iterable<String> ids, Set<String> allowed) async {
    final clean = NazaFeaturePinPolicy.sanitize(ids, allowed);
    try {
      final prefs = await SharedPreferences.getInstance();
      return await prefs.setStringList(_unifiedFeatureDrawerKey, clean);
    } catch (_) {
      return false;
    }
  }
}

/// The single mobile navigation entry point. The centered orbit control opens
/// every feature; pins are managed inside that same surface.
final class NazaUnifiedFeatureDrawer extends StatefulWidget {
  final List<NazaFeatureDestination> destinations;
  final String selectedId;
  final Color surface;
  final Color panel;
  final Color border;
  final Color text;
  final Color subtext;

  const NazaUnifiedFeatureDrawer({
    super.key,
    required this.destinations,
    required this.selectedId,
    required this.surface,
    required this.panel,
    required this.border,
    required this.text,
    required this.subtext,
  });

  @override
  State<NazaUnifiedFeatureDrawer> createState() =>
      _UnifiedFeatureDrawerNazaUnifiedFeatureDrawerState();
}

class _UnifiedFeatureDrawerNazaUnifiedFeatureDrawerState
    extends State<NazaUnifiedFeatureDrawer> {
  final NazaFeaturePinStore _unifiedFeatureDrawerStore =
      const NazaFeaturePinStore();
  List<String> _unifiedFeatureDrawerPins = NazaFeaturePinPolicy.defaults;
  bool _unifiedFeatureDrawerLoaded = false;
  bool _unifiedFeatureDrawerSaving = false;

  Set<String> get _unifiedFeatureDrawerAllowed =>
      widget.destinations.map((e) => e.id).toSet();

  @override
  void initState() {
    super.initState();
    unawaited(_unifiedFeatureDrawerLoad());
  }

  @override
  void didUpdateWidget(covariant NazaUnifiedFeatureDrawer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!_unifiedFeatureDrawerSameDestinationIds(
      oldWidget.destinations,
      widget.destinations,
    )) {
      final clean = NazaFeaturePinPolicy.sanitize(
        _unifiedFeatureDrawerPins,
        _unifiedFeatureDrawerAllowed,
      );
      if (!_unifiedFeatureDrawerSameIds(clean, _unifiedFeatureDrawerPins)) {
        _unifiedFeatureDrawerPins = clean;
        unawaited(
          _unifiedFeatureDrawerStore.save(clean, _unifiedFeatureDrawerAllowed),
        );
      }
    }
  }

  Future<void> _unifiedFeatureDrawerLoad() async {
    final pins = await _unifiedFeatureDrawerStore.load(
      _unifiedFeatureDrawerAllowed,
    );
    if (!mounted) return;
    setState(() {
      _unifiedFeatureDrawerPins = pins;
      _unifiedFeatureDrawerLoaded = true;
    });
  }

  Future<void> _unifiedFeatureDrawerTogglePin(String id) async {
    if (!_unifiedFeatureDrawerLoaded || _unifiedFeatureDrawerSaving) {
      if (!_unifiedFeatureDrawerLoaded) {
        _unifiedFeatureDrawerMessage('Loading your saved wheel settings…');
      }
      return;
    }
    _unifiedFeatureDrawerSaving = true;
    if (!_unifiedFeatureDrawerAllowed.contains(id)) return;
    if (id == NazaFeaturePinPolicy.requiredId) {
      _unifiedFeatureDrawerMessage('Chat stays pinned in the center.');
      return;
    }
    final next = List<String>.from(_unifiedFeatureDrawerPins);
    if (next.remove(id)) {
      _unifiedFeatureDrawerMessage('Removed from your wheel.');
    } else {
      if (next.length >= NazaFeaturePinPolicy.maxPins) {
        _unifiedFeatureDrawerMessage(
          'Your wheel can hold up to ${NazaFeaturePinPolicy.maxPins} pins.',
        );
        return;
      }
      next.add(id);
      _unifiedFeatureDrawerMessage('Pinned to your wheel.');
    }
    final clean = NazaFeaturePinPolicy.sanitize(
      next,
      _unifiedFeatureDrawerAllowed,
    );
    final previous = List<String>.from(_unifiedFeatureDrawerPins);
    final saved = await _unifiedFeatureDrawerStore.save(
      clean,
      _unifiedFeatureDrawerAllowed,
    );
    _unifiedFeatureDrawerSaving = false;
    if (!mounted) return;
    if (saved) {
      setState(() => _unifiedFeatureDrawerPins = clean);
      _unifiedFeatureDrawerMessage(
        next.contains(id)
            ? 'Pinned to your wheel.'
            : 'Removed from your wheel.',
      );
    } else {
      setState(() => _unifiedFeatureDrawerPins = previous);
      _unifiedFeatureDrawerMessage(
        'Could not save wheel settings. Your previous pins were kept.',
      );
    }
  }

  void _unifiedFeatureDrawerMessage(String value) {
    final messenger = ScaffoldMessenger.maybeOf(context);
    messenger
      ?..hideCurrentSnackBar()
      ..showSnackBar(
        SnackBar(
          content: Text(value),
          behavior: SnackBarBehavior.floating,
          duration: const Duration(milliseconds: 1500),
        ),
      );
  }

  void _unifiedFeatureDrawerOpen(NazaFeatureDestination destination) {
    HapticFeedback.selectionClick();
    destination.onOpen();
  }

  NazaFeatureDestination? _unifiedFeatureDrawerById(String id) {
    for (final destination in widget.destinations) {
      if (destination.id == id) return destination;
    }
    return null;
  }

  Future<void> _unifiedFeatureDrawerShowDrawer() async {
    FocusManager.instance.primaryFocus?.unfocus();
    await showModalBottomSheet<void>(
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withValues(alpha: 0.58),
      builder: (sheetContext) => StatefulBuilder(
        builder: (context, setSheetState) =>
            _UnifiedFeatureDrawerFeatureWheelSheet(
              destinations: widget.destinations,
              pins: _unifiedFeatureDrawerPins,
              selectedId: widget.selectedId,
              surface: widget.surface,
              panel: widget.panel,
              border: widget.border,
              text: widget.text,
              subtext: widget.subtext,
              onOpen: (destination) {
                Navigator.of(sheetContext).pop();
                _unifiedFeatureDrawerOpen(destination);
              },
              onTogglePin: (id) async {
                await _unifiedFeatureDrawerTogglePin(id);
                if (sheetContext.mounted) setSheetState(() {});
              },
            ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final pinned = _unifiedFeatureDrawerPins
        .map(_unifiedFeatureDrawerById)
        .whereType<NazaFeatureDestination>()
        .toList(growable: false);
    final midpoint = (pinned.length + 1) ~/ 2;
    final leftPins = pinned.take(midpoint).toList(growable: false);
    final rightPins = pinned.skip(midpoint).toList(growable: false);
    return Semantics(
      container: true,
      label: 'Feature wheel navigation',
      child: Container(
        key: const ValueKey<String>('unified-feature-drawer'),
        height: 62,
        padding: const EdgeInsets.fromLTRB(8, 5, 8, 5),
        decoration: BoxDecoration(
          color: widget.surface,
          border: Border(top: BorderSide(color: widget.border)),
        ),
        child: Row(
          children: <Widget>[
            Expanded(
              child: _UnifiedFeatureDrawerOrbitPinStrip(
                pins: leftPins,
                reverse: true,
                selectedId: widget.selectedId,
                border: widget.border,
                subtext: widget.subtext,
                onOpen: _unifiedFeatureDrawerOpen,
                onUnpin: _unifiedFeatureDrawerTogglePin,
              ),
            ),
            const SizedBox(width: 6),
            Semantics(
              button: true,
              label: 'Open all features',
              hint: 'Tap to open the draggable feature wheel',
              child: IconButton.filled(
                key: const ValueKey<String>('open-feature-wheel'),
                tooltip: 'Explore features',
                onPressed: _unifiedFeatureDrawerLoaded
                    ? _unifiedFeatureDrawerShowDrawer
                    : null,
                icon: const Icon(Icons.blur_circular_rounded),
                style: IconButton.styleFrom(
                  backgroundColor: widget.panel,
                  foregroundColor: widget.text,
                  side: BorderSide(color: widget.border),
                  minimumSize: const Size(48, 48),
                ),
              ),
            ),
            const SizedBox(width: 6),
            Expanded(
              child: _UnifiedFeatureDrawerOrbitPinStrip(
                pins: rightPins,
                selectedId: widget.selectedId,
                border: widget.border,
                subtext: widget.subtext,
                onOpen: _unifiedFeatureDrawerOpen,
                onUnpin: _unifiedFeatureDrawerTogglePin,
              ),
            ),
          ],
        ),
      ),
    );
  }

  static bool _unifiedFeatureDrawerSameIds(List<String> a, List<String> b) {
    if (a.length != b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) return false;
    }
    return true;
  }
}

final class _UnifiedFeatureDrawerOrbitPinStrip extends StatelessWidget {
  final List<NazaFeatureDestination> pins;
  final bool reverse;
  final String selectedId;
  final Color border;
  final Color subtext;
  final ValueChanged<NazaFeatureDestination> onOpen;
  final ValueChanged<String> onUnpin;

  const _UnifiedFeatureDrawerOrbitPinStrip({
    required this.pins,
    this.reverse = false,
    required this.selectedId,
    required this.border,
    required this.subtext,
    required this.onOpen,
    required this.onUnpin,
  });

  @override
  Widget build(BuildContext context) => ListView.separated(
    reverse: reverse,
    scrollDirection: Axis.horizontal,
    itemCount: pins.length,
    separatorBuilder: (_, _) => const SizedBox(width: 4),
    itemBuilder: (_, index) {
      final item = pins[index];
      final selected = item.id == selectedId;
      return Tooltip(
        message: item.label,
        child: InkWell(
          borderRadius: BorderRadius.circular(16),
          onTap: () => onOpen(item),
          onLongPress: item.id == NazaFeaturePinPolicy.requiredId
              ? null
              : () => onUnpin(item.id),
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 180),
            width: 44,
            decoration: BoxDecoration(
              color: selected
                  ? item.accent.withValues(alpha: .2)
                  : Colors.transparent,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: selected ? item.accent : border),
            ),
            child: Icon(
              item.icon,
              size: 20,
              color: selected ? item.accent : subtext,
            ),
          ),
        ),
      );
    },
  );
}

/// Desktop presentation of the same allowlisted registry and persisted pins.
/// The rail stays compact while its orbit button reveals every destination.
final class NazaUnifiedFeatureRail extends StatefulWidget {
  final List<NazaFeatureDestination> destinations;
  final String selectedId;
  final Color surface, panel, border, text, subtext;

  const NazaUnifiedFeatureRail({
    super.key,
    required this.destinations,
    required this.selectedId,
    required this.surface,
    required this.panel,
    required this.border,
    required this.text,
    required this.subtext,
  });

  @override
  State<NazaUnifiedFeatureRail> createState() =>
      _UnifiedFeatureDrawerNazaUnifiedFeatureRailState();
}

class _UnifiedFeatureDrawerNazaUnifiedFeatureRailState
    extends State<NazaUnifiedFeatureRail> {
  final _unifiedFeatureDrawerStore = const NazaFeaturePinStore();
  List<String> _unifiedFeatureDrawerPins = NazaFeaturePinPolicy.defaults;
  bool _unifiedFeatureDrawerLoaded = false;
  bool _unifiedFeatureDrawerSaving = false;
  Set<String> get _unifiedFeatureDrawerAllowed =>
      widget.destinations.map((e) => e.id).toSet();

  @override
  void initState() {
    super.initState();
    unawaited(_unifiedFeatureDrawerLoad());
  }

  Future<void> _unifiedFeatureDrawerLoad() async {
    final pins = await _unifiedFeatureDrawerStore.load(
      _unifiedFeatureDrawerAllowed,
    );
    if (mounted) {
      setState(() {
        _unifiedFeatureDrawerPins = pins;
        _unifiedFeatureDrawerLoaded = true;
      });
    }
  }

  @override
  void didUpdateWidget(covariant NazaUnifiedFeatureRail oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!_unifiedFeatureDrawerSameDestinationIds(
      oldWidget.destinations,
      widget.destinations,
    )) {
      final clean = NazaFeaturePinPolicy.sanitize(
        _unifiedFeatureDrawerPins,
        _unifiedFeatureDrawerAllowed,
      );
      if (clean.length != _unifiedFeatureDrawerPins.length ||
          clean.asMap().entries.any(
            (entry) => entry.value != _unifiedFeatureDrawerPins[entry.key],
          )) {
        _unifiedFeatureDrawerPins = clean;
        unawaited(
          _unifiedFeatureDrawerStore.save(clean, _unifiedFeatureDrawerAllowed),
        );
      }
    }
  }

  NazaFeatureDestination? _unifiedFeatureDrawerById(String id) {
    for (final item in widget.destinations) {
      if (item.id == id) return item;
    }
    return null;
  }

  Future<void> _unifiedFeatureDrawerToggle(String id) async {
    if (!_unifiedFeatureDrawerLoaded || _unifiedFeatureDrawerSaving) return;
    if (!_unifiedFeatureDrawerAllowed.contains(id) ||
        id == NazaFeaturePinPolicy.requiredId)
      return;
    _unifiedFeatureDrawerSaving = true;
    final next = List<String>.from(_unifiedFeatureDrawerPins);
    final previous = List<String>.from(_unifiedFeatureDrawerPins);
    if (!next.remove(id)) {
      if (next.length >= NazaFeaturePinPolicy.maxPins) {
        if (mounted)
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Unpin a feature before adding another.'),
            ),
          );
        return;
      }
      next.add(id);
    }
    final clean = NazaFeaturePinPolicy.sanitize(
      next,
      _unifiedFeatureDrawerAllowed,
    );
    if (mounted) setState(() => _unifiedFeatureDrawerPins = clean);
    final saved = await _unifiedFeatureDrawerStore.save(
      clean,
      _unifiedFeatureDrawerAllowed,
    );
    _unifiedFeatureDrawerSaving = false;
    if (mounted && !saved) setState(() => _unifiedFeatureDrawerPins = previous);
  }

  void _unifiedFeatureDrawerOpen(NazaFeatureDestination item) {
    HapticFeedback.selectionClick();
    item.onOpen();
  }

  Future<void> _unifiedFeatureDrawerShowAll() async {
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, updateDialog) => Dialog(
          backgroundColor: widget.surface,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(28),
            side: BorderSide(color: widget.border),
          ),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 720, maxHeight: 680),
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(22, 18, 10, 10),
                  child: Row(
                    children: [
                      Icon(Icons.blur_circular_rounded, color: widget.text),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              'Feature orbit',
                              style: TextStyle(
                                color: widget.text,
                                fontSize: 22,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            Text(
                              'Open any feature · hold to pin or unpin',
                              style: TextStyle(color: widget.subtext),
                            ),
                          ],
                        ),
                      ),
                      IconButton(
                        tooltip: 'Close',
                        onPressed: () => Navigator.pop(dialogContext),
                        icon: const Icon(Icons.close_rounded),
                      ),
                    ],
                  ),
                ),
                Expanded(
                  child: GridView.builder(
                    padding: const EdgeInsets.fromLTRB(18, 8, 18, 22),
                    gridDelegate:
                        const SliverGridDelegateWithMaxCrossAxisExtent(
                          maxCrossAxisExtent: 180,
                          mainAxisExtent: 146,
                          crossAxisSpacing: 10,
                          mainAxisSpacing: 10,
                        ),
                    itemCount: widget.destinations.length,
                    itemBuilder: (_, index) {
                      final item = widget.destinations[index],
                          pinned = _unifiedFeatureDrawerPins.contains(item.id),
                          selected = item.id == widget.selectedId;
                      return Semantics(
                        button: true,
                        selected: selected,
                        label: '${item.displayTitle}, ${item.displayZone}',
                        hint: pinned
                            ? 'Long press to unpin'
                            : 'Long press to pin',
                        child: Material(
                          color: Color.alphaBlend(
                            item.accent.withValues(alpha: selected ? .22 : .10),
                            widget.panel,
                          ),
                          borderRadius: BorderRadius.circular(22),
                          child: InkWell(
                            borderRadius: BorderRadius.circular(22),
                            onTap: () {
                              Navigator.pop(dialogContext);
                              _unifiedFeatureDrawerOpen(item);
                            },
                            onLongPress: () async {
                              await _unifiedFeatureDrawerToggle(item.id);
                              if (dialogContext.mounted) updateDialog(() {});
                            },
                            child: Container(
                              padding: const EdgeInsets.all(13),
                              decoration: BoxDecoration(
                                borderRadius: BorderRadius.circular(22),
                                border: Border.all(
                                  color: pinned ? item.accent : widget.border,
                                ),
                              ),
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Row(
                                    children: [
                                      CircleAvatar(
                                        backgroundColor: item.accent.withValues(
                                          alpha: .18,
                                        ),
                                        child: Icon(
                                          item.icon,
                                          color: item.accent,
                                        ),
                                      ),
                                      const Spacer(),
                                      Icon(
                                        pinned
                                            ? Icons.push_pin_rounded
                                            : Icons.push_pin_outlined,
                                        color: pinned
                                            ? item.accent
                                            : widget.subtext,
                                        size: 17,
                                      ),
                                    ],
                                  ),
                                  const Spacer(),
                                  Text(
                                    item.displayTitle,
                                    maxLines: 2,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                      color: widget.text,
                                      fontWeight: FontWeight.w900,
                                      fontSize: 12,
                                    ),
                                  ),
                                  Text(
                                    item.label,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                      color: widget.subtext,
                                      fontSize: 10,
                                    ),
                                  ),
                                  Text(
                                    item.displayZone.toUpperCase(),
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                      color: item.accent,
                                      fontSize: 9,
                                      fontWeight: FontWeight.w900,
                                      letterSpacing: .7,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ),
                        ),
                      );
                    },
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final pinned = _unifiedFeatureDrawerPins
        .map(_unifiedFeatureDrawerById)
        .whereType<NazaFeatureDestination>()
        .toList();
    final settings = _unifiedFeatureDrawerById('settings');
    final history = _unifiedFeatureDrawerById('history');
    return Container(
      key: const ValueKey('unified-feature-rail'),
      width: 92,
      decoration: BoxDecoration(
        color: widget.surface,
        border: Border(right: BorderSide(color: widget.border)),
      ),
      child: Column(
        children: [
          Expanded(
            child: ListView.separated(
              padding: const EdgeInsets.fromLTRB(8, 10, 8, 6),
              itemCount: pinned.length,
              separatorBuilder: (_, _) => const SizedBox(height: 6),
              itemBuilder: (_, index) {
                final item = pinned[index],
                    selected = item.id == widget.selectedId;
                return Tooltip(
                  message: item.label,
                  child: Semantics(
                    button: true,
                    selected: selected,
                    label: item.label,
                    child: InkWell(
                      borderRadius: BorderRadius.circular(20),
                      onTap: () => _unifiedFeatureDrawerOpen(item),
                      onLongPress: item.id == NazaFeaturePinPolicy.requiredId
                          ? null
                          : () => _unifiedFeatureDrawerToggle(item.id),
                      child: AnimatedContainer(
                        duration: const Duration(milliseconds: 180),
                        height: 64,
                        decoration: BoxDecoration(
                          color: selected
                              ? item.accent.withValues(alpha: .18)
                              : Colors.transparent,
                          borderRadius: BorderRadius.circular(20),
                          border: Border.all(
                            color: selected ? item.accent : Colors.transparent,
                          ),
                        ),
                        child: Column(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            Icon(
                              item.icon,
                              color: selected ? item.accent : widget.subtext,
                            ),
                            const SizedBox(height: 3),
                            Text(
                              item.id == NazaFeaturePinPolicy.requiredId
                                  ? 'Chat'
                                  : item.label,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                color: selected ? widget.text : widget.subtext,
                                fontSize: 9.5,
                                fontWeight: FontWeight.w800,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                );
              },
            ),
          ),
          if (history != null)
            Padding(
              padding: const EdgeInsets.fromLTRB(9, 2, 9, 2),
              child: Tooltip(
                message: 'History',
                child: InkWell(
                  borderRadius: BorderRadius.circular(18),
                  onTap: () => _unifiedFeatureDrawerOpen(history),
                  child: SizedBox(
                    height: 42,
                    child: FittedBox(
                      fit: BoxFit.scaleDown,
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Icon(
                            Icons.history_rounded,
                            color: widget.subtext,
                            size: 19,
                          ),
                          Text(
                            'History',
                            style: TextStyle(
                              color: widget.subtext,
                              fontSize: 9,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            ),
          if (settings != null)
            Padding(
              padding: const EdgeInsets.fromLTRB(9, 2, 9, 4),
              child: Tooltip(
                message: 'Settings',
                child: InkWell(
