final class _UnifiedFeatureDrawerFeatureWheelSheet extends StatefulWidget {
  final List<NazaFeatureDestination> destinations;
  final List<String> pins;
  final String selectedId;
  final Color surface;
  final Color panel;
  final Color border;
  final Color text;
  final Color subtext;
  final ValueChanged<NazaFeatureDestination> onOpen;
  final Future<void> Function(String id) onTogglePin;

  const _UnifiedFeatureDrawerFeatureWheelSheet({
    required this.destinations,
    required this.pins,
    required this.selectedId,
    required this.surface,
    required this.panel,
    required this.border,
    required this.text,
    required this.subtext,
    required this.onOpen,
    required this.onTogglePin,
  });

  @override
  State<_UnifiedFeatureDrawerFeatureWheelSheet> createState() =>
      _UnifiedFeatureDrawerFeatureWheelSheetState();
}

class _UnifiedFeatureDrawerFeatureWheelSheetState
    extends State<_UnifiedFeatureDrawerFeatureWheelSheet> {
  static const int _unifiedFeatureDrawerOrbitBase = 10000;
  late final PageController _unifiedFeatureDrawerController;
  double _unifiedFeatureDrawerPage = 0;
  String _unifiedFeatureDrawerCategory = 'All';
  String _unifiedFeatureDrawerQuery = '';

  List<NazaFeatureDestination> get _unifiedFeatureDrawerVisible => widget
      .destinations
      .where((e) {
        final categoryMatch =
            _unifiedFeatureDrawerCategory == 'All' ||
            e.category == _unifiedFeatureDrawerCategory;
        final query = _unifiedFeatureDrawerQuery.trim().toLowerCase();
        final queryMatch =
            query.isEmpty ||
            e.label.toLowerCase().contains(query) ||
            e.displayTitle.toLowerCase().contains(query) ||
            e.displayZone.toLowerCase().contains(query) ||
            e.category.toLowerCase().contains(query) ||
            e.description.toLowerCase().contains(query);
        return categoryMatch && queryMatch;
      })
      .toList(growable: false);

  @override
  void initState() {
    super.initState();
    final selected = widget.destinations.indexWhere(
      (e) => e.id == widget.selectedId,
    );
    final count = widget.destinations.length;
    final logical = selected < 0 ? 0 : selected;
    final initial = count == 0
        ? _unifiedFeatureDrawerOrbitBase
        : _unifiedFeatureDrawerOrbitBase -
              (_unifiedFeatureDrawerOrbitBase % count) +
              logical;
    _unifiedFeatureDrawerPage = initial.toDouble();
    _unifiedFeatureDrawerController = PageController(
      initialPage: initial,
      viewportFraction: 0.38,
    )..addListener(_unifiedFeatureDrawerTrackPage);
  }

  void _unifiedFeatureDrawerRecenterOrbit() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_unifiedFeatureDrawerController.hasClients) return;
      final count = _unifiedFeatureDrawerVisible.length;
      final target = count == 0
          ? _unifiedFeatureDrawerOrbitBase
          : _unifiedFeatureDrawerOrbitBase -
                (_unifiedFeatureDrawerOrbitBase % count);
      _unifiedFeatureDrawerPage = target.toDouble();
      _unifiedFeatureDrawerController.jumpToPage(target);
    });
  }

  void _unifiedFeatureDrawerTrackPage() {
    final page = _unifiedFeatureDrawerController.page;
    if (page != null && mounted)
      setState(() => _unifiedFeatureDrawerPage = page);
  }

  @override
  void dispose() {
    _unifiedFeatureDrawerController
      ..removeListener(_unifiedFeatureDrawerTrackPage)
      ..dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final categories = <String>{
      'All',
      ...widget.destinations.map((e) => e.category),
    }.toList();
    final visible = _unifiedFeatureDrawerVisible;
    return Container(
      constraints: BoxConstraints(
        maxHeight: MediaQuery.sizeOf(context).height * 0.74,
      ),
      decoration: BoxDecoration(
        color: widget.surface,
        borderRadius: const BorderRadius.vertical(top: Radius.circular(32)),
        border: Border.all(color: widget.border),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: <Widget>[
          const SizedBox(height: 10),
          Container(
            width: 44,
            height: 4,
            decoration: BoxDecoration(
              color: widget.border,
              borderRadius: BorderRadius.circular(99),
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 16, 12, 8),
            child: Row(
              children: <Widget>[
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: <Widget>[
                      Text(
                        'Your feature wheel',
                        style: TextStyle(
                          color: widget.text,
                          fontSize: 22,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      Text(
                        'Explore focused app zones · hold a card to pin',
                        style: TextStyle(color: widget.subtext, fontSize: 12),
                      ),
                    ],
                  ),
                ),
                IconButton(
                  tooltip: 'Close',
                  onPressed: () => Navigator.maybePop(context),
                  icon: const Icon(Icons.close_rounded),
                ),
              ],
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(18, 0, 18, 10),
            child: TextField(
              onChanged: (value) => setState(() {
                _unifiedFeatureDrawerQuery = value;
                _unifiedFeatureDrawerRecenterOrbit();
              }),
              style: TextStyle(color: widget.text),
              decoration: InputDecoration(
                hintText: 'Search all ${widget.destinations.length} features',
                hintStyle: TextStyle(color: widget.subtext),
                prefixIcon: Icon(Icons.search_rounded, color: widget.subtext),
                filled: true,
                fillColor: widget.panel,
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(18),
                  borderSide: BorderSide(color: widget.border),
                ),
                enabledBorder: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(18),
                  borderSide: BorderSide(color: widget.border),
                ),
              ),
            ),
          ),
          SizedBox(
            height: 40,
            child: ListView.separated(
              padding: const EdgeInsets.symmetric(horizontal: 18),
              scrollDirection: Axis.horizontal,
              itemCount: categories.length,
              separatorBuilder: (_, _) => const SizedBox(width: 7),
              itemBuilder: (_, index) {
                final category = categories[index];
                return ChoiceChip(
                  label: Text(category),
                  selected: category == _unifiedFeatureDrawerCategory,
                  onSelected: (_) => setState(() {
                    _unifiedFeatureDrawerCategory = category;
                    _unifiedFeatureDrawerQuery = '';
                    _unifiedFeatureDrawerRecenterOrbit();
                  }),
                );
              },
            ),
          ),
          const SizedBox(height: 14),
          SizedBox(
            height: 178,
            child: PageView.builder(
              key: ValueKey<String>(_unifiedFeatureDrawerCategory),
              controller: _unifiedFeatureDrawerController,
              padEnds: true,
              itemCount: visible.isEmpty ? 0 : null,
              itemBuilder: (context, index) {
                final distance = (index - _unifiedFeatureDrawerPage)
                    .abs()
                    .clamp(0.0, 1.0);
                final signedDistance = index - _unifiedFeatureDrawerPage;
                final scale = 1 - distance * 0.2;
                final lift = math.cos(signedDistance * math.pi / 3) * 18;
                final item = visible[index % visible.length];
                final pinned = widget.pins.contains(item.id);
                return Transform.translate(
                  offset: Offset(0, -lift),
                  child: Transform.rotate(
                    angle: signedDistance * 0.16,
                    child: Transform.scale(
                      scale: scale,
                      child: Semantics(
                        button: true,
                        selected: item.id == widget.selectedId,
                        label: '${item.displayTitle}, ${item.displayZone}',
                        hint: pinned
                            ? 'Long press to unpin'
                            : 'Long press to pin',
                        child: Card(
                          color: Color.alphaBlend(
                            item.accent.withValues(alpha: 0.13),
                            widget.panel,
                          ),
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(28),
                            side: BorderSide(
                              color: pinned ? item.accent : widget.border,
                              width: pinned ? 1.5 : 1,
                            ),
                          ),
                          child: InkWell(
                            borderRadius: BorderRadius.circular(28),
                            onTap: () => widget.onOpen(item),
                            onLongPress: () => widget.onTogglePin(item.id),
                            child: Padding(
                              padding: const EdgeInsets.all(14),
                              child: Column(
                                mainAxisAlignment: MainAxisAlignment.center,
                                children: <Widget>[
                                  CircleAvatar(
                                    radius: 22,
                                    backgroundColor: item.accent.withValues(
                                      alpha: 0.18,
                                    ),
                                    child: Icon(
                                      item.icon,
                                      color: item.accent,
                                      size: 24,
                                    ),
                                  ),
                                  const SizedBox(height: 6),
                                  Text(
                                    item.displayTitle,
                                    textAlign: TextAlign.center,
                                    maxLines: 2,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                      color: widget.text,
                                      fontWeight: FontWeight.w900,
                                    ),
                                  ),
                                  Text(
                                    item.label,
                                    textAlign: TextAlign.center,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                      color: widget.subtext,
                                      fontSize: 10,
                                    ),
                                  ),
                                  const SizedBox(height: 3),
                                  Text(
                                    item.displayZone.toUpperCase(),
                                    textAlign: TextAlign.center,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                      color: item.accent,
                                      fontSize: 9,
                                      fontWeight: FontWeight.w900,
                                      letterSpacing: 1.1,
                                    ),
                                  ),
                                  const SizedBox(height: 5),
                                  Icon(
                                    pinned
                                        ? Icons.push_pin_rounded
                                        : Icons.push_pin_outlined,
                                    size: 15,
                                    color: pinned
                                        ? item.accent
                                        : widget.subtext,
                                  ),
                                ],
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                );
              },
            ),
          ),
          if (visible.isNotEmpty)
            Padding(
              padding: const EdgeInsets.fromLTRB(24, 0, 24, 22),
              child: Text(
                visible[_unifiedFeatureDrawerPage.round() % visible.length]
                    .description,
                textAlign: TextAlign.center,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(color: widget.subtext, height: 1.35),
              ),
            ),
        ],
      ),
    );
  }
}

