const Object _nazaBookforgeBookUnset = Object();

enum BookProvider { gemma4, gpt56Luna }

enum BookFormat { markdown, plainText, docx }

enum BookOrigin { local, generated, repository }

enum BookStatus { draft, review, published }

class BookMedia {
  const BookMedia({
    required this.name,
    required this.mimeType,
    required this.bytes,
  });

  final String name;
  final String mimeType;
  final List<int> bytes;

  Map<String, Object?> toJson() => <String, Object?>{
    'name': name,
    'mimeType': mimeType,
    'bytes': base64Encode(bytes),
  };

  factory BookMedia.fromJson(Map<String, Object?> json) => BookMedia(
    name: json['name'] as String? ?? 'image',
    mimeType: json['mimeType'] as String? ?? 'image/png',
    bytes: base64Decode(json['bytes'] as String? ?? ''),
  );
}

class BookDocument {
  const BookDocument({
    required this.id,
    required this.title,
    required this.author,
    required this.content,
    required this.format,
    required this.origin,
    required this.status,
    required this.createdAt,
    required this.updatedAt,
    this.sourcePath,
    this.repository,
    this.tags = const <String>[],
    this.media = const <BookMedia>[],
  });

  final String id;
  final String title;
  final String author;
  final String content;
  final BookFormat format;
  final BookOrigin origin;
  final BookStatus status;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String? sourcePath;
  final String? repository;
  final List<String> tags;
  final List<BookMedia> media;

  int get wordCount => RegExp(r'\b[\w’\-]+\b').allMatches(content).length;
  int get estimatedMinutes => wordCount == 0 ? 0 : (wordCount / 220).ceil();

  BookDocument copyWith({
    String? title,
    String? author,
    String? content,
    BookFormat? format,
    BookOrigin? origin,
    BookStatus? status,
    DateTime? updatedAt,
    Object? sourcePath = _nazaBookforgeBookUnset,
    Object? repository = _nazaBookforgeBookUnset,
    List<String>? tags,
    List<BookMedia>? media,
  }) {
    return BookDocument(
      id: id,
      title: title ?? this.title,
      author: author ?? this.author,
      content: content ?? this.content,
      format: format ?? this.format,
      origin: origin ?? this.origin,
      status: status ?? this.status,
      createdAt: createdAt,
      updatedAt: updatedAt ?? this.updatedAt,
      sourcePath: identical(sourcePath, _nazaBookforgeBookUnset)
          ? this.sourcePath
          : sourcePath as String?,
      repository: identical(repository, _nazaBookforgeBookUnset)
          ? this.repository
          : repository as String?,
      tags: tags ?? this.tags,
      media: media ?? this.media,
    );
  }

  Map<String, Object?> toJson() => <String, Object?>{
    'id': id,
    'title': title,
    'author': author,
    'content': content,
    'format': format.name,
    'origin': origin.name,
    'status': status.name,
    'createdAt': createdAt.toIso8601String(),
    'updatedAt': updatedAt.toIso8601String(),
    'sourcePath': sourcePath,
    'repository': repository,
    'tags': tags,
    'media': media.map((BookMedia item) => item.toJson()).toList(),
  };

  factory BookDocument.fromJson(Map<String, Object?> json) {
    T parseEnum<T extends Enum>(List<T> values, Object? value, T fallback) {
      return values.where((T item) => item.name == value).firstOrNull ??
          fallback;
    }

    return BookDocument(
      id: json['id'] as String,
      title: json['title'] as String? ?? 'Untitled',
      author: json['author'] as String? ?? 'Unknown',
      content: json['content'] as String? ?? '',
      format: parseEnum(BookFormat.values, json['format'], BookFormat.markdown),
      origin: parseEnum(BookOrigin.values, json['origin'], BookOrigin.local),
      status: parseEnum(BookStatus.values, json['status'], BookStatus.draft),
      createdAt:
          DateTime.tryParse(json['createdAt'] as String? ?? '') ??
          DateTime.now(),
      updatedAt:
          DateTime.tryParse(json['updatedAt'] as String? ?? '') ??
          DateTime.now(),
      sourcePath: json['sourcePath'] as String?,
      repository: json['repository'] as String?,
      tags: (json['tags'] as List<Object?>? ?? const <Object?>[])
          .whereType<String>()
          .toList(),
      media: (json['media'] as List<Object?>? ?? const <Object?>[])
          .whereType<Map<Object?, Object?>>()
          .map(
            (Map<Object?, Object?> item) =>
                BookMedia.fromJson(Map<String, Object?>.from(item)),
          )
          .toList(),
    );
  }

  String encode() => jsonEncode(toJson());
}

class RepositoryBook {
  const RepositoryBook({
    required this.name,
    required this.path,
    required this.sha,
    required this.size,
    required this.downloadUrl,
    required this.format,
  });

  final String name;
  final String path;
  final String sha;
  final int size;
  final Uri? downloadUrl;
  final BookFormat format;
}

class RepositoryTarget {
  const RepositoryTarget({
    required this.owner,
    required this.name,
    this.branch = 'main',
    this.directory = 'generated',
  });

  final String owner;
  final String name;
  final String branch;
  final String directory;

  String get fullName => '$owner/$name';

  RepositoryTarget copyWith({
    String? owner,
    String? name,
    String? branch,
    String? directory,
  }) {
    return RepositoryTarget(
      owner: owner ?? this.owner,
      name: name ?? this.name,
      branch: branch ?? this.branch,
      directory: directory ?? this.directory,
    );
  }
}

class GenerationRequest {
  const GenerationRequest({
    required this.title,
    required this.premise,
    required this.audience,
    required this.voice,
    required this.chapterCount,
    required this.depth,
    required this.includeExercises,
    required this.includeSources,
    this.chapterWordTarget = 1200,
  });

  final String title;
  final String premise;
  final String audience;
  final String voice;
  final int chapterCount;
  final String depth;
  final bool includeExercises;
  final bool includeSources;
  final int chapterWordTarget;
}

class GenerationProgress {
  const GenerationProgress({
    required this.completed,
    required this.total,
    required this.phase,
  });

  final int completed;
  final int total;
  final String phase;

  double get fraction => total == 0 ? 0 : completed / total;
}

extension FirstOrNull<T> on Iterable<T> {
  T? get firstOrNull => isEmpty ? null : first;
}

class LibraryStore {
  LibraryStore({NazaSecureDatabase? database})
    : _nazaBookforgeDatabase = database ?? NazaSecureDatabase.instance;

  static const String _nazaBookforgeLegacyKey = 'bookforge.library.v1';
  static const String _nazaBookforgeIndexKey = 'bookforge.library-index.v2';
  static const String _nazaBookforgeBookPrefix = 'bookforge.book.v2.';

  final NazaSecureDatabase _nazaBookforgeDatabase;

  Future<List<BookDocument>> load() async {
    final index = await _nazaBookforgeDatabase.readJson(
      'bookforge',
      _nazaBookforgeIndexKey,
    );
    if (index is List) {
      final books = <BookDocument>[];
      for (final Object? id in index) {
        if (id is! String || id.isEmpty) {
          throw StateError('The encrypted BookForge index is malformed.');
        }
        final value = await _nazaBookforgeDatabase.readJson(
          'bookforge',
          _nazaBookforgeRecordKey(id),
        );
        if (value is! Map) {
          throw StateError(
            'An encrypted BookForge record referenced by the index is missing or malformed.',
          );
        }
        books.add(BookDocument.fromJson(Map<String, Object?>.from(value)));
      }
      await _nazaBookforgeRemoveLegacyPlaintextIfPresent();
      return books;
    }
    if (index != null) {
      throw StateError('The encrypted BookForge index is malformed.');
    }

    final secure = await _nazaBookforgeDatabase.readJson(
      'bookforge',
      'library',
    );
    if (secure is List) {
      final books = _nazaBookforgeDecode(secure);
      await _nazaBookforgeMigrateBooks(books);
      await _nazaBookforgeRemoveLegacyPlaintextIfPresent();
      return books;
    }
    if (secure != null) {
      throw StateError('The encrypted BookForge library is malformed.');
    }

    // Older builds mirrored the encrypted library into preferences. Read that
    // value only as a one-time migration source; never write new manuscripts
    // or media there. Delete it only after the secure rewrite succeeds so a
    // transient keychain/database failure cannot destroy the user's library.
    final SharedPreferences prefs = await SharedPreferences.getInstance();
    final String? raw = prefs.getString(_nazaBookforgeLegacyKey);
    if (raw == null || raw.isEmpty) return <BookDocument>[];
    late final List<BookDocument> books;
    try {
      final List<dynamic> decoded = jsonDecode(raw) as List<dynamic>;
      books = _nazaBookforgeDecode(decoded);
    } catch (error) {
      throw StateError('The legacy BookForge library is malformed: $error');
    }
    await _nazaBookforgeMigrateBooks(books);
    await _nazaBookforgeRemoveLegacyPlaintextIfPresent(preferences: prefs);
    return books;
  }

  Future<void> saveBook(BookDocument book) async {
    await _nazaBookforgeDatabase.writeJson(
      'bookforge',
      _nazaBookforgeRecordKey(book.id),
      book.toJson(),
    );
  }

  Future<void> saveBooks(List<BookDocument> books) async {
    for (final BookDocument book in books) {
      await saveBook(book);
    }
    await _nazaBookforgeDatabase.writeJson(
      'bookforge',
      _nazaBookforgeIndexKey,
      books.map((BookDocument book) => book.id).toList(),
    );
    // Remove the old monolithic encrypted record after the per-book migration.
    await _nazaBookforgeDatabase.delete('bookforge', 'library');
  }

  Future<void> deleteBook(
    BookDocument book,
    List<BookDocument> remaining,
  ) async {
    await _nazaBookforgeDatabase.delete(
      'bookforge',
      _nazaBookforgeRecordKey(book.id),
    );
    await _nazaBookforgeDatabase.writeJson(
      'bookforge',
      _nazaBookforgeIndexKey,
      remaining.map((BookDocument item) => item.id).toList(),
    );
  }

  Future<void> _nazaBookforgeMigrateBooks(List<BookDocument> books) =>
      saveBooks(books);

  Future<void> _nazaBookforgeRemoveLegacyPlaintextIfPresent({
    SharedPreferences? preferences,
  }) async {
    final prefs = preferences ?? await SharedPreferences.getInstance();
    if (prefs.getString(_nazaBookforgeLegacyKey) == null) return;
    final removed = await prefs.remove(_nazaBookforgeLegacyKey);
    if (!removed || prefs.getString(_nazaBookforgeLegacyKey) != null) {
      throw StateError(
        'The legacy plaintext BookForge library could not be removed securely.',
      );
    }
  }

  String _nazaBookforgeRecordKey(String id) =>
      '$_nazaBookforgeBookPrefix${base64UrlEncode(utf8.encode(id)).replaceAll('=', '')}';

  List<BookDocument> _nazaBookforgeDecode(Object value) {
    if (value is! List)
      throw const FormatException('Invalid BookForge library.');
    return value
        .map(
          (Object? item) =>
              BookDocument.fromJson(Map<String, Object?>.from(item as Map)),
        )
        .toList();
  }
}

class ImportService {
  // These limits apply before archive entry contents are materialized. They
  // bound both attacker-controlled compressed input and the declared ZIP
  // expansion, which protects the UI isolate from decompression bombs.
  static const int maxCompressedBytes = 32 * 1024 * 1024;
  static const int maxArchiveEntries = 256;
  static const int maxExpandedBytes = 64 * 1024 * 1024;
  static const int maxEntryBytes = 16 * 1024 * 1024;
  static const int maxXmlBytes = 12 * 1024 * 1024;
  static const int maxMediaBytes = 24 * 1024 * 1024;

  Future<BookDocument?> pickAndImport({
    String author = 'Unknown author',
  }) async {
    final FilePickerResult? result = await FilePicker.pickFiles(
      type: FileType.custom,
      allowedExtensions: <String>['md', 'markdown', 'txt', 'docx'],
      withData: false,
      withReadStream: true,
    );
    if (result == null || result.files.isEmpty) return null;
    final PlatformFile file = result.files.single;
    final Uint8List bytes = await NazaBoundedInput.readPlatformFile(
      file,
      maxBytes: maxCompressedBytes,
      violation: const FormatException(
        'Choose a non-empty file within the 32 MiB import limit.',
      ),
    );
    final String ext = (file.extension ?? '').toLowerCase();
    // Decode once and reuse the validated archive for both document text and
    // media extraction. This halves ZIP parsing and avoids duplicate lazy
    // decompression for DOCX imports.
    final Archive? archive = ext == 'docx'
        ? _nazaBookforgeDecodeBoundedArchive(bytes)
        : null;
    final String content = sanitize(
      archive == null
          ? utf8.decode(bytes, allowMalformed: true)
          : _nazaBookforgeDocxToMarkdownArchive(archive),
    );
    final DateTime now = DateTime.now();
    return BookDocument(
      id: '${now.microsecondsSinceEpoch}-${file.name.hashCode}',
      title: titleFrom(content, file.name),
      author: author,
      content: content,
      format: ext == 'docx'
          ? BookFormat.docx
          : ext == 'txt'
          ? BookFormat.plainText
          : BookFormat.markdown,
      origin: BookOrigin.local,
      status: BookStatus.draft,
      createdAt: now,
      updatedAt: now,
      sourcePath: file.name,
      tags: const <String>['imported'],
      media: archive == null
          ? const <BookMedia>[]
          : _nazaBookforgeDocxMedia(archive),
    );
  }

  String docxToMarkdown(Uint8List bytes) {
    return _nazaBookforgeDocxToMarkdownArchive(
      _nazaBookforgeDecodeBoundedArchive(bytes),
    );
  }

  String _nazaBookforgeDocxToMarkdownArchive(Archive archive) {
    ArchiveFile? document;
    for (final ArchiveFile file in archive.files) {
      if (file.name == 'word/document.xml') {
        document = file;
        break;
      }
    }
    if (document == null)
      throw const FormatException('DOCX is missing word/document.xml.');
    if (document.size > maxXmlBytes) {
      throw const FormatException('DOCX XML exceeds the 12 MiB safety limit.');
    }
    final Uint8List data = document.content;
    final XmlDocument xml = XmlDocument.parse(
      utf8.decode(data, allowMalformed: true),
    );
    final StringBuffer out = StringBuffer();
    for (final XmlElement paragraph in xml.findAllElements('w:p')) {
      // DOCX stores a paragraph across many runs.  Reading only `w:t` and
      // joining blindly loses spaces, tabs, and explicit line breaks, which
      // makes imported books appear as one long/vertical word on mobile.
      final StringBuffer paragraphText = StringBuffer();
      for (final XmlNode node in paragraph.descendants) {
        if (node is! XmlElement) continue;
        if (node.name.local == 't') {
          paragraphText.write(node.innerText);
        } else if (node.name.local == 'tab') {
          paragraphText.write('    ');
        } else if (node.name.local == 'br' || node.name.local == 'cr') {
          paragraphText.write('\n');
        }
      }
      final String text = paragraphText
          .toString()
          .replaceAll(RegExp(r'[ \t]+'), ' ')
          .trim();
      if (text.isEmpty) continue;
      final String? style = paragraph
          .findAllElements('w:pStyle')
          .map((XmlElement node) => node.getAttribute('w:val'))
          .whereType<String>()
          .firstOrNull;
      if (style != null && style.toLowerCase().startsWith('heading')) {
        final int parsed =
            int.tryParse(style.replaceAll(RegExp(r'\D'), '')) ?? 1;
        final int level = parsed < 1
            ? 1
            : parsed > 6
            ? 6
            : parsed;
        out.writeln('${List<String>.filled(level, '#').join()} $text\n');
      } else {
        out.writeln('$text\n');
      }
    }
    return out.toString().trim();
  }

  List<BookMedia> docxMedia(Uint8List bytes) {
    return _nazaBookforgeDocxMedia(_nazaBookforgeDecodeBoundedArchive(bytes));
  }

  List<BookMedia> _nazaBookforgeDocxMedia(Archive archive) {
    int mediaBytes = 0;
    return archive.files
        .where((ArchiveFile file) {
          final String name = file.name.toLowerCase();
          return name.startsWith('word/media/') &&
              (name.endsWith('.png') ||
                  name.endsWith('.jpg') ||
                  name.endsWith('.jpeg') ||
                  name.endsWith('.gif') ||
                  name.endsWith('.webp'));
        })
        .map((ArchiveFile file) {
          mediaBytes += file.size;
          if (mediaBytes > maxMediaBytes) {
            throw const FormatException(
              'DOCX media exceeds the 24 MiB safety limit.',
            );
          }
          final String name = file.name.split('/').last;
          final String extension = name.contains('.')
              ? name.split('.').last.toLowerCase()
              : 'png';
          final Uint8List bytes = file.content;
          return BookMedia(
            name: name,
            mimeType: extension == 'jpg' || extension == 'jpeg'
                ? 'image/jpeg'
                : 'image/$extension',
            bytes: bytes,
          );
        })
        .toList();
  }

  Archive _nazaBookforgeDecodeBoundedArchive(Uint8List bytes) {
    if (bytes.length > maxCompressedBytes) {
      throw const FormatException('DOCX exceeds the 32 MiB compressed limit.');
    }
    var entries = 0;
    var expandedBytes = 0;
    return ZipDecoder().decodeBytes(
      bytes,
      callback: (ArchiveFile file) {
        if (++entries > maxArchiveEntries) {
          throw const FormatException(
            'DOCX contains too many archive entries.',
          );
        }
        if (file.size < 0 || file.size > maxEntryBytes) {
          throw const FormatException(
            'DOCX archive entry exceeds the 16 MiB limit.',
          );
        }
        expandedBytes += file.size;
        if (expandedBytes > maxExpandedBytes) {
          throw const FormatException(
            'DOCX expanded content exceeds the 64 MiB limit.',
          );
        }
      },
    );
  }

  String titleFrom(String content, String fallback) {
    final String fileTitle = fallback
        .replaceFirst(RegExp(r'\.[^.]+$'), '')
        .replaceAll(RegExp(r'[_-]+'), ' ')
        .trim();
    final generic = <String>{'table of contents', 'contents', 'toc', 'index'};
    final headings = RegExp(r'^#{1,2}\s+(.+)$', multiLine: true)
        .allMatches(content)
        .map((match) => _nazaBookforgeCleanTitle(match.group(1) ?? ''))
        .where(
          (title) => title.isNotEmpty && !generic.contains(title.toLowerCase()),
        )
        .toList();
    // Prefer the repository filename when the document only exposes a
    // navigational “Table of Contents” heading (common in DOCX exports).
    if (fileTitle.isNotEmpty && !generic.contains(fileTitle.toLowerCase())) {
      return fileTitle.length > 160 ? fileTitle.substring(0, 160) : fileTitle;
    }
    if (headings.isNotEmpty) return headings.first;
    return fileTitle.isEmpty ? 'Imported book' : fileTitle;
  }

  String _nazaBookforgeCleanTitle(String value) => value
      .replaceAll(RegExp(r'[\u0000-\u001F]'), ' ')
      .replaceAll(RegExp(r'[*_`<>]'), '')
      .replaceAll(RegExp(r'\s+'), ' ')
      .trim();

  String sanitize(String value) {
    final String clean = value
        .replaceAll('\r\n', '\n')
        .replaceAll('\r', '\n')
        .replaceAll(RegExp(r'[\u0000-\u0008\u000B\u000C\u000E-\u001F]'), '');
    if (clean.length > 12000000)
      throw const FormatException('Book is too large to import safely.');
    return clean.trim();
  }
}

class GitHubService {
  static const int maxDownloadBytes = ImportService.maxCompressedBytes;
  static const Duration requestTimeout = Duration(seconds: 30);
  GitHubService({http.Client? client, NazaHarmGate? harmGate})
    : _nazaBookforgeClient = client ?? http.Client(),
      _nazaBookforgeHarmGate = harmGate ?? NazaSentinelGuard.instance.gate;
  final http.Client _nazaBookforgeClient;
  final NazaHarmGate _nazaBookforgeHarmGate;

  Map<String, String> headers(String token) {
    final clean = token.trim();
    if (clean.length > 1024 || clean.contains(RegExp(r'[\r\n\u0000]'))) {
      throw const FormatException('GitHub credential is malformed.');
    }
    return <String, String>{
      'Accept': 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
      if (clean.isNotEmpty) 'Authorization': 'Bearer $clean',
    };
  }

  Future<List<RepositoryBook>> scanBooks(
    RepositoryTarget target, {
    String token = '',
  }) async {
    _nazaBookforgeValidateTarget(target);
    final Uri uri = Uri.https(
      'api.github.com',
      '/repos/${target.fullName}/git/trees/${target.branch}',
      <String, String>{'recursive': '1'},
    );
    await _nazaBookforgeHarmGate.requireAllowed('github.repository.scan');
    final http.Response response = await _nazaBookforgeClient
        .get(uri, headers: headers(token))
        .timeout(requestTimeout);
    _nazaBookforgeCheck(response, 'scan repository');
    final Map<String, dynamic> data =
        jsonDecode(response.body) as Map<String, dynamic>;
    if (data['truncated'] == true) {
      throw StateError(
        'GitHub returned a truncated repository tree. Narrow the repository or scan a subdirectory.',
      );
    }
    final List<dynamic> tree = data['tree'] as List<dynamic>? ?? <dynamic>[];
    final List<RepositoryBook> books = <RepositoryBook>[];
    for (final dynamic item in tree) {
      final Map<String, dynamic> node = item as Map<String, dynamic>;
      if (node['type'] != 'blob') continue;
      final String path = node['path'] as String? ?? '';
      if (path.isEmpty ||
          path.startsWith('/') ||
          path.contains('..') ||
          path.length > 512)
        continue;
      final String lower = path.toLowerCase();
      if (!lower.endsWith('.md') &&
          !lower.endsWith('.txt') &&
          !lower.endsWith('.docx'))
        continue;
      books.add(
        RepositoryBook(
          name: path.split('/').last,
          path: path,
          sha: node['sha'] as String? ?? '',
          size: node['size'] as int? ?? 0,
          downloadUrl: Uri.tryParse(
            'https://raw.githubusercontent.com/${target.fullName}/${target.branch}/$path',
          ),
          format: lower.endsWith('.docx')
              ? BookFormat.docx
              : lower.endsWith('.txt')
              ? BookFormat.plainText
              : BookFormat.markdown,
        ),
      );
    }
    books.sort(
      (RepositoryBook a, RepositoryBook b) => a.path.compareTo(b.path),
    );
    return books;
  }

  Future<BookDocument> downloadBook(
    RepositoryTarget target,
    RepositoryBook book, {
    String token = '',
  }) async {
    _nazaBookforgeValidateTarget(target);
    _nazaBookforgeValidateRepositoryPath(book.path);
    // The Contents API does not reliably return inline content for large files
    // (notably DOCX files). Fetch the raw blob instead so the ZIP remains intact.
    // Reconstruct the URI from the validated target/path instead of trusting a
    // repository response or deserialized `downloadUrl` to choose the host.
    final Uri uri = Uri.https(
      'raw.githubusercontent.com',
      '/${target.fullName}/${target.branch}/${book.path}',
    );
    await _nazaBookforgeHarmGate.requireAllowed('github.data.pull');
    final Uint8List bytes = await _nazaBookforgeDownloadBounded(
      uri,
      headers: headers(token),
      action: 'download ${book.path}',
    );
    final ImportService importer = ImportService();
    final String content = importer.sanitize(
      book.format == BookFormat.docx
          ? importer.docxToMarkdown(bytes)
          : utf8.decode(bytes, allowMalformed: true),
    );
    final DateTime now = DateTime.now();
    return BookDocument(
      id: '${now.microsecondsSinceEpoch}-${book.sha}',
      title: importer.titleFrom(content, book.name),
      author: 'Unknown author',
      content: content,
      format: book.format,
      origin: BookOrigin.repository,
      status: BookStatus.published,
      createdAt: now,
      updatedAt: now,
      sourcePath: book.path,
      repository: target.fullName,
      tags: const <String>['repository'],
      media: book.format == BookFormat.docx
          ? importer.docxMedia(bytes)
          : const <BookMedia>[],
    );
  }

  Future<Uint8List> _nazaBookforgeDownloadBounded(
    Uri uri, {
    required Map<String, String> headers,
    required String action,
  }) async {
    final http.StreamedResponse response = await _nazaBookforgeClient
        .send(
          http.Request('GET', uri)
            ..followRedirects = false
            ..headers.addAll(headers),
        )
        .timeout(requestTimeout);
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw StateError('Could not $action (${response.statusCode}).');
    }
    final int? advertised = int.tryParse(
      response.headers['content-length'] ?? '',
    );
    if (advertised != null && advertised > maxDownloadBytes) {
      throw const FormatException(
        'Repository download exceeds the 32 MiB limit.',
      );
    }
    final builder = BytesBuilder(copy: false);
    var received = 0;
    await for (final chunk in response.stream) {
      received += chunk.length;
      if (received > maxDownloadBytes) {
        throw const FormatException(
          'Repository download exceeds the 32 MiB limit.',
        );
      }
      builder.add(chunk);
    }
    return builder.takeBytes();
  }

  Future<Uri> publishMarkdown({
    required RepositoryTarget target,
    required BookDocument book,
    required String token,
    bool allowOverwrite = false,
  }) async {
    if (token.trim().isEmpty)
      throw ArgumentError('A GitHub token is required to publish.');
    _nazaBookforgeValidateTarget(target);
    final String directory = target.directory.trim().replaceAll(
      RegExp(r'^/+|/+$'),
      '',
    );
    if (directory.isNotEmpty) _nazaBookforgeValidateRepositoryPath(directory);
    final String path =
        '${directory.isEmpty ? '' : '$directory/'}${_nazaBookforgeSlug(book.title)}.md';
    final Uri uri = Uri.https(
      'api.github.com',
      '/repos/${target.fullName}/contents/$path',
    );
    await _nazaBookforgeHarmGate.requireAllowed('github.data.publish');
    String? existingSha;
    final http.Response existing = await _nazaBookforgeClient
        .get(
          uri.replace(queryParameters: <String, String>{'ref': target.branch}),
          headers: headers(token),
        )
        .timeout(requestTimeout);
    if (existing.statusCode == 200) {
      existingSha =
          (jsonDecode(existing.body) as Map<String, dynamic>)['sha'] as String?;
    } else if (existing.statusCode != 404) {
      _nazaBookforgeCheck(existing, 'check existing file');
    }
    if (existingSha != null && !allowOverwrite) {
      throw StateError(
        'A file already exists at $path. Confirm overwrite explicitly before publishing.',
      );
    }

    final String escapedTitle = _nazaBookforgeYamlDoubleQuoted(book.title);
    final String escapedAuthor = _nazaBookforgeYamlDoubleQuoted(book.author);
    final String frontMatter =
        '''---
title: "$escapedTitle"
author: "$escapedAuthor"
status: published
updated: ${DateTime.now().toUtc().toIso8601String()}
tags: [${book.tags.map(_nazaBookforgeYamlDoubleQuoted).map((String value) => '"$value"').join(', ')}]
---

''';
    final Map<String, Object?> payload = <String, Object?>{
      'message': 'Publish ${book.title}',
      'content': base64Encode(
        utf8.encode('$frontMatter${book.content.trim()}\n'),
      ),
      'branch': target.branch,
      ...?existingSha == null ? null : <String, String>{'sha': existingSha},
    };
    final http.Response response = await _nazaBookforgeClient
        .put(
          uri,
          headers: <String, String>{
            ...headers(token),
            'Content-Type': 'application/json',
          },
          body: jsonEncode(payload),
        )
        .timeout(requestTimeout);
    _nazaBookforgeCheck(response, 'publish $path');
    final Map<String, dynamic> body =
        jsonDecode(response.body) as Map<String, dynamic>;
    final Map<String, dynamic> content =
        body['content'] as Map<String, dynamic>? ?? <String, dynamic>{};
    return Uri.parse(
      content['html_url'] as String? ??
          'https://github.com/${target.fullName}/blob/${target.branch}/$path',
    );
  }

  void _nazaBookforgeCheck(http.Response response, String action) {
    if (response.statusCode >= 200 && response.statusCode < 300) return;
    String message = response.body;
    try {
      message =
          (jsonDecode(response.body) as Map<String, dynamic>)['message']
              as String? ??
          message;
    } catch (_) {}
    throw StateError('Could not $action (${response.statusCode}): $message');
  }

  static void _nazaBookforgeValidateTarget(RepositoryTarget target) {
    final owner = target.owner.trim();
    final repository = target.name.trim();
    final branch = target.branch.trim();
    if (!RegExp(r'^[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})$').hasMatch(owner) ||
        !RegExp(r'^[A-Za-z0-9][A-Za-z0-9._-]{0,99}$').hasMatch(repository)) {
      throw const FormatException('GitHub repository identity is malformed.');
    }
    if (branch.isEmpty ||
        branch.length > 255 ||
        !RegExp(r'^[A-Za-z0-9._/-]+$').hasMatch(branch) ||
        branch.startsWith('/') ||
        branch.endsWith('/') ||
        branch.contains('..') ||
        branch.contains('//') ||
        branch.contains('@{') ||
        branch.endsWith('.lock')) {
      throw const FormatException('GitHub branch identity is malformed.');
    }
  }

  static void _nazaBookforgeValidateRepositoryPath(String raw) {
    final path = raw.trim();
    final segments = path.split('/');
    if (path.isEmpty ||
        path.length > 512 ||
        path.startsWith('/') ||
        path.endsWith('/') ||
        path.contains('\\') ||
        path.contains(RegExp(r'[\u0000-\u001F\u007F]')) ||
        segments.any(
          (segment) =>
              segment.isEmpty ||
              segment == '.' ||
              segment == '..' ||
              segment.length > 160,
        )) {
      throw const FormatException('Repository path is malformed.');
    }
  }

  String _nazaBookforgeSlug(String value) {
    final String slug = value
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '-')
        .replaceAll(RegExp(r'^-+|-+$'), '')
        .replaceAll(RegExp(r'-{2,}'), '-');
    if (slug.isNotEmpty) return slug;
    var hash = 2166136261;
    for (final int byte in utf8.encode(value)) {
      hash ^= byte;
      hash = (hash * 16777619) & 0x7fffffff;
    }
    return 'book-$hash';
  }

  // Front matter is deliberately emitted with a strict double-quoted scalar.
  // Normalizing line breaks and control characters first prevents user data
  // from terminating a YAML field or introducing a new mapping key. Escaping
  // backslashes before quotes also avoids YAML escape-sequence confusion.
  String _nazaBookforgeYamlDoubleQuoted(String value) {
    final String oneLine = value
        .replaceAll(RegExp(r'[\u0000-\u001F\u007F]'), ' ')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
    return oneLine.replaceAll('\\', '\\\\').replaceAll('"', '\\"');
  }
}

typedef NazaBookCompletion =
    Future<String> Function({
      required String systemInstruction,
      required String prompt,
      void Function(String text)? onPartial,
    });

final class GenerationCancellationToken {
  bool _nazaBookforgeCancelled = false;
  bool get isCancelled => _nazaBookforgeCancelled;
  void cancel() => _nazaBookforgeCancelled = true;
}

class GenerationService {
  static const Set<String> allowedApiHosts = <String>{'api.openai.com'};
  static const Duration requestTimeout = Duration(seconds: 90);

  GenerationService({http.Client? client, this.completion})
    : _nazaBookforgeClient = client ?? http.Client();
  final http.Client _nazaBookforgeClient;
  NazaBookCompletion? completion;

  /// Validates the egress boundary before an API key is attached. Custom
  /// endpoints remain usable for keyless/local providers, but an OpenAI key
  /// is never sent to an arbitrary host, plaintext transport, or non-default
  /// port. Redirects are also disabled in [_complete].
  static void validateApiKeyEndpoint(Uri uri) {
    if (uri.scheme != 'https' ||
        !allowedApiHosts.contains(uri.host.toLowerCase()) ||
        (uri.hasPort && uri.port != 443)) {
      throw ArgumentError(
        'API-key generation requires https://api.openai.com on port 443.',
      );
    }
  }

  Stream<GenerationProgress> generate({
    required GenerationRequest request,
    required String endpoint,
    required String model,
    required String apiKey,
    required void Function(String markdown) onDraft,
    void Function(String text)? onPartial,
    GenerationCancellationToken? cancellation,
  }) async* {
    void checkCancelled() {
      if (cancellation?.isCancelled == true) {
        throw const NazaBookGenerationCancelled();
      }
    }

    checkCancelled();
    final int total = request.chapterCount + 1;
    yield GenerationProgress(
      completed: 0,
      total: total,
      phase: 'Designing the book',
    );
    final String outline = await _nazaBookforgeComplete(
      endpoint: endpoint,
      model: model,
      apiKey: apiKey,
      system:
          'You are a rigorous book architect. Return only a numbered chapter outline with concise chapter purposes.',
      prompt:
          '''Create ${request.chapterCount} chapters for "${request.title}".
Premise: ${request.premise}
Audience: ${request.audience}
Voice: ${request.voice}
Depth: ${request.depth}
Every chapter must make a distinct intellectual contribution.''',
      onPartial: onPartial,
    );
    checkCancelled();
    final List<String> titles = _nazaBookforgeParseOutline(
      outline,
      request.chapterCount,
    );
    final List<String> chapters = <String>[];
    onDraft(_nazaBookforgeAssemble(request.title, titles, chapters));

    for (int index = 0; index < titles.length; index++) {
      checkCancelled();
      String chapter = await _nazaBookforgeComplete(
        endpoint: endpoint,
        model: model,
        apiKey: apiKey,
        system:
            'Write advanced, original nonfiction in Markdown. Explain how and why. Avoid filler and fabricated citations.',
        prompt:
            '''Book: ${request.title}
Premise: ${request.premise}
Audience: ${request.audience}
Voice: ${request.voice}
Depth: ${request.depth}
Outline:
${titles.asMap().entries.map((MapEntry<int, String> entry) => '${entry.key + 1}. ${entry.value}').join('\n')}

Write chapter ${index + 1}: ${titles[index]}.
Use a chapter heading, clear subsections, concrete examples, technical details, and a practical synthesis.${request.includeExercises ? '\nInclude three exercises.' : ''}${request.includeSources ? '\nAdd a Sources to Verify section with search targets, never invented citations.' : ''}''',
        onPartial: onPartial,
      );
      chapter = chapter.trim();
      if (chapter.isEmpty) {
        chapter = await _nazaBookforgeComplete(
          endpoint: endpoint,
          model: model,
          apiKey: apiKey,
          system: 'Write the missing chapter now in Markdown.',
          prompt:
              'Write chapter ${index + 1}: ${titles[index]} for ${request.title}.',
          onPartial: onPartial,
        );
      }
      var continuation = 0;
      while (_nazaBookforgeWordCount(chapter) < request.chapterWordTarget &&
          continuation < 4) {
        checkCancelled();
        continuation++;
        final remaining =
            request.chapterWordTarget - _nazaBookforgeWordCount(chapter);
        final String context = chapter.length > 12000
            ? chapter.substring(chapter.length - 12000)
            : chapter;
        final addition = await _nazaBookforgeComplete(
          endpoint: endpoint,
          model: model,
          apiKey: apiKey,
          system:
              'Continue the same chapter seamlessly. Return only new prose, no repeated heading or preamble.',
          prompt:
              'Continue chapter ${index + 1} of ${request.title}. Current word count: ${_nazaBookforgeWordCount(chapter)}. Add about $remaining words while preserving continuity. Use this bounded tail for continuity:\n$context',
          onPartial: onPartial,
        );
        if (addition.trim().isEmpty) break;
        chapter = '$chapter\n\n${addition.trim()}';
      }
      chapters.add(chapter);
      onDraft(_nazaBookforgeAssemble(request.title, titles, chapters));
      yield GenerationProgress(
        completed: index + 1,
        total: total,
        phase: 'Writing chapter ${index + 1} of ${titles.length}',
      );
    }
    yield GenerationProgress(
      completed: total,
      total: total,
      phase: 'Draft complete',
    );
  }

  int _nazaBookforgeWordCount(String value) =>
      RegExp(r"\b[\w’'-]+\b").allMatches(value).length;

  String _nazaBookforgeAssemble(
    String title,
    List<String> outline,
    List<String> chapters,
  ) {
    final String toc = outline
        .asMap()
        .entries
        .map(
          (MapEntry<int, String> entry) => '${entry.key + 1}. ${entry.value}',
        )
        .join('\n');
    return '# $title\n\n## Table of Contents\n\n$toc\n\n${chapters.join('\n\n---\n\n')}';
  }

  Future<String> _nazaBookforgeComplete({
    required String endpoint,
    required String model,
    required String apiKey,
    required String system,
    required String prompt,
    void Function(String text)? onPartial,
  }) async {
    if (completion != null) {
      return completion!(
        systemInstruction: system,
        prompt: prompt,
        onPartial: onPartial,
      );
    }
    final Uri uri = Uri.parse(
      endpoint.trim().isEmpty
          ? 'https://api.openai.com/v1/chat/completions'
          : endpoint.trim(),
    );
    final String trimmedKey = apiKey.trim();
    if (trimmedKey.isNotEmpty) validateApiKeyEndpoint(uri);
    final http.Request request = http.Request('POST', uri)
      ..followRedirects = false
      ..headers.addAll(<String, String>{
        'Content-Type': 'application/json',
        if (trimmedKey.isNotEmpty) 'Authorization': 'Bearer $trimmedKey',
      })
      ..body = jsonEncode(<String, Object?>{
        'model': model,
        'messages': <Map<String, String>>[
          <String, String>{'role': 'system', 'content': system},
          <String, String>{'role': 'user', 'content': prompt},
        ],
      });
    final http.StreamedResponse streamed = await _nazaBookforgeClient
        .send(request)
        .timeout(requestTimeout);
    final http.Response response = await http.Response.fromStream(streamed);
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw StateError(
        'Generation failed (${response.statusCode}): ${response.body}',
      );
    }
    final Map<String, dynamic> data =
        jsonDecode(response.body) as Map<String, dynamic>;
    final List<dynamic> choices =
        data['choices'] as List<dynamic>? ?? <dynamic>[];
    if (choices.isEmpty)
      throw const FormatException('The model returned no choices.');
    final Map<String, dynamic> choice = choices.first as Map<String, dynamic>;
    final Map<String, dynamic> message =
        choice['message'] as Map<String, dynamic>? ?? <String, dynamic>{};
    return message['content'] as String? ?? '';
  }

  List<String> _nazaBookforgeParseOutline(String outline, int count) {
    final List<String> titles = outline
        .split('\n')
        .map(
          (String line) => line
              .replaceFirst(
                RegExp(
                  r'^\s*(?:chapter\s*)?\d+[.):\-]\s*',
                  caseSensitive: false,
                ),
                '',
              )
              .trim(),
        )
        .where((String line) => line.isNotEmpty)
        .take(count)
        .toList();
    while (titles.length < count) {
      titles.add('Chapter ${titles.length + 1}');
    }
    return titles;
  }
}

final class NazaBookGenerationCancelled implements Exception {
  const NazaBookGenerationCancelled();

  @override
  String toString() => 'Book generation was cancelled.';
}

