class StudioScreen extends StatefulWidget {
  const StudioScreen({super.key, this.completion, this.initialPage = 0});

  final NazaBookCompletion? completion;
  final int initialPage;

  @override
  State<StudioScreen> createState() => _NazaBookforgeStudioScreenState();
}

class _NazaBookforgeStudioScreenState extends State<StudioScreen> {
  final LibraryStore _nazaBookforgeStore = LibraryStore();
  final ImportService _nazaBookforgeImporter = ImportService();
  final GitHubService _nazaBookforgeGithub = GitHubService();
  late final GenerationService _nazaBookforgeGeneration = GenerationService(
    completion: widget.completion,
  );

  final TextEditingController _nazaBookforgeSearch = TextEditingController();
  final TextEditingController _nazaBookforgeEditor = TextEditingController();
  final TextEditingController _nazaBookforgeGithubToken =
      TextEditingController();
  final TextEditingController _nazaBookforgeApiKey = TextEditingController();
  final TextEditingController _nazaBookforgeEndpoint = TextEditingController(
    text: 'https://api.openai.com/v1/chat/completions',
  );
  final TextEditingController _nazaBookforgeModel = TextEditingController(
    text: 'gpt-5-mini',
  );
  final BookProvider _nazaBookforgeProvider = BookProvider.gemma4;
  final TextEditingController _nazaBookforgeOwner = TextEditingController(
    text: 'ornab74',
  );
  final TextEditingController _nazaBookforgeRepo = TextEditingController(
    text: 'books',
  );
  final TextEditingController _nazaBookforgeBranch = TextEditingController(
    text: 'main',
  );
  final TextEditingController _nazaBookforgeDirectory = TextEditingController(
    text: 'generated',
  );

  List<BookDocument> _nazaBookforgeBooks = <BookDocument>[];
  List<RepositoryBook> _nazaBookforgeRemoteBooks = <RepositoryBook>[];
  BookDocument? _nazaBookforgeSelected;
  Timer? _nazaBookforgeSaveTimer;
  Timer? _nazaBookforgeEditorUiTimer;
  Future<void> _nazaBookforgeSaveQueue = Future<void>.value();
  int _nazaBookforgeSaveRevision = 0;
  late int _nazaBookforgePage = widget.initialPage.clamp(0, 2);
  bool _nazaBookforgeLoading = true;
  bool _nazaBookforgeSaving = false;
  bool _nazaBookforgeBusy = false;
  bool _nazaBookforgePreview = true;
  GenerationProgress? _nazaBookforgeProgress;
  String _nazaBookforgeStreamingText = '';
  String _nazaBookforgePendingStreamText = '';
  Timer? _nazaBookforgeStreamPaintTimer;
  GenerationCancellationToken? _nazaBookforgeGenerationCancellation;
  int _nazaBookforgeGenerationSerial = 0;

  RepositoryTarget get _nazaBookforgeTarget => RepositoryTarget(
    owner: _nazaBookforgeOwner.text.trim(),
    name: _nazaBookforgeRepo.text.trim(),
    branch: _nazaBookforgeBranch.text.trim().isEmpty
        ? 'main'
        : _nazaBookforgeBranch.text.trim(),
    directory: _nazaBookforgeDirectory.text.trim(),
  );

  @override
  void initState() {
    super.initState();
    _nazaBookforgeSearch.addListener(_nazaBookforgeRefresh);
    _nazaBookforgeEditor.addListener(_nazaBookforgeEditorChanged);
    _nazaBookforgeLoad();
  }

  @override
  void dispose() {
    _nazaBookforgeSaveTimer?.cancel();
    _nazaBookforgeEditorUiTimer?.cancel();
    _nazaBookforgeStreamPaintTimer?.cancel();
    _nazaBookforgeGenerationCancellation?.cancel();
    for (final TextEditingController controller in <TextEditingController>[
      _nazaBookforgeSearch,
      _nazaBookforgeEditor,
      _nazaBookforgeGithubToken,
      _nazaBookforgeApiKey,
      _nazaBookforgeEndpoint,
      _nazaBookforgeModel,
      _nazaBookforgeOwner,
      _nazaBookforgeRepo,
      _nazaBookforgeBranch,
      _nazaBookforgeDirectory,
    ]) {
      controller.dispose();
    }
    super.dispose();
  }

  void _nazaBookforgeRefresh() {
    if (mounted) setState(() {});
  }

  Future<void> _nazaBookforgeLoad() async {
    List<BookDocument> books = <BookDocument>[];
    try {
      books = await _nazaBookforgeStore.load();
    } catch (error) {
      _nazaBookforgeError(error);
    }
    try {
      final Object? savedGitHubToken = await NazaSecureDatabase.instance
          .readJson('bookforge', 'github-token');
      if (savedGitHubToken is String && savedGitHubToken.isNotEmpty) {
        _nazaBookforgeGithubToken.text = savedGitHubToken;
      }
      final Object? savedKey = await NazaSecureDatabase.instance.readJson(
        'bookforge',
        'openai-api-key',
      );
      if (savedKey is String && savedKey.isNotEmpty)
        _nazaBookforgeApiKey.text = savedKey;
      final Object? savedModel = await NazaSecureDatabase.instance.readJson(
        'bookforge',
        'openai-model',
      );
      if (savedModel is String && savedModel.isNotEmpty)
        _nazaBookforgeModel.text = savedModel;
      final Object? savedEndpoint = await NazaSecureDatabase.instance.readJson(
        'bookforge',
        'openai-endpoint',
      );
      if (savedEndpoint is String && savedEndpoint.isNotEmpty)
        _nazaBookforgeEndpoint.text = savedEndpoint;
    } catch (_) {
      // The vault may still be locked during first paint; the key remains editable.
    }
    if (!mounted) return;
    setState(() {
      _nazaBookforgeBooks = books;
      _nazaBookforgeLoading = false;
      _nazaBookforgeSelected = books.isEmpty ? null : books.first;
      _nazaBookforgeEditor.text = _nazaBookforgeSelected?.content ?? '';
    });
  }

  void _nazaBookforgeSelect(BookDocument book) {
    if (_nazaBookforgeSelected?.id == book.id) return;
    // Selection can race with the editor's debounce callback. Detach the
    // listener while replacing the document so the incoming book is never
    // treated as an edit to the outgoing book.
    _nazaBookforgeEditor.removeListener(_nazaBookforgeEditorChanged);
    _nazaBookforgeEditor.text = book.content;
    _nazaBookforgeEditor.addListener(_nazaBookforgeEditorChanged);
    if (mounted) setState(() => _nazaBookforgeSelected = book);
  }

  void _nazaBookforgeEditorChanged() {
    final BookDocument? current = _nazaBookforgeSelected;
    if (current == null || current.content == _nazaBookforgeEditor.text) return;
    final int index = _nazaBookforgeBooks.indexWhere(
      (BookDocument book) => book.id == current.id,
    );
    if (index < 0) return;
    if (index < 0) return;
    final BookDocument updated = current.copyWith(
      content: _nazaBookforgeEditor.text,
      status: BookStatus.draft,
      updatedAt: DateTime.now(),
    );
    _nazaBookforgeBooks[index] = updated;
    _nazaBookforgeSelected = updated;
    // Do not rebuild the complete library/Markdown tree for every keystroke.
    // The editor owns its text rendering; header/status refresh is throttled.
    if (!_nazaBookforgeSaving && mounted)
      setState(() => _nazaBookforgeSaving = true);
    _nazaBookforgeEditorUiTimer?.cancel();
    _nazaBookforgeEditorUiTimer = Timer(const Duration(milliseconds: 120), () {
      if (mounted) setState(() {});
    });
    _nazaBookforgeSaveTimer?.cancel();
    _nazaBookforgeSaveTimer = Timer(const Duration(milliseconds: 600), () {
      unawaited(_nazaBookforgeQueueSaveBook(updated));
    });
  }

  Future<void> _nazaBookforgeQueueSaveBook(BookDocument book) {
    final int revision = ++_nazaBookforgeSaveRevision;
    _nazaBookforgeSaveQueue = _nazaBookforgeSaveQueue.then((_) async {
      try {
        await _nazaBookforgeStore.saveBook(book);
        if (mounted && revision == _nazaBookforgeSaveRevision) {
          setState(() => _nazaBookforgeSaving = false);
        }
      } catch (error) {
        if (mounted && revision == _nazaBookforgeSaveRevision) {
          setState(() => _nazaBookforgeSaving = false);
          _nazaBookforgeError(error);
        }
      }
    });
    return _nazaBookforgeSaveQueue;
  }

  Future<void> _nazaBookforgeImport() async {
    try {
      final BookDocument? book = await _nazaBookforgeImporter.pickAndImport();
      if (book == null) return;
      setState(() {
        _nazaBookforgeBooks.insert(0, book);
        _nazaBookforgePage = 0;
      });
      _nazaBookforgeSelect(book);
      await _nazaBookforgeStore.saveBook(book);
    } catch (error) {
      _nazaBookforgeError(error);
    }
  }

  Future<void> _nazaBookforgeNewBook() async {
    final DateTime now = DateTime.now();
    final BookDocument book = BookDocument(
      id: now.microsecondsSinceEpoch.toString(),
      title: 'Untitled Book',
      author: 'Unknown author',
      content: '# Untitled Book\n\nBegin writing here.\n',
      format: BookFormat.markdown,
      origin: BookOrigin.local,
      status: BookStatus.draft,
      createdAt: now,
      updatedAt: now,
    );
    setState(() {
      _nazaBookforgeBooks.insert(0, book);
      _nazaBookforgePage = 0;
    });
    _nazaBookforgeSelect(book);
    await _nazaBookforgeStore.saveBooks(_nazaBookforgeBooks);
  }

  Future<void> _nazaBookforgeEditMetadata() async {
    final BookDocument? current = _nazaBookforgeSelected;
    if (current == null) return;
    final TextEditingController title = TextEditingController(
      text: current.title,
    );
    final TextEditingController author = TextEditingController(
      text: current.author,
    );
    final bool? save = await showDialog<bool>(
      context: context,
      builder: (BuildContext context) => AlertDialog(
        title: const Text('Book metadata'),
        content: SizedBox(
          width: 420,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: <Widget>[
              TextField(
                controller: title,
                decoration: const InputDecoration(labelText: 'Title'),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: author,
                decoration: const InputDecoration(labelText: 'Author'),
              ),
            ],
          ),
        ),
        actions: <Widget>[
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Save'),
          ),
        ],
      ),
    );
    if (save != true || !mounted) return;
    final int index = _nazaBookforgeBooks.indexWhere(
      (BookDocument book) => book.id == current.id,
    );
    final BookDocument updated = current.copyWith(
      title: title.text.trim().isEmpty ? current.title : title.text.trim(),
      author: author.text.trim().isEmpty ? current.author : author.text.trim(),
      updatedAt: DateTime.now(),
    );
    setState(() {
      _nazaBookforgeBooks[index] = updated;
      _nazaBookforgeSelected = updated;
    });
    await _nazaBookforgeStore.saveBook(updated);
  }

  Future<void> _nazaBookforgeDelete() async {
    final BookDocument? current = _nazaBookforgeSelected;
    if (current == null) return;
    final bool? confirmed = await showDialog<bool>(
      context: context,
      builder: (BuildContext context) => AlertDialog(
        title: const Text('Delete local copy?'),
        content: Text(
          'Remove “${current.title}” from the local BookForge library?',
        ),
        actions: <Widget>[
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Delete'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    setState(() {
      _nazaBookforgeBooks.removeWhere(
        (BookDocument book) => book.id == current.id,
      );
      _nazaBookforgeSelected = _nazaBookforgeBooks.isEmpty
          ? null
          : _nazaBookforgeBooks.first;
    });
    _nazaBookforgeEditor.removeListener(_nazaBookforgeEditorChanged);
    _nazaBookforgeEditor.text = _nazaBookforgeSelected?.content ?? '';
    _nazaBookforgeEditor.addListener(_nazaBookforgeEditorChanged);
    await _nazaBookforgeStore.deleteBook(current, _nazaBookforgeBooks);
  }

  Future<void> _nazaBookforgeScan() async {
    if (_nazaBookforgeTarget.owner.isEmpty ||
        _nazaBookforgeTarget.name.isEmpty) {
      _nazaBookforgeError('Repository owner and name are required.');
      return;
    }
    setState(() => _nazaBookforgeBusy = true);
    try {
      final List<RepositoryBook> books = await _nazaBookforgeGithub.scanBooks(
        _nazaBookforgeTarget,
        token: _nazaBookforgeGithubToken.text,
      );
      if (!mounted) return;
      setState(() => _nazaBookforgeRemoteBooks = books);
      _nazaBookforgeMessage('Found ${books.length} readable files.');
    } catch (error) {
      _nazaBookforgeError(error);
    } finally {
      if (mounted) setState(() => _nazaBookforgeBusy = false);
    }
  }

  Future<void> _nazaBookforgeDownload(RepositoryBook remote) async {
    setState(() => _nazaBookforgeBusy = true);
    try {
      final BookDocument book = await _nazaBookforgeGithub.downloadBook(
        _nazaBookforgeTarget,
        remote,
        token: _nazaBookforgeGithubToken.text,
      );
      final int index = _nazaBookforgeBooks.indexWhere(
        (BookDocument item) =>
            item.repository == book.repository &&
            item.sourcePath == book.sourcePath,
      );
      if (index >= 0) {
        _nazaBookforgeBooks[index] = book;
      } else {
        _nazaBookforgeBooks.insert(0, book);
      }
      setState(() => _nazaBookforgePage = 0);
      _nazaBookforgeSelect(
        index >= 0 ? _nazaBookforgeBooks[index] : _nazaBookforgeBooks.first,
      );
      await _nazaBookforgeStore.saveBooks(_nazaBookforgeBooks);
    } catch (error) {
      _nazaBookforgeError(error);
    } finally {
      if (mounted) setState(() => _nazaBookforgeBusy = false);
    }
  }

  Future<void> _nazaBookforgePublish() async {
    final BookDocument? current = _nazaBookforgeSelected;
    if (current == null) return;
    setState(() => _nazaBookforgeBusy = true);
    try {
      final Uri uri = await _nazaBookforgeGithub.publishMarkdown(
        target: _nazaBookforgeTarget,
        book: current,
        token: _nazaBookforgeGithubToken.text,
      );
      final int index = _nazaBookforgeBooks.indexWhere(
        (BookDocument book) => book.id == current.id,
      );
      final BookDocument published = current.copyWith(
        status: BookStatus.published,
        repository: _nazaBookforgeTarget.fullName,
        updatedAt: DateTime.now(),
      );
      setState(() {
        _nazaBookforgeBooks[index] = published;
        _nazaBookforgeSelected = published;
      });
      await _nazaBookforgeStore.saveBook(published);
      _nazaBookforgeMessage('Published: $uri');
    } catch (error) {
      _nazaBookforgeError(error);
    } finally {
      if (mounted) setState(() => _nazaBookforgeBusy = false);
    }
  }

  Future<void> _nazaBookforgeGenerate(GenerationRequest request) async {
    final int generationId = ++_nazaBookforgeGenerationSerial;
    if (_nazaBookforgeProvider == BookProvider.gpt56Luna &&
        _nazaBookforgeApiKey.text.trim().isEmpty) {
      _nazaBookforgeError('Add an API key in Settings before generating.');
      return;
    }
    _nazaBookforgeGeneration.completion =
        _nazaBookforgeProvider == BookProvider.gemma4
        ? widget.completion
        : null;
    final cancellation = GenerationCancellationToken();
    _nazaBookforgeGenerationCancellation?.cancel();
    _nazaBookforgeGenerationCancellation = cancellation;
    final DateTime now = DateTime.now();
    BookDocument draft = BookDocument(
      id: 'generated-${now.microsecondsSinceEpoch}',
      title: request.title,
      author: 'Unknown author',
      content: '# ${request.title}\n\nDesigning the manuscript…',
      format: BookFormat.markdown,
      origin: BookOrigin.generated,
      status: BookStatus.draft,
      createdAt: now,
      updatedAt: now,
      tags: <String>['generated', request.depth.toLowerCase()],
    );
    setState(() {
      _nazaBookforgeBooks.insert(0, draft);
      _nazaBookforgePage = 0;
      _nazaBookforgeBusy = true;
      _nazaBookforgeProgress = const GenerationProgress(
        completed: 0,
        total: 1,
        phase: 'Starting',
      );
      _nazaBookforgeStreamingText = 'Gemma is preparing the outline...\n\n';
      _nazaBookforgePage = 4;
    });
    _nazaBookforgeSelect(draft);
    await _nazaBookforgeQueueSaveBook(draft);
    try {
      final Stream<GenerationProgress> stream = _nazaBookforgeGeneration
          .generate(
            request: request,
            endpoint: _nazaBookforgeEndpoint.text,
            model: _nazaBookforgeProvider == BookProvider.gpt56Luna
                ? _nazaBookforgeModel.text.trim()
                : _nazaBookforgeModel.text.trim(),
            apiKey: _nazaBookforgeApiKey.text,
            cancellation: cancellation,
            onDraft: (String markdown) {
              if (generationId != _nazaBookforgeGenerationSerial) return;
              final int index = _nazaBookforgeBooks.indexWhere(
                (BookDocument book) => book.id == draft.id,
              );
              if (index < 0 || !mounted) return;
              draft = draft.copyWith(
                content: markdown,
                updatedAt: DateTime.now(),
              );
              _nazaBookforgeEditor.removeListener(_nazaBookforgeEditorChanged);
              _nazaBookforgeEditor.text = markdown;
              _nazaBookforgeEditor.addListener(_nazaBookforgeEditorChanged);
              setState(() {
                _nazaBookforgeBooks[index] = draft;
                _nazaBookforgeSelected = draft;
                _nazaBookforgeStreamingText = markdown;
              });
              unawaited(_nazaBookforgeQueueSaveBook(draft));
            },
            onPartial: (String text) {
              if (!mounted || generationId != _nazaBookforgeGenerationSerial)
                return;
              _nazaBookforgePendingStreamText = text;
              if (_nazaBookforgeStreamPaintTimer?.isActive ?? false) return;
              _nazaBookforgeStreamPaintTimer = Timer(
                const Duration(milliseconds: 90),
                () {
                  if (mounted)
                    setState(
                      () => _nazaBookforgeStreamingText =
                          _nazaBookforgePendingStreamText,
                    );
                },
              );
            },
          );
      await for (final GenerationProgress progress in stream) {
        if (mounted && generationId == _nazaBookforgeGenerationSerial) {
          setState(() => _nazaBookforgeProgress = progress);
        }
      }
      await _nazaBookforgeQueueSaveBook(draft);
      _nazaBookforgeMessage('Generated draft complete.');
    } catch (error) {
      _nazaBookforgeError(error);
    } finally {
      if (mounted) setState(() => _nazaBookforgeBusy = false);
    }
  }

  void _nazaBookforgeError(Object error) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(error.toString()),
        backgroundColor: Theme.of(context).colorScheme.error,
      ),
    );
  }

  void _nazaBookforgeMessage(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(SnackBar(content: Text(message)));
  }

  List<BookDocument> get _nazaBookforgeVisibleBooks {
    final String query = _nazaBookforgeSearch.text.trim().toLowerCase();
    if (query.isEmpty) return _nazaBookforgeBooks;
    return _nazaBookforgeBooks.where((BookDocument book) {
      return book.title.toLowerCase().contains(query) ||
          book.author.toLowerCase().contains(query) ||
          book.tags.any((String tag) => tag.toLowerCase().contains(query));
    }).toList();
  }

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final compact = constraints.maxWidth < 700;
        final content = _nazaBookforgePageBody();
        return Scaffold(
          body: SafeArea(
            child: compact
                ? content
                : Row(
                    children: <Widget>[
                      NavigationRail(
                        selectedIndex: _nazaBookforgePage == 4
                            ? 1
                            : (_nazaBookforgePage >= 0 && _nazaBookforgePage < 4
                                  ? _nazaBookforgePage
                                  : 0),
                        onDestinationSelected: (int value) =>
                            setState(() => _nazaBookforgePage = value),
                        labelType: NavigationRailLabelType.all,
                        leading: Padding(
                          padding: const EdgeInsets.only(bottom: 18),
                          child: Container(
                            width: 46,
                            height: 46,
                            decoration: BoxDecoration(
                              gradient: const LinearGradient(
                                colors: <Color>[
                                  Color(0xFF9A7CFF),
                                  Color(0xFF4D7DFF),
                                ],
                              ),
                              borderRadius: BorderRadius.circular(14),
                            ),
                            child: const Icon(
                              Icons.menu_book_rounded,
                              color: Colors.white,
                            ),
                          ),
                        ),
                        destinations: const <NavigationRailDestination>[
                          NavigationRailDestination(
                            icon: Icon(Icons.auto_stories_outlined),
                            selectedIcon: Icon(Icons.auto_stories),
                            label: Text('Library'),
                          ),
                          NavigationRailDestination(
                            icon: Icon(Icons.auto_awesome_outlined),
                            selectedIcon: Icon(Icons.auto_awesome),
                            label: Text('Generate'),
                          ),
                          NavigationRailDestination(
                            icon: Icon(Icons.cloud_outlined),
                            selectedIcon: Icon(Icons.cloud),
                            label: Text('Repository'),
                          ),
                        ],
                      ),
                      const VerticalDivider(width: 1, color: Color(0xFF202632)),
                      Expanded(child: content),
                    ],
                  ),
          ),
          bottomNavigationBar: compact
              ? NavigationBar(
                  selectedIndex: _nazaBookforgePage == 4
                      ? 1
                      : _nazaBookforgePage.clamp(0, 2),
                  onDestinationSelected: (value) =>
                      setState(() => _nazaBookforgePage = value),
                  destinations: const [
                    NavigationDestination(
                      icon: Icon(Icons.auto_stories_outlined),
                      selectedIcon: Icon(Icons.auto_stories),
                      label: 'Library',
                    ),
                    NavigationDestination(
                      icon: Icon(Icons.auto_awesome_outlined),
                      selectedIcon: Icon(Icons.auto_awesome),
                      label: 'Generate',
                    ),
                    NavigationDestination(
                      icon: Icon(Icons.cloud_outlined),
                      selectedIcon: Icon(Icons.cloud),
                      label: 'Repository',
                    ),
                  ],
                )
              : null,
        );
      },
    );
  }

  Widget _nazaBookforgePageBody() {
    return switch (_nazaBookforgePage) {
      0 => _nazaBookforgeLibrary(),
      1 => GeneratorPanel(
        onGenerate: _nazaBookforgeGenerate,
        busy: _nazaBookforgeBusy,
      ),
      2 => RepositoryPanel(
        owner: _nazaBookforgeOwner,
        repo: _nazaBookforgeRepo,
        branch: _nazaBookforgeBranch,
        directory: _nazaBookforgeDirectory,
        books: _nazaBookforgeRemoteBooks,
        busy: _nazaBookforgeBusy,
        onScan: _nazaBookforgeScan,
        onOpen: _nazaBookforgeDownload,
      ),
      4 => _nazaBookforgeLiveGenerationPage(),
      _ => _nazaBookforgeLibrary(),
    };
  }

  Widget _nazaBookforgeLiveGenerationPage() {
    final GenerationProgress? progress = _nazaBookforgeProgress;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: <Widget>[
        Row(
          children: <Widget>[
            const Icon(Icons.auto_awesome, color: Color(0xFF7C5CFC)),
            const SizedBox(width: 10),
            Expanded(
              child: Text(
                progress?.phase ?? 'Preparing Gemma',
                style: const TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.w700,
                ),
              ),
            ),
            TextButton.icon(
              onPressed: () => setState(() => _nazaBookforgePage = 0),
              icon: const Icon(Icons.menu_book),
              label: const Text('Library'),
            ),
          ],
        ),
        if (progress != null) LinearProgressIndicator(value: progress.fraction),
        const SizedBox(height: 12),
