    required this.owner,
    required this.repo,
    required this.branch,
    required this.directory,
    required this.books,
    required this.busy,
    required this.onScan,
    required this.onOpen,
  });

  final TextEditingController owner;
  final TextEditingController repo;
  final TextEditingController branch;
  final TextEditingController directory;
  final List<RepositoryBook> books;
  final bool busy;
  final VoidCallback onScan;
  final ValueChanged<RepositoryBook> onOpen;

  @override
  Widget build(BuildContext context) {
    final bool compact = MediaQuery.sizeOf(context).width < 760;
    final double compactFieldWidth = (MediaQuery.sizeOf(context).width - 68)
        .clamp(220.0, 900.0);
    return Padding(
      padding: EdgeInsets.all(compact ? 16 : 30),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          const Text(
            'Repository library',
            style: TextStyle(fontSize: 30, fontWeight: FontWeight.w900),
          ),
          const SizedBox(height: 8),
          const Text(
            'Recursively scan a GitHub repository, import its books, and publish edited Markdown editions.',
            style: TextStyle(color: Color(0xFF8A94A6)),
          ),
          const SizedBox(height: 24),
          Card(
            child: Padding(
              padding: const EdgeInsets.all(18),
              child: Wrap(
                spacing: 12,
                runSpacing: 12,
                children: <Widget>[
                  SizedBox(
                    width: compact ? compactFieldWidth : 180,
                    child: TextField(
                      controller: owner,
                      decoration: const InputDecoration(labelText: 'Owner'),
                    ),
                  ),
                  SizedBox(
                    width: compact ? compactFieldWidth : 180,
                    child: TextField(
                      controller: repo,
                      decoration: const InputDecoration(
                        labelText: 'Repository',
                      ),
                    ),
                  ),
                  SizedBox(
                    width: compact ? compactFieldWidth : 140,
                    child: TextField(
                      controller: branch,
                      decoration: const InputDecoration(labelText: 'Branch'),
                    ),
                  ),
                  SizedBox(
                    width: compact ? compactFieldWidth : 165,
                    child: TextField(
                      controller: directory,
                      decoration: const InputDecoration(
                        labelText: 'Publish folder',
                      ),
                    ),
                  ),
                  FilledButton.icon(
                    onPressed: busy ? null : onScan,
                    icon: busy
                        ? const SizedBox.square(
                            dimension: 17,
                            child: CircularProgressIndicator(strokeWidth: 2),
                          )
                        : const Icon(Icons.radar),
                    label: const Text('Scan'),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 18),
          Expanded(
            child: books.isEmpty
                ? const EmptyPanel(
                    icon: Icons.account_tree_outlined,
                    title: 'Repository not scanned',
                    body:
                        'Scan ornab74/books or another repository to catalog Markdown, text, and DOCX files.',
                  )
                : Card(
                    child: ListView.separated(
                      padding: const EdgeInsets.all(10),
                      itemCount: books.length,
                      separatorBuilder: (_, _) => const Divider(height: 1),
                      itemBuilder: (BuildContext context, int index) {
                        final RepositoryBook book = books[index];
                        return ListTile(
                          leading: Icon(
                            book.format == BookFormat.docx
                                ? Icons.description_outlined
                                : Icons.article_outlined,
                          ),
                          title: Text(book.name),
                          subtitle: Text(
                            '${book.path} · ${formatBytes(book.size)}',
                          ),
                          trailing: const Icon(Icons.download_rounded),
                          onTap: busy ? null : () => onOpen(book),
                        );
                      },
                    ),
                  ),
          ),
        ],
      ),
    );
  }

  String formatBytes(int bytes) {
    if (bytes > 1024 * 1024)
      return '${(bytes / (1024 * 1024)).toStringAsFixed(1)} MB';
    if (bytes > 1024) return '${(bytes / 1024).toStringAsFixed(1)} KB';
    return '$bytes B';
  }
}

