typedef NazaExplorePrompt =
    Future<String> Function({
      required String systemInstruction,
      required String prompt,
      Uint8List? imageBytes,
    });
typedef NazaExploreImagePicker = Future<NazaExploreImage?> Function();

final class NazaExploreImage {
  final String name;
  final Uint8List bytes;
  final int width;
  final int height;
  const NazaExploreImage({
    required this.name,
    required this.bytes,
    this.width = 1,
    this.height = 1,
  });
}

final class _NazaExplorationHubGardenLogEntry {
  final DateTime date;
  final String plant;
  final double height;
  final double width;
  final int health;
  final String kind;
  const _NazaExplorationHubGardenLogEntry({
    required this.date,
    required this.plant,
    required this.height,
    required this.width,
    required this.health,
    required this.kind,
  });
}

/// A bounded, transparent approximation of the six HeartFlow dimensions.
///
/// This is intentionally classical: it borrows the language of the supplied
/// HeartFlow concept (coupled dimensions and constructive/destructive
/// interaction), but it is not a quantum measurement, a financial score, or a
/// clinical instrument. Keeping the calculation local and explainable gives
/// the user a reproducible baseline before the language model adds context.
final class NazaHeartFlowSimulation {
  final double stewardship;
  final double compassion;
  final double creativity;
  final double greedDissipation;
  final double courage;
  final double harmony;
  final double coherence;
  final double score;

  const NazaHeartFlowSimulation({
    required this.stewardship,
    required this.compassion,
    required this.creativity,
    required this.greedDissipation,
    required this.courage,
    required this.harmony,
    required this.coherence,
    required this.score,
  });

  factory NazaHeartFlowSimulation.run({
    required String reflection,
    String? ageOrRange,
    String? restingBaseline,
  }) {
    final text = reflection.toLowerCase();
    double signal(List<String> terms, double base) {
      final hits = terms.where(text.contains).length;
      return _nazaExplorationHubClamp(base + hits * 0.07);
    }

    final stewardship = signal([
      'repair',
      'garden',
      'nature',
      'reuse',
      'waste',
      'community',
    ], 0.50);
    final compassion = signal([
      'help',
      'care',
      'listen',
      'mentor',
      'support',
      'food',
      'volunteer',
    ], 0.50);
    final creativity = signal([
      'learn',
      'make',
      'write',
      'build',
      'code',
      'art',
      'idea',
      'research',
    ], 0.50);
    final greedDissipation = signal([
      'share',
      'fair',
      'generous',
      'donate',
      'equitable',
      'enough',
    ], 0.50);
    final courage = signal([
      'truth',
      'speak',
      'boundary',
      'brave',
      'risk',
      'protect',
      'justice',
    ], 0.50);
    final harmony = signal([
      'rest',
      'sleep',
      'calm',
      'restore',
      'connect',
      'balance',
      'breath',
    ], 0.50);

    // Optional numeric context is treated as a weak signal only. It never
    // becomes a health judgment and malformed values are safely ignored.
    final baseline = double.tryParse(
      (restingBaseline ?? '').replaceAll(RegExp(r'[^0-9.]'), ''),
    );
    final baselineAdjustment = baseline == null
        ? 0.0
        : baseline >= 45 && baseline <= 100
        ? 0.03
        : -0.02;
    final adjustedHarmony = _nazaExplorationHubClamp(
      harmony + baselineAdjustment,
    );

    final dimensions = [
      stewardship,
      compassion,
      creativity,
      greedDissipation,
      courage,
      adjustedHarmony,
    ];
    final average = dimensions.reduce((a, b) => a + b) / dimensions.length;
    final spread =
        dimensions
            .map((value) => (value - average).abs())
            .reduce((a, b) => a + b) /
        dimensions.length;
    final coupling = _nazaExplorationHubClamp(1.0 - spread * 0.45);
    final ageSignal = (ageOrRange ?? '').trim().isEmpty ? 0.0 : 0.01;

    return NazaHeartFlowSimulation(
      stewardship: stewardship,
      compassion: compassion,
      creativity: creativity,
      greedDissipation: greedDissipation,
      courage: courage,
      harmony: adjustedHarmony,
      coherence: coupling,
      score: _nazaExplorationHubClamp(average * coupling + ageSignal),
    );
  }

  static double _nazaExplorationHubClamp(double value) =>
      value.clamp(0.0, 1.0).toDouble();

  String toPromptBlock() =>
      '''
LOCAL HEARTFLOW SIMULATION (classical approximation; not diagnosis or fact)
Stewardship Resonance: ${stewardship.toStringAsFixed(2)}
Compassion Throughput: ${compassion.toStringAsFixed(2)}
Creativity Flux: ${creativity.toStringAsFixed(2)}
Greed Dissipation: ${greedDissipation.toStringAsFixed(2)}
Courage Activation: ${courage.toStringAsFixed(2)}
Harmony Coherence: ${harmony.toStringAsFixed(2)}
Cross-dimension coherence: ${coherence.toStringAsFixed(2)}
HeartFlow index: ${score.toStringAsFixed(2)}
Interpret these as reflective signals with uncertainty. Do not rank, diagnose,
predict a person's worth, or infer missing identity or health information.
''';
}

enum NazaExplorationSection { findIt, garden, drive, predict, heartFlow }

extension NazaExplorationSectionX on NazaExplorationSection {
  String get label => switch (this) {
    NazaExplorationSection.findIt => 'Find It',
    NazaExplorationSection.garden => 'Garden',
    NazaExplorationSection.drive => 'Drive',
    NazaExplorationSection.predict => 'Predict',
    NazaExplorationSection.heartFlow => 'Heart Flow',
  };
  IconData get icon => switch (this) {
    NazaExplorationSection.findIt => Icons.travel_explore_rounded,
    NazaExplorationSection.garden => Icons.eco_rounded,
    NazaExplorationSection.drive => Icons.directions_car_rounded,
    NazaExplorationSection.predict => Icons.query_stats_rounded,
    NazaExplorationSection.heartFlow => Icons.favorite_rounded,
  };
}

class NazaExplorationHub extends StatefulWidget {
  const NazaExplorationHub({
    super.key,
    required this.runPrompt,
    required this.pickGardenImage,
    this.initialSection = NazaExplorationSection.findIt,
  });
  final NazaExplorePrompt runPrompt;
  final NazaExploreImagePicker pickGardenImage;
  final NazaExplorationSection initialSection;
  @override
  State<NazaExplorationHub> createState() =>
      _NazaExplorationHubNazaExplorationHubState();
}

class _NazaExplorationHubNazaExplorationHubState
    extends State<NazaExplorationHub> {
  static const int _nazaExplorationHubMaxGardenImages = 4;
  static const int _nazaExplorationHubMaxGardenBytes = 24 * 1024 * 1024;
  late final PageController _nazaExplorationHubPages = PageController(
    initialPage: widget.initialSection.index,
  );
  final Map<NazaExplorationSection, TextEditingController>
  _nazaExplorationHubDetails = {
    for (final section in NazaExplorationSection.values)
      section: TextEditingController(),
  };
  final _nazaExplorationHubFindLocation = TextEditingController(),
      _nazaExplorationHubDriveLocation = TextEditingController(),
      _nazaExplorationHubDriveDestination = TextEditingController();
  final _nazaExplorationHubPredictLocation = TextEditingController(),
      _nazaExplorationHubHeartName = TextEditingController(),
      _nazaExplorationHubHeartAge = TextEditingController(),
      _nazaExplorationHubHeartBaseline = TextEditingController(),
      _nazaExplorationHubHeartIdentityEmail = TextEditingController(),
      _nazaExplorationHubHeartIdentityHandleA = TextEditingController(),
      _nazaExplorationHubHeartIdentityHandleB = TextEditingController();
  late NazaExplorationSection _nazaExplorationHubSection =
      widget.initialSection;
  bool _nazaExplorationHubBusy = false, _nazaExplorationHubPickingImage = false;
  int _nazaExplorationHubRunGeneration = 0;
  String _nazaExplorationHubResult = '';
  String? _nazaExplorationHubError;
  String? _nazaExplorationHubHeartSuggestions;
  NazaHeartFlowSimulation? _nazaExplorationHubHeartSimulation;
  bool _nazaExplorationHubSuggestionsBusy = false;
  String _nazaExplorationHubFindPrompt = 'Compare nearby options',
      _nazaExplorationHubGardenPrompt = 'Identify plant and health signals';
  String _nazaExplorationHubDrivePrompt = 'Plan a safe efficient route',
      _nazaExplorationHubPredictPrompt = 'Forecast demand and timing';
  String _nazaExplorationHubHeartPrompt = 'Recovery and readiness reflection';
  final List<NazaExploreImage> _nazaExplorationHubGardenImages =
      <NazaExploreImage>[];
  final _nazaExplorationHubGardenPlant = TextEditingController();
  final _nazaExplorationHubGardenHeight = TextEditingController();
  final _nazaExplorationHubGardenWidth = TextEditingController();
  final _nazaExplorationHubGardenHealth = TextEditingController(text: '7');
  String _nazaExplorationHubGardenKind = 'Plant';
  String? _nazaExplorationHubSelectedGardenOrganism;
  final List<_NazaExplorationHubGardenLogEntry> _nazaExplorationHubGardenLog =
      <_NazaExplorationHubGardenLogEntry>[];

  @override
  void didUpdateWidget(covariant NazaExplorationHub oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.initialSection != widget.initialSection &&
        _nazaExplorationHubSection != widget.initialSection)
      _nazaExplorationHubSelect(widget.initialSection, animate: false);
  }

  @override
  void dispose() {
    _nazaExplorationHubPages.dispose();
    for (final c in _nazaExplorationHubDetails.values) {
      c.dispose();
    }
    for (final c in [
      _nazaExplorationHubFindLocation,
      _nazaExplorationHubDriveLocation,
      _nazaExplorationHubDriveDestination,
      _nazaExplorationHubPredictLocation,
      _nazaExplorationHubHeartName,
      _nazaExplorationHubHeartAge,
      _nazaExplorationHubHeartBaseline,
      _nazaExplorationHubHeartIdentityEmail,
      _nazaExplorationHubHeartIdentityHandleA,
      _nazaExplorationHubHeartIdentityHandleB,
      _nazaExplorationHubGardenPlant,
      _nazaExplorationHubGardenHeight,
      _nazaExplorationHubGardenWidth,
      _nazaExplorationHubGardenHealth,
    ]) {
      c.dispose();
    }
    super.dispose();
  }

  void _nazaExplorationHubSelect(
    NazaExplorationSection section, {
    bool animate = true,
  }) {
    setState(() {
      _nazaExplorationHubSection = section;
      _nazaExplorationHubResult = '';
      _nazaExplorationHubError = null;
      _nazaExplorationHubHeartSuggestions = null;
    });
    if (!_nazaExplorationHubPages.hasClients) return;
    animate
        ? _nazaExplorationHubPages.animateToPage(
            section.index,
            duration: const Duration(milliseconds: 240),
            curve: Curves.easeOutCubic,
          )
        : _nazaExplorationHubPages.jumpToPage(section.index);
  }

  Future<void> _nazaExplorationHubPickGardenImage() async {
    if (_nazaExplorationHubPickingImage || _nazaExplorationHubBusy) return;
    setState(() {
      _nazaExplorationHubPickingImage = true;
      _nazaExplorationHubError = null;
    });
    try {
      final image = await widget.pickGardenImage();
      if (!mounted || image == null) return;
      final totalBytes = _nazaExplorationHubGardenImages.fold<int>(
        0,
        (sum, item) => sum + item.bytes.length,
      );
      if (image.bytes.isEmpty || image.bytes.length > 8 * 1024 * 1024) {
        setState(
          () =>
              _nazaExplorationHubError = 'Choose a non-empty image under 8 MB.',
        );
        return;
      }
      if (_nazaExplorationHubGardenImages.length >=
              _nazaExplorationHubMaxGardenImages ||
          totalBytes + image.bytes.length > _nazaExplorationHubMaxGardenBytes) {
        setState(
          () => _nazaExplorationHubError =
              'Garden supports up to 4 photos and 24 MB total.',
        );
        return;
      }
      setState(() => _nazaExplorationHubGardenImages.add(image));
    } catch (_) {
      if (mounted)
        setState(
          () => _nazaExplorationHubError =
              'The camera image could not be opened.',
        );
    } finally {
      if (mounted) setState(() => _nazaExplorationHubPickingImage = false);
    }
  }

  String? _nazaExplorationHubValidate() {
    if (_nazaExplorationHubDetails[_nazaExplorationHubSection]!.text
        .trim()
        .isEmpty)
      return 'Add details about what you want analyzed.';
    return switch (_nazaExplorationHubSection) {
      NazaExplorationSection.findIt
          when _nazaExplorationHubFindLocation.text.trim().isEmpty =>
        'Add a city, neighborhood, address, or area for FindIt.',
      NazaExplorationSection.garden
          when _nazaExplorationHubGardenImages.isEmpty =>
        'Capture or choose a garden photo first.',
      NazaExplorationSection.drive
          when _nazaExplorationHubDriveLocation.text.trim().isEmpty =>
        'Add your starting location or service area.',
      NazaExplorationSection.predict
          when _nazaExplorationHubPredictLocation.text.trim().isEmpty =>
        'Add the market or operating location for this prediction.',
      NazaExplorationSection.heartFlow
          when _nazaExplorationHubHeartName.text.trim().isEmpty =>
        'Add a name or private profile label.',
      _ => null,
    };
  }

  Future<void> _nazaExplorationHubRun() async {
    final int runId = ++_nazaExplorationHubRunGeneration;
    final NazaExplorationSection requestedSection = _nazaExplorationHubSection;
    final invalid = _nazaExplorationHubValidate();
    if (invalid != null) {
      setState(() => _nazaExplorationHubError = invalid);
      return;
    }
    setState(() {
      _nazaExplorationHubBusy = true;
      _nazaExplorationHubResult = '';
      _nazaExplorationHubError = null;
      if (_nazaExplorationHubSection == NazaExplorationSection.heartFlow) {
        _nazaExplorationHubHeartSimulation = NazaHeartFlowSimulation.run(
          reflection: _nazaExplorationHubDetails[_nazaExplorationHubSection]!
              .text
              .trim(),
          ageOrRange: _nazaExplorationHubHeartAge.text,
          restingBaseline: _nazaExplorationHubHeartBaseline.text,
        );
        _nazaExplorationHubHeartSuggestions = null;
      }
    });
    try {
      final text = await widget.runPrompt(
        systemInstruction: _nazaExplorationHubSystemInstruction,
        prompt: _nazaExplorationHubBuildPrompt(),
        imageBytes: _nazaExplorationHubSection == NazaExplorationSection.garden
            ? (_nazaExplorationHubGardenImages.isEmpty
                  ? null
                  : _nazaExplorationHubGardenImages.first.bytes)
            : null,
      );
      if (text.trim().isEmpty) {
        throw const FormatException('The model returned no usable analysis.');
      }
      if (mounted &&
          runId == _nazaExplorationHubRunGeneration &&
          _nazaExplorationHubSection == requestedSection) {
        setState(() => _nazaExplorationHubResult = text);
      }
    } catch (_) {
      if (mounted && runId == _nazaExplorationHubRunGeneration)
        setState(
          () => _nazaExplorationHubError =
              'Unable to run the local analysis. Try again.',
        );
    } finally {
      if (mounted) setState(() => _nazaExplorationHubBusy = false);
    }
  }

  String
  get _nazaExplorationHubSystemInstruction => switch (_nazaExplorationHubSection) {
    NazaExplorationSection.findIt =>
      'You are Naza FindIt. Use only the supplied location. Never claim live availability, distance, hours, or prices. Label assumptions and verification steps.',
    NazaExplorationSection.garden =>
      'You are Naza Garden vision intelligence. Describe visible evidence before hypotheses. Never claim certainty from one image. Give low-risk care steps.',
    NazaExplorationSection.drive =>
      'You are Naza Drive. Prioritize safety. Never claim live traffic, closures, or route status. Use location details only for this response.',
    NazaExplorationSection.predict =>
      'You are Naza Predict. Produce scenarios, not facts. State assumptions, confidence, sensitivity, missing data, and invalidation signals.',
    NazaExplorationSection.heartFlow =>
      'You are Naza Heart Flow. Provide reflective wellness modeling, not diagnosis or emergency guidance. Avoid identity inference and explain uncertainty.',
  };
  String _nazaExplorationHubBuildPrompt() {
    final details = _nazaExplorationHubDetails[_nazaExplorationHubSection]!.text
        .trim();
    final context = switch (_nazaExplorationHubSection) {
      NazaExplorationSection.findIt =>
        'Task: $_nazaExplorationHubFindPrompt\nLocation: ${_nazaExplorationHubFindLocation.text.trim()}\nPreferences: $details',
      NazaExplorationSection.garden =>
        'Task: $_nazaExplorationHubGardenPrompt\nSubject type: $_nazaExplorationHubGardenKind\nImages (${_nazaExplorationHubGardenImages.length}): ${_nazaExplorationHubGardenImages.map((image) => '${image.name} (${image.width}x${image.height})').join(', ')}\nLogged observations: ${_nazaExplorationHubGardenLog.map((e) => '${e.kind}:${e.plant}, height=${e.height}cm, width=${e.width}cm, health=${e.health}/10').join('; ')}\nObservations/request: $details',
      NazaExplorationSection.drive =>
        'Task: $_nazaExplorationHubDrivePrompt\nStart/service area: ${_nazaExplorationHubDriveLocation.text.trim()}\nDestination: ${_nazaExplorationHubOptional(_nazaExplorationHubDriveDestination)}\nConstraints: $details',
      NazaExplorationSection.predict =>
        'Task: $_nazaExplorationHubPredictPrompt\nMarket/location: ${_nazaExplorationHubPredictLocation.text.trim()}\nScenario/timeframe/signals: $details',
      NazaExplorationSection.heartFlow =>
        'Task: $_nazaExplorationHubHeartPrompt\nPrivate profile: ${_nazaExplorationHubHeartName.text.trim()}\n'
            'Age/range: ${_nazaExplorationHubOptional(_nazaExplorationHubHeartAge)}\n'
            'Resting baseline: ${_nazaExplorationHubOptional(_nazaExplorationHubHeartBaseline)}\n'
            'UserIdentity fields supplied: ${_nazaExplorationHubIdentityPresence()}\n'
            'UserIdentity local reference: ${_nazaExplorationHubIdentityReference()}\n'
            'Activity/sleep/stress/symptoms/goals: $details\n'
            '${_nazaExplorationHubHeartSimulation?.toPromptBlock() ?? ''}',
    };
    return 'Workspace: ${_nazaExplorationHubSection.label}\n$context\n\nReturn: supplied context, analysis, assumptions, uncertainty/confidence, safety limits, and next actions. Do not invent live facts or missing measurements.';
  }

  String _nazaExplorationHubOptional(TextEditingController c) =>
      c.text.trim().isEmpty ? 'not supplied' : c.text.trim();

  String _nazaExplorationHubIdentityPresence() {
    final fields = [
      _nazaExplorationHubHeartIdentityEmail,
      _nazaExplorationHubHeartIdentityHandleA,
      _nazaExplorationHubHeartIdentityHandleB,
    ];
    final count = fields.where((field) => field.text.trim().isNotEmpty).length;
    return '$count of 3';
  }

  /// The model receives only a short local reference, never raw identity
  /// values. The values are not persisted by this workflow.
  String _nazaExplorationHubIdentityReference() {
    final raw =
        [
              _nazaExplorationHubHeartIdentityEmail,
              _nazaExplorationHubHeartIdentityHandleA,
              _nazaExplorationHubHeartIdentityHandleB,
            ]
            .map((field) => field.text.trim())
            .where((value) => value.isNotEmpty)
            .join('|');
    if (raw.isEmpty) return 'not supplied';
    final digest = crypto.sha256.convert(utf8.encode(raw)).toString();
    return digest.substring(0, 16);
  }

  Future<void> _nazaExplorationHubGenerateHeartSuggestions() async {
    if (_nazaExplorationHubSuggestionsBusy ||
        _nazaExplorationHubHeartSimulation == null ||
        _nazaExplorationHubResult.trim().isEmpty) {
      return;
    }
    setState(() {
      _nazaExplorationHubSuggestionsBusy = true;
      _nazaExplorationHubError = null;
    });
    try {
      final response = await widget.runPrompt(
        systemInstruction:
            'You are Naza Heart Flow follow-up guidance. Use the simulation as a reflective, non-clinical signal. Propose practical, voluntary actions that improve human and ecological wellbeing. Do not gamify, rank, shame, diagnose, infer identity, or promise that an action changes a score. Prefer small measurable experiments, consent, accessibility, rest, mutual aid, stewardship, and community benefit. Include safety boundaries and ways to review whether an action helped.',
        prompt:
            '''Create a second-stage humanity-oriented action brief.

${_nazaExplorationHubHeartSimulation!.toPromptBlock()}

First-stage reflection:
$_nazaExplorationHubResult

Return 3–5 concrete actions across personal wellbeing, care for others,
creative contribution, fairness/resource sharing, courage/advocacy, and
ecological stewardship where appropriate. Explain the likely benefit,
consent/accessibility considerations, a low-effort version, and a review
signal for each. These are suggestions, not obligations or medical advice.''',
      );
      if (!mounted) return;
      setState(() => _nazaExplorationHubHeartSuggestions = response.trim());
    } catch (_) {
      if (mounted) {
        setState(
          () => _nazaExplorationHubError =
              'The follow-up action brief could not be generated.',
        );
      }
    } finally {
      if (mounted) setState(() => _nazaExplorationHubSuggestionsBusy = false);
    }
  }

