  void _nazaExplorationHubGardenLogEntry() {
    final height = double.tryParse(_nazaExplorationHubGardenHeight.text.trim());
    final width = double.tryParse(_nazaExplorationHubGardenWidth.text.trim());
    final health = int.tryParse(_nazaExplorationHubGardenHealth.text.trim());
    if (height == null ||
        width == null ||
        health == null ||
        height <= 0 ||
        width <= 0 ||
        health < 0 ||
        health > 10) {
      setState(
        () => _nazaExplorationHubError =
            'Enter positive height and width estimates to save a garden observation.',
      );
      return;
    }
    setState(() {
      _nazaExplorationHubGardenLog.add(
        _NazaExplorationHubGardenLogEntry(
          date: DateTime.now(),
