const Object _nazaHealthdashMonolithHealthUnset = Object();

final class NazaWeatherPoint {
  const NazaWeatherPoint({
    required this.time,
    required this.temperature,
    required this.wind,
    required this.rain,
    required this.snow,
    required this.code,
  });
  final DateTime time;
  final double temperature, wind, rain, snow;
  final int code;
}

final class OpenMeteoService {
  static const _nazaHealthdashMonolithMaxPoints = 240;
  Future<List<NazaWeatherPoint>> forecast({
    required double latitude,
    required double longitude,
    int days = 7,
  }) async {
    if (!latitude.isFinite ||
        !longitude.isFinite ||
        latitude.abs() > 90 ||
        longitude.abs() > 180)
      throw const FormatException('Invalid location.');
    final uri = Uri.https('api.open-meteo.com', '/v1/forecast', {
      'latitude': latitude.toStringAsFixed(4),
      'longitude': longitude.toStringAsFixed(4),
      'hourly':
          'temperature_2m,precipitation,rain,snowfall,wind_speed_10m,weather_code',
      'forecast_days': days.clamp(1, 16).toString(),
      'timezone': 'auto',
    });
    final response = await http.get(uri).timeout(const Duration(seconds: 15));
    if (response.statusCode != 200)
      throw StateError('Open-Meteo unavailable (${response.statusCode}).');
    final body = jsonDecode(response.body);
    if (body is! Map) throw const FormatException('Invalid weather response.');
    final hourly = body['hourly'];
    if (hourly is! Map)
      throw const FormatException('Weather hourly data missing.');
    final times = (hourly['time'] as List?)?.cast<String>() ?? const <String>[];
    final temp = (hourly['temperature_2m'] as List?) ?? const [];
    final wind = (hourly['wind_speed_10m'] as List?) ?? const [];
    final rain = (hourly['rain'] as List?) ?? const [];
    final snow = (hourly['snowfall'] as List?) ?? const [];
    final codes = (hourly['weather_code'] as List?) ?? const [];
    final count = [
      times.length,
      temp.length,
      wind.length,
      rain.length,
      snow.length,
      codes.length,
    ].reduce(math.min).clamp(0, _nazaHealthdashMonolithMaxPoints).toInt();
    return List.generate(
      count,
      (i) => NazaWeatherPoint(
        time: DateTime.tryParse(times[i]) ?? DateTime.now(),
        temperature: (temp[i] as num).toDouble(),
        wind: (wind[i] as num).toDouble(),
        rain: (rain[i] as num).toDouble(),
        snow: (snow[i] as num).toDouble(),
        code: (codes[i] as num).round(),
      ),
    );
  }
}

