// -----------------------------------------------------------------------------
// Quantum-inspired RGB circuit.
// Ports HealthDash's PennyLane RX/RY/CNOT/RZ two-qubit math into pure Dart.
// This is a deterministic classical state-vector simulation, not quantum RNG.
// Real cryptographic keys use OS entropy through the cryptography package.
// -----------------------------------------------------------------------------

final class _NazaHealthdashMonolithCx {
  final double re;
  final double im;
  const _NazaHealthdashMonolithCx(this.re, this.im);
  _NazaHealthdashMonolithCx operator +(_NazaHealthdashMonolithCx other) =>
      _NazaHealthdashMonolithCx(re + other.re, im + other.im);
  _NazaHealthdashMonolithCx operator *(_NazaHealthdashMonolithCx other) =>
      _NazaHealthdashMonolithCx(
        re * other.re - im * other.im,
        re * other.im + im * other.re,
      );
  double get abs2 => re * re + im * im;
}

final class NazaQuantumRgbEntropy {
  const NazaQuantumRgbEntropy._();

  static double circuitScore(double r, double g, double b) {
    final a = r.clamp(0.0, 1.0).toDouble();
    final bb = g.clamp(0.0, 1.0).toDouble();
    final c = b.clamp(0.0, 1.0).toDouble();
    var s = <_NazaHealthdashMonolithCx>[
      const _NazaHealthdashMonolithCx(1, 0),
      const _NazaHealthdashMonolithCx(0, 0),
      const _NazaHealthdashMonolithCx(0, 0),
      const _NazaHealthdashMonolithCx(0, 0),
    ];
    s = _nazaHealthdashMonolithSingle(
      s,
      0,
      _nazaHealthdashMonolithRx(a * math.pi),
    );
    s = _nazaHealthdashMonolithSingle(
      s,
      1,
      _nazaHealthdashMonolithRy(bb * math.pi),
    );
    s = _nazaHealthdashMonolithCnot(s, control: 0, target: 1);
    s = _nazaHealthdashMonolithSingle(
      s,
      1,
      _nazaHealthdashMonolithRz(c * math.pi),
    );
    s = _nazaHealthdashMonolithSingle(
      s,
      0,
      _nazaHealthdashMonolithRx((a + bb) * math.pi / 2),
    );
    s = _nazaHealthdashMonolithSingle(
      s,
      1,
      _nazaHealthdashMonolithRy((bb + c) * math.pi / 2),
    );
    final z0 = _nazaHealthdashMonolithZ(s, 0);
    final z1 = _nazaHealthdashMonolithZ(s, 1);
    final combined = ((z0 + 1) / 2 * 0.58) + ((z1 + 1) / 2 * 0.42);
    final score = 1 / (1 + math.exp(-6 * (combined - 0.5)));
    return score.clamp(0.0, 1.0).toDouble();
  }

  static Color accentFor(Color source, DateTime now) {
    final score = circuitScore(source.r, source.g, source.b);
    final secureMix = math.Random.secure().nextInt(1 << 31);
    final dateMix = now.year * 372 + now.month * 31 + now.day;
    final random = math.Random(
      secureMix ^ dateMix ^ (score * 0x7fffffff).round(),
    );
    final hue =
        (source.computeLuminance() * 190 +
            score * 140 +
            random.nextDouble() * 30) %
        360;
    return HSLColor.fromAHSL(
      1,
      hue,
      (0.58 + score * 0.20).clamp(0.0, 1.0).toDouble(),
      0.50 + random.nextDouble() * 0.08,
    ).toColor();
  }

  static List<List<_NazaHealthdashMonolithCx>> _nazaHealthdashMonolithRx(
    double t,
  ) => [
    [
      _NazaHealthdashMonolithCx(math.cos(t / 2), 0),
      _NazaHealthdashMonolithCx(0, -math.sin(t / 2)),
    ],
    [
      _NazaHealthdashMonolithCx(0, -math.sin(t / 2)),
      _NazaHealthdashMonolithCx(math.cos(t / 2), 0),
    ],
  ];

  static List<List<_NazaHealthdashMonolithCx>> _nazaHealthdashMonolithRy(
    double t,
  ) => [
    [
      _NazaHealthdashMonolithCx(math.cos(t / 2), 0),
      _NazaHealthdashMonolithCx(-math.sin(t / 2), 0),
    ],
    [
      _NazaHealthdashMonolithCx(math.sin(t / 2), 0),
      _NazaHealthdashMonolithCx(math.cos(t / 2), 0),
    ],
  ];

  static List<List<_NazaHealthdashMonolithCx>> _nazaHealthdashMonolithRz(
    double t,
  ) => [
    [
      _NazaHealthdashMonolithCx(math.cos(-t / 2), math.sin(-t / 2)),
      const _NazaHealthdashMonolithCx(0, 0),
    ],
    [
      const _NazaHealthdashMonolithCx(0, 0),
      _NazaHealthdashMonolithCx(math.cos(t / 2), math.sin(t / 2)),
    ],
  ];

  static List<_NazaHealthdashMonolithCx> _nazaHealthdashMonolithSingle(
    List<_NazaHealthdashMonolithCx> state,
    int wire,
    List<List<_NazaHealthdashMonolithCx>> gate,
  ) {
    final out = List<_NazaHealthdashMonolithCx>.filled(
      4,
      const _NazaHealthdashMonolithCx(0, 0),
    );
    for (var basis = 0; basis < 4; basis++) {
      final bit = (basis >> (1 - wire)) & 1;
      for (var targetBit = 0; targetBit < 2; targetBit++) {
        final targetBasis = wire == 0
            ? ((targetBit << 1) | (basis & 1))
            : ((basis & 2) | targetBit);
        out[targetBasis] =
            out[targetBasis] + gate[targetBit][bit] * state[basis];
      }
    }
    return out;
  }

  static List<_NazaHealthdashMonolithCx> _nazaHealthdashMonolithCnot(
    List<_NazaHealthdashMonolithCx> state, {
    required int control,
    required int target,
  }) {
    final out = List<_NazaHealthdashMonolithCx>.filled(
      4,
      const _NazaHealthdashMonolithCx(0, 0),
    );
    for (var basis = 0; basis < 4; basis++) {
      final controlBit = (basis >> (1 - control)) & 1;
      final targetBasis = controlBit == 1 ? basis ^ (1 << (1 - target)) : basis;
      out[targetBasis] = out[targetBasis] + state[basis];
    }
    return out;
  }

  static double _nazaHealthdashMonolithZ(
    List<_NazaHealthdashMonolithCx> state,
    int wire,
  ) {
    var value = 0.0;
    for (var basis = 0; basis < 4; basis++) {
      final bit = (basis >> (1 - wire)) & 1;
      value += (bit == 0 ? 1 : -1) * state[basis].abs2;
    }
    return value.clamp(-1.0, 1.0).toDouble();
  }
}

final class NazaQuantumRiskPacket {
  final String domain;
  final double riskScore;
  final String riskLevel;
  final String riskSummary;
  final String promptBlock;

  const NazaQuantumRiskPacket({
    required this.domain,
    required this.riskScore,
    required this.riskLevel,
    required this.riskSummary,
    required this.promptBlock,
  });

  static NazaQuantumRiskPacket build(String domain, String contextText) {
    final config = switch (domain) {
      'dental_recovery' => (
        bias: 0.57,
        low:
            'Low follow-up risk prior. Continue conservative aftercare and keep monitoring the site.',
        medium:
            'Medium follow-up risk prior. Compare the photo with the aftercare plan and watch closely for worsening symptoms.',
        high:
            'High follow-up risk prior. Visible warning signs or worsening notes deserve a careful re-check and may justify contacting a dentist.',
        rule:
            'Use this local prior as conservative follow-up pressure only. Visible evidence and user notes win; never diagnose.',
      ),
      'assistant_context' => (
        bias: 0.32,
        low:
            'Low context pressure. Keep the answer direct and focused on the exact request.',
        medium:
            'Medium context pressure. Include the most relevant tracked facts, likely next action and missing details.',
        high:
            'High context pressure. Lead with safety boundaries, concrete next actions and what should be verified before acting.',
        rule:
            'Use this local transform only for answer emphasis and ordering, never as clinical evidence.',
      ),
      _ => (
        bias: 0.42,
        low:
            'Low follow-up risk prior. Keep the routine consistent and monitor normally.',
        medium:
            'Medium follow-up risk prior. If the photo shows buildup or gum irritation, pay closer attention and tighten the routine.',
        high:
            'High follow-up risk prior. Visible concerns or poor image clarity should push toward a closer self-check and possible dentist follow-up.',
        rule:
            'Use this local prior only as a gentle caution signal. Visible image evidence wins; never diagnose disease.',
      ),
    };

    // Flutter has no psutil equivalent in this monolith. Preserve HealthDash's
    // fallback baseline rather than inventing device sensor measurements.
    const cpu = 0.20;
    const mem = 0.24;
    const load1 = 0.16;
    const temp = 0.05;
    final metricsRgb = (
      r: (cpu * (1 + load1)).clamp(0.0, 1.0).toDouble(),
      g: (mem * (1 + load1 * 0.5)).clamp(0.0, 1.0).toDouble(),
      b: (temp * (0.5 + cpu * 0.5)).clamp(0.0, 1.0).toDouble(),
    );
    final digest = crypto.sha256
        .convert(utf8.encode('${domain.trim()}|${contextText.trim()}'))
        .bytes;
    final signatureRgb = (
      r: digest[2] / 255.0,
      g: digest[11] / 255.0,
      b: digest[23] / 255.0,
    );
    final sim = (
      r: (metricsRgb.r * 0.52 + signatureRgb.r * 0.48)
          .clamp(0.0, 1.0)
          .toDouble(),
      g: (metricsRgb.g * 0.48 + signatureRgb.g * 0.52)
          .clamp(0.0, 1.0)
          .toDouble(),
      b: (metricsRgb.b * 0.40 + signatureRgb.b * 0.60)
          .clamp(0.0, 1.0)
          .toDouble(),
    );
    final entropy = NazaQuantumRgbEntropy.circuitScore(sim.r, sim.g, sim.b);
    // This synthetic/hash-derived signal is routing metadata only. It must
    // never manufacture health urgency or override evidence-backed output.
    const score = 0.0;
    const level = 'Low';
    final summary = 'Routing prior only; no health risk is inferred from it.';
    final block =
        '''
[quantum_risk_sim]
mode: naza_dart_quantum_risk_v1
domain: $domain
tag: _quantum:state/$domain/${level.toLowerCase()}
system_metrics: unavailable; deterministic fallback baseline used
quantum_entropy_score: ${entropy.toStringAsFixed(3)}
metrics_rgb: ${metricsRgb.r.toStringAsFixed(2)},${metricsRgb.g.toStringAsFixed(2)},${metricsRgb.b.toStringAsFixed(2)}
context_signature_rgb: ${signatureRgb.r.toStringAsFixed(2)},${signatureRgb.g.toStringAsFixed(2)},${signatureRgb.b.toStringAsFixed(2)}
sim_signal_rgb: ${sim.r.toStringAsFixed(2)},${sim.g.toStringAsFixed(2)},${sim.b.toStringAsFixed(2)}
local_prior_risk_score: ${score.toStringAsFixed(1)}
local_prior_risk_level: $level
prior_rule: ${config.rule}
[/quantum_risk_sim]
''';
    return NazaQuantumRiskPacket(
      domain: domain,
      riskScore: score,
      riskLevel: level,
      riskSummary: summary,
      promptBlock: block,
    );
  }
}

