        identical(lastCompletedAt, _nazaHealthdashMonolithHealthUnset)
        ? this.lastCompletedAt
        : lastCompletedAt as DateTime?,
    medicationId: identical(medicationId, _nazaHealthdashMonolithHealthUnset)
        ? this.medicationId
        : medicationId as String?,
  );

  Map<String, Object?> toJson() => {
    'id': id,
    'domain': domain.name,
    'title': title,
    'note': note,
    'clock': clock,
    'duration_minutes': durationMinutes,
