// -----------------------------------------------------------------------------
// Daily review first, then weekly review. Each gate is persisted by local key.
// -----------------------------------------------------------------------------

final class NazaDailyWeeklyFlow {
  const NazaDailyWeeklyFlow._();

  static Future<NazaHealthState> runIfNeeded({
    required BuildContext context,
    required NazaHealthState state,
    required Future<void> Function(NazaHealthState) persist,
    required NazaHealthAgentBridge agent,
  }) async {
    var current = state;
    final now = DateTime.now();
    final dayKey = localDayKey(now);
    final weekKey = localWeekKey(now);

    // Explicit user order: DAILY first.
    if (current.lastDailyFlowDay != dayKey && context.mounted) {
      final reviewed = await showModalBottomSheet<NazaHealthState>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        builder: (_) => _NazaHealthdashMonolithDailyReviewSheet(
          state: current,
          agent: agent,
        ),
      );
      if (reviewed != null) {
        current = reviewed.copyWith(lastDailyFlowDay: dayKey);
        await persist(current);
      }
    }

    // WEEKLY follows daily and can appear on the same first open of the week.
    if (current.lastWeeklyFlowWeek != weekKey && context.mounted) {
      final reviewed = await showModalBottomSheet<NazaHealthState>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        builder: (_) => _NazaHealthdashMonolithWeeklyReviewSheet(
          state: current,
          agent: agent,
        ),
      );
      if (reviewed != null) {
        current = reviewed.copyWith(lastWeeklyFlowWeek: weekKey);
        await persist(current);
      }
    }
    return current;
  }
}

final class _NazaHealthdashMonolithDailyReviewSheet extends StatefulWidget {
  final NazaHealthState state;
  final NazaHealthAgentBridge agent;
  const _NazaHealthdashMonolithDailyReviewSheet({
    required this.state,
    required this.agent,
  });
  @override
  State<_NazaHealthdashMonolithDailyReviewSheet> createState() =>
      _NazaHealthdashMonolithDailyReviewSheetState();
}

class _NazaHealthdashMonolithDailyReviewSheetState
    extends State<_NazaHealthdashMonolithDailyReviewSheet> {
  late NazaHealthState state = widget.state;
  String brief = '';
  bool thinking = false;

  @override
  Widget build(BuildContext context) {
    final now = DateTime.now();
    final today = NazaScheduleEngine.forDay(state.schedules, now);
    return DraggableScrollableSheet(
      expand: false,
      initialChildSize: .90,
      minChildSize: .58,
      maxChildSize: .98,
      builder: (_, scroll) => ListView(
        controller: scroll,
        padding: const EdgeInsets.all(18),
        children: [
          _NazaHealthdashMonolithFlowHeader(
            icon: Icons.today_rounded,
            title: 'Daily flow',
            subtitle: 'Once per day on app open • ${localDayKey(now)}',
            onClose: () => Navigator.pop(context, state),
          ),
          const SizedBox(height: 12),
          Builder(
            builder: (_) {
              final todayMeals = state.meals
                  .where((m) => localDayKey(m.timestamp) == localDayKey(now))
                  .toList();
              final calories = todayMeals.fold<int>(
                0,
                (sum, m) => sum + (m.estimate?.calories ?? 0),
              );
              final protein = todayMeals.fold<double>(
                0,
                (sum, m) => sum + (m.estimate?.proteinG ?? 0),
              );
              final plan = state.latestMealPlan;
              final todayPlanned =
                  plan?.meals
                      .where((m) => m.dayKey == localDayKey(now))
                      .length ??
                  0;
              return _NazaHealthdashMonolithInfoCard(
                icon: Icons.restaurant_rounded,
                title:
                    'Food today • ${todayMeals.length} logged • $todayPlanned planned',
                body:
                    '$calories kcal estimated • ${protein.toStringAsFixed(0)} g protein estimated. '
                    'Unlogged meals are missing data, not assumed skipped meals.',
              );
            },
          ),
          const SizedBox(height: 10),
          if (today.isEmpty)
            const _NazaHealthdashMonolithInfoCard(
              icon: Icons.event_busy_rounded,
              title: 'Nothing scheduled yet',
              body:
                  'Add a workout, brushing routine, medication reminder, recovery check-in or custom event.',
            ),
          for (final occurrence in today)
            Card(
              child: ListTile(
                leading: Icon(occurrence.item.domain.icon),
                title: Text(occurrence.item.title),
                subtitle: Text(
                  '${occurrence.item.clock} • ${NazaScheduleEngine.dueLabel(occurrence, now)}',
                ),
                trailing: occurrence.completedToday
                    ? const Icon(Icons.check_circle_rounded)
                    : IconButton(
                        tooltip: 'Mark complete',
                        onPressed: () {
                          final updated = state.schedules
                              .map(
                                (e) => e.id == occurrence.item.id
                                    ? e.copyWith(
                                        lastCompletedAt: DateTime.now(),
                                      )
                                    : e,
                              )
                              .toList();
                          setState(
                            () => state = state.copyWith(schedules: updated),
                          );
                        },
                        icon: const Icon(Icons.check_rounded),
                      ),
              ),
            ),
          const SizedBox(height: 8),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              FilledButton.tonalIcon(
                onPressed: () =>
                    _nazaHealthdashMonolithQuickAdd(NazaScheduleDomain.workout),
                icon: const Icon(Icons.directions_run_rounded),
                label: const Text('Workout'),
              ),
              FilledButton.tonalIcon(
                onPressed: _nazaHealthdashMonolithAddBrushPair,
                icon: const Icon(Icons.health_and_safety_rounded),
                label: const Text('AM/PM brushing'),
              ),
              FilledButton.tonalIcon(
                onPressed: () => _nazaHealthdashMonolithQuickAdd(
                  NazaScheduleDomain.medication,
                ),
                icon: const Icon(Icons.medication_rounded),
                label: const Text('Medication'),
              ),
              FilledButton.tonalIcon(
                onPressed: () => _nazaHealthdashMonolithQuickAdd(
                  NazaScheduleDomain.recovery,
                ),
                icon: const Icon(Icons.spa_rounded),
                label: const Text('Recovery'),
              ),
            ],
          ),
          const SizedBox(height: 14),
          FilledButton.icon(
            onPressed: thinking ? null : _nazaHealthdashMonolithAskAgent,
            icon: thinking
                ? const SizedBox.square(
                    dimension: 18,
                    child: CircularProgressIndicator(strokeWidth: 2),
                  )
                : const Icon(Icons.auto_awesome_rounded),
            label: Text(
              thinking
                  ? '${state.personality.label} is reviewing…'
                  : 'Ask ${state.personality.label} for today’s next actions',
            ),
          ),
          if (brief.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 12),
              child: _NazaHealthdashMonolithInfoCard(
                icon: Icons.auto_awesome_rounded,
                title: '${state.personality.label} • daily brief',
                body: brief,
              ),
            ),
          const SizedBox(height: 18),
          FilledButton(
            onPressed: () => Navigator.pop(context, state),
            child: const Text('Finish daily flow'),
          ),
        ],
      ),
    );
  }

  Future<void> _nazaHealthdashMonolithQuickAdd(
    NazaScheduleDomain domain,
  ) async {
    final item = await showDialog<NazaScheduleItem>(
      context: context,
      builder: (_) =>
          _NazaHealthdashMonolithScheduleEditorDialog(domain: domain),
    );
    if (item != null) {
      setState(
        () => state = state.copyWith(schedules: [...state.schedules, item]),
      );
    }
  }

  void _nazaHealthdashMonolithAddBrushPair() {
    final today = localDayKey(DateTime.now());
    final add = [
      NazaScheduleItem(
        id: nazaHealthId('brush-am'),
        domain: NazaScheduleDomain.dental,
        title: 'Brush teeth',
        clock: '08:00',
        durationMinutes: 3,
        startDay: today,
      ),
      NazaScheduleItem(
        id: nazaHealthId('brush-pm'),
        domain: NazaScheduleDomain.dental,
        title: 'Brush teeth',
        clock: '20:00',
        durationMinutes: 3,
        startDay: today,
      ),
    ];
    setState(
      () => state = state.copyWith(schedules: [...state.schedules, ...add]),
    );
  }

  Future<void> _nazaHealthdashMonolithAskAgent() async {
    setState(() => thinking = true);
    try {
      final result = await widget.agent.runText(
        systemInstruction: NazaHealthPrompts.baseSafety,
        prompt: NazaHealthPrompts.dailyCoach(state, DateTime.now()),
      );
      if (mounted) setState(() => brief = result.trim());
    } catch (error) {
      if (mounted) setState(() => brief = 'Agent unavailable: $error');
    } finally {
      if (mounted) setState(() => thinking = false);
    }
  }
}

final class _NazaHealthdashMonolithWeeklyReviewSheet extends StatefulWidget {
  final NazaHealthState state;
  final NazaHealthAgentBridge agent;
  const _NazaHealthdashMonolithWeeklyReviewSheet({
    required this.state,
    required this.agent,
  });
  @override
  State<_NazaHealthdashMonolithWeeklyReviewSheet> createState() =>
      _NazaHealthdashMonolithWeeklyReviewSheetState();
}

class _NazaHealthdashMonolithWeeklyReviewSheetState
    extends State<_NazaHealthdashMonolithWeeklyReviewSheet> {
  late NazaHealthState state = widget.state;
  String brief = '';
  bool thinking = false;

  @override
  Widget build(BuildContext context) {
    final weekStart = startOfIsoWeek(DateTime.now());
    final weekEnd = weekStart.add(const Duration(days: 6));
    final occurrences = NazaScheduleEngine.range(
      state.schedules,
      weekStart,
      weekEnd,
    );
    return DraggableScrollableSheet(
      expand: false,
      initialChildSize: .94,
      minChildSize: .65,
      maxChildSize: .99,
      builder: (_, scroll) => ListView(
        controller: scroll,
        padding: const EdgeInsets.all(18),
        children: [
          _NazaHealthdashMonolithFlowHeader(
            icon: Icons.date_range_rounded,
            title: 'Weekly flow',
            subtitle:
                'Once per ISO week • ${localDayKey(weekStart)} → ${localDayKey(weekEnd)}',
            onClose: () => Navigator.pop(context, state),
          ),
          const SizedBox(height: 12),
          _NazaHealthdashMonolithInfoCard(
            icon: Icons.calendar_view_week_rounded,
            title: '${occurrences.length} scheduled occurrences',
            body:
                'Set twice-weekly workouts, selected-day routines, medication times and calendar alarms. The exported .ics file carries recurrence rules and VALARM reminders.',
          ),
          const SizedBox(height: 10),
          Builder(
            builder: (_) {
              final plan = state.latestMealPlan;
              final feedback = NazaMealFeedbackEngine.summarize(
                plan,
                state.meals,
              );
              final groceryTotal = state.groceries.fold<double>(
                0,
                (sum, item) => sum + item.estimatedCost,
              );
              return _NazaHealthdashMonolithInfoCard(
                icon: Icons.restaurant_menu_rounded,
                title: plan == null
                    ? 'Food plan not generated'
                    : 'Food plan • ${(feedback.adherenceRatio * 100).toStringAsFixed(0)}% linked',
                body: plan == null
                    ? 'The Meal Plan surface can build a pantry-aware seven-day plan.'
                    : '${feedback.loggedAgainstPlan}/${feedback.planned} planned meals have linked logs. '
                          'Grocery ledger: ${state.bodyProfile.currencyLabel} ${groceryTotal.toStringAsFixed(2)} estimated. '
                          'Missing meal logs are treated as unknown, not skipped.',
              );
            },
          ),
          const SizedBox(height: 10),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              FilledButton.tonalIcon(
                onPressed: _nazaHealthdashMonolithAddTwiceWeeklyWorkout,
                icon: const Icon(Icons.fitness_center_rounded),
                label: const Text('2×/week workout'),
              ),
              FilledButton.tonalIcon(
                onPressed: _nazaHealthdashMonolithAddBrushPair,
                icon: const Icon(Icons.health_and_safety_rounded),
                label: const Text('AM/PM brushing'),
              ),
              FilledButton.tonalIcon(
                onPressed: () => _nazaHealthdashMonolithAddSchedule(
                  NazaScheduleDomain.medication,
                ),
                icon: const Icon(Icons.medication_rounded),
                label: const Text('Medication'),
              ),
              FilledButton.tonalIcon(
                onPressed: _nazaHealthdashMonolithExportCalendar,
                icon: const Icon(Icons.ios_share_rounded),
                label: const Text('Export .ics'),
              ),
            ],
          ),
          const SizedBox(height: 12),
          for (var i = 0; i < 7; i++)
            _NazaHealthdashMonolithWeekDayCard(
              day: weekStart.add(Duration(days: i)),
              occurrences: occurrences
                  .where(
                    (e) =>
                        localDayKey(e.start) ==
                        localDayKey(weekStart.add(Duration(days: i))),
                  )
                  .toList(),
            ),
          const SizedBox(height: 12),
          FilledButton.icon(
            onPressed: thinking ? null : _nazaHealthdashMonolithAskAgent,
            icon: const Icon(Icons.auto_awesome_rounded),
            label: Text(
              thinking
                  ? '${state.personality.label} is planning…'
                  : 'Ask ${state.personality.label} to review the week',
            ),
          ),
          if (brief.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 12),
              child: _NazaHealthdashMonolithInfoCard(
                icon: Icons.auto_awesome_rounded,
                title: '${state.personality.label} • weekly brief',
                body: brief,
              ),
            ),
          const SizedBox(height: 18),
          FilledButton(
            onPressed: () => Navigator.pop(context, state),
            child: const Text('Finish weekly flow'),
          ),
        ],
      ),
    );
  }

  void _nazaHealthdashMonolithAddTwiceWeeklyWorkout() {
    final item = NazaScheduleItem(
      id: nazaHealthId('workout'),
      domain: NazaScheduleDomain.workout,
      title: 'Workout',
      clock: '18:00',
      durationMinutes: 35,
      recurrence: NazaRecurrenceKind.selectedWeekdays,
      weekdays: const [DateTime.monday, DateTime.thursday],
      startDay: localDayKey(DateTime.now()),
      alarmMinutesBefore: 30,
    );
    setState(
      () => state = state.copyWith(schedules: [...state.schedules, item]),
    );
  }

  void _nazaHealthdashMonolithAddBrushPair() {
    final today = localDayKey(DateTime.now());
    setState(
      () => state = state.copyWith(
        schedules: [
          ...state.schedules,
          NazaScheduleItem(
            id: nazaHealthId('brush-am'),
            domain: NazaScheduleDomain.dental,
            title: 'Brush teeth',
            clock: '08:00',
            durationMinutes: 3,
            startDay: today,
          ),
          NazaScheduleItem(
            id: nazaHealthId('brush-pm'),
            domain: NazaScheduleDomain.dental,
            title: 'Brush teeth',
            clock: '20:00',
            durationMinutes: 3,
            startDay: today,
          ),
        ],
      ),
    );
  }

  Future<void> _nazaHealthdashMonolithAddSchedule(
    NazaScheduleDomain domain,
  ) async {
    final item = await showDialog<NazaScheduleItem>(
      context: context,
      builder: (_) =>
          _NazaHealthdashMonolithScheduleEditorDialog(domain: domain),
    );
    if (item != null) {
      setState(
        () => state = state.copyWith(schedules: [...state.schedules, item]),
      );
    }
  }

  Future<void> _nazaHealthdashMonolithExportCalendar() async {
    final file = await NazaIcsExporter.saveToDocuments(state.schedules);
    if (!mounted) return;
    final ics = await file.readAsString();
    await Clipboard.setData(ClipboardData(text: ics));
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('Saved ${file.path}; ICS content also copied.')),
    );
  }

  Future<void> _nazaHealthdashMonolithAskAgent() async {
    setState(() => thinking = true);
    try {
      final result = await widget.agent.runText(
        systemInstruction: NazaHealthPrompts.baseSafety,
        prompt: NazaHealthPrompts.weeklyPlanner(state, DateTime.now()),
      );
      if (mounted) setState(() => brief = result.trim());
    } catch (error) {
      if (mounted) setState(() => brief = 'Agent unavailable: $error');
    } finally {
      if (mounted) setState(() => thinking = false);
    }
  }
}

