final class _NazaHealthdashMonolithScheduleEditorDialog extends StatefulWidget {
  final NazaScheduleDomain domain;
  const _NazaHealthdashMonolithScheduleEditorDialog({required this.domain});
  @override
  State<_NazaHealthdashMonolithScheduleEditorDialog> createState() =>
      _NazaHealthdashMonolithScheduleEditorDialogState();
}

class _NazaHealthdashMonolithScheduleEditorDialogState
    extends State<_NazaHealthdashMonolithScheduleEditorDialog> {
  late final TextEditingController title = TextEditingController(
    text: widget.domain.label,
  );
  final note = TextEditingController();
  TimeOfDay time = const TimeOfDay(hour: 18, minute: 0);
  NazaRecurrenceKind recurrence = NazaRecurrenceKind.daily;
  final Set<int> weekdays = {DateTime.monday, DateTime.thursday};
  int interval = 1;
  int duration = 30;
  int alarm = 15;

  @override
  void dispose() {
    title.dispose();
    note.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => AlertDialog(
    title: Text('Add ${widget.domain.label.toLowerCase()} schedule'),
    content: SizedBox(
      width: 520,
      child: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextField(
              controller: title,
              decoration: const InputDecoration(labelText: 'Title'),
            ),
            TextField(
              controller: note,
              maxLines: 2,
              decoration: const InputDecoration(labelText: 'Note'),
            ),
            ListTile(
              contentPadding: EdgeInsets.zero,
              title: const Text('Time'),
              subtitle: Text(time.format(context)),
              trailing: const Icon(Icons.schedule_rounded),
              onTap: () async {
                final next = await showTimePicker(
                  context: context,
                  initialTime: time,
                );
                if (next != null) setState(() => time = next);
              },
            ),
            DropdownButtonFormField<NazaRecurrenceKind>(
              initialValue: recurrence,
              decoration: const InputDecoration(labelText: 'Recurrence'),
              items: const [
                DropdownMenuItem(
                  value: NazaRecurrenceKind.once,
                  child: Text('One time'),
                ),
                DropdownMenuItem(
                  value: NazaRecurrenceKind.daily,
                  child: Text('Daily'),
                ),
                DropdownMenuItem(
                  value: NazaRecurrenceKind.selectedWeekdays,
                  child: Text('Selected weekdays / twice weekly'),
                ),
                DropdownMenuItem(
                  value: NazaRecurrenceKind.everyNDays,
                  child: Text('Every N days'),
                ),
                DropdownMenuItem(
                  value: NazaRecurrenceKind.everyNWeeks,
                  child: Text('Every N weeks'),
                ),
              ],
              onChanged: (v) => setState(() => recurrence = v ?? recurrence),
            ),
            if (recurrence == NazaRecurrenceKind.selectedWeekdays ||
                recurrence == NazaRecurrenceKind.everyNWeeks)
              Padding(
                padding: const EdgeInsets.only(top: 10),
                child: Wrap(
                  spacing: 6,
                  children: List.generate(7, (i) {
                    final d = i + 1;
                    return FilterChip(
                      selected: weekdays.contains(d),
                      label: Text(const ['M', 'T', 'W', 'T', 'F', 'S', 'S'][i]),
                      onSelected: (selected) => setState(
                        () => selected ? weekdays.add(d) : weekdays.remove(d),
                      ),
                    );
                  }),
                ),
              ),
            if (recurrence == NazaRecurrenceKind.everyNDays ||
                recurrence == NazaRecurrenceKind.everyNWeeks)
              _NazaHealthdashMonolithStepperRow(
                label: 'Interval',
                value: interval,
                onChanged: (v) =>
                    setState(() => interval = v.clamp(1, 52).toInt()),
              ),
            _NazaHealthdashMonolithStepperRow(
              label: 'Duration min',
              value: duration,
              step: 5,
              onChanged: (v) =>
                  setState(() => duration = v.clamp(1, 720).toInt()),
            ),
            _NazaHealthdashMonolithStepperRow(
              label: 'Calendar alarm min before',
              value: alarm,
              step: 5,
              onChanged: (v) =>
                  setState(() => alarm = v.clamp(0, 10080).toInt()),
            ),
          ],
        ),
      ),
    ),
    actions: [
      TextButton(
        onPressed: () => Navigator.pop(context),
        child: const Text('Cancel'),
      ),
      FilledButton(
        onPressed: () => Navigator.pop(
          context,
          NazaScheduleItem(
            id: nazaHealthId('schedule'),
            domain: widget.domain,
            title: title.text.trim().isEmpty
                ? widget.domain.label
                : title.text.trim(),
            note: note.text.trim(),
            clock: hhmm(time),
            durationMinutes: duration,
            recurrence: recurrence,
            interval: interval,
            weekdays: weekdays.toList()..sort(),
            startDay: localDayKey(DateTime.now()),
            alarmMinutesBefore: alarm,
          ),
        ),
        child: const Text('Add'),
      ),
    ],
  );
}

final class _NazaHealthdashMonolithStepperRow extends StatelessWidget {
  final String label;
  final int value;
  final int step;
  final ValueChanged<int> onChanged;
  const _NazaHealthdashMonolithStepperRow({
    required this.label,
    required this.value,
    this.step = 1,
    required this.onChanged,
  });
  @override
  Widget build(BuildContext context) => Row(
    children: [
      Expanded(child: Text('$label: $value')),
      IconButton(
        onPressed: () => onChanged(value - step),
        icon: const Icon(Icons.remove_rounded),
      ),
      IconButton(
        onPressed: () => onChanged(value + step),
        icon: const Icon(Icons.add_rounded),
      ),
    ],
  );
}

