final class _NazaHealthdashMonolithNazaCommandSpec {
  final String title;
  final String subtitle;
  final IconData icon;
  final List<String> keywords;
  final VoidCallback action;

  const _NazaHealthdashMonolithNazaCommandSpec(
    this.title,
    this.subtitle,
    this.icon,
    this.keywords,
    this.action,
  );

  String get searchText =>
      '$title $subtitle ${keywords.join(' ')}'.toLowerCase();

  void invoke() => action();
}

final class _NazaHealthdashMonolithNazaCommandPaletteSheet
    extends StatefulWidget {
  final List<_NazaHealthdashMonolithNazaCommandSpec> commands;

  const _NazaHealthdashMonolithNazaCommandPaletteSheet({
    required this.commands,
  });

