      _NazaHealthdashMonolithNazaCommandPaletteSheetState();
}

class _NazaHealthdashMonolithNazaCommandPaletteSheetState
    extends State<_NazaHealthdashMonolithNazaCommandPaletteSheet> {
  final controller = TextEditingController();

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final query = controller.text.trim().toLowerCase();
    final commands = query.isEmpty
        ? widget.commands
        : widget.commands
              .where((command) => command.searchText.contains(query))
              .toList();
    return FractionallySizedBox(
      heightFactor: .88,
      child: Padding(
        padding: EdgeInsets.fromLTRB(
          16,
          12,
          16,
          16 + MediaQuery.viewInsetsOf(context).bottom,
        ),
        child: Column(
          children: [
            Container(
              width: 48,
              height: 4,
              decoration: BoxDecoration(
                color: Theme.of(context).colorScheme.outlineVariant,
                borderRadius: BorderRadius.circular(99),
              ),
            ),
            const SizedBox(height: 14),
            TextField(
              controller: controller,
              autofocus: true,
              onChanged: (_) => setState(() {}),
              decoration: const InputDecoration(
                prefixIcon: Icon(Icons.manage_search_rounded),
                labelText: 'Search Naza + personal-care commands',
                hintText: 'meds, workout, fridge, settings, review…',
              ),
            ),
            const SizedBox(height: 12),
            Expanded(
              child: commands.isEmpty
                  ? const Center(child: Text('No matching command.'))
                  : ListView.separated(
                      itemCount: commands.length,
                      separatorBuilder: (_, _) => const Divider(height: 1),
                      itemBuilder: (context, index) {
                        final command = commands[index];
                        return ListTile(
                          leading: Icon(command.icon),
                          title: Text(command.title),
                          subtitle: Text(command.subtitle),
                          trailing: const Icon(Icons.arrow_forward_rounded),
                          onTap: () => Navigator.pop(context, command),
                        );
                      },
                    ),
            ),
          ],
        ),
      ),
    );
  }
}

