final class NazaHealthDashMonolith extends StatefulWidget {
  final NazaHealthAgentBridge agent;
  final NazaExistingSurfaceBridge existing;
  final NazaHealthVault? vault;
  final NazaHealthPage initialPage;
  const NazaHealthDashMonolith({
    super.key,
    required this.agent,
    required this.existing,
    this.vault,
    this.initialPage = NazaHealthPage.today,
  });
  @override
  State<NazaHealthDashMonolith> createState() =>
      _NazaHealthdashMonolithNazaHealthDashMonolithState();
}

class _NazaHealthdashMonolithNazaHealthDashMonolithState
    extends State<NazaHealthDashMonolith> {
  late final NazaHealthVault vault = widget.vault ?? NazaHealthVault();
  NazaHealthState state = const NazaHealthState();
  late NazaHealthPage page = widget.initialPage;
  bool loading = true;
  bool flowRunning = false;
  String? bootError;
  Color accent = const Color(0xFF8DFFC4);

  @override
  void initState() {
    super.initState();
    unawaited(_nazaHealthdashMonolithBoot());
  }

  @override
  void didUpdateWidget(covariant NazaHealthDashMonolith oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.initialPage != widget.initialPage &&
        page != widget.initialPage) {
      setState(() => page = widget.initialPage);
    }
  }

  Future<void> _nazaHealthdashMonolithBoot() async {
    try {
      final loaded = await vault.load();
      if (!mounted) return;
      setState(() {
        state = loaded;
        accent = NazaQuantumRgbEntropy.accentFor(
          const Color(0xFF8DFFC4),
          DateTime.now(),
        );
        loading = false;
      });
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) unawaited(_nazaHealthdashMonolithRunFlow());
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        loading = false;
        bootError = error.toString();
      });
    }
  }

  Future<void> _nazaHealthdashMonolithPersist(NazaHealthState next) async {
    if (mounted) setState(() => state = next);
    await vault.save(next);
  }

  Future<void> _nazaHealthdashMonolithRunFlow() async {
    if (flowRunning || !mounted) return;
    flowRunning = true;
    try {
      final next = await NazaDailyWeeklyFlow.runIfNeeded(
        context: context,
        state: state,
        persist: _nazaHealthdashMonolithPersist,
        agent: widget.agent,
      );
      if (mounted) setState(() => state = next);
    } finally {
      flowRunning = false;
    }
  }

  void _nazaHealthdashMonolithSnack(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(SnackBar(content: Text(message)));
  }

