  Future<void> _nazaHealthdashMonolithRunIntegrityCheck() async {
    try {
      final result = await vault.integrityCheck();
      _nazaHealthdashMonolithSnack('Naza vault integrity: $result');
    } catch (error) {
      _nazaHealthdashMonolithSnack('Vault integrity check failed: $error');
    }
  }

  Future<void> _nazaHealthdashMonolithOpenHelpStep(
    NazaHelpFlowStep step,
  ) async {
    var flow = state.helpFlow.copyWith(lastStepId: step.id);
    if (const {'I', 'J', 'K'}.contains(step.id)) {
      flow = flow.mark(step.id);
    }
    await _nazaHealthdashMonolithPersist(state.copyWith(helpFlow: flow));
    switch (step.id) {
      case 'A':
      case 'C':
        if (mounted) setState(() => page = NazaHealthPage.today);
        break;
      case 'B':
      case 'D':
      case 'E':
        if (mounted) setState(() => page = NazaHealthPage.medications);
        break;
      case 'F':
        if (mounted) setState(() => page = NazaHealthPage.dental);
        break;
      case 'G':
        if (mounted) setState(() => page = NazaHealthPage.exercise);
        break;
      case 'H':
        if (mounted) setState(() => page = NazaHealthPage.recovery);
        break;
      case 'I':
        widget.existing.openChat();
        break;
      case 'J':
      case 'K':
        widget.existing.openSettings();
        break;
      default:
        break;
    }
  }

  @override
  Widget build(BuildContext context) {
    if (loading) {
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }
    if (bootError != null) {
      return Scaffold(
        appBar: AppBar(title: const Text('Health vault locked')),
        body: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 620),
            child: Padding(
              padding: const EdgeInsets.all(24),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Icon(Icons.lock_rounded, size: 56),
                  const SizedBox(height: 16),
                  const Text(
                    'Pass 5 stores personal-health data inside NazaSecureDatabase. '
                    'Unlock the Naza vault before opening the health surface.',
                    textAlign: TextAlign.center,
                  ),
                  const SizedBox(height: 10),
                  SelectableText(bootError!, textAlign: TextAlign.center),
                  const SizedBox(height: 16),
                  FilledButton.icon(
                    onPressed: widget.existing.openSettings,
                    icon: const Icon(Icons.settings_rounded),
                    label: const Text('Open Naza settings'),
                  ),
                ],
              ),
            ),
          ),
        ),
      );
    }
    final scheme = ColorScheme.fromSeed(
      seedColor: accent,
      brightness: Brightness.dark,
    );
    return Theme(
      data: Theme.of(context).copyWith(colorScheme: scheme),
      child: Scaffold(
        appBar: AppBar(
          title: Text(_nazaHealthdashMonolithPageLabel(page)),
          actions: [
            IconButton(
              tooltip: 'Daily + weekly review',
              onPressed: _nazaHealthdashMonolithRunFlow,
              icon: const Icon(Icons.auto_awesome_rounded),
            ),
          ],
        ),
        body: AnimatedSwitcher(
          duration: const Duration(milliseconds: 180),
          child: KeyedSubtree(
            key: ValueKey(page),
            child: _nazaHealthdashMonolithPageBody(),
          ),
        ),
      ),
    );
  }

