class _NazaHealthdashMonolithMedicationPageState
    extends State<_NazaHealthdashMonolithMedicationPage> {
  DateTime selectedDay = startOfDay(DateTime.now());
  bool safetyBusy = false;
  bool bottleBusy = false;
  NazaPillBottleDraft? bottleDraft;

  NazaHealthState get state => widget.state;
  List<NazaMedication> get active =>
      state.medications.where((m) => m.active).toList();
  List<NazaMedication> get archived =>
      state.medications.where((m) => !m.active).toList()..sort(
        (a, b) => (b.archivedAt ?? b.createdAt).compareTo(
          a.archivedAt ?? a.createdAt,
        ),
      );

  @override
  Widget build(BuildContext context) => DefaultTabController(
    length: 5,
    child: Column(
      children: [
        Material(
          color: Theme.of(context).colorScheme.surface,
          child: const TabBar(
            isScrollable: true,
            tabs: [
              Tab(icon: Icon(Icons.checklist_rounded), text: 'Today checklist'),
              Tab(icon: Icon(Icons.medication_rounded), text: 'Medications'),
              Tab(icon: Icon(Icons.shield_rounded), text: 'Safety'),
              Tab(
                icon: Icon(Icons.document_scanner_rounded),
                text: 'Bottle scanner',
              ),
              Tab(icon: Icon(Icons.archive_rounded), text: 'Archive'),
            ],
          ),
        ),
        Expanded(
          child: TabBarView(
            children: [
              _nazaHealthdashMonolithChecklistTab(),
              _nazaHealthdashMonolithMedicationsTab(),
              _nazaHealthdashMonolithSafetyTab(),
              _nazaHealthdashMonolithBottleTab(),
              _nazaHealthdashMonolithArchiveTab(),
            ],
          ),
        ),
      ],
    ),
  );

  Widget _nazaHealthdashMonolithChecklistTab() {
    final now = DateTime.now();
    final rows = <({NazaMedication med, NazaMedicationSlot slot})>[];
    for (final med in active) {
      for (final slot in NazaMedicationPlanEngine.buildDailySlots(
        med,
        selectedDay,
        now,
      )) {
        rows.add((med: med, slot: slot));
      }
    }
    rows.sort((a, b) => a.slot.scheduledAt.compareTo(b.slot.scheduledAt));
    final taken = rows
        .where((e) => e.slot.status == NazaMedicationSlotStatus.taken)
        .length;
    final due = rows
        .where((e) => e.slot.status == NazaMedicationSlotStatus.due)
        .length;
    final missed = rows
        .where((e) => e.slot.status == NazaMedicationSlotStatus.missed)
        .length;
    final upcoming = rows
        .where((e) => e.slot.status == NazaMedicationSlotStatus.upcoming)
        .length;

    return ListView(
      padding: const EdgeInsets.all(16),
      children: [
        _NazaHealthdashMonolithPageHeader(
          title: 'Daily medication checklist',
          subtitle:
              'Stable slot keys reconcile taken, due, missed and upcoming records without relying on memory.',
          action: OutlinedButton.icon(
            onPressed: _nazaHealthdashMonolithPickChecklistDate,
            icon: const Icon(Icons.event_rounded),
            label: Text(localDayKey(selectedDay)),
          ),
        ),
        const SizedBox(height: 12),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: [
            Chip(label: Text('$taken taken')),
            Chip(label: Text('$due due')),
            Chip(label: Text('$missed missed')),
            Chip(label: Text('$upcoming upcoming')),
          ],
        ),
        SwitchListTile.adaptive(
          contentPadding: EdgeInsets.zero,
          title: const Text('Allow checklist uncheck'),
          subtitle: const Text(
            'Off by default. When enabled, unchecking removes the dose record matched to that exact slot.',
          ),
          value: state.allowChecklistUncheck,
          onChanged: (value) =>
              widget.onState(state.copyWith(allowChecklistUncheck: value)),
        ),
        if (rows.isEmpty)
          const _NazaHealthdashMonolithInfoCard(
            icon: Icons.event_busy_rounded,
            title: 'No resolved slots',
            body:
                'Add a custom plan such as Breakfast, Lunch, Dinner; explicit times; or an interval plus first planned dose time.',
          ),
        for (final row in rows)
          _nazaHealthdashMonolithSlotCard(row.med, row.slot),
      ],
    );
  }

  Widget _nazaHealthdashMonolithSlotCard(
    NazaMedication med,
    NazaMedicationSlot slot,
  ) {
    final color = switch (slot.status) {
      NazaMedicationSlotStatus.taken => Colors.greenAccent,
      NazaMedicationSlotStatus.due => Colors.amberAccent,
      NazaMedicationSlotStatus.missed => Colors.redAccent,
      NazaMedicationSlotStatus.upcoming => Theme.of(
        context,
      ).colorScheme.primary,
    };
    return Card(
      child: ListTile(
        leading: CircleAvatar(
          child: Icon(
            slot.status == NazaMedicationSlotStatus.taken
                ? Icons.check_rounded
                : Icons.medication_rounded,
            color: color,
          ),
        ),
        title: Text('${med.name} • ${slot.label}'),
        subtitle: Text(
          '${slot.scheduledAt.hour.toString().padLeft(2, '0')}:${slot.scheduledAt.minute.toString().padLeft(2, '0')} • '
          '${med.doseMg.g} mg • ${slot.statusText}',
        ),
        trailing: slot.status == NazaMedicationSlotStatus.taken
            ? (state.allowChecklistUncheck
                  ? IconButton(
                      tooltip: 'Uncheck this exact slot',
                      icon: const Icon(Icons.undo_rounded),
                      onPressed: () =>
                          _nazaHealthdashMonolithUncheckSlot(med, slot),
                    )
                  : const Icon(Icons.lock_rounded))
            : IconButton(
                tooltip: 'Log dose for this slot',
                icon: const Icon(Icons.check_circle_outline_rounded),
                onPressed: () => _nazaHealthdashMonolithLogSlot(med, slot),
              ),
      ),
    );
  }

  Widget _nazaHealthdashMonolithMedicationsTab() => ListView(
    padding: const EdgeInsets.all(16),
    children: [
      _NazaHealthdashMonolithPageHeader(
        title: 'Shape the regimen',
        subtitle:
            'Create or edit the current regimen. Named slots and interval-generated slots share one deterministic planner.',
        action: FilledButton.icon(
          onPressed: () => _nazaHealthdashMonolithEditMedication(),
          icon: const Icon(Icons.add_rounded),
          label: const Text('Medication'),
        ),
      ),
      const SizedBox(height: 12),
      for (final med in active)
        Card(
          child: Padding(
            padding: const EdgeInsets.all(14),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    Expanded(
                      child: Text(
                        med.name,
                        style: const TextStyle(fontWeight: FontWeight.w900),
                      ),
                    ),
                    if (med.source == 'vision')
                      const Chip(label: Text('Bottle import')),
                  ],
                ),
                Text(
                  '${med.doseMg.g} mg • every ${med.intervalHours.g}h • max ${med.maxDailyMg.g} mg / rolling 24h',
                ),
                if (med.directions.isNotEmpty) Text(med.directions),
                if (med.scheduleText.isNotEmpty)
                  Text('Directions/timing: ${med.scheduleText}'),
                const SizedBox(height: 8),
                Text(
                  'Resolved plan: ${NazaMedicationPlanEngine.resolvedTemplates(med).map((e) => '${e.label} ${e.minutes ~/ 60}:${(e.minutes % 60).toString().padLeft(2, '0')}').join(' • ')}',
                ),
                const SizedBox(height: 10),
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: [
                    FilledButton.tonalIcon(
                      onPressed: () =>
                          _nazaHealthdashMonolithLogUnscheduledDose(med),
                      icon: const Icon(Icons.check_rounded),
                      label: const Text('Log now'),
                    ),
                    OutlinedButton.icon(
                      onPressed: () =>
                          _nazaHealthdashMonolithEditMedication(existing: med),
                      icon: const Icon(Icons.edit_rounded),
                      label: const Text('Edit'),
                    ),
                    OutlinedButton.icon(
                      onPressed: () =>
                          _nazaHealthdashMonolithAddCalendarReminders(med),
                      icon: const Icon(Icons.calendar_month_rounded),
                      label: const Text('Calendar'),
                    ),
                    OutlinedButton.icon(
                      onPressed: () =>
                          _nazaHealthdashMonolithArchiveMedication(med),
                      icon: const Icon(Icons.archive_rounded),
                      label: const Text('Archive'),
                    ),
                  ],
                ),
                if (med.history.isNotEmpty) ...[
                  const Divider(height: 24),
                  Text(
                    'Recent history',
                    style: Theme.of(context).textTheme.titleSmall?.copyWith(
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                  for (final log in med.history.reversed.take(6))
                    Text(
                      '• ${log.timestamp} • ${log.doseMg.g} mg${log.slotKey.isEmpty ? '' : ' • ${log.slotKey.split('::').last}'}',
                    ),
                ],
              ],
            ),
          ),
        ),
    ],
  );

  Widget _nazaHealthdashMonolithSafetyTab() {
    final signature = NazaMedicationSafetyEngine.regimenSignature(active);
    // `lastWhere(orElse: () => null)` cannot safely be expressed by casting a
    // non-nullable iterable to nullable values: dart:core's CastIterable still
    // casts the fallback through the source type at runtime. Find the latest
    // matching review explicitly so an empty/locked review history renders a
    // normal empty state instead of crashing the entire medication page.
    NazaMedicationReview? latestAll;
    for (final review in state.medicationReviews.reversed) {
      if (review.scope == 'regimen' && review.regimenSignature == signature) {
        latestAll = review;
        break;
      }
    }
    return ListView(
      padding: const EdgeInsets.all(16),
      children: [
        _NazaHealthdashMonolithPageHeader(
          title: 'Medication safety',
          subtitle:
              'Deterministic stored-rule checks first; local Gemma review second. Model output cannot rewrite medication facts.',
          action: FilledButton.icon(
            onPressed: safetyBusy || active.isEmpty
                ? null
                : _nazaHealthdashMonolithRunAllMedsReview,
            icon: safetyBusy
                ? const SizedBox.square(
                    dimension: 16,
                    child: CircularProgressIndicator(strokeWidth: 2),
                  )
                : const Icon(Icons.shield_rounded),
            label: const Text('Run all-meds check'),
          ),
        ),
        const SizedBox(height: 12),
        _NazaHealthdashMonolithInfoCard(
          icon: Icons.rule_rounded,
          title: 'Deterministic regimen flags',
          body:
              NazaMedicationSafetyEngine.deterministicRegimenFlags(
                active,
              ).isEmpty
              ? 'No structural schedule/data flags were found.'
              : NazaMedicationSafetyEngine.deterministicRegimenFlags(
                  active,
                ).map((e) => '• $e').join('\n'),
        ),
        if (latestAll != null) ...[
          const SizedBox(height: 10),
          _nazaHealthdashMonolithReviewCard(latestAll),
        ],
        const SizedBox(height: 12),
        for (final med in active)
          Card(
            child: ListTile(
              leading: const Icon(Icons.medication_rounded),
              title: Text(med.name),
              subtitle: Text(
                NazaMedicationSafetyEngine.beforeLogging(
                  med,
                  DateTime.now(),
                ).detail,
              ),
              trailing: TextButton(
                onPressed: safetyBusy
                    ? null
                    : () => _nazaHealthdashMonolithRunFocusedReview(med),
                child: const Text('Review'),
              ),
            ),
          ),
        if (state.medicationReviews.isNotEmpty) ...[
          const SizedBox(height: 18),
          Text(
            'Saved safety reviews',
            style: Theme.of(
              context,
            ).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w900),
          ),
          for (final review in state.medicationReviews.reversed.take(20))
            _nazaHealthdashMonolithReviewCard(review),
        ],
      ],
    );
  }

  Widget _nazaHealthdashMonolithReviewCard(NazaMedicationReview review) => Card(
    child: Padding(
      padding: const EdgeInsets.all(14),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                child: Text(
                  review.display,
                  style: const TextStyle(fontWeight: FontWeight.w900),
                ),
              ),
              Chip(label: Text(review.action)),
            ],
          ),
          Text(review.message),
          if (review.flags.isNotEmpty) ...[
            const SizedBox(height: 6),
            for (final flag in review.flags) Text('• $flag'),
          ],
          Text(
            '${review.timestamp} • ${review.scope}',
            style: Theme.of(context).textTheme.bodySmall,
          ),
        ],
      ),
    ),
  );

  Widget _nazaHealthdashMonolithBottleTab() => ListView(
    padding: const EdgeInsets.all(16),
    children: [
      _NazaHealthdashMonolithPageHeader(
        title: 'Pill Bottle Scanner',
        subtitle:
            'Use the existing Naza vision/LiteRT-LM path to create a draft, then manually confirm it before it becomes regimen data.',
        action: FilledButton.icon(
