  Future<void> _nazaHealthdashMonolithPickChecklistDate() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: selectedDay,
      firstDate: DateTime(2020),
      lastDate: DateTime.now().add(const Duration(days: 365)),
    );
    if (picked != null && mounted)
      setState(() => selectedDay = startOfDay(picked));
  }

  Future<void> _nazaHealthdashMonolithEditMedication({
    NazaMedication? existing,
  }) async {
    final name = TextEditingController(text: existing?.name ?? '');
    final dose = TextEditingController(
      text: existing == null ? '' : existing.doseMg.g,
    );
    final interval = TextEditingController(
      text: existing?.intervalHours.g ?? '8',
    );
    final max = TextEditingController(
      text: existing == null ? '' : existing.maxDailyMg.g,
    );
    final firstDose = TextEditingController(
      text: existing?.firstDoseTime ?? '',
    );
    final times = TextEditingController(
      text: existing?.customTimes.join(', ') ?? '',
    );
    final schedule = TextEditingController(text: existing?.scheduleText ?? '');
    final directions = TextEditingController(text: existing?.directions ?? '');
    final notes = TextEditingController(text: existing?.notes ?? '');

    final ok = await showDialog<bool>(
      context: context,
      builder: (_) => AlertDialog(
        title: Text(
          existing == null ? 'Add medication' : 'Edit ${existing.name}',
        ),
        content: SizedBox(
          width: 600,
          child: SingleChildScrollView(
            child: Column(
              children: [
                TextField(
                  controller: name,
                  decoration: const InputDecoration(labelText: 'Name'),
                ),
                TextField(
                  controller: dose,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(labelText: 'Dose mg'),
                ),
                TextField(
                  controller: interval,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: 'Minimum interval hours',
                  ),
                ),
                TextField(
                  controller: max,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: 'Max mg / rolling 24h',
                  ),
                ),
                TextField(
                  controller: firstDose,
                  decoration: const InputDecoration(
                    labelText: 'First planned dose time (HH:MM)',
                  ),
                ),
                TextField(
                  controller: times,
                  maxLines: 2,
                  decoration: const InputDecoration(
                    labelText: 'Custom daily dose times',
                    helperText:
                        'Examples: Breakfast, Lunch, Dinner OR Breakfast 08:00, Mid day 12:00, Nighttime 21:00',
                  ),
                ),
                TextField(
                  controller: schedule,
                  maxLines: 2,
                  decoration: const InputDecoration(
                    labelText: 'Schedule / timing directions',
                  ),
                ),
                TextField(
                  controller: directions,
                  maxLines: 2,
                  decoration: const InputDecoration(
                    labelText: 'Bottle / prescriber directions',
                  ),
                ),
                TextField(
                  controller: notes,
                  maxLines: 3,
                  decoration: const InputDecoration(labelText: 'Notes'),
                ),
              ],
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Save'),
          ),
        ],
      ),
    );
    if (ok != true) return;

    final parsedCustom = times.text
        .split(RegExp(r'[,;\n]+'))
        .map((e) => e.trim())
        .where((e) => e.isNotEmpty)
        .toList();
    final updated = NazaMedication(
      id: existing?.id ?? nazaHealthId('med'),
      name: name.text.trim().isEmpty ? 'Medication' : name.text.trim(),
      doseMg: math.max(0, double.tryParse(dose.text) ?? 0).toDouble(),
      intervalHours: math
          .max(.25, double.tryParse(interval.text) ?? 8)
          .toDouble(),
      maxDailyMg: math.max(0, double.tryParse(max.text) ?? 0).toDouble(),
      directions: directions.text.trim(),
      notes: notes.text.trim(),
      firstDoseTime: firstDose.text.trim(),
      customTimes: parsedCustom,
      scheduleText: schedule.text.trim(),
      source: existing?.source ?? 'manual',
      sourcePhoto: existing?.sourcePhoto ?? '',
      active: true,
      createdAt: existing?.createdAt ?? DateTime.now(),
      history: existing?.history ?? const [],
    );
    final meds = existing == null
        ? [...state.medications, updated]
        : state.medications
              .map((m) => m.id == existing.id ? updated : m)
              .toList();
    await widget.onState(state.copyWith(medications: meds));
    widget.onMessage(
      existing == null ? 'Medication added.' : 'Medication updated.',
    );
  }

  Future<void> _nazaHealthdashMonolithLogSlot(
    NazaMedication med,
    NazaMedicationSlot slot,
  ) async {
    final deterministic = NazaMedicationSafetyEngine.beforeLogging(
      med,
      DateTime.now(),
    );
    if (deterministic.severity == NazaSafetySeverity.stop) {
      await _nazaHealthdashMonolithShowSafetyStop(deterministic);
      return;
    }
    final updated = NazaMedicationPlanEngine.logSlot(med, slot, DateTime.now());
    if (updated == null) return;
    await _nazaHealthdashMonolithReplaceMedication(updated);
    widget.onMessage('Dose logged for ${med.name} • ${slot.label}.');
  }

  Future<void> _nazaHealthdashMonolithUncheckSlot(
    NazaMedication med,
    NazaMedicationSlot slot,
  ) async {
    if (!state.allowChecklistUncheck) return;
    await _nazaHealthdashMonolithReplaceMedication(
      NazaMedicationPlanEngine.removeSlotLog(med, slot),
    );
    widget.onMessage('Checklist entry reverted; matching dose record removed.');
  }

  Future<void> _nazaHealthdashMonolithLogUnscheduledDose(
    NazaMedication med,
  ) async {
    final check = NazaMedicationSafetyEngine.beforeLogging(med, DateTime.now());
    if (check.severity == NazaSafetySeverity.stop) {
      await _nazaHealthdashMonolithShowSafetyStop(check);
      return;
    }
    final history = [
      ...med.history,
      NazaDoseLog(timestamp: DateTime.now(), doseMg: med.doseMg),
    ].takeLast(240);
    await _nazaHealthdashMonolithReplaceMedication(
      med.copyWith(history: history),
    );
    widget.onMessage('Dose logged after deterministic checks.');
  }

  Future<void> _nazaHealthdashMonolithShowSafetyStop(
    NazaMedicationSafetyResult check,
  ) => showDialog<void>(
    context: context,
    builder: (_) => AlertDialog(
      icon: const Icon(Icons.warning_amber_rounded),
      title: Text(check.title),
      content: Text(check.detail),
      actions: [
        FilledButton(
          onPressed: () => Navigator.pop(context),
          child: const Text('Close'),
        ),
      ],
    ),
  );

  Future<void> _nazaHealthdashMonolithReplaceMedication(
    NazaMedication medication,
  ) => widget.onState(
    state.copyWith(
      medications: state.medications
          .map((m) => m.id == medication.id ? medication : m)
          .toList(),
    ),
  );

  Future<void> _nazaHealthdashMonolithArchiveMedication(
    NazaMedication med,
  ) async {
    final archivedMed = med.copyWith(active: false, archivedAt: DateTime.now());
    final schedules = state.schedules
        .where((s) => s.medicationId != med.id)
        .toList();
    await widget.onState(
      state.copyWith(
        medications: state.medications
            .map((m) => m.id == med.id ? archivedMed : m)
            .toList(),
        schedules: schedules,
      ),
    );
    widget.onMessage('${med.name} archived; dose history preserved.');
  }

  Future<void> _nazaHealthdashMonolithRestoreMedication(
    NazaMedication med,
  ) async {
    await _nazaHealthdashMonolithReplaceMedication(
      med.copyWith(active: true, clearArchivedAt: true),
    );
    widget.onMessage('${med.name} restored to the current regimen.');
  }

  Future<void> _nazaHealthdashMonolithAddCalendarReminders(
    NazaMedication med,
  ) async {
    final templates = NazaMedicationPlanEngine.resolvedTemplates(med);
    final today = localDayKey(DateTime.now());
    final retained = state.schedules
        .where((s) => s.medicationId != med.id)
        .toList();
    final additions = templates.map(
      (slot) => NazaScheduleItem(
        id: nazaHealthId('med-reminder'),
        domain: NazaScheduleDomain.medication,
        title: '${med.name} • ${slot.label}',
        note: med.directions,
        clock:
            '${(slot.minutes ~/ 60).toString().padLeft(2, '0')}:${(slot.minutes % 60).toString().padLeft(2, '0')}',
        durationMinutes: 5,
        recurrence: NazaRecurrenceKind.daily,
        startDay: today,
        alarmMinutesBefore: 0,
        medicationId: med.id,
      ),
    );
    await widget.onState(
      state.copyWith(schedules: [...retained, ...additions]),
    );
    widget.onMessage(
      'Calendar reminders regenerated from the current medication plan.',
    );
  }

  Future<void> _nazaHealthdashMonolithRunFocusedReview(
    NazaMedication med,
  ) async {
    setState(() => safetyBusy = true);
    try {
      final deterministic = NazaMedicationSafetyEngine.beforeLogging(
        med,
        DateTime.now(),
      );
      final raw = await widget.agent.runText(
        systemInstruction: NazaHealthPrompts.baseSafety,
        prompt: NazaHealthPrompts.focusedMedicationReview(med, deterministic),
      );
      final parsed = decodeNazaHealthJson(raw);
      final review = NazaMedicationReview(
        id: nazaHealthId('med-review'),
        timestamp: DateTime.now(),
        scope: 'focused',
        medicationId: med.id,
        regimenSignature: NazaMedicationSafetyEngine.regimenSignature(active),
        action: _nazaHealthdashMonolithSafeMedicationAction(parsed['action']),
        display: parsed['display']?.toString() ?? '${med.name} safety review',
        message: parsed['message']?.toString() ?? deterministic.detail,
        flags: ((parsed['flags'] as List?) ?? const [])
            .map((e) => e.toString())
            .take(20)
            .toList(),
        rawModelText: raw,
      );
      await widget.onState(
        state.copyWith(
          medicationReviews: [...state.medicationReviews, review].takeLast(120),
        ),
      );
      widget.onMessage('Focused safety review saved locally.');
    } catch (error) {
      widget.onMessage('Focused safety review failed: $error');
    } finally {
      if (mounted) setState(() => safetyBusy = false);
    }
  }

  Future<void> _nazaHealthdashMonolithRunAllMedsReview() async {
    setState(() => safetyBusy = true);
    try {
      final flags = NazaMedicationSafetyEngine.deterministicRegimenFlags(
        active,
      );
      final raw = await widget.agent.runText(
        systemInstruction: NazaHealthPrompts.baseSafety,
        prompt: NazaHealthPrompts.allMedicationReview(active, flags),
      );
      final parsed = decodeNazaHealthJson(raw);
      final review = NazaMedicationReview(
        id: nazaHealthId('regimen-review'),
        timestamp: DateTime.now(),
        scope: 'regimen',
        regimenSignature: NazaMedicationSafetyEngine.regimenSignature(active),
        action: _nazaHealthdashMonolithSafeMedicationAction(parsed['action']),
        display: parsed['display']?.toString() ?? 'All-meds integration',
        message:
            parsed['message']?.toString() ?? 'Combined regimen review saved.',
        flags: {
          ...flags,
          ...((parsed['flags'] as List?) ?? const []).map((e) => e.toString()),
        }.take(40).toList(),
        rawModelText: raw,
      );
      await widget.onState(
        state.copyWith(
          medicationReviews: [...state.medicationReviews, review].takeLast(120),
        ),
      );
      widget.onMessage('All-meds integration review saved locally.');
    } catch (error) {
      widget.onMessage('All-meds review failed: $error');
    } finally {
      if (mounted) setState(() => safetyBusy = false);
    }
  }

  Future<void> _nazaHealthdashMonolithScanBottle() async {
    final picker = widget.agent.pickImage;
    final vision = widget.agent.runVision;
    if (picker == null || vision == null) {
      widget.onMessage(
        'Connect the Naza image picker and vision runner first.',
      );
      return;
    }
    setState(() => bottleBusy = true);
    try {
      final image = await picker();
      if (image == null) return;
      final raw = await vision(
        imageBytes: image.bytes,
        systemInstruction: NazaHealthPrompts.baseSafety,
        prompt: NazaHealthPrompts.pillBottleVision(image.name),
      );
      final draft = NazaPillBottleDraft.fromModel(image.name, raw);
      if (mounted) setState(() => bottleDraft = draft);
    } catch (error) {
      widget.onMessage('Bottle scan failed: $error');
    } finally {
      if (mounted) setState(() => bottleBusy = false);
    }
  }

  Future<void> _nazaHealthdashMonolithConfirmBottleDraft() async {
    final draft = bottleDraft;
    if (draft == null) return;
    final name = TextEditingController(text: draft.name);
    final dose = TextEditingController(
      text: draft.doseMg > 0 ? draft.doseMg.g : '',
    );
    final interval = TextEditingController(
      text: draft.intervalHours > 0 ? draft.intervalHours.g : '',
    );
    final max = TextEditingController(
      text: draft.maxDailyMg > 0 ? draft.maxDailyMg.g : '',
    );
    final schedule = TextEditingController(text: draft.scheduleText);
    final directions = TextEditingController(text: draft.directions);
    final notes = TextEditingController(text: draft.notes);
    final ok = await showDialog<bool>(
      context: context,
      builder: (_) => AlertDialog(
        title: const Text('Confirm bottle details'),
        content: SizedBox(
          width: 600,
          child: SingleChildScrollView(
            child: Column(
              children: [
                const _NazaHealthdashMonolithInfoCard(
                  icon: Icons.fact_check_rounded,
                  title: 'Manual verification required',
                  body:
                      'Compare every field with the physical label. The image model is an extraction aid, not an authoritative medication source.',
                ),
                TextField(
                  controller: name,
                  decoration: const InputDecoration(
                    labelText: 'Medication name',
                  ),
                ),
                TextField(
                  controller: dose,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(labelText: 'Dose mg'),
                ),
                TextField(
                  controller: interval,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: 'Interval hours',
                  ),
                ),
                TextField(
                  controller: max,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: 'Max mg / rolling 24h',
                  ),
                ),
                TextField(
                  controller: schedule,
                  decoration: const InputDecoration(
                    labelText: 'Schedule / timing',
                  ),
                ),
                TextField(
                  controller: directions,
                  maxLines: 2,
                  decoration: const InputDecoration(labelText: 'Directions'),
                ),
                TextField(
                  controller: notes,
                  maxLines: 3,
                  decoration: const InputDecoration(labelText: 'Notes'),
                ),
              ],
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('I verified these fields'),
          ),
        ],
      ),
    );
    if (ok != true) return;

    final med = NazaMedication(
      id: nazaHealthId('med'),
      name: name.text.trim().isEmpty ? 'Medication' : name.text.trim(),
      doseMg: math.max(0, double.tryParse(dose.text) ?? 0).toDouble(),
      intervalHours: math
          .max(0, double.tryParse(interval.text) ?? 0)
          .toDouble(),
      maxDailyMg: math.max(0, double.tryParse(max.text) ?? 0).toDouble(),
      scheduleText: schedule.text.trim(),
      directions: directions.text.trim(),
      notes: notes.text.trim(),
      source: 'vision',
      sourcePhoto: draft.imageName,
      createdAt: DateTime.now(),
    );
    final record = NazaBottleImportRecord(
      timestamp: DateTime.now(),
      imageName: draft.imageName,
      medicationId: med.id,
      summary:
          '${med.name} | ${med.doseMg.g}mg | every ${med.intervalHours.g}h',
      confidence: draft.confidence,
      riskScore: draft.riskScore,
      riskLevel: draft.riskLevel,
      riskSummary: draft.riskSummary,
    );
    await widget.onState(
      state.copyWith(
        medications: [...state.medications, med],
        bottleImports: [...state.bottleImports, record].takeLast(16),
      ),
    );
    if (mounted) setState(() => bottleDraft = null);
    widget.onMessage('Verified bottle draft saved as a current medication.');
  }
}

final class _NazaHealthdashMonolithDentalPage extends StatefulWidget {
  final NazaHealthState state;
  final Future<void> Function(NazaHealthState) onState;
  final NazaHealthAgentBridge agent;
  final ValueChanged<String> onMessage;
  const _NazaHealthdashMonolithDentalPage({
    required this.state,
    required this.onState,
    required this.agent,
    required this.onMessage,
  });

  @override
  State<_NazaHealthdashMonolithDentalPage> createState() =>
      _NazaHealthdashMonolithDentalPageState();
}

class _NazaHealthdashMonolithDentalPageState
    extends State<_NazaHealthdashMonolithDentalPage> {
  int tab = 0;
  bool busy = false;

  NazaDentalState get dental => widget.state.dental;

  @override
  Widget build(BuildContext context) => ListView(
    padding: const EdgeInsets.all(16),
    children: [
      _NazaHealthdashMonolithPageHeader(
        title: 'Dental Health Studio',
        subtitle:
            'Routine reminders, visible hygiene review, and dental-procedure recovery journal.',
        action: FilledButton.tonalIcon(
          onPressed: _nazaHealthdashMonolithSyncDentalCalendar,
          icon: const Icon(Icons.calendar_month_rounded),
          label: const Text('Sync reminders'),
        ),
      ),
      const SizedBox(height: 12),
      SegmentedButton<int>(
        segments: const [
          ButtonSegment(
            value: 0,
            icon: Icon(Icons.checklist_rounded),
            label: Text('Routine'),
          ),
          ButtonSegment(
            value: 1,
            icon: Icon(Icons.camera_alt_rounded),
            label: Text('Hygiene Vision'),
          ),
          ButtonSegment(
            value: 2,
            icon: Icon(Icons.healing_rounded),
            label: Text('Recovery'),
          ),
        ],
        selected: {tab},
        onSelectionChanged: (s) => setState(() => tab = s.first),
      ),
      const SizedBox(height: 14),
      if (tab == 0) _nazaHealthdashMonolithRoutine(),
      if (tab == 1) _nazaHealthdashMonolithHygieneVision(),
      if (tab == 2) _nazaHealthdashMonolithRecovery(),
    ],
  );

  Widget _nazaHealthdashMonolithRoutine() => Column(
    children: [
      _NazaHealthdashMonolithHabitCard(
        icon: Icons.cleaning_services_rounded,
        title: 'Brush',
        intervalHours: dental.brushIntervalHours,
        last: dental.lastBrush,
        onDone: () => widget.onState(
          widget.state.copyWith(
            dental: dental.copyWith(lastBrush: DateTime.now()),
          ),
        ),
      ),
      _NazaHealthdashMonolithHabitCard(
        icon: Icons.linear_scale_rounded,
        title: 'Floss',
        intervalHours: dental.flossIntervalHours,
        last: dental.lastFloss,
        onDone: () => widget.onState(
          widget.state.copyWith(
            dental: dental.copyWith(lastFloss: DateTime.now()),
          ),
        ),
      ),
      _NazaHealthdashMonolithHabitCard(
        icon: Icons.water_drop_rounded,
        title: 'Rinse',
        intervalHours: dental.rinseIntervalHours,
        last: dental.lastRinse,
        onDone: () => widget.onState(
          widget.state.copyWith(
            dental: dental.copyWith(lastRinse: DateTime.now()),
          ),
        ),
      ),
      const SizedBox(height: 8),
      OutlinedButton.icon(
        onPressed: _nazaHealthdashMonolithEditIntervals,
        icon: const Icon(Icons.tune_rounded),
        label: const Text('Edit reminder rhythm'),
      ),
    ],
  );

  Widget _nazaHealthdashMonolithHygieneVision() {
    final latest = dental.latestHygiene;
    final trend = _nazaHealthdashMonolithScoreTrend(
      dental.hygieneHistory.map((e) => e.score).toList(),
    );
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _NazaHealthdashMonolithInfoCard(
          icon: Icons.visibility_rounded,
          title: 'Visible hygiene review',
          body: latest == null
              ? 'No photo review saved yet. The local vision model scores visible cleanliness only; it is not a dental diagnosis.'
              : '${latest.rating} • ${latest.score.toStringAsFixed(0)}/100 • confidence ${(latest.confidence * 100).toStringAsFixed(0)}%\n${latest.summary}\n$trend',
        ),
        const SizedBox(height: 10),
        FilledButton.icon(
          onPressed: busy ? null : _nazaHealthdashMonolithReviewHygienePhoto,
          icon: busy
              ? const SizedBox.square(
                  dimension: 18,
                  child: CircularProgressIndicator(strokeWidth: 2),
                )
              : const Icon(Icons.camera_alt_rounded),
          label: const Text('Review hygiene photo locally'),
        ),
        if (latest != null) ...[
          const SizedBox(height: 10),
          _NazaHealthdashMonolithInfoCard(
            icon:
                _nazaHealthdashMonolithWarningNeedsAttention(
                  latest.warningFlags,
                )
                ? Icons.warning_amber_rounded
                : Icons.tips_and_updates_rounded,
            title: 'Latest coaching',
            body:
                'Suggestions: ${latest.suggestions}\nWarning flags: ${latest.warningFlags.isEmpty ? 'none' : latest.warningFlags}\nRisk: ${latest.riskLevel} ${latest.riskScore.toStringAsFixed(0)}/100 • ${latest.riskSummary}',
          ),
        ],
        const SizedBox(height: 12),
        for (final review in dental.hygieneHistory.reversed.take(8))
          ListTile(
            leading: CircleAvatar(child: Text(review.score.toStringAsFixed(0))),
            title: Text(review.rating),
            subtitle: Text(
              '${review.timestamp} • risk ${review.riskLevel} ${review.riskScore.toStringAsFixed(0)}/100',
            ),
          ),
      ],
    );
  }

  Widget _nazaHealthdashMonolithRecovery() {
    final latest = dental.latestRecovery;
    final day = dental.recoveryDayNumber();
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _NazaHealthdashMonolithInfoCard(
          icon: Icons.healing_rounded,
          title: dental.recoveryEnabled
              ? '${dental.procedureType.isEmpty ? 'Dental recovery' : dental.procedureType}${day == null ? '' : ' • day $day'}'
              : 'Dental recovery mode is off',
          body: dental.recoveryEnabled
              ? 'Procedure date: ${dental.procedureDate.isEmpty ? 'unknown' : dental.procedureDate}\nSymptoms: ${dental.symptomNotes.isEmpty ? 'none recorded' : dental.symptomNotes}\nCare notes: ${dental.careNotes.isEmpty ? 'none recorded' : dental.careNotes}'
              : 'Start a recovery episode to keep procedure context, daily photo reviews and conservative aftercare notes together.',
        ),
        const SizedBox(height: 10),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: [
