  Future<void> _nazaHealthdashMonolithReviewHygienePhoto() async {
    final picker = widget.agent.pickImage;
    final vision = widget.agent.runVision;
    if (picker == null || vision == null) {
      widget.onMessage(
        'The host must connect NazaHealthAgentBridge.pickImage and runVision to the existing Naza vision runtime.',
      );
      return;
    }
    final picked = await picker();
    if (picked == null) return;
    setState(() => busy = true);
    try {
      final raw = await vision(
        imageBytes: picked.bytes,
        systemInstruction: NazaHealthPrompts.baseSafety,
        prompt: NazaHealthPrompts.dentalHygieneVision(),
      );
      final j = decodeNazaHealthJson(raw);
      var score = ((j['hygiene_score'] as num?)?.toDouble() ?? 0);
      if (score > 0 && score <= 1) score *= 100;
      score = score.clamp(0, 100).toDouble();
      var confidence = ((j['confidence'] as num?)?.toDouble() ?? 0);
      if (confidence > 1 && confidence <= 100) confidence /= 100;
      confidence = confidence.clamp(0, 1).toDouble();
      final ratingRaw = j['rating']?.toString().trim() ?? '';
      final visibleSigns = j['visible_signs']?.toString().trim() ?? '';
      final suggestions = j['suggestions']?.toString().trim() ?? '';
      final riskPacket = NazaQuantumRiskPacket.build(
        'dental_hygiene',
        'teeth and mouth hygiene photo review with visible-cleanliness scoring',
      );
      final modelRiskScore = (j['risk_score'] as num?)?.toDouble();
      final modelRiskLevel = j['risk_level']?.toString().trim() ?? '';
      final modelRiskSummary = j['risk_summary']?.toString().trim() ?? '';
      final riskScore = modelRiskScore == null || modelRiskScore <= 0
          ? riskPacket.riskScore
          : modelRiskScore.clamp(0, 100).toDouble();
      final riskLevel = modelRiskLevel.isEmpty
          ? riskPacket.riskLevel
          : _nazaHealthdashMonolithRiskLevel(modelRiskLevel, riskScore);
      final riskSummary = modelRiskSummary.isEmpty
          ? riskPacket.riskSummary
          : modelRiskSummary;
      final review = NazaDentalHygieneReview(
        timestamp: DateTime.now(),
        imageName: picked.name,
        score: score,
        rating: ratingRaw.isEmpty
            ? _nazaHealthdashMonolithDentalRating(score)
            : ratingRaw,
        summary: visibleSigns.isNotEmpty
            ? visibleSigns
            : 'Review the photo manually; the model did not provide a clear hygiene summary.',
        suggestions: suggestions.isNotEmpty
            ? suggestions
            : 'Brush gently for two minutes, floss carefully, and stay consistent with your routine.',
        warningFlags: j['warning_flags']?.toString().trim() ?? '',
        confidence: confidence,
        riskScore: riskScore,
        riskLevel: riskLevel,
        riskSummary: riskSummary,
      );
      await widget.onState(
        widget.state.copyWith(
          dental: dental.copyWith(
            hygieneHistory: [...dental.hygieneHistory, review].takeLast(20),
          ),
        ),
      );
      widget.onMessage('Dental hygiene photo review saved locally.');
    } catch (error) {
      widget.onMessage('Dental hygiene review failed: $error');
    } finally {
      if (mounted) setState(() => busy = false);
    }
  }

  Future<void> _nazaHealthdashMonolithEditRecoveryPlan() async {
    final procedure = TextEditingController(text: dental.procedureType);
    final date = TextEditingController(text: dental.procedureDate);
    final symptoms = TextEditingController(text: dental.symptomNotes);
    final care = TextEditingController(text: dental.careNotes);
    final ok = await showDialog<bool>(
      context: context,
      builder: (_) => AlertDialog(
        title: const Text('Dental recovery plan'),
        content: SizedBox(
          width: 560,
          child: SingleChildScrollView(
            child: Column(
              children: [
                TextField(
                  controller: procedure,
                  decoration: const InputDecoration(
                    labelText: 'Procedure type',
                  ),
                ),
                TextField(
                  controller: date,
                  decoration: const InputDecoration(
                    labelText: 'Procedure date YYYY-MM-DD',
                  ),
                ),
                TextField(
                  controller: symptoms,
                  maxLines: 3,
                  decoration: const InputDecoration(labelText: 'Symptom notes'),
                ),
                TextField(
                  controller: care,
                  maxLines: 3,
                  decoration: const InputDecoration(
                    labelText: 'Dentist / aftercare notes',
                  ),
                ),
              ],
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Save'),
          ),
        ],
      ),
    );
    if (ok != true) return;
    final parsed = date.text.trim().isEmpty
        ? null
        : DateTime.tryParse(date.text.trim());
    if (date.text.trim().isNotEmpty && parsed == null) {
      widget.onMessage('Use YYYY-MM-DD for the dental procedure date.');
      return;
    }
    if (parsed != null &&
        startOfDay(parsed).isAfter(startOfDay(DateTime.now()))) {
      widget.onMessage('Dental procedure date cannot be in the future.');
      return;
    }
    await widget.onState(
      widget.state.copyWith(
        dental: dental.copyWith(
          recoveryEnabled:
              procedure.text.trim().isNotEmpty ||
              date.text.trim().isNotEmpty ||
              symptoms.text.trim().isNotEmpty ||
              care.text.trim().isNotEmpty,
          procedureType: procedure.text.trim(),
          procedureDate: date.text.trim(),
          symptomNotes: symptoms.text.trim(),
          careNotes: care.text.trim(),
        ),
      ),
    );
  }

  Future<void> _nazaHealthdashMonolithReviewRecoveryPhoto() async {
    final picker = widget.agent.pickImage;
    final vision = widget.agent.runVision;
    if (picker == null || vision == null) {
      widget.onMessage(
        'The host must connect image picking + the existing Naza vision runtime for dental recovery review.',
      );
      return;
    }
    final picked = await picker();
    if (picked == null) return;
    setState(() => busy = true);
    try {
      final raw = await vision(
        imageBytes: picked.bytes,
        systemInstruction: NazaHealthPrompts.baseSafety,
        prompt: NazaHealthPrompts.dentalRecoveryVision(dental),
      );
      final j = decodeNazaHealthJson(raw);
      var score = ((j['recovery_score'] as num?)?.toDouble() ?? 0);
      if (score > 0 && score <= 1) score *= 100;
      score = score.clamp(0, 100).toDouble();
      var confidence = ((j['confidence'] as num?)?.toDouble() ?? 0);
      if (confidence > 1 && confidence <= 100) confidence /= 100;
      confidence = confidence.clamp(0, 1).toDouble();
      final statusRaw = j['status']?.toString().trim() ?? '';
      final healingSummary = j['healing_summary']?.toString().trim() ?? '';
      final careSuggestions = j['care_suggestions']?.toString().trim() ?? '';
      final riskContext = jsonEncode({
        'procedure_type': dental.procedureType,
        'procedure_date': dental.procedureDate,
        'day_number': dental.recoveryDayNumber(),
        'symptom_notes': dental.symptomNotes,
        'care_notes': dental.careNotes,
      });
      final riskPacket = NazaQuantumRiskPacket.build(
        'dental_recovery',
        riskContext,
      );
      final modelRiskScore = (j['risk_score'] as num?)?.toDouble();
      final modelRiskLevel = j['risk_level']?.toString().trim() ?? '';
      final modelRiskSummary = j['risk_summary']?.toString().trim() ?? '';
      final riskScore = modelRiskScore == null || modelRiskScore <= 0
          ? riskPacket.riskScore
          : modelRiskScore.clamp(0, 100).toDouble();
      final riskLevel = modelRiskLevel.isEmpty
          ? riskPacket.riskLevel
          : _nazaHealthdashMonolithRiskLevel(modelRiskLevel, riskScore);
      final riskSummary = modelRiskSummary.isEmpty
          ? riskPacket.riskSummary
          : modelRiskSummary;
      final status = statusRaw.isNotEmpty
          ? statusRaw
          : score >= 80
          ? 'Looks steady'
          : score >= 55
          ? 'Monitor closely'
          : score > 0
          ? 'Needs dentist review'
          : 'Needs manual review';
      final review = NazaDentalRecoveryReview(
        timestamp: DateTime.now(),
        imageName: picked.name,
        dayNumber: dental.recoveryDayNumber() ?? 0,
        score: score,
        status: status,
        summary: healingSummary.isNotEmpty
            ? healingSummary
            : 'Review the photo manually; the model did not provide a clear healing summary.',
        advice: careSuggestions.isNotEmpty
            ? careSuggestions
            : "Follow your dentist's aftercare directions and reach out if symptoms feel worse instead of better.",
        warningFlags: j['warning_flags']?.toString().trim() ?? '',
        confidence: confidence,
        riskScore: riskScore,
        riskLevel: riskLevel,
        riskSummary: riskSummary,
      );
      await widget.onState(
        widget.state.copyWith(
          dental: dental.copyWith(
            recoveryHistory: [...dental.recoveryHistory, review].takeLast(30),
          ),
        ),
      );
      widget.onMessage('Dental recovery photo review saved locally.');
    } catch (error) {
      widget.onMessage('Dental recovery review failed: $error');
    } finally {
      if (mounted) setState(() => busy = false);
    }
  }

  static String _nazaHealthdashMonolithDentalRating(double score) {
    if (score >= 88) return 'Excellent';
    if (score >= 72) return 'Good';
    if (score >= 55) return 'Needs polish';
    return 'Needs attention';
  }

  static String _nazaHealthdashMonolithScoreTrend(List<double> values) {
    if (values.isEmpty) return 'Take a first AI review to start the trend.';
    if (values.length < 2) return 'First AI review saved.';
    final delta = values.last - values[values.length - 2];
    if (delta.abs() < 2) return 'Holding steady versus the last review.';
    return '${delta.abs().toStringAsFixed(0)} points ${delta > 0 ? 'up' : 'down'} versus the last review.';
  }

  static bool _nazaHealthdashMonolithWarningNeedsAttention(String text) {
    final lower = text.trim().toLowerCase();
    if (lower.isEmpty || lower == 'none' || lower == 'none.') return false;
    return [
      'warning',
      'urgent',
      'call',
      'dentist',
      'swelling',
      'pus',
      'bleeding',
      'infection',
      'review',
    ].any(lower.contains);
  }

  static String _nazaHealthdashMonolithRiskLevel(String? raw, double score) {
    final clean = (raw ?? '').trim().toLowerCase();
    if (clean == 'low') return 'Low';
    if (clean == 'medium') return 'Medium';
    if (clean == 'high') return 'High';
    if (score >= 70) return 'High';
    if (score >= 40) return 'Medium';
    return 'Low';
  }
}

final class _NazaHealthdashMonolithHabitCard extends StatelessWidget {
  final IconData icon;
  final String title;
  final double intervalHours;
  final DateTime? last;
  final VoidCallback onDone;
  const _NazaHealthdashMonolithHabitCard({
    required this.icon,
    required this.title,
    required this.intervalHours,
    required this.last,
    required this.onDone,
  });
  @override
  Widget build(BuildContext context) {
    final now = DateTime.now();
    final interval = Duration(minutes: (intervalHours * 60).round());
    final due = last == null || now.difference(last!) >= interval;
    final text = last == null
        ? 'Ready now'
        : due
        ? 'Due now'
        : 'Not due yet';
    return Card(
      child: ListTile(
        leading: Icon(icon),
        title: Text(title),
        subtitle: Text('$text • every ${intervalHours.g}h'),
        trailing: FilledButton.tonal(
          onPressed: onDone,
          child: const Text('Done'),
        ),
      ),
    );
  }
}

final class _NazaHealthdashMonolithWalkingMetabolismPage
    extends StatefulWidget {
  final NazaHealthState state;
  final Future<void> Function(NazaHealthState) onState;
  final NazaHealthAgentBridge agent;

  const _NazaHealthdashMonolithWalkingMetabolismPage({
    required this.state,
    required this.onState,
    required this.agent,
  });

  @override
  State<_NazaHealthdashMonolithWalkingMetabolismPage> createState() =>
      _NazaHealthdashMonolithWalkingMetabolismPageState();
}

class _NazaHealthdashMonolithWalkingMetabolismPageState
    extends State<_NazaHealthdashMonolithWalkingMetabolismPage> {
  final _nazaHealthdashMonolithWeather = OpenMeteoService();
  List<NazaWeatherPoint> _nazaHealthdashMonolithForecast = const [];
  bool _nazaHealthdashMonolithWeatherBusy = false;
  String? _nazaHealthdashMonolithWeatherError;
  String? _nazaHealthdashMonolithWeatherReview;
  bool _nazaHealthdashMonolithReviewBusy = false;
  Timer? _nazaHealthdashMonolithTimer;
  StreamSubscription<StepCount>? _nazaHealthdashMonolithStepSubscription;
  int? _nazaHealthdashMonolithSensorStartSteps;
  DateTime? _nazaHealthdashMonolithStartedAt;
  final _nazaHealthdashMonolithSteps = TextEditingController();
  final _nazaHealthdashMonolithDistance = TextEditingController();
  final _nazaHealthdashMonolithTemperature = TextEditingController();
  final _nazaHealthdashMonolithWeight = TextEditingController();
  final _nazaHealthdashMonolithCalories = TextEditingController();
  final _nazaHealthdashMonolithSleep = TextEditingController();
  final _nazaHealthdashMonolithMeds = TextEditingController();

  @override
  void dispose() {
    _nazaHealthdashMonolithTimer?.cancel();
    _nazaHealthdashMonolithStepSubscription?.cancel();
    for (final c in [
      _nazaHealthdashMonolithSteps,
      _nazaHealthdashMonolithDistance,
      _nazaHealthdashMonolithTemperature,
      _nazaHealthdashMonolithWeight,
      _nazaHealthdashMonolithCalories,
      _nazaHealthdashMonolithSleep,
      _nazaHealthdashMonolithMeds,
    ])
      c.dispose();
    super.dispose();
  }

  int get _nazaHealthdashMonolithMinutes =>
      _nazaHealthdashMonolithStartedAt == null
      ? 0
      : DateTime.now().difference(_nazaHealthdashMonolithStartedAt!).inMinutes;

  Future<void> _nazaHealthdashMonolithStartWalk() async {
    setState(() {
      _nazaHealthdashMonolithStartedAt = DateTime.now();
      _nazaHealthdashMonolithTimer = Timer.periodic(
        const Duration(seconds: 30),
        (_) {
          if (mounted) setState(() {});
        },
      );
    });
    await _nazaHealthdashMonolithStartStepSensor();
  }

  Future<void> _nazaHealthdashMonolithFinishWalk() async {
    final start = _nazaHealthdashMonolithStartedAt;
    if (start == null) return;
    final session = NazaWalkingSession(
      id: nazaHealthId('walk'),
      startedAt: start,
      endedAt: DateTime.now(),
      steps: int.tryParse(_nazaHealthdashMonolithSteps.text) ?? 0,
      activeMinutes: _nazaHealthdashMonolithMinutes,
      distanceMeters:
          double.tryParse(_nazaHealthdashMonolithDistance.text) ?? 0,
      outdoorTempC:
          double.tryParse(_nazaHealthdashMonolithTemperature.text) ?? 0,
      gpsTracked: _nazaHealthdashMonolithForecast.isNotEmpty,
    );
    _nazaHealthdashMonolithTimer?.cancel();
    await _nazaHealthdashMonolithStepSubscription?.cancel();
    setState(() => _nazaHealthdashMonolithStartedAt = null);
    await widget.onState(
      widget.state.copyWith(
        walkingSessions: [...widget.state.walkingSessions, session],
      ),
    );
  }

  Future<void> _nazaHealthdashMonolithSaveCheckin() async {
    final checkin = NazaMetabolicCheckin(
      day: DateTime.now(),
      weightKg: double.tryParse(_nazaHealthdashMonolithWeight.text) ?? 0,
      estimatedCalories:
          double.tryParse(_nazaHealthdashMonolithCalories.text) ?? 0,
      steps: int.tryParse(_nazaHealthdashMonolithSteps.text) ?? 0,
      sleepHours: double.tryParse(_nazaHealthdashMonolithSleep.text) ?? 0,
      medicationContext: _nazaHealthdashMonolithMeds.text.trim(),
    );
    await widget.onState(
      widget.state.copyWith(
        metabolicCheckins: [...widget.state.metabolicCheckins, checkin],
      ),
    );
    if (mounted)
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Metabolic response check-in saved locally.'),
        ),
      );
  }

  Future<void> _nazaHealthdashMonolithLoadWeather() async {
    setState(() {
      _nazaHealthdashMonolithWeatherBusy = true;
      _nazaHealthdashMonolithWeatherError = null;
    });
    try {
      if (!await Geolocator.isLocationServiceEnabled())
        throw StateError('Location services are disabled.');
      var permission = await Geolocator.checkPermission();
      if (permission == LocationPermission.denied)
        permission = await Geolocator.requestPermission();
      if (permission == LocationPermission.denied ||
          permission == LocationPermission.deniedForever)
        throw StateError('Location permission was not granted.');
      final position = await Geolocator.getCurrentPosition(
        locationSettings: const LocationSettings(
          accuracy: LocationAccuracy.reduced,
          timeLimit: Duration(seconds: 15),
        ),
      );
      final points = await _nazaHealthdashMonolithWeather.forecast(
        latitude: position.latitude,
        longitude: position.longitude,
      );
      if (mounted) setState(() => _nazaHealthdashMonolithForecast = points);
    } catch (error) {
      if (mounted)
        setState(
          () => _nazaHealthdashMonolithWeatherError =
              'Weather unavailable: $error',
        );
    } finally {
      if (mounted) setState(() => _nazaHealthdashMonolithWeatherBusy = false);
    }
  }

  Future<void> _nazaHealthdashMonolithStartStepSensor() async {
    final permission = await Permission.activityRecognition.request();
    if (!permission.isGranted) {
      if (mounted)
        setState(
          () => _nazaHealthdashMonolithWeatherError =
              'Activity permission was not granted; enter steps manually.',
        );
      return;
    }
    await _nazaHealthdashMonolithStepSubscription?.cancel();
    _nazaHealthdashMonolithSensorStartSteps = null;
    _nazaHealthdashMonolithStepSubscription = Pedometer.stepCountStream.listen(
      (event) {
        _nazaHealthdashMonolithSensorStartSteps ??= event.steps;
        if (mounted)
          setState(
            () => _nazaHealthdashMonolithSteps.text = math
                .max(0, event.steps - _nazaHealthdashMonolithSensorStartSteps!)
                .toString(),
          );
      },
      onError: (_) {
        if (mounted)
          setState(
            () => _nazaHealthdashMonolithWeatherError =
                'Step sensor unavailable; enter steps manually.',
          );
      },
    );
  }

  Future<void> _nazaHealthdashMonolithReviewWeather() async {
    if (_nazaHealthdashMonolithForecast.isEmpty ||
        _nazaHealthdashMonolithReviewBusy)
      return;
    setState(() => _nazaHealthdashMonolithReviewBusy = true);
    try {
      final sample = _nazaHealthdashMonolithForecast
          .take(24)
          .map(
            (p) =>
                '${p.time.toIso8601String()} temp=${p.temperature}C wind=${p.wind}km/h rain=${p.rain}mm snow=${p.snow}cm code=${p.code}',
          )
          .join('\n');
      final review = await widget.agent.runText(
        systemInstruction:
            'Review bounded weather data for walking. Discuss heat/cold, wind, rain, snow or ice, visibility, and useful time windows. Be conservative, do not invent observations, and state uncertainty.',
        prompt:
            'Open-Meteo hourly observations:\n$sample\nSuggest safer walking windows and practical precautions.',
      );
      if (mounted)
        setState(() => _nazaHealthdashMonolithWeatherReview = review.trim());
    } catch (error) {
      if (mounted)
        setState(
          () => _nazaHealthdashMonolithWeatherError =
              'Weather review unavailable: $error',
        );
    } finally {
      if (mounted) setState(() => _nazaHealthdashMonolithReviewBusy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final sessions = widget.state.walkingSessions;
    final recent = sessions.where(
      (e) =>
          e.endedAt.isAfter(DateTime.now().subtract(const Duration(days: 28))),
    );
    final totalSteps = recent.fold<int>(0, (sum, e) => sum + e.steps);
    final totalMeters = recent.fold<double>(
      0,
      (sum, e) => sum + e.distanceMeters,
    );
    final avgSteps = recent.isEmpty ? 0 : totalSteps ~/ recent.length;
    final latest = widget.state.metabolicCheckins.isEmpty
        ? null
        : widget.state.metabolicCheckins.last;
    return ListView(
      padding: const EdgeInsets.all(16),
      children: [
        const _NazaHealthdashMonolithPageHeader(
          title: 'Walking Mode',
          subtitle:
