final class _NazaHealthdashMonolithWalkingRibbonPainter extends CustomPainter {
  final int steps;
  final int average;
  const _NazaHealthdashMonolithWalkingRibbonPainter({
    required this.steps,
    required this.average,
  });
  @override
  void paint(Canvas canvas, Size size) {
    final colors = [
      const Color(0xFF63D7FF),
      const Color(0xFF8DFFC4),
      const Color(0xFFFFD166),
      const Color(0xFFFF7B9C),
    ];
    final max = math.max(1, math.max(steps, average)).toDouble();
    for (var i = 0; i < colors.length; i++) {
      final y = size.height * (i + 0.5) / colors.length;
      final width =
          size.width *
          (0.26 +
              0.74 *
                  ((steps + average * i / colors.length) / max).clamp(
                    0.0,
                    1.0,
                  ));
      final paint = Paint()
        ..color = colors[i].withValues(alpha: 0.75)
        ..strokeWidth = 8
        ..strokeCap = StrokeCap.round;
      canvas.drawLine(
        Offset(8, y),
        Offset(width, y + math.sin(i * 1.4) * 6),
        paint,
      );
    }
  }

  @override
  bool shouldRepaint(
    covariant _NazaHealthdashMonolithWalkingRibbonPainter old,
  ) => old.steps != steps || old.average != average;
}

