    final summary = weekSummary;
    final planned = NazaExerciseProgramEngine.planForWeek(
      widget.state.exerciseProgram,
      DateTime.now(),
    );
    return ListView(
      padding: const EdgeInsets.all(16),
      children: [
        _NazaHealthdashMonolithPageHeader(
          title: 'Movement + Program Studio',
          subtitle:
              'Personal-health rhythm plus an explicit user-configured weekly program. '
