            ButtonSegment(
              value: 1,
              icon: Icon(Icons.view_week_rounded),
              label: Text('Program'),
            ),
            ButtonSegment(
              value: 2,
              icon: Icon(Icons.history_rounded),
              label: Text('History'),
            ),
          ],
          selected: {section},
          onSelectionChanged: (v) => setState(() => section = v.first),
        ),
        const SizedBox(height: 12),
        if (section == 0) ...[
          Wrap(
            spacing: 10,
            runSpacing: 10,
            children: [
              _NazaHealthdashMonolithMetricCard(
                label: 'Walk',
                value:
                    '${totals['walk']!.g}/${widget.state.exercise.dailyWalkGoalMinutes.g} min',
                icon: Icons.directions_walk_rounded,
              ),
              _NazaHealthdashMonolithMetricCard(
                label: 'Light',
                value:
                    '${totals['light']!.g}/${widget.state.exercise.dailyLightGoalMinutes.g} min',
                icon: Icons.fitness_center_rounded,
              ),
              _NazaHealthdashMonolithMetricCard(
                label: 'Stretch',
