class _NazaHealthdashMonolithIntelligencePageState
    extends State<_NazaHealthdashMonolithIntelligencePage> {
  String output = '';
  bool busy = false;
  @override
  Widget build(BuildContext context) => ListView(
    padding: const EdgeInsets.all(16),
    children: [
      Text(
        'Health Intelligence',
        style: Theme.of(
          context,
        ).textTheme.headlineMedium?.copyWith(fontWeight: FontWeight.w900),
      ),
      Text(
        '${widget.state.personality.label}: ${widget.state.personality.subtitle}',
      ),
      const SizedBox(height: 12),
      Wrap(
        spacing: 8,
        runSpacing: 8,
        children: [
          FilledButton.tonal(
            onPressed: busy
                ? null
                : () => _nazaHealthdashMonolithRun(
                    NazaHealthPrompts.dailyCoach(widget.state, DateTime.now()),
                  ),
            child: const Text('Daily brief'),
          ),
          FilledButton.tonal(
            onPressed: busy
                ? null
                : () => _nazaHealthdashMonolithRun(
                    NazaHealthPrompts.weeklyPlanner(
                      widget.state,
                      DateTime.now(),
                    ),
                  ),
            child: const Text('Weekly planner'),
          ),
          FilledButton.tonal(
            onPressed: busy
                ? null
                : () => _nazaHealthdashMonolithRun(
                    NazaHealthPrompts.exerciseSuggestion(widget.state),
                  ),
            child: const Text('Exercise agent'),
          ),
          FilledButton.tonal(
            onPressed: busy
                ? null
                : () => _nazaHealthdashMonolithRun(
                    NazaHealthPrompts.workflowAdvisor(
                      widget.state,
                      DateTime.now(),
                    ),
                  ),
            child: const Text('A–K workflow advisor'),
          ),
          FilledButton.tonal(
            onPressed: busy
                ? null
                : () => _nazaHealthdashMonolithRun(
                    NazaHealthPrompts.mealPlanFeedback(
                      widget.state,
                      DateTime.now(),
                    ),
                  ),
            child: const Text('Food-plan feedback'),
          ),
        ],
      ),
      if (busy)
        const Padding(
          padding: EdgeInsets.all(20),
          child: Center(child: CircularProgressIndicator()),
        ),
      if (output.isNotEmpty)
        Padding(
          padding: const EdgeInsets.only(top: 12),
          child: SelectableText(output),
        ),
    ],
  );
  Future<void> _nazaHealthdashMonolithRun(String prompt) async {
    setState(() => busy = true);
    try {
      final result = await widget.agent.runText(
        systemInstruction: NazaHealthPrompts.baseSafety,
        prompt: prompt,
      );
      if (mounted) setState(() => output = result);
    } finally {
      if (mounted) setState(() => busy = false);
    }
  }
}

