class AppController extends ChangeNotifier {
  static const _appControllerActiveCarsKey = 'active_car_ids';
  static const _appControllerVolumeKey = 'engine_volume';
  static const _appControllerHapticsKey = 'haptics';
  static const _appControllerAutoAdvanceKey = 'auto_advance';
  static const _appControllerShowNumbersKey = 'show_sequence_numbers';
  static const _appControllerDifficultyKey = 'difficulty';
  static const _appControllerPlayersKey = 'party_players';
  static const _appControllerUnlockedKey = 'unlocked_achievements';
  static const _appControllerPreviewedKey = 'previewed_cars';

  static const _appControllerGamesKey = 'stats_games';
  static const _appControllerWinsKey = 'stats_wins';
  static const _appControllerBestRoundKey = 'stats_best_round';
  static const _appControllerBestScoreKey = 'stats_best_score';
  static const _appControllerCorrectInputsKey = 'stats_correct_inputs';

  SharedPreferences? _appControllerPreferences;
  Timer? _appControllerSaveDebounce;

  bool isReady = false;
  double engineVolume = 0.82;
  bool hapticsEnabled = true;
  bool autoAdvance = true;
  bool showSequenceNumbers = true;
  Difficulty difficulty = Difficulty.sport;
  GameMode selectedMode = GameMode.classic;

  List<String> activeCarIds = List<String>.of(defaultActiveCarIds);
  List<PartyPlayer> partyPlayers = const [
    PartyPlayer(id: 'driver-1', name: 'YOU', colorValue: 0xFF9B5CFF),
    PartyPlayer(id: 'driver-2', name: 'MAYA', colorValue: 0xFF22D3EE),
    PartyPlayer(id: 'driver-3', name: 'JAY', colorValue: 0xFF76FF03),
    PartyPlayer(id: 'driver-4', name: 'LEX', colorValue: 0xFFFF6D3A),
  ];
  Set<String> unlockedAchievementIds = <String>{};
  Set<String> previewedCarIds = <String>{};
  GameStats stats = const GameStats();

  List<CarProfile> get activeCars =>
      activeCarIds.map(carById).toList(growable: false);

  int get totalXp => achievementCatalog
      .where((achievement) => unlockedAchievementIds.contains(achievement.id))
      .fold(0, (sum, achievement) => sum + achievement.xp);

  Future<void> initialize() async {
    _appControllerPreferences = await SharedPreferences.getInstance();
    final prefs = _appControllerPreferences!;

    final storedCars = prefs.getStringList(_appControllerActiveCarsKey);
    if (storedCars != null) {
      final valid = storedCars
          .where((id) => carCatalog.any((car) => car.id == id))
          .toList();
      if (valid.length >= 4) {
        activeCarIds = valid.take(8).toList();
      }
    }

    engineVolume = prefs.getDouble(_appControllerVolumeKey) ?? engineVolume;
    hapticsEnabled = prefs.getBool(_appControllerHapticsKey) ?? hapticsEnabled;
    autoAdvance = prefs.getBool(_appControllerAutoAdvanceKey) ?? autoAdvance;
    showSequenceNumbers =
        prefs.getBool(_appControllerShowNumbersKey) ?? showSequenceNumbers;

    final storedDifficulty = prefs.getString(_appControllerDifficultyKey);
    difficulty = Difficulty.values.firstWhere(
      (value) => value.name == storedDifficulty,
      orElse: () => difficulty,
    );

    final encodedPlayers = prefs.getStringList(_appControllerPlayersKey);
    if (encodedPlayers != null && encodedPlayers.isNotEmpty) {
      try {
        partyPlayers = encodedPlayers
            .map(
              (entry) => PartyPlayer.fromJson(
                jsonDecode(entry) as Map<String, Object?>,
              ),
            )
            .toList();
      } on FormatException {
        // Keep defaults if a previous save was malformed.
      }
    }

    unlockedAchievementIds =
        (prefs.getStringList(_appControllerUnlockedKey) ?? const <String>[])
            .toSet();
    previewedCarIds =
        (prefs.getStringList(_appControllerPreviewedKey) ?? const <String>[])
            .toSet();
    stats = GameStats(
      gamesPlayed: prefs.getInt(_appControllerGamesKey) ?? 0,
      wins: prefs.getInt(_appControllerWinsKey) ?? 0,
      bestRound: prefs.getInt(_appControllerBestRoundKey) ?? 0,
      bestScore: prefs.getInt(_appControllerBestScoreKey) ?? 0,
      totalCorrectInputs: prefs.getInt(_appControllerCorrectInputsKey) ?? 0,
    );

    isReady = true;
    notifyListeners();
  }

  void selectMode(GameMode mode) {
    selectedMode = mode;
    notifyListeners();
  }

  void setEngineVolume(double value) {
    engineVolume = value.clamp(0.0, 1.0).toDouble();
    notifyListeners();
    _appControllerScheduleSave();
  }

  void setHaptics(bool value) {
    hapticsEnabled = value;
    notifyListeners();
    _appControllerScheduleSave();
  }

  void setAutoAdvance(bool value) {
    autoAdvance = value;
    notifyListeners();
    _appControllerScheduleSave();
  }

  void setShowSequenceNumbers(bool value) {
    showSequenceNumbers = value;
    notifyListeners();
    _appControllerScheduleSave();
  }

  void setDifficulty(Difficulty value) {
    difficulty = value;
    notifyListeners();
    _appControllerScheduleSave();
  }

  bool toggleActiveCar(String id) {
    if (activeCarIds.contains(id)) {
      if (activeCarIds.length <= 4) {
        return false;
      }
      activeCarIds.remove(id);
    } else {
      if (activeCarIds.length >= 8) {
        return false;
      }
      activeCarIds.add(id);
    }
    if (activeCarIds.length == 8) {
      unlockAchievement('garage_collector');
    }
    notifyListeners();
    _appControllerScheduleSave();
    return true;
  }

  void recordCarPreview(String id) {
    previewedCarIds.add(id);
    if (previewedCarIds.length == carCatalog.length) {
      unlockAchievement('sound_check');
    }
    notifyListeners();
    _appControllerScheduleSave();
  }

  void addPartyPlayer(String name) {
    if (partyPlayers.length >= 8 || name.trim().isEmpty) {
      return;
    }
    const colors = [
      0xFFFF4FB8,
      0xFFFFC93D,
      0xFF53F087,
      0xFF2979FF,
      0xFFFF6D3A,
      0xFF00E5FF,
      0xFFB388FF,
      0xFFFF5252,
    ];
    partyPlayers = [
      ...partyPlayers,
      PartyPlayer(
        id: 'driver-${DateTime.now().microsecondsSinceEpoch}',
        name: name.trim().toUpperCase(),
        colorValue: colors[partyPlayers.length % colors.length],
      ),
    ];
    notifyListeners();
    _appControllerScheduleSave();
  }

  void removePartyPlayer(String id) {
    if (partyPlayers.length <= 2) {
      return;
    }
    partyPlayers = partyPlayers.where((player) => player.id != id).toList();
    notifyListeners();
    _appControllerScheduleSave();
  }

  void renamePartyPlayer(String id, String name) {
    partyPlayers = partyPlayers
        .map(
          (player) => player.id == id
              ? player.copyWith(name: name.trim().toUpperCase())
              : player,
        )
        .toList();
    notifyListeners();
    _appControllerScheduleSave();
  }

  void recordPartyResults(List<PartyPlayer> results) {
    final scoresById = {for (final player in results) player.id: player.score};
    partyPlayers = partyPlayers.map((player) {
      final resultScore = scoresById[player.id] ?? 0;
      return player.copyWith(
        score: resultScore > player.score ? resultScore : player.score,
        lives: 3,
      );
    }).toList();
    notifyListeners();
    _appControllerScheduleSave();
  }

  void recordCorrectInput() {
    stats = stats.copyWith(totalCorrectInputs: stats.totalCorrectInputs + 1);
    _appControllerScheduleSave();
  }

  void recordGame({
    required int round,
    required int score,
    required bool won,
    required int mistakes,
    required GameMode mode,
  }) {
    stats = stats.copyWith(
      gamesPlayed: stats.gamesPlayed + 1,
      wins: stats.wins + (won ? 1 : 0),
      bestRound: round > stats.bestRound ? round : stats.bestRound,
      bestScore: score > stats.bestScore ? score : stats.bestScore,
    );
    unlockAchievement('first_ignition');
    if (round >= 10) {
      unlockAchievement('pattern_master');
    }
    if (round >= 5 && mistakes == 0) {
      unlockAchievement('perfect_lap');
    }
    if (mode == GameMode.party) {
      unlockAchievement('party_starter');
    }
    if (difficulty == Difficulty.redline && round >= 15) {
      unlockAchievement('redline_memory');
    }
    notifyListeners();
    _appControllerScheduleSave();
  }

  void unlockAchievement(String id) {
    if (unlockedAchievementIds.add(id)) {
      notifyListeners();
      _appControllerScheduleSave();
    }
  }

  Future<void> resetStats() async {
    stats = const GameStats();
    unlockedAchievementIds.clear();
    previewedCarIds.clear();
    partyPlayers = partyPlayers
        .map((player) => player.copyWith(score: 0, lives: 3))
        .toList();
    notifyListeners();
    await _appControllerSave();
  }

  void _appControllerScheduleSave() {
    _appControllerSaveDebounce?.cancel();
    _appControllerSaveDebounce = Timer(
      const Duration(milliseconds: 250),
      _appControllerSave,
    );
  }

  Future<void> _appControllerSave() async {
    final prefs = _appControllerPreferences;
    if (prefs == null) {
      return;
    }
    await Future.wait([
      prefs.setStringList(_appControllerActiveCarsKey, activeCarIds),
      prefs.setDouble(_appControllerVolumeKey, engineVolume),
      prefs.setBool(_appControllerHapticsKey, hapticsEnabled),
      prefs.setBool(_appControllerAutoAdvanceKey, autoAdvance),
      prefs.setBool(_appControllerShowNumbersKey, showSequenceNumbers),
      prefs.setString(_appControllerDifficultyKey, difficulty.name),
      prefs.setStringList(
        _appControllerPlayersKey,
        partyPlayers.map((player) => jsonEncode(player.toJson())).toList(),
      ),
      prefs.setStringList(
        _appControllerUnlockedKey,
        unlockedAchievementIds.toList(),
      ),
      prefs.setStringList(_appControllerPreviewedKey, previewedCarIds.toList()),
      prefs.setInt(_appControllerGamesKey, stats.gamesPlayed),
      prefs.setInt(_appControllerWinsKey, stats.wins),
      prefs.setInt(_appControllerBestRoundKey, stats.bestRound),
      prefs.setInt(_appControllerBestScoreKey, stats.bestScore),
      prefs.setInt(_appControllerCorrectInputsKey, stats.totalCorrectInputs),
    ]);
  }

  @override
  void dispose() {
    _appControllerSaveDebounce?.cancel();
    unawaited(_appControllerSave());
    super.dispose();
  }
}

