Future<void> runRevRecallStandalone() async {
  WidgetsFlutterBinding.ensureInitialized();
  runApp(const RevRecallBootstrap());
}

class RevRecallBootstrap extends StatefulWidget {
  const RevRecallBootstrap({super.key});

  @override
  State<RevRecallBootstrap> createState() =>
      _RevRecallRevRecallBootstrapState();
}

class _RevRecallRevRecallBootstrapState extends State<RevRecallBootstrap> {
  late final AppController controller;
  late final EngineAudioService audio;

  @override
  void initState() {
    super.initState();
    controller = AppController();
    audio = EngineAudioService();
    controller.initialize();
  }

  @override
  void dispose() {
    controller.dispose();
    audio.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AppScope(
      notifier: controller,
      audio: audio,
      child: AnimatedBuilder(
        animation: controller,
        builder: (context, _) {
          if (!controller.isReady) {
            return const _RevRecallSplashScreen();
          }
          return const AppShell();
        },
      ),
    );
  }
}

class _RevRecallSplashScreen extends StatelessWidget {
  const _RevRecallSplashScreen();

  @override
  Widget build(BuildContext context) {
    return const Scaffold(
      body: NeonBackground(
        child: Center(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              GradientTitle(text: 'REV//RECALL', fontSize: 36),
              SizedBox(height: 20),
              CircularProgressIndicator(),
              SizedBox(height: 12),
              Text('WARMING UP THE GARAGE'),
            ],
          ),
        ),
      ),
    );
  }
}

