// SOURCE SECTION: lib/naza_rev_recall/screens/game_screen.dart
// ============================================================================

class GameScreen extends StatefulWidget {
  const GameScreen({required this.mode, super.key});

  final GameMode mode;

  @override
  State<GameScreen> createState() => _GameScreenGameScreenState();
}

class _GameScreenGameScreenState extends State<GameScreen> {
  late final GameController controller;
  bool _gameScreenInitialized = false;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_gameScreenInitialized) {
      return;
    }
    _gameScreenInitialized = true;
    final app = AppScope.of(context);
    controller = GameController(
      app: app,
      audio: AppScope.audioOf(context),
      mode: widget.mode,
    );
    WidgetsBinding.instance.addPostFrameCallback((_) => controller.start());
  }

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  Future<bool> _gameScreenHandleBack() async {
    if (controller.phase != GamePhase.gameOver &&
        controller.phase != GamePhase.idle) {
      final leave = await showDialog<bool>(
        context: context,
        builder: (context) => AlertDialog(
          title: const Text('Exit this run?'),
          content: const Text(
            'Your current run will be recorded as incomplete.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context, false),
              child: const Text('STAY'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(context, true),
              child: const Text('EXIT'),
            ),
          ],
        ),
      );
      if (leave != true) {
        return false;
      }
      await controller.finish(won: false);
    }
    return true;
  }

  @override
  Widget build(BuildContext context) {
    final canPop =
        controller.phase == GamePhase.gameOver ||
        controller.phase == GamePhase.idle;
    return PopScope(
      canPop: canPop,
      onPopInvokedWithResult: (didPop, _) async {
        if (didPop || !await _gameScreenHandleBack() || !context.mounted) {
          return;
        }
        Navigator.of(context).pop();
      },
      child: Scaffold(
        body: NeonBackground(
          child: AnimatedBuilder(
            animation: controller,
            builder: (context, _) {
              return LayoutBuilder(
                builder: (context, constraints) {
                  final wheelSize = math.min(380.0, constraints.maxWidth - 34);
                  return SingleChildScrollView(
                    padding: const EdgeInsets.fromLTRB(16, 10, 16, 28),
                    child: Center(
                      child: ConstrainedBox(
                        constraints: const BoxConstraints(maxWidth: 760),
                        child: Column(
                          children: [
                            _GameScreenGameTopBar(controller: controller),
                            const SizedBox(height: 12),
                            _GameScreenSequenceProgress(controller: controller),
                            const SizedBox(height: 12),
                            Text(
                              controller.statusText,
                              textAlign: TextAlign.center,
                              style: Theme.of(context).textTheme.titleLarge
                                  ?.copyWith(letterSpacing: 0.8),
                            ),
                            if (controller.currentPlayer != null) ...[
                              const SizedBox(height: 5),
                              Text(
                                '${controller.currentPlayer!.name}\'S TURN',
                                style: TextStyle(
                                  color: controller.currentPlayer!.color,
                                  fontWeight: FontWeight.w800,
                                ),
                              ),
                            ],
                            const SizedBox(height: 14),
                            CarWheel(
                              cars: controller.activeCars,
                              centerLabel: '${controller.round}',
                              highlightedCarId: controller.highlightedCarId,
                              enabled: controller.acceptsInput,
                              onCarTap: controller.tapCar,
                              size: wheelSize,
                            ),
                            const SizedBox(height: 16),
                            _GameScreenInputStrip(controller: controller),
                            if (widget.mode == GameMode.party) ...[
                              const SizedBox(height: 14),
                              _GameScreenPartyStandings(controller: controller),
                            ],
                            const SizedBox(height: 14),
                            _GameScreenResultPanel(controller: controller),
                          ],
                        ),
                      ),
                    ),
                  );
                },
              );
            },
          ),
        ),
      ),
    );
  }
}

class _GameScreenGameTopBar extends StatelessWidget {
  const _GameScreenGameTopBar({required this.controller});

  final GameController controller;

  @override
  Widget build(BuildContext context) {
    return Row(
      children: [
        IconButton.filledTonal(
          onPressed: () => Navigator.maybePop(context),
          icon: const Icon(Icons.arrow_back_rounded),
        ),
        const SizedBox(width: 10),
