                    NeonPanel(
                      borderColor: AppColors.cyan.withValues(alpha: 0.4),
                      child: const Row(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Icon(
                            Icons.info_outline_rounded,
                            color: AppColors.cyan,
                          ),
                          SizedBox(width: 12),
                          Expanded(
                            child: Text(
                              'Party Mode uses one phone. Pass it to the highlighted driver after each round. '
                              'Each driver has three lives and an independent score.',
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  Future<void> _playersScreenAddPlayer(BuildContext context) async {
    final name = await _playersScreenNameDialog(context, title: 'Add driver');
    if (name != null && context.mounted) {
      AppScope.of(context).addPartyPlayer(name);
    }
  }

  Future<void> _playersScreenRenamePlayer(
    BuildContext context,
    PartyPlayer player,
  ) async {
    final name = await _playersScreenNameDialog(
      context,
      title: 'Rename driver',
      initialValue: player.name,
    );
    if (name != null && context.mounted) {
      AppScope.of(context).renamePartyPlayer(player.id, name);
    }
  }

  Future<String?> _playersScreenNameDialog(
    BuildContext context, {
    required String title,
    String initialValue = '',
  }) async {
    final controller = TextEditingController(text: initialValue);
    final result = await showDialog<String>(
      context: context,
      builder: (context) => AlertDialog(
        title: Text(title),
        content: TextField(
          controller: controller,
          autofocus: true,
          maxLength: 12,
          textCapitalization: TextCapitalization.characters,
          decoration: const InputDecoration(labelText: 'Driver name'),
          onSubmitted: (value) => Navigator.pop(context, value.trim()),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('CANCEL'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, controller.text.trim()),
            child: const Text('SAVE'),
          ),
        ],
      ),
    );
    controller.dispose();
    return result?.trim().isEmpty == true ? null : result;
  }
}

