class NeonBackground extends StatelessWidget {
  const NeonBackground({required this.child, super.key});

  final Widget child;

  @override
  Widget build(BuildContext context) {
    return DecoratedBox(
      decoration: BoxDecoration(
        gradient: RadialGradient(
          center: Alignment(0, -0.65),
          radius: 1.15,
          colors: [
            Color.alphaBlend(
              Theme.of(context).colorScheme.primary.withValues(alpha: .16),
              Theme.of(context).colorScheme.surface,
            ),
            Theme.of(context).scaffoldBackgroundColor,
          ],
          stops: [0, 0.72],
        ),
      ),
      child: Stack(
        fit: StackFit.expand,
        children: [
          const IgnorePointer(child: _NeonWidgetsGridOverlay()),
          SafeArea(child: child),
        ],
      ),
    );
  }
}

class _NeonWidgetsGridOverlay extends StatelessWidget {
  const _NeonWidgetsGridOverlay();

  @override
  Widget build(BuildContext context) {
    return CustomPaint(painter: _NeonWidgetsGridPainter());
  }
}

class _NeonWidgetsGridPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = AppColors.cyan.withValues(alpha: 0.035)
      ..strokeWidth = 1;
    const spacing = 36.0;
    for (var x = 0.0; x < size.width; x += spacing) {
      canvas.drawLine(Offset(x, 0), Offset(x, size.height), paint);
    }
    for (var y = 0.0; y < size.height; y += spacing) {
      canvas.drawLine(Offset(0, y), Offset(size.width, y), paint);
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

class NeonPanel extends StatelessWidget {
  const NeonPanel({
    required this.child,
    this.padding = const EdgeInsets.all(16),
    this.borderColor,
    this.glowColor,
    this.onTap,
    super.key,
  });

  final Widget child;
  final EdgeInsetsGeometry padding;
  final Color? borderColor;
  final Color? glowColor;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    final panel = AnimatedContainer(
      duration: const Duration(milliseconds: 180),
      padding: padding,
      decoration: BoxDecoration(
        color: Theme.of(context).colorScheme.surface.withValues(alpha: 0.94),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: borderColor ?? Theme.of(context).colorScheme.outlineVariant,
        ),
        boxShadow: glowColor == null
            ? const []
            : [
                BoxShadow(
                  color: glowColor!.withValues(alpha: 0.22),
                  blurRadius: 18,
                  spreadRadius: 1,
                ),
              ],
      ),
      child: child,
    );
    return onTap == null
        ? panel
        : InkWell(
            onTap: onTap,
            borderRadius: BorderRadius.circular(16),
            child: panel,
          );
  }
}

class NeonButton extends StatelessWidget {
  const NeonButton({
    required this.label,
    required this.onPressed,
    this.icon,
    this.color = AppColors.purple,
    this.expanded = true,
    this.enabled = true,
    super.key,
  });

  final String label;
  final VoidCallback onPressed;
  final IconData? icon;
  final Color color;
  final bool expanded;
  final bool enabled;

  @override
  Widget build(BuildContext context) {
    final button = DecoratedBox(
      decoration: BoxDecoration(
        gradient: LinearGradient(
          colors: [
            color.withValues(alpha: 0.95),
            color.withValues(alpha: 0.55),
          ],
        ),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: color.withValues(alpha: 0.95)),
        boxShadow: [
          BoxShadow(color: color.withValues(alpha: 0.28), blurRadius: 18),
        ],
      ),
      child: FilledButton.icon(
        onPressed: enabled ? onPressed : null,
        icon: icon == null ? const SizedBox.shrink() : Icon(icon),
        label: Padding(
          padding: const EdgeInsets.symmetric(vertical: 14),
          child: Text(label.toUpperCase()),
        ),
        style: FilledButton.styleFrom(
          backgroundColor: Colors.transparent,
          disabledBackgroundColor: Colors.transparent,
          shadowColor: Colors.transparent,
          foregroundColor: Colors.white,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(14),
          ),
        ),
      ),
    );
    return expanded ? SizedBox(width: double.infinity, child: button) : button;
  }
}

class GradientTitle extends StatelessWidget {
  const GradientTitle({required this.text, this.fontSize = 44, super.key});

  final String text;
  final double fontSize;

  @override
