// LLM-CONTEXT:BEGIN
// FILE: lib/onboarding/boot_coordinator.dart
// ROLE: Owns boot coordinator behavior within the onboarding subsystem.
// DOMAIN: onboarding
// SECURITY-INVARIANT: Complete vault establishment and artifact verification before entering private application surfaces.
// CHANGE-GUARD: Preserve public contracts, bounded inputs, lifecycle cleanup, and fail-closed behavior; run analysis and relevant tests after edits.
// DOCS: See /docs/llm-context-schema.md and the nearest mermaid.md architecture map.
// LLM-CONTEXT:END

enum _BootCoordinatorBootStage {
  loading,
  security,
  model,
  guide,
  themes,
  preparing,
  home,
}

final class NazaBootDiagnostics {
  NazaBootDiagnostics._();

  static final Stopwatch _bootCoordinatorClock = Stopwatch()..start();

  static void log(String message) {
    developer.log(
      '[+${_bootCoordinatorClock.elapsedMilliseconds}ms] $message',
      name: 'NazaBoot',
    );
  }

  static void failure(String step, Object error, StackTrace stackTrace) {
    developer.log(
      '[+${_bootCoordinatorClock.elapsedMilliseconds}ms] FAIL $step: $error',
      name: 'NazaBoot',
      error: error,
      stackTrace: stackTrace,
    );
  }
}

/// Naza's vault-first startup coordinator.
///
/// First-run order is intentionally explicit:
/// 1. establish encrypted storage (passwordless secure-storage mode by default),
/// 2. obtain/verify the model,
/// 3. optional AI/product guide,
/// 4. theme selection,
/// 5. open Chat; native AI loading begins only when the user sends a prompt.
final class NazaBootCoordinator extends StatefulWidget {
  const NazaBootCoordinator({super.key});

  static Future<void> launch() async {
    WidgetsFlutterBinding.ensureInitialized();
    if (Platform.isAndroid || Platform.isIOS) {
      await SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);
      await SystemChrome.setPreferredOrientations(const <DeviceOrientation>[
        DeviceOrientation.portraitUp,
        DeviceOrientation.portraitDown,
      ]);
      SystemChrome.setSystemUIOverlayStyle(
        const SystemUiOverlayStyle(
          statusBarColor: Colors.transparent,
          systemNavigationBarColor: Color(0xFF020806),
          statusBarIconBrightness: Brightness.light,
          systemNavigationBarIconBrightness: Brightness.light,
          systemNavigationBarContrastEnforced: false,
        ),
      );
    }
    runApp(const NazaBootCoordinator());
  }

  @override
  State<NazaBootCoordinator> createState() =>
      _BootCoordinatorNazaBootCoordinatorState();
}

final class _BootCoordinatorNazaBootCoordinatorState
    extends State<NazaBootCoordinator> {
  static const String _bootCoordinatorOnboardingNamespace = 'naza-first-run-v3';
  static const String _bootCoordinatorOnboardingCompleteKey = 'complete';

  final NazaSecureDatabase _bootCoordinatorVault = NazaSecureDatabase.instance;
  final NazaLocalModelPreference _bootCoordinatorLocalPreference =
      NazaLocalModelPreference();
  final TextEditingController _bootCoordinatorPassword =
      TextEditingController();
  final TextEditingController _bootCoordinatorConfirmPassword =
      TextEditingController();
  final TextEditingController _bootCoordinatorUnlockPassword =
      TextEditingController();
  final PageController _bootCoordinatorGuideController = PageController();

  _BootCoordinatorBootStage _bootCoordinatorStage =
      _BootCoordinatorBootStage.loading;
  // Headless Linux sessions commonly have no unlocked Secret Service. Use
  // explicit password protection by default so first launch is reliable.
  bool _bootCoordinatorRequirePassword = Platform.isLinux;
  bool _bootCoordinatorExistingPasswordVault = false;
  bool _bootCoordinatorBusy = false;
  bool _bootCoordinatorUseLocalModel = false;
  bool _bootCoordinatorDownloadPaused = false;
  bool _bootCoordinatorModelReady = false;
  bool _bootCoordinatorSentinelReady = false;
  String _bootCoordinatorDownloadArtifactLabel = 'Gemma model';
  String? _bootCoordinatorError;
  String _bootCoordinatorStatus = 'Preparing private local storage…';
  String _bootCoordinatorThemeId = NazaBootThemeCatalog.defaultId;
  int _bootCoordinatorGuidePage = 0;
  NazaDownloadSnapshot? _bootCoordinatorDownload;
  NazaDownloadSnapshot? _bootCoordinatorPendingDownload;
  NazaTransferController? _bootCoordinatorTransferControl;
  NazaPausableModelDownloader? _bootCoordinatorActiveDownloader;
  Timer? _bootCoordinatorDownloadPaintTimer;
  DateTime _bootCoordinatorLastDownloadPaint =
      DateTime.fromMillisecondsSinceEpoch(0);
  String? _bootCoordinatorCachedThemeId;
  ThemeData? _bootCoordinatorCachedTheme;

  NazaBootTheme get _bootCoordinatorTheme =>
      NazaBootThemeCatalog.byId(_bootCoordinatorThemeId);
  ThemeData get _bootCoordinatorThemeData {
    if (_bootCoordinatorCachedThemeId != _bootCoordinatorThemeId ||
        _bootCoordinatorCachedTheme == null) {
      _bootCoordinatorCachedThemeId = _bootCoordinatorThemeId;
      _bootCoordinatorCachedTheme = _bootCoordinatorTheme.build();
    }
    return _bootCoordinatorCachedTheme!;
  }

  bool get _bootCoordinatorDesktop =>
      Platform.isWindows || Platform.isLinux || Platform.isMacOS;

  bool get _bootCoordinatorAllModelsReady =>
      _bootCoordinatorModelReady && _bootCoordinatorSentinelReady;

  Future<T> _bootCoordinatorTrace<T>(
    String step,
    Future<T> Function() operation,
  ) async {
    final timer = Stopwatch()..start();
    NazaBootDiagnostics.log('START $step');
    try {
      final result = await operation();
      NazaBootDiagnostics.log('DONE $step in ${timer.elapsedMilliseconds}ms');
      return result;
    } catch (error, stackTrace) {
      NazaBootDiagnostics.failure(
        '$step after ${timer.elapsedMilliseconds}ms',
        error,
        stackTrace,
      );
      rethrow;
    }
  }

  @override
  void initState() {
    super.initState();
    NazaBootDiagnostics.log('coordinator initialized');
    unawaited(_bootCoordinatorBootstrap());
  }

  @override
  void dispose() {
    _bootCoordinatorPassword.dispose();
    _bootCoordinatorConfirmPassword.dispose();
    _bootCoordinatorUnlockPassword.dispose();
    _bootCoordinatorGuideController.dispose();
    _bootCoordinatorDownloadPaintTimer?.cancel();
    _bootCoordinatorTransferControl?.cancel();
    unawaited(_bootCoordinatorActiveDownloader?.close());
    super.dispose();
  }

  Future<void> _bootCoordinatorBootstrap() async {
    try {
      final inspection = await _bootCoordinatorTrace(
        'vault inspection',
        _bootCoordinatorVault.inspect,
      );
      NazaBootDiagnostics.log(
        'vault inspection result: access=${inspection.access.name}, '
        'passwordRequired=${inspection.passwordRequired}, '
        'legacyDataPresent=${inspection.legacyDataPresent}',
      );
      if (!mounted) return;
      switch (inspection.access) {
        case NazaVaultAccess.setupRequired:
          setState(() {
            _bootCoordinatorStage = _BootCoordinatorBootStage.security;
            _bootCoordinatorExistingPasswordVault = false;
            _bootCoordinatorRequirePassword =
                false; // UX default: encrypted, no boot password.
            _bootCoordinatorStatus =
                'Choose how Naza One unlocks on this device.';
          });
          return;
        case NazaVaultAccess.locked:
          if (inspection.passwordRequired) {
            setState(() {
              _bootCoordinatorStage = _BootCoordinatorBootStage.security;
              _bootCoordinatorExistingPasswordVault = true;
              _bootCoordinatorRequirePassword = true;
              _bootCoordinatorStatus = 'Unlock your encrypted Naza One vault.';
            });
            return;
          }
          await _bootCoordinatorTrace(
            'device-key vault unlock',
            _bootCoordinatorVault.unlockWithDeviceKey,
          );
          await _bootCoordinatorTrace(
            'post-unlock startup handoff',
            () => _bootCoordinatorAfterVaultUnlocked(),
          );
          return;
        case NazaVaultAccess.unlocked:
          await _bootCoordinatorTrace(
            'already-unlocked startup handoff',
            () => _bootCoordinatorAfterVaultUnlocked(),
          );
          return;
      }
    } catch (error, stackTrace) {
      NazaBootDiagnostics.failure('bootstrap', error, stackTrace);
      if (!mounted) return;
      setState(() {
        _bootCoordinatorStage = _BootCoordinatorBootStage.security;
        _bootCoordinatorError = '$error';
        _bootCoordinatorStatus = 'Encrypted storage needs attention.';
      });
    }
  }

  Future<void> _bootCoordinatorCreateVault() async {
    if (_bootCoordinatorBusy) return;
    if (Platform.isLinux) _bootCoordinatorRequirePassword = true;
    final password = _bootCoordinatorPassword.text;
    if (_bootCoordinatorRequirePassword) {
      if (password.length < 12) {
        setState(
          () => _bootCoordinatorError =
              'Use at least 12 characters for the boot password.',
        );
        return;
      }
      if (password != _bootCoordinatorConfirmPassword.text) {
        setState(
          () => _bootCoordinatorError = 'The two passwords do not match.',
        );
        return;
      }
    }
    setState(() {
      _bootCoordinatorBusy = true;
      _bootCoordinatorError = null;
      _bootCoordinatorStatus = _bootCoordinatorRequirePassword
          ? 'Deriving encrypted vault keys…'
          : 'Creating encrypted vault + protected device unlock key…';
    });
    try {
      await _bootCoordinatorTrace(
        'vault creation',
        () => _bootCoordinatorVault.create(
          password: _bootCoordinatorRequirePassword ? password : '',
          passwordRequired: _bootCoordinatorRequirePassword,
        ),
      );
      await _bootCoordinatorTrace(
        'post-create startup handoff',
        () => _bootCoordinatorAfterVaultUnlocked(firstRun: true),
      );
    } catch (error, stackTrace) {
      NazaBootDiagnostics.failure('create vault flow', error, stackTrace);
      if (mounted) setState(() => _bootCoordinatorError = '$error');
    } finally {
      if (mounted) setState(() => _bootCoordinatorBusy = false);
    }
  }

  Future<void> _bootCoordinatorUnlockVault() async {
    if (_bootCoordinatorBusy) return;
    setState(() {
      _bootCoordinatorBusy = true;
      _bootCoordinatorError = null;
      _bootCoordinatorStatus = 'Authenticating encrypted vault…';
    });
    try {
      await _bootCoordinatorTrace(
        'password vault unlock',
        () => _bootCoordinatorVault.unlock(_bootCoordinatorUnlockPassword.text),
      );
      await _bootCoordinatorTrace(
        'post-password-unlock startup handoff',
        () => _bootCoordinatorAfterVaultUnlocked(),
      );
    } catch (error, stackTrace) {
      NazaBootDiagnostics.failure('password unlock flow', error, stackTrace);
      if (mounted)
        setState(() => _bootCoordinatorError = 'Unlock failed: $error');
    } finally {
      if (mounted) setState(() => _bootCoordinatorBusy = false);
    }
  }

  Future<void> _bootCoordinatorAfterVaultUnlocked({
    bool firstRun = false,
  }) async {
    await _bootCoordinatorTrace<void>('read saved theme', NazaThemeStore.load);
    final savedThemeId = NazaThemeStore.selectedId.value;
    final completeRaw = await _bootCoordinatorTrace(
      'read onboarding completion marker',
      () => _bootCoordinatorVault.readJson(
        _bootCoordinatorOnboardingNamespace,
        _bootCoordinatorOnboardingCompleteKey,
      ),
    );
    final complete = completeRaw is Map && completeRaw['complete'] == true;

    if (!mounted) return;
    setState(() {
      _bootCoordinatorThemeId = NazaBootThemeCatalog.byId(savedThemeId).id;
      _bootCoordinatorStage = _BootCoordinatorBootStage.loading;
      _bootCoordinatorStatus = 'Checking trusted local model…';
      _bootCoordinatorError = null;
    });

    // Check the managed cache first. Re-validating a persisted Windows local
    // model preference here can hash a multi-gigabyte file before the model
    // store gets a chance to use its existing attestation.
    var modelStatus = await _bootCoordinatorTrace(
      'managed model cache refresh',
      NazaSecureModelStore.refresh,
    );
    NazaBootDiagnostics.log(
      'managed model cache refresh result: installed=${modelStatus.installed}, '
      'phase=${modelStatus.phase}',
    );
    if (!modelStatus.installed) {
      if (mounted) {
        setState(
          () => _bootCoordinatorStatus = 'Verifying selected local model…',
        );
      }
      await _bootCoordinatorTrace(
        'restore preferred local model',
        _bootCoordinatorRestorePreferredLocalModel,
      );
      modelStatus = await _bootCoordinatorTrace(
        'managed model cache refresh after local restore',
        NazaSecureModelStore.refresh,
      );
      NazaBootDiagnostics.log(
        'post-restore model cache result: installed=${modelStatus.installed}, '
        'phase=${modelStatus.phase}',
      );
    }
    _bootCoordinatorModelReady = modelStatus.installed;
    _bootCoordinatorSentinelReady = await _bootCoordinatorTrace(
      'probabilistic harm-filter model verification',
      NazaSentinelModelStore.isInstalled,
    );

    if (!mounted) return;
    if (complete && _bootCoordinatorAllModelsReady && !firstRun) {
      // _unlockVault keeps the coordinator busy while authenticating. Allow
      // the authenticated startup handoff to take ownership of that same
      // busy state; otherwise _prepareAndEnterChat would return immediately
      // and leave the coordinator on the loading screen forever.
      await _bootCoordinatorTrace(
        'authenticated automatic chat handoff',
        () => _bootCoordinatorPrepareAndEnterChat(
          markComplete: false,
          allowBusyHandoff: true,
        ),
      );
      return;
    }
    setState(() {
      _bootCoordinatorStage = _BootCoordinatorBootStage.model;
      _bootCoordinatorStatus = _bootCoordinatorAllModelsReady
          ? 'Verified Gemma and safety sentinel are ready.'
          : _bootCoordinatorModelReady
          ? 'Gemma is ready; install the pinned core safety sentinel.'
          : 'Choose how to install the verified local AI models.';
    });
  }

  Future<void> _bootCoordinatorRestorePreferredLocalModel() async {
    if (!_bootCoordinatorDesktop) {
      NazaBootDiagnostics.log(
        'skip local preference restore: non-desktop platform',
      );
      return;
    }
    try {
      final env = await _bootCoordinatorTrace(
        'verify NAZA_MODEL_PATH override',
        _bootCoordinatorLocalPreference.verifiedEnvironmentOverride,
      );
      if (env != null) {
        NazaBootDiagnostics.log('verified environment model override found');
        await _bootCoordinatorTrace(
          'materialize environment model into managed cache',
          () => _bootCoordinatorLocalPreference.materializeForApp(env),
        );
        return;
      }
      final persisted = await _bootCoordinatorTrace(
        'verify persisted local model selection',
        _bootCoordinatorLocalPreference.verifiedPersistedSelection,
      );
      if (persisted != null) {
        NazaBootDiagnostics.log(
          'verified persisted local model selection found',
        );
        await _bootCoordinatorTrace(
          'materialize persisted model into managed cache',
          () => _bootCoordinatorLocalPreference.materializeForApp(persisted),
        );
      } else {
        NazaBootDiagnostics.log('no verified local model preference found');
      }
    } catch (error, stackTrace) {
      // Model screen will expose the managed-cache state and allow recovery.
      NazaBootDiagnostics.failure(
        'restore preferred local model (falling back to model screen)',
        error,
        stackTrace,
      );
    }
  }

  Future<File> _bootCoordinatorManagedModelTarget() async {
    final support = await getApplicationSupportDirectory();
    return File(
      '${support.path}/verified_models/${NazaModelDistributionManifest.gemma4E2b.modelFileName}',
    );
  }

  Future<void> _bootCoordinatorStartDownload() async {
    if (_bootCoordinatorBusy || _bootCoordinatorAllModelsReady) {
      if (_bootCoordinatorAllModelsReady) _bootCoordinatorGoToGuide();
      return;
    }
    _bootCoordinatorDownloadPaintTimer?.cancel();
    _bootCoordinatorDownloadPaintTimer = null;
    setState(() {
      _bootCoordinatorBusy = true;
      _bootCoordinatorError = null;
      _bootCoordinatorDownload = null;
      _bootCoordinatorPendingDownload = null;
      _bootCoordinatorDownloadPaused = false;
      _bootCoordinatorStatus = 'Loading signed-in-app mirror identity…';
    });

    final control = NazaTransferController();
    _bootCoordinatorTransferControl = control;
    try {
      if (!_bootCoordinatorModelReady) {
        _bootCoordinatorDownloadArtifactLabel = 'Gemma model';
        final manifest = await NazaRuntimeMirrorCatalog.resolve(
          NazaModelDistributionManifest.gemma4E2b,
        );
        final downloader = NazaPausableModelDownloader(
          manifest: manifest,
          control: control,
        );
        _bootCoordinatorActiveDownloader = downloader;
        final target = await _bootCoordinatorManagedModelTarget();
        await downloader.download(
          target: target,
          onProgress: _bootCoordinatorPublishDownloadProgress,
        );
        await downloader.close();
        _bootCoordinatorActiveDownloader = null;
        final refreshed = await NazaSecureModelStore.refresh();
        if (!refreshed.installed) {
          throw StateError(
            'Downloaded Gemma model passed transport verification but app trust refresh did not accept it.',
          );
        }
        _bootCoordinatorModelReady = true;
      }

      if (!_bootCoordinatorSentinelReady) {
        _bootCoordinatorDownloadArtifactLabel = 'Core safety sentinel';
        if (mounted) {
          setState(() {
            _bootCoordinatorDownload = null;
            _bootCoordinatorPendingDownload = null;
            _bootCoordinatorStatus =
                'Preparing the pinned scanner-only safety model…';
          });
        }
        final downloader = NazaPausableModelDownloader(
          manifest: NazaModelDistributionManifest.llama3SmallSentinel,
          control: control,
        );
        _bootCoordinatorActiveDownloader = downloader;
        await downloader.download(
          target: await NazaSentinelModelStore.target(),
          onProgress: _bootCoordinatorPublishDownloadProgress,
        );
        await downloader.close();
        _bootCoordinatorActiveDownloader = null;
        _bootCoordinatorSentinelReady =
            await NazaSentinelModelStore.isInstalled();
        if (!_bootCoordinatorSentinelReady) {
          throw StateError(
            'Downloaded safety sentinel failed the final local trust refresh.',
          );
        }
      }
      if (!mounted) return;
      setState(() {
        _bootCoordinatorModelReady = true;
        _bootCoordinatorSentinelReady = true;
        _bootCoordinatorDownloadPaused = false;
        _bootCoordinatorStatus =
            'Verified Gemma and core safety sentinel ready.';
      });
      _bootCoordinatorGoToGuide();
    } catch (error) {
      if (mounted) {
        setState(() {
          _bootCoordinatorError = '$error';
          _bootCoordinatorStatus =
              'Model download paused by an error. Completed chunks are kept for resume.';
        });
      }
    } finally {
      if (_bootCoordinatorActiveDownloader != null) {
        await _bootCoordinatorActiveDownloader!.close();
        _bootCoordinatorActiveDownloader = null;
      }
      if (mounted) setState(() => _bootCoordinatorBusy = false);
    }
  }

  void _bootCoordinatorPublishDownloadProgress(NazaDownloadSnapshot snapshot) {
    if (!mounted) return;
    final priorStage =
        (_bootCoordinatorPendingDownload ?? _bootCoordinatorDownload)?.stage;
    _bootCoordinatorPendingDownload = snapshot;
    _bootCoordinatorDownload = snapshot;
    if (!_bootCoordinatorDownloadPaused ||
        snapshot.stage == NazaDownloadStage.complete) {
      _bootCoordinatorStatus = switch (snapshot.stage) {
        NazaDownloadStage.probing =>
          'Preparing approved $_bootCoordinatorDownloadArtifactLabel mirrors…',
        NazaDownloadStage.allocating =>
          'Resuming $_bootCoordinatorDownloadArtifactLabel secure chunk spool…',
        NazaDownloadStage.downloading =>
          'Downloading $_bootCoordinatorDownloadArtifactLabel from verified transports…',
        NazaDownloadStage.verifying =>
          'Checking $_bootCoordinatorDownloadArtifactLabel hashes + final SHA-256…',
        NazaDownloadStage.complete =>
          'Verified $_bootCoordinatorDownloadArtifactLabel installed.',
      };
    }

    final now = DateTime.now();
    final stageChanged = priorStage != snapshot.stage;
    final terminal = snapshot.stage == NazaDownloadStage.complete;
    final sincePaint = now.difference(_bootCoordinatorLastDownloadPaint);
    if (stageChanged ||
        terminal ||
        sincePaint >= const Duration(milliseconds: 250)) {
      _bootCoordinatorDownloadPaintTimer?.cancel();
      _bootCoordinatorDownloadPaintTimer = null;
      _bootCoordinatorLastDownloadPaint = now;
      setState(() {});
      return;
    }

    _bootCoordinatorDownloadPaintTimer ??= Timer(
      const Duration(milliseconds: 250) - sincePaint,
      () {
        _bootCoordinatorDownloadPaintTimer = null;
        if (!mounted) return;
        _bootCoordinatorLastDownloadPaint = DateTime.now();
        setState(() {});
      },
    );
  }

  void _bootCoordinatorPauseDownload() {
    final control = _bootCoordinatorTransferControl;
    if (control == null || control.isPaused || control.isCancelled) return;
    control.pause();
    setState(() {
      _bootCoordinatorDownloadPaused = true;
      _bootCoordinatorStatus =
          'Paused — in-memory sockets are back-pressured and completed chunks stay on disk.';
    });
  }

  void _bootCoordinatorResumeDownload() {
    final control = _bootCoordinatorTransferControl;
    if (control == null || !control.isPaused || control.isCancelled) return;
    control.resume();
    setState(() {
      _bootCoordinatorDownloadPaused = false;
      _bootCoordinatorStatus = 'Resuming multi-source model transfer…';
    });
  }

  Future<void> _bootCoordinatorChooseLocalModel() async {
    if (!_bootCoordinatorDesktop || _bootCoordinatorBusy) return;
    setState(() {
      _bootCoordinatorBusy = true;
      _bootCoordinatorError = null;
      _bootCoordinatorStatus = 'Choose the trusted Gemma .litertlm file…';
    });
    try {
      const group = XTypeGroup(
        label: 'LiteRT-LM model',
        extensions: <String>['litertlm'],
      );
      final selected = await openFile(
        acceptedTypeGroups: const <XTypeGroup>[group],
      );
      if (selected == null) {
        if (mounted)
          setState(
            () => _bootCoordinatorStatus = 'Local model selection cancelled.',
          );
        return;
      }
      if (mounted)
        setState(
          () => _bootCoordinatorStatus =
              'Hashing selected model — this can take a moment…',
        );
      final preference = await _bootCoordinatorLocalPreference.verifyAndPersist(
        File(selected.path),
      );
      if (mounted)
        setState(
          () => _bootCoordinatorStatus =
              'Model hash matched. Copying a private verified snapshot…',
        );
      await _bootCoordinatorLocalPreference.materializeForApp(preference);
      final refreshed = await NazaSecureModelStore.refresh();
      if (!refreshed.installed) {
        throw StateError(
          'Verified local model could not be activated by the app model store.',
        );
      }
      if (!mounted) return;
      setState(() {
        _bootCoordinatorModelReady = true;
        _bootCoordinatorSentinelReady = false;
        _bootCoordinatorUseLocalModel = false;
        _bootCoordinatorStatus =
            'Verified Gemma selected. Install the pinned core safety sentinel to continue.';
      });
      if (await NazaSentinelModelStore.isInstalled()) {
        if (!mounted) return;
        setState(() {
          _bootCoordinatorSentinelReady = true;
          _bootCoordinatorStatus =
              'Verified Gemma and core safety sentinel ready.';
        });
        _bootCoordinatorGoToGuide();
      }
    } catch (error) {
      if (mounted)
        setState(() => _bootCoordinatorError = 'Local model rejected: $error');
    } finally {
      if (mounted) setState(() => _bootCoordinatorBusy = false);
    }
  }

  void _bootCoordinatorGoToGuide() {
    if (!mounted) return;
    setState(() {
      _bootCoordinatorStage = _BootCoordinatorBootStage.guide;
      _bootCoordinatorGuidePage = 0;
      _bootCoordinatorError = null;
    });
  }

  void _bootCoordinatorGoToThemes() {
    setState(() {
      _bootCoordinatorStage = _BootCoordinatorBootStage.themes;
      _bootCoordinatorError = null;
    });
  }

  Future<void> _bootCoordinatorSaveTheme(String id) async {
    final theme = NazaBootThemeCatalog.byId(id);
    setState(() => _bootCoordinatorThemeId = theme.id);
    await NazaThemeStore.select(theme.id);
  }

  Future<void> _bootCoordinatorPrepareAndEnterChat({
    bool markComplete = true,
    bool allowBusyHandoff = false,
  }) async {
    if (_bootCoordinatorBusy && !allowBusyHandoff) return;
    setState(() {
      _bootCoordinatorBusy = true;
      _bootCoordinatorStage = _BootCoordinatorBootStage.preparing;
      _bootCoordinatorError = null;
      _bootCoordinatorStatus = 'Loading local AI runtime…';
    });
    try {
      if (markComplete) {
        await _bootCoordinatorTrace(
          'write onboarding completion marker',
          () => _bootCoordinatorVault.writeJson(
            _bootCoordinatorOnboardingNamespace,
            _bootCoordinatorOnboardingCompleteKey,
            <String, Object?>{
              'schema': 'naza-first-run-v3',
              'complete': true,
              'completedAt': DateTime.now().toUtc().toIso8601String(),
            },
          ),
        );
      }
      // Enter the workspace immediately. Loading a multi-gigabyte native model
      // and constructing a LiteRT conversation can take well over a minute on
      // a memory-constrained CPU device; blocking the entire app here made the
      // boot progress appear frozen. These idempotent preparations continue in
      // the background, and the first send awaits the same operations.
      unawaited(NazaLocalGemma.instance.prepareBackendPreference());
      unawaited(NazaSecureModelStore.refresh());
      if (!mounted) return;
      setState(() {
        _bootCoordinatorStage = _BootCoordinatorBootStage.home;
        _bootCoordinatorBusy = false;
        _bootCoordinatorStatus = 'Ready';
      });
    } catch (error, stackTrace) {
      NazaBootDiagnostics.failure('chat handoff', error, stackTrace);
      if (!mounted) return;
      setState(() {
        _bootCoordinatorBusy = false;
        _bootCoordinatorStage = _BootCoordinatorBootStage.model;
        _bootCoordinatorError = 'AI runtime did not become ready: $error';
        _bootCoordinatorStatus =
            'Model is installed, but runtime initialization needs attention.';
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<String>(
      valueListenable: NazaThemeStore.selectedId,
      builder: (_, selectedThemeId, _) {
        final atHome = _bootCoordinatorStage == _BootCoordinatorBootStage.home;
        return MaterialApp(
          debugShowCheckedModeBanner: false,
          title: atHome ? 'Naza One' : 'Naza One · First Run',
          theme: atHome
              ? NazaBootThemeCatalog.byId(selectedThemeId).build()
              : _bootCoordinatorThemeData,
          home: atHome
              ? const NazaStableHome()
              : Scaffold(
                  body: Stack(
                    children: <Widget>[
                      Positioned.fill(
                        child: _BootCoordinatorBootBackdrop(
                          theme: _bootCoordinatorTheme,
                        ),
                      ),
                      SafeArea(
                        // Keep MaterialApp mounted across the boot handoff.
                        // Replacing the complete inherited-widget tree here
                        // can deactivate it before its dependents are removed.
                        child: switch (_bootCoordinatorStage) {
                          _BootCoordinatorBootStage.loading =>
                            _bootCoordinatorLoadingScreen(),
                          _BootCoordinatorBootStage.security =>
                            _bootCoordinatorSecurityScreen(),
                          _BootCoordinatorBootStage.model =>
                            _bootCoordinatorModelScreen(),
                          _BootCoordinatorBootStage.guide =>
                            _bootCoordinatorGuideScreen(),
                          _BootCoordinatorBootStage.themes =>
                            _bootCoordinatorThemeScreen(),
                          _BootCoordinatorBootStage.preparing =>
                            _bootCoordinatorPreparingScreen(),
                          _BootCoordinatorBootStage.home =>
                            const SizedBox.shrink(),
                        },
                      ),
                    ],
                  ),
                ),
        );
      },
    );
  }

  Widget _bootCoordinatorShell({
    required String eyebrow,
    required String title,
    required String subtitle,
    required Widget child,
    Widget? footer,
  }) {
    final scheme = _bootCoordinatorThemeData.colorScheme;
    return Center(
      key: ValueKey<String>('boot-${_bootCoordinatorStage.name}'),
      child: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 980),
          child: Container(
            padding: const EdgeInsets.all(26),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(32),
              color: scheme.surface.withValues(alpha: 0.90),
              border: Border.all(color: scheme.primary.withValues(alpha: 0.22)),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: <Widget>[
                Text(
                  eyebrow.toUpperCase(),
                  style: TextStyle(
                    color: scheme.primary,
                    fontSize: 12,
                    letterSpacing: 2.1,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 10),
                Text(
                  title,
                  style: _bootCoordinatorThemeData.textTheme.headlineMedium
                      ?.copyWith(
                        fontWeight: FontWeight.w900,
                        color: scheme.onSurface,
                      ),
                ),
                const SizedBox(height: 8),
                Text(
                  subtitle,
                  style: TextStyle(
                    color: scheme.onSurfaceVariant,
                    height: 1.45,
                  ),
                ),
                const SizedBox(height: 24),
                child,
                if (_bootCoordinatorError != null) ...<Widget>[
                  const SizedBox(height: 18),
                  _bootCoordinatorMessageCard(
                    Icons.error_outline_rounded,
                    _bootCoordinatorError!,
                    scheme.error,
                  ),
                ],
                if (footer != null) ...<Widget>[
                  const SizedBox(height: 22),
                  footer,
                ],
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _bootCoordinatorLoadingScreen() => _bootCoordinatorShell(
    eyebrow: 'Naza One',
    title: 'Private AI, preparing locally',
    subtitle: _bootCoordinatorStatus,
    child: ValueListenableBuilder<NazaModelStoreStatus>(
      valueListenable: NazaSecureModelStore.status,
      builder: (_, modelStatus, _) {
        final measuredProgress = modelStatus.busy && modelStatus.progress > 0;
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: <Widget>[
            NazaProgressBar(
              value: modelStatus.installed
                  ? 1
                  : measuredProgress
                  ? modelStatus.progress.clamp(0, 100) / 100
                  : modelStatus.busy
                  ? null
                  : 0,
            ),
            if (modelStatus.busy) ...<Widget>[
              const SizedBox(height: 10),
              Text(
                modelStatus.phase,
                style: TextStyle(
                  color: _bootCoordinatorThemeData.colorScheme.onSurfaceVariant,
                  fontSize: 12,
                ),
              ),
            ],
          ],
        );
      },
    ),
  );

  Widget _bootCoordinatorSecurityScreen() {
    if (_bootCoordinatorExistingPasswordVault) {
      return _bootCoordinatorShell(
        eyebrow: '1 · Security',
        title: 'Unlock your encrypted vault',
        subtitle: 'This vault was configured to require a password at startup.',
        child: Column(
          children: <Widget>[
            TextField(
              controller: _bootCoordinatorUnlockPassword,
              obscureText: true,
              enabled: !_bootCoordinatorBusy,
              onSubmitted: (_) => unawaited(_bootCoordinatorUnlockVault()),
              decoration: const InputDecoration(
                labelText: 'Vault password',
                prefixIcon: Icon(Icons.password_rounded),
              ),
            ),
            const SizedBox(height: 14),
            Align(
              alignment: Alignment.centerRight,
              child: FilledButton.icon(
                onPressed: _bootCoordinatorBusy
                    ? null
                    : _bootCoordinatorUnlockVault,
                icon: const Icon(Icons.lock_open_rounded),
                label: const Text('Unlock'),
              ),
            ),
          ],
        ),
      );
    }

    return _bootCoordinatorShell(
      eyebrow: '1 · Security',
      title: 'Encrypted from the first launch',
      subtitle: Platform.isLinux
          ? 'Your vault is always encrypted. Linux uses a startup password because this session has no unlocked desktop keyring.'
          : 'Your vault is always encrypted. For the smoothest experience, Naza One defaults to a protected device unlock key. A startup password is optional.',
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          _bootCoordinatorMessageCard(
            Icons.shield_outlined,
            _bootCoordinatorRequirePassword
                ? 'Password mode: Argon2id derives the key-encryption key. You will enter this password on future app starts.'
                : 'Default mode: a random unlock secret is stored in the operating system secure credential store. Your SQLite records remain AES-256-GCM encrypted.',
            _bootCoordinatorThemeData.colorScheme.primary,
          ),
          const SizedBox(height: 16),
          Material(
            type: MaterialType.transparency,
            child: CheckboxListTile(
              value: _bootCoordinatorRequirePassword,
              contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading,
              title: const Text(
                'Require a password every time Naza One starts',
                style: TextStyle(fontWeight: FontWeight.w800),
              ),
              subtitle: Text(
                Platform.isLinux
                    ? 'Linux requires a startup password when no desktop keyring is available.'
                    : 'Opt in for a stronger interactive startup gate. Leave unchecked for secure-storage unlock with no password prompt.',
              ),
              onChanged: _bootCoordinatorBusy || Platform.isLinux
