  Widget _bootCoordinatorModelScreen() {
    final snapshot = _bootCoordinatorDownload;
    final verifying = snapshot?.stage == NazaDownloadStage.verifying;
    final complete = snapshot?.stage == NazaDownloadStage.complete;
    final measuredDownload =
        snapshot != null &&
        (snapshot.stage == NazaDownloadStage.allocating ||
            snapshot.stage == NazaDownloadStage.downloading) &&
        snapshot.receivedBytes > 0;
    final double? progressValue = _bootCoordinatorAllModelsReady
        ? 1
        : complete
        ? 1
        : verifying
        ? null
        : measuredDownload
        ? snapshot.fraction
        : _bootCoordinatorBusy
        ? null
        : 0;
    final scheme = _bootCoordinatorThemeData.colorScheme;
    return _bootCoordinatorShell(
      eyebrow: '2 · Local AI model',
      title: 'Verified multi-source model setup',
      subtitle:
          'Naza installs Gemma for Chat plus a separate scanner-only Llama safety sentinel. Both use resumable 4 MiB chunks from approved HTTPS hosts and exact part/final SHA-256 verification.',
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Container(
            padding: const EdgeInsets.all(18),
            decoration: BoxDecoration(
              color: scheme.surfaceContainerHighest.withValues(alpha: 0.52),
              borderRadius: BorderRadius.circular(22),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: <Widget>[
                Row(
                  children: <Widget>[
                    Icon(
                      _bootCoordinatorAllModelsReady
                          ? Icons.verified_rounded
                          : Icons.hub_rounded,
                      color: scheme.primary,
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Text(
                        _bootCoordinatorStatus,
                        style: const TextStyle(fontWeight: FontWeight.w800),
                      ),
                    ),
                    if (snapshot != null &&
                        !verifying &&
                        (complete || measuredDownload))
                      Text(
                        '${snapshot.percent}%',
                        style: TextStyle(
                          color: scheme.primary,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                  ],
                ),
                const SizedBox(height: 14),
                ClipRRect(
                  borderRadius: BorderRadius.circular(100),
                  child: NazaProgressBar(value: progressValue),
                ),
                const SizedBox(height: 10),
                if (snapshot != null)
                  Wrap(
                    spacing: 14,
                    runSpacing: 7,
                    children: <Widget>[
                      _bootCoordinatorMetric(
                        'Received',
                        _bootCoordinatorFormatBytes(snapshot.receivedBytes),
                      ),
                      _bootCoordinatorMetric(
                        'Total',
                        _bootCoordinatorFormatBytes(snapshot.totalBytes),
                      ),
                      _bootCoordinatorMetric(
                        'Streams',
                        '${snapshot.activeTransfers}',
                      ),
                      _bootCoordinatorMetric(
                        'Chunks',
                        '${snapshot.completedChunks}/${snapshot.totalChunks}',
                      ),
                      _bootCoordinatorMetric(
                        'Speed',
                        '${_bootCoordinatorFormatBytes(snapshot.bytesPerSecond.round())}/s',
                      ),
                      _bootCoordinatorMetric(
                        'Fastest',
                        snapshot.fastestProvider ?? 'probing',
                      ),
                    ],
                  ),
                const SizedBox(height: 16),
                Wrap(
                  spacing: 10,
                  runSpacing: 10,
                  children: <Widget>[
                    if (!_bootCoordinatorAllModelsReady &&
                        !_bootCoordinatorBusy)
                      FilledButton.icon(
                        onPressed: _bootCoordinatorModelReady
                            ? _bootCoordinatorStartDownload
                            : _bootCoordinatorUseLocalModel
                            ? _bootCoordinatorChooseLocalModel
                            : _bootCoordinatorStartDownload,
                        icon: Icon(
                          _bootCoordinatorModelReady
                              ? Icons.security_rounded
                              : _bootCoordinatorUseLocalModel
                              ? Icons.folder_open_rounded
                              : Icons.download_rounded,
                        ),
                        label: Text(
                          _bootCoordinatorModelReady
                              ? 'Download safety sentinel'
                              : _bootCoordinatorUseLocalModel
                              ? 'Select & verify model'
                              : 'Download both verified models',
                        ),
                      ),
                    if (_bootCoordinatorBusy &&
                        _bootCoordinatorTransferControl != null &&
                        !_bootCoordinatorDownloadPaused)
                      OutlinedButton.icon(
                        onPressed: _bootCoordinatorPauseDownload,
                        icon: const Icon(Icons.pause_rounded),
                        label: const Text('Pause'),
                      ),
                    if (_bootCoordinatorBusy &&
                        _bootCoordinatorTransferControl != null &&
