  Widget _bootCoordinatorMessageCard(IconData icon, String text, Color color) =>
      Container(
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(18),
          color: color.withValues(alpha: 0.08),
          border: Border.all(color: color.withValues(alpha: 0.20)),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: <Widget>[
            Icon(icon, color: color, size: 20),
            const SizedBox(width: 10),
            Expanded(child: Text(text, style: const TextStyle(height: 1.4))),
          ],
        ),
      );

  Widget _bootCoordinatorMetric(String label, String value) => Chip(
    avatar: const Icon(Icons.bolt_rounded, size: 15),
    label: Text('$label · $value'),
  );

  Widget _bootCoordinatorThemeDot(Color color) => Container(
    width: 15,
    height: 15,
    decoration: BoxDecoration(color: color, shape: BoxShape.circle),
  );

  static String _bootCoordinatorFormatBytes(int bytes) {
    const units = <String>['B', 'KiB', 'MiB', 'GiB'];
    var value = bytes.toDouble();
    var unit = 0;
    while (value >= 1024 && unit < units.length - 1) {
      value /= 1024;
      unit++;
    }
    return '${value.toStringAsFixed(unit >= 2 ? 1 : 0)} ${units[unit]}';
  }
}

