final class NazaBootTheme {
  const NazaBootTheme({
    required this.id,
    required this.label,
    required this.description,
    required this.seed,
    required this.accent,
    required this.brightness,
  });

  final String id;
  final String label;
  final String description;
  final Color seed;
  final Color accent;
  final Brightness brightness;

  ThemeData build() {
    final generatedScheme = ColorScheme.fromSeed(
      seedColor: seed,
      brightness: brightness,
    );
    // Keep Material widgets on the same two-color contract as the custom
    // shell. ColorScheme.fromSeed derives a complementary secondary color,
    // which made a green theme grow orange controls in otherwise green pages.
    final scheme = generatedScheme.copyWith(
      primary: accent,
      onPrimary: _bootThemeCatalogBestOn(accent),
      secondary: seed,
      onSecondary: _bootThemeCatalogBestOn(seed),
      tertiary: accent,
      onTertiary: _bootThemeCatalogBestOn(accent),
      outline: seed.withValues(
        alpha: brightness == Brightness.dark ? 0.55 : 0.65,
      ),
      outlineVariant: seed.withValues(
        alpha: brightness == Brightness.dark ? 0.28 : 0.35,
      ),
    );
    final dark = brightness == Brightness.dark;
    return ThemeData(
      useMaterial3: true,
      brightness: brightness,
      colorScheme: scheme,
      // InkSparkle/InkRipple compile a fragment shader on the first tap on
      // some desktop GPU drivers. Boot buttons should be visually immediate
      // and must not introduce a one-frame shader hitch.
      splashFactory: NoSplash.splashFactory,
      splashColor: Colors.transparent,
      highlightColor: Colors.transparent,
      hoverColor: Colors.transparent,
      focusColor: Colors.transparent,
      fontFamily: 'Inter',
      scaffoldBackgroundColor: dark
          ? Color.alphaBlend(
              seed.withValues(alpha: 0.055),
              const Color(0xFF030706),
            )
          : Color.alphaBlend(
              seed.withValues(alpha: 0.035),
              const Color(0xFFFFFBFE),
            ),
      cardTheme: CardThemeData(
        elevation: 0,
        color: scheme.surface.withValues(alpha: dark ? 0.92 : 0.96),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(24),
          side: BorderSide(color: scheme.primary.withValues(alpha: 0.18)),
        ),
      ),
      filledButtonTheme: FilledButtonThemeData(
        style: FilledButton.styleFrom(
          minimumSize: const Size(0, 48),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(17),
          ),
          textStyle: const TextStyle(fontWeight: FontWeight.w800),
        ),
      ),
      outlinedButtonTheme: OutlinedButtonThemeData(
        style: OutlinedButton.styleFrom(
          minimumSize: const Size(0, 48),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(17),
          ),
        ),
      ),
      inputDecorationTheme: InputDecorationTheme(
        filled: true,
        fillColor: scheme.surfaceContainerHighest.withValues(
          alpha: dark ? 0.52 : 0.68,
        ),
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(18),
          borderSide: BorderSide(color: scheme.outlineVariant),
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(18),
          borderSide: BorderSide(color: scheme.outlineVariant),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(18),
          borderSide: BorderSide(color: scheme.primary, width: 1.5),
        ),
      ),
      progressIndicatorTheme: ProgressIndicatorThemeData(color: scheme.primary),
    );
  }

  static Color _bootThemeCatalogBestOn(Color color) =>
      ThemeData.estimateBrightnessForColor(color) == Brightness.dark
      ? Colors.white
      : const Color(0xFF111111);
}

