enum NazaOnboardingModelPhase {
  checking,
  missing,
  downloading,
  verifying,
  ready,
  failed,
}

final class NazaOnboardingModelState {
  const NazaOnboardingModelState({
    required this.phase,
    this.progress,
    this.message = '',
    this.localPath,
    this.bytesReceived,
    this.totalBytes,
  });

  final NazaOnboardingModelPhase phase;
  final double? progress;
  final String message;
  final String? localPath;
  final int? bytesReceived;
  final int? totalBytes;

  bool get ready => phase == NazaOnboardingModelPhase.ready;
  bool get busy =>
      phase == NazaOnboardingModelPhase.checking ||
      phase == NazaOnboardingModelPhase.downloading ||
      phase == NazaOnboardingModelPhase.verifying;
}

typedef NazaEnsureModel = Future<void> Function();
typedef NazaChooseLocalModel = Future<void> Function();

/// First-run model acquisition + compact guide. The caller owns persistence of
/// the completed flag so this gate is shown once and future launches go Chat.
final class NazaFirstRunOnboarding extends StatefulWidget {
  const NazaFirstRunOnboarding({
    super.key,
    required this.modelState,
    required this.ensureModel,
    required this.onComplete,
    this.chooseLocalModel,
    this.autoStartDownload = true,
    this.modelName = 'Gemma 4 E2B',
  });

  final ValueListenable<NazaOnboardingModelState> modelState;
  final NazaEnsureModel ensureModel;
  final NazaChooseLocalModel? chooseLocalModel;
  final FutureOr<void> Function() onComplete;
  final bool autoStartDownload;
  final String modelName;

  @override
  State<NazaFirstRunOnboarding> createState() =>
      _FirstRunOnboardingNazaFirstRunOnboardingState();
}

final class _FirstRunOnboardingNazaFirstRunOnboardingState
    extends State<NazaFirstRunOnboarding> {
  bool _firstRunOnboardingAutoAttempted = false;
  bool _firstRunOnboardingShowHelp = false;
  bool _firstRunOnboardingBusy = false;

  @override
  void initState() {
    super.initState();
    widget.modelState.addListener(_firstRunOnboardingModelChanged);
    WidgetsBinding.instance.addPostFrameCallback(
      (_) => _firstRunOnboardingMaybeAutoStart(),
    );
  }

  @override
  void didUpdateWidget(covariant NazaFirstRunOnboarding oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!identical(oldWidget.modelState, widget.modelState)) {
      oldWidget.modelState.removeListener(_firstRunOnboardingModelChanged);
      widget.modelState.addListener(_firstRunOnboardingModelChanged);
    }
  }

  @override
  void dispose() {
    widget.modelState.removeListener(_firstRunOnboardingModelChanged);
    super.dispose();
  }

  void _firstRunOnboardingModelChanged() {
    if (!mounted) return;
    if (widget.modelState.value.ready && !_firstRunOnboardingShowHelp) {
      setState(() => _firstRunOnboardingShowHelp = true);
    }
  }

  void _firstRunOnboardingMaybeAutoStart() {
    if (!mounted ||
        _firstRunOnboardingAutoAttempted ||
        !widget.autoStartDownload)
      return;
    final state = widget.modelState.value;
    if (state.ready) {
      setState(() => _firstRunOnboardingShowHelp = true);
      return;
    }
    if (state.phase == NazaOnboardingModelPhase.missing ||
        state.phase == NazaOnboardingModelPhase.failed) {
      _firstRunOnboardingAutoAttempted = true;
      unawaited(_firstRunOnboardingEnsure());
    }
  }

  Future<void> _firstRunOnboardingEnsure() async {
    if (_firstRunOnboardingBusy) return;
    setState(() => _firstRunOnboardingBusy = true);
    try {
      await widget.ensureModel();
      if (mounted && widget.modelState.value.ready) {
        setState(() => _firstRunOnboardingShowHelp = true);
      }
    } finally {
      if (mounted) setState(() => _firstRunOnboardingBusy = false);
    }
  }

  Future<void> _firstRunOnboardingChooseLocal() async {
    final choose = widget.chooseLocalModel;
    if (_firstRunOnboardingBusy || choose == null) return;
    setState(() => _firstRunOnboardingBusy = true);
    try {
      await choose();
      if (mounted && widget.modelState.value.ready) {
        setState(() => _firstRunOnboardingShowHelp = true);
      }
    } finally {
      if (mounted) setState(() => _firstRunOnboardingBusy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<NazaOnboardingModelState>(
      valueListenable: widget.modelState,
      builder: (context, state, _) => Center(
        child: SingleChildScrollView(
          padding: const EdgeInsets.all(20),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 720),
            child: AnimatedSwitcher(
              duration: const Duration(milliseconds: 280),
              child: _firstRunOnboardingShowHelp && state.ready
                  ? _FirstRunOnboardingHelpCard(
                      key: const ValueKey<String>('help'),
                      modelName: widget.modelName,
                      onComplete: widget.onComplete,
                    )
                  : _FirstRunOnboardingModelSetupCard(
                      key: const ValueKey<String>('model'),
                      modelName: widget.modelName,
                      state: state,
                      actionBusy: _firstRunOnboardingBusy,
                      onEnsure: _firstRunOnboardingEnsure,
                      onChooseLocal: widget.chooseLocalModel == null
                          ? null
                          : _firstRunOnboardingChooseLocal,
                    ),
            ),
          ),
        ),
      ),
    );
  }
}

final class _FirstRunOnboardingModelSetupCard extends StatelessWidget {
  const _FirstRunOnboardingModelSetupCard({
    super.key,
    required this.modelName,
    required this.state,
    required this.actionBusy,
    required this.onEnsure,
    this.onChooseLocal,
  });

  final String modelName;
  final NazaOnboardingModelState state;
  final bool actionBusy;
  final Future<void> Function() onEnsure;
  final Future<void> Function()? onChooseLocal;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final progress = _firstRunOnboardingProgress(state);
    return Container(
      padding: const EdgeInsets.all(24),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(28),
        border: Border.all(color: scheme.primary.withValues(alpha: 0.25)),
        color: Color.alphaBlend(
          scheme.primary.withValues(alpha: 0.06),
          scheme.surface,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Row(
            children: <Widget>[
              _FirstRunOnboardingStatusOrb(ready: state.ready),
              const SizedBox(width: 14),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    Text(
                      'Private model setup',
                      style: Theme.of(context).textTheme.headlineSmall
                          ?.copyWith(fontWeight: FontWeight.w800),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      '$modelName runs locally after its integrity check passes.',
                      style: TextStyle(color: scheme.onSurfaceVariant),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 22),
          _FirstRunOnboardingStatusLine(state: state),
          if (progress != null) ...<Widget>[
            const SizedBox(height: 13),
            ClipRRect(
              borderRadius: BorderRadius.circular(100),
              child: NazaProgressBar(value: progress, minHeight: 8),
            ),
            const SizedBox(height: 7),
            Text(
              _firstRunOnboardingProgressLabel(state),
              style: Theme.of(context).textTheme.bodySmall,
            ),
          ],
          const SizedBox(height: 18),
          DecoratedBox(
            decoration: BoxDecoration(
              color: scheme.surfaceContainerHighest.withValues(alpha: 0.48),
              borderRadius: BorderRadius.circular(17),
            ),
            child: const Padding(
              padding: EdgeInsets.all(14),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Icon(Icons.verified_user_outlined, size: 19),
                  SizedBox(width: 10),
                  Expanded(
                    child: Text(
                      'NAZA verifies the model before inference. Partial or mismatched model data is never marked trusted.',
                    ),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 18),
          Wrap(
            spacing: 10,
            runSpacing: 10,
            children: <Widget>[
              FilledButton.icon(
                onPressed: state.busy || actionBusy ? null : onEnsure,
                icon: Icon(
                  state.phase == NazaOnboardingModelPhase.failed
                      ? Icons.refresh_rounded
                      : Icons.download_rounded,
                ),
                label: Text(
                  state.phase == NazaOnboardingModelPhase.failed
                      ? 'Retry secure setup'
                      : state.ready
                      ? 'Continue'
                      : 'Download & verify',
                ),
              ),
              if (onChooseLocal != null)
                OutlinedButton.icon(
                  onPressed: state.busy || actionBusy ? null : onChooseLocal,
                  icon: const Icon(Icons.folder_open_rounded),
                  label: const Text('Use local model'),
                ),
            ],
          ),
        ],
      ),
    );
  }

  static double? _firstRunOnboardingProgress(NazaOnboardingModelState state) {
    if (state.progress case final p?) return p.clamp(0.0, 1.0);
    final received = state.bytesReceived;
    final total = state.totalBytes;
    if (received == null || total == null || total <= 0) return null;
    return (received / total).clamp(0.0, 1.0);
  }

  static String _firstRunOnboardingProgressLabel(
    NazaOnboardingModelState state,
  ) {
    final progress = _firstRunOnboardingProgress(state);
    if (progress == null) return 'Preparing…';
    final percent = (progress * 100).toStringAsFixed(progress < 0.1 ? 1 : 0);
    if (state.bytesReceived != null && state.totalBytes != null) {
      return '$percent% · ${_firstRunOnboardingBytes(state.bytesReceived!)} / ${_firstRunOnboardingBytes(state.totalBytes!)}';
    }
    return '$percent%';
  }

  static String _firstRunOnboardingBytes(int bytes) {
    const units = <String>['B', 'KB', 'MB', 'GB'];
    var value = bytes.toDouble();
    var unit = 0;
    while (value >= 1024 && unit < units.length - 1) {
      value /= 1024;
      unit++;
    }
    return '${value.toStringAsFixed(unit >= 2 ? 1 : 0)} ${units[unit]}';
  }
}

