/// Shared responsive chrome for Naza scanners.
///
/// Compact/mobile layouts put Start/Stop in the top-right and stack scanner
/// stages vertically. Wide desktop layouts use a continuous two-pane surface
/// so evidence/input can remain visible while results update beside it.
final class NazaScannerSurface extends StatelessWidget {
  final String title;
  final String subtitle;
  final IconData icon;
  final bool started;
  final bool busy;
  final VoidCallback? onStart;
  final VoidCallback? onStop;
  final Widget primary;
  final Widget secondary;
  final Widget? tray;
  final double wideBreakpoint;

  const NazaScannerSurface({
    super.key,
    required this.title,
    required this.subtitle,
    required this.icon,
    required this.started,
    required this.busy,
    required this.onStart,
    required this.onStop,
    required this.primary,
    required this.secondary,
    this.tray,
    this.wideBreakpoint = 900,
  });

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final wide = constraints.maxWidth >= wideBreakpoint;
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: <Widget>[
            _ScannerSurfaceScannerHeader(
              title: title,
              subtitle: subtitle,
              icon: icon,
              started: started,
              busy: busy,
              onStart: onStart,
              onStop: onStop,
            ),
            const SizedBox(height: 12),
            Expanded(
              child: wide
                  ? _ScannerSurfaceWideScannerFlow(
                      primary: primary,
                      secondary: secondary,
                    )
                  : _ScannerSurfaceCompactScannerFlow(
                      primary: primary,
                      secondary: secondary,
                    ),
            ),
            if (tray != null) ...<Widget>[
              const SizedBox(height: 10),
              NazaScannerTray(child: tray!),
            ],
          ],
        );
      },
    );
  }
}

final class _ScannerSurfaceScannerHeader extends StatelessWidget {
  final String title;
  final String subtitle;
  final IconData icon;
  final bool started;
  final bool busy;
  final VoidCallback? onStart;
  final VoidCallback? onStop;

  const _ScannerSurfaceScannerHeader({
    required this.title,
    required this.subtitle,
    required this.icon,
    required this.started,
    required this.busy,
    required this.onStart,
    required this.onStop,
  });

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    return Material(
      color: scheme.surface,
      borderRadius: BorderRadius.circular(22),
      clipBehavior: Clip.antiAlias,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(14, 12, 12, 12),
        child: Row(
          children: <Widget>[
            Container(
              width: 46,
              height: 46,
              decoration: BoxDecoration(
                color: scheme.primary.withAlpha(28),
                borderRadius: BorderRadius.circular(16),
              ),
              alignment: Alignment.center,
              child: Icon(icon, color: scheme.primary),
            ),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Text(
                    title,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: Theme.of(context).textTheme.titleMedium?.copyWith(
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  const SizedBox(height: 2),
                  Text(
                    subtitle,
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: Theme.of(context).textTheme.bodySmall,
                  ),
                ],
              ),
            ),
            const SizedBox(width: 10),
            if (!started)
              FilledButton.icon(
                onPressed: onStart,
                icon: const Icon(Icons.play_arrow_rounded),
                label: const Text('Start'),
              )
            else if (busy)
              FilledButton.tonalIcon(
                onPressed: onStop,
                icon: const Icon(Icons.stop_rounded),
                label: const Text('Stop'),
              )
            else
              const _ScannerSurfaceReadyPill(),
          ],
        ),
      ),
    );
  }
}

final class _ScannerSurfaceReadyPill extends StatelessWidget {
  const _ScannerSurfaceReadyPill();

  @override
  Widget build(BuildContext context) {
    final color = Theme.of(context).colorScheme.primary;
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
      decoration: BoxDecoration(
        color: color.withAlpha(24),
        borderRadius: BorderRadius.circular(999),
        border: Border.all(color: color.withAlpha(90)),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: <Widget>[
          Icon(Icons.circle, size: 8, color: color),
          const SizedBox(width: 6),
          const Text('Ready', style: TextStyle(fontWeight: FontWeight.w800)),
        ],
      ),
    );
  }
}

final class _ScannerSurfaceWideScannerFlow extends StatelessWidget {
  final Widget primary;
  final Widget secondary;

  const _ScannerSurfaceWideScannerFlow({
    required this.primary,
    required this.secondary,
  });

  @override
  Widget build(BuildContext context) => Row(
    crossAxisAlignment: CrossAxisAlignment.stretch,
    children: <Widget>[
      Expanded(
        flex: 11,
        child: _ScannerSurfaceScannerPane(
          label: 'Evidence & controls',
          icon: Icons.tune_rounded,
          child: primary,
        ),
      ),
      const SizedBox(width: 12),
      Expanded(
        flex: 13,
        child: _ScannerSurfaceScannerPane(
          label: 'Live result',
          icon: Icons.analytics_outlined,
          child: secondary,
        ),
      ),
    ],
  );
}

final class _ScannerSurfaceCompactScannerFlow extends StatelessWidget {
  final Widget primary;
  final Widget secondary;

  const _ScannerSurfaceCompactScannerFlow({
    required this.primary,
    required this.secondary,
  });

  @override
  Widget build(BuildContext context) => ListView(
    keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
    children: <Widget>[
      _ScannerSurfaceScannerPane(
        label: 'Evidence & controls',
        icon: Icons.tune_rounded,
        child: primary,
      ),
      const SizedBox(height: 12),
      _ScannerSurfaceScannerPane(
        label: 'Result',
        icon: Icons.analytics_outlined,
        child: secondary,
      ),
    ],
  );
}

final class _ScannerSurfaceScannerPane extends StatelessWidget {
  final String label;
  final IconData icon;
  final Widget child;

  const _ScannerSurfaceScannerPane({
    required this.label,
    required this.icon,
    required this.child,
  });

