final class AionAuthorizationIntent {
  AionAuthorizationIntent({
    required this.purpose,
    required Uint8List eventNonce,
    required Uint8List verifierNonce,
    required this.issuedAt,
    required this.expiresAt,
    required this.expectedAionEpoch,
    required this.expectedMslCounter,
    required this.mslDeviceId,
    required this.mslProfileId,
    required Uint8List postQuantumContextDigest,
    required Uint8List targetDigest,
  }) : eventNonce = Uint8List.fromList(eventNonce),
       verifierNonce = Uint8List.fromList(verifierNonce),
       postQuantumContextDigest = Uint8List.fromList(postQuantumContextDigest),
       targetDigest = Uint8List.fromList(targetDigest) {
    final lifetime = expiresAt.toUtc().difference(issuedAt.toUtc());
    if (!_aionAuthorizationEventSafeId(purpose) ||
        !_aionAuthorizationEventSafeId(mslDeviceId) ||
        !_aionAuthorizationEventSafeId(mslProfileId) ||
        eventNonce.length != 32 ||
        verifierNonce.length != 32 ||
        postQuantumContextDigest.length != 32 ||
        targetDigest.length != 32 ||
        expectedAionEpoch < 1 ||
        expectedMslCounter < 1 ||
        lifetime <= Duration.zero ||
        lifetime > const Duration(minutes: 5)) {
      throw ArgumentError('Invalid AION authorization intent.');
    }
    commitment = _aionAuthorizationEventHash(canonicalBytes());
  }

  final String purpose;
  final Uint8List eventNonce;
  final Uint8List verifierNonce;
  final DateTime issuedAt;
  final DateTime expiresAt;
  final int expectedAionEpoch;
  final int expectedMslCounter;
  final String mslDeviceId;
  final String mslProfileId;
  final Uint8List postQuantumContextDigest;
  final Uint8List targetDigest;
  late final Uint8List commitment;

  Uint8List canonicalBytes() => _aionAuthorizationEventJoin([
    utf8.encode('AION-AUTHORIZATION-INTENT/v1'),
    _aionAuthorizationEventField(utf8.encode(purpose)),
    _aionAuthorizationEventField(eventNonce),
    _aionAuthorizationEventField(verifierNonce),
    _aionAuthorizationEventI64(issuedAt.toUtc().microsecondsSinceEpoch),
    _aionAuthorizationEventI64(expiresAt.toUtc().microsecondsSinceEpoch),
    _aionAuthorizationEventU64(expectedAionEpoch),
    _aionAuthorizationEventU64(expectedMslCounter),
    _aionAuthorizationEventField(utf8.encode(mslDeviceId)),
    _aionAuthorizationEventField(utf8.encode(mslProfileId)),
    _aionAuthorizationEventField(postQuantumContextDigest),
    _aionAuthorizationEventField(targetDigest),
  ]);

  void validateAt(DateTime now) {
    final instant = now.toUtc();
    if (instant.isBefore(
          issuedAt.toUtc().subtract(const Duration(seconds: 30)),
        ) ||
        !instant.isBefore(expiresAt.toUtc())) {
      throw StateError('Authorization intent is not currently valid.');
    }
  }
}

bool _aionAuthorizationEventSafeId(String value) =>
    RegExp(r'^[A-Za-z0-9._:/-]{1,64}$').hasMatch(value);
Uint8List _aionAuthorizationEventHash(List<int> value) =>
    Uint8List.fromList(crypto.sha256.convert(value).bytes);
Uint8List _aionAuthorizationEventField(List<int> value) =>
    _aionAuthorizationEventJoin([
      (ByteData(
        4,
      )..setUint32(0, value.length, Endian.big)).buffer.asUint8List(),
      value,
    ]);
Uint8List _aionAuthorizationEventU64(int value) =>
    (ByteData(8)..setUint64(0, value, Endian.big)).buffer.asUint8List();
Uint8List _aionAuthorizationEventI64(int value) =>
    (ByteData(8)..setInt64(0, value, Endian.big)).buffer.asUint8List();
Uint8List _aionAuthorizationEventJoin(Iterable<List<int>> values) {
  final builder = BytesBuilder(copy: false);
  for (final value in values) {
    builder.add(value);
  }
  return builder.takeBytes();
}

