enum AionContributionVisibility { public, confidential }

final class AionContribution {
  AionContribution({
    required this.sourceId,
    required this.round,
    required this.visibility,
    required Uint8List commitment,
    required Uint8List reveal,
    required Uint8List signature,
  }) : commitment = Uint8List.fromList(commitment),
       reveal = Uint8List.fromList(reveal),
       signature = Uint8List.fromList(signature);

  final String sourceId;
  final int round;
  final AionContributionVisibility visibility;
  final Uint8List commitment;
  final Uint8List reveal;
  final Uint8List signature;
}

abstract interface class AionContributionVerifier {
  Future<bool> verify({
    required String sourceId,
    required int round,
    required Uint8List signedMessage,
    required Uint8List signature,
  });
}

abstract interface class AionContributorTrustPolicy {
  String? trustDomainFor({required String sourceId, required int round});
}

final class AionMlDsaContributorIdentity {
  AionMlDsaContributorIdentity({
    required this.sourceId,
    required Uint8List publicKey,
    required this.trustDomain,
    this.parameterSet = DilithiumParameter.mlDsa65,
    this.validFromRound = 1,
    this.validThroughRound = 0x7fffffffffffffff,
  }) : _aionEntropyFederationPublicKey = Uint8List.fromList(publicKey) {
    if (!RegExp(r'^[A-Za-z0-9._:/-]{1,64}$').hasMatch(sourceId) ||
        !RegExp(r'^[A-Za-z0-9._:/-]{1,64}$').hasMatch(trustDomain) ||
        validFromRound < 1 ||
        validThroughRound < validFromRound ||
        publicKey.length != DilithiumParams.get(parameterSet).publicKeyBytes) {
      throw const MslProtocolException(
        'aion_mldsa_identity_invalid',
        'The pinned ML-DSA contributor identity is malformed.',
      );
    }
  }

  final String sourceId;
  final String trustDomain;
  final Uint8List _aionEntropyFederationPublicKey;
  Uint8List get publicKey =>
      Uint8List.fromList(_aionEntropyFederationPublicKey);
  final DilithiumParameter parameterSet;
  final int validFromRound;
  final int validThroughRound;
}

/// A fail-closed FIPS 204 verifier backed by an immutable identity-key map.
/// Verification runs away from the UI isolate. A Dart isolate limits workload
/// interference but is not an operating-system security sandbox.
final class PinnedMlDsaContributorVerifier
    implements AionContributionVerifier, AionContributorTrustPolicy {
  PinnedMlDsaContributorVerifier(
    Iterable<AionMlDsaContributorIdentity> identities,
  ) : _aionEntropyFederationIdentities = Map.unmodifiable({
        for (final identity in identities) identity.sourceId: identity,
      }) {
    if (_aionEntropyFederationIdentities.isEmpty ||
        _aionEntropyFederationIdentities.length != identities.length) {
      throw const MslProtocolException(
        'aion_mldsa_pins_invalid',
        'ML-DSA contributor pins must be non-empty and uniquely named.',
      );
    }
  }

  static final Uint8List _aionEntropyFederationContext = Uint8List.fromList(
    utf8.encode('NAZA-AION-FEDERATION-v1'),
  );
  final Map<String, AionMlDsaContributorIdentity>
  _aionEntropyFederationIdentities;

  static Uint8List get signingContext =>
      Uint8List.fromList(_aionEntropyFederationContext);

  @override
  String? trustDomainFor({required String sourceId, required int round}) {
    final identity = _aionEntropyFederationIdentities[sourceId];
    if (identity == null ||
        round < identity.validFromRound ||
        round > identity.validThroughRound) {
      return null;
    }
    return identity.trustDomain;
  }

  @override
  Future<bool> verify({
    required String sourceId,
    required int round,
    required Uint8List signedMessage,
    required Uint8List signature,
  }) async {
    final identity = _aionEntropyFederationIdentities[sourceId];
    if (identity == null ||
        round < identity.validFromRound ||
        round > identity.validThroughRound ||
        signedMessage.isEmpty ||
        signedMessage.length > 4096 ||
        signature.length !=
            DilithiumParams.get(identity.parameterSet).signatureBytes) {
      return false;
    }
    final request = _AionEntropyFederationMlDsaVerificationRequest(
      publicKey: Uint8List.fromList(identity.publicKey),
      message: Uint8List.fromList(signedMessage),
      signature: Uint8List.fromList(signature),
      parameterSet: identity.parameterSet,
      context: Uint8List.fromList(_aionEntropyFederationContext),
    );
    try {
      return await Isolate.run(
        () => _aionEntropyFederationVerifyMlDsa(request),
      );
    } catch (_) {
      return false;
    }
  }
}

final class _AionEntropyFederationMlDsaVerificationRequest {
  const _AionEntropyFederationMlDsaVerificationRequest({
    required this.publicKey,
    required this.message,
    required this.signature,
    required this.parameterSet,
    required this.context,
  });
  final Uint8List publicKey;
  final Uint8List message;
  final Uint8List signature;
  final DilithiumParameter parameterSet;
  final Uint8List context;
}

bool _aionEntropyFederationVerifyMlDsa(
  _AionEntropyFederationMlDsaVerificationRequest request,
) => MlDsa.verify(
  request.publicKey,
  request.message,
  request.signature,
  DilithiumParams.get(request.parameterSet),
  ctx: request.context,
);

final class AionFederationMix {
  AionFederationMix._({
    required this.round,
    required Uint8List transcriptCommitment,
    required Uint8List confidentialMix,
    required List<String> acceptedSources,
    required List<String> confidentialSources,
    required List<String> confidentialTrustDomains,
  }) : _aionEntropyFederationTranscriptCommitment = Uint8List.fromList(
         transcriptCommitment,
       ),
       _aionEntropyFederationConfidentialMix = Uint8List.fromList(
         confidentialMix,
       ),
       acceptedSources = List.unmodifiable(acceptedSources),
       confidentialSources = List.unmodifiable(confidentialSources),
       confidentialTrustDomains = List.unmodifiable(confidentialTrustDomains);

  final int round;
  final Uint8List _aionEntropyFederationTranscriptCommitment;
  final Uint8List _aionEntropyFederationConfidentialMix;
  final List<String> acceptedSources;
  final List<String> confidentialSources;
  final List<String> confidentialTrustDomains;
  bool _aionEntropyFederationConsumed = false;

  Uint8List get transcriptCommitment =>
      Uint8List.fromList(_aionEntropyFederationTranscriptCommitment);
  Uint8List get confidentialMix =>
      Uint8List.fromList(_aionEntropyFederationConfidentialMix);

  AionFederationBinding consumeForEpoch(int expectedEpoch) {
    if (_aionEntropyFederationConsumed || round != expectedEpoch) {
      throw const MslProtocolException(
        'aion_federation_replay',
        'The federation mix is stale, reused, or bound to another epoch.',
      );
    }
    _aionEntropyFederationConsumed = true;
    return AionFederationBinding._(
      round: round,
      transcriptCommitment: _aionEntropyFederationTranscriptCommitment,
      confidentialMix: _aionEntropyFederationConfidentialMix,
      acceptedSourceCount: acceptedSources.length,
      confidentialSourceCount: confidentialSources.length,
      confidentialTrustDomainCount: confidentialTrustDomains.length,
    );
  }

  // Public beacons improve freshness and auditability, but are predictable to
  // observers and therefore receive no secret-entropy credit.
  int get publicEntropyCreditBits => 0;
}

final class AionFederationBinding {
  AionFederationBinding._({
    required this.round,
    required Uint8List transcriptCommitment,
    required Uint8List confidentialMix,
    required this.acceptedSourceCount,
    required this.confidentialSourceCount,
    required this.confidentialTrustDomainCount,
  }) : transcriptCommitment = Uint8List.fromList(transcriptCommitment),
       confidentialMix = Uint8List.fromList(confidentialMix);

  final int round;
  final Uint8List transcriptCommitment;
  final Uint8List confidentialMix;
  final int acceptedSourceCount;
  final int confidentialSourceCount;
  final int confidentialTrustDomainCount;
}

final class AionEntropyFederation {
  const AionEntropyFederation({
    required this.verifier,
    this.minimumSources = 3,
    this.minimumConfidentialSources = 1,
    this.minimumConfidentialTrustDomains = 1,
  });

  final AionContributionVerifier verifier;
  final int minimumSources;
  final int minimumConfidentialSources;
  final int minimumConfidentialTrustDomains;

  Future<AionFederationMix> combine(
    List<AionContribution> contributions,
  ) async {
    if (minimumSources < 2 ||
        minimumSources > 16 ||
        minimumConfidentialSources < 1 ||
        minimumConfidentialSources > minimumSources ||
        minimumConfidentialTrustDomains < 1 ||
        minimumConfidentialTrustDomains > minimumConfidentialSources ||
        contributions.length < minimumSources ||
        contributions.length > 16) {
      throw const MslProtocolException(
        'aion_federation_quorum',
        'The contribution federation does not satisfy its bounded quorum.',
      );
    }
    final ordered = [...contributions]
      ..sort((left, right) => left.sourceId.compareTo(right.sourceId));
    final round = ordered.first.round;
    final seen = <String>{};
    final confidential = <AionContribution>[];
    final confidentialTrustDomains = <String>{};
    final transcript = BytesBuilder(copy: false)
      ..add(utf8.encode('AION-FEDERATION/transcript/v1'))
      ..add(_aionEntropyFederationU64(round));

    for (final contribution in ordered) {
      if (!RegExp(
            r'^[A-Za-z0-9._:/-]{1,64}$',
          ).hasMatch(contribution.sourceId) ||
          !seen.add(contribution.sourceId) ||
          round <= 0 ||
          contribution.round != round ||
          contribution.commitment.length != 32 ||
          contribution.reveal.length < 32 ||
          contribution.reveal.length > 128 ||
          contribution.signature.length < 64 ||
          !_aionEntropyFederationConstantTimeEqual(
            contribution.commitment,
            commitmentFor(
              sourceId: contribution.sourceId,
              round: round,
              reveal: contribution.reveal,
            ),
          )) {
        throw const MslProtocolException(
          'aion_federation_invalid',
          'A federation contribution is malformed, duplicated, or substituted.',
        );
      }
      final signedMessage = signedMessageFor(contribution);
      if (!await verifier.verify(
        sourceId: contribution.sourceId,
        round: contribution.round,
        signedMessage: signedMessage,
        signature: contribution.signature,
      )) {
        throw const MslProtocolException(
          'aion_federation_signature',
          'A federation contribution signature was rejected.',
        );
      }
      transcript
        ..add(
          _aionEntropyFederationLengthPrefixed(
            utf8.encode(contribution.sourceId),
          ),
        )
        ..add(_aionEntropyFederationU64(contribution.round))
        ..add([contribution.visibility.index])
        ..add(contribution.commitment)
        ..add(_aionEntropyFederationHash(contribution.signature));
      if (contribution.visibility == AionContributionVisibility.confidential) {
        confidential.add(contribution);
        if (verifier is AionContributorTrustPolicy) {
          final policy = verifier as AionContributorTrustPolicy;
          final domain = policy.trustDomainFor(
            sourceId: contribution.sourceId,
            round: contribution.round,
          );
          if (domain == null) {
            throw const MslProtocolException(
              'aion_federation_trust_domain',
              'A confidential contributor has no active trust domain.',
            );
          }
          confidentialTrustDomains.add(domain);
        }
      }
    }
    if (confidential.length < minimumConfidentialSources) {
      throw const MslProtocolException(
        'aion_federation_confidential_quorum',
        'The confidential contribution quorum was not met.',
      );
    }
    if (minimumConfidentialTrustDomains > 1 &&
        confidentialTrustDomains.length < minimumConfidentialTrustDomains) {
      throw const MslProtocolException(
        'aion_federation_trust_domain_quorum',
        'The independent confidential trust-domain quorum was not met.',
      );
    }
    final secretMaterial = BytesBuilder(copy: false)
      ..add(utf8.encode('AION-FEDERATION/confidential/v1'))
      ..add(_aionEntropyFederationU64(round));
    for (final contribution in confidential) {
      secretMaterial
        ..add(
          _aionEntropyFederationLengthPrefixed(
            utf8.encode(contribution.sourceId),
          ),
        )
        ..add(_aionEntropyFederationLengthPrefixed(contribution.reveal));
    }
    return AionFederationMix._(
      round: round,
      transcriptCommitment: _aionEntropyFederationHash(transcript.takeBytes()),
      confidentialMix: _aionEntropyFederationHash(secretMaterial.takeBytes()),
      acceptedSources: List.unmodifiable(
        ordered.map((value) => value.sourceId),
      ),
      confidentialSources: List.unmodifiable(
        confidential.map((value) => value.sourceId),
      ),
      confidentialTrustDomains: List.unmodifiable(
        confidentialTrustDomains.toList()..sort(),
      ),
    );
  }

  static Uint8List commitmentFor({
    required String sourceId,
    required int round,
    required Uint8List reveal,
  }) => _aionEntropyFederationHash([
    ...utf8.encode('AION-FEDERATION/commit/v1'),
    ..._aionEntropyFederationLengthPrefixed(utf8.encode(sourceId)),
    ..._aionEntropyFederationU64(round),
    ..._aionEntropyFederationLengthPrefixed(reveal),
  ]);

  static Uint8List signedMessageFor(AionContribution value) =>
      Uint8List.fromList([
        ...utf8.encode('AION-FEDERATION/sign/v1'),
        ..._aionEntropyFederationLengthPrefixed(utf8.encode(value.sourceId)),
        ..._aionEntropyFederationU64(value.round),
        value.visibility.index,
        ...value.commitment,
      ]);
}

Uint8List _aionEntropyFederationHash(List<int> value) =>
    Uint8List.fromList(crypto.sha256.convert(value).bytes);

Uint8List _aionEntropyFederationLengthPrefixed(List<int> value) =>
    Uint8List.fromList([
      ...(ByteData(
        4,
      )..setUint32(0, value.length, Endian.big)).buffer.asUint8List(),
      ...value,
    ]);

Uint8List _aionEntropyFederationU64(int value) =>
    (ByteData(8)..setUint64(0, value, Endian.big)).buffer.asUint8List();

bool _aionEntropyFederationConstantTimeEqual(List<int> left, List<int> right) {
  var difference = left.length ^ right.length;
  final length = math.min(left.length, right.length);
  for (var index = 0; index < length; index++) {
    difference |= left[index] ^ right[index];
  }
  return difference == 0;
}

// ============================================================================
// SOURCE SECTION: lib/security/aion_virtual_msl.dart
// ============================================================================

// Hardwareless AION-MSL security mode. Simulated chaos receives zero entropy
// credit; security comes from cryptographic roots, fresh CSPRNG output, the
// monotonic store, and (for maximum mode) an authenticated ML-KEM secret.

enum AionProfile { research, local, maximum, federatedMaximum }

final class AionCheckpoint {
  AionCheckpoint({
    this.suiteVersion = AionVirtualMslEngine.suiteVersion,
    required this.epoch,
    required Uint8List ratchet,
    required Uint8List merkleRoot,
  }) : ratchet = Uint8List.fromList(ratchet),
       merkleRoot = Uint8List.fromList(merkleRoot);
  final int epoch;
  final int suiteVersion;
  final Uint8List ratchet;
  final Uint8List merkleRoot;
}

abstract interface class AionCheckpointStore {
  Future<AionCheckpoint?> load(AionProfile profile);
  Future<void> compareAndCommit({
    required AionProfile profile,
    required int expectedEpoch,
    required AionCheckpoint next,
  });
}

final class AionMemoryCheckpointStore implements AionCheckpointStore {
  AionCheckpoint? _aionVirtualMslValue;
  @override
  Future<AionCheckpoint?> load(AionProfile profile) async =>
      _aionVirtualMslValue == null
      ? null
      : AionCheckpoint(
          suiteVersion: _aionVirtualMslValue!.suiteVersion,
          epoch: _aionVirtualMslValue!.epoch,
          ratchet: _aionVirtualMslValue!.ratchet,
          merkleRoot: _aionVirtualMslValue!.merkleRoot,
        );
  @override
  Future<void> compareAndCommit({
    required AionProfile profile,
    required int expectedEpoch,
    required AionCheckpoint next,
  }) async {
    if ((_aionVirtualMslValue?.epoch ?? 0) != expectedEpoch ||
        next.epoch != expectedEpoch + 1 ||
        next.suiteVersion != AionVirtualMslEngine.suiteVersion) {
      throw const MslProtocolException(
        'aion_checkpoint_fork',
        'The AION checkpoint has forked or rolled back.',
      );
    }
    _aionVirtualMslValue = AionCheckpoint(
      suiteVersion: next.suiteVersion,
      epoch: next.epoch,
      ratchet: next.ratchet,
      merkleRoot: next.merkleRoot,
    );
  }
}

final class AionPolicy {
  const AionPolicy({
    required this.profile,
    required this.latticeWidth,
    required this.sequentialRounds,
    required this.challengeDepth,
    required this.handleLifetime,
    this.requiresFederation = false,
  });

  final AionProfile profile;
  final int latticeWidth;
  final int sequentialRounds;
  final int challengeDepth;
  final Duration handleLifetime;
  final bool requiresFederation;

  static const research = AionPolicy(
    profile: AionProfile.research,
    latticeWidth: 256,
    sequentialRounds: 64,
    challengeDepth: 8,
    handleLifetime: Duration(seconds: 30),
  );
  static const local = AionPolicy(
    profile: AionProfile.local,
    latticeWidth: 2048,
    sequentialRounds: 2048,
    challengeDepth: 24,
    handleLifetime: Duration(seconds: 20),
  );
  static const maximum = AionPolicy(
    profile: AionProfile.maximum,
    latticeWidth: 8192,
    sequentialRounds: 8192,
    challengeDepth: 48,
    handleLifetime: Duration(seconds: 10),
  );
  static const federatedMaximum = AionPolicy(
    profile: AionProfile.federatedMaximum,
    latticeWidth: 8192,
    sequentialRounds: 8192,
    challengeDepth: 48,
    handleLifetime: Duration(seconds: 10),
    requiresFederation: true,
  );

  void validate() {
    if (latticeWidth < 256 ||
        latticeWidth > 65536 ||
        sequentialRounds < 1 ||
        sequentialRounds > 1000000 ||
        challengeDepth < 8 ||
        challengeDepth > 256 ||
        handleLifetime <= Duration.zero ||
        handleLifetime > const Duration(minutes: 5)) {
      throw const MslProtocolException(
        'aion_policy_invalid',
        'The AION policy exceeds its bounded security envelope.',
      );
    }
  }
}

final class AionChaosFrame {
  const AionChaosFrame(this.coordinates);
  final List<double> coordinates;

  Uint8List canonicalBytes() {
    if (coordinates.length < 8 ||
        coordinates.length > 4096 ||
        coordinates.any((v) => !v.isFinite || v < -1 || v > 1)) {
      throw const MslProtocolException(
        'aion_chaos_invalid',
        'The simulated chaos frame is malformed.',
      );
    }
    final data = ByteData(4 + coordinates.length * 8)
      ..setUint32(0, coordinates.length, Endian.big);
    for (var i = 0; i < coordinates.length; i++) {
      data.setFloat64(4 + i * 8, coordinates[i], Endian.big);
    }
    return data.buffer.asUint8List();
  }
}

final class AionCapability {
  AionCapability._(
    this.id,
    this.purpose,
    this.epoch,
    this.expiresAt,
    Uint8List eventCommitment,
  ) : eventCommitment = Uint8List.fromList(eventCommitment);
  final String id;
  final String purpose;
  final int epoch;
  final DateTime expiresAt;
  final Uint8List eventCommitment;
}

final class AionProof {
  const AionProof({
    required this.epoch,
    required this.transcriptDigest,
    required this.stateCommitment,
    required this.proof,
    required this.capability,
    required this.entropyCreditBits,
    required this.authorizationEventCommitment,
    required this.physicalReceiptDigest,
  });
  final int epoch;
  final Uint8List transcriptDigest;
  final Uint8List stateCommitment;
  final Uint8List proof;
  final AionCapability capability;
  final int entropyCreditBits;
  final Uint8List authorizationEventCommitment;
  final Uint8List physicalReceiptDigest;
}

typedef AionEntropySource = Uint8List Function(int length);

abstract interface class AionExternalKeySchedule {
  Future<Uint8List> deriveActiveKey({
    required Uint8List transcriptDigest,
    required Uint8List priorRatchet,
    required Uint8List freshEntropy,
    required Uint8List postQuantumSecret,
    required Uint8List federationSecret,
    required Uint8List authorizationEventCommitment,
    required Uint8List physicalReceiptDigest,
  });
}

final class AionVirtualMslEngine {
  static const int suiteVersion = 2;

  AionVirtualMslEngine({
    required this.policy,
    required this.counterStore,
    required this.checkpointStore,
    Uint8List? deviceRoot,
    Uint8List? userRoot,
    this.externalKeySchedule,
    AionEntropySource? entropy,
    DateTime Function()? clock,
  }) : _aionVirtualMslDeviceRoot = Uint8List.fromList(deviceRoot ?? const []),
       _aionVirtualMslUserRoot = userRoot == null
           ? null
           : Uint8List.fromList(userRoot),
       _aionVirtualMslEntropy = entropy ?? _aionVirtualMslSecureEntropy,
       _aionVirtualMslClock = clock ?? DateTime.now {
    policy.validate();
    if (policy.requiresFederation &&
        (externalKeySchedule == null ||
            deviceRoot != null ||
            userRoot != null)) {
      throw const MslProtocolException(
        'aion_external_schedule_required',
        'Federated maximum requires an external key schedule and forbids host-resident roots.',
      );
    }
    if (!policy.requiresFederation &&
        (deviceRoot == null ||
            deviceRoot.length < 32 ||
            deviceRoot.length > 128 ||
            (userRoot != null &&
                (userRoot.length < 32 || userRoot.length > 128)))) {
      throw const MslProtocolException(
        'aion_root_invalid',
        'AION roots must contain at least 256 bits.',
      );
    }
    _aionVirtualMslRatchet = policy.requiresFederation
        ? _aionVirtualMslHmac(
            _aionVirtualMslHash(utf8.encode('AION-MSL/external/genesis/v2')),
            utf8.encode('AION-MSL/ratchet/genesis/v2'),
          )
        : _aionVirtualMslHmac(
            _aionVirtualMslDeviceRoot,
            utf8.encode('AION-MSL/ratchet/genesis/v1'),
          );
    _aionVirtualMslMerkleRoot = _aionVirtualMslHash(
      utf8.encode('AION-MSL/merkle/empty/v1'),
    );
  }

  final AionPolicy policy;
  final MslMonotonicCounterStore counterStore;
  final AionCheckpointStore checkpointStore;
  final AionExternalKeySchedule? externalKeySchedule;
  final Uint8List _aionVirtualMslDeviceRoot;
  final Uint8List? _aionVirtualMslUserRoot;
  final AionEntropySource _aionVirtualMslEntropy;
  final DateTime Function() _aionVirtualMslClock;
  final Map<String, _AionVirtualMslAionStoredCapability>
  _aionVirtualMslCapabilities = {};
  late Uint8List _aionVirtualMslRatchet;
  late Uint8List _aionVirtualMslMerkleRoot;
  int _aionVirtualMslEpoch = 0;
  bool _aionVirtualMslBusy = false;
  bool _aionVirtualMslInitialized = false;
  Uint8List? _aionVirtualMslLastEntropyDigest;

  Future<AionProof> advance({
    required String purpose,
    required Uint8List verifierNonce,
    required Uint8List postQuantumSecret,
    required List<AionChaosFrame> chaosFrames,
    AionFederationMix? federation,
    MslAuthorizationBinding? authorizationBinding,
  }) async {
    if (_aionVirtualMslBusy)
      throw const MslProtocolException(
        'aion_busy',
        'AION is already advancing.',
      );
    if (!RegExp(r'^[A-Za-z0-9._:/-]{1,64}$').hasMatch(purpose) ||
        verifierNonce.length != 32 ||
        chaosFrames.isEmpty ||
        chaosFrames.length > 64) {
      throw const MslProtocolException(
        'aion_request_invalid',
        'The AION request is malformed.',
      );
    }
    if ((policy.profile == AionProfile.maximum ||
            policy.profile == AionProfile.federatedMaximum) &&
        postQuantumSecret.length < 32) {
      throw const MslProtocolException(
        'aion_pq_required',
        'Maximum AION requires an authenticated ML-KEM secret.',
      );
    }
    if (postQuantumSecret.length > 128)
      throw const MslProtocolException(
        'aion_pq_invalid',
        'The PQ contribution is oversized.',
      );
    if (policy.requiresFederation && federation == null) {
      throw const MslProtocolException(
        'aion_federation_required',
        'Federated-maximum AION cannot run without a verified federation.',
      );
    }
    if (policy.requiresFederation && authorizationBinding == null) {
      throw const MslProtocolException(
        'authorization_event_required',
        'Federated maximum requires a physical authorization-event receipt.',
      );
    }
    _aionVirtualMslBusy = true;
    Uint8List? working;
    Uint8List? freshMaterial;
    Uint8List? extractInput;
    Uint8List? pseudorandomKey;
    try {
      final persisted = await counterStore.current(
        deviceId: 'aion-virtual',
        profileId: policy.profile.name,
      );
      final checkpoint = await checkpointStore.load(policy.profile);
      if (!_aionVirtualMslInitialized) {
        if (checkpoint != null) {
          if (checkpoint.suiteVersion != suiteVersion) {
            throw const MslProtocolException(
              'aion_suite_downgrade',
              'The AION checkpoint belongs to an unsupported cryptographic suite.',
            );
          }
          _aionVirtualMslZero(_aionVirtualMslRatchet);
          _aionVirtualMslRatchet = Uint8List.fromList(checkpoint.ratchet);
          _aionVirtualMslMerkleRoot = Uint8List.fromList(checkpoint.merkleRoot);
          _aionVirtualMslEpoch = checkpoint.epoch;
        }
        _aionVirtualMslInitialized = true;
