final class AionSecureDatabaseCheckpointStore implements AionCheckpointStore {
  AionSecureDatabaseCheckpointStore({NazaSecureDatabase? database})
    : _aionVirtualMslStoreDatabase = database ?? NazaSecureDatabase.instance;
  final NazaSecureDatabase _aionVirtualMslStoreDatabase;
  Future<void> _aionVirtualMslStoreTail = Future<void>.value();

  String _aionVirtualMslStoreKey(AionProfile profile) =>
      'checkpoint.v1.${profile.name}';

  @override
