    final raw = await _aionVirtualMslStoreDatabase.readJson(
      'aion-msl',
      _aionVirtualMslStoreKey(profile),
    );
    if (raw == null) return null;
    if (raw is! Map ||
        raw['suite'] != AionVirtualMslEngine.suiteVersion ||
        raw['epoch'] is! int ||
        raw['ratchet'] is! String ||
        raw['merkle'] is! String) {
