      final expected = await _authenticatedRollbackGuardMacFor(epoch);
      if (!_authenticatedRollbackGuardConstantTimeTextEquals(expected, mac)) {
        throw const NazaSecurityException(
          'rollback_state_authentication',
          'Protected rollback state authentication failed.',
        );
