  /// prefix. Callers should pass only credentials already held in trusted
  /// configuration, never values discovered in untrusted content.
  static String redactExactSecrets(String value, Iterable<String> secrets) {
    var clean = value;
    for (final candidate in secrets) {
      final secret = candidate.trim();
      if (secret.length >= 8) {
        clean = clean.replaceAll(secret, '[REDACTED_CONFIGURED_SECRET]');
      }
    }
    return clean;
  }

  static String _boundarySanitizerClean(
    String value, {
    required int maxCharacters,
  }) {
    if (maxCharacters < 1) {
      throw ArgumentError.value(maxCharacters, 'maxCharacters');
    }
    var clean = value
        .replaceAll('\r\n', '\n')
        .replaceAll('\r', '\n')
        .replaceAll(_boundarySanitizerDisallowedControls, '');
    if (clean.length > maxCharacters) {
      clean = clean.substring(0, maxCharacters);
      // Do not leave a dangling UTF-16 high surrogate at the truncation edge.
      if (clean.isNotEmpty) {
        final last = clean.codeUnitAt(clean.length - 1);
        if (last >= 0xD800 && last <= 0xDBFF) {
          clean = clean.substring(0, clean.length - 1);
        }
      }
    }
    return clean;
  }

  static String _boundarySanitizerRedactSecrets(String value) => value
      .replaceAll(_boundarySanitizerPemPrivateKey, '[REDACTED_PRIVATE_KEY]')
      .replaceAll(_boundarySanitizerBearerSecret, 'Bearer [REDACTED]')
      .replaceAllMapped(
        _boundarySanitizerNamedSecret,
        (match) => '${match.group(1)}=[REDACTED]',
      )
      .replaceAll(_boundarySanitizerJwt, '[REDACTED_JWT]')
      .replaceAll(_boundarySanitizerKnownToken, '[REDACTED_TOKEN]');
}

