// LLM-CONTEXT:END

final class NazaHardenedSecurityRuntime {
  NazaHardenedSecurityRuntime({
    required this.vault,
    required this.secureStore,
    required this.guardian,
    required this.appIdentity,
    required this.trustRootIdentity,
  });

  final NazaSecureDatabase vault;
  final NazaDeviceKeyStore secureStore;
  final NazaKeyGuardian guardian;
  final String appIdentity;
  final String trustRootIdentity;

  NazaHardenedVaultController? _hardenedSecurityRuntimeController;
  NazaPersistentForwardAudit? _hardenedSecurityRuntimePersistentAudit;
  NazaKeyHandle? _hardenedSecurityRuntimeCapabilityRoot;
  NazaKeyHandle? _hardenedSecurityRuntimeAuditRoot;
  NazaVerifiedModelIdentity? _hardenedSecurityRuntimeActiveModel;
  Uint8List? _hardenedSecurityRuntimeSessionBinding;

  bool get isReady =>
      _hardenedSecurityRuntimeController?.isReady == true &&
      _hardenedSecurityRuntimePersistentAudit?.initialized == true;

  NazaHardenedVaultController get controller {
    final value = _hardenedSecurityRuntimeController;
    if (value == null || !isReady) {
      throw const NazaSecurityException(
        'runtime_not_ready',
        'Hardened security runtime is not initialized.',
      );
    }
    return value;
  }

  int? get securityEpoch => _hardenedSecurityRuntimeController?.securityEpoch;
  int? get auditSequence => _hardenedSecurityRuntimePersistentAudit?.sequence;
  String? get auditTip => _hardenedSecurityRuntimePersistentAudit?.tip;

  Future<void> create({
    required String password,
    required NazaVerifiedModelIdentity model,
    required NazaPostQuantumRecoveryState recovery,
    NazaPqTrustPolicy? trustPolicy,
    bool passwordRequired = true,
    Map<NazaVaultRecordKey, Object?> initialRecords = const {},
  }) async {
    await model.reverifyArtifacts();
    final identities = await const NazaSecurityIdentityDeriver().derive(
      model: model,
      recovery: recovery,
      trustPolicy: trustPolicy ?? NazaPqTrustPolicy.maximum(),
    );
    final hardened = _hardenedSecurityRuntimeNewController(identities);
    await hardened.create(
      password: password,
      passwordRequired: passwordRequired,
      initialRecords: initialRecords,
    );
    try {
      _hardenedSecurityRuntimeActiveModel = model;
      _hardenedSecurityRuntimeController = hardened;
      await _hardenedSecurityRuntimeInitializeRuntimeSecurity(identities);
      await _hardenedSecurityRuntimeAppendPersistent(
        'runtime-created',
        <String, Object?>{
          'modelIdentity': identities.modelIdentity,
          'recoveryIdentity': identities.recoveryIdentity,
          'trustPolicyIdentity': identities.trustPolicyIdentity,
        },
      );
    } catch (_) {
      await hardened.lock();
      _hardenedSecurityRuntimeDestroySessionState();
      rethrow;
    }
  }

  Future<void> unlock({
    required String password,
    required NazaVerifiedModelIdentity model,
    required NazaPostQuantumRecoveryState recovery,
    NazaPqTrustPolicy? trustPolicy,
  }) async {
    await model.reverifyArtifacts();
    final identities = await const NazaSecurityIdentityDeriver().derive(
      model: model,
      recovery: recovery,
      trustPolicy: trustPolicy ?? NazaPqTrustPolicy.maximum(),
    );
    final hardened = _hardenedSecurityRuntimeNewController(identities);
    await hardened.unlock(password);
    try {
      _hardenedSecurityRuntimeActiveModel = model;
      _hardenedSecurityRuntimeController = hardened;
      await _hardenedSecurityRuntimeInitializeRuntimeSecurity(identities);
      await _hardenedSecurityRuntimeAppendPersistent(
        'runtime-unlocked',
        <String, Object?>{
          'method': 'password',
          'modelIdentity': identities.modelIdentity,
          'recoveryIdentity': identities.recoveryIdentity,
        },
      );
    } catch (_) {
      await hardened.lock();
      _hardenedSecurityRuntimeDestroySessionState();
      rethrow;
    }
  }

  Future<void> lock() async {
    // Locking is a safety operation: audit durability must never keep the
    // vault open. Capture the controller, tear down session state, and lock
    // the encrypted store even when best-effort audit append fails.
    Object? auditFailure;
    try {
      if (isReady) {
        await _hardenedSecurityRuntimeAppendPersistent(
          'runtime-locking',
          const <String, Object?>{},
        );
      }
    } catch (error) {
      auditFailure = error;
    } finally {
      _hardenedSecurityRuntimePersistentAudit?.destroy();
      _hardenedSecurityRuntimePersistentAudit = null;
      _hardenedSecurityRuntimeActiveModel = null;
      _hardenedSecurityRuntimeZero(_hardenedSecurityRuntimeSessionBinding);
      _hardenedSecurityRuntimeSessionBinding = null;
      final hardened = _hardenedSecurityRuntimeController;
      _hardenedSecurityRuntimeController = null;
      if (hardened != null) {
        await hardened.lock();
      } else if (vault.isUnlocked) {
        await vault.lock();
      }
    }
    if (auditFailure != null) throw auditFailure;
  }

  /// Call immediately before the model worker opens/uses the artifact. The
  /// production loader's own attestation checks remain complementary; this is
  /// the hardened security runtime's independent trust gate.
  Future<void> assertModelStillTrusted() async {
    final model = _hardenedSecurityRuntimeActiveModel;
    if (model == null || !isReady) {
      throw const NazaSecurityException(
        'model_trust_unavailable',
        'No active byte-verified model identity is bound to this runtime.',
      );
    }
    await model.reverifyArtifacts();
  }

  Future<NazaCapabilityLease> authorizeWithPassword({
    required String password,
    required NazaPrivilegedAction action,
    String resource = 'vault',
  }) async {
    await assertModelStillTrusted();
    final lease = await controller.authorizeWithPassword(
      password: password,
      action: action,
      resource: resource,
    );
    await _hardenedSecurityRuntimeAppendPersistent(
      'runtime-capability-issued',
      <String, Object?>{'action': action.name, 'resource': resource},
    );
    return lease;
  }

  Future<NazaCapabilityLease> authorizeWithDeviceKey({
    required NazaPrivilegedAction action,
    String resource = 'vault',
  }) async {
    await assertModelStillTrusted();
    final lease = await controller.authorizeWithDeviceKey(
      action: action,
      resource: resource,
    );
    await _hardenedSecurityRuntimeAppendPersistent(
      'runtime-capability-issued-device-key',
      <String, Object?>{'action': action.name, 'resource': resource},
    );
    return lease;
  }

  Future<Map<NazaVaultRecordKey, Object?>> exportRecordsAuthorized(
    NazaCapabilityLease lease,
  ) async {
    await assertModelStillTrusted();
    final records = await controller.exportRecordsAuthorized(lease);
    records.removeWhere(
      (record, _) => record.namespace.startsWith('security.'),
    );
    await _hardenedSecurityRuntimeAppendPersistent(
      'runtime-vault-exported',
      <String, Object?>{'recordCount': records.length},
    );
    return records;
  }

  Future<void> rotateDataKeyAuthorized(NazaCapabilityLease lease) async {
    await assertModelStillTrusted();
    await controller.rotateDataKeyAuthorized(lease);
    await _hardenedSecurityRuntimeAppendPersistent(
      'runtime-data-key-rotated',
      const <String, Object?>{},
    );
  }

  Future<void> verifyPersistentAudit({int maxEntries = 256}) async {
    final audit = _hardenedSecurityRuntimePersistentAudit;
    if (audit == null || !audit.initialized) {
      throw const NazaSecurityException(
        'audit_not_ready',
        'Persistent audit is not initialized.',
      );
    }
    await audit.verifyRecent(maxEntries: maxEntries);
  }

  NazaHardenedVaultController _hardenedSecurityRuntimeNewController(
    NazaSecurityIdentitySnapshot identities,
  ) {
    return NazaHardenedVaultController(
      vault: vault,
      secureStore: secureStore,
      keyGuardian: guardian,
      appIdentity: appIdentity,
      modelIdentity: identities.modelIdentity,
      policyIdentity: identities.trustPolicyIdentity,
      recoveryGeneration: identities.recoveryIdentity,
      trustRootIdentity: trustRootIdentity,
    );
  }

  Future<void> _hardenedSecurityRuntimeInitializeRuntimeSecurity(
    NazaSecurityIdentitySnapshot identities,
  ) async {
    final state = _hardenedSecurityRuntimeController?.securityState;
    if (state == null) {
      throw const NazaSecurityException(
        'security_state_missing',
        'Controller did not expose an active security state.',
      );
    }

    _hardenedSecurityRuntimeCapabilityRoot = await guardian.ensureRoot(
      vaultId: state.vaultId,
      purpose: NazaGuardianPurpose.capabilityRoot,
    );
    _hardenedSecurityRuntimeAuditRoot = await guardian.ensureRoot(
      vaultId: state.vaultId,
      purpose: NazaGuardianPurpose.auditRoot,
    );
    if (_hardenedSecurityRuntimeCapabilityRoot!.exportable ||
        _hardenedSecurityRuntimeAuditRoot!.exportable) {
      throw const NazaSecurityException(
        'guardian_exportable_root',
        'Hardened runtime roots must be represented by non-exportable handles.',
      );
    }

    final derived = await guardian.deriveEphemeralSecret(
      handle: _hardenedSecurityRuntimeCapabilityRoot!,
      label: 'runtime-session-binding',
      context: <String, Object?>{
        'epoch': state.epoch,
        'modelIdentity': identities.modelIdentity,
        'recoveryIdentity': identities.recoveryIdentity,
        'trustPolicyIdentity': identities.trustPolicyIdentity,
      },
    );
    _hardenedSecurityRuntimeZero(_hardenedSecurityRuntimeSessionBinding);
    _hardenedSecurityRuntimeSessionBinding = derived;

    final checkpointKey = await guardian.deriveEphemeralSecret(
      handle: _hardenedSecurityRuntimeAuditRoot!,
      label: 'persistent-audit-checkpoint',
      context: <String, Object?>{
        'vaultId': state.vaultId,
        'format': 'naza-audit-checkpoint-v2',
      },
    );
    NazaPersistentForwardAudit? candidateAudit;
    try {
      candidateAudit = NazaPersistentForwardAudit(
        vault: vault,
        secureStore: secureStore,
        vaultId: state.vaultId,
        checkpointKey: checkpointKey,
      );
      await candidateAudit.initialize();
      await candidateAudit.verifyRecent();
      _hardenedSecurityRuntimePersistentAudit?.destroy();
      _hardenedSecurityRuntimePersistentAudit = candidateAudit;
      candidateAudit = null;
    } catch (_) {
      candidateAudit?.destroy();
      rethrow;
    } finally {
      _hardenedSecurityRuntimeZero(checkpointKey);
    }
  }

  Future<void> _hardenedSecurityRuntimeAppendPersistent(
    String event,
    Map<String, Object?> data,
  ) async {
    final audit = _hardenedSecurityRuntimePersistentAudit;
    final epoch = _hardenedSecurityRuntimeController?.securityEpoch;
    if (audit == null || epoch == null) {
      throw const NazaSecurityException(
        'audit_not_ready',
        'Persistent audit is not initialized.',
      );
    }
    await audit.append(
      event: event,
      data: <String, Object?>{
        ...data,
        'guardianCapabilityProtection':
            _hardenedSecurityRuntimeCapabilityRoot?.protection.name ?? '',
        'guardianAuditProtection':
            _hardenedSecurityRuntimeAuditRoot?.protection.name ?? '',
      },
      securityEpoch: epoch,
    );
  }

  void _hardenedSecurityRuntimeDestroySessionState() {
    _hardenedSecurityRuntimePersistentAudit?.destroy();
    _hardenedSecurityRuntimePersistentAudit = null;
    _hardenedSecurityRuntimeActiveModel = null;
    _hardenedSecurityRuntimeZero(_hardenedSecurityRuntimeSessionBinding);
    _hardenedSecurityRuntimeSessionBinding = null;
    _hardenedSecurityRuntimeController = null;
  }
}

void _hardenedSecurityRuntimeZero(List<int>? bytes) {
  if (bytes == null) return;
  for (var index = 0; index < bytes.length; index++) {
    bytes[index] = 0;
  }
}

