    final kernel = _hardenedVaultControllerRequireKernel();
    await kernel.consumeLease(
      lease,
      action: NazaPrivilegedAction.importVault,
      resource: 'vault',
    );
    await _hardenedVaultControllerAdvanceSecurityEpoch(
      'vault-imported',
      <String, Object?>{'replace': replace, 'recordCount': records.length},
