enum NazaTrustClass {
  trustedSystem,
  trustedLocal,
  userAuthored,
  modelGenerated,
  externalUntrusted,
  malformedOrUnknown,
}

enum NazaIntentRisk {
  informational,
  privateRead,
  privateWrite,
  privileged,
  catastrophic,
