const _keyGuardianGuardianFormat = 'naza-key-guardian-v1';

enum NazaGuardianProtection {
  volatileMemory,
  platformSecureStore,
  hardwareBacked,
}

enum NazaGuardianPurpose {
  capabilityRoot,
  auditRoot,
  rollbackRoot,
  ipcRoot,
  modelTrustRoot,
}

final class NazaKeyHandle {
  final String id;
  final NazaGuardianPurpose purpose;
  final NazaGuardianProtection protection;
  final bool exportable;

  const NazaKeyHandle({
    required this.id,
    required this.purpose,
    required this.protection,
    required this.exportable,
  });
}

abstract interface class NazaKeyGuardian {
  Future<NazaKeyHandle> ensureRoot({
    required String vaultId,
    required NazaGuardianPurpose purpose,
  });

  Future<Uint8List> deriveEphemeralSecret({
    required NazaKeyHandle handle,
    required String label,
    required Map<String, Object?> context,
  });

  Future<void> revokeRoot(NazaKeyHandle handle);
}

final class NazaSecureStoreKeyGuardian implements NazaKeyGuardian {
  NazaSecureStoreKeyGuardian(this._keyGuardianStore);

  final NazaDeviceKeyStore _keyGuardianStore;
  final Hmac _keyGuardianHmac = Hmac.sha256();

  @override
  Future<NazaKeyHandle> ensureRoot({
    required String vaultId,
    required NazaGuardianPurpose purpose,
  }) async {
    _keyGuardianValidateVaultId(vaultId);
    final id = '$_keyGuardianGuardianFormat/$vaultId/${purpose.name}';
    final storageKey = _keyGuardianStorageKey(id);
    final existing = await _keyGuardianStore.read(storageKey);
    if (existing == null || existing.isEmpty) {
      final root = _keyGuardianRandomBytes(32);
      try {
        await _keyGuardianStore.write(storageKey, base64Encode(root));
      } finally {
        _keyGuardianZero(root);
      }
    } else {
      final decoded = _keyGuardianDecodeRoot(existing);
      _keyGuardianZero(decoded);
    }
    return NazaKeyHandle(
      id: id,
      purpose: purpose,
      protection: NazaGuardianProtection.platformSecureStore,
      exportable: false,
    );
  }

  @override
  Future<Uint8List> deriveEphemeralSecret({
    required NazaKeyHandle handle,
    required String label,
    required Map<String, Object?> context,
  }) async {
    _keyGuardianValidateHandle(handle);
    if (label.isEmpty || label.length > 128) {
      throw ArgumentError.value(label, 'label', 'Invalid derivation label.');
    }
    final encodedRoot = await _keyGuardianStore.read(
      _keyGuardianStorageKey(handle.id),
    );
    if (encodedRoot == null || encodedRoot.isEmpty) {
      throw const NazaKeyGuardianException(
        'root_missing',
        'The protected guardian root is unavailable.',
      );
    }
    final root = _keyGuardianDecodeRoot(encodedRoot);
    try {
      final transcript = utf8.encode(
        _keyGuardianCanonicalJson(<String, Object?>{
          'format': _keyGuardianGuardianFormat,
          'handle': handle.id,
          'label': label,
          'purpose': handle.purpose.name,
          'context': context,
        }),
      );
      final mac = await _keyGuardianHmac.calculateMac(
        transcript,
        secretKey: SecretKey(root),
      );
      return Uint8List.fromList(mac.bytes);
    } finally {
      _keyGuardianZero(root);
    }
  }

  @override
  Future<void> revokeRoot(NazaKeyHandle handle) async {
    _keyGuardianValidateHandle(handle);
    await _keyGuardianStore.delete(_keyGuardianStorageKey(handle.id));
  }

  void _keyGuardianValidateHandle(NazaKeyHandle handle) {
    final expectedSuffix = '/${handle.purpose.name}';
    if (handle.exportable ||
        handle.protection != NazaGuardianProtection.platformSecureStore ||
        !handle.id.startsWith('$_keyGuardianGuardianFormat/') ||
        !handle.id.endsWith(expectedSuffix)) {
      throw const NazaKeyGuardianException(
        'invalid_handle',
        'The guardian key handle is not valid for this provider or purpose.',
      );
    }
    final components = handle.id.split('/');
    if (components.length != 3 ||
        components[0] != _keyGuardianGuardianFormat ||
        components[2] != handle.purpose.name) {
      throw const NazaKeyGuardianException(
        'invalid_handle',
        'The guardian key handle identity is malformed.',
      );
    }
    _keyGuardianValidateVaultId(components[1]);
  }

  Uint8List _keyGuardianDecodeRoot(String encoded) {
    try {
      final bytes = Uint8List.fromList(base64Decode(encoded));
      if (bytes.length != 32) {
        _keyGuardianZero(bytes);
        throw const FormatException('unexpected root length');
      }
      return bytes;
    } catch (error) {
      throw NazaKeyGuardianException(
        'root_corrupt',
        'Protected guardian root is malformed: $error',
      );
    }
  }

  String _keyGuardianStorageKey(String id) =>
      'naza-guardian-${base64UrlEncode(utf8.encode(id)).replaceAll('=', '')}';
}

final class NazaKeyGuardianException implements Exception {
  final String code;
  final String message;

  const NazaKeyGuardianException(this.code, this.message);

  @override
  String toString() => 'NazaKeyGuardianException($code): $message';
}

void _keyGuardianValidateVaultId(String vaultId) {
  if (!RegExp(r'^[A-Za-z0-9_-]{16,64}$').hasMatch(vaultId)) {
    throw ArgumentError.value(vaultId, 'vaultId', 'Invalid vault identifier.');
  }
}

Object? _keyGuardianCanonicalize(Object? value) {
  if (value is Map) {
    final keys = value.keys.map((key) => key.toString()).toList()..sort();
    return <String, Object?>{
      for (final key in keys) key: _keyGuardianCanonicalize(value[key]),
    };
  }
  if (value is List) {
    return value
        .map<Object?>((item) => _keyGuardianCanonicalize(item))
        .toList(growable: false);
  }
  if (value is num || value is bool || value is String || value == null) {
    return value;
  }
  return value.toString();
}

String _keyGuardianCanonicalJson(Object? value) =>
    jsonEncode(_keyGuardianCanonicalize(value));

Uint8List _keyGuardianRandomBytes(int length) {
  final random = math.Random.secure();
  return Uint8List.fromList(
    List<int>.generate(length, (_) => random.nextInt(256)),
  );
}

void _keyGuardianZero(List<int>? bytes) {
  if (bytes == null) return;
  for (var index = 0; index < bytes.length; index++) {
    bytes[index] = 0;
  }
}

