      final seed = _metamericSurfaceLatticeHmacSha512(
        _metamericSurfaceLatticeBindingKey,
        _metamericSurfaceLatticeConcat([
          _metamericSurfaceLatticeField(utf8.encode('MSL/challenge-seed/v2')),
          _metamericSurfaceLatticeField(request.verifierNonce),
          _metamericSurfaceLatticeField(deviceNonce),
          _metamericSurfaceLatticeU64(nextCounter),
          _metamericSurfaceLatticeField(utf8.encode(profile.id)),
          _metamericSurfaceLatticeField(request.authorizationIntent.commitment),
        ]),
      );
      final program = _metamericSurfaceLatticeGenerateProgram(seed);
      final requestedDigest = _metamericSurfaceLatticeSha3(
        program.canonicalBytes(),
      );
      final result = await reader.execute(program);
      surfaceSecret = result.surfaceSecret;
      if (surfaceSecret.length < 32 ||
          result.executedProgramDigest.length != requestedDigest.length ||
          !_metamericSurfaceLatticeConstantTimeEqual(
            result.executedProgramDigest,
            requestedDigest,
          )) {
        throw const MslProtocolException(
          'reader_transcript_mismatch',
          'The reader did not prove execution of the requested program.',
        );
      }
      if (result.firmwareMeasurement.length != 32 ||
          result.attestation.length < 64 ||
          !await attestationVerifier.verify(
            deviceId: reader.deviceId,
            profileId: profile.id,
            requestedProgramDigest: requestedDigest,
            result: result,
          )) {
        throw const MslProtocolException(
          'reader_attestation_rejected',
          'The reader firmware or execution attestation is not trusted.',
        );
      }
      _metamericSurfaceLatticeValidateHealth(result.health);
      final transcript = _metamericSurfaceLatticeConcat([
        _metamericSurfaceLatticeField(utf8.encode(mslProtocolVersion)),
        _metamericSurfaceLatticeField(utf8.encode(reader.deviceId)),
        _metamericSurfaceLatticeField(utf8.encode(profile.id)),
        _metamericSurfaceLatticeField(utf8.encode(request.purpose)),
        _metamericSurfaceLatticeField(request.verifierNonce),
        _metamericSurfaceLatticeField(deviceNonce),
        _metamericSurfaceLatticeU64(nextCounter),
        _metamericSurfaceLatticeField(requestedDigest),
        _metamericSurfaceLatticeField(result.firmwareMeasurement),
        _metamericSurfaceLatticeField(request.authorizationIntent.commitment),
        _metamericSurfaceLatticeField(
          request.authorizationIntent.postQuantumContextDigest,
        ),
        _metamericSurfaceLatticeField(request.authorizationIntent.targetDigest),
      ]);
      final transcriptDigest = _metamericSurfaceLatticeSha3(transcript);
      sessionKey = _metamericSurfaceLatticeExtractAndExpand(
        surfaceSecret,
        postQuantumSharedSecret,
        transcriptDigest,
        request.purpose,
      );
      final proof = _metamericSurfaceLatticeHmacSha512(
        sessionKey,
        _metamericSurfaceLatticeConcat([
          _metamericSurfaceLatticeField(utf8.encode('MSL/proof/v2')),
          _metamericSurfaceLatticeField(transcriptDigest),
        ]),
      );
      final handleId = base64UrlEncode(
        _metamericSurfaceLatticeSha3(
          _metamericSurfaceLatticeConcat([
            sessionKey,
            _metamericSurfaceLatticeEntropy(16),
          ]),
        ),
      ).replaceAll('=', '');
      final committedCounter = await counterStore.advance(
        deviceId: reader.deviceId,
        profileId: profile.id,
        expectedCurrent: _metamericSurfaceLatticeCounter,
      );
      if (committedCounter != nextCounter) {
        throw const MslProtocolException(
          'counter_commit_invalid',
          'The monotonic counter store returned an invalid transition.',
        );
      }
      _metamericSurfaceLatticeCounter = committedCounter;
      _metamericSurfaceLatticeSessionKeys[handleId] =
          _MetamericSurfaceLatticeMslStoredKey(
            sessionKey,
            now.add(keyLifetime),
          );
      sessionKey = null; // Ownership moved into the opaque handle store.
      _metamericSurfaceLatticePurgeExpiredKeys(now);
      final receiptDigest = _metamericSurfaceLatticeSha3(
        _metamericSurfaceLatticeConcat([
          _metamericSurfaceLatticeField(
            utf8.encode('MSL/authorization-receipt/v1'),
          ),
          _metamericSurfaceLatticeField(request.authorizationIntent.commitment),
          _metamericSurfaceLatticeField(transcriptDigest),
          _metamericSurfaceLatticeField(proof),
          _metamericSurfaceLatticeU64(nextCounter),
        ]),
      );
      return MslAuthenticationProof(
        deviceId: reader.deviceId,
        profileId: profile.id,
        transcriptDigest: transcriptDigest,
        proof: proof,
        keyHandle: MslKeyHandle._(handleId, now, now.add(keyLifetime)),
        counter: nextCounter,
        authorizationBinding: MslAuthorizationBinding._(
          intent: request.authorizationIntent,
          deviceId: reader.deviceId,
          profileId: profile.id,
          counter: nextCounter,
          transcriptDigest: Uint8List.fromList(transcriptDigest),
          receiptDigest: receiptDigest,
        ),
      );
    } catch (_) {
      try {
        await reader.resetAfterFault();
      } catch (_) {
        // Preserve the original failure; the next call still checks state.
      }
      rethrow;
    } finally {
      if (surfaceSecret != null) _metamericSurfaceLatticeZeroize(surfaceSecret);
      if (sessionKey != null) _metamericSurfaceLatticeZeroize(sessionKey);
      _metamericSurfaceLatticeBusy = false;
    }
  }

  Uint8List authenticateMessage(MslKeyHandle handle, Uint8List message) {
    final key = _metamericSurfaceLatticeResolveHandle(handle);
    if (message.length > 1024 * 1024) {
      throw const MslProtocolException(
        'message_too_large',
        'The authenticated message exceeds one MiB.',
      );
    }
    return _metamericSurfaceLatticeHmacSha512(
      key,
      _metamericSurfaceLatticeConcat([
        _metamericSurfaceLatticeField(utf8.encode('MSL/application-mac/v2')),
        _metamericSurfaceLatticeField(message),
      ]),
    );
  }

  void destroyHandle(MslKeyHandle handle) {
    final stored = _metamericSurfaceLatticeSessionKeys.remove(handle.id);
    if (stored != null) _metamericSurfaceLatticeZeroize(stored.key);
  }

  void dispose() {
    for (final stored in _metamericSurfaceLatticeSessionKeys.values) {
      _metamericSurfaceLatticeZeroize(stored.key);
    }
    _metamericSurfaceLatticeSessionKeys.clear();
    _metamericSurfaceLatticeZeroize(_metamericSurfaceLatticeBindingKey);
  }

  void _metamericSurfaceLatticeValidateRequest(
    MslAuthenticationRequest request,
    Uint8List pqSecret,
  ) {
    final now = _metamericSurfaceLatticeClock().toUtc();
    final issued = request.issuedAt.toUtc();
    try {
      request.authorizationIntent.validateAt(now);
    } catch (_) {
      throw const MslProtocolException(
        'authorization_event_invalid',
        'The shared authorization intent is expired or not yet valid.',
      );
    }
    if (request.verifierNonce.length != 32 ||
        request.purpose.isEmpty ||
        request.purpose.length > 64 ||
        !_metamericSurfaceLatticeSafePurpose(request.purpose) ||
        issued.isAfter(now.add(const Duration(seconds: 30))) ||
        now.difference(issued) > requestLifetime) {
      throw const MslProtocolException(
        'request_invalid',
        'The verifier request is malformed, expired, or outside policy.',
      );
    }
    final intent = request.authorizationIntent;
    if (intent.purpose != request.purpose ||
        !_metamericSurfaceLatticeConstantTimeEqual(
          intent.verifierNonce,
          request.verifierNonce,
        ) ||
        intent.issuedAt.toUtc() != issued ||
        intent.mslDeviceId != reader.deviceId ||
        intent.mslProfileId != profile.id) {
      throw const MslProtocolException(
        'authorization_event_mismatch',
        'The physical request does not match its authorization intent.',
      );
    }
    if (pqSecret.length < 32 || pqSecret.length > 128) {
      throw const MslProtocolException(
        'pq_secret_invalid',
        'A 32-128 byte authenticated post-quantum shared secret is required.',
      );
    }
    if (reader.state == MslReaderState.executing ||
        reader.state == MslReaderState.reconstructing ||
        reader.state == MslReaderState.fault) {
      throw const MslProtocolException(
        'reader_state_invalid',
        'The reader is not in a safe state for authentication.',
      );
    }
  }

  void _metamericSurfaceLatticeEnforceRateLimit(DateTime now) {
    _metamericSurfaceLatticeRequestTimes.removeWhere(
      (time) => now.difference(time) >= rateWindow,
    );
    if (_metamericSurfaceLatticeRequestTimes.length >=
        maximumRequestsPerWindow) {
      throw const MslProtocolException(
        'rate_limited',
        'The physical interrogation rate limit was reached.',
      );
    }
    _metamericSurfaceLatticeRequestTimes.add(now);
  }

  MslChallengeProgram _metamericSurfaceLatticeGenerateProgram(Uint8List seed) {
    var stream = Uint8List.fromList(seed);
    var offset = stream.length;
    int nextInt(int bound) {
      if (offset + 4 > stream.length) {
        stream = _metamericSurfaceLatticeHmacSha512(
          _metamericSurfaceLatticeBindingKey,
          _metamericSurfaceLatticeConcat([
            _metamericSurfaceLatticeField(
              utf8.encode('MSL/challenge-expand/v2'),
            ),
            _metamericSurfaceLatticeField(stream),
          ]),
        );
        offset = 0;
      }
      final value = ByteData.sublistView(stream).getUint32(offset, Endian.big);
      offset += 4;
      return value % bound;
    }

    final instructions = <MslChallengeInstruction>[];
    var energy = 0;
    for (var index = 0; index < profile.challengeCount; index++) {
      final intensity =
          profile.intensitiesMilli[nextInt(profile.intensitiesMilli.length)];
      final duration =
          profile.durationsMicros[nextInt(profile.durationsMicros.length)];
      energy += intensity * math.max(1, duration ~/ 1000);
      if (energy > profile.maxCumulativeEnergyUnits) {
        throw const MslProtocolException(
          'optical_dose_exceeded',
          'The generated program exceeds the optical dose limit.',
        );
      }
      instructions.add(
        MslChallengeInstruction(
          wavelengthNm:
              profile.wavelengthsNm[nextInt(profile.wavelengthsNm.length)],
          intensityMilli: intensity,
          incidenceMilliDegrees:
              profile.incidenceMilliDegrees[nextInt(
                profile.incidenceMilliDegrees.length,
              )],
          polarizationMilliDegrees:
              profile.polarizationMilliDegrees[nextInt(
                profile.polarizationMilliDegrees.length,
              )],
          durationMicros: duration,
        ),
      );
    }
    return MslChallengeProgram(
      profileId: profile.id,
      instructions: List.unmodifiable(instructions),
    );
  }

  void _metamericSurfaceLatticeValidateHealth(MslReaderHealth health) {
    if (!health.productionFirmware ||
        !health.resetVerified ||
        health.detectorSaturated ||
        health.detectorUnderexposed ||
        health.temperatureMilliC < profile.minimumTemperatureMilliC ||
        health.temperatureMilliC > profile.maximumTemperatureMilliC ||
        health.maximumTimingErrorMicros > profile.maximumTimingErrorMicros) {
      throw const MslProtocolException(
        'reader_health_rejected',
        'The optical execution was outside its authenticated operating envelope.',
      );
    }
  }

  Uint8List _metamericSurfaceLatticeExtractAndExpand(
    Uint8List surface,
    Uint8List pq,
    Uint8List transcript,
    String purpose,
  ) {
    final salt = _metamericSurfaceLatticeSha3(
      _metamericSurfaceLatticeConcat([
        _metamericSurfaceLatticeField(utf8.encode('MSL/hybrid-extract/v2')),
        _metamericSurfaceLatticeField(transcript),
      ]),
    );
    final prk = _metamericSurfaceLatticeHmacSha512(
      salt,
      _metamericSurfaceLatticeConcat([
        _metamericSurfaceLatticeField(surface),
        _metamericSurfaceLatticeField(pq),
      ]),
    );
    try {
      return _metamericSurfaceLatticeHmacSha512(
        prk,
        _metamericSurfaceLatticeConcat([
          _metamericSurfaceLatticeField(utf8.encode('MSL/session-key/v2')),
          _metamericSurfaceLatticeField(utf8.encode(reader.deviceId)),
          _metamericSurfaceLatticeField(utf8.encode(profile.id)),
          _metamericSurfaceLatticeField(utf8.encode(purpose)),
          _metamericSurfaceLatticeField(transcript),
          Uint8List.fromList([1]),
        ]),
      ).sublist(0, 32);
    } finally {
      _metamericSurfaceLatticeZeroize(prk);
    }
  }

  Uint8List _metamericSurfaceLatticeResolveHandle(MslKeyHandle handle) {
    final now = _metamericSurfaceLatticeClock().toUtc();
    if (!now.isBefore(handle.expiresAt)) {
      destroyHandle(handle);
      throw const MslProtocolException(
        'key_handle_expired',
        'The MSL key handle expired.',
      );
    }
    final stored = _metamericSurfaceLatticeSessionKeys[handle.id];
    if (stored == null) {
      throw const MslProtocolException(
        'key_handle_unknown',
        'The MSL key handle is unknown or destroyed.',
      );
    }
    return stored.key;
  }

  void _metamericSurfaceLatticePurgeExpiredKeys(DateTime now) {
    final expired = _metamericSurfaceLatticeSessionKeys.entries
        .where((entry) => !now.isBefore(entry.value.expiresAt))
        .map((entry) => entry.key)
        .toList(growable: false);
    for (final id in expired) {
      final stored = _metamericSurfaceLatticeSessionKeys.remove(id);
      if (stored != null) _metamericSurfaceLatticeZeroize(stored.key);
    }
  }
}

final class _MetamericSurfaceLatticeMslStoredKey {
  const _MetamericSurfaceLatticeMslStoredKey(this.key, this.expiresAt);
  final Uint8List key;
  final DateTime expiresAt;
}

bool _metamericSurfaceLatticeSafeId(String value) =>
    value.isNotEmpty &&
    value.length <= 128 &&
    RegExp(r'^[A-Za-z0-9._:-]+$').hasMatch(value);
bool _metamericSurfaceLatticeSafePurpose(String value) =>
    RegExp(r'^[A-Za-z0-9._:/-]+$').hasMatch(value);

Uint8List _metamericSurfaceLatticeField(List<int> value) =>
    _metamericSurfaceLatticeConcat([
      _metamericSurfaceLatticeU32(value.length),
      Uint8List.fromList(value),
    ]);
Uint8List _metamericSurfaceLatticeU32(int value) =>
    (ByteData(4)..setUint32(0, value, Endian.big)).buffer.asUint8List();
Uint8List _metamericSurfaceLatticeU64(int value) =>
    (ByteData(8)..setUint64(0, value, Endian.big)).buffer.asUint8List();
Uint8List _metamericSurfaceLatticeConcat(Iterable<List<int>> parts) {
  final builder = BytesBuilder(copy: false);
  for (final part in parts) {
    builder.add(part);
  }
  return builder.takeBytes();
}

Uint8List _metamericSurfaceLatticeSha3(List<int> value) {
  // SHA-512/256 is unavailable in package:crypto. SHA-256 remains a standard
  // collision-resistant transcript digest; HMAC-SHA-512 performs extraction.
  return Uint8List.fromList(crypto.sha256.convert(value).bytes);
}

Uint8List _metamericSurfaceLatticeHmacSha512(List<int> key, List<int> value) =>
    Uint8List.fromList(crypto.Hmac(crypto.sha512, key).convert(value).bytes);

Uint8List _metamericSurfaceLatticeSecureEntropy(int length) {
  final random = math.Random.secure();
  return Uint8List.fromList(
    List<int>.generate(length, (_) => random.nextInt(256), growable: false),
  );
}

bool _metamericSurfaceLatticeConstantTimeEqual(
  List<int> left,
  List<int> right,
) {
  var difference = left.length ^ right.length;
  final length = math.min(left.length, right.length);
  for (var index = 0; index < length; index++) {
    difference |= left[index] ^ right[index];
  }
  return difference == 0;
}

void _metamericSurfaceLatticeZeroize(Uint8List value) =>
    value.fillRange(0, value.length, 0);
String _metamericSurfaceLatticeHex(List<int> value) =>
    value.map((byte) => byte.toRadixString(16).padLeft(2, '0')).join();

