const _persistentAuditAuditFormat = 'naza-persistent-audit-v1';
const _persistentAuditAuditNamespace = 'security.audit';
const _persistentAuditAuditCheckpointFormat = 'naza-audit-checkpoint-v2';
const _persistentAuditAuditCheckpointPrefix = 'naza-audit-checkpoint-v2';

final class NazaPersistentAuditEntry {
  final int sequence;
  final int securityEpoch;
  final String event;
  final Map<String, Object?> data;
  final String previous;
  final String mac;
  final String digest;

  const NazaPersistentAuditEntry({
    required this.sequence,
    required this.securityEpoch,
    required this.event,
    required this.data,
    required this.previous,
    required this.mac,
    required this.digest,
  });

  Map<String, Object?> toJson() => <String, Object?>{
    'format': _persistentAuditAuditFormat,
    'sequence': sequence,
    'securityEpoch': securityEpoch,
    'event': event,
    'data': _persistentAuditCanonicalize(data),
    'previous': previous,
    'mac': mac,
    'digest': digest,
  };
}

final class NazaPersistentAuditCheckpoint {
  final int sequence;
  final String tip;
  final String ratchetKey;

  const NazaPersistentAuditCheckpoint({
    required this.sequence,
    required this.tip,
    required this.ratchetKey,
  });

  Map<String, Object?> toJson() => <String, Object?>{
    'format': _persistentAuditAuditFormat,
    'sequence': sequence,
    'tip': tip,
    'ratchetKey': ratchetKey,
  };

  factory NazaPersistentAuditCheckpoint.fromJson(Map<String, Object?> json) {
    if (json['format'] != _persistentAuditAuditFormat) {
      throw const NazaPersistentAuditException(
        'checkpoint_format',
        'Persistent audit checkpoint payload format is invalid.',
      );
    }
    final sequence = _persistentAuditPositiveOrZeroInt(json['sequence']);
    final tip = json['tip']?.toString() ?? '';
    final ratchetKey = json['ratchetKey']?.toString() ?? '';
    if (sequence == null || tip.isEmpty || ratchetKey.isEmpty) {
      throw const NazaPersistentAuditException(
        'checkpoint_corrupt',
        'Persistent audit checkpoint payload is malformed.',
      );
    }
    return NazaPersistentAuditCheckpoint(
      sequence: sequence,
      tip: tip,
      ratchetKey: ratchetKey,
    );
  }
}

/// Forward-secure audit log with restart persistence.
///
/// Audit entries are encrypted by the vault. Restart state is independently
/// sealed with AES-256-GCM under a guardian-derived checkpoint key, binding the
/// checkpoint to this vault ID through AEAD associated data. The current
/// ratchet key therefore never appears as plaintext in the secure-store record.
final class NazaPersistentForwardAudit {
  NazaPersistentForwardAudit({
    required this.vault,
    required this.secureStore,
    required this.vaultId,
    required List<int> checkpointKey,
  }) : _persistentAuditCheckpointKey = Uint8List.fromList(checkpointKey) {
    if (_persistentAuditCheckpointKey.length != 32) {
      _persistentAuditZero(_persistentAuditCheckpointKey);
      throw ArgumentError.value(
        checkpointKey.length,
        'checkpointKey',
        'Audit checkpoint key must be 32 bytes.',
      );
    }
  }

  final NazaSecureDatabase vault;
  final NazaDeviceKeyStore secureStore;
  final String vaultId;

  final Hmac _persistentAuditHmac = Hmac.sha256();
  final Sha256 _persistentAuditSha256 = Sha256();
  final AesGcm _persistentAuditCheckpointCipher = AesGcm.with256bits();
  final Uint8List _persistentAuditCheckpointKey;

  int _persistentAuditSequence = 0;
  String _persistentAuditTip = 'GENESIS';
  Uint8List? _persistentAuditRatchetKey;
  bool _persistentAuditInitialized = false;
  bool _persistentAuditDisposed = false;

  int get sequence => _persistentAuditSequence;
  String get tip => _persistentAuditTip;
  bool get initialized => _persistentAuditInitialized;

  Future<void> initialize() async {
    if (_persistentAuditDisposed) {
      throw const NazaPersistentAuditException(
        'audit_disposed',
        'Persistent audit instance has been destroyed.',
      );
    }
    _persistentAuditValidateVaultId(vaultId);
    if (!vault.isUnlocked) {
      throw const NazaPersistentAuditException(
        'vault_locked',
        'Vault must be unlocked before the persistent audit can initialize.',
      );
    }
    _persistentAuditResetRatchet();

    final checkpointRaw = await secureStore.read(
      _persistentAuditCheckpointStorageKey,
    );
    if (checkpointRaw == null || checkpointRaw.isEmpty) {
      // Once an audit entry exists, disappearance of the external checkpoint is
      // a tamper/rollback signal. Do not rebuild a new GENESIS checkpoint over
      // existing history.
      final existingFirst = await vault.readJson(
        _persistentAuditAuditNamespace,
        _persistentAuditEntryKey(1),
      );
      if (existingFirst != null) {
        throw const NazaPersistentAuditException(
          'checkpoint_missing',
          'Persistent audit history exists but its protected checkpoint is missing.',
        );
      }
      final key = _persistentAuditRandomBytes(32);
      _persistentAuditRatchetKey = Uint8List.fromList(key);
      _persistentAuditSequence = 0;
      _persistentAuditTip = 'GENESIS';
      await _persistentAuditPersistCheckpoint();
      _persistentAuditZero(key);
    } else {
      final checkpoint = await _persistentAuditDecodeCheckpoint(checkpointRaw);
      final key = _persistentAuditDecodeKey(checkpoint.ratchetKey);
      _persistentAuditRatchetKey = key;
      _persistentAuditSequence = checkpoint.sequence;
      _persistentAuditTip = checkpoint.tip;
    }

    await _persistentAuditReconcilePendingEntry();
    _persistentAuditInitialized = true;
  }

  Future<NazaPersistentAuditEntry> append({
    required String event,
    required Map<String, Object?> data,
    required int securityEpoch,
  }) async {
    _persistentAuditRequireInitialized();
    if (event.isEmpty || event.length > 128) {
      throw ArgumentError.value(event, 'event', 'Invalid audit event name.');
    }
    if (securityEpoch < 1) {
      throw ArgumentError.value(securityEpoch, 'securityEpoch');
    }
    final key = _persistentAuditRequireRatchetKey();
    final nextSequence = _persistentAuditSequence + 1;
    final body = <String, Object?>{
      'format': _persistentAuditAuditFormat,
      'sequence': nextSequence,
      'securityEpoch': securityEpoch,
      'event': event,
      'data': _persistentAuditCanonicalize(data),
      'previous': _persistentAuditTip,
    };
    final mac = await _persistentAuditMacForBody(body, key);
    final digest = await _persistentAuditDigestFor(<String, Object?>{
      ...body,
      'mac': mac,
    });
    final entry = NazaPersistentAuditEntry(
      sequence: nextSequence,
      securityEpoch: securityEpoch,
      event: event,
      data: Map<String, Object?>.unmodifiable(data),
      previous: _persistentAuditTip,
      mac: mac,
      digest: digest,
    );

    // Entry first, checkpoint second. A crash between these writes leaves one
    // authenticated pending entry that startup can reconcile using the old
    // checkpoint ratchet key.
    await vault.writeJson(
      _persistentAuditAuditNamespace,
      _persistentAuditEntryKey(nextSequence),
      entry.toJson(),
    );

    final nextKey = await _persistentAuditRatchet(key, nextSequence);
    final oldKey = _persistentAuditRatchetKey;
    _persistentAuditRatchetKey = nextKey;
    _persistentAuditSequence = nextSequence;
    _persistentAuditTip = digest;
    try {
      await _persistentAuditPersistCheckpoint();
    } catch (_) {
      _persistentAuditZero(_persistentAuditRatchetKey);
      _persistentAuditRatchetKey = oldKey;
      _persistentAuditSequence = nextSequence - 1;
      _persistentAuditTip = entry.previous;
      rethrow;
    }
    if (!identical(oldKey, _persistentAuditRatchetKey))
      _persistentAuditZero(oldKey);
    return entry;
  }

  Future<void> verifyRecent({int maxEntries = 256}) async {
    _persistentAuditRequireInitialized();
    if (maxEntries < 1 || maxEntries > 4096) {
      throw ArgumentError.value(maxEntries, 'maxEntries');
    }
    if (_persistentAuditSequence == 0) return;

    final start = math.max(1, _persistentAuditSequence - maxEntries + 1);
    String? expectedPrevious;
    for (var seq = start; seq <= _persistentAuditSequence; seq++) {
      final raw = await vault.readJson(
        _persistentAuditAuditNamespace,
        _persistentAuditEntryKey(seq),
      );
      if (raw is! Map) {
        throw NazaPersistentAuditException(
          'audit_gap',
          'Persistent audit entry $seq is missing.',
        );
      }
      final entry = _persistentAuditParseEntry(raw);
      if (entry.sequence != seq) {
        throw const NazaPersistentAuditException(
          'audit_sequence',
          'Persistent audit entry sequence is invalid.',
        );
      }
      if (expectedPrevious != null && entry.previous != expectedPrevious) {
        throw const NazaPersistentAuditException(
          'audit_chain',
          'Persistent audit hash chain is broken.',
        );
      }
      final body = <String, Object?>{
        'format': _persistentAuditAuditFormat,
        'sequence': entry.sequence,
        'securityEpoch': entry.securityEpoch,
        'event': entry.event,
        'data': _persistentAuditCanonicalize(entry.data),
        'previous': entry.previous,
        'mac': entry.mac,
      };
      final expectedDigest = await _persistentAuditDigestFor(body);
      if (!_persistentAuditConstantTimeTextEquals(
        expectedDigest,
        entry.digest,
      )) {
        throw const NazaPersistentAuditException(
          'audit_digest',
          'Persistent audit entry content digest is invalid.',
        );
      }
      expectedPrevious = entry.digest;
    }
    if (expectedPrevious != _persistentAuditTip) {
      throw const NazaPersistentAuditException(
        'audit_tip_mismatch',
        'Persistent audit tip does not match protected checkpoint.',
      );
    }
  }

  Future<void> _persistentAuditReconcilePendingEntry() async {
    final currentKey = _persistentAuditRequireRatchetKey();
    final pendingSequence = _persistentAuditSequence + 1;
    final raw = await vault.readJson(
      _persistentAuditAuditNamespace,
      _persistentAuditEntryKey(pendingSequence),
    );
    if (raw == null) return;
    if (raw is! Map) {
      throw const NazaPersistentAuditException(
        'audit_entry_corrupt',
        'Pending audit entry is malformed.',
      );
    }
    final entry = _persistentAuditParseEntry(raw);
    if (entry.sequence != pendingSequence ||
        entry.previous != _persistentAuditTip) {
      throw const NazaPersistentAuditException(
        'audit_pending_invalid',
        'Pending audit entry does not extend the protected checkpoint.',
      );
    }
    final body = <String, Object?>{
      'format': _persistentAuditAuditFormat,
      'sequence': entry.sequence,
      'securityEpoch': entry.securityEpoch,
      'event': entry.event,
      'data': _persistentAuditCanonicalize(entry.data),
      'previous': entry.previous,
    };
    final expectedMac = await _persistentAuditMacForBody(body, currentKey);
    if (!_persistentAuditConstantTimeTextEquals(expectedMac, entry.mac)) {
      throw const NazaPersistentAuditException(
        'audit_authentication',
        'Pending audit entry authentication failed.',
      );
    }
    final expectedDigest = await _persistentAuditDigestFor(<String, Object?>{
      ...body,
      'mac': entry.mac,
    });
    if (!_persistentAuditConstantTimeTextEquals(expectedDigest, entry.digest)) {
      throw const NazaPersistentAuditException(
        'audit_digest',
        'Pending audit entry digest failed validation.',
      );
    }

    final unexpectedNext = await vault.readJson(
      _persistentAuditAuditNamespace,
      _persistentAuditEntryKey(pendingSequence + 1),
    );
    if (unexpectedNext != null) {
      throw const NazaPersistentAuditException(
        'audit_multi_pending',
        'Multiple uncheckpointed audit entries were found.',
      );
    }

    final nextKey = await _persistentAuditRatchet(currentKey, pendingSequence);
    final oldKey = _persistentAuditRatchetKey;
    _persistentAuditRatchetKey = nextKey;
    _persistentAuditSequence = pendingSequence;
    _persistentAuditTip = entry.digest;
    await _persistentAuditPersistCheckpoint();
    _persistentAuditZero(oldKey);
  }

  Future<String> _persistentAuditMacForBody(
    Map<String, Object?> body,
    List<int> key,
  ) async {
    final mac = await _persistentAuditHmac.calculateMac(
      utf8.encode(_persistentAuditCanonicalJson(body)),
      secretKey: SecretKey(key),
    );
    return base64UrlEncode(mac.bytes).replaceAll('=', '');
  }

  Future<String> _persistentAuditDigestFor(Map<String, Object?> body) async {
    final digest = await _persistentAuditSha256.hash(
      utf8.encode(_persistentAuditCanonicalJson(body)),
    );
    return base64UrlEncode(digest.bytes).replaceAll('=', '');
  }

  Future<Uint8List> _persistentAuditRatchet(List<int> key, int sequence) async {
    final mac = await _persistentAuditHmac.calculateMac(
      utf8.encode('$_persistentAuditAuditFormat/ratchet/$vaultId/$sequence'),
      secretKey: SecretKey(key),
    );
    return Uint8List.fromList(mac.bytes);
  }

  Future<void> _persistentAuditPersistCheckpoint() async {
    final checkpoint = NazaPersistentAuditCheckpoint(
      sequence: _persistentAuditSequence,
      tip: _persistentAuditTip,
      ratchetKey: base64Encode(_persistentAuditRequireRatchetKey()),
    );
    final clear = Uint8List.fromList(
      utf8.encode(jsonEncode(checkpoint.toJson())),
    );
    try {
      final box = await _persistentAuditCheckpointCipher.encrypt(
        clear,
        secretKey: SecretKey(_persistentAuditCheckpointKey),
        aad: _persistentAuditCheckpointAad,
      );
      await secureStore.write(
        _persistentAuditCheckpointStorageKey,
        jsonEncode(<String, Object?>{
          'format': _persistentAuditAuditCheckpointFormat,
          'cipher': 'AES-256-GCM',
          'nonce': base64Encode(box.nonce),
          'cipherText': base64Encode(box.cipherText),
          'mac': base64Encode(box.mac.bytes),
        }),
      );
    } finally {
      _persistentAuditZero(clear);
    }
  }

  Future<NazaPersistentAuditCheckpoint> _persistentAuditDecodeCheckpoint(
    String encoded,
  ) async {
    try {
      final outer = jsonDecode(encoded);
      if (outer is! Map ||
          outer['format'] != _persistentAuditAuditCheckpointFormat ||
          outer['cipher'] != 'AES-256-GCM') {
        throw const FormatException('invalid checkpoint envelope');
      }
      final clear = Uint8List.fromList(
        await _persistentAuditCheckpointCipher.decrypt(
          SecretBox(
            base64Decode(outer['cipherText'].toString()),
            nonce: base64Decode(outer['nonce'].toString()),
            mac: Mac(base64Decode(outer['mac'].toString())),
          ),
          secretKey: SecretKey(_persistentAuditCheckpointKey),
          aad: _persistentAuditCheckpointAad,
        ),
      );
      try {
        final inner = jsonDecode(utf8.decode(clear));
        if (inner is! Map) throw const FormatException('payload not a map');
        return NazaPersistentAuditCheckpoint.fromJson(
          Map<String, Object?>.from(inner),
        );
      } finally {
        _persistentAuditZero(clear);
      }
    } on SecretBoxAuthenticationError catch (error) {
      throw NazaPersistentAuditException(
        'checkpoint_authentication',
        'Persistent audit checkpoint authentication failed.',
        error,
      );
    } on NazaPersistentAuditException {
      rethrow;
    } catch (error) {
      throw NazaPersistentAuditException(
        'checkpoint_corrupt',
        'Protected audit checkpoint is malformed: $error',
      );
    }
  }

  NazaPersistentAuditEntry _persistentAuditParseEntry(Map raw) {
    final map = Map<String, Object?>.from(raw);
    if (map['format'] != _persistentAuditAuditFormat) {
      throw const NazaPersistentAuditException(
        'audit_entry_format',
        'Persistent audit entry format is invalid.',
      );
    }
    final sequence = _persistentAuditPositiveInt(map['sequence']);
    final epoch = _persistentAuditPositiveInt(map['securityEpoch']);
    final event = map['event']?.toString() ?? '';
    final previous = map['previous']?.toString() ?? '';
    final mac = map['mac']?.toString() ?? '';
    final digest = map['digest']?.toString() ?? '';
    final dataRaw = map['data'];
    if (sequence == null ||
        epoch == null ||
        event.isEmpty ||
        previous.isEmpty ||
        mac.isEmpty ||
        digest.isEmpty ||
        dataRaw is! Map) {
      throw const NazaPersistentAuditException(
        'audit_entry_corrupt',
        'Persistent audit entry is malformed.',
      );
    }
    return NazaPersistentAuditEntry(
      sequence: sequence,
      securityEpoch: epoch,
      event: event,
      data: Map<String, Object?>.from(dataRaw),
      previous: previous,
      mac: mac,
      digest: digest,
    );
  }

  Uint8List _persistentAuditDecodeKey(String encoded) {
    try {
      final key = Uint8List.fromList(base64Decode(encoded));
      if (key.length != 32) {
        _persistentAuditZero(key);
        throw const FormatException('wrong key length');
      }
      return key;
    } catch (error) {
      throw NazaPersistentAuditException(
        'checkpoint_key',
        'Protected audit ratchet key is invalid: $error',
      );
    }
  }

  List<int> get _persistentAuditCheckpointAad =>
      utf8.encode('$_persistentAuditAuditCheckpointFormat/$vaultId');

  String get _persistentAuditCheckpointStorageKey =>
      '$_persistentAuditAuditCheckpointPrefix-$vaultId';

  String _persistentAuditEntryKey(int sequence) =>
      sequence.toString().padLeft(20, '0');

  Uint8List _persistentAuditRequireRatchetKey() {
    final key = _persistentAuditRatchetKey;
    if (key == null) {
      throw const NazaPersistentAuditException(
        'audit_uninitialized',
        'Persistent audit is not initialized.',
      );
    }
    return key;
  }

  void _persistentAuditRequireInitialized() {
    if (_persistentAuditDisposed ||
        !_persistentAuditInitialized ||
        _persistentAuditRatchetKey == null) {
      throw const NazaPersistentAuditException(
        'audit_uninitialized',
        'Persistent audit is not initialized.',
      );
    }
  }

  void _persistentAuditResetRatchet() {
    _persistentAuditInitialized = false;
    _persistentAuditSequence = 0;
    _persistentAuditTip = 'GENESIS';
    _persistentAuditZero(_persistentAuditRatchetKey);
    _persistentAuditRatchetKey = null;
  }

  void destroy() {
    _persistentAuditResetRatchet();
    _persistentAuditZero(_persistentAuditCheckpointKey);
    _persistentAuditDisposed = true;
  }
}

final class NazaPersistentAuditException implements Exception {
  final String code;
  final String message;
  final Object? cause;

  const NazaPersistentAuditException(this.code, this.message, [this.cause]);

  @override
  String toString() => 'NazaPersistentAuditException($code): $message';
}

Object? _persistentAuditCanonicalize(Object? value) {
  if (value is Map) {
    final keys = value.keys.map((key) => key.toString()).toList()..sort();
    return <String, Object?>{
      for (final key in keys) key: _persistentAuditCanonicalize(value[key]),
    };
  }
  if (value is List) {
    return value
        .map<Object?>((item) => _persistentAuditCanonicalize(item))
        .toList(growable: false);
  }
  if (value is num || value is bool || value is String || value == null) {
    return value;
  }
  return value.toString();
}

String _persistentAuditCanonicalJson(Object? value) =>
    jsonEncode(_persistentAuditCanonicalize(value));

int? _persistentAuditPositiveInt(Object? value) {
  final parsed = value is int ? value : int.tryParse(value?.toString() ?? '');
  return parsed != null && parsed > 0 ? parsed : null;
}

int? _persistentAuditPositiveOrZeroInt(Object? value) {
  final parsed = value is int ? value : int.tryParse(value?.toString() ?? '');
  return parsed != null && parsed >= 0 ? parsed : null;
}

bool _persistentAuditConstantTimeTextEquals(String a, String b) {
  final aa = utf8.encode(a);
  final bb = utf8.encode(b);
  var difference = aa.length ^ bb.length;
  final length = math.min(aa.length, bb.length);
  for (var index = 0; index < length; index++) {
    difference |= aa[index] ^ bb[index];
  }
  return difference == 0;
}

Uint8List _persistentAuditRandomBytes(int length) {
  final random = math.Random.secure();
  return Uint8List.fromList(
    List<int>.generate(length, (_) => random.nextInt(256)),
  );
}

void _persistentAuditValidateVaultId(String vaultId) {
  if (!RegExp(r'^[A-Za-z0-9_-]{16,64}$').hasMatch(vaultId)) {
    throw ArgumentError.value(vaultId, 'vaultId', 'Invalid vault identifier.');
  }
}

void _persistentAuditZero(List<int>? bytes) {
  if (bytes == null) return;
  for (var index = 0; index < bytes.length; index++) {
    bytes[index] = 0;
  }
}

