abstract interface class NazaDeviceKeyStore {
  Future<String?> read(String key);

  Future<void> write(String key, String value);

  Future<void> delete(String key);
}

final class NazaPlatformDeviceKeyStore implements NazaDeviceKeyStore {
  const NazaPlatformDeviceKeyStore();

  static const FlutterSecureStorage _secureDatabaseStorage =
      FlutterSecureStorage();

  @override
  Future<String?> read(String key) => _secureDatabaseStorage.read(key: key);

  @override
  Future<void> write(String key, String value) {
    return _secureDatabaseStorage.write(key: key, value: value);
  }

  @override
  Future<void> delete(String key) => _secureDatabaseStorage.delete(key: key);
}

final class NazaMemoryDeviceKeyStore implements NazaDeviceKeyStore {
  final Map<String, String> _secureDatabaseValues = <String, String>{};

  @override
  Future<String?> read(String key) async => _secureDatabaseValues[key];

  @override
  Future<void> write(String key, String value) async {
    _secureDatabaseValues[key] = value;
  }

  @override
  Future<void> delete(String key) async {
    _secureDatabaseValues.remove(key);
  }
}

/// A SQLite record store whose values and logical identifiers are protected by
