  final NazaDeviceKeyStore _secureDatabaseDeviceKeyStore;
  final NazaVaultCryptoPolicy _secureDatabasePolicy;
  final AesGcm _secureDatabaseAes = AesGcm.with256bits();
  final Hmac _secureDatabaseHmac = Hmac.sha256();
  final Hkdf _secureDatabaseHkdf = Hkdf(hmac: Hmac.sha256(), outputLength: 32);

  Future<void> _secureDatabaseTail = Future<void>.value();
  sqlite.Database? _secureDatabaseDatabase;
  Map<String, Object?>? _secureDatabaseHeader;
  Uint8List? _secureDatabaseVaultUnlockKey;
  Uint8List? _secureDatabaseIndexKey;
  final Map<int, Uint8List> _secureDatabaseDataKeys = <int, Uint8List>{};
  int? _secureDatabaseActiveDataKeyId;

  bool get isUnlocked =>
      _secureDatabaseDatabase != null && _secureDatabaseVaultUnlockKey != null;
  bool get passwordRequired =>
      _secureDatabaseHeader?['passwordRequired'] != false;

  int? get activeDataKeyId => _secureDatabaseActiveDataKeyId;

  Future<NazaVaultInspection> inspect() {
    return _secureDatabaseEnqueue(() async {
      if (isUnlocked) {
        return NazaVaultInspection(
          access: NazaVaultAccess.unlocked,
          passwordRequired: _secureDatabaseHeader?['passwordRequired'] != false,
          legacyDataPresent: false,
        );
      }
      final headerFile = await _secureDatabaseHeaderFile();
      final legacy = await _secureDatabaseLegacyDataPresent();
      if (!await headerFile.exists()) {
        return NazaVaultInspection(
          access: NazaVaultAccess.setupRequired,
          passwordRequired: true,
          legacyDataPresent: legacy,
        );
      }
      final header = await _secureDatabaseReadHeader(headerFile);
      return NazaVaultInspection(
        access: NazaVaultAccess.locked,
        passwordRequired: header['passwordRequired'] != false,
        legacyDataPresent: legacy,
      );
    });
