      () => _secureDatabaseCreateNow(
        password: password,
        passwordRequired: passwordRequired,
        initialRecords: initialRecords,
      ),
    );
  }

  Future<void> unlock(String password) {
    return _secureDatabaseEnqueue(
      () => _secureDatabaseUnlockNow(password: password),
    );
  }

  Future<void> unlockWithDeviceKey() {
    return _secureDatabaseEnqueue(() => _secureDatabaseUnlockNow());
  }

  Future<void> lock() {
    return _secureDatabaseEnqueue(() async => _secureDatabaseLockNow());
  }

  /// Removes only a just-created vault after an explicitly failed recovery
