  Future<void> discardFailedCreation() {
    return _secureDatabaseEnqueue(() async {
      final header = _secureDatabaseHeader;
      final vaultId = header?['vaultId']?.toString();
      await _secureDatabaseLockNow();
      final headerFile = await _secureDatabaseHeaderFile();
      final databaseFile = await _secureDatabaseDatabaseFile();
      if (await headerFile.exists()) await headerFile.delete();
      if (await databaseFile.exists()) await databaseFile.delete();
