  Future<Object?> readJson(String namespace, String key) {
    _secureDatabaseValidatePublicRecordKey(namespace, key);
    return _secureDatabaseEnqueue(
      () => _secureDatabaseReadJsonNow(namespace, key),
    );
  }

  Future<void> writeJson(String namespace, String key, Object? value) {
    _secureDatabaseValidatePublicRecordKey(namespace, key);
