  Future<void> delete(String namespace, String key) {
    _secureDatabaseValidatePublicRecordKey(namespace, key);
    return _secureDatabaseEnqueue(() async {
      final db = _secureDatabaseRequireDatabase();
      final recordId = await _secureDatabaseRecordId(namespace, key);
      db.execute('DELETE FROM vault_records WHERE record_id = ?', [recordId]);
