  Future<Map<NazaVaultRecordKey, Object?>> exportRecords() {
    return _secureDatabaseEnqueue(_secureDatabaseExportRecordsNow);
  }

  Future<void> importRecords(
    Map<NazaVaultRecordKey, Object?> records, {
    bool replace = false,
  }) {
    for (final recordKey in records.keys) {
      _secureDatabaseValidatePublicRecordKey(
        recordKey.namespace,
        recordKey.key,
      );
    }
    return _secureDatabaseEnqueue(() async {
      final db = _secureDatabaseRequireDatabase();
      db.execute('BEGIN IMMEDIATE');
      try {
        if (replace) {
          db.execute('DELETE FROM vault_records WHERE record_id != ?', [
            await _secureDatabaseRecordId(
              _secureDatabaseSentinelNamespace,
              _secureDatabaseSentinelKey,
            ),
          ]);
        }
        for (final entry in records.entries) {
          await _secureDatabaseWriteJsonNow(
            entry.key.namespace,
            entry.key.key,
            entry.value,
            database: db,
          );
