  }

  /// Rotates the active data-encryption key transactionally. A pending header
  /// retains both keys until a database scan proves that the old key is unused.
  Future<void> rotateDataKey() {
    return _secureDatabaseEnqueue(_secureDatabaseRotateDataKeyNow);
  }

  Future<String> integrityCheck() {
    return _secureDatabaseEnqueue(() async {
      final rows = _secureDatabaseRequireDatabase().select(
        'PRAGMA integrity_check',
      );
      return rows.isEmpty ? 'unknown' : rows.first.columnAt(0).toString();
    });
  }

  Future<File> databaseFile() => _secureDatabaseDatabaseFile();

  Future<T> _secureDatabaseEnqueue<T>(Future<T> Function() operation) {
    final queued = _secureDatabaseTail.then((_) => operation());
    _secureDatabaseTail = queued.then<void>(
      (_) {},
      onError: (Object _, StackTrace _) {},
    );
    return queued;
  }

  Future<void> _secureDatabaseCreateNow({
    required String password,
    required bool passwordRequired,
    required Map<NazaVaultRecordKey, Object?> initialRecords,
  }) async {
    await _secureDatabaseLockNow();
    _secureDatabaseValidatePolicy();
    for (final recordKey in initialRecords.keys) {
      _secureDatabaseValidatePublicRecordKey(
        recordKey.namespace,
        recordKey.key,
      );
    }
    final headerFile = await _secureDatabaseHeaderFile();
    if (await headerFile.exists()) {
      throw const NazaVaultException(
        'already_exists',
        'A vault already exists. Unlock it instead of replacing it.',
      );
    }
    if (passwordRequired) _secureDatabaseValidateNewPassword(password);

    final directory = await _secureDatabaseDirectoryProvider();
    await directory.create(recursive: true);
    final databaseFile = await _secureDatabaseDatabaseFile();
    final databasePart = File('${databaseFile.path}.creating');
    if (await databasePart.exists()) await databasePart.delete();
    if (await databaseFile.exists()) {
      throw const NazaVaultException(
        'orphaned_database',
        'A vault database exists without its header. It was preserved for recovery.',
      );
    }

    Uint8List? authKey;
    Uint8List? vaultKey;
    Uint8List? dataKey;
    var deviceKeyWritten = false;
    String? createdVaultId;
    sqlite.Database? db;
    try {
      final vaultId = base64UrlEncode(
        _secureDatabaseRandomBytes(18),
      ).replaceAll('=', '');
      createdVaultId = vaultId;
      final salt = _secureDatabaseRandomBytes(16);
      final header = <String, Object?>{
        'format': _secureDatabaseVaultFormat,
        'version': 3,
        'vaultId': vaultId,
        'generation': 1,
        'passwordRequired': passwordRequired,
        'kdf': passwordRequired
            ? <String, Object?>{
                'algorithm': 'Argon2id-1.3',
                'salt': base64Encode(salt),
                'memoryKiB': _secureDatabasePolicy.argonMemoryKiB,
                'iterations': _secureDatabasePolicy.argonIterations,
                'parallelism': _secureDatabasePolicy.argonParallelism,
                'length': 32,
              }
            : <String, Object?>{'algorithm': 'platform-secure-storage'},
        'activeDataKeyId': 1,
        'rotationPending': false,
        'createdAt': DateTime.now().toUtc().toIso8601String(),
      };

      if (passwordRequired) {
        authKey = await _secureDatabaseDeriveArgon2(
          password: password,
          salt: salt,
          memoryKiB: _secureDatabasePolicy.argonMemoryKiB,
          iterations: _secureDatabasePolicy.argonIterations,
          parallelism: _secureDatabasePolicy.argonParallelism,
        );
      } else {
        authKey = _secureDatabaseRandomBytes(32);
        try {
          await _secureDatabaseDeviceKeyStore.write(
            _secureDatabaseDeviceStorageKey(vaultId),
            base64Encode(authKey),
          );
          deviceKeyWritten = true;
        } catch (error) {
          throw NazaVaultException(
            'secure_storage_unavailable',
            'Boot-password bypass requires the operating system secure key store.',
            error,
          );
        }
      }

      vaultKey = _secureDatabaseRandomBytes(32);
      dataKey = _secureDatabaseRandomBytes(32);
      header['wrappedVaultKey'] = await _secureDatabaseSeal(
        vaultKey,
        authKey,
        _secureDatabaseVaultKeyAad(header),
      );
      header['wrappedDataKeys'] = <Object?>[
        {
          'id': 1,
          'createdAt': DateTime.now().toUtc().toIso8601String(),
          'envelope': await _secureDatabaseSeal(
            dataKey,
            vaultKey,
            _secureDatabaseDataKeyAad(vaultId, 1),
          ),
        },
      ];
      header[_secureDatabaseHeaderAuthenticationField] =
          await _secureDatabaseHeaderAuthentication(header, vaultKey);

      _secureDatabaseHeader = header;
      _secureDatabaseVaultUnlockKey = Uint8List.fromList(vaultKey);
      _secureDatabaseIndexKey = await _secureDatabaseDeriveIndexKey(
        vaultKey,
        vaultId,
      );
      _secureDatabaseDataKeys[1] = Uint8List.fromList(dataKey);
      _secureDatabaseActiveDataKeyId = 1;

      db = sqlite.sqlite3.open(databasePart.path);
      _secureDatabaseConfigureAndCreateSchema(db);
      await _secureDatabaseWriteJsonNow(
        _secureDatabaseSentinelNamespace,
        _secureDatabaseSentinelKey,
        {'vaultId': vaultId, 'format': _secureDatabaseVaultFormat},
        database: db,
      );
      for (final entry in initialRecords.entries) {
        await _secureDatabaseWriteJsonNow(
          entry.key.namespace,
          entry.key.key,
          entry.value,
          database: db,
        );
      }
      final check = db.select('PRAGMA integrity_check').first.columnAt(0);
      if (check != 'ok') {
        throw NazaVaultException(
          'database_integrity',
          'The new SQLite vault failed its integrity check: $check',
        );
      }
      db.execute('PRAGMA wal_checkpoint(TRUNCATE)');
      db.close();
      db = null;

      await databasePart.rename(databaseFile.path);
      await _secureDatabaseHarden(databaseFile);
      await _secureDatabaseWriteHeader(headerFile, header);
      await _secureDatabaseOpenAndVerify(header);
    } catch (_) {
      db?.close();
      await _secureDatabaseLockNow();
      if (await databasePart.exists()) await databasePart.delete();
      if (!await headerFile.exists() && await databaseFile.exists()) {
        await databaseFile.delete();
      }
      if (deviceKeyWritten) {
        try {
          if (createdVaultId != null) {
            await _secureDatabaseDeviceKeyStore.delete(
              _secureDatabaseDeviceStorageKey(createdVaultId),
            );
          }
        } catch (_) {}
      }
      rethrow;
    } finally {
      _secureDatabaseZero(authKey);
      _secureDatabaseZero(vaultKey);
      _secureDatabaseZero(dataKey);
    }
  }

  Future<void> _secureDatabaseUnlockNow({String? password}) async {
    await _secureDatabaseLockNow();
    final headerFile = await _secureDatabaseHeaderFile();
    if (!await headerFile.exists()) {
      throw const NazaVaultException(
        'setup_required',
        'Create the encrypted vault before unlocking it.',
      );
    }
    final header = await _secureDatabaseReadHeader(headerFile);
    final passwordRequired = header['passwordRequired'] != false;
    Uint8List? authKey;
    Uint8List? vaultKey;
    try {
      if (passwordRequired) {
        if (password == null || password.isEmpty) {
          throw const NazaVaultException(
            'password_required',
            'Enter the startup password.',
          );
        }
        authKey = await _secureDatabasePasswordKey(password, header);
      } else {
        final vaultId = header['vaultId']?.toString() ?? '';
        try {
          final encoded = await _secureDatabaseDeviceKeyStore.read(
            _secureDatabaseDeviceStorageKey(vaultId),
          );
          if (encoded == null) {
            throw const FormatException('Device unlock key is missing.');
          }
          authKey = Uint8List.fromList(base64Decode(encoded));
        } catch (error) {
          throw NazaVaultException(
            'secure_storage_unavailable',
            'The operating system secure key store could not unlock this vault.',
            error,
          );
        }
      }
      if (authKey.length != 32) {
        throw const NazaVaultException(
          'invalid_key',
          'The vault unlock key has an invalid length.',
        );
      }
      vaultKey = await _secureDatabaseUnwrapVaultKey(header, authKey);
      final dataKeys = await _secureDatabaseUnwrapDataKeys(header, vaultKey);
      final activeId = _secureDatabaseIntValue(header['activeDataKeyId']);
      if (!dataKeys.containsKey(activeId)) {
        throw const NazaVaultException(
          'invalid_header',
          'The active data key is missing from the vault header.',
        );
      }
      await _secureDatabaseVerifyOrMigrateHeaderAuthentication(
        headerFile,
        header,
        vaultKey,
        dataKeys,
        activeId,
      );
      _secureDatabaseHeader = header;
      _secureDatabaseVaultUnlockKey = Uint8List.fromList(vaultKey);
      _secureDatabaseIndexKey = await _secureDatabaseDeriveIndexKey(
        vaultKey,
        header['vaultId'].toString(),
      );
      _secureDatabaseDataKeys.addAll(dataKeys);
      _secureDatabaseActiveDataKeyId = activeId;
      await _secureDatabaseOpenAndVerify(header);
      if (header['rotationPending'] == true) {
        await _secureDatabaseResumeRotation();
      }
    } on SecretBoxAuthenticationError catch (error) {
      await _secureDatabaseLockNow();
      throw NazaVaultException(
        'authentication_failed',
        passwordRequired
            ? 'The startup password is incorrect.'
            : 'The device unlock key could not authenticate the vault.',
        error,
      );
    } on FormatException catch (error) {
      await _secureDatabaseLockNow();
      throw NazaVaultException(
        'invalid_header',
        'The vault header is malformed.',
        error,
      );
    } catch (_) {
      await _secureDatabaseLockNow();
      rethrow;
    } finally {
      _secureDatabaseZero(authKey);
      _secureDatabaseZero(vaultKey);
    }
  }

  Future<void> _secureDatabaseOpenAndVerify(Map<String, Object?> header) async {
    final file = await _secureDatabaseDatabaseFile();
    if (!await file.exists()) {
      throw const NazaVaultException(
        'database_missing',
        'The encrypted SQLite vault is missing.',
      );
    }
    final db = sqlite.sqlite3.open(file.path);
    try {
      _secureDatabaseConfigureConnection(db);
      if (db.userVersion != 3) {
        throw NazaVaultException(
          'database_version',
          'Unsupported vault database version ${db.userVersion}.',
        );
      }
      _secureDatabaseDatabase = db;
      final sentinel = await _secureDatabaseReadJsonNow(
        _secureDatabaseSentinelNamespace,
        _secureDatabaseSentinelKey,
      );
      if (sentinel is! Map || sentinel['vaultId'] != header['vaultId']) {
        throw const NazaVaultException(
          'sentinel_mismatch',
          'The vault header and encrypted database do not belong together.',
        );
      }
    } catch (_) {
      if (identical(_secureDatabaseDatabase, db))
        _secureDatabaseDatabase = null;
      db.close();
      rethrow;
    }
  }

  Future<Object?> _secureDatabaseReadJsonNow(
    String namespace,
    String key,
  ) async {
    final db = _secureDatabaseRequireDatabase();
    final recordId = await _secureDatabaseRecordId(namespace, key);
    final rows = db.select(
      'SELECT key_id, nonce, cipher_text, mac FROM vault_records '
      'WHERE record_id = ?',
      [recordId],
    );
    if (rows.isEmpty) return null;
    return _secureDatabaseDecryptRecord(rows.single, recordId, namespace, key);
  }

  Future<void> _secureDatabaseWriteJsonNow(
    String namespace,
    String key,
    Object? value, {
    sqlite.Database? database,
  }) async {
    _secureDatabaseValidateLogicalKey(namespace, 'namespace');
    _secureDatabaseValidateLogicalKey(key, 'key');
    final db = database ?? _secureDatabaseRequireDatabase();
    final keyId = _secureDatabaseActiveDataKeyId;
    final dataKey = keyId == null ? null : _secureDatabaseDataKeys[keyId];
    if (keyId == null || dataKey == null) {
      throw const NazaVaultException('locked', 'The vault is locked.');
    }
    final recordId = await _secureDatabaseRecordId(namespace, key);
    final clear = Uint8List.fromList(
      utf8.encode(
        jsonEncode({'namespace': namespace, 'key': key, 'value': value}),
      ),
    );
    try {
      final box = await _secureDatabaseAes.encrypt(
        clear,
        secretKey: SecretKey(dataKey),
        aad: _secureDatabaseRecordAad(recordId, keyId),
      );
      db.execute(
        'INSERT INTO vault_records '
        '(record_id, key_id, nonce, cipher_text, mac, updated_at) '
        'VALUES (?, ?, ?, ?, ?, ?) '
        'ON CONFLICT(record_id) DO UPDATE SET '
        'key_id=excluded.key_id, nonce=excluded.nonce, '
        'cipher_text=excluded.cipher_text, mac=excluded.mac, '
        'updated_at=excluded.updated_at',
        [
          recordId,
          keyId,
          Uint8List.fromList(box.nonce),
          Uint8List.fromList(box.cipherText),
          Uint8List.fromList(box.mac.bytes),
          DateTime.now().toUtc().millisecondsSinceEpoch,
        ],
      );
    } finally {
      _secureDatabaseZero(clear);
    }
  }

  Future<Object?> _secureDatabaseDecryptRecord(
    sqlite.Row row,
    Uint8List recordId,
    String expectedNamespace,
    String expectedKey,
  ) async {
    final keyId = _secureDatabaseIntValue(row['key_id']);
    final dataKey = _secureDatabaseDataKeys[keyId];
    if (dataKey == null) {
      throw NazaVaultException(
        'missing_data_key',
        'Encrypted record references unavailable key $keyId.',
      );
    }
    Uint8List? clear;
    try {
      clear = Uint8List.fromList(
        await _secureDatabaseAes.decrypt(
          SecretBox(
            List<int>.from(row['cipher_text'] as Uint8List),
            nonce: List<int>.from(row['nonce'] as Uint8List),
            mac: Mac(List<int>.from(row['mac'] as Uint8List)),
          ),
          secretKey: SecretKey(dataKey),
          aad: _secureDatabaseRecordAad(recordId, keyId),
        ),
      );
      final decoded = jsonDecode(utf8.decode(clear));
      if (decoded is! Map ||
          decoded['namespace'] != expectedNamespace ||
          decoded['key'] != expectedKey) {
        throw const NazaVaultException(
          'record_identity',
          'An encrypted record was substituted into the wrong vault slot.',
        );
      }
      return decoded['value'];
    } on SecretBoxAuthenticationError catch (error) {
      throw NazaVaultException(
        'record_authentication',
        'Encrypted vault record authentication failed.',
        error,
      );
    } finally {
      _secureDatabaseZero(clear);
    }
  }

  Future<Map<NazaVaultRecordKey, Object?>>
  _secureDatabaseExportRecordsNow() async {
    const maxExportRecords = 10000;
    const maxExportPlaintextBytes = 64 * 1024 * 1024;
    final db = _secureDatabaseRequireDatabase();
    final rows = db.select(
      'SELECT record_id, key_id, nonce, cipher_text, mac FROM vault_records LIMIT 10001',
    );
    final result = <NazaVaultRecordKey, Object?>{};
    var plaintextBytes = 0;
    for (final row in rows) {
      if (result.length >= maxExportRecords) {
        throw const NazaVaultException(
          'export_budget_exceeded',
          'Vault export exceeds the safe record-count budget.',
        );
      }
      final recordId = Uint8List.fromList(row['record_id'] as Uint8List);
      final keyId = _secureDatabaseIntValue(row['key_id']);
      final dataKey = _secureDatabaseDataKeys[keyId];
      if (dataKey == null) {
        throw NazaVaultException(
          'missing_data_key',
          'Encrypted record references unavailable key $keyId.',
        );
      }
      Uint8List? clear;
      try {
        clear = Uint8List.fromList(
          await _secureDatabaseAes.decrypt(
            SecretBox(
              List<int>.from(row['cipher_text'] as Uint8List),
              nonce: List<int>.from(row['nonce'] as Uint8List),
              mac: Mac(List<int>.from(row['mac'] as Uint8List)),
            ),
            secretKey: SecretKey(dataKey),
            aad: _secureDatabaseRecordAad(recordId, keyId),
          ),
        );
        final decoded = jsonDecode(utf8.decode(clear));
        plaintextBytes += clear.length;
        if (plaintextBytes > maxExportPlaintextBytes) {
          throw const NazaVaultException(
            'export_budget_exceeded',
            'Vault export exceeds the safe plaintext-memory budget.',
          );
        }
        if (decoded is! Map) {
          throw const NazaVaultException(
            'invalid_record',
            'An encrypted vault record is malformed.',
          );
        }
        final namespace = decoded['namespace']?.toString() ?? '';
        final key = decoded['key']?.toString() ?? '';
        if (namespace == _secureDatabaseSentinelNamespace) continue;
        final expectedId = await _secureDatabaseRecordId(namespace, key);
        if (!_secureDatabaseConstantTimeEquals(recordId, expectedId)) {
          throw const NazaVaultException(
            'record_identity',
            'An encrypted record identifier failed validation.',
          );
        }
        result[NazaVaultRecordKey(namespace, key)] = decoded['value'];
      } on SecretBoxAuthenticationError catch (error) {
        throw NazaVaultException(
          'record_authentication',
          'Encrypted vault record authentication failed.',
          error,
        );
      } finally {
        _secureDatabaseZero(clear);
      }
    }
    return result;
  }

  Future<void> _secureDatabaseChangeUnlockNow({
    required String newPassword,
    required bool passwordRequired,
  }) async {
    final vaultKey = _secureDatabaseRequireVaultKey();
    final header = Map<String, Object?>.from(_secureDatabaseRequireHeader());
    if (passwordRequired) _secureDatabaseValidateNewPassword(newPassword);
    final oldPasswordRequired = header['passwordRequired'] != false;
    if (!passwordRequired && !oldPasswordRequired) return;
    final vaultId = header['vaultId'].toString();
    Uint8List? authKey;
    var deviceKeyWritten = false;
    try {
      header['generation'] = _secureDatabaseIntValue(header['generation']) + 1;
      header['passwordRequired'] = passwordRequired;
      if (passwordRequired) {
        final salt = _secureDatabaseRandomBytes(16);
        header['kdf'] = <String, Object?>{
          'algorithm': 'Argon2id-1.3',
          'salt': base64Encode(salt),
          'memoryKiB': _secureDatabasePolicy.argonMemoryKiB,
          'iterations': _secureDatabasePolicy.argonIterations,
          'parallelism': _secureDatabasePolicy.argonParallelism,
          'length': 32,
        };
        authKey = await _secureDatabaseDeriveArgon2(
          password: newPassword,
          salt: salt,
          memoryKiB: _secureDatabasePolicy.argonMemoryKiB,
          iterations: _secureDatabasePolicy.argonIterations,
          parallelism: _secureDatabasePolicy.argonParallelism,
        );
      } else {
        authKey = _secureDatabaseRandomBytes(32);
        try {
          await _secureDatabaseDeviceKeyStore.write(
            _secureDatabaseDeviceStorageKey(vaultId),
            base64Encode(authKey),
          );
          deviceKeyWritten = true;
        } catch (error) {
          throw NazaVaultException(
            'secure_storage_unavailable',
            'The operating system secure key store is unavailable; the startup password remains enabled.',
            error,
          );
        }
        header['kdf'] = <String, Object?>{
          'algorithm': 'platform-secure-storage',
        };
      }
      header['wrappedVaultKey'] = await _secureDatabaseSeal(
        vaultKey,
        authKey,
        _secureDatabaseVaultKeyAad(header),
      );
      header['updatedAt'] = DateTime.now().toUtc().toIso8601String();
      header[_secureDatabaseHeaderAuthenticationField] =
          await _secureDatabaseHeaderAuthentication(header, vaultKey);
      await _secureDatabaseWriteHeader(
        await _secureDatabaseHeaderFile(),
        header,
      );
      _secureDatabaseHeader = header;
      if (passwordRequired && !oldPasswordRequired) {
        await _secureDatabaseDeviceKeyStore.delete(
          _secureDatabaseDeviceStorageKey(vaultId),
        );
      }
    } catch (_) {
      if (deviceKeyWritten && oldPasswordRequired) {
        try {
          await _secureDatabaseDeviceKeyStore.delete(
            _secureDatabaseDeviceStorageKey(vaultId),
          );
        } catch (_) {}
      }
      rethrow;
    } finally {
      _secureDatabaseZero(authKey);
    }
  }

  Future<void> _secureDatabaseRotateDataKeyNow() async {
    final header = Map<String, Object?>.from(_secureDatabaseRequireHeader());
    final vaultKey = _secureDatabaseRequireVaultKey();
    final db = _secureDatabaseRequireDatabase();
    final oldIds = _secureDatabaseDataKeys.keys.toList(growable: false);
    final nextId = oldIds.isEmpty ? 1 : oldIds.reduce(math.max) + 1;
    final nextKey = _secureDatabaseRandomBytes(32);
    try {
      final wrapped = List<Object?>.from(
        (header['wrappedDataKeys'] as List?) ?? const [],
      );
      wrapped.add({
        'id': nextId,
        'createdAt': DateTime.now().toUtc().toIso8601String(),
        'envelope': await _secureDatabaseSeal(
          nextKey,
          vaultKey,
          _secureDatabaseDataKeyAad(header['vaultId'].toString(), nextId),
        ),
      });
      header['wrappedDataKeys'] = wrapped;
      header['activeDataKeyId'] = nextId;
      header['rotationPending'] = true;
      header['generation'] = _secureDatabaseIntValue(header['generation']) + 1;
      header['updatedAt'] = DateTime.now().toUtc().toIso8601String();
      header[_secureDatabaseHeaderAuthenticationField] =
          await _secureDatabaseHeaderAuthentication(header, vaultKey);
      await _secureDatabaseWriteHeader(
        await _secureDatabaseHeaderFile(),
        header,
      );
      _secureDatabaseHeader = header;
      _secureDatabaseDataKeys[nextId] = Uint8List.fromList(nextKey);
      _secureDatabaseActiveDataKeyId = nextId;

      db.execute('BEGIN IMMEDIATE');
      try {
        final rows = db.select(
          'SELECT record_id, key_id, nonce, cipher_text, mac '
          'FROM vault_records WHERE key_id != ?',
          [nextId],
        );
        for (final row in rows) {
          await _secureDatabaseReencryptRow(db, row, nextId, nextKey);
        }
        db.execute('COMMIT');
      } catch (_) {
        db.execute('ROLLBACK');
        rethrow;
      }
      await _secureDatabaseFinalizeRotation();
    } finally {
      _secureDatabaseZero(nextKey);
    }
  }

  Future<void> _secureDatabaseResumeRotation() async {
    final activeId = _secureDatabaseActiveDataKeyId;
    final activeKey = activeId == null
        ? null
        : _secureDatabaseDataKeys[activeId];
    if (activeId == null || activeKey == null) {
      throw const NazaVaultException(
        'rotation_state',
        'Vault rotation metadata is incomplete.',
      );
    }
    final db = _secureDatabaseRequireDatabase();
    db.execute('BEGIN IMMEDIATE');
    try {
      final rows = db.select(
        'SELECT record_id, key_id, nonce, cipher_text, mac '
        'FROM vault_records WHERE key_id != ?',
        [activeId],
      );
      for (final row in rows) {
        await _secureDatabaseReencryptRow(db, row, activeId, activeKey);
      }
      db.execute('COMMIT');
    } catch (_) {
      db.execute('ROLLBACK');
      rethrow;
    }
    await _secureDatabaseFinalizeRotation();
  }

  Future<void> _secureDatabaseReencryptRow(
    sqlite.Database db,
    sqlite.Row row,
    int nextId,
    Uint8List nextKey,
  ) async {
    final recordId = Uint8List.fromList(row['record_id'] as Uint8List);
    final oldId = _secureDatabaseIntValue(row['key_id']);
    final oldKey = _secureDatabaseDataKeys[oldId];
    if (oldKey == null) {
      throw NazaVaultException(
        'missing_data_key',
        'Cannot rotate record encrypted with missing key $oldId.',
      );
    }
    Uint8List? clear;
    try {
      clear = Uint8List.fromList(
        await _secureDatabaseAes.decrypt(
          SecretBox(
            List<int>.from(row['cipher_text'] as Uint8List),
            nonce: List<int>.from(row['nonce'] as Uint8List),
            mac: Mac(List<int>.from(row['mac'] as Uint8List)),
          ),
          secretKey: SecretKey(oldKey),
          aad: _secureDatabaseRecordAad(recordId, oldId),
        ),
      );
      final box = await _secureDatabaseAes.encrypt(
        clear,
        secretKey: SecretKey(nextKey),
        aad: _secureDatabaseRecordAad(recordId, nextId),
      );
      db.execute(
        'UPDATE vault_records SET key_id=?, nonce=?, cipher_text=?, mac=?, '
        'updated_at=? WHERE record_id=?',
        [
          nextId,
          Uint8List.fromList(box.nonce),
          Uint8List.fromList(box.cipherText),
          Uint8List.fromList(box.mac.bytes),
          DateTime.now().toUtc().millisecondsSinceEpoch,
          recordId,
        ],
      );
    } finally {
      _secureDatabaseZero(clear);
    }
  }

  Future<void> _secureDatabaseFinalizeRotation() async {
    final db = _secureDatabaseRequireDatabase();
    final activeId = _secureDatabaseActiveDataKeyId!;
    final remaining = db.select(
      'SELECT COUNT(*) AS count FROM vault_records WHERE key_id != ?',
      [activeId],
    ).single['count'];
    if (_secureDatabaseIntValue(remaining) != 0) {
      throw const NazaVaultException(
        'rotation_incomplete',
        'Old encrypted records remain after data-key rotation.',
      );
    }
    final header = Map<String, Object?>.from(_secureDatabaseRequireHeader());
    final wrapped = ((header['wrappedDataKeys'] as List?) ?? const [])
        .whereType<Map>()
        .where((entry) => _secureDatabaseIntValue(entry['id']) == activeId)
        .map((entry) => Map<String, Object?>.from(entry))
        .toList(growable: false);
    if (wrapped.length != 1) {
      throw const NazaVaultException(
        'rotation_state',
        'The active wrapped data key is missing or duplicated.',
      );
    }
    header['wrappedDataKeys'] = wrapped;
    header['rotationPending'] = false;
    header['updatedAt'] = DateTime.now().toUtc().toIso8601String();
    header[_secureDatabaseHeaderAuthenticationField] =
        await _secureDatabaseHeaderAuthentication(
          header,
          _secureDatabaseRequireVaultKey(),
        );
    await _secureDatabaseWriteHeader(await _secureDatabaseHeaderFile(), header);
    for (final id in _secureDatabaseDataKeys.keys.toList()) {
      if (id == activeId) continue;
      _secureDatabaseZero(_secureDatabaseDataKeys.remove(id));
    }
    _secureDatabaseHeader = header;
  }

  Future<Uint8List> _secureDatabaseRecordId(
    String namespace,
    String key,
  ) async {
    _secureDatabaseValidateLogicalKey(namespace, 'namespace');
    _secureDatabaseValidateLogicalKey(key, 'key');
    final indexKey = _secureDatabaseIndexKey;
    if (indexKey == null) {
      throw const NazaVaultException('locked', 'The vault is locked.');
    }
    final mac = await _secureDatabaseHmac.calculateMac(
      utf8.encode('$_secureDatabaseVaultFormat\u001f$namespace\u001f$key'),
      secretKey: SecretKey(indexKey),
    );
    return Uint8List.fromList(mac.bytes);
  }

  Future<Uint8List> _secureDatabaseDeriveIndexKey(
    List<int> vaultKey,
    String vaultId,
  ) async {
    final key = await _secureDatabaseHkdf.deriveKey(
      secretKey: SecretKey(vaultKey),
      nonce: utf8.encode(vaultId),
      info: utf8.encode('$_secureDatabaseVaultFormat/index-key'),
    );
    return Uint8List.fromList(await key.extractBytes());
  }

  Future<Uint8List> _secureDatabasePasswordKey(
    String password,
    Map<String, Object?> header,
  ) async {
    _secureDatabaseValidatePasswordInput(password);
    final kdf = header['kdf'];
    if (kdf is! Map || kdf['algorithm'] != 'Argon2id-1.3') {
      throw const FormatException('Unsupported password KDF.');
    }
    return _secureDatabaseDeriveArgon2(
      password: password,
      salt: Uint8List.fromList(base64Decode(kdf['salt'].toString())),
      memoryKiB: _secureDatabaseIntValue(kdf['memoryKiB']),
      iterations: _secureDatabaseIntValue(kdf['iterations']),
      parallelism: _secureDatabaseIntValue(kdf['parallelism']),
    );
  }

  Future<Uint8List> _secureDatabaseUnwrapVaultKey(
    Map<String, Object?> header,
    List<int> authKey,
  ) async {
    final envelope = header['wrappedVaultKey'];
    if (envelope is! Map) throw const FormatException('Missing wrapped VUK.');
    final clear = await _secureDatabaseOpenEnvelope(
      Map<String, Object?>.from(envelope),
      authKey,
      _secureDatabaseVaultKeyAad(header),
    );
    if (clear.length != 32) throw const FormatException('Invalid VUK length.');
    return clear;
  }

  Future<Map<int, Uint8List>> _secureDatabaseUnwrapDataKeys(
    Map<String, Object?> header,
    List<int> vaultKey,
  ) async {
    final raw = header['wrappedDataKeys'];
    if (raw is! List || raw.isEmpty) {
      throw const FormatException('Missing wrapped data keys.');
    }
    final vaultId = header['vaultId'].toString();
    final result = <int, Uint8List>{};
    try {
      for (final item in raw) {
        if (item is! Map || item['envelope'] is! Map) {
          throw const FormatException('Malformed wrapped data key.');
        }
        final id = _secureDatabaseIntValue(item['id']);
        if (id < 1) throw const FormatException('Invalid data key ID.');
        final clear = await _secureDatabaseOpenEnvelope(
          Map<String, Object?>.from(item['envelope'] as Map),
          vaultKey,
          _secureDatabaseDataKeyAad(vaultId, id),
        );
        if (clear.length != 32 || result.containsKey(id)) {
          _secureDatabaseZero(clear);
          throw const FormatException('Invalid or duplicate data key.');
        }
        result[id] = clear;
      }
      return result;
    } catch (_) {
      for (final key in result.values) {
        _secureDatabaseZero(key);
      }
      rethrow;
    }
  }

  Future<Map<String, Object?>> _secureDatabaseSeal(
    List<int> clear,
    List<int> key,
    List<int> aad,
  ) async {
    final box = await _secureDatabaseAes.encrypt(
      clear,
      secretKey: SecretKey(key),
      aad: aad,
    );
    return {
      'cipher': 'AES-256-GCM',
      'nonce': base64Encode(box.nonce),
      'cipherText': base64Encode(box.cipherText),
      'mac': base64Encode(box.mac.bytes),
    };
  }

  Future<Uint8List> _secureDatabaseOpenEnvelope(
    Map<String, Object?> envelope,
    List<int> key,
    List<int> aad,
  ) async {
    if (envelope['cipher'] != 'AES-256-GCM') {
      throw const FormatException('Unsupported vault cipher.');
    }
    final clear = await _secureDatabaseAes.decrypt(
      SecretBox(
        base64Decode(envelope['cipherText'].toString()),
        nonce: base64Decode(envelope['nonce'].toString()),
        mac: Mac(base64Decode(envelope['mac'].toString())),
      ),
      secretKey: SecretKey(key),
      aad: aad,
    );
    return Uint8List.fromList(clear);
  }

  List<int> _secureDatabaseVaultKeyAad(Map<String, Object?> header) {
    final kdf = header['kdf'];
    final normalizedKdf = kdf is Map
        ? Map<String, Object?>.from(kdf)
        : const <String, Object?>{};
    return utf8.encode(
      jsonEncode({
        'format': _secureDatabaseVaultFormat,
        'version': header['version'],
        'vaultId': header['vaultId'],
        'passwordRequired': header['passwordRequired'],
        'kdf': normalizedKdf,
      }),
    );
  }

  List<int> _secureDatabaseDataKeyAad(String vaultId, int keyId) {
    return utf8.encode('$_secureDatabaseVaultFormat/$vaultId/data-key/$keyId');
  }

  List<int> _secureDatabaseRecordAad(Uint8List recordId, int keyId) {
    return utf8.encode(
      '$_secureDatabaseVaultFormat/record/$keyId/${base64UrlEncode(recordId)}',
    );
  }

  Future<void> _secureDatabaseVerifyOrMigrateHeaderAuthentication(
    File headerFile,
    Map<String, Object?> header,
    Uint8List vaultKey,
    Map<int, Uint8List> dataKeys,
    int activeId,
  ) async {
    final encoded = header[_secureDatabaseHeaderAuthenticationField];
    if (encoded == null) {
      _secureDatabaseValidateLegacyRotationState(
        header,
        dataKeys.keys,
        activeId,
      );
      header['updatedAt'] = DateTime.now().toUtc().toIso8601String();
      header[_secureDatabaseHeaderAuthenticationField] =
          await _secureDatabaseHeaderAuthentication(header, vaultKey);
      await _secureDatabaseWriteHeader(headerFile, header);
      return;
    }
    Uint8List? supplied;
    try {
      supplied = Uint8List.fromList(base64Decode(encoded.toString()));
    } catch (error) {
      throw NazaVaultException(
        'header_authentication',
        'The vault header authentication value is malformed.',
        error,
      );
    }
    final expected = await _secureDatabaseHeaderAuthenticationBytes(
      header,
      vaultKey,
    );
    try {
      if (supplied.length != 32 ||
          !_secureDatabaseConstantTimeEquals(supplied, expected)) {
        throw const NazaVaultException(
          'header_authentication',
          'The vault header security controls failed authentication.',
        );
      }
    } finally {
      _secureDatabaseZero(supplied);
      _secureDatabaseZero(expected);
    }
  }

  void _secureDatabaseValidateLegacyRotationState(
    Map<String, Object?> header,
    Iterable<int> unwrappedKeyIds,
    int activeId,
  ) {
    final ids = unwrappedKeyIds.toList()..sort();
    if (ids.isEmpty || !ids.contains(activeId)) {
      throw const NazaVaultException(
        'header_authentication',
        'The legacy vault header has invalid data-key controls.',
      );
    }
    if (header['rotationPending'] == true) {
      if (ids.length < 2 || activeId != ids.last) {
        throw const NazaVaultException(
          'header_authentication',
          'The legacy pending rotation does not select the newest data key.',
        );
      }
      return;
    }
    if (ids.length != 1 || activeId != ids.single) {
      throw const NazaVaultException(
        'header_authentication',
        'The legacy finalized header retains ambiguous data keys.',
      );
    }
  }

  Future<String> _secureDatabaseHeaderAuthentication(
    Map<String, Object?> header,
    List<int> vaultKey,
  ) async {
    final bytes = await _secureDatabaseHeaderAuthenticationBytes(
      header,
      vaultKey,
    );
    try {
      return base64Encode(bytes);
    } finally {
      _secureDatabaseZero(bytes);
    }
  }

  Future<Uint8List> _secureDatabaseHeaderAuthenticationBytes(
    Map<String, Object?> header,
    List<int> vaultKey,
  ) async {
    final vaultId = header['vaultId']?.toString() ?? '';
    final derived = await _secureDatabaseHkdf.deriveKey(
      secretKey: SecretKey(vaultKey),
      nonce: utf8.encode(vaultId),
      info: utf8.encode(
        '$_secureDatabaseVaultFormat/header-authentication-key/v1',
      ),
    );
    final key = Uint8List.fromList(await derived.extractBytes());
    try {
      final canonical = <String, Object?>{
        for (final entry in header.entries)
          if (entry.key != _secureDatabaseHeaderAuthenticationField)
            entry.key: _secureDatabaseCanonicalJsonValue(entry.value),
      };
      final material = utf8.encode(
        '$_secureDatabaseHeaderAuthenticationFormat\u001f${jsonEncode(_secureDatabaseCanonicalJsonValue(canonical))}',
      );
      final mac = await _secureDatabaseHmac.calculateMac(
        material,
        secretKey: SecretKey(key),
      );
      return Uint8List.fromList(mac.bytes);
    } finally {
      _secureDatabaseZero(key);
    }
  }

  Object? _secureDatabaseCanonicalJsonValue(Object? value) {
    if (value == null || value is bool || value is num || value is String) {
      return value;
    }
    if (value is List) {
      return value
          .map(_secureDatabaseCanonicalJsonValue)
          .toList(growable: false);
    }
    if (value is Map) {
      final keys = value.keys.map((key) {
        if (key is! String) {
          throw const FormatException(
            'Vault header authentication requires string map keys.',
          );
        }
        return key;
      }).toList()..sort();
      return <String, Object?>{
        for (final key in keys)
          key: _secureDatabaseCanonicalJsonValue(value[key]),
      };
    }
    throw const FormatException(
      'Vault header authentication contains an unsupported value.',
    );
  }

  Future<Map<String, Object?>> _secureDatabaseReadHeader(File file) async {
    try {
      final stat = await file.stat();
      if (stat.size <= 0 || stat.size > _secureDatabaseMaxHeaderBytes) {
        throw const FormatException('Invalid vault header size.');
      }
      final decoded = jsonDecode(await file.readAsString());
      if (decoded is! Map) throw const FormatException('Header is not a map.');
      final header = Map<String, Object?>.from(decoded);
      if (header['format'] != _secureDatabaseVaultFormat ||
          header['version'] != 3) {
        throw const FormatException('Unsupported vault header version.');
      }
      final vaultId = header['vaultId']?.toString() ?? '';
      if (!RegExp(r'^[A-Za-z0-9_-]{16,64}$').hasMatch(vaultId)) {
        throw const FormatException('Invalid vault identifier.');
      }
      return header;
    } catch (error) {
      if (error is NazaVaultException) rethrow;
      throw NazaVaultException(
        'invalid_header',
        'The vault header is missing, corrupt, or unsupported.',
        error,
      );
    }
  }

  Future<void> _secureDatabaseWriteHeader(
    File file,
    Map<String, Object?> header,
  ) async {
    await _secureDatabaseAtomicWrite(
      file,
      const JsonEncoder.withIndent('  ').convert(header),
    );
    final verify = await _secureDatabaseReadHeader(file);
    if (verify['generation'] != header['generation'] ||
        verify['vaultId'] != header['vaultId']) {
      throw const NazaVaultException(
        'header_write',
        'The new vault header failed read-back verification.',
      );
    }
  }

  void _secureDatabaseConfigureAndCreateSchema(sqlite.Database db) {
    _secureDatabaseConfigureConnection(db);
    db.execute('''
CREATE TABLE IF NOT EXISTS vault_records (
  record_id BLOB PRIMARY KEY NOT NULL,
  key_id INTEGER NOT NULL,
  nonce BLOB NOT NULL CHECK(length(nonce) = 12),
  cipher_text BLOB NOT NULL,
  mac BLOB NOT NULL CHECK(length(mac) = 16),
  updated_at INTEGER NOT NULL
) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS vault_records_key_id ON vault_records(key_id);
''');
    db.userVersion = 3;
  }

  void _secureDatabaseConfigureConnection(sqlite.Database db) {
    db.execute('PRAGMA trusted_schema=OFF');
    db.execute('PRAGMA foreign_keys=ON');
    db.execute('PRAGMA secure_delete=ON');
    db.execute('PRAGMA journal_mode=WAL');
    db.execute('PRAGMA synchronous=FULL');
    db.execute('PRAGMA busy_timeout=5000');
  }

  Future<void> _secureDatabaseLockNow() async {
    final db = _secureDatabaseDatabase;
    _secureDatabaseDatabase = null;
    if (db != null) {
      try {
        db.execute('PRAGMA wal_checkpoint(TRUNCATE)');
      } catch (_) {}
      db.close();
    }
    _secureDatabaseHeader = null;
    _secureDatabaseZero(_secureDatabaseVaultUnlockKey);
    _secureDatabaseZero(_secureDatabaseIndexKey);
    _secureDatabaseVaultUnlockKey = null;
    _secureDatabaseIndexKey = null;
    for (final key in _secureDatabaseDataKeys.values) {
      _secureDatabaseZero(key);
    }
    _secureDatabaseDataKeys.clear();
    _secureDatabaseActiveDataKeyId = null;
  }

  sqlite.Database _secureDatabaseRequireDatabase() {
    final db = _secureDatabaseDatabase;
    if (db == null) {
      throw const NazaVaultException('locked', 'The vault is locked.');
    }
    return db;
  }

  Uint8List _secureDatabaseRequireVaultKey() {
    final key = _secureDatabaseVaultUnlockKey;
    if (key == null) {
      throw const NazaVaultException('locked', 'The vault is locked.');
    }
    return key;
  }

  Map<String, Object?> _secureDatabaseRequireHeader() {
    final header = _secureDatabaseHeader;
    if (header == null) {
      throw const NazaVaultException('locked', 'The vault is locked.');
    }
    return header;
  }

  void _secureDatabaseValidateNewPassword(String password) {
    final characters = password.runes.length;
    if (characters < _secureDatabasePolicy.minimumPasswordCharacters) {
      throw NazaVaultException(
        'weak_password',
        'Use at least ${_secureDatabasePolicy.minimumPasswordCharacters} characters.',
      );
    }
    if (characters > 1024) {
      throw const NazaVaultException(
        'password_too_long',
        'The startup password is too long.',
      );
    }
  }

  void _secureDatabaseValidatePasswordInput(String password) {
    final characters = password.runes.length;
    if (characters < 1 || characters > 1024) {
      throw const NazaVaultException(
        'invalid_password',
        'The startup password must contain 1-1024 characters.',
      );
    }
  }

  void _secureDatabaseValidatePolicy() {
    if (_secureDatabasePolicy.argonMemoryKiB < 64 ||
        _secureDatabasePolicy.argonMemoryKiB >
            _secureDatabaseMaxArgonMemoryKiB ||
        _secureDatabasePolicy.argonIterations < 1 ||
        _secureDatabasePolicy.argonIterations >
            _secureDatabaseMaxArgonIterations ||
        _secureDatabasePolicy.argonParallelism < 1 ||
        _secureDatabasePolicy.argonParallelism > 16 ||
        _secureDatabasePolicy.minimumPasswordCharacters < 1 ||
        _secureDatabasePolicy.minimumPasswordCharacters > 1024) {
      throw const NazaVaultException(
        'invalid_crypto_policy',
        'The vault cryptographic policy is outside supported safety limits.',
      );
    }
  }

  void _secureDatabaseValidatePublicRecordKey(String namespace, String key) {
    _secureDatabaseValidateLogicalKey(namespace, 'namespace');
    _secureDatabaseValidateLogicalKey(key, 'key');
    if (namespace == _secureDatabaseSentinelNamespace) {
      throw ArgumentError.value(
        namespace,
        'namespace',
        'The vault system namespace is reserved.',
      );
    }
  }

  void _secureDatabaseValidateLogicalKey(String value, String label) {
    if (value.isEmpty ||
        value.length > 240 ||
        value.contains('\u0000') ||
        value.contains(_secureDatabaseRecordIdSeparator)) {
      throw ArgumentError.value(value, label, 'Invalid vault record $label.');
    }
  }

  Future<bool> _secureDatabaseLegacyDataPresent() async {
    final directory = await _secureDatabaseDirectoryProvider();
    const names = [
      'naza_one_vault.key',
      'naza_one_history.aesgcm.json',
      'naza_scanner_drafts.sqlite.aesgcm.json',
      'naza_one_vector_memory.aesgcm.json',
      'naza_verification_state.aesgcm.json',
      'naza_generation_settings.sqlite.aesgcm.json',
    ];
    for (final name in names) {
      if (await File('${directory.path}/$name').exists()) return true;
    }
    return false;
  }

  Future<File> _secureDatabaseDatabaseFile() async {
    final directory = await _secureDatabaseDirectoryProvider();
    return File('${directory.path}/$_secureDatabaseDatabaseFileName');
  }

  Future<File> _secureDatabaseHeaderFile() async {
    final directory = await _secureDatabaseDirectoryProvider();
    return File('${directory.path}/$_secureDatabaseHeaderFileName');
  }

  String _secureDatabaseDeviceStorageKey(String vaultId) =>
      '$_secureDatabaseDeviceKeyName-$vaultId';

  Uint8List _secureDatabaseRandomBytes(int length) {
    final random = math.Random.secure();
    return Uint8List.fromList(
      List<int>.generate(length, (_) => random.nextInt(256)),
    );
  }

  int _secureDatabaseIntValue(Object? value) {
    if (value is int) return value;
    return int.tryParse(value?.toString() ?? '') ?? -1;
  }

  bool _secureDatabaseConstantTimeEquals(List<int> a, List<int> b) {
    var difference = a.length ^ b.length;
    final length = math.min(a.length, b.length);
    for (var i = 0; i < length; i++) {
      difference |= a[i] ^ b[i];
    }
    return difference == 0;
  }

  void _secureDatabaseZero(List<int>? bytes) {
    if (bytes == null) return;
    for (var i = 0; i < bytes.length; i++) {
      bytes[i] = 0;
    }
  }

  Future<void> _secureDatabaseAtomicWrite(File file, String contents) async {
    await file.parent.create(recursive: true);
    final part = File('${file.path}.new');
    if (await part.exists()) await part.delete();
    await part.writeAsString(contents, flush: true);
    await _secureDatabaseHarden(part);
    final backup = File('${file.path}.previous');
    if (await backup.exists()) await backup.delete();
    var movedOld = false;
    try {
      if (await file.exists()) {
        await file.rename(backup.path);
        movedOld = true;
      }
      await part.rename(file.path);
      if (movedOld && await backup.exists()) await backup.delete();
      await _secureDatabaseHarden(file);
    } catch (_) {
      if (await part.exists()) await part.delete();
      if (movedOld && !await file.exists() && await backup.exists()) {
        await backup.rename(file.path);
      }
      rethrow;
    }
  }

  Future<void> _secureDatabaseHarden(File file) async {
    if (Platform.isWindows || !await file.exists()) return;
    try {
      await Process.run('chmod', ['600', file.path]);
    } catch (_) {}
  }
}

Future<Uint8List> _secureDatabaseDeriveArgon2({
  required String password,
  required Uint8List salt,
  required int memoryKiB,
  required int iterations,
  required int parallelism,
}) async {
  if (salt.length < 16 ||
      memoryKiB < 64 ||
      memoryKiB > _secureDatabaseMaxArgonMemoryKiB ||
      iterations < 1 ||
      iterations > _secureDatabaseMaxArgonIterations ||
      parallelism < 1 ||
      parallelism > 16) {
    throw const FormatException('Unsafe Argon2id parameters.');
  }
  final passwordBytes = Uint8List.fromList(utf8.encode(password));
  try {
    final derived = await Isolate.run<List<int>>(() async {
      // This function already owns a dedicated worker isolate. The default
      // desktop Argon2 implementation would otherwise spawn another isolate
      // inside it, causing avoidable isolate-group startup/safepoint pauses in
      // debug builds. The KDF parameters and resulting bytes are unchanged.
      const noNestedWorkers = 0;
      const uninterruptedWorkerChunk = -1;
      final algorithm = DartArgon2id(
        parallelism: parallelism,
        memory: memoryKiB,
        iterations: iterations,
        hashLength: 32,
        maxIsolates: noNestedWorkers,
        blocksPerProcessingChunk: uninterruptedWorkerChunk,
      );
      final key = await algorithm.deriveKey(
        secretKey: SecretKey(passwordBytes),
        nonce: salt,
      );
      return key.extractBytes();
    });
    return Uint8List.fromList(derived);
  } finally {
    for (var i = 0; i < passwordBytes.length; i++) {
      passwordBytes[i] = 0;
    }
  }
}

