    'epoch': epoch,
    'modelIdentity': modelIdentity,
    'policyIdentity': policyIdentity,
    'recoveryGeneration': recoveryGeneration,
    'trustRootIdentity': trustRootIdentity,
    'vaultId': vaultId,
  };
}

enum NazaPrivilegedAction {
  readPrivateData,
  writePrivateData,
  exportVault,
  importVault,
  rotateKeys,
  changeAuthentication,
  changeRecovery,
  replaceModel,
  changeTrustRoot,
  eraseVault,
}

/// Single-purpose bearer capability bound to security state, use budget, and a
/// short authorization lifetime measured by a session-monotonic clock.
final class NazaCapabilityLease {
  final String id;
  final NazaPrivilegedAction action;
  final String resource;
  final int issuedEpoch;
  final String stateDigest;
  final int maxUses;
  final int issuedMonotonicCounter;
  final int issuedAtMicros;
  final int expiresAtMicros;

  int _securityKernelUses = 0;
  bool _securityKernelRevoked = false;

  NazaCapabilityLease._({
    required this.id,
    required this.action,
    required this.resource,
    required this.issuedEpoch,
    required this.stateDigest,
    required this.maxUses,
    required this.issuedMonotonicCounter,
    required this.issuedAtMicros,
    required this.expiresAtMicros,
  });

  int get uses => _securityKernelUses;
  bool get revoked => _securityKernelRevoked;
  bool get exhausted => _securityKernelUses >= maxUses;

  void revoke() => _securityKernelRevoked = true;
}

final class NazaSecurityKernel {
  NazaSecurityKernel({
    required List<int> capabilityKey,
    required NazaSecurityState initialState,
    int Function()? monotonicMicros,
  }) : _securityKernelCapabilityKey = Uint8List.fromList(capabilityKey),
       _securityKernelState = initialState,
       _securityKernelMonotonicMicros =
           monotonicMicros ?? _securityKernelNewMonotonicClock() {
    if (_securityKernelCapabilityKey.length != 32) {
      _securityKernelCapabilityKey.fillRange(
        0,
        _securityKernelCapabilityKey.length,
        0,
      );
      throw ArgumentError.value(
        capabilityKey.length,
        'capabilityKey',
        'must contain exactly 32 bytes',
      );
    }
  }

  final Uint8List _securityKernelCapabilityKey;
  final Hmac _securityKernelHmac = Hmac.sha256();
  final int Function() _securityKernelMonotonicMicros;
  NazaSecurityState _securityKernelState;
  int _securityKernelCounter = 0;
  final Map<String, NazaCapabilityLease> _securityKernelLeases =
      <String, NazaCapabilityLease>{};

  NazaSecurityState get state => _securityKernelState;

  Future<String> stateDigest() async {
    final bytes = utf8.encode(
      _securityKernelCanonicalJson(_securityKernelState.toCanonicalMap()),
    );
    final mac = await _securityKernelHmac.calculateMac(
      bytes,
      secretKey: SecretKey(_securityKernelCapabilityKey),
    );
    return base64UrlEncode(mac.bytes).replaceAll('=', '');
  }

  Future<NazaCapabilityLease> issueLease({
    required NazaPrivilegedAction action,
    required String resource,
    int maxUses = 1,
    Duration ttl = const Duration(seconds: 60),
  }) async {
    if (maxUses < 1 || maxUses > 1024) {
      throw ArgumentError.value(
        maxUses,
        'maxUses',
        'Use count must be 1-1024.',
      );
    }
    if (ttl < const Duration(seconds: 1) || ttl > const Duration(minutes: 5)) {
      throw ArgumentError.value(
        ttl,
        'ttl',
        'Capability lifetime must be between 1 second and 5 minutes.',
      );
    }
    _securityKernelCounter++;
    final digest = await stateDigest();
    final nonce = _securityKernelRandomBytes(16);
    final issuedAt = _securityKernelMonotonicMicros();
    final expiresAt = issuedAt + ttl.inMicroseconds;
    final material = utf8.encode(
      '${action.name}\u001f$resource\u001f${_securityKernelState.epoch}\u001f$_securityKernelCounter\u001f$issuedAt\u001f$expiresAt\u001f$digest',
    );
    final idMac = await _securityKernelHmac.calculateMac(<int>[
      ...nonce,
      ...material,
    ], secretKey: SecretKey(_securityKernelCapabilityKey));
    final id = base64UrlEncode(idMac.bytes).replaceAll('=', '');
    final lease = NazaCapabilityLease._(
      id: id,
      action: action,
      resource: resource,
      issuedEpoch: _securityKernelState.epoch,
      stateDigest: digest,
      maxUses: maxUses,
      issuedMonotonicCounter: _securityKernelCounter,
      issuedAtMicros: issuedAt,
      expiresAtMicros: expiresAt,
    );
    _securityKernelLeases[id] = lease;
    return lease;
  }

  Future<void> consumeLease(
    NazaCapabilityLease lease, {
    required NazaPrivilegedAction action,
    required String resource,
  }) async {
    final current = _securityKernelLeases[lease.id];
    if (!identical(current, lease) || lease.revoked) {
      throw const NazaSecurityException(
        'capability_invalid',
        'Capability is unknown or revoked.',
      );
    }
    final now = _securityKernelMonotonicMicros();
    if (now > lease.expiresAtMicros) {
      lease.revoke();
      _securityKernelLeases.remove(lease.id);
      throw const NazaSecurityException(
        'capability_expired',
        'Capability authorization has expired; authenticate again.',
      );
    }
    if (lease.exhausted) {
      throw const NazaSecurityException(
        'capability_exhausted',
        'Capability use budget is exhausted.',
      );
    }
    if (lease.action != action || lease.resource != resource) {
      throw const NazaSecurityException(
        'capability_scope',
        'Capability does not authorize this operation.',
      );
    }
    if (lease.issuedEpoch != _securityKernelState.epoch ||
        lease.stateDigest != await stateDigest()) {
      throw const NazaSecurityException(
        'capability_stale',
        'Capability was issued under a previous security state.',
      );
    }
    lease._securityKernelUses++;
    if (lease.exhausted) {
      lease.revoke();
      _securityKernelLeases.remove(lease.id);
    }
  }

  void transition(NazaSecurityState next) {
    if (next.epoch <= _securityKernelState.epoch) {
      throw const NazaSecurityException(
        'epoch_rollback',
        'Security epoch must increase monotonically.',
      );
    }
    _securityKernelState = next;
    revokeAll();
  }

  void revokeAll() {
    for (final lease in _securityKernelLeases.values) {
      lease.revoke();
    }
    _securityKernelLeases.clear();
  }

  void destroy() {
    revokeAll();
    _securityKernelZero(_securityKernelCapabilityKey);
  }
}

final class NazaForwardSecureAudit {
  NazaForwardSecureAudit({required List<int> initialKey})
    : _securityKernelKey = Uint8List.fromList(initialKey);

  final Hmac _securityKernelHmac = Hmac.sha256();
  Uint8List _securityKernelKey;
  int _securityKernelSequence = 0;
  String _securityKernelTip = 'GENESIS';

  int get sequence => _securityKernelSequence;
  String get tip => _securityKernelTip;

  Future<NazaAuditEntry> append({
    required String event,
    required Map<String, Object?> data,
    required int securityEpoch,
  }) async {
    if (event.isEmpty || event.length > 128) {
      throw ArgumentError.value(event, 'event', 'Invalid audit event name.');
    }
    final sequence = ++_securityKernelSequence;
    final body = <String, Object?>{
      'data': _securityKernelCanonicalize(data),
      'event': event,
      'previous': _securityKernelTip,
      'securityEpoch': securityEpoch,
      'sequence': sequence,
    };
    final encoded = utf8.encode(_securityKernelCanonicalJson(body));
    final mac = await _securityKernelHmac.calculateMac(
      encoded,
      secretKey: SecretKey(_securityKernelKey),
    );
    final macText = base64UrlEncode(mac.bytes).replaceAll('=', '');
    final entry = NazaAuditEntry(
      sequence: sequence,
      securityEpoch: securityEpoch,
      event: event,
      data: Map<String, Object?>.unmodifiable(data),
      previous: _securityKernelTip,
      mac: macText,
    );
    _securityKernelTip = await _securityKernelEntryDigest(entry);
    final nextKey = await _securityKernelRatchet(_securityKernelKey, sequence);
    _securityKernelZero(_securityKernelKey);
    _securityKernelKey = nextKey;
    return entry;
  }

  void destroy() {
    _securityKernelZero(_securityKernelKey);
  }

  Future<Uint8List> _securityKernelRatchet(List<int> key, int sequence) async {
    final mac = await _securityKernelHmac.calculateMac(
      utf8.encode('naza-forward-audit-v1/$sequence'),
      secretKey: SecretKey(key),
    );
    return Uint8List.fromList(mac.bytes);
  }

  Future<String> _securityKernelEntryDigest(NazaAuditEntry entry) async {
    final hash = await Sha256().hash(
      utf8.encode(_securityKernelCanonicalJson(entry.toCanonicalMap())),
    );
    return base64UrlEncode(hash.bytes).replaceAll('=', '');
  }
}

final class NazaAuditEntry {
  final int sequence;
  final int securityEpoch;
  final String event;
  final Map<String, Object?> data;
  final String previous;
  final String mac;

  const NazaAuditEntry({
    required this.sequence,
    required this.securityEpoch,
    required this.event,
    required this.data,
    required this.previous,
    required this.mac,
  });

  Map<String, Object?> toCanonicalMap() => <String, Object?>{
    'data': _securityKernelCanonicalize(data),
    'event': event,
    'mac': mac,
    'previous': previous,
    'securityEpoch': securityEpoch,
    'sequence': sequence,
  };
}

/// Legacy/simple counter guard retained for low-level tests and non-hardened
/// consumers. Hardened vaults use NazaAuthenticatedRollbackGuard instead.
final class NazaRollbackGuard {
  NazaRollbackGuard(this._securityKernelStore, {required this.storageKey});

  final NazaDeviceCounterStore _securityKernelStore;
  final String storageKey;

  Future<int> minimumEpoch() async {
    final raw = await _securityKernelStore.read(storageKey);
    if (raw == null || raw.isEmpty) return 0;
    final value = int.tryParse(raw);
    if (value == null || value < 0) {
      throw const NazaSecurityException(
        'rollback_state_corrupt',
        'Stored rollback state is malformed.',
      );
    }
    return value;
  }

  Future<void> verify(int candidateEpoch) async {
    final minimum = await minimumEpoch();
    if (candidateEpoch < minimum) {
      throw NazaSecurityException(
        'rollback_detected',
        'Vault epoch $candidateEpoch is older than protected epoch $minimum.',
      );
    }
  }

  Future<void> commit(int epoch) async {
    final current = await minimumEpoch();
    if (epoch < current) {
      throw const NazaSecurityException(
        'epoch_rollback',
        'Rollback guard cannot move backwards.',
      );
    }
    await _securityKernelStore.write(storageKey, epoch.toString());
  }
}

abstract interface class NazaDeviceCounterStore {
  Future<String?> read(String key);
  Future<void> write(String key, String value);
}

final class NazaMemoryCounterStore implements NazaDeviceCounterStore {
  final Map<String, String> _securityKernelValues = <String, String>{};

  @override
  Future<String?> read(String key) async => _securityKernelValues[key];

  @override
  Future<void> write(String key, String value) async {
    _securityKernelValues[key] = value;
  }
}

final class NazaSecurityException implements Exception {
  final String code;
  final String message;

  const NazaSecurityException(this.code, this.message);

  @override
  String toString() => 'NazaSecurityException($code): $message';
}

Object? _securityKernelCanonicalize(Object? value) {
  if (value is Map) {
    final keys = value.keys.map((key) => key.toString()).toList()..sort();
    return <String, Object?>{
      for (final key in keys) key: _securityKernelCanonicalize(value[key]),
    };
  }
  if (value is List) {
    return value
        .map<Object?>((item) => _securityKernelCanonicalize(item))
        .toList(growable: false);
  }
  if (value is num || value is bool || value is String || value == null) {
    return value;
  }
  return value.toString();
}

String _securityKernelCanonicalJson(Object? value) =>
    jsonEncode(_securityKernelCanonicalize(value));

Uint8List _securityKernelRandomBytes(int length) {
  final random = math.Random.secure();
  return Uint8List.fromList(
    List<int>.generate(length, (_) => random.nextInt(256)),
  );
}

int Function() _securityKernelNewMonotonicClock() {
  final stopwatch = Stopwatch()..start();
  return () => stopwatch.elapsedMicroseconds;
}

void _securityKernelZero(List<int>? bytes) {
  if (bytes == null) return;
  for (var i = 0; i < bytes.length; i++) {
    bytes[i] = 0;
  }
}

