/// Compact diagnostics card for proving which inference backend is active.
/// It deliberately does not infer GPU use from throughput; callers update the
/// telemetry only after model initialization succeeds or falls back.
final class NazaRuntimeBackendCard extends StatefulWidget {
  NazaRuntimeBackendCard({super.key, NazaRuntimeTelemetry? telemetry})
    : telemetry = telemetry ?? NazaRuntimeTelemetry.instance;

  final NazaRuntimeTelemetry telemetry;

  @override
  State<NazaRuntimeBackendCard> createState() =>
      _RuntimeBackendCardNazaRuntimeBackendCardState();
}

final class _RuntimeBackendCardNazaRuntimeBackendCardState
    extends State<NazaRuntimeBackendCard> {
  late NazaLiteRtRuntimeProfile _runtimeBackendCardProfile;

  @override
  void initState() {
    super.initState();
    _runtimeBackendCardProfile = widget.telemetry.profile;
    widget.telemetry.addListener(_runtimeBackendCardChanged);
  }

  @override
  void didUpdateWidget(covariant NazaRuntimeBackendCard oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!identical(oldWidget.telemetry, widget.telemetry)) {
      oldWidget.telemetry.removeListener(_runtimeBackendCardChanged);
      _runtimeBackendCardProfile = widget.telemetry.profile;
      widget.telemetry.addListener(_runtimeBackendCardChanged);
    }
  }

  @override
  void dispose() {
    widget.telemetry.removeListener(_runtimeBackendCardChanged);
    super.dispose();
  }

  void _runtimeBackendCardChanged(NazaLiteRtRuntimeProfile value) {
    if (mounted) setState(() => _runtimeBackendCardProfile = value);
  }

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final activeGpu = _runtimeBackendCardProfile.gpuConfirmed;
    final fallback = _runtimeBackendCardProfile.cpuFallback;
    final stateIcon = activeGpu
        ? Icons.bolt_rounded
        : fallback
        ? Icons.swap_horiz_rounded
        : Icons.memory_rounded;

    return Container(
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(22),
        color: scheme.surfaceContainerHighest.withValues(alpha: 0.42),
        border: Border.all(
          color: activeGpu
              ? scheme.primary.withValues(alpha: 0.38)
              : scheme.outlineVariant.withValues(alpha: 0.44),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Row(
            children: <Widget>[
              Container(
                width: 42,
                height: 42,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(13),
                  color: activeGpu
                      ? scheme.primaryContainer.withValues(alpha: 0.62)
                      : scheme.surfaceContainerHigh,
                ),
                child: Icon(
                  stateIcon,
                  color: activeGpu ? scheme.primary : null,
                ),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    Text(
                      'Inference Runtime',
                      style: Theme.of(context).textTheme.titleMedium?.copyWith(
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      _runtimeBackendCardProfile.compactLabel,
                      style: TextStyle(
                        color: activeGpu
                            ? scheme.primary
                            : scheme.onSurfaceVariant,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 14),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: <Widget>[
              _RuntimeBackendCardRuntimeChip(
                label: _runtimeBackendCardProfile.platform,
              ),
              _RuntimeBackendCardRuntimeChip(
                label: 'bridge ${_runtimeBackendCardProfile.dartBridge}',
              ),
              _RuntimeBackendCardRuntimeChip(
                label: 'native ${_runtimeBackendCardProfile.nativeRuntime}',
              ),
              if (_runtimeBackendCardProfile.windowsGpuNoCache)
                const _RuntimeBackendCardRuntimeChip(
                  label: 'GPU cache :nocache',
                ),
              _RuntimeBackendCardRuntimeChip(
                label:
                    'requested ${_runtimeBackendCardProfile.requestedBackend.name.toUpperCase()}',
              ),
              _RuntimeBackendCardRuntimeChip(
                label:
                    'actual ${_runtimeBackendCardProfile.actualBackend.name.toUpperCase()}',
              ),
            ],
          ),
          if (_runtimeBackendCardProfile.adapter
              case final adapter?) ...<Widget>[
            const SizedBox(height: 12),
            _RuntimeBackendCardInfoLine(
              icon: Icons.developer_board_outlined,
              title: 'Adapter',
              value: adapter,
            ),
          ],
          if (_runtimeBackendCardProfile.failureReason
              case final reason?) ...<Widget>[
            const SizedBox(height: 10),
            _RuntimeBackendCardInfoLine(
              icon: Icons.info_outline_rounded,
              title: fallback ? 'Fallback reason' : 'Backend error',
              value: reason,
            ),
          ],
          const SizedBox(height: 12),
          Text(
            activeGpu
                ? 'GPU is confirmed by successful backend initialization telemetry.'
                : fallback
                ? 'GPU was requested but inference is currently using the CPU fallback.'
                : 'GPU is not marked active until backend initialization explicitly succeeds.',
            style: TextStyle(color: scheme.onSurfaceVariant, height: 1.3),
          ),
        ],
      ),
    );
  }
}

