final class NazaThemeController extends ChangeNotifier {
  NazaThemeController({NazaThemePreset initial = NazaThemePreset.naza})
    : _nazaThemesPreset = initial;

  NazaThemePreset _nazaThemesPreset;

  NazaThemePreset get preset => _nazaThemesPreset;

  NazaThemeSpec get spec => NazaThemeCatalog.spec(_nazaThemesPreset);

  ThemeData get theme => spec.build();

  void select(NazaThemePreset preset) {
    if (_nazaThemesPreset == preset) return;
    _nazaThemesPreset = preset;
    notifyListeners();
  }
}

final class NazaThemePicker extends StatelessWidget {
  final NazaThemePreset selected;
  final ValueChanged<NazaThemePreset> onSelected;

  const NazaThemePicker({
    super.key,
    required this.selected,
    required this.onSelected,
  });

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final width = constraints.maxWidth;
        final columns = width >= 1000
            ? 4
            : width >= 700
            ? 3
            : width >= 440
            ? 2
            : 1;
        final gap = 10.0;
        final tileWidth = (width - gap * (columns - 1)) / columns;
        return Wrap(
          spacing: gap,
          runSpacing: gap,
          children: <Widget>[
            for (final preset in NazaThemePreset.values)
              SizedBox(
                width: tileWidth,
                child: _NazaThemesThemeTile(
                  preset: preset,
                  selected: preset == selected,
                  onTap: () => onSelected(preset),
                ),
              ),
          ],
        );
      },
    );
  }
}

final class _NazaThemesThemeTile extends StatelessWidget {
  final NazaThemePreset preset;
  final bool selected;
  final VoidCallback onTap;

  const _NazaThemesThemeTile({
    required this.preset,
    required this.selected,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final spec = NazaThemeCatalog.spec(preset);
    return Material(
      color: spec.surface,
      borderRadius: BorderRadius.circular(18),
      clipBehavior: Clip.antiAlias,
      child: InkWell(
        onTap: onTap,
        child: Container(
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(18),
            border: Border.all(
              color: selected ? spec.primary : spec.muted.withAlpha(70),
              width: selected ? 2 : 1,
            ),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              Row(
                children: <Widget>[
                  for (final color in <Color>[
                    spec.primary,
                    spec.secondary,
                    spec.tertiary,
                  ])
                    Container(
                      width: 22,
                      height: 22,
                      margin: const EdgeInsets.only(right: 5),
                      decoration: BoxDecoration(
                        color: color,
                        shape: BoxShape.circle,
                      ),
                    ),
                  const Spacer(),
                  if (selected)
                    Icon(Icons.check_circle_rounded, color: spec.primary),
                ],
              ),
              const SizedBox(height: 12),
              Text(
                preset.label,
                style: TextStyle(
                  color: spec.text,
                  fontWeight: FontWeight.w900,
                  fontSize: 16,
                ),
              ),
              const SizedBox(height: 3),
              Text(
                preset.description,
                style: TextStyle(color: spec.muted, height: 1.3),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

